def _dashboard_etag(*discriminators):
    """Cheap version tag for dashboard payloads.

    Reads ``MAX(modified)`` from the three tables that any dashboard pulls
    from (PO Dispatch, Daily Execution, Work Done), plus the caller's
    discriminators (user, im, date range). Hashed to a short opaque token.

    Used for an If-None-Match-style short-circuit: if the FE passes the
    same token it had last time, the endpoint returns a tiny ``unchanged``
    payload instead of regenerating 5–15kB of JSON.
    """
    import hashlib
    try:
        rows = frappe.db.sql(
            """
            SELECT
              (SELECT UNIX_TIMESTAMP(MAX(modified)) FROM `tabPO Dispatch`)    AS pd,
              (SELECT UNIX_TIMESTAMP(MAX(modified)) FROM `tabDaily Execution`) AS de,
              (SELECT UNIX_TIMESTAMP(MAX(modified)) FROM `tabWork Done`)       AS wd,
              (SELECT UNIX_TIMESTAMP(MAX(modified)) FROM `tabRollout Plan`)    AS rp,
              (SELECT UNIX_TIMESTAMP(MAX(modified)) FROM `tabINET Team`)       AS it,
              (SELECT UNIX_TIMESTAMP(MAX(modified)) FROM `tabPO Intake Line`)  AS il
            """,
            as_dict=True,
        )
        row = rows[0] if rows else {}
    except Exception:
        row = {}
    parts = [
        str(row.get("pd") or 0),
        str(row.get("de") or 0),
        str(row.get("wd") or 0),
        str(row.get("rp") or 0),
        str(row.get("it") or 0),
        # PO Intake Line — without it a PO upload would not bust the cache and
        # any PO-value series (get_po_vs_invoice_trend) would serve stale.
        str(row.get("il") or 0),
    ]
    for d in discriminators:
        parts.append("" if d is None else str(d))
    h = hashlib.sha1("|".join(parts).encode("utf-8")).hexdigest()
    return h[:16]


def _iso_now():
    """Return current time as ISO-8601 with the site timezone offset.

    `frappe.utils.now()` returns a naive string in the site timezone with no
    offset, so a browser in a different timezone parses it as its own local
    time and the displayed "last updated" drifts by the offset. Emitting an
    offset-aware string makes the FE's `new Date(s)` parse to the correct
    instant regardless of browser timezone.
    """
    tz_name = frappe.utils.get_system_timezone() or "UTC"
    try:
        from zoneinfo import ZoneInfo
        tz = ZoneInfo(tz_name)
    except Exception:
        try:
            import pytz
            tz = pytz.timezone(tz_name)
        except Exception:
            import datetime as _dt
            return _dt.datetime.now(_dt.timezone.utc).isoformat(timespec="seconds")
    import datetime as _dt
    return _dt.datetime.now(tz).isoformat(timespec="seconds")


def _parse_rows(rows):
    """Accept a JSON string or a Python list/dict and always return a list."""
    if isinstance(rows, str):
        rows = frappe.parse_json(rows)
    if isinstance(rows, dict):
        rows = [rows]
    return rows or []


def _portal_row_limit(limit, default=500):
    """
    Normalize portal list size.

    - ``0`` = unlimited (omit ``LIMIT`` in raw SQL; use ``limit_page_length=0`` / ``page_length=0``
      in Frappe list APIs so no row cap is applied).
    - Positive values are clamped to 1..10000.
    - Missing/invalid uses ``default`` (must be >= 1).
    """
    try:
        lim = cint(limit)
    except Exception:
        lim = -1
    if lim == 0:
        return 0
    if lim < 1:
        lim = cint(default) or 500
    return int(min(max(lim, 1), 10000))


def _sql_limit_suffix(limit_val):
    """Append to SQL; empty string when ``limit_val`` is 0 (unlimited)."""
    if not limit_val:
        return ""
    return f" LIMIT {int(limit_val)}"


def _portal_filters_dict(portal_filters):
    """Parse optional portal_filters JSON from the SPA into a dict."""
    if isinstance(portal_filters, str):
        portal_filters = frappe.parse_json(portal_filters) if portal_filters else {}
    return portal_filters if isinstance(portal_filters, dict) else {}


def _ensure_list(raw):
    """Coerce a filter value (string / JSON array / list) into a deduped list
    of non-empty stripped strings. Enables multi-select on any filter that
    previously only accepted a single value."""
    if raw is None:
        return []
    if isinstance(raw, (list, tuple, set)):
        items = list(raw)
    elif isinstance(raw, str):
        s = raw.strip()
        if not s:
            return []
        # JSON array?
        if s[0] == "[":
            try:
                parsed = json.loads(s)
                if isinstance(parsed, list):
                    items = parsed
                else:
                    items = [s]
            except Exception:
                items = [s]
        else:
            items = [s]
    else:
        items = [raw]
    seen = set()
    out = []
    for it in items:
        v = str(it or "").strip()
        if not v or v in seen:
            continue
        seen.add(v)
        out.append(v)
    return out


def _chunked(items, size=1000):
    """Split a list into fixed-size chunks. Use this for any `filters={"x":
    ["in", names]}` built from a potentially-large, unbounded name list (e.g.
    row-limit "All" on a heavy-line page) - frappe.get_all's own query
    validator runs the fully-rendered SQL through sqlparse, which hard-fails
    (SQLParseError: Maximum number of tokens exceeded) once a single IN
    clause gets into the thousands of values."""
    items = list(items)
    for i in range(0, len(items), size):
        yield items[i:i + size]


# Sentinel a toolbar filter sends to mean "rows where this is empty". Blank is
# a real answer to most of these questions — which lines have no IM, which work
# has no issue flag — and until this existed there was no way to ask for it.
# The value is deliberately one nothing in the data can collide with, and it is
# the same one a few pages had already hand-rolled before it lived here.
FILTER_BLANK = "__NONE__"


def _sql_in_or_eq(expr, raw):
    """Build ``expr = %s`` or ``expr IN (%s, %s, …)`` with params for a single
    or multi-value filter. Returns (clause_or_None, params).

    FILTER_BLANK among the values ORs in a blank test, so "IM = Rafeeq OR no IM
    at all" is one selection rather than two impossible ones. ``expr`` appears
    twice in that case — fine because every caller passes a developer-authored
    fragment with no bind placeholders of its own; keep it that way.
    """
    vals = _ensure_list(raw)
    if not vals:
        return None, []
    wants_blank = FILTER_BLANK in vals
    real = [v for v in vals if v != FILTER_BLANK]

    parts, params = [], []
    if len(real) == 1:
        parts.append(f"{expr} = %s")
        params.extend(real)
    elif real:
        parts.append(f"{expr} IN ({', '.join(['%s'] * len(real))})")
        params.extend(real)
    if wants_blank:
        parts.append(f"({expr} IS NULL OR {expr} = '')")

    if not parts:
        return None, []
    return (parts[0] if len(parts) == 1 else "(" + " OR ".join(parts) + ")"), params


# Manage Table column key -> physical PO Dispatch column. Shared by the
# substring filter, the Excel-style value filter and the column-options
# endpoint so all three agree on what a column means.
# Excel-filter bucket -> how many leading chars of the value to group on.
# "2026-08-28 14:23:11" -> "2026-08" (month) / "2026-08-28" (day), matching how
# date columns are actually displayed instead of listing every timestamp.
EXCEL_FILTER_BUCKETS = {"month": 7, "day": 10}


