def excel_orm_filter(field, raw_val):
    """One Excel-style dict filter as a Frappe ORM filter entry, or None.

    For sources that build get_all() filter lists instead of raw SQL. Entries
    in such a list are ANDed, so the three parts cannot be OR'd the way
    excel_filter_clause() does. Precedence: an explicit value selection wins,
    and a substring is applied only when nothing is ticked — combining both on
    one column is not expressible here.
    """
    if not field or not _column_filter_is_active(raw_val):
        return None
    vals = [str(x) for x in (raw_val.get("values") or []) if str(x or "").strip()]
    vals = vals[:EXCEL_FILTER_MAX_VALUES]
    if raw_val.get("blanks"):
        # Both, because a "blank" cell is NULL in some rows and '' in others.
        vals = vals + ["", None]
    if vals:
        return [field, "in", vals]
    cpat = _sql_like_pattern(raw_val.get("contains"))
    if cpat:
        return [field, "like", cpat]
    return None


def excel_options_from_orm(doctype, filters, field, search=None, limit=500):
    """Option list for an ORM-filtered source.

    Reuses the caller's own get_all() filters — the same guarantee the SQL
    path gets from sharing a WHERE clause: the dropdown cannot offer a value
    the row query would return nothing for.
    """
    limit = max(1, min(cint(limit) or 500, 2000))
    # Frappe accepts dict OR list filters but they cannot be concatenated —
    # list(dict) yields bare keys. Normalise to the list form.
    if isinstance(filters, dict):
        base = []
        for k, v in filters.items():
            if isinstance(v, (list, tuple)) and len(v) == 2:
                base.append([k, v[0], v[1]])
            else:
                base.append([k, "=", v])
    else:
        base = list(filters or [])
    conds = base + [[field, "not in", ["", None]]]
    pat = _sql_like_pattern(search)
    if pat:
        conds = conds + [[field, "like", pat]]
    rows = frappe.get_all(
        doctype, filters=conds, pluck=field, distinct=True,
        order_by=field, limit_page_length=limit,
    ) or []
    values = [{"value": str(v), "label": str(v)} for v in rows if v not in (None, "")]
    has_blanks = bool(frappe.get_all(
        doctype, filters=base + [[field, "in", ["", None]]], limit_page_length=1,
    ))
    if values and all(_is_numeric_str(v["value"]) for v in values):
        values.sort(key=lambda o: float(o["value"]))
        for v in values:
            v["label"] = _trim_number(v["value"])
    return {"values": values, "has_blanks": has_blanks, "total": len(values), "supported": True}


def _is_numeric_str(v):
    try:
        float(v)
        return True
    except (TypeError, ValueError):
        return False


def _trim_number(v):
    """"1075.000000000" -> "1075";  "118.080000000" -> "118.08"."""
    s = str(v)
    if "." not in s:
        return s
    s = s.rstrip("0").rstrip(".")
    return s or "0"


def excel_options_from_query(from_sql, where_sql, params, expr, bucket=None,
                             search=None, limit=500, label_kind=None):
    """Build one Excel-filter option list for ANY source.

    Source-agnostic half of the column-options feature: the caller supplies its
    own FROM (with whatever joins it needs), the WHERE it would use for the row
    list, and the column's null-safe expression. Everything else — bucketing,
    server-side search, the true total, the blanks probe, label formatting and
    numeric ordering — is identical everywhere and lives here.

    Passing the row list's OWN where/params is what guarantees a dropdown can
    never offer a value that then returns no rows.

    ``label_kind``: "month" | "day" | "money" | "qty" | "percent" | None.
    -> {"values": [{"value","label"}], "has_blanks": bool, "total": int}
    """
    bucket_len = EXCEL_FILTER_BUCKETS.get((bucket or "").strip().lower())
    if bucket_len:
        # LEFT(...) not DATE_FORMAT — see excel_filter_clause() for why.
        expr = f"LEFT({expr}, {bucket_len})"

    limit = max(1, min(cint(limit) or 500, 2000))
    search_sql = ""
    search_params = []
    pat = _sql_like_pattern(search)
    if pat:
        search_sql = f" AND {expr} LIKE %s"
        search_params = [pat]
    qp = tuple(params) + tuple(search_params)

    # The true match count tells the caller whether it holds the full set (and
    # can narrow client-side) or has to come back as the user types.
    total = cint(
        frappe.db.sql(
            f"SELECT COUNT(DISTINCT {expr}) FROM {from_sql} "
            f"WHERE {where_sql} AND {expr} != ''{search_sql}",
            qp,
        )[0][0]
    )
    rows = frappe.db.sql(
        f"SELECT DISTINCT {expr} AS val FROM {from_sql} "
        f"WHERE {where_sql} AND {expr} != ''{search_sql} "
        f"ORDER BY val LIMIT {limit}",
        qp,
        as_dict=True,
    )
    # Blanks ignore the search text — the caller decides whether to show the
    # "(Blanks)" row for what was typed.
    has_blanks = bool(
        frappe.db.sql(
            f"SELECT 1 FROM {from_sql} WHERE {where_sql} AND {expr} = '' LIMIT 1",
            tuple(params),
        )
    )

    def _label(val):
        # Labels must read like the column does, or the checkboxes won't look
        # like what's on screen: CAST on a decimal(21,9) yields
        # "992.000000000", which is not what an Amount column shows.
        if label_kind == "percent":
            return f"{val}%"
        if label_kind == "money":
            try:
                return f"{float(val):,.2f}"
            except Exception:
                return val
        if label_kind == "qty":
            try:
                return f"{float(val):,.10g}"
            except Exception:
                return val
        if label_kind == "month":
            try:
                y, m = val.split("-")
                return f"{calendar.month_abbr[int(m)]} {y}"
            except Exception:
                return val
        return val  # "day" is already YYYY-MM-DD, as displayed

    values = []
    for r in rows:
        val = r.get("val")
        if val in (None, ""):
            continue
        val = str(val)
        values.append({"value": val, "label": _label(val)})

    # SQL ORDER BY is lexical, which reads wrong for numbers ("100" before
    # "70", "1075" before "111.6"). Sort numerically whenever the column is
    # numeric — either because the caller said so, or because every value
    # parses as a number. The auto-detect matters for sources that don't
    # classify their columns: a CAST on a decimal(21,9) yields
    # "1075.000000000", which is neither readable nor correctly ordered.
    auto_numeric = (
        label_kind is None
        and values
        and all(_is_numeric_str(v["value"]) for v in values)
    )
    if label_kind in ("percent", "money", "qty") or auto_numeric:
        def _num(o):
            try:
                return float(o["value"])
            except Exception:
                return float("inf")
        values.sort(key=_num)
    if auto_numeric:
        # Trim the storage padding so the list reads like the column:
        # "1075.000000000" -> "1075", "118.080000000" -> "118.08".
        for v in values:
            v["label"] = _trim_number(v["value"])

    return {"values": values, "has_blanks": has_blanks, "total": total, "supported": True}


# ── Page summaries ──────────────────────────────────────────────────────────
# Twin of the column-options feature above, and it works the same way: a page's
# list function hands over its OWN from/where/params, so the headline figures
# can never disagree with the rows the table would show. The point is that the
# user sees "1,284 lines · 12.4M" the moment the page opens, without paging the
# whole dataset in — the numbers are aggregates, so they ignore the row limit
# entirely.
#
# A metric is one of:
#   {"key","label","agg":"count"}                    -> COUNT(*)
#   {"key","label","agg":"count_if","cond":SQL}      -> rows matching cond
#   {"key","label","agg":"count_distinct","expr":SQL}
#   {"key","label","agg":"sum","expr":SQL}
#   {"key","label","agg":"sum_if","expr":SQL,"cond":SQL}
# plus optional "format" ("int"|"money"|"qty"|"percent"), "tone"
# ("default"|"good"|"warn"|"bad"|"info") and "hint" (tooltip text).
#
# `expr` and `cond` are developer-authored constants declared next to the list
# function whose aliases they use — never anything a caller supplies. Keep it
# that way: they are interpolated into the SQL as-is.
SUMMARY_AGGREGATES = {
    "count": lambda m: "COUNT(*)",
    "count_if": lambda m: f"SUM(CASE WHEN {m['cond']} THEN 1 ELSE 0 END)",
    "count_distinct": lambda m: f"COUNT(DISTINCT {m['expr']})",
    "sum": lambda m: f"COALESCE(SUM({m['expr']}), 0)",
    "sum_if": lambda m: f"COALESCE(SUM(CASE WHEN {m['cond']} THEN {m['expr']} ELSE 0 END), 0)",
}


def summary_from_query(from_sql, where_sql, params, metrics):
    """Compute every headline figure for one page in a single round trip.

    All metrics fold into one SELECT of conditional aggregates rather than one
    query per figure: a page showing six numbers costs one query, not six, and
    every figure is guaranteed to describe the same snapshot.
    """
    metrics = [m for m in (metrics or []) if m.get("key") and m.get("agg") in SUMMARY_AGGREGATES]
    if not metrics:
        return {"metrics": [], "supported": False}

    select_sql = ", ".join(
        f"{SUMMARY_AGGREGATES[m['agg']](m)} AS `m_{i}`" for i, m in enumerate(metrics)
    )
    row = frappe.db.sql(
        f"SELECT {select_sql} FROM {from_sql} WHERE {where_sql}",
        tuple(params),
        as_dict=True,
    )
    vals = row[0] if row else {}

    out = []
    for i, m in enumerate(metrics):
        raw = vals.get(f"m_{i}")
        try:
            num = float(raw or 0)
        except Exception:
            num = 0.0
        out.append({
            "key": m["key"],
            "label": m.get("label") or m["key"],
            # Counts come back as ints so the UI never renders "12.0 lines".
            "value": int(num) if m.get("format", "int") == "int" else num,
            "format": m.get("format", "int"),
            "tone": m.get("tone", "default"),
            "hint": m.get("hint", ""),
            # Consecutive metrics sharing a group render as one captioned
            # cluster instead of N identical boxes — a breakdown reads as a
            # breakdown, and the strip stays narrow.
            "group": m.get("group", ""),
            # Breakdown members worth nothing are noise; totals still show 0.
            "hide_if_zero": bool(m.get("hide_if_zero")),
        })
    return {"metrics": out, "supported": True}


def merge_summaries(*results):
    """Add several summaries together, metric by metric.

    For pages whose row list is the union of more than one query (Work Done
    also emits synthesized subcon rows that have no Work Done record), the
    headline figures have to cover the same union or the chip disagrees with
    the row count sitting right under it.
    """
    order = []
    merged = {}
    for res in results:
        for m in (res or {}).get("metrics", []) or []:
            key = m.get("key")
            if not key:
                continue
            if key not in merged:
                merged[key] = dict(m)
                order.append(key)
            else:
                merged[key]["value"] = (merged[key].get("value") or 0) + (m.get("value") or 0)
                if merged[key].get("format", "int") == "int":
                    merged[key]["value"] = int(merged[key]["value"])
    return {"metrics": [merged[k] for k in order], "supported": bool(order)}


def _summary_via(fn, **call_kwargs):
    """Ask a list function for its own summary — mirrors _excel_options_via."""
    return fn(_summary=1, **call_kwargs)


def _excel_options_cache_key(*parts):
    """Cache key for one column-option lookup.

    The caller MUST include the session user: option lists are derived from
    whatever filters the page passes, and some pages scope by IM, so a shared
    key could hand one user another's value list.
    """
    raw = json.dumps(parts, sort_keys=True, default=str)
    return "inet:excel_opts:" + hashlib.md5(raw.encode()).hexdigest()


def excel_filter_clause(expr, raw_val):
    """WHERE clause + params for ONE Excel-style (dict) column filter.

    ``expr`` is the column's null-safe SQL expression (IFNULL/CASE wrapped), so
    "blank" is uniformly ``= ''``. Returns ``(None, [])`` when the filter is
    inactive or the column has no expression.

    Every per-column filter loop in this file must route dict values through
    here — both so the three filter kinds (exact values / blanks / contains)
    behave identically everywhere, and because the substring path's
    _sql_like_pattern() does ``(term or "").strip()`` and raises
    AttributeError on a dict.
    """
    if not expr or not _column_filter_is_active(raw_val):
        return None, []
    blen = EXCEL_FILTER_BUCKETS.get(raw_val.get("bucket"))
    if blen:
        # LEFT(...) not DATE_FORMAT: frappe only collapses the '%%' escape when
        # bind params are present, so a mask degrades to the literal '%Y-%m'
        # on a param-less query.
        expr = f"LEFT({expr}, {blen})"

    conds = []
    params = []
    vals = [str(x) for x in (raw_val.get("values") or []) if str(x or "").strip()]
    vals = vals[:EXCEL_FILTER_MAX_VALUES]
    if vals:
        conds.append(f"{expr} IN ({', '.join(['%s'] * len(vals))})")
        params.extend(vals)
    if raw_val.get("blanks"):
        conds.append(f"{expr} = ''")
    cpat = _sql_like_pattern(raw_val.get("contains"))
    if cpat:
        conds.append(f"{expr} LIKE %s")
        params.append(cpat)
    if not conds:
        return None, []
    return "(" + " OR ".join(conds) + ")", params


def _sql_like_pattern(term):
    """Build a LIKE pattern with % wildcards; escape % and _ in user input."""
    # Fail-safe: an Excel-style column filter is a dict, and there are many
    # per-column filter loops in this file. One that has not been taught to
    # route dicts through excel_filter_clause() must degrade to "no filter"
    # rather than raising AttributeError on .strip() and 500-ing the page.
    if isinstance(term, (dict, list, tuple, set)):
        return None
    t = (term or "").strip()
    if not t:
        return None
    t = t.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    return f"%{t}%"


def _sql_like_tokens(term, max_tokens=1000):
    """Split a free-text search on whitespace / commas / semicolons / pipes
    into individual LIKE patterns. Any row matching any token is returned
    (OR'd). Multi-word phrases are not preserved — users who need phrase
    matching should paste a distinctive substring instead."""
    if not term:
        return []
    raw = re.split(r"[\s,;|]+", str(term))
    seen = set()
    out = []
    for piece in raw:
        s = (piece or "").strip()
        if not s or s in seen:
            continue
        seen.add(s)
        esc = s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        out.append(f"%{esc}%")
        if len(out) >= max_tokens:
            break
    return out


def _sql_raw_tokens(term, max_tokens=1000):
    """Split a search term into raw (un-wildcarded) WORD-level tokens — used
    to build the AND-across-words LIKE clause, where every individual word
    must be found somewhere in the row (possibly in different columns)."""
    if not term:
        return []
    raw = re.split(r"[\s,;|]+", str(term))
    seen = set()
    out = []
    for piece in raw:
        s = (piece or "").strip()
        if not s or s in seen:
            continue
        seen.add(s)
        out.append(s)
        if len(out) >= max_tokens:
            break
    return out


def _sql_value_tokens(term, max_tokens=1000):
    """Split a search term into raw, un-wildcarded WHOLE-VALUE tokens, for
    exact IN matching against a batch of pasted identifiers. Splits only on
    hard separators (newline/CR/tab/comma/semicolon/pipe) — deliberately NOT
    on a plain space — so a single pasted value that itself contains a space
    (e.g. a DUID like "...M24_rack Fuse Upgrade") survives as one token
    instead of being shredded into unrelated words, the same way
    `_sql_raw_tokens` above would."""
    if not term:
        return []
    raw = re.split(r"[\n\r\t,;|]+", str(term))
    seen = set()
    out = []
    for piece in raw:
        s = (piece or "").strip()
        if not s or s in seen:
            continue
        seen.add(s)
        out.append(s)
        if len(out) >= max_tokens:
            break
    return out


def _sql_search_clause(concat_expr, term, exact_cols=None):
    """Build a search clause requiring every word in `term` to be found
    somewhere in `concat_expr` (AND across words) — a multi-word search only
    matches rows containing all the words, not rows that merely contain any
    one of them (so a single value with its own internal space, e.g. a DUID
    like "...M24_rack Fuse Upgrade", is treated as one thing to find, not a
    string of unrelated keywords).

    That AND rule alone breaks pasting several DISTINCT exact values at once
    (e.g. 3 different DUIDs copied from Excel into a search box) — no single
    row can ever contain all 3, so the AND clause would match nothing. When
    `exact_cols` (a list of raw SQL column expressions) is given, this adds
    "OR this row's own code exactly equals one of the pasted values" as an
    alternative — so either a described single target OR a batch of exact
    pasted values works from the same box, in one query, no retry needed.

    The exact-match side uses WHOLE-VALUE tokens (`_sql_value_tokens`, split
    only on hard separators), not the word-level `tokens` used for the AND
    clause — otherwise a pasted value that itself has an internal space
    (e.g. a DUID) would get shredded into unrelated words there too, and a
    batch paste containing exactly one such value would silently drop it
    (reproduced: pasting "SITE-1" + "DUID with a space" only ever matched
    "SITE-1").

    Returns (clause_sql_or_None, params_list). Empty term → (None, [])."""
    tokens = _sql_raw_tokens(term)
    if not tokens:
        return None, []
    patterns = ["%" + t.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%" for t in tokens]
    ands = " AND ".join([f"{concat_expr} LIKE %s"] * len(patterns))
    clause = f"({ands})"
    params = list(patterns)
    value_tokens = _sql_value_tokens(term)
    # A batch pasted with plain SPACES (no newline/comma/tab — e.g. copied out
    # of a single Excel cell, or typed) collapses to one whole-value token, so
    # the exact-match branch below never armed. The AND-across-words clause was
    # then the only thing left, and it can never match a batch: no single row
    # contains every pasted identifier. Reproduced — two POIDs separated by a
    # newline returned 2 rows, the same two separated by a space returned 0.
    # Fall back to word tokens for the exact side only when the term carries no
    # hard separator at all, so a pasted value with an internal space (a DUID
    # like "...M24_rack Fuse Upgrade") still arrives with one and keeps its
    # whole-value handling untouched.
    if len(value_tokens) <= 1 and len(tokens) > 1:
        value_tokens = tokens
    if exact_cols and len(value_tokens) > 1:
        ph = ", ".join(["%s"] * len(value_tokens))
        exact_ors = " OR ".join(f"{col} IN ({ph})" for col in exact_cols)
        clause = f"({clause} OR ({exact_ors}))"
        for _ in exact_cols:
            params.extend(value_tokens)
    return clause, params


def _apply_dummy_description(rows):
    """For open dummy PO rows (is_dummy_po=1) replace item_description with
    manager_remark so every list view shows the IM's note instead of the
    placeholder text set at creation time."""
    for r in rows:
        if r.get("is_dummy_po") and not (r.get("item_description") or "").strip():
            r["item_description"] = r.get("manager_remark") or ""
    return rows


def _po_dispatch_col_expr(col, alias=None, prefix="pd"):
    """Return ``"<prefix>.<col> AS <alias>"`` if the column exists on PO Dispatch,
    otherwise ``"NULL AS <alias>"``. Lets queries that touch optional columns
    survive on environments where a migration hasn't run yet.
    """
    alias = alias or col
    if frappe.db.has_column("PO Dispatch", col):
        return f"{prefix}.{col} AS {alias}"
    return f"NULL AS {alias}"


def _remark_select(prefix="pd"):
    """SELECT-clause fragment for the role-scoped remark trio. Falls back to
    NULLs on environments that haven't migrated the new columns yet."""
    return ", ".join([
        _po_dispatch_col_expr("general_remark", prefix=prefix),
        _po_dispatch_col_expr("manager_remark", prefix=prefix),
        _po_dispatch_col_expr("team_lead_remark", prefix=prefix),
    ])


_PIC_STATUS_TO_BILLING = {
    # PIC scale (11 values) → Work Done billing bucket (Pending / Invoiced / Closed).
    "Commercial Invoice Closed":    "Closed",
    "PO Line Canceled":             "Closed",
    "Commercial Invoice Submitted": "Invoiced",
    # Everything else (Ready for Invoice, Under I-BUY, Under ISDP, Work Not Done,
    # Under Process to Apply, both Rejected variants, PO Need to Cancel) maps to
    # "Pending" — billing only counts when the invoice is actually submitted.
}


def _billing_status_from_pic(pic_status, fallback=None):
    """Roll the 11-value PIC scale up to the 3-bucket billing_status used by
    PM / IM Work Done views. Falls back to the existing Work Done value when
    no PIC status has been set yet."""
    if pic_status:
        return _PIC_STATUS_TO_BILLING.get(pic_status, "Pending")
    return fallback or "Pending"


def _normalize_int_token(value):
    """Render a numeric value as a clean integer string when it has no fractional part.

    Excel binary parsers hand back ``1.0`` for what should be an integer; if we
    drop that into a POID we end up with ugly suffixes like ``-1-1.0``.
    """
    if value is None or value == "":
        return ""
    if isinstance(value, bool):
        return str(int(value))
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(int(value)) if value.is_integer() else str(value)
    s = str(value).strip()
    # Strip a trailing ".0" left over from float-to-string conversions upstream.
    if s.endswith(".0") and s[:-2].lstrip("-").isdigit():
        return s[:-2]
    return s


def _make_poid(po_no, po_line_no, shipment_number):
    """Build POID: PO No - PO Line No - Shipment No."""
    parts = [str(po_no or "").strip(), str(cint(po_line_no) if po_line_no else 0)]
    ship = _normalize_int_token(shipment_number)
    if ship and ship != "0":
        parts.append(ship)
    return "-".join(parts)


def _resolve_line_poid(po_no, po_line_no, shipment_number, fallback=None):
    """Prefer explicit POID from intake line; otherwise rebuild from line metadata."""
    poid = (fallback or "").strip()
    return poid or _make_poid(po_no, po_line_no, shipment_number)


def _resolve_customer_link_name(customer_input):
    """Resolve Excel/UI label to Customer.name for Link fields."""
    c = (customer_input or "").strip()
    if not c:
        return None
    if frappe.db.exists("Customer", c):
        return c
    return frappe.db.get_value("Customer", {"customer_name": c}, "name")


def ensure_item_master(item_code_input, item_name=None):
    """
    Create a minimal Item if missing (for PO import). Requires ERPNext Item / Item Group.
    """
    code = (item_code_input or "").strip()
    if not code:
        return False, "item_code is required"
    if frappe.db.exists("Item", code):
        return True, None
    if not frappe.db.exists("DocType", "Item"):
        return False, "Item master is not available (install ERPNext Stock or create Item manually)"
    ig = frappe.db.get_value("Item Group", {"is_group": 0}, "name")
    if not ig:
        ig = frappe.db.sql_list("SELECT name FROM `tabItem Group` LIMIT 1")
        ig = ig[0] if ig else None
    if not ig:
        return False, "No Item Group found — create one under Stock"
    uom = frappe.db.get_single_value("Stock Settings", "stock_uom") or "Nos"
    try:
        it = frappe.new_doc("Item")
        it.item_code = code
        it.item_name = (item_name or code)[:140]
        it.item_group = ig
        it.stock_uom = uom
        if hasattr(it, "is_stock_item"):
            it.is_stock_item = 0
        it.insert(ignore_permissions=True)
        _try_set_arabic_item_name(code, it.item_name)
    except Exception as e:
        if frappe.db.exists("Item", code):
            return True, None
        return False, str(e)
    return True, None


def _try_set_arabic_item_name(item_code, item_name_en):
    """Auto-translate item_name to Arabic after creation. Silent no-op when:
    - custom_item_name_arabic field doesn't exist (app not installed)
    - Groq API key not configured
    - Translation API call fails
    """
    try:
        if not frappe.db.has_column("Item", "custom_item_name_arabic"):
            return
        try:
            from arabic_translation.api.translation import translate_to_arabic, get_groq_api_key
        except ImportError:
            return
        if not get_groq_api_key():
            return
        arabic = translate_to_arabic(item_name_en)
        if arabic and arabic.strip():
            frappe.db.set_value("Item", item_code, "custom_item_name_arabic", arabic.strip())
    except Exception:
        pass


def ensure_project_control_center(project_code, customer_input, project_name=None, center_area=None):
    """Create Project Control Center when missing (PO import)."""
    pc = (project_code or "").strip()
    if not pc:
        return False, "project_code is required"
    if frappe.db.exists("Project Control Center", pc):
        return True, None
    cust = _resolve_customer_link_name(customer_input)
    if not cust:
        return False, "Customer is required to auto-create project"
    try:
        doc = frappe.new_doc("Project Control Center")
        doc.project_code = pc
        doc.project_name = ((project_name or pc) or "").strip()[:140] or pc
        doc.customer = cust
        if center_area:
            doc.center_area = str(center_area).strip()
        if hasattr(doc, "region_type"):
            doc.region_type = region_type_from_center_area(doc.center_area)
        doc.active_flag = "Yes"
        doc.project_status = "Active"
        doc.insert(ignore_permissions=True)
    except Exception as e:
        return False, str(e)
    return True, None


def ensure_customer_item_master(customer_input, item_code_input):
    """
    Ensure an active Customer Item Master exists for this customer and Item.
    Creates one with zero rates if missing; reactivates if an inactive row exists.

    Returns
    -------
    (ok: bool, err: str|None)
    """
    customer = _resolve_customer_link_name(customer_input)
    item_code = (item_code_input or "").strip()
    if not customer:
        return False, "Customer not found in Customer master"
    if not item_code:
        return False, "item_code is required"
    ok_item, err_item = ensure_item_master(item_code)
    if not ok_item:
        return False, err_item

    existing = frappe.db.get_value(
        "Customer Item Master",
        {"customer": customer, "item_code": item_code},
        ["name", "active_flag"],
        as_dict=True,
    )
    if existing:
        if not cint(existing.active_flag):
            frappe.db.set_value(
                "Customer Item Master",
                existing.name,
                "active_flag",
                1,
                update_modified=True,
            )
        return True, None

    try:
        doc = frappe.new_doc("Customer Item Master")
        doc.customer = customer
        doc.item_code = item_code
        doc.active_flag = 1
        doc.standard_rate_sar = 0
        doc.hard_rate_sar = 0
        doc.insert(ignore_permissions=True)
    except Exception as e:
        if frappe.db.exists(
            "Customer Item Master", {"customer": customer, "item_code": item_code}
        ):
            return True, None
        return False, str(e)

    return True, None


def ensure_duid_master(duid_input, site_name=None, center_area=None):
    """Ensure DUID Master exists for site_code; DUID and site_code are same."""
    duid = str(duid_input or "").strip()
    if not duid:
        return True, None
    if not frappe.db.exists("DocType", "DUID Master"):
        return True, None

    existing = frappe.db.get_value(
        "DUID Master",
        duid,
        ["name", "site_name", "center_area"],
        as_dict=True,
    )
    if existing:
        updates = {}
        if site_name and not existing.get("site_name"):
            updates["site_name"] = str(site_name).strip()
        if center_area and not existing.get("center_area"):
            updates["center_area"] = str(center_area).strip()
        if updates:
            frappe.db.set_value("DUID Master", duid, updates, update_modified=False)
        return True, None

    try:
        doc = frappe.new_doc("DUID Master")
        doc.duid = duid
        doc.site_name = (site_name or "")[:140]
        doc.center_area = (center_area or "")[:140]
        doc.insert(ignore_permissions=True)
    except Exception as e:
        if frappe.db.exists("DUID Master", duid):
            return True, None
        return False, str(e)
    return True, None


def _sanitize_table_pref_config(config):
    """Sanitize table personalization payload."""
    if isinstance(config, str):
        config = frappe.parse_json(config)
    config = config or {}
    if not isinstance(config, dict):
        return {}

    out = {}

    order = config.get("order")
    if isinstance(order, list):
        out["order"] = [str(x) for x in order if str(x).strip()][:200]

    hidden = config.get("hidden")
    if isinstance(hidden, list):
        out["hidden"] = [str(x) for x in hidden if str(x).strip()][:200]

    widths = config.get("widths")
    if isinstance(widths, dict):
        clean_widths = {}
        for k, v in widths.items():
            key = str(k).strip()
            if not key:
                continue
            px = cint(v)
            # Guardrails
            px = max(60, min(px, 1200))
            clean_widths[key] = px
        out["widths"] = clean_widths

    filters = config.get("filters")
    if isinstance(filters, dict):
        clean_filters = {}
        for k, v in filters.items():
            key = str(k).strip()
            if not key:
                continue
            # Excel-style column filter: keep the dict shape intact. str(v) here
            # would persist a Python dict repr and silently corrupt the saved
            # selection on the next page load.
            if isinstance(v, dict):
                raw_vals = v.get("values")
                vals = (
                    # Cap mirrors EXCEL_MAX_SELECTED in DataTablePro.jsx and
                    # keeps the generated IN (...) far below MySQL's 10k
                    # token ceiling.
                    [str(x)[:200] for x in raw_vals if str(x or "").strip()][:1000]
                    if isinstance(raw_vals, list)
                    else []
                )
                blanks = 1 if v.get("blanks") else 0
                bucket = v.get("bucket") if v.get("bucket") in EXCEL_FILTER_BUCKETS else None
                contains = str(v.get("contains") or "").strip()[:200]
                if vals or blanks or contains:
                    clean_filters[key] = {
                        "values": vals, "blanks": blanks, "bucket": bucket, "contains": contains,
                    }
                continue
            clean_filters[key] = str(v or "")[:200]
        out["filters"] = clean_filters

    out["show_filters"] = 1 if cint(config.get("show_filters")) else 0

    frozen = config.get("frozen")
    if isinstance(frozen, list):
        out["frozen"] = [str(x) for x in frozen if str(x).strip()][:200]

    sort = config.get("sort")
    if isinstance(sort, dict):
        key = str(sort.get("key") or "").strip()
        direction = str(sort.get("dir") or "desc").strip()
        if key and direction in ("asc", "desc"):
            out["sort"] = {"key": key, "dir": direction}

    dyn = config.get("dynamic_fields")
    if isinstance(dyn, list):
        clean_dyn = []
        for item in dyn[:40]:
            if not isinstance(item, dict):
                continue
            key = str(item.get("key") or "").strip()[:120]
            if not key or not key.startswith("dyn_"):
                continue
            dt = str(item.get("doctype") or "").strip()[:120]
            fn = str(item.get("fieldname") or "").strip()[:120]
            sk = str(item.get("source_key") or "").strip()[:120]
            if not dt or not fn or not sk:
                continue
            clean_dyn.append(
                {
                    "key": key,
                    "doctype": dt,
                    "fieldname": fn,
                    "source_key": sk,
                    "label": str(item.get("label") or fn)[:200],
                }
            )
        out["dynamic_fields"] = clean_dyn

    return out


# Frappe stores list-view prefs in `__UserSettings` (user, doctype, data) — not on `tabUser`.
# Use a dedicated synthetic doctype key so portal table layouts persist reliably.
_PORTAL_TABLE_PREFS_DOCTYPE = "INET PMS Table Prefs"


def _get_all_table_prefs_for_user(user):
    if not user or user == "Guest":
        return {}
    try:
        rows = frappe.db.sql(
            "select `data` from `__UserSettings` where `user`=%s and `doctype`=%s",
            (user, _PORTAL_TABLE_PREFS_DOCTYPE),
        )
    except Exception:
        rows = None
    if rows and rows[0] and rows[0][0]:
        try:
            blob = rows[0][0]
            parsed = frappe.parse_json(blob) if isinstance(blob, str) else blob
        except Exception:
            parsed = {}
        if isinstance(parsed, dict):
            inner = parsed.get("inet_table_preferences")
            if isinstance(inner, dict):
                return inner
    # Legacy: some sites may still have JSON on User (if column exists)
    if frappe.db.has_column("User", "user_settings"):
        try:
            raw = frappe.db.get_value("User", user, "user_settings")
        except Exception:
            raw = None
        if raw:
            try:
                parsed = frappe.parse_json(raw) if isinstance(raw, str) else raw
            except Exception:
                parsed = {}
            if isinstance(parsed, dict):
                inner = parsed.get("inet_table_preferences") or {}
                if isinstance(inner, dict):
                    return inner
    return {}


def _save_all_table_prefs_for_user(user, prefs):
    """Persist portal table prefs for the session user (same mechanism as Desk __UserSettings)."""
    if not user or user == "Guest":
        frappe.throw("Not permitted", frappe.PermissionError)
    if user != frappe.session.user:
        frappe.throw("Not permitted", frappe.PermissionError)
    payload = json.dumps({"inet_table_preferences": prefs})
    frappe.db.multisql(
        {
            "mariadb": (
                "INSERT INTO `__UserSettings`(`user`, `doctype`, `data`) "
                "VALUES (%s, %s, %s) ON DUPLICATE KEY UPDATE `data`=%s"
            ),
            "postgres": (
                'INSERT INTO "__UserSettings" ("user", "doctype", "data") '
                'VALUES (%s, %s, %s) ON CONFLICT ("user", "doctype") DO UPDATE SET "data"=%s'
            ),
        },
        (user, _PORTAL_TABLE_PREFS_DOCTYPE, payload, payload),
    )
    try:
        frappe.cache.hset("_user_settings", f"{_PORTAL_TABLE_PREFS_DOCTYPE}::{user}", None)
    except Exception:
        pass


@frappe.whitelist()
def get_table_preferences(table_id):
    """Read per-user table preferences for a page/table id."""
    table_id = str(table_id or "").strip()
    if not table_id:
        frappe.throw("table_id is required")
    user = frappe.session.user
    prefs = _get_all_table_prefs_for_user(user)
    config = prefs.get(table_id) or {}
    return _sanitize_table_pref_config(config)


@frappe.whitelist()
def get_distinct_field_values(doctype, fields):
    """Return {fieldname: [distinct values]} for the given fields on a doctype.

    Powers filter dropdowns that must show ALL possible values regardless of
    the current row-limit. SQL-injection safe: doctype must exist, fields
    must appear in the doctype meta.
    """
    if not doctype or not isinstance(doctype, str):
        return {}
    if not frappe.db.exists("DocType", doctype):
        return {}

    if isinstance(fields, str):
        try:
            fields_list = frappe.parse_json(fields)
        except Exception:
            fields_list = []
    else:
        fields_list = fields
    if not isinstance(fields_list, list):
        return {}

    meta = frappe.get_meta(doctype)
    allowed = {f.fieldname for f in meta.fields}
    allowed.add("name")  # always safe

    out = {}
    table_name = "tab" + doctype
    for f in fields_list:
        if not isinstance(f, str) or f not in allowed:
            continue
        try:
            # This must return every distinct value, not a sample — filter
            # dropdowns silently drop whatever falls past the cap (e.g. DUID
            # codes sorting after position 5000 used to just never appear).
            # 25000 is comfortably above any single field's real cardinality
            # in this app while still bounding a truly pathological doctype.
            rows = frappe.db.sql(
                f"SELECT DISTINCT `{f}` FROM `{table_name}` "
                f"WHERE `{f}` IS NOT NULL AND `{f}` != '' "
                f"ORDER BY `{f}` LIMIT 25000",
                as_list=True,
            )
            out[f] = [r[0] for r in rows if r[0]]
        except Exception:
            out[f] = []
    return out


@frappe.whitelist()
def get_item_codes_for_project(project_code):
    """Return sorted distinct item_codes in PO Intake Line for a given project."""
    if not project_code:
        return []
    rows = frappe.db.sql(
        "SELECT DISTINCT item_code FROM `tabPO Intake Line` "
        "WHERE project_code = %s AND item_code IS NOT NULL AND item_code != '' "
        "ORDER BY item_code LIMIT 1000",
        project_code,
        as_list=True,
    )
    return [r[0] for r in rows if r[0]]


@frappe.whitelist()
def get_all_table_preferences():
    """Return every saved table preference for the current user in one call.

    Prefetched at app boot so per-table `load(tableId)` lookups are synchronous —
    removes a blocking round-trip that used to precede every table render.
    """
    user = frappe.session.user
    prefs = _get_all_table_prefs_for_user(user) or {}
    out = {}
    for k, v in prefs.items():
        if not isinstance(k, str):
            continue
        out[k] = _sanitize_table_pref_config(v or {})
    return out


@frappe.whitelist()
def save_table_preferences(table_id, config=None):
    """Save per-user table preferences for a page/table id."""
    table_id = str(table_id or "").strip()
    if not table_id:
        frappe.throw("table_id is required")
    if len(table_id) > 400:
        frappe.throw("table_id is too long")

    if isinstance(config, str):
        try:
            config = frappe.parse_json(config) if (config or "").strip() else {}
        except Exception:
            config = {}

    user = frappe.session.user
    prefs = _get_all_table_prefs_for_user(user)
    prefs[table_id] = _sanitize_table_pref_config(config)
    _save_all_table_prefs_for_user(user, prefs)
    return {"ok": True}


@frappe.whitelist()
def get_table_field_values(doctype, fieldname, names):
    """
    Fetch one field for a list of document names.
    Used by table personalization to add doctype-backed columns dynamically.
    """
    doctype = str(doctype or "").strip()
    fieldname = str(fieldname or "").strip()
    if isinstance(names, str):
        names = frappe.parse_json(names)
    names = names or []

    if not doctype or not fieldname:
        frappe.throw("doctype and fieldname are required")
    if not isinstance(names, list):
        frappe.throw("names must be a list")

    meta = frappe.get_meta(doctype)
    if not meta.has_field(fieldname) and fieldname != "name":
        frappe.throw(f"Field '{fieldname}' not found in {doctype}")

    rows = frappe.get_all(
        doctype,
        filters={"name": ["in", [str(n) for n in names if str(n).strip()]]},
        fields=["name", fieldname],
        limit_page_length=max(1, len(names)),
        ignore_permissions=True,
    )
    out = {r.get("name"): r.get(fieldname) for r in rows}
    return {"values": out}


@frappe.whitelist()
def get_doctype_fields(doctype):
    """Return selectable fields for a doctype as {label, fieldname}."""
    doctype = str(doctype or "").strip()
    if not doctype:
        frappe.throw("doctype is required")
    meta = frappe.get_meta(doctype)
    fields = [{"label": "Name", "fieldname": "name"}]
    for df in meta.fields:
        if not getattr(df, "fieldname", None):
            continue
        if df.fieldtype in ("Section Break", "Column Break", "Tab Break", "Button", "Fold", "Heading", "HTML"):
            continue
        fields.append({
            "label": (df.label or df.fieldname),
            "fieldname": df.fieldname,
        })
    return {"fields": fields}


def _insert_po_dispatch_with_poid(dispatch_doc, poid):
    """
    Insert PO Dispatch. `name` stays as the SYS-YYYY-##### series ID.
    `poid` field holds the business POID; `system_id` mirrors `name` for legacy compatibility.
    """
    poid = (poid or "").strip()
    if poid:
        dispatch_doc.poid = poid
    dispatch_doc.insert(ignore_permissions=True)
    frappe.db.set_value("PO Dispatch", dispatch_doc.name, "system_id", dispatch_doc.name, update_modified=False)
    return dispatch_doc.name


def _upsert_po_dispatch_for_line(
    po_intake_name,
    po_no,
    line_dict,
    *,
    customer=None,
    im=None,
    target_month=None,
    planning_mode="Plan",
    dispatch_status="Pending",
    dispatch_mode="Manual",
):
    """Create or update PO Dispatch for a line while preserving immutable system_id."""
    po_line_no = cint(line_dict.get("po_line_no") or 0)
    project_code = line_dict.get("project_code")
    center_area = line_dict.get("center_area") or line_dict.get("area")
    site_code = (line_dict.get("site_code") or "").strip()
    site_name = line_dict.get("site_name")
    ok_duid, err_duid = ensure_duid_master(site_code, site_name, center_area)
    if not ok_duid:
        frappe.throw(err_duid or f"Could not create DUID Master for {site_code}")
    poid = _resolve_line_poid(
        po_no=po_no,
        po_line_no=po_line_no,
        shipment_number=line_dict.get("shipment_number"),
        fallback=line_dict.get("poid"),
    )
    payload = {
        "poid": poid,
        "po_intake": po_intake_name,
        "po_no": po_no,
        "po_line_no": po_line_no,
        "item_code": line_dict.get("item_code"),
        "item_description": line_dict.get("item_description"),
        "qty": flt(line_dict.get("qty", 0)),
        "rate": flt(line_dict.get("rate", 0)),
        "line_amount": flt(line_dict.get("line_amount", 0)),
        # Copy payment_terms from the intake line so the PO Dispatch validate
        # hook can parse MS1/MS2 percentages without joining back to the parent.
        "payment_terms": line_dict.get("payment_terms") or "",
        # PIC list view surfaces tax_rate alongside the line amount.
        "tax_rate": line_dict.get("tax_rate") or "",
        "customer": customer,
        "im": im,
        "target_month": target_month,
        "planning_mode": planning_mode,
        "dispatch_status": dispatch_status,
        "dispatch_mode": dispatch_mode,
        "center_area": center_area,
        "region_type": region_type_from_center_area(center_area),
        "site_code": site_code,
        "site_name": site_name,
    }
    proj_huawei_im = None
    if project_code and frappe.db.exists("Project Control Center", project_code):
        payload["project_code"] = project_code
        proj_owners = frappe.db.get_value(
            "Project Control Center", project_code, ["isdp_owner", "ibuy_owner", "huawei_im"], as_dict=True
        ) or {}
        if proj_owners.get("isdp_owner"):
            payload["isdp_owner"] = proj_owners["isdp_owner"]
        if proj_owners.get("ibuy_owner"):
            payload["ibuy_owner"] = proj_owners["ibuy_owner"]
        # Only ever applied on the brand-new PO Dispatch below, never on the
        # existing_name update branch — a PM/IM may have already overridden
        # huawei_im (e.g. from the rollout planning popup) and re-syncing
        # this line must not stomp that back to the project's default.
        proj_huawei_im = proj_owners.get("huawei_im")

    existing_name = frappe.db.get_value(
        "PO Dispatch", {"po_intake": po_intake_name, "po_line_no": po_line_no}, "name"
    )
    if existing_name:
        # Strip empty/None values so DATE columns don't choke on ''.
        clean = {k: v for k, v in payload.items() if v is not None and v != ""}
        frappe.db.set_value("PO Dispatch", existing_name, clean, update_modified=False)
        system_id = frappe.db.get_value("PO Dispatch", existing_name, "system_id")
        if not system_id:
            frappe.db.set_value("PO Dispatch", existing_name, "system_id", existing_name, update_modified=False)
        # Ensure poid field is populated for docs created before this field existed
        if not frappe.db.get_value("PO Dispatch", existing_name, "poid"):
            frappe.db.set_value("PO Dispatch", existing_name, "poid", poid, update_modified=False)
        return existing_name

    doc = frappe.new_doc("PO Dispatch")
    for key, value in payload.items():
        if value is not None and value != "":
            setattr(doc, key, value)
    if proj_huawei_im:
        doc.huawei_im = proj_huawei_im
    return _insert_po_dispatch_with_poid(doc, poid)


def _try_auto_dispatch(doc_name, po_no, child_rows):
    """
    After PO Intake save, auto-dispatch lines whose project has an IM assigned.

    Field team is chosen later by the IM at rollout planning (not on PO Dispatch).

    child_rows: list of (child_doc_name, line_dict) tuples
    Returns count of auto-dispatched lines.
    """
    # Batch-fetch IM + customer for all distinct project codes up front — replaces
    # 2 queries per child row with 1 IN query, critical when a PO has 1000+ lines.
    project_codes = list({
        (line_dict.get("project_code") or "").strip()
        for _, line_dict in child_rows
        if line_dict.get("project_code")
    })
    proj_map = {}
    if project_codes:
        for p in frappe.get_all(
            "Project Control Center",
            filters={"name": ["in", project_codes]},
            fields=["name", "implementation_manager", "customer"],
            limit_page_length=len(project_codes) + 1,
        ):
            proj_map[p.name] = p

    count = 0
    for child_doc_name, line_dict in child_rows:
        project_code = line_dict.get("project_code")
        if not project_code:
            continue
        pdata = proj_map.get(project_code)
        if not pdata or not pdata.get("implementation_manager"):
            continue

        _upsert_po_dispatch_for_line(
            doc_name,
            po_no,
            line_dict,
            customer=pdata.get("customer"),
            im=pdata.get("implementation_manager"),
            target_month=None,
            planning_mode="Plan",
            dispatch_status="Dispatched",
            dispatch_mode="Auto",
        )

        frappe.db.set_value(
            "PO Intake Line",
            child_doc_name,
            {"po_line_status": "Dispatched", "dispatch_mode": "Auto"},
            update_modified=False,
        )
        count += 1

    return count


@frappe.whitelist()
def backfill_po_dispatch_id_to_poid(limit=500):
    """
    One-time maintenance:
    Rename PO Dispatch docs to the PO Intake Line POID when possible.
    Returns summary counters.
    """
    limit = cint(limit or 500)
    rows = frappe.get_all(
        "PO Dispatch",
        fields=["name", "po_intake", "po_line_no", "po_no"],
        order_by="modified desc",
        limit_page_length=limit,
    )

    updated = 0
    skipped = 0
    failed = []

    for d in rows:
        line = frappe.db.get_value(
            "PO Intake Line",
            {"parent": d.po_intake, "po_line_no": d.po_line_no},
            ["poid", "shipment_number"],
            as_dict=True,
        )
        poid = _resolve_line_poid(
            po_no=d.po_no,
            po_line_no=d.po_line_no,
            shipment_number=(line or {}).get("shipment_number"),
            fallback=(line or {}).get("poid"),
        )
        if not poid or d.poid == poid:
            skipped += 1
            continue
        try:
            frappe.db.set_value("PO Dispatch", d.name, "poid", poid, update_modified=False)
            if not frappe.db.get_value("PO Dispatch", d.name, "system_id"):
                frappe.db.set_value("PO Dispatch", d.name, "system_id", d.name, update_modified=False)
            updated += 1
        except Exception:
            failed.append({"name": d.name, "poid": poid})

    frappe.db.commit()
    return {"checked": len(rows), "updated": updated, "skipped": skipped, "failed": failed}


