# Task 12 — Pipeline Operations
# ---------------------------------------------------------------------------


@frappe.whitelist()
def export_po_dump(from_date=None, to_date=None, unique_inet_uid=1, statuses=None, limit=20000, search=None, column_filters=None, _options=None, _summary=None):
    """
    Export PO Intake lines whose parent PO was created in the date range (upload date).
    Returns uploaded PO lines in source column order for audit/export.

    ``statuses`` is a JSON list / comma string of buckets to include — any of
    ``OPEN`` (New / Dispatched / Completed), ``CLOSED``, ``CANCELLED``. Defaults
    to OPEN only so dumps stay small after archive imports.
    """
    has_date_filter = bool(from_date and to_date)
    fd = getdate(from_date) if from_date else None
    td = getdate(to_date) if to_date else None
    if has_date_filter and td < fd:
        frappe.throw("to_date must be on or after from_date")

    if isinstance(statuses, str):
        try:
            parsed = frappe.parse_json(statuses)
            if isinstance(parsed, (list, tuple)):
                statuses = parsed
        except Exception:
            statuses = [s.strip() for s in statuses.split(",") if s.strip()]
    if not statuses:
        statuses = ["OPEN"]
    bucket_set = {str(s).strip().upper() for s in statuses}
    line_status_filter = []
    if "OPEN" in bucket_set:
        line_status_filter += ["New", "Dispatched", "Completed", ""]
    if "CLOSED" in bucket_set:
        line_status_filter.append("Closed")
    if "CANCELLED" in bucket_set or "CANCELED" in bucket_set:
        line_status_filter.append("Cancelled")

    rows_out = []

    # Restrict to the date range via a SQL JOIN + WHERE, never by pulling
    # every matching `PO Intake` name into Python and re-injecting it as a
    # `parent IN (...)` list — with tens of thousands of PO Intake records,
    # that list is long enough to blow past sqlparse's 10,000-token query
    # validation cap (SQLParseError: "Maximum number of tokens exceeded").
    date_where = ""
    date_params = []
    if has_date_filter:
        date_where = "AND DATE(pi.creation) BETWEEN %s AND %s"
        date_params = [fd, td]

    # Total counts per bucket for the active date range — independent of which
    # buckets the caller is fetching, so the FE can always show full counts.
    bucket_totals = {"open": 0, "closed": 0, "cancelled": 0}
    agg = frappe.db.sql(
        f"""
        SELECT
          SUM(CASE WHEN IFNULL(pil.po_line_status, 'New') IN ('New','Dispatched','Completed','') THEN 1 ELSE 0 END) AS open_cnt,
          SUM(CASE WHEN pil.po_line_status = 'Closed' THEN 1 ELSE 0 END) AS closed_cnt,
          SUM(CASE WHEN pil.po_line_status = 'Cancelled' THEN 1 ELSE 0 END) AS cancelled_cnt
        FROM `tabPO Intake Line` pil
        JOIN `tabPO Intake` pi ON pi.name = pil.parent
        WHERE 1=1 {date_where}
        """,
        date_params,
        as_dict=True,
    )
    if agg:
        bucket_totals["open"] = cint(agg[0].open_cnt or 0)
        bucket_totals["closed"] = cint(agg[0].closed_cnt or 0)
        bucket_totals["cancelled"] = cint(agg[0].cancelled_cnt or 0)

    if not sum(bucket_totals.values()):
        return {
            "from_date": str(fd),
            "to_date": str(td),
            "rows": rows_out,
            "totals": bucket_totals,
        }

    fields = [
        "name",
        "parent",
        "source_id",
        "poid",
        "po_line_no",
        "shipment_number",
        "site_name",
        "site_code",
        "project_code",
        "project_name",
        "item_code",
        "item_description",
        "uom",
        "qty",
        "due_qty",
        "billed_quantity",
        "quantity_cancel",
        "start_date",
        "end_date",
        "sub_contract_no",
        "currency",
        "rate",
        "line_amount",
        "tax_rate",
        "payment_terms",
        "center_area",
        "publish_date",
        "po_line_status",
    ]

    # Allow up to 100k rows for archive dumps. Honor any positive limit (down
    # to 1) from the FE row-limit selector — previously we floored at 100,
    # which made "20" and "100" return the same result.
    lim = min(max(int(limit or 100000), 1), 100000)

    where_clauses = ["1=1"]
    params = []
    if has_date_filter:
        where_clauses.append("DATE(pi.creation) BETWEEN %s AND %s")
        params += [fd, td]
    if line_status_filter:
        statuses_uniq = list({s for s in line_status_filter})
        ph_status = ", ".join(["%s"] * len(statuses_uniq))
        where_clauses.append(f"IFNULL(pil.po_line_status, '') IN ({ph_status})")
        params += statuses_uniq
    if search and search.strip():
        like = f"%{search.strip()}%"
        search_fields = [
            "pil.source_id", "pil.poid", "pil.item_code", "pil.item_description",
            "pil.site_code", "pil.site_name", "pil.project_code", "pil.project_name",
            "pil.sub_contract_no", "pil.payment_terms", "pil.center_area", "pil.shipment_number",
        ]
        where_clauses.append("(" + " OR ".join(f"{f} LIKE %s" for f in search_fields) + ")")
        params += [like] * len(search_fields)

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale (each column matched independently and ANDed, not blended
    # into the wide `search` box above).
    col_filter_map_dump = {
        "poid": "IFNULL(pil.poid,'')",
        "line_status": "IFNULL(pil.po_line_status,'')",
        "po_no": "IFNULL(pi.po_no,'')",
        "project": "IFNULL(pil.project_code,'')",
        "project_name": "IFNULL(pil.project_name,'')",
        "duid": "IFNULL(pil.site_code,'')",
        "item_code": "IFNULL(pil.item_code,'')",
        "item_description": "IFNULL(pil.item_description,'')",
        "qty": "CAST(pil.qty AS CHAR)",
        "unit_price": "CAST(pil.rate AS CHAR)",
        "amount": "CAST(pil.line_amount AS CHAR)",
        "start_date": "CAST(pil.start_date AS CHAR)",
        "end_date": "CAST(pil.end_date AS CHAR)",
    }
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — must be handled before
            # _sql_like_pattern(), which raises on a dict.
            if isinstance(raw_val, dict):
                clause, cparams = excel_filter_clause(col_filter_map_dump.get(col_key), raw_val)
                if clause:
                    where_clauses.append(clause)
                    params.extend(cparams)
                continue
            pat_d = _sql_like_pattern(raw_val)
            if not pat_d:
                continue
            expr_d = col_filter_map_dump.get(col_key)
            if not expr_d:
                continue
            where_clauses.append(f"{expr_d} LIKE %s")
            params.append(pat_d)

    fields_sql = ", ".join(f"pil.`{f}`" for f in fields)
    if _options:
        _e = col_filter_map_dump.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabPO Intake Line` pil JOIN `tabPO Intake` pi ON pi.name = pil.parent",
            " AND ".join(where_clauses), params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # The dump is an export view — what matters is the size and value of
        # what is about to be exported.
        return summary_from_query(
            "`tabPO Intake Line` pil JOIN `tabPO Intake` pi ON pi.name = pil.parent",
            " AND ".join(where_clauses), params, [
                {"key": "lines", "label": "Lines", "agg": "count"},
                {"key": "pos", "label": "POs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pi.po_no,''), '')"},
                {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pil.site_code,''), '')"},
                {"key": "value", "label": "Value", "agg": "sum",
                 "expr": "IFNULL(pil.line_amount, 0)", "format": "money", "tone": "good"},
            ])

    lines = frappe.db.sql(
        f"""
        SELECT {fields_sql},
               pi.po_no AS parent_po_no, pi.status AS parent_status,
               DATE(pi.creation) AS parent_upload_date
        FROM `tabPO Intake Line` pil
        JOIN `tabPO Intake` pi ON pi.name = pil.parent
        WHERE {' AND '.join(where_clauses)}
        ORDER BY pil.parent DESC, pil.idx ASC
        LIMIT {lim}
        """,
        params,
        as_dict=True,
    )
    for ln in lines:
        # The PO Dump column reads from the per-line status (po_line_status)
        # so each POID shows its own state. Treat New / Dispatched / Completed
        # as Open for filter / display roll-ups.
        line_status = (ln.get("po_line_status") or "").strip()
        if not line_status:
            line_status = (ln.get("parent_status") or "OPEN").strip()
        upper = line_status.upper()
        if upper in ("NEW", "DISPATCHED", "COMPLETED", "OPEN"):
            display_status = "OPEN"
        elif upper in ("CLOSED",):
            display_status = "CLOSED"
        elif upper in ("CANCELLED", "CANCELED"):
            display_status = "CANCELLED"
        else:
            display_status = upper or "OPEN"
        rows_out.append(
            {
                "id": ln.get("source_id") or "",
                "po_status": display_status,
                "po_line_status": line_status,
                "po_no": ln.get("parent_po_no") or "",
                "po_line_no": ln.get("po_line_no"),
                "shipment_no": ln.get("shipment_number") or "",
                "site_name": ln.get("site_name") or "",
                "site_code": ln.get("site_code") or "",
                "item_code": ln.get("item_code") or "",
                "item_description": ln.get("item_description") or "",
                "unit": ln.get("uom") or "",
                "requested_qty": ln.get("qty"),
                "due_qty": ln.get("due_qty"),
                "billed_quantity": ln.get("billed_quantity"),
                "quantity_cancel": ln.get("quantity_cancel"),
                "start_date": ln.get("start_date"),
                "end_date": ln.get("end_date"),
                "sub_contract_no": ln.get("sub_contract_no") or "",
                "currency": ln.get("currency") or "",
                "unit_price": ln.get("rate"),
                "line_amount": ln.get("line_amount"),
                "tax_rate": ln.get("tax_rate") or "",
                "payment_terms": ln.get("payment_terms") or "",
                "poid": ln.get("poid") or "",
                "project_code": ln.get("project_code") or "",
                "project_name": ln.get("project_name") or "",
                "center_area": ln.get("center_area") or "",
                "publish_date": ln.get("publish_date"),
                "upload_date": str(ln.get("parent_upload_date") or ""),
            }
        )

    return {
        "from_date": str(fd),
        "to_date": str(td),
        "rows": rows_out,
        "totals": bucket_totals,
    }


@frappe.whitelist()
def upload_po_file(file_url, customer=None):
    """
    Parse an uploaded Huawei PO export (.xlsx/.csv) and return validated / error rows.

    Returns
    -------
    {"valid_rows": [...], "error_rows": [...], "total": N}
    """
    # ---- Resolve the physical file path --------------------------------
    if file_url.startswith("/private/files/"):
        file_path = frappe.get_site_path("private", "files", file_url[len("/private/files/"):])
    elif file_url.startswith("/files/"):
        file_path = frappe.get_site_path("public", "files", file_url[len("/files/"):])
    else:
        # Fall back to Frappe File document
        try:
            file_doc = frappe.get_doc("File", {"file_url": file_url})
            file_path = file_doc.get_full_path()
        except Exception:
            frappe.throw(f"Cannot resolve file path for: {file_url}")

    # ---- Column alias map ----------------------------------------------
    ALIAS = {
        "ID": "source_id",
        "PO Status": "po_status",
        "PO STATUS": "po_status",
        "Status": "po_status",
        "PO status": "po_status",
        "PO NO.": "po_no",
        "PO Line NO.": "po_line_no",
        "Shipment NO.": "shipment_no",
        "Site Name": "site_name",
        "Site Code": "site_code",
        "Item Code": "item_code",
        "Item Description": "item_description",
        "Unit": "unit",
        "Requested Qty": "qty",
        "Due Qty": "due_qty",
        "Billed Quantity": "billed_quantity",
        "Quantity Cancel": "quantity_cancel",
        "Start Date": "start_date",
        "End Date": "end_date",
        "Sub Contract NO.": "sub_contract_no",
        "Currency": "currency",
        "Unit Price": "rate",
        "Line Amount": "line_amount",
        "Tax Rate": "tax_rate",
        "Payment Terms": "payment_terms",
        "Project Code": "project_code",
        "Project Name": "project_name",
        "Center Area": "center_area",
        "Publish Date": "publish_date",
    }

    ext = os.path.splitext(file_path)[1].lower()
    if ext == ".csv":
        with open(file_path, "r", encoding="utf-8-sig", newline="") as f:
            csv_rows = list(csv.reader(f))
        if not csv_rows:
            frappe.throw("The uploaded file appears to be empty.")
        raw_headers = csv_rows[0]
        rows_iter = iter(csv_rows[1:])
    else:
        try:
            import openpyxl
        except ImportError:
            frappe.throw("openpyxl is not installed. Run `bench pip install openpyxl`.")
        wb = openpyxl.load_workbook(file_path, data_only=True)
        ws = wb.active
        rows_iter = ws.iter_rows(values_only=True)
        raw_headers = next(rows_iter, None)

    # First row = headers
    if not raw_headers:
        frappe.throw("The uploaded file appears to be empty.")

    headers = [str(h).strip() if h is not None else "" for h in raw_headers]

    valid_rows = []
    error_rows = []
    cim_ensured_keys = set()

    for row_idx, raw_row in enumerate(rows_iter, start=2):
        row_dict = {}
        for col_idx, cell_val in enumerate(raw_row):
            raw_header = headers[col_idx] if col_idx < len(headers) else ""
            std_key = ALIAS.get(raw_header)
            if std_key:
                row_dict[std_key] = cell_val

        row_dict["po_status"] = _normalize_po_intake_status(row_dict.get("po_status"))

        # ---- Validation ------------------------------------------------
        errors = []
        # Standard upload is for active workflow lines only. Closed / Cancelled
        # lines must be backfilled through the Archive tab so they don't
        # auto-dispatch into the IM queue.
        if row_dict["po_status"] in ("CLOSED", "CANCELLED"):
            errors.append(
                f"PO Status is {row_dict['po_status']} — use the Archive tab to import closed / cancelled lines"
            )
        if not row_dict.get("po_no"):
            errors.append("po_no is required")
        # Accept rows where item_code is blank / "NA" if we can fall back to
        # the description (helper rewrites the code at confirm time).
        resolved_code, used_desc = _resolve_item_code_with_fallback(row_dict)
        if not resolved_code:
            errors.append("item_code is required (or provide an item_description fallback)")
        elif used_desc:
            row_dict["item_code"] = resolved_code
            if not str(row_dict.get("item_description") or "").strip():
                row_dict["item_description"] = resolved_code
        if not row_dict.get("project_code"):
            errors.append("project_code is required")
        qty = flt(row_dict.get("qty", 0))
        rate = flt(row_dict.get("rate", 0))
        if qty <= 0:
            errors.append("qty must be > 0")
        if rate <= 0:
            errors.append("rate must be > 0")

        project_code = str(row_dict.get("project_code") or "").strip()
        if project_code and not frappe.db.exists("Project Control Center", project_code):
            cust_for_proj = (customer or "").strip() or str(row_dict.get("customer") or "").strip()
            if cust_for_proj:
                ok_p, err_p = ensure_project_control_center(
                    project_code,
                    cust_for_proj,
                    row_dict.get("project_name"),
                    row_dict.get("center_area"),
                )
                if not ok_p:
                    errors.append(err_p or "Could not create Project Control Center")
            else:
                errors.append(
                    "project_code not found in Project Control Center (select customer on upload to auto-create project)"
                )

        item_code = str(row_dict.get("item_code") or "").strip()
        if item_code:
            ok_i, err_i = ensure_item_master(item_code, row_dict.get("item_description"))
            if not ok_i:
                errors.append(err_i or "Could not create Item")
        if customer and item_code:
            ck = (customer.strip(), item_code)
            if ck not in cim_ensured_keys:
                ok_cim, cim_err = ensure_customer_item_master(customer, item_code)
                if ok_cim:
                    cim_ensured_keys.add(ck)
                else:
                    errors.append(cim_err or "Could not create Customer Item Master")
        elif item_code:
            cim_filters = {"item_code": item_code, "active_flag": 1}
            if not frappe.db.exists("Customer Item Master", cim_filters):
                errors.append(
                    "item_code not found in Customer Item Master (pick a customer in upload to auto-create per customer)"
                )

        if errors:
            row_dict["_row"] = row_idx
            row_dict["_errors"] = errors
            error_rows.append(row_dict)
        else:
            row_dict["qty"] = qty
            row_dict["rate"] = rate
            line_amount = flt(row_dict.get("line_amount", 0))
            row_dict["line_amount"] = line_amount if line_amount > 0 else (qty * rate)
            row_dict["item_exists"] = True
            row_dict["project_exists"] = True
            valid_rows.append(row_dict)

    return {
        "valid_rows": valid_rows,
        "error_rows": error_rows,
        "total": len(valid_rows) + len(error_rows),
    }


_ITEM_CODE_PLACEHOLDERS = {"", "NA", "N/A", "-", "N.A.", "NULL", "NONE"}


def _resolve_item_code_with_fallback(line):
    """Return (item_code, used_description_flag).

    Some Master Tracker rows leave Item Code blank or filled in with ``NA``.
    Standard PO uploads can't insert a PO Intake Line with a blank Item Code
    (it's a mandatory link to ``Item``), so when the value is missing or a
    placeholder, fall back to using the Item Description as the code (truncated
    to fit Frappe's Data length limit). The matching ``Item`` will be created
    by ``ensure_item_master`` further down the line.
    """
    raw = (line.get("item_code") or "")
    code = str(raw).strip()
    if code.upper() in _ITEM_CODE_PLACEHOLDERS:
        desc = str(line.get("item_description") or "").strip()
        if desc:
            return desc[:140].strip(), True
        # No description either — caller will need to skip this row.
        return "", True
    return code, False


def _poid_for_upload_line(po_no, line):
    """Stable POID for de-duplication (matches PO Intake Line / dispatch conventions)."""
    return _make_poid(po_no, line.get("po_line_no"), line.get("shipment_no"))


def _existing_poids_on_intake_doc(doc):
    seen = set()
    for row in doc.po_lines:
        pid = (row.poid or "").strip()
        if not pid:
            pid = _make_poid(doc.po_no, row.po_line_no, row.shipment_number)
        seen.add(pid)
    return seen


@frappe.whitelist()
def confirm_po_upload(rows):
    """
    Take validated rows (JSON string or list), group by po_no, and create or extend PO Intake.

    New PO numbers create a PO Intake document. If the PO already exists, new lines are appended
    when their POID is not already on the document (same PO No + line + shipment).

    Returns
    -------
    {
        "created": new PO Intake documents created,
        "lines_imported": child lines inserted,
        "lines_skipped_duplicate": rows skipped because POID already exists,
        "names": names of newly created PO Intake docs (append-only POs omitted),
    }
    """
    rows = _parse_rows(rows)

    # Group by po_no (normalize key for DB lookup)
    po_groups = {}
    for row in rows:
        po_no = row.get("po_no")
        if po_no is None or str(po_no).strip() == "":
            continue
        key = str(po_no).strip()
        po_groups.setdefault(key, []).append(row)

    created = 0
    names = []
    lines_imported = 0
    lines_skipped_duplicate = 0
    lines_skipped_terminal = 0   # = closed + cancelled (kept for backward-compat)
    lines_skipped_closed = 0
    lines_skipped_cancelled = 0
    terminal_dupe_samples = []  # first ~20 (poid, existing_status) pairs for the FE summary
    item_code_from_desc = 0  # rows where item_code was blank / "NA" — fell back to item_description
    auto_dispatched = 0
    po_summary = []  # per-PO breakdown for audit/UI: [{po_no, intake_name, lines_added, lines_skipped, is_new}]

    for po_no, lines in po_groups.items():
        first = lines[0]

        # Resolve customer (same rules for new + existing intake)
        row_customer = first.get("customer")
        doc_customer = row_customer
        if not doc_customer:
            project_code_hdr = first.get("project_code")
            if project_code_hdr:
                doc_customer = frappe.db.get_value(
                    "Project Control Center", project_code_hdr, "customer"
                )
        if not doc_customer:
            frappe.throw(f"Customer is required for PO {po_no}")
        resolved_cust = _resolve_customer_link_name(doc_customer)
        if not resolved_cust:
            frappe.throw(f"Customer does not exist: {doc_customer}")

        existing_name = frappe.db.get_value("PO Intake", {"po_no": po_no}, "name")
        existing_poids = set()
        existing_status_by_poid = {}
        if existing_name:
            # Fetch fields for POID dedup + the existing line's status so we can
            # tell the user which duplicates are sitting under terminal states.
            existing_rows = frappe.db.sql(
                "SELECT po_line_no, shipment_number, poid, po_line_status "
                "FROM `tabPO Intake Line` WHERE parent=%s",
                existing_name, as_dict=True,
            )
            for r in existing_rows:
                pid = (r.poid or "").strip() or _make_poid(po_no, r.po_line_no, r.shipment_number)
                existing_poids.add(pid)
                existing_status_by_poid[pid] = (r.po_line_status or "").strip()
            existing_customer = frappe.db.get_value("PO Intake", existing_name, "customer")
            if existing_customer != resolved_cust:
                frappe.throw(
                    f"PO {po_no} already exists for customer {existing_customer}; "
                    f"upload uses {resolved_cust}. Use the same customer or a different PO number."
                )

        # Bulk pre-fetch project codes to avoid a frappe.db.exists() call per line
        all_project_codes = {
            str(l.get("project_code") or "").strip() for l in lines if l.get("project_code")
        }
        if all_project_codes:
            _ph = ",".join(["%s"] * len(all_project_codes))
            existing_projects = {
                r[0]
                for r in frappe.db.sql(
                    f"SELECT name FROM `tabProject Control Center` WHERE name IN ({_ph})",
                    list(all_project_codes),
                )
            }
        else:
            existing_projects = set()

        cim_pairs_done = set()
        duid_done = set()  # site_codes whose DUID master was already ensured this batch
        new_entries = []  # (source_line_dict, append_row_dict)
        po_skipped = 0

        for line in lines:
            poid = _poid_for_upload_line(po_no, line)
            if poid in existing_poids:
                lines_skipped_duplicate += 1
                po_skipped += 1
                existing_status = existing_status_by_poid.get(poid, "")
                if existing_status == "Closed":
                    lines_skipped_terminal += 1
                    lines_skipped_closed += 1
                elif existing_status == "Cancelled":
                    lines_skipped_terminal += 1
                    lines_skipped_cancelled += 1
                if existing_status in ("Closed", "Cancelled") and len(terminal_dupe_samples) < 20:
                    terminal_dupe_samples.append({
                        "poid": poid,
                        "existing_status": existing_status,
                        "po_no": po_no,
                    })
                continue

            item_code, used_desc = _resolve_item_code_with_fallback(line)
            if used_desc and item_code:
                # Stamp the resolved code back on the source line so subsequent
                # lookups (CIM, dispatch upsert) all see the same value.
                line["item_code"] = item_code
                if not str(line.get("item_description") or "").strip():
                    line["item_description"] = item_code
                item_code_from_desc += 1
            if not item_code:
                # Truly empty (no description either) — skip rather than fail.
                lines_skipped_duplicate += 1
                po_skipped += 1
                continue
            qty = flt(line.get("qty", 0))
            rate = flt(line.get("rate", 0))
            if qty <= 0 or rate <= 0:
                frappe.throw(f"Invalid qty/rate in PO {po_no} for item {item_code}")
            project_code = str(line.get("project_code") or "").strip()
            if project_code and project_code not in existing_projects:
                ok_p, err_p = ensure_project_control_center(
                    project_code,
                    resolved_cust,
                    line.get("project_name") or first.get("project_name"),
                    line.get("center_area") or first.get("center_area"),
                )
                if not ok_p:
                    frappe.throw(err_p or f"Project code not found: {project_code}")
                existing_projects.add(project_code)

            cim_key = (resolved_cust, item_code)
            if cim_key not in cim_pairs_done:
                ok_cim, cim_err = ensure_customer_item_master(resolved_cust, item_code)
                if not ok_cim:
                    frappe.throw(
                        cim_err
                        or f"Customer Item Master could not be created for customer {resolved_cust} and item {item_code}"
                    )
                cim_pairs_done.add(cim_key)

            line_center_area = line.get("center_area") or first.get("center_area")
            line_region = region_type_from_center_area(line_center_area)
            site_code = str(line.get("site_code") or "").strip()
            if site_code not in duid_done:
                ok_duid, err_duid = ensure_duid_master(
                    site_code,
                    line.get("site_name"),
                    line_center_area,
                )
                if not ok_duid:
                    frappe.throw(err_duid or f"Could not create DUID Master for {site_code}")
                duid_done.add(site_code)

            append_row = {
                "source_id": line.get("source_id"),
                "po_line_no": cint(line.get("po_line_no") or 0),
                "shipment_number": line.get("shipment_no"),
                "poid": poid,
                "site_code": site_code,
                "site_name": line.get("site_name"),
                "item_code": item_code,
                "item_description": line.get("item_description"),
                "uom": line.get("unit"),
                "qty": qty,
                "due_qty": flt(line.get("due_qty", 0)),
                "billed_quantity": flt(line.get("billed_quantity", 0)),
                "quantity_cancel": flt(line.get("quantity_cancel", 0)),
                "start_date": line.get("start_date"),
                "end_date": line.get("end_date"),
                "sub_contract_no": line.get("sub_contract_no"),
                "currency": line.get("currency"),
                "rate": rate,
                "line_amount": flt(line.get("line_amount", 0)) or (qty * rate),
                "tax_rate": line.get("tax_rate"),
                "payment_terms": line.get("payment_terms"),
                "project_code": line.get("project_code"),
                "project_name": line.get("project_name"),
                "center_area": line_center_area,
                "region_type": line_region,
                "publish_date": line.get("publish_date"),
            }
            new_entries.append((line, append_row))
            existing_poids.add(poid)

        if not new_entries:
            # Every line was a duplicate — still record the PO for the audit summary
            if po_skipped > 0:
                po_summary.append({
                    "po_no": po_no,
                    "intake_name": existing_name,
                    "lines_added": 0,
                    "lines_skipped": po_skipped,
                    "is_new": False,
                })
            continue

        hdr_status = first.get("po_status") or first.get("status") or first.get("po_intake_status")

        if existing_name:
            doc = frappe.get_doc("PO Intake", existing_name)
            doc.status = _normalize_po_intake_status(hdr_status)
            for _src, append_row in new_entries:
                doc.append("po_lines", append_row)
            # Defence in depth: a few legacy rows leak into valid_rows with a
            # blank item_code (e.g. when the source cell is whitespace). Don't
            # blow up the whole upload — the helper above already filled in a
            # description-derived code where possible.
            # NOTE: flags.ignore_mandatory does NOT propagate to child saves in Frappe.
            # If a child row ever has a blank mandatory field this will still throw.
            # Fix if it surfaces: change to doc.save(ignore_mandatory=True, ...) or
            # pre-fill the field with a placeholder before saving.
            doc.flags.ignore_mandatory = True
            doc.save(ignore_permissions=True)
            is_new_po = False
        else:
            doc = frappe.new_doc("PO Intake")
            doc.po_no = po_no
            doc.customer = resolved_cust
            doc.status = _normalize_po_intake_status(hdr_status)
            doc.publish_date = first.get("publish_date")
            doc.center_area = first.get("center_area")
            for _src, append_row in new_entries:
                doc.append("po_lines", append_row)
            doc.flags.ignore_mandatory = True
            doc.insert(ignore_permissions=True)
            created += 1
            names.append(doc.name)
            is_new_po = True

        frappe.db.commit()
        lines_imported += len(new_entries)
        po_summary.append({
            "po_no": po_no,
            "intake_name": doc.name,
            "lines_added": len(new_entries),
            "lines_skipped": po_skipped,
            "is_new": is_new_po,
        })

        # Resolve DB names for new child rows via SQL — avoids doc.reload() + O(n²) scan
        new_poid_map = {append_row["poid"]: append_row for _src, append_row in new_entries}
        child_sql_rows = frappe.db.sql(
            "SELECT name, po_line_no, shipment_number, poid FROM `tabPO Intake Line` WHERE parent=%s",
            doc.name, as_dict=True,
        )
        child_rows = []
        for r in child_sql_rows:
            got_poid = (r.poid or "").strip() or _make_poid(po_no, r.po_line_no, r.shipment_number)
            if got_poid in new_poid_map:
                row_dict = dict(new_poid_map[got_poid])
                row_dict["name"] = r.name
                row_dict["parent"] = doc.name
                child_rows.append((r.name, row_dict))

        # Ensure each new line has a PO Dispatch row + immutable system_id even before dispatch.
        for _child_name, line_dict in child_rows:
            _upsert_po_dispatch_for_line(
                doc.name,
                po_no,
                line_dict,
                customer=resolved_cust,
                dispatch_status="Pending",
                dispatch_mode="Manual",
            )
        auto_dispatched += _try_auto_dispatch(doc.name, po_no, child_rows)

    return {
        "created": created,
        "lines_imported": lines_imported,
        "lines_skipped_duplicate": lines_skipped_duplicate,
        "lines_skipped_terminal": lines_skipped_terminal,
        "lines_skipped_closed": lines_skipped_closed,
        "lines_skipped_cancelled": lines_skipped_cancelled,
        "terminal_dupe_samples": terminal_dupe_samples,
        "item_code_from_desc": item_code_from_desc,
        "auto_dispatched": auto_dispatched,
        "names": names,
        "po_summary": po_summary,
    }


@frappe.whitelist()
def record_po_upload_log(payload):
    """Persist a PO Upload Log for audit/history. Called after all chunks complete.

    payload = {
        "file_name": "...", "file_url": "...", "customer": "...",
        "total_rows": N, "lines_imported": N, "lines_skipped": N,
        "po_created": N, "po_updated": N, "auto_dispatched": N,
        "po_summary": [{po_no, intake_name, lines_added, lines_skipped, is_new/status}, ...],
        "status": "Completed"|"Partial"|"Failed",
        "notes": "...",
    }
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload)
    payload = payload or {}

    doc = frappe.new_doc("PO Upload Log")
    doc.uploaded_by = frappe.session.user
    doc.uploaded_at = frappe.utils.now_datetime()
    doc.file_name = (payload.get("file_name") or "")[:140]
    doc.file_url = (payload.get("file_url") or "")[:240]
    doc.customer = payload.get("customer") or None
    doc.total_rows = cint(payload.get("total_rows") or 0)
    doc.lines_imported = cint(payload.get("lines_imported") or 0)
    doc.lines_skipped = cint(payload.get("lines_skipped") or 0)
    doc.lines_skipped_terminal = cint(payload.get("lines_skipped_terminal") or 0)
    doc.lines_skipped_closed = cint(payload.get("lines_skipped_closed") or 0)
    doc.lines_skipped_cancelled = cint(payload.get("lines_skipped_cancelled") or 0)
    samples = payload.get("terminal_dupe_samples")
    if samples:
        try:
            doc.terminal_dupe_samples = frappe.as_json(samples)[:8000]
        except Exception:
            doc.terminal_dupe_samples = None
    doc.po_created = cint(payload.get("po_created") or 0)
    doc.po_updated = cint(payload.get("po_updated") or 0)
    doc.auto_dispatched = cint(payload.get("auto_dispatched") or 0)
    doc.status = payload.get("status") or "Completed"
    doc.notes = (payload.get("notes") or "")[:2000]

    for item in (payload.get("po_summary") or []):
        if not isinstance(item, dict):
            continue
        status = item.get("status")
        if not status:
            if item.get("is_new"):
                status = "New"
            elif cint(item.get("lines_added") or 0) > 0:
                status = "Appended"
            else:
                status = "Duplicate"
        doc.append("po_details", {
            "po_no": (item.get("po_no") or "")[:140],
            "intake_name": item.get("intake_name") or None,
            "status": status,
            "lines_added": cint(item.get("lines_added") or 0),
            "lines_skipped": cint(item.get("lines_skipped") or 0),
        })

    doc.insert(ignore_permissions=True)
    frappe.db.commit()
    return {"name": doc.name}


@frappe.whitelist()
def list_po_upload_logs(limit=50):
    """Return recent PO Upload Log entries with per-PO counts."""
    limit = cint(limit or 50)
    if limit <= 0 or limit > 500:
        limit = 50
    rows = frappe.get_all(
        "PO Upload Log",
        fields=[
            "name", "uploaded_by", "uploaded_at", "customer", "file_name",
            "total_rows", "lines_imported", "lines_overridden", "lines_skipped", "lines_skipped_terminal",
            "lines_skipped_closed", "lines_skipped_cancelled",
            "po_created", "po_updated", "auto_dispatched", "status",
        ],
        order_by="uploaded_at desc",
        limit_page_length=limit,
    )
    # Attach po count per log (quick summary; full details on demand)
    log_names = [r.name for r in rows]
    counts = {}
    if log_names:
        placeholders = ",".join(["%s"] * len(log_names))
        count_rows = frappe.db.sql(
            f"SELECT parent, COUNT(*) AS c FROM `tabPO Upload Log Detail` "
            f"WHERE parent IN ({placeholders}) GROUP BY parent",
            log_names,
            as_dict=True,
        )
        counts = {r.parent: r.c for r in count_rows}
    for r in rows:
        r["po_count"] = counts.get(r.name, 0)
    return rows


@frappe.whitelist()
def get_po_upload_log(name):
    """Return a PO Upload Log with its per-PO detail rows."""
    if not name:
        frappe.throw("name is required")
    if not frappe.db.exists("PO Upload Log", name):
        frappe.throw(f"PO Upload Log not found: {name}")
    doc = frappe.get_doc("PO Upload Log", name)
    samples = []
    if getattr(doc, "terminal_dupe_samples", None):
        try:
            parsed = frappe.parse_json(doc.terminal_dupe_samples)
            if isinstance(parsed, list):
                samples = parsed
        except Exception:
            samples = []
    return {
        "name": doc.name,
        "uploaded_by": doc.uploaded_by,
        "uploaded_at": doc.uploaded_at,
        "customer": doc.customer,
        "file_name": doc.file_name,
        "file_url": doc.file_url,
        "status": doc.status,
        "total_rows": doc.total_rows,
        "lines_imported": doc.lines_imported,
        "lines_overridden": getattr(doc, "lines_overridden", 0) or 0,
        "lines_skipped": doc.lines_skipped,
        "lines_skipped_terminal": getattr(doc, "lines_skipped_terminal", 0) or 0,
        "lines_skipped_closed": getattr(doc, "lines_skipped_closed", 0) or 0,
        "lines_skipped_cancelled": getattr(doc, "lines_skipped_cancelled", 0) or 0,
        "terminal_dupe_samples": samples,
        "po_created": doc.po_created,
        "po_updated": doc.po_updated,
        "auto_dispatched": doc.auto_dispatched,
        "notes": doc.notes,
        "po_details": [
            {
                "po_no": d.po_no,
                "intake_name": d.intake_name,
                "status": d.status,
                "lines_added": d.lines_added,
                "lines_skipped": d.lines_skipped,
            }
            for d in (doc.po_details or [])
        ],
    }


def _get_dispatch_for_intake_line(parent_name, po_line_no):
    """Load dispatch row for a PO Intake line; tolerate DB missing `region_type` before migrate."""
    filters = {"po_intake": parent_name, "po_line_no": po_line_no}
    fields_full = [
        "name", "system_id", "im", "dispatch_mode", "target_month", "region_type", "center_area",
    ]
    try:
        return frappe.db.get_value("PO Dispatch", filters, fields_full, as_dict=True) or {}
    except frappe.db.OperationalError as e:
        if not frappe.db.is_missing_column(e):
            raise
        row = frappe.db.get_value(
            "PO Dispatch",
            filters,
            ["name", "system_id", "im", "dispatch_mode", "target_month", "center_area"],
            as_dict=True,
        ) or {}
        row["region_type"] = region_type_from_center_area(row.get("center_area"))
        return row


@frappe.whitelist()
def list_po_intake_lines(status="New", limit=None, portal_filters=None, _options=None, _summary=None):
    """
    Return PO Intake child lines that match given po_line_status (or all when status='all').
    Each row is enriched with parent PO Intake fields and, for dispatched lines, dispatch info.

    ``portal_filters`` (JSON dict) may include: search, project_code, site_code, dispatched_im (or im),
    from_date, to_date (dispatch ``target_month`` when a dispatch row exists),
    intake_tab (e.g. ``New`` — skips IM-on-dispatch filter so undispatched lines are not dropped).
    """
    filters = {}
    if status and status.lower() != "all":
        filters["po_line_status"] = status

    limit_page_length = _portal_row_limit(limit, 500)
    pf = _portal_filters_dict(portal_filters)

    def _portal_active():
        if not pf:
            return False
        for k in ("search", "q", "project_code", "site_code", "item_code", "dispatched_im", "im", "from_date", "to_date", "line_status"):
            if (pf.get(k) or "").strip() if isinstance(pf.get(k), str) else pf.get(k):
                return True
        cf = pf.get("column_filters")
        if isinstance(cf, str):
            try:
                cf = frappe.parse_json(cf)
            except Exception:
                cf = None
        if isinstance(cf, dict) and any(str(v or "").strip() for v in cf.values()):
            return True
        return False

    line_fields_full = [
        "name", "parent", "po_line_no", "poid", "shipment_number",
        "item_code", "item_description", "qty", "rate", "line_amount",
        "project_code", "site_code", "site_name", "area", "center_area", "region_type",
        "po_line_status", "activity_code", "dispatch_mode",
    ]
    line_fields_base = [
        "name", "parent", "po_line_no", "poid", "shipment_number",
        "item_code", "item_description", "qty", "rate", "line_amount",
        "project_code", "site_code", "site_name", "area",
        "po_line_status", "activity_code", "dispatch_mode",
    ]

    lines = []
    # `or _options` / `or _summary`: both are built from the wheres/params
    # assembled in this branch, so it must be taken even when no portal filter
    # is active (otherwise the non-SQL path returns rows instead of options).
    if _portal_active() or _options or _summary:
        wheres = ["1=1"]
        params = []
        if filters.get("po_line_status"):
            wheres.append("pil.po_line_status = %s")
            params.append(filters["po_line_status"])
        # Toolbar "Status" dropdown - only meaningful on the "All Lines" tab
        # (status="all"), since the other tabs already exact-match via the
        # `status` positional arg above; distinct from the Manage Table
        # column filter's "status" key (col_filter_map_intake, LIKE-based).
        line_status_vals = _ensure_list(pf.get("line_status"))
        if line_status_vals:
            c, p = _sql_in_or_eq("IFNULL(pil.po_line_status,'')", line_status_vals)
            if c:
                wheres.append(c)
                params.extend(p)
        for col, key in (("IFNULL(pil.project_code,'')", "project_code"),
                         ("IFNULL(pil.site_code,'')", "site_code"),
                         ("IFNULL(pil.item_code,'')", "item_code")):
            c, p = _sql_in_or_eq(col, pf.get(key))
            if c:
                wheres.append(c)
                params.extend(p)
        im_vals = _ensure_list(pf.get("dispatched_im") or pf.get("im"))
        intake_tab = (pf.get("intake_tab") or "").strip().lower()
        if im_vals and intake_tab != "new":
            c, p = _sql_in_or_eq("IFNULL(pd.im,'')", im_vals)
            wheres.append(c)
            params.extend(p)
        if pf.get("from_date") and pf.get("to_date"):
            wheres.append(
                "(pd.name IS NULL OR (pd.target_month BETWEEN %s AND %s))"
            )
            params.extend([pf["from_date"], pf["to_date"]])
        elif pf.get("from_date"):
            wheres.append("(pd.name IS NULL OR pd.target_month >= %s)")
            params.append(pf["from_date"])
        elif pf.get("to_date"):
            wheres.append("(pd.name IS NULL OR pd.target_month <= %s)")
            params.append(pf["to_date"])
        # Per-column "Manage Table" filters — see list_im_rollout_plans for
        # the rationale. "Domain"/"Huawei IM" are normally Python post-query
        # enrichments (_enrich_with_project_fields, by project_code) — the
        # `pcc` join below makes them backend-filterable too, same pattern
        # used for list_execution_monitor_rows/list_issue_risk_rows.
        col_filter_map_intake = {
            "poid": "IFNULL(pil.poid,'')",
            "system_id": "IFNULL(pd.system_id,'')",
            "po_no": "IFNULL(pi.po_no,'')",
            "shipment_no": "IFNULL(pil.shipment_number,'')",
            "item_code": "IFNULL(pil.item_code,'')",
            "description": "IFNULL(pil.item_description,'')",
            "qty": "CAST(pil.qty AS CHAR)",
            "rate": "CAST(pil.rate AS CHAR)",
            "amount": "CAST(pil.line_amount AS CHAR)",
            "project": "IFNULL(pil.project_code,'')",
            "duid": "IFNULL(pil.site_code,'')",
            "domain": "COALESCE(NULLIF(pd.project_domain,''), pcc_pil.project_domain, '')",
            "huawei_im": "IFNULL(pcc_pil.huawei_im,'')",
            "mode": "COALESCE(NULLIF(pil.dispatch_mode,''), pd.dispatch_mode, '')",
            "target_month": "CAST(pd.target_month AS CHAR)",
            "status": "IFNULL(pil.po_line_status,'')",
            # Parent PO Intake status, shown as the "PO Status" column.
            "po_status": "IFNULL(pi.status,'')",
            # Column shows dispatched_im_full_name (see
            # _batch_im_master_full_names below) with the code as fallback —
            # resolve the same way so the dropdown matches the cells.
            "im": ("IFNULL(NULLIF((SELECT imm_i.full_name FROM `tabIM Master` imm_i "
                   "WHERE imm_i.name = pd.im), ''), IFNULL(pd.im,''))"),
            # Replaces the old collapsed, unfilterable "current_stage" column
            # with its own real pieces — each one backend-filterable, unlike
            # the composite string it replaced.
            "plan_status": (
                "IFNULL((SELECT rp.plan_status FROM `tabRollout Plan` rp "
                "WHERE rp.po_dispatch = pd.name AND rp.plan_status != 'Cancelled' "
                "ORDER BY IFNULL(rp.visit_number,0) DESC, rp.modified DESC LIMIT 1), '')"
            ),
            # IFNULL wraps the CAST, not just the subquery — CAST(NULL AS CHAR)
            # is NULL, and NULL never equals '' in SQL, so has_blanks/ != ''
            # checks elsewhere in excel_options_from_query would silently
            # never treat a blank plan_date as blank.
            "plan_date": (
                "IFNULL(CAST((SELECT rp.plan_date FROM `tabRollout Plan` rp "
                "WHERE rp.po_dispatch = pd.name AND rp.plan_status != 'Cancelled' "
                "ORDER BY IFNULL(rp.visit_number,0) DESC, rp.modified DESC LIMIT 1) AS CHAR), '')"
            ),
            # Keys must match DataTablePro's auto-derived col_key for the
            # header text — "PIC Status (MS1)"/"PIC Status (MS2)" both slugify
            # to pic_status_ms1/pic_status_ms2 (see keyFromLabel in
            # DataTablePro.jsx), not "pic_status". The cell renders via
            # PicStatusBadge, which displays "Work Not Done" for a blank
            # value rather than leaving it empty — match that here too, or
            # the dropdown's "(Blanks)" option wouldn't correspond to any
            # value actually shown on screen.
            "pic_status_ms1": "IF(IFNULL(pd.pic_status,'')='', 'Work Not Done', pd.pic_status)",
            "pic_status_ms2": "IF(IFNULL(pd.pic_status_ms2,'')='', 'Work Not Done', pd.pic_status_ms2)",
            # How the line got its Work Done — Rollout Execution / Backend /
            # Direct Close (Work Done.source). Blank until work is actually
            # recorded.
            "work_type": (
                "IFNULL((SELECT wd.source FROM `tabWork Done` wd "
                "WHERE wd.system_id = pd.name ORDER BY wd.modified DESC LIMIT 1), '')"
            ),
            "subcon_status": "IFNULL(pd.subcon_status,'')",
            # Column shows the team's display name (see the backend_team_name_map
            # resolution below) with the code as fallback — resolve the same
            # way so the dropdown matches the cells, same pattern as "im".
            "backend_team": (
                "IFNULL(NULLIF((SELECT bt.team_name FROM `tabINET Team` bt "
                "WHERE bt.name = pd.backend_team), ''), IFNULL(pd.backend_team,''))"
            ),
            "subcon_completed_on": "IFNULL(CAST(pd.subcon_completed_on AS CHAR), '')",
            "ms1_amount": "IFNULL(CAST(pd.ms1_amount AS CHAR), '')",
            "ms2_amount": "IFNULL(CAST(pd.ms2_amount AS CHAR), '')",
        }
        if frappe.db.has_column("PO Intake Line", "center_area"):
            col_filter_map_intake["center_area"] = "IFNULL(pil.center_area,'')"
        if frappe.db.has_column("PO Intake Line", "region_type"):
            col_filter_map_intake["region"] = "IFNULL(pil.region_type,'')"
        col_filter_map_intake["activity_type"] = (
            "IFNULL((SELECT activity_type FROM `tabItem` WHERE name = pil.item_code), '')"
        )
        column_filters_intake = pf.get("column_filters")
        if isinstance(column_filters_intake, str):
            try:
                column_filters_intake = frappe.parse_json(column_filters_intake)
            except Exception:
                column_filters_intake = None
        if isinstance(column_filters_intake, dict):
            for col_key, raw_val in column_filters_intake.items():
                # Excel-style value filter — must be handled before
                # _sql_like_pattern(), which raises on a dict.
                if isinstance(raw_val, dict):
                    # col_filter_map_intake["im"] already resolves the full
                    # name the column displays — don't override it with the code.
                    expr_x = col_filter_map_intake.get(col_key)
                    clause, cparams = excel_filter_clause(expr_x, raw_val)
                    if clause:
                        wheres.append(clause)
                        params.extend(cparams)
                    continue
                pat_i = _sql_like_pattern(raw_val)
                if not pat_i:
                    continue
                if col_key == "im":
                    wheres.append(
                        "(IFNULL(pd.im,'') LIKE %s OR pd.im IN "
                        "(SELECT name FROM `tabIM Master` WHERE full_name LIKE %s))"
                    )
                    params.extend([pat_i, pat_i])
                    continue
                expr_i = col_filter_map_intake.get(col_key)
                if not expr_i:
                    continue
                wheres.append(f"{expr_i} LIKE %s")
                params.append(pat_i)

        concat_expr_intake = (
            "CONCAT_WS(' ', IFNULL(pil.name,''), IFNULL(pil.poid,''), IFNULL(pil.item_code,''), "
            "IFNULL(pil.item_description,''), "
            "IFNULL(pil.project_code,''), IFNULL(pil.site_code,''), IFNULL(pi.po_no,''), "
            "IFNULL(pi.customer,''), IFNULL(pil.center_area,''), IFNULL(pil.region_type,''), "
            "COALESCE(NULLIF(pd.project_domain,''), pcc_pil.project_domain, ''), IFNULL(pcc_pil.huawei_im,''))"
        )
        clause, cparams = _sql_search_clause(
            concat_expr_intake, pf.get("search") or pf.get("q") or "",
            exact_cols=["IFNULL(pil.poid,'')", "IFNULL(pil.site_code,'')", "IFNULL(pil.name,'')"],
        )
        if clause:
            wheres.append(clause)
            params.extend(cparams)
        # Excel column-filter option list. Answered here rather than from a
        # separate endpoint so it reuses THIS function's fully-built wheres/
        # params — the option list can then never offer a value that the row
        # query would return nothing for.
        if _options:
            _ocol = _options.get("col_key")
            _expr = col_filter_map_intake.get(_ocol)
            if not _expr:
                return {"values": [], "has_blanks": False, "total": 0, "supported": False}
            return excel_options_from_query(
                INTAKE_LINE_FROM_SQL, " AND ".join(wheres), params, _expr,
                bucket=_options.get("bucket"), search=_options.get("search"),
                limit=_options.get("limit"), label_kind=_options.get("label_kind"),
            )
        if _summary:
            # PM's question on this page is dispatch throughput: how much is
            # still waiting on me, how much is out with the teams, and how much
            # of it went out automatically. Value is the PO line amount, which
            # is what the table's own total column adds up.
            _mode = "COALESCE(NULLIF(pil.dispatch_mode,''), pd.dispatch_mode, '')"
            _st = "IFNULL(pil.po_line_status,'')"
            return summary_from_query(INTAKE_LINE_FROM_SQL, " AND ".join(wheres), params, [
                {"key": "lines", "label": "Lines", "agg": "count"},
                {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pil.site_code,''), '')"},
                {"key": "value", "label": "Value", "agg": "sum",
                 "expr": "IFNULL(pil.line_amount, 0)", "format": "money", "tone": "good"},
                {"key": "new", "label": "To dispatch", "agg": "count_if", "group": "Pipeline",
                 "cond": f"{_st} = 'New'", "tone": "warn",
                 "hint": "Not dispatched yet — waiting on PM"},
                {"key": "dispatched", "label": "Dispatched", "agg": "count_if", "group": "Pipeline",
                 "cond": f"{_st} = 'Dispatched'", "tone": "info"},
                {"key": "completed", "label": "Completed", "agg": "count_if", "group": "Pipeline",
                 "cond": f"{_st} = 'Completed'", "tone": "good", "hide_if_zero": True},
                {"key": "closed", "label": "Closed", "agg": "count_if", "group": "Pipeline",
                 "cond": f"{_st} = 'Closed'", "hide_if_zero": True},
                {"key": "cancelled", "label": "Cancelled", "agg": "count_if", "group": "Pipeline",
                 "cond": f"{_st} = 'Cancelled'", "tone": "bad", "hide_if_zero": True},
                {"key": "auto", "label": "Auto", "agg": "count_if", "group": "Mode",
                 "cond": f"{_mode} = 'Auto'", "hide_if_zero": True},
                {"key": "manual", "label": "Manual", "agg": "count_if", "group": "Mode",
                 "cond": f"{_mode} = 'Manual'", "hide_if_zero": True},
            ])
        id_sql = (
            "SELECT pil.name AS line_id "
            "FROM `tabPO Intake Line` pil "
            "INNER JOIN `tabPO Intake` pi ON pi.name = pil.parent "
            "LEFT JOIN `tabPO Dispatch` pd ON pd.po_intake = pil.parent AND pd.po_line_no = pil.po_line_no "
            "LEFT JOIN `tabProject Control Center` pcc_pil ON pcc_pil.name = pil.project_code "
            f"WHERE {' AND '.join(wheres)} "
            "ORDER BY pil.parent DESC, pil.idx ASC "
            f"{_sql_limit_suffix(limit_page_length)}"
        )
        id_rows = frappe.db.sql(id_sql, tuple(params), as_dict=True)
        line_ids = [r.line_id for r in (id_rows or []) if r.get("line_id")]
        if not line_ids:
            lines = []
        else:
            order_index = {n: i for i, n in enumerate(line_ids)}
            try:
                lines = frappe.get_all(
                    "PO Intake Line",
                    filters={"name": ["in", line_ids]},
                    fields=line_fields_full,
                    limit_page_length=len(line_ids) + 1,
                )
            except frappe.db.OperationalError as e:
                if not frappe.db.is_missing_column(e):
                    raise
                lines = frappe.get_all(
                    "PO Intake Line",
                    filters={"name": ["in", line_ids]},
                    fields=line_fields_base,
                    limit_page_length=len(line_ids) + 1,
                )
                for row in lines:
                    row.setdefault("center_area", None)
                    row.setdefault("region_type", None)
            lines.sort(key=lambda r: order_index.get(r.name, 10**9))
    else:
        ga_kwargs = dict(
            filters=filters,
            order_by="parent desc, idx asc",
        )
        if limit_page_length:
            ga_kwargs["limit_page_length"] = limit_page_length
        try:
            lines = frappe.get_all("PO Intake Line", fields=line_fields_full, **ga_kwargs)
        except frappe.db.OperationalError as e:
            if not frappe.db.is_missing_column(e):
                raise
            lines = frappe.get_all("PO Intake Line", fields=line_fields_base, **ga_kwargs)
            for row in lines:
                row.setdefault("center_area", None)
                row.setdefault("region_type", None)

    # Batch-enrich: two bulk fetches replace 1 query per parent + 1 query per line.
    # For 4k+ rows this collapses ~4000 round-trips into 2, cutting load from ~40s
    # to sub-second on realistic sizes.
    parent_names = list({line.get("parent") for line in lines if line.get("parent")})
    parent_map = {}
    if parent_names:
        for chunk in _chunked(parent_names):
            for p in frappe.get_all(
                "PO Intake",
                filters={"name": ["in", chunk]},
                fields=["name", "po_no", "customer", "center_area"],
                limit_page_length=len(chunk) + 1,
            ):
                parent_map[p.name] = p

    dispatch_map = {}
    if parent_names:
        disp_fields_full = [
            "name", "po_intake", "po_line_no", "system_id", "im", "huawei_im",
            "dispatch_mode", "target_month", "region_type", "center_area",
            "ms1_amount", "ms2_amount", "pic_status", "pic_status_ms2", "dispatch_status",
            "subcon_status", "backend_team", "subcon_completed_on",
        ]
        disp_fields_base = [
            "name", "po_intake", "po_line_no", "system_id", "im",
            "dispatch_mode", "target_month", "center_area", "dispatch_status",
        ]
        all_disp = []
        use_base_fields = False
        for chunk in _chunked(parent_names):
            if not use_base_fields:
                try:
                    all_disp.extend(frappe.get_all(
                        "PO Dispatch",
                        filters={"po_intake": ["in", chunk]},
                        fields=disp_fields_full,
                        limit_page_length=len(chunk) * 100 + 1,
                    ))
                    continue
                except frappe.db.OperationalError as e:
                    if not frappe.db.is_missing_column(e):
                        raise
                    use_base_fields = True
                    # Fall through to fetch this chunk (and every subsequent
                    # one) with the reduced field set below.
            chunk_disp = frappe.get_all(
                "PO Dispatch",
                filters={"po_intake": ["in", chunk]},
                fields=disp_fields_base,
                limit_page_length=len(chunk) * 100 + 1,
            )
            for d in chunk_disp:
                d["region_type"] = region_type_from_center_area(d.get("center_area"))
            all_disp.extend(chunk_disp)
        for d in all_disp:
            dispatch_map[(d.po_intake, cint(d.po_line_no))] = d

    for line in lines:
        parent_name = line.get("parent")
        pdata = parent_map.get(parent_name) or {}
        line["po_no"] = pdata.get("po_no", "")
        line["customer"] = pdata.get("customer", "")
        line["po_intake"] = parent_name
        line["center_area"] = line.get("center_area") or pdata.get("center_area")

        dispatch_data = dispatch_map.get((parent_name, cint(line.get("po_line_no")))) or {}
        if dispatch_data:
            line["dispatch_name"] = dispatch_data.get("name")
            line["system_id"] = dispatch_data.get("system_id")
            line["dispatch_status"] = dispatch_data.get("dispatch_status")
        if dispatch_data:
            # Was gated to po_line_status == "Dispatched" only, so the "All
            # Lines" tab silently showed a blank IM/target month/MS amounts
            # for Closed/Cancelled/Completed lines even though their linked
            # PO Dispatch record has real values - any status with a linked
            # dispatch should show them.
            line["dispatched_im"] = dispatch_data.get("im")
            line["dispatch_target_month"] = dispatch_data.get("target_month")
            if not line.get("dispatch_mode"):
                line["dispatch_mode"] = dispatch_data.get("dispatch_mode")
            if dispatch_data.get("region_type"):
                line["region_type"] = dispatch_data.get("region_type")
            elif not line.get("region_type"):
                line["region_type"] = region_type_from_center_area(
                    dispatch_data.get("center_area") or line.get("center_area")
                )
            line["ms1_amount"] = flt(dispatch_data.get("ms1_amount") or 0)
            line["ms2_amount"] = flt(dispatch_data.get("ms2_amount") or 0)
            line["pic_status"] = dispatch_data.get("pic_status")
            line["pic_status_ms2"] = dispatch_data.get("pic_status_ms2")
            line["huawei_im"] = dispatch_data.get("huawei_im")
            line["subcon_status"] = dispatch_data.get("subcon_status")
            line["backend_team"] = dispatch_data.get("backend_team")
            line["subcon_completed_on"] = dispatch_data.get("subcon_completed_on")

        if not line.get("region_type"):
            line["region_type"] = region_type_from_center_area(line.get("center_area"))

    im_dispatched_ids = list(
        {
            line.get("dispatched_im")
            for line in lines
            if line.get("dispatched_im")
        }
    )
    im_fn_map = _batch_im_master_full_names(im_dispatched_ids)
    for line in lines:
        imn = line.get("dispatched_im")
        if imn:
            line["dispatched_im_full_name"] = im_fn_map.get(imn)

    # Backend Team — show the display name (falls back to the code), same
    # idea as dispatched_im_full_name above.
    backend_team_ids = list({line.get("backend_team") for line in lines if line.get("backend_team")})
    backend_team_name_map = {}
    if backend_team_ids:
        for chunk in _chunked(backend_team_ids):
            for t in frappe.get_all(
                "INET Team", filters={"name": ["in", chunk]}, fields=["name", "team_name"],
            ):
                backend_team_name_map[t.name] = t.team_name
    for line in lines:
        bt = line.get("backend_team")
        if bt:
            line["backend_team"] = backend_team_name_map.get(bt) or bt

    _enrich_with_project_fields(lines)
    # Pre-existing gap: this function never populated activity_type at all
    # (admin/PODispatch.jsx's "Activity Type" column always showed blank),
    # unrelated to the filter fix below but fixed alongside it.
    act_map_pil = _batch_item_activity_types(lines)
    for line in lines:
        line["activity_type"] = act_map_pil.get(line.get("item_code") or "")

    # Plan Status / Work Done Status / Work Done Revenue (admin/PODispatch.jsx
    # "All Lines" tab) - where a Dispatched/Completed line actually is right
    # now across the wider pipeline (Planning/In Execution/... -> Work Done ->
    # PIC), shown as their own columns rather than one collapsed "Current
    # Stage" string (which hid whichever of these wasn't picked, and couldn't
    # be backend-filtered at all). pic_status/pic_status_ms2 are already set
    # on `line` above (real PO Dispatch columns, both shown as their own
    # columns too). Batched + chunked (see _chunked) so this stays safe at
    # the same "All Lines, row limit All" scale that caused the earlier
    # SQLParseError.
    stage_dispatch_names = list({
        line.get("dispatch_name")
        for line in lines
        if line.get("dispatch_name") and line.get("po_line_status") in ("Dispatched", "Completed")
    })
    work_type = {}
    latest_plan_status = {}
    latest_plan_date = {}
    if stage_dispatch_names:
        wd_rows_for_stage = []
        for chunk in _chunked(stage_dispatch_names):
            wd_rows_for_stage.extend(frappe.get_all(
                "Work Done",
                filters={"system_id": ["in", chunk]},
                fields=["system_id", "source", "modified"],
                order_by="modified desc",
            ))
        for r in wd_rows_for_stage:
            # Work type takes the most recently touched row, same "latest
            # wins" rule as plan status/date below.
            if r.system_id not in work_type:
                work_type[r.system_id] = r.source
        plan_rows_for_stage = []
        for chunk in _chunked(stage_dispatch_names):
            plan_rows_for_stage.extend(frappe.get_all(
                "Rollout Plan",
                filters={"po_dispatch": ["in", chunk]},
                fields=["po_dispatch", "plan_status", "plan_date", "visit_number", "modified"],
                order_by="visit_number desc, modified desc",
            ))
        for r in plan_rows_for_stage:
            if r.po_dispatch not in latest_plan_status:
                latest_plan_status[r.po_dispatch] = r.plan_status
                latest_plan_date[r.po_dispatch] = r.plan_date

    for line in lines:
        dispatch_name = line.get("dispatch_name")
        line["plan_status"] = latest_plan_status.get(dispatch_name)
        line["plan_date"] = latest_plan_date.get(dispatch_name)
        line["work_type"] = work_type.get(dispatch_name)

    return lines


def _require_inet_im_session():
    user = frappe.session.user
    if not user or user == "Guest":
        frappe.throw("Not permitted", frappe.PermissionError)
    roles = set(frappe.get_roles(user))
    if (
        "INET IM" not in roles
        and "Administrator" not in roles
        and "System Manager" not in roles
    ):
        frappe.throw(
            "Only Implementation Managers can use this action.",
            frappe.PermissionError,
        )
    _im_resolved, im_identifiers, _ = resolve_im_for_session()
    if not im_identifiers:
        frappe.throw(
            "Could not resolve IM from your user profile.",
            frappe.ValidationError,
        )
    return _im_resolved, im_identifiers


def _pcc_im_allows_project(project_code, im_identifiers):
    if not project_code or not frappe.db.exists("Project Control Center", project_code):
        return False
    im_on = frappe.db.get_value(
        "Project Control Center", project_code, "implementation_manager"
    )
    if not im_on:
        return False
    return im_on in set(im_identifiers)


def _forecast_week_bounds(target_week):
    """Snap any date to (monday, sunday) of the week containing it."""
    wk = getdate(target_week)
    monday = add_days(wk, -wk.weekday())
    return monday, add_days(monday, 6)


def _validate_forecast_input(
    target_month, target_week, target_date, target_team, im_identifiers,
    require_week=True,
):
    """Normalise + validate the forecast an IM sets when dispatching PO lines.

    Returns ``(month, monday, day, team)`` — the first two as YYYY-MM-DD
    strings (month is always the 1st), ``day`` and ``team`` None when unset.

    Shared by every path that writes a forecast so the rules cannot drift
    between bulk dispatch, dummy create/update and internal work.

    The week is *snapped* to its Monday rather than rejected when it isn't
    one. ``_rollout_week_bounds`` already makes the server the authority on
    where a week starts, and snapping keeps the endpoint immune to a client
    that builds dates in local time and serialises them in UTC.

    Month membership is tested by OVERLAP, not containment: the picker offers
    every week that overlaps the chosen month, so a month's first week usually
    starts in the previous one. Requiring the Monday to land inside the month
    would make that option un-submittable in 6 months out of 7. The trade-off
    is that a straddling week is valid under either adjacent month — the
    picker's label ("W1 - Aug 31 to Sep 6") is what tells the IM which.
    """
    target_month = (target_month or "").strip()
    if not target_month:
        frappe.throw("target_month is required")
    try:
        if len(target_month) == 7:
            target_month = f"{target_month}-01"
        month_start = getdate(target_month).replace(day=1)
    except Exception:
        frappe.throw("Invalid target_month (expected YYYY-MM or YYYY-MM-DD)")

    target_week = (target_week or "").strip()
    if not target_week:
        if require_week:
            frappe.throw(
                "target_week is required - pick the forecast week for these lines"
            )
        return str(month_start), None, None, None
    try:
        monday, sunday = _forecast_week_bounds(target_week)
    except Exception:
        frappe.throw("Invalid target_week (expected YYYY-MM-DD)")

    month_end = get_last_day(month_start)
    if monday > month_end or sunday < month_start:
        frappe.throw(
            f"Target week {monday} - {sunday} does not fall in "
            f"{month_start.strftime('%B %Y')}"
        )

    day = None
    target_date = (target_date or "").strip()
    if target_date:
        try:
            day = getdate(target_date)
        except Exception:
            frappe.throw("Invalid target_date (expected YYYY-MM-DD)")
        if not (monday <= day <= sunday):
            frappe.throw(
                f"Target date {day} must fall inside the target week "
                f"({monday} - {sunday})"
            )

    team = None
    target_team = (target_team or "").strip()
    if target_team:
        row = frappe.db.get_value(
            "INET Team", target_team, ["status", "team_category", "im"], as_dict=True
        )
        if not row:
            frappe.throw(f"INET Team {target_team} not found")
        if (row.get("status") or "") != "Active":
            frappe.throw(f"Team {target_team} is not Active")
        if (row.get("team_category") or "Field Team") == "Backend Team":
            frappe.throw(
                "Backend teams are assigned through the sub-contract flow, "
                "not the forecast"
            )
        # A team with no IM is in every IM's pool, matching how the plan
        # modal's own team picker sources its options.
        if (row.get("im") or "") and row["im"] not in set(im_identifiers or []):
            frappe.throw(f"Team {target_team} does not belong to you")
        team = target_team

    return str(month_start), str(monday), (str(day) if day else None), team



@frappe.whitelist()
@frappe.whitelist()
def search_po_items(query=""):
    """Search Item master by item_code or item_name. Open to any logged-in user."""
    if not frappe.session.user or frappe.session.user == "Guest":
        frappe.throw("Not permitted", frappe.PermissionError)
    q = (query or "").strip()
    base_filters = [["disabled", "=", 0], ["item_group", "=", "Telecom Services"]]
    if q:
        rows = frappe.db.get_all(
            "Item",
            filters=base_filters + [["item_code", "like", f"%{q}%"]],
            fields=["item_code", "item_name", "description"],
            order_by="item_code asc",
            limit=30,
            ignore_permissions=True,
        )
        if not rows:
            rows = frappe.db.get_all(
                "Item",
                filters=base_filters + [["item_name", "like", f"%{q}%"]],
                fields=["item_code", "item_name", "description"],
                order_by="item_code asc",
                limit=30,
                ignore_permissions=True,
            )
    else:
        rows = frappe.db.get_all(
            "Item",
            filters=base_filters,
            fields=["item_code", "item_name", "description"],
            order_by="item_code asc",
            limit=30,
            ignore_permissions=True,
        )
    return rows


@frappe.whitelist()
def create_im_dummy_po_dispatch(payload=None):
    """
    Dummy PO Dispatch: only project is required at create time.

    Placeholder DUID / item / qty are set; real details are applied in map_im_dummy_po_to_intake_line.

    payload: {"project_code": required, "target_month": optional "YYYY-MM" or
    "YYYY-MM-01". If provided, the dummy dispatch skips PO Intake and lands
    directly in My Dispatches under that month.}
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload)
    payload = payload or {}

    _im_resolved, im_identifiers = _require_inet_im_session()

    project_code = (payload.get("project_code") or "").strip()
    if not project_code:
        frappe.throw("project_code is required")
    if not _pcc_im_allows_project(project_code, im_identifiers):
        frappe.throw("You are not the Implementation Manager for this project.")

    target_month = (payload.get("target_month") or "").strip()
    if target_month:
        # Accept "YYYY-MM" or a full date — always store as first-of-month.
        try:
            if len(target_month) == 7:
                target_month = f"{target_month}-01"
            target_month = str(getdate(target_month).replace(day=1))
        except Exception:
            frappe.throw("Invalid target_month (expected YYYY-MM or YYYY-MM-DD)")

    # Optional manager_remark — shown to field users on the plan card /
    # execution form (PO Dispatch.manager_remark already flows through).
    manager_remark = (payload.get("manager_remark") or payload.get("note") or "").strip()

    # Optional item_code — IM picks the activity item up-front.
    # Description: pulled from Item master when item_code given; otherwise
    # caller may supply a free-text description.
    item_code_input = (payload.get("item_code") or "").strip()
    item_code_val = None
    item_description_val = (payload.get("item_description") or "").strip()
    if item_code_input:
        if not frappe.db.exists("Item", item_code_input):
            frappe.throw(frappe._(f"Item {item_code_input} not found"))
        item_code_val = item_code_input
        master_desc = (frappe.db.get_value("Item", item_code_input, "description") or "").strip()
        if master_desc:
            item_description_val = master_desc

    # Optional DUID — IM may pick a real DUID Master row up-front, type a
    # known DUID code directly (auto-created if new), or leave blank for a
    # DUMMY-* placeholder that the map step replaces later.
    requested_site_code = (payload.get("site_code") or "").strip()
    site_code = None
    site_name = None
    center_area = None
    if requested_site_code:
        if frappe.db.exists("DUID Master", requested_site_code):
            d = frappe.db.get_value(
                "DUID Master", requested_site_code,
                ["site_name", "center_area"], as_dict=True,
            ) or {}
            site_code = requested_site_code
            site_name = d.get("site_name") or requested_site_code
            center_area = d.get("center_area")
        else:
            # Auto-create a DUID Master entry for the typed code.
            ok_duid, err_duid = ensure_duid_master(requested_site_code, site_name=requested_site_code)
            if not ok_duid:
                frappe.throw(err_duid or f"Could not create DUID Master for {requested_site_code}")
            site_code = requested_site_code
            site_name = requested_site_code
    else:
        for _attempt in range(40):
            candidate = f"DUMMY-{frappe.generate_hash(length=14)}"
            if not frappe.db.exists("DUID Master", candidate):
                site_code = candidate
                break
        if not site_code:
            frappe.throw("Could not allocate a placeholder DUID — retry.")
        site_name = "Pending — map to PO line"
        ok_duid, err_duid = ensure_duid_master(site_code, site_name=site_name, center_area=None)
        if not ok_duid:
            frappe.throw(err_duid or f"Could not create DUID Master for {site_code}")

    customer = frappe.db.get_value("Project Control Center", project_code, "customer")

    # item_code is a Link to Item — leaving it blank avoids tripping the
    # LinkValidationError. The map-to-intake-line step fills the real item.
    item_description = ""
    qty = flt(1)
    rate = flt(0)
    line_amount = flt(0)

    # Placeholder PO until map: DUMMY-yymmdd-XXXXXX (6 hex) → short POID e.g. DUMMY-260416-A3B4C5-1
    dt = now_datetime()
    for _attempt in range(30):
        po_no = f"DUMMY-{dt.strftime('%y%m%d')}-{frappe.generate_hash(length=6).upper()}"
        if not frappe.db.exists("PO Dispatch", {"po_no": po_no}):
            break
    else:
        frappe.throw("Could not allocate a unique dummy PO number — retry.")

    poid = _make_poid(po_no, 1, None)

    doc = frappe.new_doc("PO Dispatch")
    doc.project_code = project_code
    doc.customer = customer
    doc.im = _im_resolved
    doc.po_no = po_no
    doc.po_line_no = 1
    if item_code_val:
        doc.item_code = item_code_val
    if item_description_val:
        doc.item_description = item_description_val
    doc.qty = qty
    doc.rate = rate
    doc.line_amount = line_amount
    doc.site_code = site_code
    doc.site_name = site_name
    doc.center_area = center_area
    doc.region_type = region_type_from_center_area(center_area)
    doc.planning_mode = "Plan"
    doc.dispatch_status = "Dispatched"
    doc.dispatch_mode = "Manual"
    if manager_remark and frappe.db.has_column("PO Dispatch", "manager_remark"):
        doc.manager_remark = manager_remark[:8000]
    if target_month and frappe.db.has_column("PO Dispatch", "target_month"):
        doc.target_month = target_month
    if frappe.db.has_column("PO Dispatch", "is_dummy_po"):
        doc.is_dummy_po = 1

    final_name = _insert_po_dispatch_with_poid(doc, poid)
    stamp = {}
    if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
        # Store the business-visible POID (DUMMY-YYMMDD-XXXXXX-1), not the
        # doctype name (SYS-YYYY-NNNNN). The Dummy POID column everywhere
        # shows this value verbatim.
        stamp["original_dummy_poid"] = poid
    if frappe.db.has_column("PO Dispatch", "was_dummy_po"):
        stamp["was_dummy_po"] = 1
    if stamp:
        frappe.db.set_value("PO Dispatch", final_name, stamp, update_modified=False)
    frappe.db.commit()
    return {"name": final_name, "po_no": po_no, "poid": poid}


@frappe.whitelist()
def update_im_dummy_po_dispatch(payload=None):
    """
    Edit an OPEN (unmapped) dummy PO Dispatch's placeholder details —
    project, target month, item, DUID, note — before mapping it to a real
    PO line. IM-only, own dummy only, same field validation as
    create_im_dummy_po_dispatch (this is deliberately the same shape:
    the IM re-submits the full form, not a sparse patch).

    Needed because map_im_dummy_po_to_intake_line requires the dummy's
    project_code to exactly match the target PO line's project — a dummy
    created with the wrong project (or DUID/item, entered before the real
    PO details were known) could never be mapped without this, since there
    was previously no way to fix those fields on an existing dummy.

    payload: {"dummy_po_dispatch": required, "project_code": required,
    "target_month", "site_code", "item_code", "item_description",
    "manager_remark": all optional, same meaning as create}.
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload)
    payload = payload or {}

    dummy_name = (payload.get("dummy_po_dispatch") or "").strip()
    if not dummy_name:
        frappe.throw("dummy_po_dispatch is required")

    _im_resolved, im_identifiers = _require_inet_im_session()

    pd = frappe.db.get_value(
        "PO Dispatch", dummy_name, ["im", "is_dummy_po"], as_dict=True
    )
    if not pd:
        frappe.throw("PO Dispatch not found.")
    if pd.im not in set(im_identifiers):
        frappe.throw("Not permitted for this dispatch.")
    if frappe.db.has_column("PO Dispatch", "is_dummy_po") and not cint(pd.is_dummy_po):
        frappe.throw("This dispatch is not an open dummy PO — it has already been mapped.")

    project_code = (payload.get("project_code") or "").strip()
    if not project_code:
        frappe.throw("project_code is required")
    if not _pcc_im_allows_project(project_code, im_identifiers):
        frappe.throw("You are not the Implementation Manager for this project.")

    target_month = (payload.get("target_month") or "").strip()
    if target_month:
        try:
            if len(target_month) == 7:
                target_month = f"{target_month}-01"
            target_month = str(getdate(target_month).replace(day=1))
        except Exception:
            frappe.throw("Invalid target_month (expected YYYY-MM or YYYY-MM-DD)")

    manager_remark = (payload.get("manager_remark") or payload.get("note") or "").strip()

    item_code_input = (payload.get("item_code") or "").strip()
    item_code_val = None
    item_description_val = (payload.get("item_description") or "").strip()
    if item_code_input:
        if not frappe.db.exists("Item", item_code_input):
            frappe.throw(frappe._(f"Item {item_code_input} not found"))
        item_code_val = item_code_input
        master_desc = (frappe.db.get_value("Item", item_code_input, "description") or "").strip()
        if master_desc:
            item_description_val = master_desc

    requested_site_code = (payload.get("site_code") or "").strip()
    site_code = None
    site_name = None
    center_area = None
    if requested_site_code:
        if frappe.db.exists("DUID Master", requested_site_code):
            d = frappe.db.get_value(
                "DUID Master", requested_site_code,
                ["site_name", "center_area"], as_dict=True,
            ) or {}
            site_code = requested_site_code
            site_name = d.get("site_name") or requested_site_code
            center_area = d.get("center_area")
        else:
            ok_duid, err_duid = ensure_duid_master(requested_site_code, site_name=requested_site_code)
            if not ok_duid:
                frappe.throw(err_duid or f"Could not create DUID Master for {requested_site_code}")
            site_code = requested_site_code
            site_name = requested_site_code
        # Leaves the dummy's OLD auto-generated DUID Master placeholder row
        # in place, unlinked — same "don't force-clean orphaned auxiliary
        # records" convention already used elsewhere in this codebase.

    updates = {
        "project_code": project_code,
        "customer": frappe.db.get_value("Project Control Center", project_code, "customer"),
        "item_code": item_code_val,
        "item_description": item_description_val,
    }
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        updates["manager_remark"] = manager_remark[:8000]
    if frappe.db.has_column("PO Dispatch", "target_month"):
        updates["target_month"] = target_month or None
    if site_code:
        updates["site_code"] = site_code
        updates["site_name"] = site_name
        updates["center_area"] = center_area
        updates["region_type"] = region_type_from_center_area(center_area)

    frappe.db.set_value("PO Dispatch", dummy_name, updates, update_modified=True)
    frappe.db.commit()
    return {"name": dummy_name}


INTERNAL_WORK_ITEM_GROUP = "Internal Work"


def _ensure_internal_work_item_group():
    """Get-or-create the leaf Item Group that separates internal-work items."""
    if frappe.db.exists("Item Group", INTERNAL_WORK_ITEM_GROUP):
        return INTERNAL_WORK_ITEM_GROUP
    parent = (
        frappe.db.get_value("Item Group", {"is_group": 1}, "name")
        or frappe.db.get_value("Item Group", "All Item Groups", "name")
    )
    ig = frappe.new_doc("Item Group")
    ig.item_group_name = INTERNAL_WORK_ITEM_GROUP
    ig.is_group = 0
    if parent:
        ig.parent_item_group = parent
    ig.insert(ignore_permissions=True)
    frappe.db.commit()
    return INTERNAL_WORK_ITEM_GROUP


def _is_internal_dispatch(name):
    if not name or not frappe.db.has_column("PO Dispatch", "is_internal_work"):
        return False
    return bool(cint(frappe.db.get_value("PO Dispatch", name, "is_internal_work") or 0))


@frappe.whitelist()
def search_internal_work_items(query=""):
    """Search Items in the Internal Work group (IM internal-work modal picker)."""
    if not frappe.session.user or frappe.session.user == "Guest":
        frappe.throw("Not permitted", frappe.PermissionError)
    q = (query or "").strip()
    base_filters = [["disabled", "=", 0], ["item_group", "=", INTERNAL_WORK_ITEM_GROUP]]
    filters = base_filters + ([["item_name", "like", f"%{q}%"]] if q else [])
    rows = frappe.db.get_all(
        "Item",
        filters=filters,
        fields=["item_code", "item_name", "description", "activity_type"],
        order_by="item_name asc",
        limit=30,
        ignore_permissions=True,
    )
    if q and not rows:
        rows = frappe.db.get_all(
            "Item",
            filters=base_filters + [["item_code", "like", f"%{q}%"]],
            fields=["item_code", "item_name", "description"],
            order_by="item_name asc",
            limit=30,
            ignore_permissions=True,
        )
    return rows


@frappe.whitelist()
def add_internal_work_item(item_name, description=None, activity_type=None):
    """IM adds a new internal-work item (Item in the Internal Work group)."""
    roles = set(frappe.get_roles(frappe.session.user))
    if not roles & {"INET IM", "INET Admin", "System Manager", "Administrator"}:
        frappe.throw("Not permitted", frappe.PermissionError)
    name = (item_name or "").strip()
    if not name:
        frappe.throw("item_name is required")
    description = (description or "").strip()
    activity_type = (activity_type or "").strip()
    if activity_type and not frappe.db.exists("Activity Type", activity_type):
        frappe.throw(f"Activity Type not found: {activity_type}")
    group = _ensure_internal_work_item_group()
    existing = frappe.db.get_value(
        "Item", {"item_name": name, "item_group": group}, "item_code"
    ) or (frappe.db.exists("Item", name) and frappe.db.get_value("Item", name, "item_group") == group and name)
    if existing:
        return {"item_code": existing, "item_name": name}
    if frappe.db.exists("Item", name):
        frappe.throw(f"An Item named {name} already exists outside the {group} group")
    uom = frappe.db.get_single_value("Stock Settings", "stock_uom") or "Nos"
    it = frappe.new_doc("Item")
    it.item_code = name[:140]
    it.item_name = name[:140]
    it.item_group = group
    it.stock_uom = uom
    if description:
        it.description = description[:2000]
    if activity_type and hasattr(it, "activity_type"):
        it.activity_type = activity_type
    if hasattr(it, "is_stock_item"):
        it.is_stock_item = 0
    it.insert(ignore_permissions=True)
    frappe.db.commit()
    return {
        "item_code": it.item_code, "item_name": it.item_name,
        "description": it.description, "activity_type": getattr(it, "activity_type", None),
    }


@frappe.whitelist()
def create_internal_work(payload=None):
    """
    Internal (non-POID) work assigned by an IM: travel, oil clearance, etc.

    No PO, no DUID, no project, no revenue — the row exists only so the standard
    Rollout Plan → Daily Execution chain can run. Never mappable to a PO line and
    never produces a Work Done record.

    payload: {
        work_type: "Domain" | "General",
        domain: Project Domain name (required when work_type == "Domain"),
        item_code: Item in the Internal Work group (required),
        description: optional free text,
        manager_remark: optional note shown to the field team,
        target_month: optional "YYYY-MM" / "YYYY-MM-DD" (defaults to current month),
    }
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload)
    payload = payload or {}

    _im_resolved, _im_identifiers = _require_inet_im_session()

    work_type = (payload.get("work_type") or "").strip()
    if work_type not in ("Domain", "General"):
        frappe.throw("work_type must be Domain or General")

    domain = (payload.get("domain") or "").strip()
    if work_type == "Domain":
        if not domain:
            frappe.throw("domain is required for Domain work")
        if not frappe.db.exists("Project Domain", domain):
            frappe.throw(f"Project Domain not found: {domain}")
    else:
        domain = ""

    item_code = (payload.get("item_code") or "").strip()
    if not item_code:
        frappe.throw("item_code is required")
    item_row = frappe.db.get_value(
        "Item", item_code, ["item_name", "item_group"], as_dict=True
    )
    if not item_row:
        frappe.throw(f"Item {item_code} not found")
    if item_row.item_group != INTERNAL_WORK_ITEM_GROUP:
        frappe.throw(f"Item {item_code} is not in the {INTERNAL_WORK_ITEM_GROUP} group")
    item_label = item_row.item_name or item_code

    description = (payload.get("description") or "").strip()
    manager_remark = (payload.get("manager_remark") or payload.get("note") or "").strip()

    target_month = (payload.get("target_month") or "").strip()
    try:
        if target_month:
            if len(target_month) == 7:
                target_month = f"{target_month}-01"
            target_month = str(getdate(target_month).replace(day=1))
        else:
            # Always set: My Dispatches filters has_target_month == "yes".
            target_month = str(getdate(nowdate()).replace(day=1))
    except Exception:
        frappe.throw("Invalid target_month (expected YYYY-MM or YYYY-MM-DD)")

    from frappe.model.naming import make_autoname
    poid = make_autoname("INT-.#####")

    doc = frappe.new_doc("PO Dispatch")
    doc.im = _im_resolved
    doc.item_code = item_code
    doc.item_description = description
    doc.qty = flt(1)
    doc.rate = flt(0)
    doc.line_amount = flt(0)
    doc.site_name = item_label
    doc.planning_mode = "Plan"
    doc.dispatch_status = "Dispatched"
    doc.dispatch_mode = "Manual"
    doc.is_internal_work = 1
    doc.internal_work_type = work_type
    doc.internal_domain = domain
    if manager_remark and frappe.db.has_column("PO Dispatch", "manager_remark"):
        doc.manager_remark = manager_remark[:8000]
    doc.target_month = target_month

    final_name = _insert_po_dispatch_with_poid(doc, poid)
    frappe.db.commit()
    return {"name": final_name, "poid": poid}


def _po_dispatch_portal_pf_active(pf):
    if not pf:
        return False
    if (pf.get("search") or pf.get("q") or "").strip():
        return True
    cf = pf.get("column_filters")
    if isinstance(cf, str):
        try:
            cf = frappe.parse_json(cf)
        except Exception:
            cf = None
    if isinstance(cf, dict) and any(_column_filter_is_active(v) for v in cf.values()):
        return True
    for k in (
        "project_code",
        "site_code",
        "team",
        "im",
        "from_date",
        "to_date",
        "dispatch_mode",
        "dummy_preset",
        "has_target_month",
        "has_target_week",
        "domain",
        "dispatch_status",
        "direct_close_only",
    ):
        v = pf.get(k)
        if v is None or v == "":
            continue
        if k == "dummy_preset" and str(v).strip().lower() == "all":
            continue
        if k in ("has_target_month", "has_target_week") and str(v).strip().lower() in ("", "any"):
            continue
        return True
    # "include" alone doesn't need the SQL path (get_list default already
    # includes nothing extra to filter); "only" is an active filter.
    if (pf.get("internal_preset") or "").strip().lower() == "only":
        return True
    return False


def _po_dispatch_portal_sql_where(filters, pf, fields):
    """Build WHERE clauses + bind values for portal-filtered PO Dispatch queries."""
    base_fl = (
        [[k, "=", v] for k, v in filters.items()]
        if isinstance(filters, dict)
        else [list(x) for x in (filters or [])]
    )
    for key in ("project_code", "site_code", "team"):
        vals = _ensure_list(pf.get(key))
        if vals:
            base_fl.append([key, "in" if len(vals) > 1 else "=", vals if len(vals) > 1 else vals[0]])
    im_vals = _ensure_list(pf.get("im"))
    if im_vals and "im" in fields:
        base_fl.append(["im", "in" if len(im_vals) > 1 else "=", im_vals if len(im_vals) > 1 else im_vals[0]])
    if pf.get("dispatch_mode"):
        base_fl.append(["dispatch_mode", "=", (pf.get("dispatch_mode") or "").strip()])
    if pf.get("from_date") and pf.get("to_date"):
        base_fl.append(["target_month", "between", [pf["from_date"], pf["to_date"]]])
    elif pf.get("from_date"):
        base_fl.append(["target_month", ">=", pf["from_date"]])
    elif pf.get("to_date"):
        base_fl.append(["target_month", "<=", pf["to_date"]])

    wheres = ["1=1"]
    params = []
    for cond in base_fl:
        if not isinstance(cond, (list, tuple)) or len(cond) != 3:
            continue
        k, op, v = cond[0], cond[1], cond[2]
        if k not in fields:
            continue
        op_l = str(op).lower()
        # A toolbar filter can ask for blanks (FILTER_BLANK) on its own or
        # alongside real values — "IM = Rafeeq OR no IM at all" is one
        # selection. Route both through _sql_in_or_eq so the sentinel behaves
        # identically here and on every other page's filters.
        if op_l in ("=", "in"):
            vlist = list(v) if isinstance(v, (list, tuple)) else [v]
            if FILTER_BLANK in vlist:
                c, p = _sql_in_or_eq(f"`{k}`", vlist)
                if c:
                    wheres.append(c)
                    params.extend(p)
                continue
        if op_l == "=":
            wheres.append(f"`{k}` = %s")
            params.append(v)
        elif op_l == "in" and isinstance(v, (list, tuple)) and v:
            ph = ", ".join(["%s"] * len(v))
            wheres.append(f"`{k}` IN ({ph})")
            params.extend(list(v))
        elif op_l == "not in" and isinstance(v, (list, tuple)) and v:
            ph = ", ".join(["%s"] * len(v))
            wheres.append(f"IFNULL(`{k}`, '') NOT IN ({ph})")
            params.extend(list(v))
        elif op_l == "between" and isinstance(v, (list, tuple)) and len(v) == 2:
            wheres.append(f"`{k}` BETWEEN %s AND %s")
            params.extend([v[0], v[1]])
        elif op_l in (">=", "<=", ">", "<"):
            wheres.append(f"`{k}` {op_l} %s")
            params.append(v)

    # "Domain" (Project Control Center's project_domain, resolved via
    # project_code — this single-table query has no join to it) and
    # "Status" (dispatch_status) — dedicated toolbar filters on the IM PO
    # Intake page's Dummy/Overview tabs, previously applied only to already-
    # loaded rows client-side.
    domain_vals = _ensure_list(pf.get("domain"))
    if domain_vals and "project_code" in fields:
        ph_dom = ", ".join(["%s"] * len(domain_vals))
        wheres.append(
            f"COALESCE(NULLIF(`tabPO Dispatch`.`project_domain`, ''), "
            f"(SELECT project_domain FROM `tabProject Control Center` "
            f"WHERE name = `tabPO Dispatch`.`project_code`)) IN ({ph_dom})"
        )
        params.extend(domain_vals)
    status_vals_pd = _ensure_list(pf.get("dispatch_status"))
    if status_vals_pd and "dispatch_status" in fields:
        ph_st = ", ".join(["%s"] * len(status_vals_pd))
        wheres.append(f"IFNULL(`dispatch_status`,'') IN ({ph_st})")
        params.extend(status_vals_pd)

    # "Direct Close" toggle on IMPOIntake.jsx's Overview tab (previously
    # applied only to already-loaded rows client-side).
    if str(pf.get("direct_close_only") or "").strip().lower() in ("1", "true", "yes") and "direct_close_by" in fields:
        wheres.append("IFNULL(`direct_close_by`,'') != ''")

    dummy_preset = (pf.get("dummy_preset") or "all").strip().lower()
    if dummy_preset == "dummy" and "is_dummy_po" in fields:
        wheres.append("IFNULL(`is_dummy_po`, 0) = 1")
    elif dummy_preset == "standard" and "is_dummy_po" in fields:
        wheres.append("(IFNULL(`is_dummy_po`, 0) = 0 OR `is_dummy_po` IS NULL)")
    elif dummy_preset == "mapped_dummy":
        wheres.append(
            "((IFNULL(was_dummy_po, 0) = 1 AND IFNULL(is_dummy_po, 0) = 0) OR "
            "(IFNULL(original_dummy_poid, '') != '' AND IFNULL(is_dummy_po, 0) = 0"
            " AND TRIM(original_dummy_poid) != IFNULL(TRIM(name), '')))"
        )
    elif dummy_preset == "dummy_any":
        # Both open dummies (is_dummy_po=1) AND mapped-from-dummy rows
        wheres.append(
            "(IFNULL(is_dummy_po, 0) = 1 OR IFNULL(was_dummy_po, 0) = 1"
            " OR (IFNULL(original_dummy_poid, '') != ''"
            " AND TRIM(original_dummy_poid) != IFNULL(TRIM(name), '')))"
        )

    # internal_preset: "exclude" (DEFAULT — internal work is invisible to PO
    # tracking/finance surfaces), "include" (planning views), "only".
    internal_preset = (pf.get("internal_preset") or "exclude").strip().lower()
    if "is_internal_work" in fields:
        if internal_preset == "only":
            wheres.append("IFNULL(`is_internal_work`, 0) = 1")
        elif internal_preset != "include":
            wheres.append("IFNULL(`is_internal_work`, 0) = 0")

    # has_target_month: "yes" (target_month set), "no" (null/empty), "any" / "" (no filter)
    htm = (pf.get("has_target_month") or "").strip().lower()
    if htm == "yes" and "target_month" in fields:
        wheres.append("`target_month` IS NOT NULL AND `target_month` != ''")
        # IM Rollout Planning view: never show dispatches that are already
        # done operationally and beyond — once PIC has taken over the
        # commercial side (Partially Submitted/Submitted/Partially Closed/
        # Closed), there's no more rollout planning to be done on it either.
        if "dispatch_status" in fields:
            wheres.append(
                "IFNULL(`dispatch_status`, 'Pending') NOT IN "
                "('Partially Submitted', 'Submitted', 'Partially Closed', 'Closed', 'Cancelled')"
            )
    elif htm == "no" and "target_month" in fields:
        wheres.append("(`target_month` IS NULL OR `target_month` = '')")

    # has_target_week: the forecast gap. Separate from has_target_month
    # because a line promoted by the PM dispatch path gets a month but never
    # a week, so "has a month" and "has a week" are genuinely different sets.
    htw = (pf.get("has_target_week") or "").strip().lower()
    if htw == "yes" and "target_week" in fields:
        wheres.append("`target_week` IS NOT NULL AND `target_week` != ''")
    elif htw == "no" and "target_week" in fields:
        wheres.append("(`target_week` IS NULL OR `target_week` = '')")

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale (each column matched independently and ANDed, not blended
    # into the wide `search` clause below).
    col_filter_map = PO_DISPATCH_COL_FILTER_MAP
    # "domain"/"huawei_im"/"activity_type" are Python post-query enrichments
    # (see _enrich_with_project_fields / the activity_type special case
    # below) - matched here via correlated subquery so Manage Table filters
    # reach the full backend dataset too, not just the loaded page.
    # "ms1"/"ms2" are computed badges - client-side only, no backend filter.
    # "plan_status"/"plan_team"/"plan_date"/"issue_category"/"issue_flag"
    # (IMPOIntake.jsx's Overview/Dummy tabs) come from a separate bulk call
    # (getDispatchPlanSummaries -> Rollout Plan/Daily Execution), not this
    # query - client-side only until/unless that's joined in here.
    # "im" is handled specially below (matches the raw code AND the joined
    # IM Master full name, since different pages show either/both).
    column_filters = pf.get("column_filters")
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style filter: an explicit set of values and/or blanks,
            # rather than a substring. Must be handled BEFORE
            # _sql_like_pattern() below, which does (term or "").strip() and
            # therefore raises AttributeError on a dict.
            #
            # NOTE for anyone extending this to another page: the three other
            # col_filter_map loops in this file (export_po_dump,
            # list_po_intake_lines, list_execution_monitor_rows) have no such
            # guard and will 500 on a dict value. Check which backend function
            # consumes a page's column_filters before opting one of its
            # columns into the Excel filter.
            if isinstance(raw_val, dict):
                clause, cparams = excel_filter_clause(
                    _po_dispatch_excel_expr(col_key, fields), raw_val
                )
                if clause:
                    wheres.append(clause)
                    params.extend(cparams)
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            if col_key == "im" and "im" in fields:
                wheres.append(
                    "(IFNULL(`im`,'') LIKE %s OR `im` IN "
                    "(SELECT name FROM `tabIM Master` WHERE full_name LIKE %s))"
                )
                params.extend([pat, pat])
                continue
            # Dummy POs with no item_description show the manager's remark
            # instead (see _apply_dummy_description) — mirror that fallback
            # so filtering "Description" matches what the column displays.
            if col_key == "description" and "item_description" in fields and "is_dummy_po" in fields and "manager_remark" in fields:
                wheres.append(
                    "(CASE WHEN IFNULL(`is_dummy_po`,0) = 1 AND IFNULL(`item_description`,'') = '' "
                    "THEN IFNULL(`manager_remark`,'') ELSE IFNULL(`item_description`,'') END) LIKE %s"
                )
                params.append(pat)
                continue
            if col_key == "activity_type" and "item_code" in fields:
                # tabItem has its own item_code column, so an unqualified
                # `item_code` inside the subquery resolves to tabItem's own
                # column instead of correlating to the outer row - qualify
                # with the real (unaliased) outer table name to fix that.
                wheres.append(
                    "IFNULL((SELECT activity_type FROM `tabItem` "
                    "WHERE name = `tabPO Dispatch`.`item_code`), '') LIKE %s"
                )
                params.append(pat)
                continue
            if col_key == "domain" and "project_code" in fields:
                # tabProject Control Center also has its own project_code
                # column, so this needs the same outer-qualification as the
                # activity_type case above to correlate correctly.
                wheres.append(
                    "COALESCE(NULLIF(`tabPO Dispatch`.`project_domain`, ''), "
                    "(SELECT project_domain FROM `tabProject Control Center` "
                    "WHERE name = `tabPO Dispatch`.`project_code`), '') LIKE %s"
                )
                params.append(pat)
                continue
            if col_key == "huawei_im" and "project_code" in fields:
                wheres.append(
                    "IFNULL((SELECT huawei_im FROM `tabProject Control Center` "
                    "WHERE name = `tabPO Dispatch`.`project_code`), '') LIKE %s"
                )
                params.append(pat)
                continue
            if col_key == "billing_status" and "pic_status" in fields:
                # Mirrors billingStatusFromPicStatus() in IMPOIntake.jsx - the
                # Overview tab's "Billing Status" column is a computed label,
                # not a raw column, so replicate that mapping here.
                wheres.append(
                    "(CASE WHEN `pic_status` IN ('Commercial Invoice Closed', 'PO Line Canceled') THEN 'Closed' "
                    "WHEN `pic_status` IN ('Commercial Invoice Submitted', 'Ready for Invoice', 'Under I-BUY', 'Under ISDP') THEN 'Invoiced' "
                    "WHEN IFNULL(`pic_status`, '') != '' THEN 'Pending' ELSE '' END) LIKE %s"
                )
                params.append(pat)
                continue
            col = col_filter_map.get(col_key)
            if not col or col not in fields:
                continue
            if col in ("qty", "rate", "line_amount", "modified", "creation"):
                wheres.append(f"CAST(`{col}` AS CHAR) LIKE %s")
            else:
                wheres.append(f"IFNULL(`{col}`, '') LIKE %s")
            params.append(pat)

    tokens = _sql_like_tokens(pf.get("search") or pf.get("q") or "")
    if tokens:
        like_cols = [
            c
            for c in (
                "name",
                "poid",
                "po_no",
                "item_code",
                "item_description",
                "dispatch_mode",
                "project_code",
                "site_code",
                "im",
                "center_area",
                "region_type",
                "original_dummy_poid",
            )
            if c in fields
        ]
        if like_cols:
            # Every token must be found in SOME column (each token ORs across
            # columns; tokens themselves are ANDed together) — a multi-word
            # search only matches rows containing all the words, not rows
            # that merely contain any one of them. Without this, searching a
            # DUID name with its own internal space (e.g. "...M24_rack Fuse
            # Upgrade") pulls in every unrelated row that happens to contain
            # a generic word like "Fuse" or "Upgrade" anywhere.
            ands = []
            for tok in tokens:
                ands.append("(" + " OR ".join(f"IFNULL(`{c}`, '') LIKE %s" for c in like_cols) + ")")
                params.extend([tok] * len(like_cols))
            clause = "(" + " AND ".join(ands) + ")"

            # Bulk-paste fallback: pasting several *distinct* exact POID/DUID
            # values (one per row) can never satisfy the AND-across-tokens
            # clause above, since no single row contains all of them at once.
            # OR in an exact-IN match on the identifying columns so each
            # pasted value can match its own row. Uses whole-VALUE tokens
            # (hard separators only — newline/tab/comma/semicolon/pipe, not
            # a plain space) so a pasted value that itself has an internal
            # space (e.g. a DUID) survives as one token instead of being
            # shredded into unrelated words, which would silently drop it
            # from a batch paste containing other, space-free values.
            value_tokens = _sql_value_tokens(pf.get("search") or pf.get("q") or "")
            exact_cols = [c for c in ("poid", "site_code", "name") if c in fields]
            if exact_cols and len(value_tokens) > 1:
                ph = ", ".join(["%s"] * len(value_tokens))
                exact_ors = " OR ".join(f"IFNULL(`{c}`, '') IN ({ph})" for c in exact_cols)
                clause = f"({clause} OR ({exact_ors}))"
                for _ in exact_cols:
                    params.extend(value_tokens)

            wheres.append(clause)

    return wheres, params


def _strip_excluded_column(pf, exclude_column):
    """Drop a column's own selection from the filters used for its option list.

    Excel keeps the column you are editing out of its own cascade, so you can
    still widen a selection after applying it.
    """
    if not exclude_column:
        return pf
    cf = pf.get("column_filters")
    if isinstance(cf, str):
        try:
            cf = frappe.parse_json(cf)
        except Exception:
            cf = None
    if isinstance(cf, dict) and exclude_column in cf:
        pf = dict(pf)
        pf["column_filters"] = {k: v for k, v in cf.items() if k != exclude_column}
    return pf


@frappe.whitelist()
def get_column_filter_options(source, col_key, bucket=None, filters=None, portal_filters=None,
                              exclude_column=None, search=None, limit=500, extra=None):
    """Excel-filter option list for any registered source.

    One endpoint for every page: ``source`` picks which table/query the values
    come from, and each source reuses the SAME where-clause its row list uses,
    so a dropdown can never offer a value that returns no rows.

    Sources are registered in EXCEL_OPTION_SOURCES. To add one, give it a
    builder that returns excel_options_from_query(...) using that query's own
    FROM/WHERE — see _excel_options_po_intake_line for the pattern where the
    WHERE only exists inside the list function.
    """
    # supported=False means the backend has no expression for this column, so
    # neither a value list NOR a substring filter can work — the UI must say
    # that rather than offering a filter that silently does nothing.
    empty = {"values": [], "has_blanks": False, "total": 0, "supported": False}
    builder = EXCEL_OPTION_SOURCES.get(source)
    if not builder or not isinstance(col_key, str) or not col_key:
        return empty

    cache_key = _excel_options_cache_key(
        frappe.session.user, source, col_key, bucket,
        filters, portal_filters, exclude_column, search, limit, extra,
    )
    # expires=True is required, not cosmetic: without it get_value() memoises
    # the miss as None into frappe.local.cache, while set_value(expires_in_sec)
    # deliberately skips that same local cache — so every later lookup in the
    # process keeps returning the stale None and the cache never hits.
    cached = frappe.cache().get_value(cache_key, expires=True)
    if cached is not None:
        return cached

    if isinstance(filters, str):
        filters = frappe.parse_json(filters) if filters else {}
    filters = filters or {}
    pf = _strip_excluded_column(_portal_filters_dict(portal_filters), exclude_column)
    if isinstance(extra, str):
        try:
            extra = frappe.parse_json(extra) if extra else {}
        except Exception:
            extra = {}
    extra = extra if isinstance(extra, dict) else {}

    result = builder(col_key, filters, pf, bucket, search, limit, extra) or empty
    frappe.cache().set_value(cache_key, result, expires_in_sec=EXCEL_OPTIONS_CACHE_TTL)
    return result


