def _summary_projects(pf, extra):
    """Project Control Center headline figures.

    The projects pages filter through the ORM rather than raw SQL, so this
    rebuilds the same predicates as WHERE fragments. Every value below is
    parameterised — only the column names are inlined, and those come from a
    fixed map, never from the caller.
    """
    wheres, params = ["1=1"], []
    _map = {
        "status": "project_status", "domain": "project_domain",
        "area": "center_area", "huawei_im": "huawei_im",
        "implementation_manager": "implementation_manager",
    }
    for key, col in _map.items():
        val = pf.get(key) or extra.get(key)
        if not val:
            continue
        vals = val if isinstance(val, (list, tuple)) else [val]
        vals = [str(v) for v in vals if str(v or "").strip()]
        if not vals:
            continue
        wheres.append(f"`{col}` IN ({', '.join(['%s'] * len(vals))})")
        params.extend(vals)
    search = (pf.get("search") or "").strip()
    if search:
        like = f"%{search}%"
        wheres.append("(`project_code` LIKE %s OR `project_name` LIKE %s OR `customer` LIKE %s)")
        params.extend([like, like, like])
    have = set(frappe.db.get_table_columns("Project Control Center"))
    metrics = [{"key": "projects", "label": "Projects", "agg": "count"}]
    if "project_status" in have:
        metrics.append({"key": "active", "label": "Active", "agg": "count_if",
                        "cond": "IFNULL(`project_status`,'') = 'Active'", "tone": "good"})
    if "project_domain" in have:
        metrics.append({"key": "domains", "label": "Domains", "agg": "count_distinct",
                        "expr": "NULLIF(IFNULL(`project_domain`,''), '')"})
    if "implementation_manager" in have:
        metrics.append({"key": "ims", "label": "IMs", "agg": "count_distinct",
                        "expr": "NULLIF(IFNULL(`implementation_manager`,''), '')"})
        metrics.append({"key": "no_im", "label": "No IM", "agg": "count_if",
                        "cond": "IFNULL(`implementation_manager`,'') = ''",
                        "tone": "warn", "hide_if_zero": True})
    # Budget used to show here (a dead field — nothing in the app writes
    # it, meaningless for a customer project). Replaced with real figures:
    # total contracted value and revenue actually realized, joined in via
    # per-project subqueries so the existing single-round-trip aggregate
    # shape (summary_from_query) still works unchanged.
    metrics.append({"key": "total_value", "label": "Total Value", "agg": "sum",
                    "expr": "IFNULL(`pcc_val`.`total_value`, 0)", "format": "money",
                    "tone": "good", "hide_if_zero": True})
    metrics.append({"key": "revenue", "label": "Revenue", "agg": "sum",
                    "expr": "IFNULL(`pcc_rev`.`revenue`, 0)", "format": "money",
                    "tone": "good", "hide_if_zero": True})
    # Subquery join columns are aliased away from "project_code" (pc_/pd_)
    # since Project Control Center has its own same-named column and the
    # existing WHERE fragments above reference it unqualified — a same-named
    # join column would make those ambiguous.
    from_sql = (
        "`tabProject Control Center` "
        "LEFT JOIN (SELECT project_code AS pc_val, SUM(line_amount) AS total_value "
        "FROM `tabPO Dispatch` WHERE IFNULL(is_internal_work, 0) = 0 "
        "GROUP BY project_code) pcc_val "
        "ON pcc_val.pc_val = `tabProject Control Center`.name "
        "LEFT JOIN (SELECT pd.project_code AS pc_rev, SUM(wd.revenue_sar) AS revenue "
        "FROM `tabWork Done` wd JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id "
        "GROUP BY pd.project_code) pcc_rev "
        "ON pcc_rev.pc_rev = `tabProject Control Center`.name"
    )
    return summary_from_query(from_sql, " AND ".join(wheres), params, metrics)


@frappe.whitelist()
def get_page_summary(source, portal_filters=None, extra=None):
    """Headline figures for one page, before (and regardless of) row loading.

    Answers "what is in this view?" from aggregates over the FULL filtered set,
    so the user does not have to raise the row limit to find out. Registered in
    SUMMARY_SOURCES; see summary_from_query() for the metric shape.
    """
    empty = {"metrics": [], "supported": False}
    builder = SUMMARY_SOURCES.get(source)
    if not builder:
        return empty

    cache_key = _excel_options_cache_key(
        frappe.session.user, "summary", source, portal_filters, extra,
    )
    # expires=True for the same reason as get_column_filter_options().
    cached = frappe.cache().get_value(cache_key, expires=True)
    if cached is not None:
        return cached

    pf = _portal_filters_dict(portal_filters)
    if isinstance(extra, str):
        try:
            extra = frappe.parse_json(extra) if extra else {}
        except Exception:
            extra = {}
    extra = extra if isinstance(extra, dict) else {}

    try:
        result = builder(pf, extra) or empty
        # A source whose list function fell through to its row path hands back
        # a list, not a summary. Don't cache that — it would pin the page to a
        # bad answer for the whole TTL, long after the source was fixed.
        if not isinstance(result, dict) or "metrics" not in result:
            return empty
    except Exception:
        # A summary is a convenience: never let a bad aggregate take the page
        # down with it. The strip just stays hidden.
        frappe.log_error(frappe.get_traceback(), f"get_page_summary({source})")
        return empty
    frappe.cache().set_value(cache_key, result, expires_in_sec=EXCEL_OPTIONS_CACHE_TTL)
    return result


def _summary_po_dispatch(pf, extra):
    """Headline figures for the PO Dispatch-backed pages.

    Rollout Planning, IM Dispatch and IM PO Intake scope their rows with TWO
    things: a portal dict AND an ORM-style filter list — and the second is
    where the IM scoping lives (``[["im", "=", imName]]``), along with each
    page's plan-scope status filter. They already keep the pair together for
    the column-filter dropdowns, so accept that same {portal, filters} shape
    here. Taking only the portal would count every IM's lines on a page that
    shows one IM's.
    """
    if isinstance(pf, dict) and ("portal" in pf or "filters" in pf):
        filters = pf.get("filters") or {}
        pf = _portal_filters_dict(pf.get("portal") or {})
    else:
        filters = extra.get("filters") or {}
    fields = list(frappe.db.get_table_columns("PO Dispatch"))
    wheres, params = _po_dispatch_portal_sql_where(filters, pf, fields)
    have = set(fields)
    metrics = [{"key": "lines", "label": "Lines", "agg": "count"}]
    if "site_code" in have:
        metrics.append({"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                        "expr": "NULLIF(IFNULL(`site_code`,''), '')"})
    if "line_amount" in have:
        metrics.append({"key": "value", "label": "Value", "agg": "sum",
                        "expr": "IFNULL(`line_amount`, 0)", "format": "money", "tone": "good"})
    if "dispatch_status" in have:
        _st = "IFNULL(`dispatch_status`,'')"
        metrics += [
            {"key": "pending", "label": "Pending", "agg": "count_if", "group": "Pipeline",
             "cond": f"{_st} = 'Pending'", "tone": "warn", "hide_if_zero": True,
             "hint": "Not planned out to a team yet"},
            {"key": "planned", "label": "Planned", "agg": "count_if", "group": "Pipeline",
             "cond": f"{_st} = 'Planned'", "tone": "info", "hide_if_zero": True},
            {"key": "dispatched", "label": "Dispatched", "agg": "count_if", "group": "Pipeline",
             "cond": f"{_st} = 'Dispatched'", "tone": "info", "hide_if_zero": True},
            {"key": "completed", "label": "Completed", "agg": "count_if", "group": "Pipeline",
             "cond": f"{_st} IN ('Completed','Partially Closed')", "tone": "good", "hide_if_zero": True},
            {"key": "closed", "label": "Closed", "agg": "count_if", "group": "Pipeline",
             "cond": f"{_st} = 'Closed'", "hide_if_zero": True},
            {"key": "cancelled", "label": "Cancelled", "agg": "count_if", "group": "Pipeline",
             "cond": f"{_st} = 'Cancelled'", "tone": "bad", "hide_if_zero": True},
        ]
    # Planning gaps a PM/IM can act on. Both are skipped when the view is
    # ALREADY scoped to that gap — a "No month" chip on PO Control's intake
    # tab (which shows exactly the lines with no month) just restates the
    # total, and a chip that always equals the total tells you nothing.
    scoped_by_month = str(pf.get("has_target_month") or "").strip().lower() in ("yes", "no")
    # `have` is PO Dispatch's own columns, so this tests `target_month` — it
    # read `dispatch_target_month` (a name only the PO-Intake-driven query
    # produces), which meant the chip never rendered on this source at all.
    if "target_month" in have and not scoped_by_month:
        metrics.append({"key": "no_month", "label": "No month", "agg": "count_if",
                        "group": "Gaps", "cond": "IFNULL(`target_month`,'') = ''",
                        "tone": "warn", "hide_if_zero": True,
                        "hint": "No target month set — cannot be scheduled"})
    scoped_by_week = str(pf.get("has_target_week") or "").strip().lower() in ("yes", "no")
    if "target_week" in have and not scoped_by_week:
        metrics.append({"key": "no_week", "label": "No week", "agg": "count_if",
                        "group": "Gaps", "cond": "IFNULL(`target_week`,'') = ''",
                        "tone": "warn", "hide_if_zero": True,
                        "hint": "No forecast week — invisible on the Weekly Forecast"})
    if "im" in have and not _has_im_filter(filters, pf):
        metrics.append({"key": "no_im", "label": "No IM", "agg": "count_if",
                        "group": "Gaps", "cond": "IFNULL(`im`,'') = ''",
                        "tone": "bad", "hide_if_zero": True,
                        "hint": "No Implementation Manager assigned"})
    # Dummy POIDs are a PO Control concern only — show the split when the page
    # is looking at them, and stay out of the way otherwise.
    dummy_preset = str(pf.get("dummy_preset") or "").strip()
    if dummy_preset in ("dummy_any", "mapped_dummy", "dummy") and "is_dummy_po" in have:
        metrics.append({"key": "dummy_open", "label": "Open", "agg": "count_if",
                        "group": "Dummy", "cond": "IFNULL(`is_dummy_po`, 0) = 1",
                        "tone": "warn", "hide_if_zero": True,
                        "hint": "Dummy POID not yet mapped to a real PO line"})
        if "was_dummy_po" in have:
            metrics.append({"key": "dummy_mapped", "label": "Mapped", "agg": "count_if",
                            "group": "Dummy", "tone": "good", "hide_if_zero": True,
                            "cond": "(IFNULL(`was_dummy_po`, 0) = 1 AND IFNULL(`is_dummy_po`, 0) = 0)"})
    return summary_from_query("`tabPO Dispatch`", " AND ".join(wheres), params, metrics)


def _has_im_filter(filters, pf):
    """True when the caller already scoped to specific IMs.

    An IM's own pages are scoped to them, so "No IM" there is always 0 —
    a permanently blank chip. Only the PM views, which span every IM, can
    actually have unassigned lines worth flagging.
    """
    if _ensure_list(pf.get("im")):
        return True
    if isinstance(filters, dict):
        return bool(filters.get("im"))
    for cond in (filters or []):
        if isinstance(cond, (list, tuple)) and len(cond) == 3 and cond[0] == "im":
            return True
    return False


def _excel_options_po_dispatch(col_key, filters, pf, bucket, search, limit, extra):
    fields = list(frappe.db.get_table_columns("PO Dispatch"))
    # col_key only ever selects among hardcoded expressions — no user input
    # reaches the SQL string.
    expr = _po_dispatch_excel_expr(col_key, fields)
    if not expr:
        return None
    base_col = PO_DISPATCH_COL_FILTER_MAP.get(col_key)
    if col_key in ("ms1", "ms2"):
        label_kind = "percent"
    elif base_col in ("line_amount", "rate"):
        label_kind = "money"
    elif base_col == "qty":
        label_kind = "qty"
    else:
        label_kind = (bucket or "").strip().lower() or None
    wheres, params = _po_dispatch_portal_sql_where(filters, pf, fields)
    return excel_options_from_query(
        "`tabPO Dispatch`", " AND ".join(wheres), params, expr,
        bucket=bucket, search=search, limit=limit, label_kind=label_kind,
    )


def _excel_options_po_intake_line(col_key, filters, pf, bucket, search, limit, extra):
    # The intake WHERE is built inside list_po_intake_lines and depends on its
    # `status` argument, so ask that function for the options rather than
    # duplicating (and risking drift from) its clause building.
    return list_po_intake_lines(
        status=extra.get("status") or "New",
        limit=1,
        portal_filters=pf,
        _options={
            "col_key": col_key, "bucket": bucket, "search": search, "limit": limit,
            "label_kind": (bucket or "").strip().lower() or None,
        },
    )


def _excel_options_via(fn, col_key, bucket, opt_search, opt_limit, **call_kwargs):
    """Ask a list function for its own column options.

    Every source below follows the same shape: the WHERE only exists inside
    the list function, so that function answers from its own fully-built
    wheres/params rather than anyone re-deriving them (which would let the
    option list drift from the rows).
    """
    return fn(
        _options={
            "col_key": col_key, "bucket": bucket, "search": opt_search, "limit": opt_limit,
            "label_kind": (bucket or "").strip().lower() or None,
        },
        **call_kwargs,
    )


