def _batch_inet_team_names(team_ids):
    ids = list({t for t in (team_ids or []) if t})
    if not ids:
        return {}
    out = {}
    for row in frappe.get_all(
        "INET Team",
        filters={"name": ["in", ids]},
        fields=["name", "team_name"],
        limit_page_length=len(ids) + 1,
    ):
        out[row.name] = row.team_name or row.name
    return out


@frappe.whitelist()
def get_team_options(team_type=None):
    """Return [{id, label}] for INET Teams. team_type: 'Backend Team' | 'Field Team' | None (all)."""
    filters = {}
    if team_type:
        filters["team_type"] = team_type
    rows = frappe.get_all(
        "INET Team",
        filters=filters,
        fields=["name", "team_name"],
        order_by="team_name asc",
        limit_page_length=500,
        ignore_permissions=True,
    )
    return [
        {"id": r.name, "label": r.team_name or r.name}
        for r in rows
    ]


@frappe.whitelist()
def get_backend_team_options():
    """Return [{id, label}] for teams assigned as backend (subcon) teams on PO Dispatches."""
    rows = frappe.db.sql("""
        SELECT DISTINCT pd.backend_team AS id,
               COALESCE(NULLIF(t.team_name,''), t.team_id, pd.backend_team) AS label
        FROM `tabPO Dispatch` pd
        LEFT JOIN `tabINET Team` t ON t.name = pd.backend_team
        WHERE pd.backend_team IS NOT NULL AND pd.backend_team != ''
        ORDER BY label
    """, as_dict=True)
    return [{"id": r.id, "label": r.label or r.id} for r in rows]


def _batch_im_master_full_names(im_ids):
    ids = list({n for n in (im_ids or []) if n})
    if not ids:
        return {}
    out = {}
    for row in frappe.get_all(
        "IM Master",
        filters={"name": ["in", ids]},
        fields=["name", "full_name"],
        limit_page_length=len(ids) + 1,
    ):
        out[row.name] = row.full_name or row.name
    return out


def _execution_monitor_scope():
    """(clause, params) restricting the Execution Monitor to the caller's own work.

    This endpoint had no scoping at all: @frappe.whitelist() means
    login-required and nothing more, so any authenticated user could read
    every IM's plans, and the `team` filter the field pages send is a
    client-supplied narrowing rather than a boundary.

    It serves three different audiences, which is why it cannot simply reuse
    _rollout_scope_clause: that helper resolves an IM and returns None for
    anyone who is not one, which would empty Field History and Field QC/CIAG
    for every field user.

      PM / admin      -> everything
      INET IM         -> their own lines (PO Dispatch.im, or Rollout Plan.im)
      INET Field Team -> their own team's plans only, matching the lead team
                         or any team on the plan's split
      anyone else     -> nothing

    A field user whose team cannot be resolved gets nothing rather than
    everything: the safe direction to fail.
    """
    user = frappe.session.user
    if not user or user == "Guest":
        return "1=0", []
    roles = set(frappe.get_roles(user))
    if roles & {"Administrator", "System Manager", "INET Admin"}:
        return "1=1", []

    if "INET IM" in roles:
        _im, im_identifiers, _ = resolve_im_for_session()
        if im_identifiers:
            ids = list(im_identifiers)
            ph = ", ".join(["%s"] * len(ids))
            if frappe.db.has_column("Rollout Plan", "im"):
                return (
                    f"(IFNULL(pd.im,'') IN ({ph}) OR IFNULL(rp.im,'') IN ({ph}))",
                    ids + ids,
                )
            return f"IFNULL(pd.im,'') IN ({ph})", ids

    if "INET Field Team" in roles:
        team_id = _session_inet_field_team_id()
        if team_id:
            return (
                "(IFNULL(rp.team,'') = %s OR EXISTS ("
                " SELECT 1 FROM `tabRollout Plan Team` rpt"
                " WHERE rpt.parent = rp.name AND IFNULL(rpt.team,'') = %s))",
                [team_id, team_id],
            )

    return "1=0", []


def _execution_closed_exists_sql(alias="rp"):
    """EXISTS(...) that is true when a line is fully closed.

    Closed means: an execution marked Completed, a Work Done record built from
    that execution, and QC/CIAG satisfied. The OR short-circuit on each gate
    honours the per-plan _required flags — when qc_required = 0 for that plan
    we do not require a Pass.

    Shared by the monitor (which hides these) and Execution Analytics (which
    counts them), so "closed" means one thing in both places.
    """
    ciag_col = "de_wd.ciag_status" if frappe.db.has_column("Daily Execution", "ciag_status") else "''"
    qc_req = f"{alias}.qc_required" if frappe.db.has_column("Rollout Plan", "qc_required") else "1"
    ciag_req = f"{alias}.ciag_required" if frappe.db.has_column("Rollout Plan", "ciag_required") else "1"
    return (
        "EXISTS ("
        " SELECT 1 FROM `tabDaily Execution` de_wd"
        " INNER JOIN `tabWork Done` wd0 ON wd0.execution = de_wd.name"
        f" WHERE de_wd.rollout_plan = {alias}.name"
        " AND de_wd.execution_status = 'Completed'"
        f" AND ({qc_req} = 0 OR IFNULL(de_wd.qc_status, '') IN ('Pass', 'Not Applicable'))"
        f" AND ({ciag_req} = 0 OR IFNULL({ciag_col}, '') IN ('Approved', 'Not Applicable'))"
        ")"
    )


def _execution_superseded_exists_sql(alias="rp"):
    """EXISTS(...) that is true when a later visit exists for the same dispatch."""
    return (
        "EXISTS ("
        " SELECT 1 FROM `tabRollout Plan` rp_later"
        f" WHERE rp_later.po_dispatch = {alias}.po_dispatch"
        f" AND IFNULL(rp_later.visit_number, 0) > IFNULL({alias}.visit_number, 0)"
        ")"
    )


@frappe.whitelist()
def list_execution_monitor_rows(filters=None, limit=500, _options=None, _summary=None):
    """
    Rich rows for PM Execution Monitor (Rollout + latest execution + dispatch context).

    filters:
      {
        "status": "Planned|In Execution|Completed|Cancelled|Planning with Issue",
        "visit_type": "...",
        "team": "...",
        "from_date": "YYYY-MM-DD",
        "to_date": "YYYY-MM-DD",
        "search": "free text (matches plan, dispatch, team, IM, …)",
        "project_code": "exact project",
        "site_code": "exact DUID / site code",
        "execution_status": "Daily Execution.execution_status (e.g. Completed for Field QC)",
        "execution_team": "Daily Execution.team when filtering by execution_status",
        "tab": "main|internal_done - which half of the main/internal-done split to return",
      }
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters)
    filters = filters or {}

    rp_fields = [
        "name",
        "po_dispatch",
        "team",
        "plan_date",
        "visit_type",
        "visit_number",
        "target_amount",
        "achieved_amount",
        "completion_pct",
        "plan_status",
        "modified",
    ]
    if frappe.db.has_column("Rollout Plan", "region_type"):
        rp_fields.append("region_type")
    if frappe.db.has_column("Rollout Plan", "im"):
        rp_fields.append("im")
    if frappe.db.has_column("Rollout Plan", "qc_required"):
        rp_fields.append("qc_required")
    if frappe.db.has_column("Rollout Plan", "ciag_required"):
        rp_fields.append("ciag_required")
    if frappe.db.has_column("Rollout Plan", "access_time"):
        rp_fields.append("access_time")
    if frappe.db.has_column("Rollout Plan", "access_period"):
        rp_fields.append("access_period")
    if frappe.db.has_column("Rollout Plan", "plan_documents"):
        rp_fields.append("plan_documents")
    lim = _portal_row_limit(limit, 500)

    # Scope BEFORE any client-supplied filter: the `team` key the field pages
    # send narrows within this, it does not define it.
    scope_c, scope_p = _execution_monitor_scope()
    wheres = [scope_c]
    params = list(scope_p)
    for col, key in (("rp.plan_status", "status"),
                     ("rp.visit_type", "visit_type"),
                     ("rp.team", "team"),
                     ("IFNULL(pd.project_code,'')", "project_code"),
                     ("IFNULL(pd.site_code,'')", "site_code")):
        c, p = _sql_in_or_eq(col, filters.get(key))
        if c:
            wheres.append(c)
            params.extend(p)
    im_vals_em = _ensure_list(filters.get("im"))
    if im_vals_em:
        ph_em = ", ".join(["%s"] * len(im_vals_em))
        if frappe.db.has_column("Rollout Plan", "im"):
            wheres.append(f"(IFNULL(pd.im,'') IN ({ph_em}) OR IFNULL(rp.im,'') IN ({ph_em}))")
            params.extend(im_vals_em + im_vals_em)
        else:
            wheres.append(f"IFNULL(pd.im,'') IN ({ph_em})")
            params.extend(im_vals_em)
    if filters.get("from_date") and filters.get("to_date"):
        wheres.append("rp.plan_date BETWEEN %s AND %s")
        params.extend([filters["from_date"], filters["to_date"]])
    elif filters.get("from_date"):
        wheres.append("rp.plan_date >= %s")
        params.append(filters["from_date"])
    elif filters.get("to_date"):
        wheres.append("rp.plan_date <= %s")
        params.append(filters["to_date"])

    # The "Internal Work Done" sub-table (client-side split of this same
    # fetch by is_internal_work=1) has its own dedicated im/team/domain/type/
    # date filters — previously applied only to the already-loaded rows.
    # Each condition is OR'd with "not an internal-work row" so it only
    # narrows the internal subset, leaving the main table's rows untouched.
    if frappe.db.has_column("PO Dispatch", "is_internal_work"):
        internal_im_vals = _ensure_list(filters.get("internal_im"))
        if internal_im_vals:
            ph_iim = ", ".join(["%s"] * len(internal_im_vals))
            wheres.append(f"(IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(pd.im,'') IN ({ph_iim}))")
            params.extend(internal_im_vals)
        internal_team_vals_em = _ensure_list(filters.get("internal_team"))
        if internal_team_vals_em:
            ph_item = ", ".join(["%s"] * len(internal_team_vals_em))
            wheres.append(f"(IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(rp.team,'') IN ({ph_item}))")
            params.extend(internal_team_vals_em)
        if frappe.db.has_column("PO Dispatch", "internal_domain"):
            internal_domain_vals_em = _ensure_list(filters.get("internal_domain"))
            if internal_domain_vals_em:
                ph_idom = ", ".join(["%s"] * len(internal_domain_vals_em))
                wheres.append(f"(IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(pd.internal_domain,'') IN ({ph_idom}))")
                params.extend(internal_domain_vals_em)
        if frappe.db.has_column("PO Dispatch", "internal_work_type"):
            internal_type_vals_em = _ensure_list(filters.get("internal_work_type"))
            if internal_type_vals_em:
                ph_ityp = ", ".join(["%s"] * len(internal_type_vals_em))
                wheres.append(f"(IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(pd.internal_work_type,'') IN ({ph_ityp}))")
                params.extend(internal_type_vals_em)
        _internal_de_date_expr = (
            "(SELECT de3.execution_date FROM `tabDaily Execution` de3 "
            "WHERE de3.rollout_plan = rp.name ORDER BY de3.modified DESC LIMIT 1)"
        )
        if filters.get("internal_from_date"):
            wheres.append(f"(IFNULL(pd.is_internal_work,0) = 0 OR {_internal_de_date_expr} >= %s)")
            params.append(filters["internal_from_date"])
        if filters.get("internal_to_date"):
            wheres.append(f"(IFNULL(pd.is_internal_work,0) = 0 OR {_internal_de_date_expr} <= %s)")
            params.append(filters["internal_to_date"])

    exec_status_vals = _ensure_list(filters.get("execution_status"))
    if exec_status_vals:
        if len(exec_status_vals) == 1:
            ex_match = "de0.execution_status = %s"
            ex_params = [exec_status_vals[0]]
        else:
            ex_match = "de0.execution_status IN ({})".format(", ".join(["%s"] * len(exec_status_vals)))
            ex_params = list(exec_status_vals)
        ex_sql = (
            "EXISTS (SELECT 1 FROM `tabDaily Execution` de0 "
            f"WHERE de0.rollout_plan = rp.name AND {ex_match}"
        )
        params.extend(ex_params)
        if filters.get("execution_team"):
            ex_sql += " AND de0.team = %s"
            params.append(filters["execution_team"])
        ex_sql += " LIMIT 1)"
        wheres.append(ex_sql)

    # Once the line is fully closed (exec Completed + QC Pass + CIAG Approved)
    # AND the IM has created a Work Done record for that execution, hide it
    # from the monitor — operators don't need to act on it anymore. The
    # OR short-circuit on each gate honours per-plan _required flags: when
    # qc_required = 0 for that plan, we don't require qc_status = Pass.
    # `closure` / `visits` default to the monitor's historical behaviour, so
    # every existing caller gets a byte-identical query. Execution Analytics
    # passes them explicitly because its whole point is to look at closed and
    # superseded work too.
    closure = (str(filters.get("closure") or "open")).strip().lower()
    if closure not in ("open", "all", "closed"):
        closure = "open"
    if closure != "all":
        negate = "NOT " if closure == "open" else ""
        wheres.append(negate + _execution_closed_exists_sql())

    visits = (str(filters.get("visits") or "current")).strip().lower()
    if visits != "all":
        # A higher-visit_number plan for the same dispatch means this one is a
        # past attempt — drop it so operators see only the current visit.
        wheres.append("NOT " + _execution_superseded_exists_sql())

    # Drill-through from Execution Analytics. The predicate comes from the
    # SAME registry the tile counted with, so the number and the list it opens
    # cannot disagree. The dex/wdx joins are added only in this branch, so the
    # ordinary monitor query is untouched.
    _bucket = (str(filters.get("bucket") or "")).strip()
    bucket_join = ""
    if _bucket:
        bucket_join = (
            f" LEFT JOIN ({_DEX_SQL}) dex ON dex.rollout_plan = rp.name"
            f" LEFT JOIN ({_WDX_SQL}) wdx ON wdx.rollout_plan = rp.name "
        )
        wheres.append(execution_bucket_condition(_bucket))

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale. This one backend serves 4 different table shapes (PM
    # Execution Monitor's main + internal-done tables, Field History, Field
    # QC/CIAG), so the map below is a superset covering every column any of
    # them show; a page just sends whichever keys its own columns produce.
    # "tl_status"/"execution_status"/"qc_status"/"ciag_status"/etc. live on
    # the *latest* Daily Execution per plan (fetched separately in Python via
    # `latest_exec_by_plan`, ordered by modified desc) — mirrored here as a
    # correlated subquery picking the same latest row.
    def _latest_de(col):
        return (
            f"(SELECT de1.{col} FROM `tabDaily Execution` de1 "
            "WHERE de1.rollout_plan = rp.name ORDER BY de1.modified DESC LIMIT 1)"
        )

    # "tab" - which subset of this shared main+internal-done fetch to
    # return. Mirrors the frontend's own client-side split (mainRows /
    # internalDoneRows in ExecutionMonitor.jsx / IMExecution.jsx):
    # "internal_done" = is_internal_work AND latest execution_status is
    # Completed; "main" (default) = everything else. Without this, one
    # row-limited fetch served both tabs, so whichever tab wasn't the
    # majority of the loaded batch silently lost rows beyond the limit.
    if frappe.db.has_column("PO Dispatch", "is_internal_work"):
        tab_scope = (filters.get("tab") or "main").strip().lower()
        if tab_scope in ("main", "internal_done"):
            _is_internal_done_expr = (
                "(IFNULL(pd.is_internal_work,0) = 1 AND IFNULL("
                + _latest_de("execution_status") + ", '') = 'Completed')"
            )
            if tab_scope == "internal_done":
                wheres.append(_is_internal_done_expr)
            else:
                wheres.append(f"NOT {_is_internal_done_expr}")

    # Dummy POs with no item_description show the manager's remark instead
    # (see _apply_dummy_description) — mirror that fallback here so filtering
    # "Description" matches what the column actually displays.
    _desc_expr = (
        "CASE WHEN IFNULL(pd.is_dummy_po,0) = 1 AND IFNULL(pd.item_description,'') = '' "
        "THEN IFNULL(pd.manager_remark,'') ELSE IFNULL(pd.item_description,'') END"
        if frappe.db.has_column("PO Dispatch", "is_dummy_po") and frappe.db.has_column("PO Dispatch", "manager_remark")
        else "IFNULL(pd.item_description,'')"
    )
    col_filter_map = {
        "plan": "rp.name",
        "project": "IFNULL(pd.project_code,'')",
        "duid": "IFNULL(pd.site_code,'')",
        "item": "IFNULL(pd.item_code,'')",
        "item_code": "IFNULL(pd.item_code,'')",
        "description": _desc_expr,
        "team": "IFNULL(it.team_name,'')",
        "plan_date": "CAST(rp.plan_date AS CHAR)",
        "visit_type": "IFNULL(rp.visit_type,'')",
        # "visit" is FieldHistory.jsx's bare "Visit" header (shows visit_type)
        # — its ExecutionMonitor.jsx counterpart is renamed to "Visit No" to
        # avoid the same slug collision fixed previously in IMPlanning.jsx.
        "visit": "IFNULL(rp.visit_type,'')",
        "visit_no": "CAST(rp.visit_number AS CHAR)",
        "target": "CAST(rp.target_amount AS CHAR)",
        "plan_status": "IFNULL(rp.plan_status,'')",
        "tl_status": _latest_de("tl_status"),
        "my_status": _latest_de("tl_status"),
        "execution_status": _latest_de("execution_status"),
        "exec_status": _latest_de("execution_status"),
        "im_status": _latest_de("execution_status"),
        "issue_category": _latest_de("issue_category"),
        # Column shows the IM's full name, falling back to the raw code. The
        # substring path special-cases `im` before this map, so it had no
        # entry here and the value dropdown reported it unfilterable.
        "im": (
            "IFNULL(NULLIF((SELECT full_name FROM `tabIM Master` "
            "WHERE name = COALESCE(NULLIF(pd.im,''), rp.im)), ''), "
            "IFNULL(COALESCE(NULLIF(pd.im,''), rp.im), ''))"
        ),
        "qc": _latest_de("qc_status"),
        "achieved_qty": f"CAST({_latest_de('achieved_qty')} AS CHAR)",
        "qty": f"CAST({_latest_de('achieved_qty')} AS CHAR)",
        "date": "CONCAT_WS(' ', CAST(" + _latest_de("execution_date") + " AS CHAR), CAST(rp.plan_date AS CHAR))",
        "exec_date": f"CAST({_latest_de('execution_date')} AS CHAR)",
        "gps": _latest_de("gps_location"),
        "execution_id": _latest_de("name"),
        "execution": _latest_de("name"),
    }
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        col_filter_map["ciag"] = _latest_de("ciag_status")
    if frappe.db.has_column("PO Dispatch", "poid"):
        col_filter_map["poid"] = "COALESCE(NULLIF(pd.poid,''), pd.name)"
    else:
        col_filter_map["poid"] = "IFNULL(pd.name,'')"
    if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
        col_filter_map["dummy_poid"] = "IFNULL(pd.original_dummy_poid,'')"
    if frappe.db.has_column("PO Dispatch", "center_area"):
        col_filter_map["center_area"] = "IFNULL(pd.center_area,'')"
    if frappe.db.has_column("PO Dispatch", "internal_work_type"):
        col_filter_map["type"] = "IFNULL(pd.internal_work_type,'')"
    region_parts = []
    if frappe.db.has_column("Rollout Plan", "region_type"):
        region_parts.append("IFNULL(rp.region_type,'')")
    if frappe.db.has_column("PO Dispatch", "region_type"):
        region_parts.append("IFNULL(pd.region_type,'')")
    if region_parts:
        col_filter_map["region"] = "CONCAT_WS(' ', " + ", ".join(region_parts) + ")"
    # "Domain"/"Huawei IM" mean different things on different tables: the
    # internal-work table shows pd.internal_domain (a real column); the
    # normal tables show the *project's* domain/Huawei IM (a Project Control
    # Center lookup by project_code, previously Python-only). The `pcc` join
    # below covers both in one expression so either table's filter works.
    domain_parts = []
    if frappe.db.has_column("PO Dispatch", "internal_domain"):
        domain_parts.append("IFNULL(pd.internal_domain,'')")
    domain_parts.append("COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '')")
    col_filter_map["domain"] = "CONCAT_WS(' ', " + ", ".join(domain_parts) + ")"
    col_filter_map["huawei_im"] = "COALESCE(NULLIF(pd.huawei_im,''), pcc.huawei_im, '')"
    if frappe.db.has_column("PO Dispatch", "general_remark"):
        col_filter_map["general"] = "IFNULL(pd.general_remark,'')"
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        col_filter_map["manager"] = "IFNULL(pd.manager_remark,'')"
    if frappe.db.has_column("PO Dispatch", "team_lead_remark"):
        col_filter_map["team_lead"] = "IFNULL(pd.team_lead_remark,'')"
    col_filter_map["activity_type"] = (
        "IFNULL((SELECT activity_type FROM `tabItem` WHERE name = pd.item_code), '')"
    )
    if frappe.db.has_column("Rollout Plan", "access_time"):
        col_filter_map["access_time"] = "IFNULL(CAST(rp.access_time AS CHAR), '')"
    # Not backend-filterable: "access" is a computed badge.
    column_filters_em = filters.get("column_filters")
    if isinstance(column_filters_em, str):
        try:
            column_filters_em = frappe.parse_json(column_filters_em)
        except Exception:
            column_filters_em = None
    if isinstance(column_filters_em, dict):
        for col_key, raw_val in column_filters_em.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            if col_key == "im":
                im_parts = ["(IFNULL(pd.im,'') LIKE %s)"]
                im_params = [pat]
                if frappe.db.has_column("Rollout Plan", "im"):
                    im_parts.append("(IFNULL(rp.im,'') LIKE %s)")
                    im_params.append(pat)
                im_parts.append(
                    "(pd.im IN (SELECT name FROM `tabIM Master` WHERE full_name LIKE %s))"
                )
                im_params.append(pat)
                if frappe.db.has_column("Rollout Plan", "im"):
                    im_parts.append(
                        "(rp.im IN (SELECT name FROM `tabIM Master` WHERE full_name LIKE %s))"
                    )
                    im_params.append(pat)
                wheres.append("(" + " OR ".join(im_parts) + ")")
                params.extend(im_params)
                continue
            expr = col_filter_map.get(col_key)
            if not expr:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat)

    like_pat = _sql_like_pattern(filters.get("search") or filters.get("q") or "")
    if like_pat:
        concat_parts = [
            "IFNULL(rp.name,'')",
            "IFNULL(rp.team,'')",
            "CAST(rp.plan_date AS CHAR)",
            "IFNULL(rp.visit_type,'')",
            "IFNULL(rp.plan_status,'')",
            "IFNULL(rp.po_dispatch,'')",
            "COALESCE(NULLIF(pd.poid,''), pd.name, '')",
            "IFNULL(pd.po_no,'')",
            "IFNULL(pd.item_code,'')",
            _desc_expr,
            "IFNULL(pd.project_code,'')",
            "IFNULL(pd.site_code,'')",
            "IFNULL(pd.site_name,'')",
            "IFNULL(pd.center_area,'')",
            "IFNULL(pd.region_type,'')",
            "IFNULL(pd.original_dummy_poid,'')",
            "IFNULL(it.team_name,'')",
            "IFNULL(pd.im,'')",
            "COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '')",
            "IFNULL(pcc.huawei_im,'')",
        ]
        if frappe.db.has_column("Rollout Plan", "region_type"):
            concat_parts.append("IFNULL(rp.region_type,'')")
        rp_im_join = ""
        if frappe.db.has_column("Rollout Plan", "im"):
            rp_im_join = "LEFT JOIN `tabIM Master` rim_rp ON rim_rp.name = rp.im"
            concat_parts.append("IFNULL(rim_rp.full_name,'')")
        pd_im_join = ""
        if frappe.db.has_column("PO Dispatch", "im"):
            pd_im_join = "LEFT JOIN `tabIM Master` rim_pd ON rim_pd.name = pd.im"
            concat_parts.append("IFNULL(rim_pd.full_name,'')")
        concat_expr = "CONCAT_WS(' ', " + ", ".join(concat_parts) + ")"
        clause, cparams = _sql_search_clause(
            concat_expr, filters.get("search") or filters.get("q") or "",
            exact_cols=["COALESCE(NULLIF(pd.poid,''), pd.name)", "IFNULL(pd.site_code,'')"],
        )
        if clause:
            wheres.append(clause)
            params.extend(cparams)
    else:
        rp_im_join = (
            "LEFT JOIN `tabIM Master` rim_rp ON rim_rp.name = rp.im"
            if frappe.db.has_column("Rollout Plan", "im")
            else ""
        )
        pd_im_join = (
            "LEFT JOIN `tabIM Master` rim_pd ON rim_pd.name = pd.im"
            if frappe.db.has_column("PO Dispatch", "im")
            else ""
        )

    sql_from = (
        "FROM `tabRollout Plan` rp "
        "LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
        "LEFT JOIN `tabINET Team` it ON it.name = rp.team "
        "LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code "
        f"{rp_im_join} {pd_im_join}{bucket_join}"
    )
    if _options:
        _e = col_filter_map.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            sql_from.replace("FROM ", "", 1), " AND ".join(wheres), params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # A PM watches this page for movement: what is running now, what
        # finished, and what has stalled. Plan status is the honest signal —
        # Rollout Plan drives the whole board.
        _ps = "IFNULL(rp.plan_status,'')"
        return summary_from_query(
            sql_from.replace("FROM ", "", 1), " AND ".join(wheres), params, [
                {"key": "plans", "label": "Plans", "agg": "count"},
                {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pd.site_code,''), '')"},
                {"key": "value", "label": "Value", "agg": "sum",
                 "expr": "IFNULL(pd.line_amount, 0)", "format": "money", "tone": "good"},
                {"key": "in_execution", "label": "Running", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} IN ('In Execution','Extended')", "tone": "info", "hide_if_zero": True},
                {"key": "completed", "label": "Completed", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Completed'", "tone": "good", "hide_if_zero": True},
                {"key": "overdue", "label": "Overdue", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Overdue'", "tone": "bad", "hide_if_zero": True,
                 "hint": "Past its planned date and not complete"},
                {"key": "issue", "label": "With issue", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Planning with Issue'", "tone": "warn", "hide_if_zero": True},
                {"key": "cancelled", "label": "Cancelled", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Cancelled'", "hide_if_zero": True},
            ])
    id_sql = (
        "SELECT rp.name AS plan_id "
        f"{sql_from} "
        f"WHERE {' AND '.join(wheres)} "
        "ORDER BY rp.modified DESC "
        f"{_sql_limit_suffix(lim)}"
    )
    plan_rows = frappe.db.sql(id_sql, tuple(params), as_dict=True)
    plan_names = [r.plan_id for r in (plan_rows or []) if r.get("plan_id")]
    if not plan_names:
        return []

    order_index = {n: i for i, n in enumerate(plan_names)}
    plans = frappe.get_all(
        "Rollout Plan",
        filters={"name": ["in", plan_names]},
        fields=rp_fields,
        limit_page_length=len(plan_names) + 1,
    )
    plans.sort(key=lambda x: order_index.get(x.name, 10**9))
    dispatch_names = [p.po_dispatch for p in plans if p.po_dispatch]

    if lim:
        exec_cap = min(max(len(plan_names) * 25, lim), 5000)
    else:
        exec_cap = min(max(len(plan_names) * 25, 500), 50000)
    _de_fields = [
        "name", "rollout_plan", "execution_date", "execution_status",
        "tl_status", "issue_category", "achieved_qty", "achieved_amount",
        "qc_status", "photos", "gps_location", "modified",
    ]
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        _de_fields.append("ciag_status")
    execution_rows = frappe.get_all(
        "Daily Execution",
        filters={"rollout_plan": ["in", plan_names]},
        fields=_de_fields,
        order_by="modified desc",
        limit_page_length=exec_cap,
    )
    latest_exec_by_plan = {}
    for ex in execution_rows:
        if ex.rollout_plan not in latest_exec_by_plan:
            latest_exec_by_plan[ex.rollout_plan] = ex

    dispatch_map = {}
    if dispatch_names:
        d_fields = [
            "name",
            "po_no",
            "item_code",
            "item_description",
            "project_code",
            "site_name",
            "site_code",
            "customer",
        ]
        if frappe.db.has_column("PO Dispatch", "poid"):
            d_fields.append("poid")
        if frappe.db.has_column("PO Dispatch", "im"):
            d_fields.append("im")
        if frappe.db.has_column("PO Dispatch", "huawei_im"):
            d_fields.append("huawei_im")
        if frappe.db.has_column("PO Dispatch", "center_area"):
            d_fields.append("center_area")
        if frappe.db.has_column("PO Dispatch", "region_type"):
            d_fields.append("region_type")
        if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
            d_fields.append("original_dummy_poid")
        if frappe.db.has_column("PO Dispatch", "is_dummy_po"):
            d_fields.append("is_dummy_po")
        for ik in ("is_internal_work", "internal_work_type", "internal_domain"):
            if frappe.db.has_column("PO Dispatch", ik):
                d_fields.append(ik)
        for rk in ("general_remark", "manager_remark", "team_lead_remark"):
            if frappe.db.has_column("PO Dispatch", rk):
                d_fields.append(rk)
        drows = frappe.get_all(
            "PO Dispatch",
            filters={"name": ["in", dispatch_names]},
            fields=d_fields,
            limit_page_length=1000,
        )
        dispatch_map = {d.name: d for d in drows}

    team_ids = [p.team for p in plans if p.team]
    im_keys = []
    for p in plans:
        if p.get("im"):
            im_keys.append(p.im)
    for d in dispatch_map.values():
        if d.get("im"):
            im_keys.append(d.im)
    team_name_map = _batch_inet_team_names(team_ids)
    im_name_map = _batch_im_master_full_names(im_keys)

    # Batch-fetch earliest timer start per DUID (site_code) for today.
    # All plans at the same physical site share the TL's first arrival time.
    timer_start_map = {}
    if plan_names and frappe.db.exists("DocType", "Execution Time Log"):
        site_for_plan = {
            p.name: (dispatch_map.get(p.po_dispatch) or {}).get("site_code") or ""
            for p in plans
        }
        site_codes = list({s for s in site_for_plan.values() if s})
        if site_codes:
            ph_s = ", ".join(["%s"] * len(site_codes))
            t_rows = frappe.db.sql(
                f"SELECT pd2.site_code, MIN(etl.start_time) AS timer_start "
                f"FROM `tabExecution Time Log` etl "
                f"INNER JOIN `tabRollout Plan` rp2 ON rp2.name = etl.rollout_plan "
                f"INNER JOIN `tabPO Dispatch` pd2 ON pd2.name = rp2.po_dispatch "
                f"WHERE pd2.site_code IN ({ph_s}) AND DATE(etl.start_time) = CURDATE() "
                f"GROUP BY pd2.site_code",
                tuple(site_codes),
                as_dict=True,
            )
            site_timer_map = {r.site_code: _frappe_dt_to_epoch_ms(r.timer_start) for r in t_rows}
            timer_start_map = {
                p_name: site_timer_map.get(site_for_plan.get(p_name))
                for p_name in plan_names
            }

    out = []
    for p in plans:
        ex = latest_exec_by_plan.get(p.name)
        d = dispatch_map.get(p.po_dispatch) if p.po_dispatch else None
        pd_im = d.get("im") if d else None
        rp_im = p.get("im") if frappe.db.has_column("Rollout Plan", "im") else None
        im_key = rp_im or pd_im
        out.append(
            {
                "name": p.name,
                "system_id": p.po_dispatch or p.name,
                "po_dispatch": p.po_dispatch,
                # Prefer the `poid` field when populated; fall back to the
                # dispatch name (which was the POID on pre-refactor docs).
                "poid": ((d.get("poid") if d else None) or (d.name if d else None) or p.po_dispatch),
                "po_no": d.po_no if d else None,
                "item_code": d.item_code if d else None,
                "item_description": d.item_description if d else None,
                "project_code": d.project_code if d else None,
                "site_name": d.site_name if d else None,
                "site_code": d.site_code if d else None,
                "center_area": (d.get("center_area") if d else None),
                "region_type": (p.get("region_type") or (d.get("region_type") if d else None)),
                "team": p.team,
                "team_name": team_name_map.get(p.team) if p.team else None,
                "im": im_key,
                "im_full_name": im_name_map.get(im_key) if im_key else None,
                "huawei_im": d.get("huawei_im") if d else None,
                "plan_date": p.plan_date,
                "visit_type": p.visit_type,
                "visit_number": p.get("visit_number") if p else None,
                "target_amount": flt(p.target_amount or 0),
                "achieved_amount": flt(p.achieved_amount or 0),
                "completion_pct": flt(p.completion_pct or 0),
                "plan_status": p.plan_status,
                "execution_name": ex.name if ex else None,
                "execution_date": ex.execution_date if ex else None,
                "execution_status": ex.execution_status if ex else None,
                "tl_status": ex.get("tl_status") if ex else None,
                "issue_category": ex.get("issue_category") if ex else None,
                "execution_achieved_qty": flt(ex.achieved_qty or 0) if ex else 0,
                "execution_achieved_amount": flt(ex.achieved_amount or 0) if ex else 0,
                "qc_status": ex.qc_status if ex else None,
                "ciag_status": ex.get("ciag_status") if ex else None,
                "photos": ex.photos if ex else None,
                "gps_location": ex.gps_location if ex else None,
                "modified": p.modified,
                "customer": d.get("customer") if d else None,
                "general_remark": d.get("general_remark") if d else None,
                "manager_remark": d.get("manager_remark") if d else None,
                "team_lead_remark": d.get("team_lead_remark") if d else None,
                "is_dummy_po": d.get("is_dummy_po") if d else None,
                "is_internal_work": d.get("is_internal_work") if d else None,
                "internal_work_type": d.get("internal_work_type") if d else None,
                "internal_domain": d.get("internal_domain") if d else None,
                "original_dummy_poid": (
                    (d.get("original_dummy_poid") or "").strip()
                    if d and frappe.db.has_column("PO Dispatch", "original_dummy_poid")
                    else None
                ),
                "access_time": str(p.access_time) if p.get("access_time") else None,
                "access_period": p.get("access_period") or None,
                "plan_documents": p.get("plan_documents") or None,
                "timer_start_ms": timer_start_map.get(p.name),
            }
        )
    if out:
        act_map = _batch_item_activity_types(out)
        for r in out:
            r["activity_type"] = act_map.get(r.get("item_code") or "")
        _enrich_with_project_fields(out)
        _apply_dummy_description(out)
    return out


@frappe.whitelist()
def get_work_done_summary():
    """
    Full-dataset Work Done summary.
    Returns operational breakdown by issue_flag, and commercial breakdown
    separately for MS1 (pic_status) and MS2 (pic_status_ms2).
    """
    has_pic     = frappe.db.has_column("PO Dispatch", "pic_status")
    has_pic_ms2 = frappe.db.has_column("PO Dispatch", "pic_status_ms2")
    has_flag    = frappe.db.has_column("Work Done", "issue_flag")

    # Operational Work Done = the IM-facing category: exactly the row set
    # the List tab itself shows (list_work_done_rows' "all" tab — real
    # records + synthesized subcon placeholders, already excluding anything
    # fully resolved on both milestones). Reusing that function directly
    # (rather than re-deriving an independent dispatch_status-based scope,
    # which is what this used to do) makes the two permanently identical by
    # construction instead of two parallel definitions that can silently
    # drift apart again — which is exactly what happened: a dispatch_status
    # IN (...) scan can't tell "fully invoiced but dispatch_status never
    # advanced" from "still needs work", and separately has no way to know
    # about a milestone that's genuinely still open (e.g. I-BUY/ISDP
    # Rejected) once dispatch_status has already moved past its own
    # 5-value list. limit=0 is required, not optional — the default 500
    # cap would silently undercount once the site has more Work Done rows
    # than that.
    def _operational_rows(group_key):
        all_rows = list_work_done_rows(filters={"tab": "all"}, limit=0) or []
        buckets = {}
        for r in all_rows:
            grp = r.get(group_key) or ""
            b = buckets.setdefault(grp, {"grp": grp, "cnt": 0, "revenue": 0})
            b["cnt"] += 1
            b["revenue"] = flt(b["revenue"]) + flt(r.get("revenue_sar"))
        return list(buckets.values())

    def _po_rows(group_expr, status_clause):
        # wd_sub: same correlated subquery pic.py's _PIC_FROM_JOIN_LEAN uses —
        # _PIC_INITIAL_RULE_SQL (pulled in via _PIC_STAGE_SQL's "pending"
        # branch) reads wd_sub.confirmed for legacy rows with no pic_status
        # set yet but already TL-confirmed. One row per po_dispatch, so this
        # LEFT JOIN can't fan out the outer COUNT/SUM.
        # wd: aggregated to ONE row per system_id before joining — a plain
        # `LEFT JOIN tabWork Done ON wd.system_id = pd.name` fans out (and
        # inflates the outer COUNT(*)) whenever a PO Dispatch has more than
        # one Work Done record, which — pre-existing duplicate-WD bug,
        # mostly fixed going forward but legacy dupes still exist on this
        # site — it sometimes does. MAX() picks one consistent value rather
        # than double-counting revenue too.
        return frappe.db.sql(f"""
            SELECT IFNULL({group_expr}, '') AS grp,
                   COUNT(*) AS cnt,
                   SUM(COALESCE(wd.revenue_sar, pd.line_amount, 0)) AS revenue
            FROM `tabPO Dispatch` pd
            LEFT JOIN (
                SELECT system_id, MAX(revenue_sar) AS revenue_sar, MAX(issue_flag) AS issue_flag
                FROM `tabWork Done`
                GROUP BY system_id
            ) wd ON wd.system_id = pd.name
            LEFT JOIN (
                SELECT rp.po_dispatch AS po_dispatch,
                       MAX(IF(wd2.submission_status = 'Confirmation Done', 1, 0)) AS confirmed
                FROM `tabRollout Plan` rp
                INNER JOIN `tabDaily Execution` de ON de.rollout_plan = rp.name
                INNER JOIN `tabWork Done` wd2 ON wd2.execution = de.name
                GROUP BY rp.po_dispatch
            ) wd_sub ON wd_sub.po_dispatch = pd.name
            WHERE {status_clause}
              AND IFNULL(pd.is_internal_work, 0) = 0
              AND IFNULL(pd.is_dummy_po, 0) = 0
            GROUP BY grp
        """, as_dict=True)

    # Commercial = PIC's own scope, exactly — no dispatch_status pre-filter.
    # A dispatch_status-range gate (e.g. "must have reached Completed") is
    # the wrong test for whether PIC has engaged with a line: pic_status/
    # pic_status_ms2 can (and, per real data, sometimes does) show genuine
    # progress — including a milestone fully closed — while dispatch_status
    # is still stuck at an early operational stage like Planned or Backend
    # Assigned, because dispatch_status only auto-advances from specific
    # triggers and doesn't always keep pace. Gating on it here excluded real
    # PIC activity (confirmed against list_pic_rows: it cost 4,570 lines in
    # the Pending bucket alone, plus 6 more misclassified out of Active,
    # entirely because operations hadn't "caught up" yet on lines PIC had
    # already touched). Matching list_pic_rows' scope precisely — just
    # is_internal_work/is_dummy_po — keeps this section permanently in sync
    # with PIC's own numbers instead of silently drifting again later.
    def _commercial_po_rows(group_expr, extra_clause="1=1"):
        return _po_rows(group_expr, extra_clause)

    # Local import: pic.py imports FROM this module, so importing it back at
    # module level here would be circular — deferring to call time avoids
    # that.
    from inet_app.api.pic import _PIC_STAGE_SQL, _PIC_INITIAL_RULE_SQL

    # Work Done Summary-specific "done enough" rule — NOT used by PIC's own
    # pages (PIC Tracker etc. still require a literal 'Commercial Invoice
    # Closed' on both milestones, unchanged). Here, a line inside the
    # "Active" stage additionally counts as Commercially Done once each
    # APPLICABLE milestone has at least reached submission: MS1 must be
    # Submitted-or-Closed; MS2 must be Submitted-or-Closed too, UNLESS MS2
    # is blank — a genuinely single-milestone line — in which case MS1 alone
    # deciding is correct (same "no MS2 required" pattern already used for
    # full closure elsewhere).
    _MS1_SUBMITTED_SQL = f"(({_PIC_INITIAL_RULE_SQL.strip()}) IN ('Commercial Invoice Submitted','Commercial Invoice Closed'))"
    _MS2_SUBMITTED_OR_NA_SQL = (
        "(IFNULL(pd.pic_status_ms2,'') IN ('Commercial Invoice Submitted','Commercial Invoice Closed') "
        "OR IFNULL(pd.pic_status_ms2,'') = '')"
    )
    _SUMMARY_DONE_ENOUGH_SQL = f"({_MS1_SUBMITTED_SQL} AND {_MS2_SUBMITTED_OR_NA_SQL})"
    # The Active stage minus whatever just got promoted to "done enough" —
    # this is what the MS1/MS2 detail below and the "Still Active" tile both
    # need to agree on, so a line can't show up as done in one place and
    # still-open in the other.
    _SUMMARY_ACTIVE_SQL = f"({_PIC_STAGE_SQL['active']} AND NOT {_SUMMARY_DONE_ENOUGH_SQL})"
    _stage_case_sql = (
        "CASE "
        f"WHEN {_PIC_STAGE_SQL['pending']} THEN 'Pending' "
        f"WHEN {_PIC_STAGE_SQL['cancelled']} THEN 'Cancelled' "
        f"WHEN {_PIC_STAGE_SQL['closed']} THEN 'Closed' "
        f"WHEN {_PIC_STAGE_SQL['active']} AND {_SUMMARY_DONE_ENOUGH_SQL} THEN 'Closed' "
        "ELSE 'Active' END"
    )

    # to_serial() below reads r.cnt/r.revenue via attribute access — frappe._dict
    # supports that (plain dict subscripting wouldn't).
    op_rows = [frappe._dict(flag=r["grp"], cnt=r["cnt"], revenue=r["revenue"]) for r in _operational_rows("issue_flag")] if has_flag else []
    # MS1/MS2 status detail is scoped to the SAME (narrowed) "Active" set the
    # headline "Still Active" tile shows, not the full 17,434-line PIC
    # universe and not the lines just promoted into "Commercially Done"
    # above — a line can't be done-enough in the headline yet still show up
    # here as still-open. Closed lines would trivially all read "Commercial
    # Invoice Closed" on both milestones anyway (not informative).
    ms1_rows = [frappe._dict(status=r["grp"], cnt=r["cnt"], revenue=r["revenue"]) for r in _commercial_po_rows("pd.pic_status", _SUMMARY_ACTIVE_SQL)] if has_pic else []
    ms2_rows = [frappe._dict(status=r["grp"], cnt=r["cnt"], revenue=r["revenue"]) for r in _commercial_po_rows("pd.pic_status_ms2", _SUMMARY_ACTIVE_SQL)] if has_pic_ms2 else []

    # Commercial "done vs active" headline: reuse PIC's own Pending/Active/
    # Closed/Cancelled stage classification (same logic PIC's own pages route
    # on) instead of a bespoke MS1-only "done" rule — a line's real
    # commercial state depends on BOTH milestones together. Full universe
    # here (not stage-scoped) since this is what CLASSIFIES every line into
    # its stage in the first place.
    stage_rows = [frappe._dict(stage=r["grp"], cnt=r["cnt"], revenue=r["revenue"]) for r in _commercial_po_rows(_stage_case_sql)]

    PIC_STATUS_ORDER = [
        "Under Process to Apply",
        "Under I-BUY",
        "Under ISDP",
        "I-BUY Rejected",
        "ISDP Rejected",
        "Ready for Invoice",
        "PO Need to Cancel",
        "PO Line Canceled",
        "Work Not Done",
    ]
    PIC_DONE_STATUSES = ["Commercial Invoice Submitted", "Commercial Invoice Closed"]
    PIC_STAGE_ORDER = ["Pending", "Active", "Closed", "Cancelled"]
    OPERATIONAL_FLAGS = [
        "POD/PPT required",
        "TFM Check list",
        "Spare part return",
        "PAT/HO Final Approval",
        "FPDC/FM Survey report Approval",
        "Partial Work done",
    ]

    def to_serial(rows, key):
        return [{"key": r[key], "count": cint(r.cnt), "revenue": float(r.revenue or 0)}
                for r in rows]

    return {
        "operational":         to_serial(op_rows,  "flag"),
        "commercial_ms1":      to_serial(ms1_rows, "status"),
        "commercial_ms2":      to_serial(ms2_rows, "status"),
        "commercial_stage":    to_serial(stage_rows, "stage"),
        "operational_order":   OPERATIONAL_FLAGS,
        "pic_status_order":    PIC_STATUS_ORDER,
        "pic_done_statuses":   PIC_DONE_STATUSES,
        "pic_stage_order":     PIC_STAGE_ORDER,
        # backward-compat alias
        "commercial":          to_serial(ms1_rows, "status"),
        "commercial_order":    PIC_STATUS_ORDER,
    }


@frappe.whitelist()
def list_work_done_rows(filters=None, limit=500, _options=None, _summary=None):
    """
    Rich Work Done rows for PM page.
    filters: {
      billing_status, from_date, to_date, team, project_code, site_code, im,
      search (free text across work done, execution, dispatch, team, IM),
    }
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters)
    filters = filters or {}

    wd_fields = [
        "name",
        "execution",
        "system_id",
        "item_code",
        "executed_qty",
        "billing_rate_sar",
        "revenue_sar",
        "team_cost_sar",
        "subcontract_cost_sar",
        "total_cost_sar",
        "margin_sar",
        "billing_status",
        "modified",
    ]
    if frappe.db.has_column("Work Done", "region_type"):
        wd_fields.append("region_type")
    if frappe.db.has_column("Work Done", "submission_status"):
        wd_fields.append("submission_status")
    if frappe.db.has_column("Work Done", "issue_flag"):
        wd_fields.append("issue_flag")
    if frappe.db.has_column("Work Done", "subcontractor"):
        wd_fields.append("subcontractor")
    if frappe.db.has_column("Work Done", "source"):
        wd_fields.append("source")
    if frappe.db.has_column("Work Done", "direct_close_by"):
        wd_fields.append("direct_close_by")
    if frappe.db.has_column("Work Done", "ms1_closed"):
        wd_fields += ["ms1_closed", "ms2_closed", "ms1_closed_at", "ms2_closed_at"]
    lim = _portal_row_limit(limit, 500)

    wheres = ["1=1"]
    params = []
    # Billing status filter uses the same PIC roll-up that the response shows
    # — picking "Closed" returns rows where the PIC has marked
    # "Commercial Invoice Closed" / "PO Line Canceled". Falls back to the
    # legacy wd.billing_status for rows that haven't been touched by PIC yet,
    # OR for sites where the pic_status column hasn't migrated.
    if frappe.db.has_column("PO Dispatch", "pic_status"):
        billing_expr = (
            "CASE "
            "WHEN pd.pic_status IN ('Commercial Invoice Closed','PO Line Canceled') THEN 'Closed' "
            "WHEN pd.pic_status IN ('Commercial Invoice Submitted','Ready for Invoice','Under I-BUY','Under ISDP') THEN 'Invoiced' "
            "WHEN IFNULL(pd.pic_status,'') != '' THEN 'Pending' "
            "ELSE IFNULL(wd.billing_status, 'Pending') END"
        )
    else:
        billing_expr = "IFNULL(wd.billing_status, 'Pending')"
    for col, key in ((billing_expr, "billing_status"),
                     ("COALESCE(pd.dispatch_status, pd_sys.dispatch_status, '')", "dispatch_status"),
                     # de.team is the team that actually executed; rp.team is
                     # only the plan's LEAD team, so on a split plan this
                     # displayed (and filtered) a SUB team's work under the
                     # INET team that led the plan. Same fix as
                     # _daily_execution_report_rows.
                     ("IFNULL(de.team, rp.team)", "team"),
                     ("COALESCE(pd.project_code, pd_sys.project_code, '')", "project_code"),
                     ("COALESCE(pd.site_code, pd_sys.site_code, '')", "site_code")):
        c, p = _sql_in_or_eq(col, filters.get(key))
        if c:
            wheres.append(c)
            params.extend(p)
    # Hide rows that are fully commercially wrapped up — the working tabs are
    # for tracking work that still needs PIC submission/invoicing, not an
    # invoicing archive. "Fully wrapped up" is judged per milestone, not per
    # dispatch_status: a row is hidden only once every milestone IT
    # represents has reached a terminal PIC status
    # (_DATA_INTEGRITY_TERMINAL_MS: Submitted / Closed / Line Canceled).
    #   - A milestone-scoped Direct Close row (ms1_closed XOR ms2_closed,
    #     see _direct_close_one) only ever represents the ONE milestone it
    #     closed — MS2's own state is irrelevant to an MS1-only row; MS2
    #     will get its own row (and its own visibility check) whenever it's
    #     eventually closed.
    #   - Every other row (normal Rollout Execution, or a Direct Close that
    #     closed the whole line at once) represents the entire dispatch, so
    #     it's hidden only once MS1 AND (MS2, if it even applies — i.e.
    #     ms2_amount > 0) are both terminal. A two-milestone line with only
    #     one milestone submitted still needs to show — there's real work
    #     left to track on the other one.
    # The "All" tab opts OUT of this: it is meant to be every work row for the
    # IM's scope, closed and invoiced ones included, so it must not be scoped
    # by commercial state at all. The other tabs keep the hide rule — they are
    # working views, and a resolved row there is noise.
    tab_scope_wd = (filters.get("tab") or "active").strip().lower()
    if tab_scope_wd != "all" and (
        frappe.db.has_column("PO Dispatch", "pic_status")
        and frappe.db.has_column("PO Dispatch", "pic_status_ms2")
        and frappe.db.has_column("Work Done", "ms1_closed")
    ):
        terminal_ms = list(_DATA_INTEGRITY_TERMINAL_MS)
        ph_ms = ", ".join(["%s"] * len(terminal_ms))
        # IFNULL wrapping matters here, not just style: pic_status is SQL NULL
        # (not '') on plenty of real rows (never touched by PIC yet). Left
        # bare, `NULL IN (...)` evaluates to NULL rather than FALSE, and
        # `NOT (... OR (NULL AND ...))` can itself come out NULL — which a
        # WHERE clause silently treats as "exclude", dropping rows that are
        # obviously unresolved. Coercing to '' first keeps this on ordinary
        # two-valued boolean logic.
        ms1_status_expr = "IFNULL(COALESCE(pd.pic_status, pd_sys.pic_status), '')"
        ms2_status_expr = "IFNULL(COALESCE(pd.pic_status_ms2, pd_sys.pic_status_ms2), '')"
        ms2_amount_expr = "COALESCE(pd.ms2_amount, pd_sys.ms2_amount, 0)"
        wheres.append(
            "NOT ("
            f"  (IFNULL(wd.ms1_closed,0) = 1 AND IFNULL(wd.ms2_closed,0) = 0 AND {ms1_status_expr} IN ({ph_ms}))"
            "  OR"
            f"  (IFNULL(wd.ms2_closed,0) = 1 AND IFNULL(wd.ms1_closed,0) = 0 AND {ms2_status_expr} IN ({ph_ms}))"
            "  OR"
            # Both flags equal (0/0 normal or full-close row, but also 1/1 —
            # real data has rows where a Direct Close set both at once) means
            # this row isn't scoped to a single milestone, so it represents
            # the whole line.
            "  (IFNULL(wd.ms1_closed,0) = IFNULL(wd.ms2_closed,0)"
            f"    AND {ms1_status_expr} IN ({ph_ms})"
            f"    AND ({ms2_amount_expr} = 0 OR {ms2_status_expr} IN ({ph_ms}))"
            "  )"
            ")"
        )
        params.extend(terminal_ms)
        params.extend(terminal_ms)
        params.extend(terminal_ms)
        params.extend(terminal_ms)
    im_vals = _ensure_list(filters.get("im"))
    if im_vals:
        rp_im_col = frappe.db.has_column("Rollout Plan", "im")
        ph = ", ".join(["%s"] * len(im_vals))
        if rp_im_col:
            wheres.append(f"(IFNULL(pd.im,'') IN ({ph}) OR IFNULL(rp.im,'') IN ({ph}) OR IFNULL(pd_sys.im,'') IN ({ph}))")
            params.extend(im_vals + im_vals + im_vals)
        else:
            wheres.append(f"(IFNULL(pd.im,'') IN ({ph}) OR IFNULL(pd_sys.im,'') IN ({ph}))")
            params.extend(im_vals + im_vals)
    if filters.get("from_date"):
        wheres.append("COALESCE(de.execution_date, DATE(wd.creation)) >= %s")
        params.append(filters["from_date"])
    if filters.get("to_date"):
        wheres.append("COALESCE(de.execution_date, DATE(wd.creation)) <= %s")
        params.append(filters["to_date"])
    if filters.get("exclude_backend"):
        wheres.append("COALESCE(pd.dispatch_status, pd_sys.dispatch_status, '') != 'Backend Assigned'")

    # Work-type toggle (Field Work / Backend / Direct Close) — a dedicated
    # toolbar filter on both WorkDone pages, previously applied only to the
    # already-loaded rows client-side. Exact-match on the stored `source`
    # value; the frontend decides whether "Rollout Execution" should also
    # include legacy empty-source rows (admin/WorkDone.jsx does, IMWorkDone.jsx
    # doesn't — that display nuance predates this fix and is left unchanged).
    source_vals = _ensure_list(filters.get("source"))
    if source_vals and frappe.db.has_column("Work Done", "source"):
        ph_src = ", ".join(["%s"] * len(source_vals))
        wheres.append(f"IFNULL(wd.source,'') IN ({ph_src})")
        params.extend(source_vals)

    # Same "loaded rows only" bug as source above, for 3 more dedicated
    # toolbar filters on the WorkDone pages. "__NONE__" is a sentinel these
    # pages already use client-side to mean "empty/not set".
    def _in_or_none(col, vals):
        none_wanted = "__NONE__" in vals
        real_vals = [v for v in vals if v != "__NONE__"]
        parts, p = [], []
        if none_wanted:
            parts.append(f"IFNULL({col},'') = ''")
        if real_vals:
            ph = ", ".join(["%s"] * len(real_vals))
            parts.append(f"{col} IN ({ph})")
            p.extend(real_vals)
        if not parts:
            return None, []
        return "(" + " OR ".join(parts) + ")", p

    submission_vals = _ensure_list(filters.get("submission_status"))
    if submission_vals and frappe.db.has_column("Work Done", "submission_status"):
        clause, p = _in_or_none("wd.submission_status", submission_vals)
        if clause:
            wheres.append(clause)
            params.extend(p)

    # "tab" - which of IMWorkDone.jsx's 3 mutually-exclusive tabs (Active /
    # Confirmed / PIC Rejected) to return. Mirrors that page's own
    # client-side split (tabRows) exactly, including the pic_rejection_remark
    # fallback. Without this, one row-limited fetch served all 3 tabs, so
    # whichever tab wasn't the majority of the loaded batch lost rows.
    if frappe.db.has_column("Work Done", "submission_status"):
        _pic_rej_expr = (
            "COALESCE(pd.pic_rejection_remark, pd_sys.pic_rejection_remark)"
            if frappe.db.has_column("PO Dispatch", "pic_rejection_remark")
            else "NULL"
        )
        if tab_scope_wd == "confirmed":
            wheres.append("IFNULL(wd.submission_status,'') = 'Confirmation Done'")
        elif tab_scope_wd == "pic_rejected":
            wheres.append(
                f"(IFNULL(wd.submission_status,'') = 'PIC Rejected' OR IFNULL({_pic_rej_expr},'') != '')"
            )
        elif tab_scope_wd == "active":
            wheres.append(
                "IFNULL(wd.submission_status,'') NOT IN ('Confirmation Done', 'PIC Rejected')"
                f" AND IFNULL({_pic_rej_expr},'') = ''"
            )

    issue_flag_vals = _ensure_list(filters.get("issue_flag"))
    if issue_flag_vals and frappe.db.has_column("Work Done", "issue_flag"):
        clause, p = _in_or_none("wd.issue_flag", issue_flag_vals)
        if clause:
            wheres.append(clause)
            params.extend(p)

    exec_status_vals_wd = _ensure_list(filters.get("execution_status"))
    if exec_status_vals_wd:
        ph_ex = ", ".join(["%s"] * len(exec_status_vals_wd))
        wheres.append(f"IFNULL(de.execution_status,'') IN ({ph_ex})")
        params.extend(exec_status_vals_wd)

    rp_im_join_wd = (
        "LEFT JOIN `tabIM Master` rim_rp ON rim_rp.name = rp.im"
        if frappe.db.has_column("Rollout Plan", "im")
        else ""
    )
    pd_im_join_wd = (
        "LEFT JOIN `tabIM Master` rim_pd ON rim_pd.name = pd.im"
        if frappe.db.has_column("PO Dispatch", "im")
        else ""
    )

    # Subcontractor / Contract Model — same resolution PIC pages already use:
    # PO Dispatch's own `contract` link wins when set (an explicit PIC-side
    # assignment), falling back to whichever team executed the work (via the
    # `it` INET Team already joined above for assigned_team).
    subcon_join_wd = ""
    _subcon_expr_wd = "NULL"
    _contract_model_expr_wd = "NULL"
    _subcon_id_expr_wd = "NULL"
    if frappe.db.has_column("PO Dispatch", "contract") and frappe.db.exists("DocType", "Subcontract Master"):
        subcon_join_wd = (
            "LEFT JOIN `tabSubcontract Master` sm_pd ON sm_pd.name = COALESCE(pd.contract, pd_sys.contract) "
            "LEFT JOIN `tabSubcontract Master` sm_it ON sm_it.name = it.subcontractor "
        )
        _subcon_expr_wd = "COALESCE(sm_pd.subcontractor_name, sm_it.subcontractor_name)"
        _contract_model_expr_wd = "COALESCE(sm_pd.contract_model, sm_it.contract_model)"
        _subcon_id_expr_wd = "COALESCE(sm_pd.name, sm_it.name)"

    subcontractor_vals = _ensure_list(filters.get("subcontractor"))
    if subcontractor_vals and subcon_join_wd:
        ph_sc = ", ".join(["%s"] * len(subcontractor_vals))
        wheres.append(f"{_subcon_id_expr_wd} IN ({ph_sc})")
        params.extend(subcontractor_vals)

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale (each column matched independently and ANDed, not blended
    # into the wide `search` clause below; same expressions widen that
    # search too, so both paths cover the same fields).
    _wd_desc_raw = "COALESCE(NULLIF(pd.item_description,''), pd_sys.item_description, '')"
    _wd_desc_expr = (
        "CASE WHEN COALESCE(pd.is_dummy_po, pd_sys.is_dummy_po, 0) = 1 AND "
        f"{_wd_desc_raw} = '' THEN "
        "COALESCE(NULLIF(pd.manager_remark,''), pd_sys.manager_remark, '') "
        f"ELSE {_wd_desc_raw} END"
        if frappe.db.has_column("PO Dispatch", "is_dummy_po") and frappe.db.has_column("PO Dispatch", "manager_remark")
        else _wd_desc_raw
    )
    col_filter_map = {
        "project_code": "COALESCE(NULLIF(pd.project_code,''), pd_sys.project_code, '')",
        "poid": "COALESCE(NULLIF(pd.poid,''), NULLIF(pd_sys.poid,''), pd.name, pd_sys.name, '')",
        "duid": "COALESCE(NULLIF(pd.site_code,''), pd_sys.site_code, '')",
        "item_code": "IFNULL(wd.item_code,'')",
        # "item_description" for IMWorkDone.jsx ("Item Description" header);
        # "description" for admin/WorkDone.jsx ("Description" header) — same
        # underlying column, two different header labels slug to two keys.
        "item_description": _wd_desc_expr,
        "description": _wd_desc_expr,
        "line_amount": "CAST(COALESCE(pd.line_amount, pd_sys.line_amount) AS CHAR)",
        "region": "COALESCE(NULLIF(pd.region_type,''), pd_sys.region_type, '')",
        "planning_timestamp": "CAST(rp.creation AS CHAR)",
        "dispatch_seq": "CAST(COALESCE(pd.po_line_no, pd_sys.po_line_no) AS CHAR)",
        "plan_date": "CAST(rp.plan_date AS CHAR)",
        "assigned_team": "IFNULL(it.team_name,'')",
        "dispatch_status": "COALESCE(NULLIF(pd.dispatch_status,''), pd_sys.dispatch_status, '')",
        "execution_date": "CAST(de.execution_date AS CHAR)",
        "execution_status": "IFNULL(de.execution_status,'')",
        "attempt": "CAST(rp.visit_number AS CHAR)",
        "qc": "IFNULL(de.qc_status,'')",
        "execution_remarks": "IFNULL(de.remarks,'')",
        "revenue": f"CAST({wd_revenue_sql('wd', 'pd', 'pd_sys')} AS CHAR)",
        "billing_status": billing_expr,
        "subcontract": f"IFNULL({_subcon_expr_wd},'')",
        "contract_model": f"IFNULL({_contract_model_expr_wd},'')",
        # Header labels present on admin/WorkDone.jsx + IMWorkDone.jsx that
        # had no entry here, so their filters silently did nothing on the
        # backend. All reachable from joins this query already makes.
        "dummy_poid": "COALESCE(NULLIF(pd.original_dummy_poid,''), pd_sys.original_dummy_poid, '')",
        "execution": "IFNULL(wd.execution,'')",
        "project": "COALESCE(NULLIF(pd.project_code,''), pd_sys.project_code, '')",
        "site": "COALESCE(NULLIF(pd.site_name,''), pd_sys.site_name, '')",
        "center_area": "COALESCE(NULLIF(pd.center_area,''), pd_sys.center_area, '')",
        "team": "IFNULL(it.team_name,'')",
        "exec_date": "CAST(de.execution_date AS CHAR)",
        "visit": "CAST(rp.visit_number AS CHAR)",
        "qty": "CAST(wd.executed_qty AS CHAR)",
        "po_status": "COALESCE(NULLIF(pd.pic_status,''), pd_sys.pic_status, '')",
        "domain": (
            "COALESCE(NULLIF(pd.project_domain,''), NULLIF(pd_sys.project_domain,''), "
            "(SELECT project_domain FROM `tabProject Control Center` "
            "WHERE name = COALESCE(NULLIF(pd.project_code,''), pd_sys.project_code)), '')"
        ),
        "huawei_im": (
            "IFNULL((SELECT huawei_im FROM `tabProject Control Center` "
            "WHERE name = COALESCE(NULLIF(pd.project_code,''), pd_sys.project_code)), '')"
        ),
        "im": (
            "IFNULL(NULLIF((SELECT full_name FROM `tabIM Master` WHERE name = "
            "COALESCE(NULLIF(pd.im,''), pd_sys.im)), ''), "
            "IFNULL(COALESCE(NULLIF(pd.im,''), pd_sys.im), ''))"
        ),
        # "Project Name" has no column on PO Dispatch — it comes from the
        # Project Control Center record the project_code points at.
        "project_name": (
            "IFNULL((SELECT project_name FROM `tabProject Control Center` "
            "WHERE name = COALESCE(NULLIF(pd.project_code,''), pd_sys.project_code)), '')"
        ),
    }
    im_filter_parts = ["COALESCE(NULLIF(pd.im,''), pd_sys.im, '')"]
    if frappe.db.has_column("Rollout Plan", "im"):
        im_filter_parts.append("IFNULL(rim_rp.full_name,'')")
    if frappe.db.has_column("PO Dispatch", "im"):
        im_filter_parts.append("IFNULL(rim_pd.full_name,'')")
    col_filter_map["inet_im"] = "CONCAT_WS(' ', " + ", ".join(im_filter_parts) + ")"
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        col_filter_map["ciag"] = "IFNULL(de.ciag_status,'')"
    if frappe.db.has_column("Work Done", "submission_status"):
        col_filter_map["submission_status"] = "IFNULL(wd.submission_status,'')"
    if frappe.db.has_column("PO Dispatch", "pic_rejection_remark"):
        col_filter_map["pic_rejection_reason"] = "COALESCE(pd.pic_rejection_remark, pd_sys.pic_rejection_remark)"
    if frappe.db.has_column("Work Done", "source"):
        col_filter_map["source"] = "IFNULL(wd.source,'')"
    if frappe.db.has_column("Work Done", "issue_flag"):
        col_filter_map["issue_flag"] = "IFNULL(wd.issue_flag,'')"
    if frappe.db.has_column("PO Dispatch", "general_remark"):
        col_filter_map["general"] = "COALESCE(pd.general_remark, pd_sys.general_remark)"
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        col_filter_map["manager"] = "COALESCE(pd.manager_remark, pd_sys.manager_remark)"
    if frappe.db.has_column("PO Dispatch", "team_lead_remark"):
        col_filter_map["team_lead"] = "COALESCE(pd.team_lead_remark, pd_sys.team_lead_remark)"
    col_filter_map["activity_type"] = "IFNULL(item_wd.activity_type,'')"
    # Not backend-filterable: "domain"/"huawei_im"/"project_name" are Python
    # post-query enrichments, "milestone" is a computed badge.
    column_filters = filters.get("column_filters")
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            expr = col_filter_map.get(col_key)
            if not expr:
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat)

    like_pat = _sql_like_pattern(filters.get("search") or filters.get("q") or "")
    if like_pat:
        concat_parts = [
            "IFNULL(wd.name,'')",
            "IFNULL(wd.execution,'')",
            "IFNULL(wd.system_id,'')",
            "IFNULL(wd.item_code,'')",
            "CAST(wd.executed_qty AS CHAR)",
            # pd is via rollout-plan chain; pd_sys is direct via wd.system_id
            # (backend assignments have no rollout plan so pd is NULL)
            "COALESCE(NULLIF(pd.poid,''), NULLIF(pd_sys.poid,''), pd.name, pd_sys.name, '')",
            "COALESCE(NULLIF(pd.po_no,''), pd_sys.po_no, '')",
            "COALESCE(NULLIF(pd.project_code,''), pd_sys.project_code, '')",
            "COALESCE(NULLIF(pd.site_code,''), pd_sys.site_code, '')",
            "COALESCE(NULLIF(pd.site_name,''), pd_sys.site_name, '')",
            "COALESCE(NULLIF(pd.item_description,''), pd_sys.item_description, '')",
            "COALESCE(NULLIF(pd.center_area,''), pd_sys.center_area, '')",
            "COALESCE(NULLIF(pd.region_type,''), pd_sys.region_type, '')",
            "COALESCE(NULLIF(pd.original_dummy_poid,''), pd_sys.original_dummy_poid, '')",
            "IFNULL(it.team_name,'')",
            "COALESCE(NULLIF(pd.im,''), pd_sys.im, '')",
        ]
        if frappe.db.has_column("Work Done", "region_type"):
            concat_parts.append("IFNULL(wd.region_type,'')")
        if frappe.db.has_column("Rollout Plan", "im"):
            concat_parts.append("IFNULL(rim_rp.full_name,'')")
        if frappe.db.has_column("PO Dispatch", "im"):
            concat_parts.append("IFNULL(rim_pd.full_name,'')")
        seen_parts = set(concat_parts)
        for expr in col_filter_map.values():
            if expr not in seen_parts:
                concat_parts.append(expr)
                seen_parts.add(expr)
        concat_expr = "CONCAT_WS(' ', " + ", ".join(concat_parts) + ")"
        clause, cparams = _sql_search_clause(
            concat_expr, filters.get("search") or filters.get("q") or "",
            exact_cols=[
                "COALESCE(NULLIF(pd.poid,''), NULLIF(pd_sys.poid,''), pd.name, pd_sys.name)",
                "COALESCE(NULLIF(pd.site_code,''), pd_sys.site_code, '')",
            ],
        )
        if clause:
            wheres.append(clause)
            params.extend(cparams)

    _wd_from = (
        "`tabWork Done` wd "
        "LEFT JOIN `tabDaily Execution` de ON de.name = wd.execution "
        "LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan "
        "LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
        "LEFT JOIN `tabPO Dispatch` pd_sys ON pd_sys.name = wd.system_id "
        "LEFT JOIN `tabItem` item_wd ON item_wd.name = wd.item_code "
        "LEFT JOIN `tabINET Team` it ON it.name = IFNULL(de.team, rp.team) "
        f"{rp_im_join_wd} {pd_im_join_wd} {subcon_join_wd}"
    )
    if _options:
        _e = col_filter_map.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            _wd_from, " AND ".join(wheres), params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # Same wheres/params the row query below uses, so the headline figures
        # describe exactly the rows the table would show — at any row limit.
        #
        # What a PM actually needs off this page is "what still needs me?" and
        # "what kind of work is this?" — NOT the billing roll-up, which is the
        # PIC's job and lives on the PIC pages. So: the work mix (field vs
        # direct close vs backend), where each entry stands in the confirmation
        # flow, and anything flagged.
        # Straight off the PO line via wd_revenue_sql, so the chip and the
        # Revenue column beneath it are the same expression. This used to be
        # COALESCE(NULLIF(wd.revenue_sar, 0), pd.line_amount, ...) — a
        # workaround for revenue_sar drifting from the line, which is now
        # prevented at the source in Work Done's before_save. The NULLIF was
        # there because a stored 0 is falsy in JS but not NULL in SQL, and
        # without it the chip read 166 short of the total below it; reading
        # the line directly makes that distinction moot.
        _rev = wd_revenue_sql("wd", "pd", "pd_sys")
        _has_source = frappe.db.has_column("Work Done", "source")
        _has_sub = frappe.db.has_column("Work Done", "submission_status")
        _has_flag = frappe.db.has_column("Work Done", "issue_flag")
        _wd_metrics = [
            {"key": "entries", "label": "Entries", "agg": "count"},
            {"key": "value", "label": "Value", "agg": "sum",
             "expr": _rev, "format": "money", "tone": "good"},
        ]
        if _has_source:
            # Rows with no source stamped are legacy field work — the page
            # displays them that way too (`row.source || "Rollout Execution"`).
            _wd_metrics += [
                {"key": "field", "label": "Field", "agg": "count_if", "group": "Work mix",
                 "cond": "IFNULL(wd.source,'') IN ('Rollout Execution','')",
                 "hint": "Executed by a field team"},
                {"key": "direct_close", "label": "Direct", "agg": "count_if", "group": "Work mix",
                 "cond": "IFNULL(wd.source,'') = 'Direct Close'", "hide_if_zero": True,
                 "hint": "Closed directly, no field execution"},
                {"key": "backend", "label": "Backend", "agg": "count_if", "group": "Work mix",
                 "cond": "IFNULL(wd.source,'') = 'Backend'", "hide_if_zero": True,
                 "hint": "Backend / subcontract work"},
            ]
        if _has_sub:
            _wd_metrics += [
                {"key": "awaiting", "label": "Awaiting", "agg": "count_if", "group": "Confirmation",
                 "cond": "IFNULL(wd.submission_status,'') IN ('', 'Ready for Confirmation')",
                 "tone": "warn", "hint": "Not yet confirmed — needs PM action"},
                {"key": "confirmed", "label": "Confirmed", "agg": "count_if", "group": "Confirmation",
                 "cond": "IFNULL(wd.submission_status,'') = 'Confirmation Done'", "tone": "good"},
                {"key": "rejected", "label": "Rejected", "agg": "count_if", "group": "Confirmation",
                 "cond": "IFNULL(wd.submission_status,'') = 'PIC Rejected'", "tone": "bad",
                 "hide_if_zero": True, "hint": "Sent back by PIC — needs rework"},
            ]
        if _has_flag:
            _wd_metrics.append(
                {"key": "issues", "label": "Flagged", "agg": "count_if",
                 "cond": "IFNULL(wd.issue_flag,'') != ''", "tone": "bad", "hide_if_zero": True,
                 "hint": "Carries an issue flag (POD/PPT, TFM, partial work…)"})
        _wd_summary = summary_from_query(_wd_from, " AND ".join(wheres), params, _wd_metrics)
        # The row list is a union — fold in the synthesized subcon rows or the
        # chip undercounts the table sitting right beneath it.
        return merge_summaries(_wd_summary, _synthesize_subcon_workdone_rows(filters, _summary=1))
    id_sql = (
        f"SELECT wd.name AS wd_name, {_subcon_expr_wd} AS subcontractor, "
        f"{_contract_model_expr_wd} AS contract_model "
        "FROM `tabWork Done` wd "
        # LEFT JOIN so direct-close WDs (execution=NULL) are also included.
        "LEFT JOIN `tabDaily Execution` de ON de.name = wd.execution "
        "LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan "
        "LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
        "LEFT JOIN `tabPO Dispatch` pd_sys ON pd_sys.name = wd.system_id "
        "LEFT JOIN `tabItem` item_wd ON item_wd.name = wd.item_code "
        "LEFT JOIN `tabINET Team` it ON it.name = IFNULL(de.team, rp.team) "
        f"{rp_im_join_wd} {pd_im_join_wd} {subcon_join_wd} "
        f"WHERE {' AND '.join(wheres)} "
        "ORDER BY wd.creation DESC "
        f"{_sql_limit_suffix(lim)}"
    )
    wd_id_rows = frappe.db.sql(id_sql, tuple(params), as_dict=True)
    wd_ids = [r.wd_name for r in (wd_id_rows or []) if r.get("wd_name")]
    subcon_map = {r.wd_name: (r.subcontractor, r.contract_model) for r in (wd_id_rows or []) if r.get("wd_name")}
    if not wd_ids:
        # No regular Work Done records matched — still try synthesized backend rows
        # (dispatches with subcon_status='Work Done' but no Daily Execution/Rollout Plan).
        return _synthesize_subcon_workdone_rows(filters) or []

    order_index = {n: i for i, n in enumerate(wd_ids)}
    rows = frappe.get_all(
        "Work Done",
        filters={"name": ["in", wd_ids]},
        fields=wd_fields,
        limit_page_length=len(wd_ids) + 1,
    )
    rows.sort(key=lambda r: order_index.get(r.name, 10**9))

    # NOTE: `limit_page_length` below is deliberately `len(<names>) + 1`, not a
    # fixed heuristic cap. Each query filters by `name in <names>` against a
    # doctype's primary key, so it can never return more rows than the name
    # list itself — the exact count is always a safe, correct bound. A fixed
    # cap (there used to be one: `rel_cap`, capped at 8000) silently drops
    # matches once the row set is large enough, which desyncs ex_map/rp_map/
    # pd_map from `rows` with no error — seen once PO Dispatch alone passed
    # 17k+ rows; Work Done/"All" will eventually reach the same scale.
    exec_names = [r.execution for r in rows if r.execution]
    ex_map = {}
    if exec_names:
        de_fields = ["name", "rollout_plan", "execution_date", "execution_status", "team", "qc_status", "remarks"]
        if frappe.db.has_column("Daily Execution", "ciag_status"):
            de_fields.append("ciag_status")
        ex_rows = frappe.get_all(
            "Daily Execution",
            filters={"name": ["in", exec_names]},
            fields=de_fields,
            limit_page_length=len(exec_names) + 1,
        )
        ex_map = {e.name: e for e in ex_rows}

    plan_names = [e.rollout_plan for e in ex_map.values() if e.rollout_plan]
    rp_map = {}
    if plan_names:
        rp_fields_wd = ["name", "po_dispatch", "plan_date", "visit_type", "visit_number", "team", "creation"]
        if frappe.db.has_column("Rollout Plan", "region_type"):
            rp_fields_wd.append("region_type")
        if frappe.db.has_column("Rollout Plan", "im"):
            rp_fields_wd.append("im")
        rp_rows = frappe.get_all(
            "Rollout Plan",
            filters={"name": ["in", plan_names]},
            fields=rp_fields_wd,
            limit_page_length=len(plan_names) + 1,
        )
        rp_map = {r.name: r for r in rp_rows}

    dispatch_names = [r.po_dispatch for r in rp_map.values() if r.po_dispatch]
    # Also include dispatches reachable via wd.system_id for backend assignments
    # where de.rollout_plan is NULL (no rollout plan chain).
    known = set(dispatch_names)
    sys_id_extras = [r.system_id for r in rows if r.get("system_id") and r.system_id not in known]
    all_dispatch_names = dispatch_names + sys_id_extras
    pd_map = {}
    if all_dispatch_names:
        pd_fields_wd = ["name", "po_no", "project_code", "site_name", "site_code", "item_code", "item_description", "customer", "line_amount", "po_line_no", "dispatch_status", "is_dummy_po"]
        for opt in ("general_remark", "manager_remark", "team_lead_remark"):
            if frappe.db.has_column("PO Dispatch", opt):
                pd_fields_wd.append(opt)
        if frappe.db.has_column("PO Dispatch", "poid"):
            pd_fields_wd.append("poid")
        if frappe.db.has_column("PO Dispatch", "im"):
            pd_fields_wd.append("im")
        if frappe.db.has_column("PO Dispatch", "huawei_im"):
            pd_fields_wd.append("huawei_im")
        if frappe.db.has_column("PO Dispatch", "center_area"):
            pd_fields_wd.append("center_area")
        if frappe.db.has_column("PO Dispatch", "region_type"):
            pd_fields_wd.append("region_type")
        if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
            pd_fields_wd.append("original_dummy_poid")
        if frappe.db.has_column("PO Dispatch", "pic_status"):
            pd_fields_wd.append("pic_status")
        if frappe.db.has_column("PO Dispatch", "pic_status_ms2"):
            pd_fields_wd.append("pic_status_ms2")
        if frappe.db.has_column("PO Dispatch", "subcon_submission_status"):
            pd_fields_wd.append("subcon_submission_status")
        if frappe.db.has_column("PO Dispatch", "pic_rejection_remark"):
            pd_fields_wd.append("pic_rejection_remark")
        pd_rows = frappe.get_all(
            "PO Dispatch",
            filters={"name": ["in", all_dispatch_names]},
            fields=pd_fields_wd,
            limit_page_length=len(all_dispatch_names) + 1,
        )
        pd_map = {p.name: p for p in pd_rows}

    team_prefetch = set()
    for ex in ex_map.values():
        if ex.team:
            team_prefetch.add(ex.team)
    for rp in rp_map.values():
        if rp.team:
            team_prefetch.add(rp.team)
    im_prefetch = set()
    for pd in pd_map.values():
        if pd.get("im"):
            im_prefetch.add(pd.im)
    if frappe.db.has_column("Rollout Plan", "im"):
        for rp in rp_map.values():
            if rp.get("im"):
                im_prefetch.add(rp.im)
    for r in rows:
        if r.get("direct_close_by"):
            im_prefetch.add(r["direct_close_by"])
    team_name_map_wd = _batch_inet_team_names(list(team_prefetch))
    im_name_map_wd = _batch_im_master_full_names(list(im_prefetch))

    project_codes = {pd.project_code for pd in pd_map.values() if pd.get("project_code")}
    project_name_map = {}
    if project_codes:
        try:
            proj_rows = frappe.get_all(
                "Project Control Center",
                filters={"name": ["in", list(project_codes)]},
                fields=["name", "project_name"],
                limit_page_length=len(project_codes) + 1,
            )
            project_name_map = {p.name: p.project_name for p in proj_rows}
        except Exception:
            project_name_map = {}

    out = []
    for r in rows:
        ex = ex_map.get(r.execution)
        rp = rp_map.get(ex.rollout_plan) if ex and ex.rollout_plan else None
        # Primary: via rollout-plan chain. Fallback: via wd.system_id (backend
        # assignments where no rollout plan exists).
        pd = (pd_map.get(rp.po_dispatch) if rp and rp.po_dispatch else None) \
             or pd_map.get(r.get("system_id"))
        team = (rp.team if rp else None) or (ex.team if ex else None)
        project_code = pd.project_code if pd else None
        ex_date = ex.execution_date if ex else None
        rp_im_row = rp.get("im") if rp and frappe.db.has_column("Rollout Plan", "im") else None
        pd_im_row = pd.get("im") if pd else None
        im_row = rp_im_row or pd_im_row
        # Billing status now follows the PIC's invoice status. The PM/IM
        # bucket (Pending / Invoiced / Closed) is rolled up from the 11-value
        # PIC scale so existing widgets/filters keep working. Falls back to
        # the legacy stored billing_status on sites that haven't migrated
        # the new pic_status column yet.
        pic_status_val = pd.get("pic_status") if pd and "pic_status" in pd else None
        billing_override = _billing_status_from_pic(pic_status_val, r.get("billing_status"))
        subcon_row = subcon_map.get(r.name) or (None, None)
        out.append(
            {
                **r,
                "billing_status": billing_override,
                "subcontractor": subcon_row[0],
                "contract_model": subcon_row[1],
                "pic_status": pic_status_val,
                "pic_status_ms2": pd.get("pic_status_ms2") if pd else None,
                "rollout_plan": ex.rollout_plan if ex else None,
                "po_dispatch": (rp.po_dispatch if rp else None) or r.get("system_id"),
                # Business POID from dispatch (fall back to dispatch name on legacy docs).
                "poid": ((pd.get("poid") if pd else None) or (pd.name if pd else None) or (rp.po_dispatch if rp else None) or r.get("system_id")),
                "po_no": pd.po_no if pd else None,
                "project_code": project_code,
                "site_name": pd.site_name if pd else None,
                "site_code": pd.site_code if pd else None,
                "center_area": pd.get("center_area") if pd else None,
                "region_type": r.get("region_type")
                or (rp.get("region_type") if rp else None)
                or (pd.get("region_type") if pd else None),
                "team": team,
                "team_name": team_name_map_wd.get(team) if team else None,
                "im": im_row,
                "im_full_name": im_name_map_wd.get(im_row) if im_row else None,
                "huawei_im": pd.get("huawei_im") if pd else None,
                "item_code": pd.item_code if pd else None,
                "item_description": pd.item_description if pd else None,
                "customer": pd.get("customer") if pd else None,
                "execution_date": ex_date,
                "execution_status": ex.execution_status if ex else None,
                "qc_status": ex.get("qc_status") if ex else None,
                "ciag_status": ex.get("ciag_status") if ex else None,
                "execution_remarks": ex.get("remarks") if ex else None,
                "plan_date": rp.plan_date if rp else None,
                "visit_type": rp.visit_type if rp else None,
                "visit_number": rp.get("visit_number") if rp else None,
                "planning_timestamp": rp.get("creation") if rp else None,
                "dispatch_seq": pd.get("po_line_no") if pd else None,
                "dispatch_status": pd.get("dispatch_status") if pd else None,
                "line_amount": pd.get("line_amount") if pd else None,
                "project_name": project_name_map.get(project_code) if project_code else None,
                "general_remark": pd.get("general_remark") if pd else None,
                "manager_remark": pd.get("manager_remark") if pd else None,
                "is_dummy_po": pd.get("is_dummy_po") if pd else None,
                "team_lead_remark": pd.get("team_lead_remark") if pd else None,
                "pic_rejection_remark": pd.get("pic_rejection_remark") if pd else None,
                "original_dummy_poid": (
                    (pd.get("original_dummy_poid") or "").strip()
                    if pd and frappe.db.has_column("PO Dispatch", "original_dummy_poid")
                    else None
                ),
                "direct_close_by_full_name": (
                    im_name_map_wd.get(r["direct_close_by"])
                    if r.get("direct_close_by") else None
                ),
            }
        )
    if out:
        act_map = _batch_item_activity_types(out)
        for r in out:
            r["activity_type"] = act_map.get(r.get("item_code") or "")

    # ── Sub-Contract completions: synthesize Work Done rows for PO Dispatches
    # whose subcon_status='Work Done'. Subcon flow lives outside the rollout
    # chain (no Daily Execution / Rollout Plan / Work Done record), so we union
    # them in here as flagged synthetic rows so they show up in the same list.
    # When exclude_backend is set the caller wants only field-execution rows
    # (Rollout Plan → Daily Execution → Work Done), so skip subcon entirely.
    subcon_rows = [] if filters.get("exclude_backend") else _synthesize_subcon_workdone_rows(filters)
    if subcon_rows:
        out.extend(subcon_rows)
        def _wd_sort_key(r):
            ex = r.get("execution_date")
            # Direct-close and backend rows have no execution_date — use the
            # date portion of modified so they sort chronologically with other rows.
            date_str = str(ex) if ex else str(r.get("modified") or "")[:10]
            return (date_str, str(r.get("modified") or ""))
        out.sort(key=_wd_sort_key, reverse=True)
    # Re-apply the row limit after combining regular + subcon rows so the total
    # never exceeds the caller's requested limit. lim=0 means unlimited — skip slice.
    if lim:
        out = out[:lim]
    _enrich_with_project_fields(out)
    _apply_dummy_description(out)
    return out


def _synthesize_subcon_workdone_rows(filters, _summary=None):
    """Build Work-Done-shaped rows from PO Dispatches with subcon_status='Work Done'.

    Honors the same filters as ``list_work_done_rows``:
        billing_status, dispatch_status, from_date / to_date, team, project_code,
        site_code, im, search.
    Subcon dispatches don't carry a billing_status; if the caller filtered to a
    specific real billing_status (Confirmed/Submitted/etc.), they're excluded.
    The ``team`` filter is matched against ``pd.backend_team`` (not the rollout team).
    """
    f = filters or {}

    # Billing status filter — subcon rows are emitted as `billing_status='Pending'`.
    # Only include them when the filter allows Pending (or is unset).
    bs_vals = _ensure_list(f.get("billing_status"))
    if bs_vals:
        accept = {"", "pending", "all"}
        if not any(str(v).strip().lower() in accept for v in bs_vals):
            return []

    # Work-type toggle (Field Work / Backend / Direct Close) — every
    # synthesized row here is emitted with source="Backend" (see below), so
    # skip generating them entirely when the caller filtered to some other
    # source.
    source_vals_sub = _ensure_list(f.get("source"))
    if source_vals_sub and "Backend" not in source_vals_sub:
        return []

    # execution_status is hardcoded "Completed" for every synthesized row
    # (see the row-building block below) — skip entirely if the filter
    # excludes that value.
    exec_status_vals_sub = _ensure_list(f.get("execution_status"))
    if exec_status_vals_sub and "Completed" not in exec_status_vals_sub:
        return []

    # issue_flag is never set on synthesized rows (always empty) — skip
    # entirely unless the filter explicitly wants "no flag" or is unset.
    issue_flag_vals_sub = _ensure_list(f.get("issue_flag"))
    if issue_flag_vals_sub and "__NONE__" not in issue_flag_vals_sub:
        return []

    where = [
        "IFNULL(pd.subcon_status,'') = 'Work Done'",
        # Exclude dispatches that already have a real Work Done record — they are
        # returned by list_work_done_rows via the regular LEFT JOIN path.
        "NOT EXISTS (SELECT 1 FROM `tabWork Done` wd WHERE wd.system_id = pd.name)",
    ]
    params = []

    # Same Subcontract Master resolution as list_work_done_rows' main path
    # (and PIC before it): an explicit override on the dispatch itself, else
    # fall back to the executing team's own subcontractor.
    subcon_join_sub = ""
    _subcon_expr_sub = "NULL"
    _contract_model_expr_sub = "NULL"
    _subcon_id_expr_sub = "NULL"
    if frappe.db.has_column("PO Dispatch", "contract") and frappe.db.exists("DocType", "Subcontract Master"):
        subcon_join_sub = (
            "LEFT JOIN `tabSubcontract Master` sm_pd ON sm_pd.name = pd.contract "
            "LEFT JOIN `tabSubcontract Master` sm_t ON sm_t.name = t.subcontractor "
        )
        _subcon_expr_sub = "COALESCE(sm_pd.subcontractor_name, sm_t.subcontractor_name)"
        _contract_model_expr_sub = "COALESCE(sm_pd.contract_model, sm_t.contract_model)"
        _subcon_id_expr_sub = "COALESCE(sm_pd.name, sm_t.name)"

    for col, key in (
        ("pd.project_code", "project_code"),
        ("pd.site_code", "site_code"),
        ("pd.backend_team", "team"),
        ("pd.dispatch_status", "dispatch_status"),
    ):
        c, p = _sql_in_or_eq(col, f.get(key))
        if c:
            where.append(c)
            params.extend(p)

    # Same milestone-based resolution check as list_work_done_rows (see there
    # for the full rationale). These synthesized rows never come from a
    # milestone-scoped Direct Close (that path always creates a real Work
    # Done record), so every row here always represents the WHOLE line —
    # only the "normal row" branch applies: hidden once MS1 is terminal AND
    # (MS2 doesn't apply, or is itself terminal too).
    if frappe.db.has_column("PO Dispatch", "pic_status") and frappe.db.has_column("PO Dispatch", "pic_status_ms2"):
        terminal_ms_sub = list(_DATA_INTEGRITY_TERMINAL_MS)
        ph_ms_sub = ", ".join(["%s"] * len(terminal_ms_sub))
        where.append(
            "NOT ("
            f"  IFNULL(pd.pic_status,'') IN ({ph_ms_sub})"
            f"  AND (IFNULL(pd.ms2_amount,0) = 0 OR IFNULL(pd.pic_status_ms2,'') IN ({ph_ms_sub}))"
            ")"
        )
        params.extend(terminal_ms_sub)
        params.extend(terminal_ms_sub)

    subcontractor_vals = _ensure_list(f.get("subcontractor"))
    if subcontractor_vals and subcon_join_sub:
        ph_sc = ", ".join(["%s"] * len(subcontractor_vals))
        where.append(f"{_subcon_id_expr_sub} IN ({ph_sc})")
        params.extend(subcontractor_vals)

    im_vals = _ensure_list(f.get("im"))
    if im_vals:
        ph = ", ".join(["%s"] * len(im_vals))
        where.append(f"IFNULL(pd.im,'') IN ({ph})")
        params.extend(im_vals)
    if f.get("from_date"):
        where.append("pd.subcon_completed_on >= %s")
        params.append(f["from_date"])
    if f.get("to_date"):
        where.append("pd.subcon_completed_on <= %s")
        params.append(f["to_date"])

    submission_vals_sub = _ensure_list(f.get("submission_status"))
    if submission_vals_sub and frappe.db.has_column("PO Dispatch", "subcon_submission_status"):
        none_wanted_sub = "__NONE__" in submission_vals_sub
        real_vals_sub = [v for v in submission_vals_sub if v != "__NONE__"]
        parts_sub = []
        if none_wanted_sub:
            parts_sub.append("IFNULL(pd.subcon_submission_status,'') = ''")
        if real_vals_sub:
            ph_sub = ", ".join(["%s"] * len(real_vals_sub))
            parts_sub.append(f"pd.subcon_submission_status IN ({ph_sub})")
            params.extend(real_vals_sub)
        if parts_sub:
            where.append("(" + " OR ".join(parts_sub) + ")")
    elif submission_vals_sub:
        # Column doesn't exist on this site — subcon_submission_status is
        # always effectively empty, so only "__NONE__" (or unset) can match.
        if "__NONE__" not in submission_vals_sub:
            return []

    # "tab" - mirrors list_work_done_rows' own tab split (see there for the
    # rationale). Without this, these synthesized rows were appended to
    # EVERY tab's result unconditionally, regardless of their real status -
    # the actual cause of the cross-tab overlap this guard fixes.
    # Note: unlike the real Work Done query, synthesized rows never surface
    # pic_rejection_remark in their output (pre-existing, this row type has
    # no such field emitted below) - so unlike list_work_done_rows' own tab
    # split, only subcon_submission_status is checked here, not that column.
    if frappe.db.has_column("PO Dispatch", "subcon_submission_status"):
        tab_scope_sub = (f.get("tab") or "active").strip().lower()
        if tab_scope_sub == "confirmed":
            where.append("IFNULL(pd.subcon_submission_status,'') = 'Confirmation Done'")
        elif tab_scope_sub == "pic_rejected":
            where.append("IFNULL(pd.subcon_submission_status,'') = 'PIC Rejected'")
        elif tab_scope_sub == "active":
            where.append(
                "IFNULL(pd.subcon_submission_status,'') NOT IN ('Confirmation Done', 'PIC Rejected')"
            )

    search = f.get("search") or f.get("q") or ""
    if search:
        clause, like_params = _sql_search_clause(
            "CONCAT_WS(' ', "
            "IFNULL(pd.poid,''), IFNULL(pd.po_no,''), IFNULL(pd.item_code,''), "
            "IFNULL(pd.item_description,''), IFNULL(pd.site_name,''), "
            "IFNULL(pd.site_code,''), IFNULL(pd.project_code,''), "
            "IFNULL(pd.center_area,''), IFNULL(pd.region_type,''), "
            "IFNULL(t.team_id,''), IFNULL(t.team_name,''), IFNULL(pd.im,''))",
            search,
            exact_cols=["IFNULL(pd.poid,'')", "IFNULL(pd.site_code,'')"],
        )
        if clause:
            where.append(clause)
            params.extend(like_params)

    # Per-column "Manage Table" filters. These synthesized rows have no
    # execution/rollout-plan chain, so only a subset of columns resolve here;
    # a filter on a column that doesn't apply to subcon rows (execution
    # status, QC, billing, etc.) must exclude these rows rather than show
    # them unconditionally, which is exactly the bug this guards against.
    _subcon_desc_expr = (
        "CASE WHEN IFNULL(pd.is_dummy_po,0) = 1 AND IFNULL(pd.item_description,'') = '' "
        "THEN IFNULL(pd.manager_remark,'') ELSE IFNULL(pd.item_description,'') END"
        if frappe.db.has_column("PO Dispatch", "is_dummy_po") and frappe.db.has_column("PO Dispatch", "manager_remark")
        else "IFNULL(pd.item_description,'')"
    )
    col_filter_map = {
        "project_code": "IFNULL(pd.project_code,'')",
        "poid": "COALESCE(NULLIF(pd.poid,''), pd.name)",
        "duid": "IFNULL(pd.site_code,'')",
        "item_code": "IFNULL(pd.item_code,'')",
        "item_description": _subcon_desc_expr,
        "description": _subcon_desc_expr,
        "line_amount": "CAST(pd.line_amount AS CHAR)",
        "region": "IFNULL(pd.region_type,'')",
        "assigned_team": "IFNULL(t.team_name,'')",
        "dispatch_status": "IFNULL(pd.dispatch_status,'')",
    }
    if frappe.db.has_column("PO Dispatch", "general_remark"):
        col_filter_map["general"] = "IFNULL(pd.general_remark,'')"
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        col_filter_map["manager"] = "IFNULL(pd.manager_remark,'')"
    if frappe.db.has_column("PO Dispatch", "team_lead_remark"):
        col_filter_map["team_lead"] = "IFNULL(pd.team_lead_remark,'')"
    col_filter_map["activity_type"] = (
        "IFNULL((SELECT activity_type FROM `tabItem` WHERE name = pd.item_code), '')"
    )
    col_filter_map["subcontract"] = f"IFNULL({_subcon_expr_sub},'')"
    col_filter_map["contract_model"] = f"IFNULL({_contract_model_expr_sub},'')"
    column_filters = f.get("column_filters")
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map.get(col_key), raw_val)
                if _c:
                    where.append(_c)
                    params.extend(_p)
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            expr = col_filter_map.get(col_key)
            if expr:
                where.append(f"{expr} LIKE %s")
                params.append(pat)
            else:
                where.append("1=0")

    sub_sub_col = (
        "pd.subcon_submission_status AS subcon_submission_status"
        if frappe.db.has_column("PO Dispatch", "subcon_submission_status")
        else "'' AS subcon_submission_status"
    )
    sql = (
        "SELECT pd.name AS po_dispatch, pd.poid AS poid, pd.po_no, pd.po_line_no, "
        "pd.project_code, pd.site_code, pd.site_name, pd.center_area, pd.region_type, "
        "pd.item_code, pd.item_description, pd.customer, pd.line_amount, "
        "pd.dispatch_status, pd.im, "
        "pd.backend_team, pd.subcon_status, pd.subcon_completed_on, pd.subcon_remark, "
        f"{sub_sub_col}, "
        f"{_remark_select()}, "
        "t.team_id AS backend_team_id, t.team_name AS backend_team_name, "
        f"{_subcon_expr_sub} AS subcontractor, {_contract_model_expr_sub} AS contract_model, "
        "pd.modified "
        "FROM `tabPO Dispatch` pd "
        "LEFT JOIN `tabINET Team` t ON t.name = pd.backend_team "
        f"{subcon_join_sub} "
        f"WHERE {' AND '.join(where)} "
        "ORDER BY pd.subcon_completed_on DESC, pd.modified DESC"
    )
    if _summary:
        # These rows are always emitted as billing_status "Pending", qty NULL
        # and revenue = the dispatch's own line_amount — see the row builder
        # below. The metric keys mirror list_work_done_rows' so merge_summaries
        # can fold the two together.
        _sub_status = (
            "IFNULL(pd.subcon_submission_status,'')"
            if frappe.db.has_column("PO Dispatch", "subcon_submission_status")
            else "''"
        )
        return summary_from_query(
            f"`tabPO Dispatch` pd LEFT JOIN `tabINET Team` t ON t.name = pd.backend_team {subcon_join_sub}",
            " AND ".join(where), params, [
                {"key": "entries", "label": "Entries", "agg": "count"},
                {"key": "value", "label": "Value", "agg": "sum",
                 "expr": "IFNULL(pd.line_amount, 0)", "format": "money", "tone": "good"},
                # Every synthesized row is emitted with source="Backend".
                {"key": "backend", "label": "Backend", "agg": "count", "group": "Work mix"},
                {"key": "awaiting", "label": "Awaiting", "agg": "count_if", "group": "Confirmation",
                 "cond": f"{_sub_status} IN ('', 'Ready for Confirmation')", "tone": "warn"},
                {"key": "confirmed", "label": "Confirmed", "agg": "count_if", "group": "Confirmation",
                 "cond": f"{_sub_status} = 'Confirmation Done'", "tone": "good"},
                {"key": "rejected", "label": "Rejected", "agg": "count_if", "group": "Confirmation",
                 "cond": f"{_sub_status} = 'PIC Rejected'", "tone": "bad"},
            ],
        )
    rows = frappe.db.sql(sql, tuple(params), as_dict=True) or []
    if not rows:
        return []

    project_codes = {r.project_code for r in rows if r.get("project_code")}
    project_name_map = {}
    if project_codes:
        try:
            proj_rows = frappe.get_all(
                "Project Control Center",
                filters={"name": ["in", list(project_codes)]},
                fields=["name", "project_name"],
                limit_page_length=len(project_codes) + 1,
            )
            project_name_map = {p.name: p.project_name for p in proj_rows}
        except Exception:
            project_name_map = {}

    im_prefetch = list({r.im for r in rows if r.get("im")})
    im_name_map = _batch_im_master_full_names(im_prefetch) if im_prefetch else {}

    out = []
    act_map = _batch_item_activity_types(rows)
    for r in rows:
        out.append({
            # Synthetic name so React/UI keys stay unique. There's no Work Done
            # doctype row backing this entry — anything that tries to mutate by
            # `name` should check `is_subcon` first.
            "name": f"SUBCON-{r.get('po_dispatch')}",
            "execution": None,
            "system_id": r.get("po_dispatch"),
            "poid": r.get("poid") or r.get("po_dispatch"),
            "po_dispatch": r.get("po_dispatch"),
            "po_no": r.get("po_no"),
            "project_code": r.get("project_code"),
            "project_name": project_name_map.get(r.get("project_code")),
            "site_code": r.get("site_code"),
            "site_name": r.get("site_name"),
            "center_area": r.get("center_area"),
            "region_type": r.get("region_type"),
            "team": r.get("backend_team"),
            "team_name": r.get("backend_team_name") or r.get("backend_team_id") or r.get("backend_team"),
            "subcontractor": r.get("subcontractor"),
            "contract_model": r.get("contract_model"),
            "im": r.get("im"),
            "im_full_name": im_name_map.get(r.get("im")),
            "item_code": r.get("item_code"),
            "item_description": r.get("item_description"),
            "customer": r.get("customer"),
            "activity_type": act_map.get(r.get("item_code") or ""),
            "executed_qty": None,
            "billing_rate_sar": None,
            "revenue_sar": r.get("line_amount"),
            "team_cost_sar": None,
            "subcontract_cost_sar": None,
            "total_cost_sar": None,
            "margin_sar": None,
            "billing_status": "Pending",
            "submission_status": r.get("subcon_submission_status") or "",
            "execution_date": r.get("subcon_completed_on"),
            "execution_status": "Completed",
            "qc_status": None,
            "ciag_status": None,
            "execution_remarks": r.get("subcon_remark"),
            "plan_date": None,
            "visit_type": "Sub-Contract",
            "visit_number": None,
            "planning_timestamp": None,
            "dispatch_seq": r.get("po_line_no"),
            "dispatch_status": r.get("dispatch_status"),
            "line_amount": r.get("line_amount"),
            "general_remark": r.get("general_remark"),
            "manager_remark": r.get("manager_remark"),
            "team_lead_remark": r.get("team_lead_remark"),
            "original_dummy_poid": None,
            "modified": r.get("modified"),
            "is_subcon": 1,
            "source": "Backend",
        })
    return out


# pic_status values that are safe to clear when IM un-confirms — no PIC work
# has been done yet. Anything beyond these means the PIC team is already
# processing the row and must be coordinated with manually.
_PIC_ENTRY_STATUSES = frozenset({"", "Work Not Done", "Under Process to Apply"})


def _revert_pic_status_if_safe(po_dispatch_name):
    """Clear pic_status on PO Dispatch when IM un-confirms Work Done, if safe.

    Returns a warning string when pic_status has progressed past the entry
    point and was therefore NOT cleared automatically.
    """
    if not po_dispatch_name:
        return None
    current = frappe.db.get_value("PO Dispatch", po_dispatch_name, "pic_status") or ""
    if current in _PIC_ENTRY_STATUSES:
        if current:  # blank already needs no write
            frappe.db.set_value(
                "PO Dispatch", po_dispatch_name, "pic_status", "",
                update_modified=False,
            )
        return None
    return (
        f"PIC status is already '{current}' — Work Done confirmation was cleared "
        "but pic_status was NOT reverted automatically. Coordinate with the PIC team."
    )


@frappe.whitelist()
def bulk_submit_work_done(payload=None):
    """
    Bulk-update submission_status for multiple Work Done rows.
    Optionally attaches one or more shared files to each linked PO Dispatch.

    payload: {
        work_done_names: list[str],
        submission_status: str,
        note: str (optional),
        file_urls: { slot: url | [url, ...] } (optional, e.g.
            {"im_doc1": ["/files/a.pdf", "/files/b.pdf"]} - each URL becomes
            its own File record under that slot, for every selected row)
    }
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload) if payload else {}
    payload = payload or {}

    work_done_names = _ensure_list(payload.get("work_done_names") or [])
    status = (payload.get("submission_status") or "").strip()
    note = payload.get("note") or None
    file_urls = payload.get("file_urls") or {}

    if not work_done_names:
        frappe.throw("No work done rows specified")
    if status not in ("", "Ready for Confirmation", "Confirmation Done"):
        frappe.throw(f"Invalid submission status: {status}")

    ALLOWED_SLOTS = {"im_doc1", "im_doc2", "im_doc2a", "im_doc2b", "im_doc2c"}

    def _resolve_po_dispatch(wd_name):
        pd = frappe.db.get_value("Work Done", wd_name, "system_id") or ""
        if pd:
            return pd
        execution = frappe.db.get_value("Work Done", wd_name, "execution") or ""
        if execution:
            rp = frappe.db.get_value("Daily Execution", execution, "rollout_plan") or ""
            if rp:
                return frappe.db.get_value("Rollout Plan", rp, "po_dispatch") or ""
        return ""

    updated = 0
    errors = []

    for wd_name in work_done_names:
        try:
            po_dispatch = _resolve_po_dispatch(wd_name)
            if po_dispatch and file_urls:
                for slot, urls in file_urls.items():
                    if slot not in ALLOWED_SLOTS:
                        continue
                    url_list = urls if isinstance(urls, (list, tuple)) else [urls]
                    for url in url_list:
                        if not url:
                            continue
                        frappe.get_doc({
                            "doctype": "File",
                            "file_url": url,
                            "attached_to_doctype": "PO Dispatch",
                            "attached_to_name": po_dispatch,
                            "attached_to_field": slot,
                        }).insert(ignore_permissions=True)
            update_work_done_submission(wd_name, status, note)
            updated += 1
        except Exception as e:
            errors.append({"name": wd_name, "error": str(e)})

    frappe.db.commit()
    return {"updated": updated, "errors": errors}


@frappe.whitelist()
def update_work_done_submission(name, submission_status, note=None):
    """IM sets Work Done submission status: 'Ready for Confirmation' or
    'Confirmation Done'. Optional note saved to PO Dispatch.im_confirmation_note."""
    name = (name or "").strip()
    status = (submission_status or "").strip()
    if not name:
        frappe.throw("name is required")
    if status not in ("Ready for Confirmation", "Confirmation Done", ""):
        frappe.throw("Invalid submission_status")
    if not frappe.db.exists("Work Done", name):
        frappe.throw(f"Work Done not found: {name}")
    frappe.db.set_value("Work Done", name, "submission_status", status, update_modified=True)

    # Notify PIC when IM confirms (db.set_value doesn't fire on_update hooks)
    if status == "Confirmation Done":
        try:
            from inet_app.api.notifications import notify_pic_work_done_submitted
            notify_pic_work_done_submitted(name)
        except Exception:
            pass

    # Resolve PO Dispatch via rollout-plan chain; fall back to Work Done.system_id
    chain_row = frappe.db.sql(
        """
        SELECT rp.po_dispatch
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        WHERE wd.name = %s
        LIMIT 1
        """,
        name, as_dict=True,
    )
    po_dispatch = (
        (chain_row[0].get("po_dispatch") if chain_row else None)
        or frappe.db.get_value("Work Done", name, "system_id")
    )

    pic_warning = None
    if po_dispatch:
        if status == "Confirmation Done":
            # Determine which milestone(s) this Work Done covers.
            # MS2-only direct-close → update pic_status_ms2.
            # MS1 close or non-milestone → update pic_status (legacy / default).
            ms_vals = {}
            if frappe.db.has_column("Work Done", "ms1_closed"):
                ms_vals = frappe.db.get_value("Work Done", name, ["ms1_closed", "ms2_closed"], as_dict=True) or {}
            ms1_cl = cint(ms_vals.get("ms1_closed") or 0)
            ms2_cl = cint(ms_vals.get("ms2_closed") or 0)
            if ms1_cl or not ms2_cl:
                current_pic = frappe.db.get_value("PO Dispatch", po_dispatch, "pic_status") or ""
                if current_pic in {"", "Work Not Done"}:
                    frappe.db.set_value(
                        "PO Dispatch", po_dispatch, "pic_status", "Under Process to Apply",
                        update_modified=False,
                    )
            if ms2_cl and frappe.db.has_column("PO Dispatch", "pic_status_ms2"):
                current_pic_ms2 = frappe.db.get_value("PO Dispatch", po_dispatch, "pic_status_ms2") or ""
                if current_pic_ms2 in {"", "Work Not Done"}:
                    frappe.db.set_value(
                        "PO Dispatch", po_dispatch, "pic_status_ms2", "Under Process to Apply",
                        update_modified=False,
                    )
            if frappe.db.has_column("PO Dispatch", "pic_rejection_remark"):
                frappe.db.set_value(
                    "PO Dispatch", po_dispatch, "pic_rejection_remark", "",
                    update_modified=False,
                )
            if note is not None and frappe.db.has_column("PO Dispatch", "im_confirmation_note"):
                frappe.db.set_value(
                    "PO Dispatch", po_dispatch, "im_confirmation_note", (note or "").strip(),
                    update_modified=False,
                )
            # Map ISDP Owner and iBuy Owner from Project Control Center
            project_code = frappe.db.get_value("PO Dispatch", po_dispatch, "project_code")
            if project_code and frappe.db.exists("Project Control Center", project_code):
                proj_owners = frappe.db.get_value(
                    "Project Control Center", project_code, ["isdp_owner", "ibuy_owner"], as_dict=True
                ) or {}
                owner_update = {}
                if proj_owners.get("isdp_owner"):
                    owner_update["isdp_owner"] = proj_owners["isdp_owner"]
                if proj_owners.get("ibuy_owner"):
                    owner_update["ibuy_owner"] = proj_owners["ibuy_owner"]
                if owner_update:
                    frappe.db.set_value("PO Dispatch", po_dispatch, owner_update, update_modified=False)

            # Stamp subcontractor onto PO Dispatch (only if not already set)
            if frappe.db.has_column("PO Dispatch", "contract"):
                existing_contract = frappe.db.get_value("PO Dispatch", po_dispatch, "contract")
                if not existing_contract:
                    sub_row = frappe.db.sql(
                        """
                        SELECT it.subcontractor
                        FROM `tabWork Done` wd
                        JOIN `tabDaily Execution` de ON de.name = wd.execution
                        JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
                        JOIN `tabINET Team` it ON it.name = rp.team
                        WHERE wd.name = %s AND IFNULL(it.subcontractor, '') != ''
                        LIMIT 1
                        """,
                        name, as_dict=True,
                    )
                    if sub_row:
                        frappe.db.set_value(
                            "PO Dispatch", po_dispatch, "contract", sub_row[0].subcontractor,
                            update_modified=False,
                        )
        else:
            # IM is un-confirming — clear pic_status if nothing has been processed yet
            pic_warning = _revert_pic_status_if_safe(po_dispatch)

    frappe.db.commit()
    result = {"name": name, "submission_status": status}
    if pic_warning:
        result["pic_warning"] = pic_warning
    return result


@frappe.whitelist()
def submit_milestone_to_pic(work_done, milestone):
    """IM explicitly submits a closed milestone to PIC from the Work Done page.
    milestone = 'MS1' or 'MS2'.
    Sets pic_status (MS1) or pic_status_ms2 (MS2) on the linked PO Dispatch to
    'Under Process to Apply', only if the milestone is closed on the Work Done
    and the PIC field is still empty / 'Work Not Done'.
    """
    milestone = (milestone or "").strip().upper()
    if milestone not in ("MS1", "MS2"):
        frappe.throw("milestone must be MS1 or MS2")

    closed_field = "ms1_closed" if milestone == "MS1" else "ms2_closed"
    pic_field    = "pic_status"  if milestone == "MS1" else "pic_status_ms2"

    wd_vals = frappe.db.get_value("Work Done", work_done,
        [closed_field, "system_id"], as_dict=True)
    if not wd_vals:
        frappe.throw("Work Done not found")
    if not cint(wd_vals.get(closed_field)):
        frappe.throw(f"{milestone} is not closed on this Work Done")

    po_dispatch = wd_vals.get("system_id")
    if not po_dispatch:
        frappe.throw("Work Done is not linked to a PO Dispatch")

    current = frappe.db.get_value("PO Dispatch", po_dispatch, pic_field) or ""
    if current not in ("", "Work Not Done"):
        frappe.throw(f"{milestone} has already been submitted to PIC (current status: {current})")

    frappe.db.set_value("PO Dispatch", po_dispatch, pic_field,
                        "Under Process to Apply", update_modified=False)
    frappe.db.commit()
    return {"ok": True, "milestone": milestone, "pic_field": pic_field,
            "po_dispatch": po_dispatch, "new_status": "Under Process to Apply"}


@frappe.whitelist()
def list_legacy_milestones_needing_resubmission(filters=None, limit=500, _options=None):
    """All PO Dispatch lines owned by the calling IM with zero Work Done
    records at all — legacy / archive-imported lines whose work (and often
    its original PIC submission) already happened historically, outside
    this system, so there's no Work Done page entry for the IM to act
    through. This is a visibility/reference list, not a queue gated on
    pic_status — every matching line stays listed regardless of its
    current milestone status, so the IM always has a place to look up old
    data and attach a supporting document if one still needs to go in.
    ms1_needs/ms2_needs only gate whether resubmit_legacy_milestone_to_pic()
    is still usable for that milestone (blocked once it's genuinely
    finished — see _DATA_INTEGRITY_TERMINAL_MS), not whether the row shows
    up here at all.

    filters (all optional, filtered in SQL like every other list_* on this
    page — never filtered client-side from an already-loaded batch):
      search: free text across poid/po_no/project_code/site_code/name
      project_code, site_code, dispatch_status: list or single value
      column_filters: { <col_key>: text } from the Manage Table per-column
        filter row on IMWorkDone.jsx's LegacyResubmitTable (table-key
        im-workdone-v1-legacy) — keys are the slugified column headers.
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters) if filters else {}
    filters = filters or {}

    _require_inet_im_session()
    caller_im = _resolve_caller_im_or_throw()
    # 0 = "All" (TABLE_ROW_LIMIT_ALL) — genuinely unlimited, no LIMIT clause.
    # Production can have far more of these than the dev site does.
    limit_page_length = _portal_row_limit(limit, 500)

    wheres = [
        "pd.im = %s",
        "IFNULL(pd.is_internal_work, 0) = 0",
        "IFNULL(pd.is_dummy_po, 0) = 0",
        # A legacy line with no Work Done record can still have its own
        # pic_status/pic_status_ms2 actively worked by PIC right now (those
        # live on PO Dispatch independent of any Work Done record) — so it
        # can progress through Partially Submitted/Submitted/Partially
        # Closed same as any other line, well before (or even without ever)
        # reaching literal Closed. Excluding those would drop a line that
        # still has one milestone genuinely needing resubmission — see
        # inet_app.api.pic._compute_dispatch_status_from_pic.
        "pd.dispatch_status IN ('Completed', 'Partially Submitted', 'Submitted', 'Partially Closed', 'Closed')",
        "NOT EXISTS (SELECT 1 FROM `tabWork Done` wd WHERE wd.system_id = pd.name)",
    ]
    params = [caller_im]

    for col, key in (("pd.project_code", "project_code"), ("pd.site_code", "site_code"), ("pd.dispatch_status", "dispatch_status")):
        clause, p = _sql_in_or_eq(col, filters.get(key))
        if clause:
            wheres.append(clause)
            params.extend(p)

    # Keys match keyFromLabel() slugs of LegacyResubmitTable's headers
    # (e.g. "PIC Status (MS1)" -> "pic_status_ms1"), not the DB column names.
    col_filter_map = {
        "poid": "IFNULL(pd.poid,'')",
        "po_no": "IFNULL(pd.po_no,'')",
        "project": "IFNULL(pd.project_code,'')",
        "duid": "IFNULL(pd.site_code,'')",
        "item_code": "IFNULL(pd.item_code,'')",
        "item_description": "IFNULL(pd.item_description,'')",
        "po_status": "IFNULL(pd.dispatch_status,'')",
        "pic_status_ms1": "IFNULL(pd.pic_status,'')",
        "pic_status_ms2": "IFNULL(pd.pic_status_ms2,'')",
        "im_note": "IFNULL(pd.im_confirmation_note,'')",
        # Remaining headers on the Resubmit-to-PIC table.
        "activity_type": "IFNULL((SELECT activity_type FROM `tabItem` WHERE name = pd.item_code), '')",
        "ms1_amount": "CAST(pd.ms1_amount AS CHAR)",
        "ms2_amount": "CAST(pd.ms2_amount AS CHAR)",
        "last_updated": "CAST(pd.modified AS CHAR)",
        "docs": (
            "CAST((SELECT COUNT(*) FROM `tabFile` f WHERE f.attached_to_doctype = 'PO Dispatch' "
            "AND f.attached_to_name = pd.name AND f.attached_to_field IN "
            "('im_doc1','im_doc2','im_doc2a','im_doc2b','im_doc2c')) AS CHAR)"
        ),
    }
    column_filters = filters.get("column_filters")
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            expr = col_filter_map.get(col_key)
            if not expr:
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat)

    search_term = filters.get("search") or filters.get("q") or ""
    if search_term:
        # _sql_search_clause (not a plain _sql_like_pattern) so pasting
        # several distinct POIDs at once — the same "paste comma/newline"
        # UX list_work_done_rows already supports — works here too. A single
        # LIKE '%...%' built from the whole pasted, semicolon-joined string
        # could never match any real row, silently returning zero results.
        clause, sp = _sql_search_clause(
            "CONCAT_WS(' ', IFNULL(pd.poid,''), IFNULL(pd.po_no,''), "
            "IFNULL(pd.project_code,''), IFNULL(pd.site_code,''), pd.name)",
            search_term,
            exact_cols=["IFNULL(pd.poid,'')", "pd.name"],
        )
        if clause:
            wheres.append(clause)
            params.extend(sp)

    if _options:
        _e = col_filter_map.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabPO Dispatch` pd", " AND ".join(wheres), params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )

    rows = frappe.db.sql(
        f"""
        SELECT pd.name, pd.poid, pd.po_no, pd.project_code, pd.site_code,
               pd.item_code, pd.item_description, pd.dispatch_status,
               pd.pic_status, pd.pic_status_ms2, pd.ms1_amount, pd.ms2_amount,
               pd.im_confirmation_note, pd.modified,
               (SELECT COUNT(*) FROM `tabFile` f
                WHERE f.attached_to_doctype = 'PO Dispatch' AND f.attached_to_name = pd.name
                  AND f.attached_to_field IN ('im_doc1', 'im_doc2', 'im_doc2a', 'im_doc2b', 'im_doc2c')
               ) AS doc_count
        FROM `tabPO Dispatch` pd
        WHERE {" AND ".join(wheres)}
        ORDER BY pd.modified DESC
        {_sql_limit_suffix(limit_page_length)}
        """,
        tuple(params),
        as_dict=True,
    )
    if rows:
        act_map = _batch_item_activity_types(rows)
        for r in rows:
            r["activity_type"] = act_map.get(r.get("item_code") or "")
            r["ms1_needs"] = bool(flt(r.get("ms1_amount")) > 0 and (r.get("pic_status") or "") not in _DATA_INTEGRITY_TERMINAL_MS)
            r["ms2_needs"] = bool(flt(r.get("ms2_amount")) > 0 and (r.get("pic_status_ms2") or "") not in _DATA_INTEGRITY_TERMINAL_MS)
    return rows


@frappe.whitelist()
def resubmit_legacy_milestone_to_pic(po_dispatch, milestone, note=None):
    """Submit a supporting document / note for a legacy line's milestone —
    no Work Done record involved, and no pic_status change either. These
    lines aren't missing evidence that needs a status push to fix; the work
    and its original PIC submission already happened historically, outside
    this system (archive import). The only gap is that any leftover
    document for it had nowhere to go through the system — this is that
    place. Only blocked once the milestone is genuinely finished
    (Commercial Invoice Closed/Submitted or PO Line Canceled —
    _DATA_INTEGRITY_TERMINAL_MS); any other current status (Work Not Done,
    Under Process to Apply, Under I-BUY, ...) is still open for this.
    """
    _require_inet_im_session()
    caller_im = _resolve_caller_im_or_throw()

    po_dispatch = (po_dispatch or "").strip()
    milestone = str(milestone or "").strip().upper()
    if milestone not in ("MS1", "MS2"):
        frappe.throw("milestone must be MS1 or MS2")
    if not po_dispatch or not frappe.db.exists("PO Dispatch", po_dispatch):
        frappe.throw(f"PO Dispatch not found: {po_dispatch}")

    pd = frappe.db.get_value(
        "PO Dispatch", po_dispatch,
        ["im", "ms1_amount", "pic_status", "ms2_amount", "pic_status_ms2"],
        as_dict=True,
    )
    if pd.im != caller_im:
        frappe.throw("Not permitted — this POID isn't assigned to you.", frappe.PermissionError)

    amount = flt(pd.ms1_amount if milestone == "MS1" else pd.ms2_amount)
    current_status = (pd.pic_status if milestone == "MS1" else pd.pic_status_ms2) or ""
    if amount <= 0:
        frappe.throw(f"{milestone} has no amount on this line — nothing to submit.")
    if current_status in _DATA_INTEGRITY_TERMINAL_MS:
        frappe.throw(f"{milestone} is already {current_status} — nothing left to submit.")

    if note is not None and frappe.db.has_column("PO Dispatch", "im_confirmation_note"):
        frappe.db.set_value("PO Dispatch", po_dispatch, "im_confirmation_note", (note or "").strip(), update_modified=True)
    frappe.db.commit()

    try:
        from inet_app.api.notifications import notify_pic_legacy_milestone_submitted
        notify_pic_legacy_milestone_submitted(po_dispatch, milestone)
    except Exception:
        pass

    return {"po_dispatch": po_dispatch, "milestone": milestone}


@frappe.whitelist()
def bulk_resubmit_legacy_milestones_to_pic(payload=None):
    """Bulk version of resubmit_legacy_milestone_to_pic — pushes several
    legacy milestones to PIC in one call, optionally attaching a shared
    file to each line's PO Dispatch first (same file_urls convention as
    bulk_submit_work_done).
    payload: {
        items: [{po_dispatch, milestone, poid (optional, for error labels)}, ...],
        note: str (optional, applied to every line),
        file_urls: { slot: url | [url, ...] } (optional)
    }
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload) if payload else {}
    payload = payload or {}

    items = payload.get("items") or []
    if isinstance(items, str):
        items = frappe.parse_json(items) if items.strip() else []
    if not isinstance(items, list):
        items = []
    note = payload.get("note") or None
    file_urls = payload.get("file_urls") or {}
    if not items:
        frappe.throw("No lines specified")

    ALLOWED_SLOTS = {"im_doc1", "im_doc2", "im_doc2a", "im_doc2b", "im_doc2c"}
    attached_to = set()
    updated = 0
    errors = []

    for item in items:
        po_dispatch = (item.get("po_dispatch") or "").strip()
        milestone = (item.get("milestone") or "").strip().upper()
        label = item.get("poid") or po_dispatch
        try:
            if po_dispatch and file_urls and po_dispatch not in attached_to:
                for slot, urls in file_urls.items():
                    if slot not in ALLOWED_SLOTS:
                        continue
                    url_list = urls if isinstance(urls, (list, tuple)) else [urls]
                    for url in url_list:
                        if not url:
                            continue
                        frappe.get_doc({
                            "doctype": "File",
                            "file_url": url,
                            "attached_to_doctype": "PO Dispatch",
                            "attached_to_name": po_dispatch,
                            "attached_to_field": slot,
                        }).insert(ignore_permissions=True)
                attached_to.add(po_dispatch)
            resubmit_legacy_milestone_to_pic(po_dispatch, milestone, note)
            updated += 1
        except Exception as e:
            errors.append({"name": label, "error": str(e)})

    frappe.db.commit()
    return {"updated": updated, "errors": errors}


@frappe.whitelist()
def update_work_done_issue(name, issue_flag):
    """IM / PM sets the issue flag on a Work Done record."""
    name = (name or "").strip()
    flag = (issue_flag or "").strip()
    if not name:
        frappe.throw("name is required")
    if flag not in _ALLOWED_WD_ISSUE_FLAGS:
        frappe.throw("Invalid issue_flag value")
    if not frappe.db.exists("Work Done", name):
        frappe.throw(f"Work Done not found: {name}")
    frappe.db.set_value("Work Done", name, "issue_flag", flag, update_modified=True)
    frappe.db.commit()
    return {"name": name, "issue_flag": flag}


@frappe.whitelist()
def get_work_done_attachments(name):
    """Return Frappe File records attached to a Work Done document."""
    name = (name or "").strip()
    if not name or not frappe.db.exists("Work Done", name):
        return []
    return frappe.db.get_all(
        "File",
        filters={"attached_to_doctype": "Work Done", "attached_to_name": name},
        fields=["name", "file_name", "file_url", "file_size", "is_private", "creation"],
        order_by="creation asc",
    )


@frappe.whitelist()
def update_subcon_submission(po_dispatch, submission_status, note=None):
    """Set submission_status on a sub-contracted PO Dispatch (no Work Done row exists).

    Stored on PO Dispatch.subcon_submission_status so synthetic Work Done rows can
    surface it in the regular list. Allowed values: '', 'Ready for Confirmation',
    'Confirmation Done'. Permission: PM, or IM owning the dispatch.
    """
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)
    status = (submission_status or "").strip()
    if status not in ("Ready for Confirmation", "Confirmation Done", ""):
        frappe.throw("Invalid submission_status")
    name = _resolve_dispatch_for_remarks(po_dispatch)
    pd = frappe.db.get_value(
        "PO Dispatch", name,
        ["name", "im", "subcon_status", "poid"],
        as_dict=True,
    ) or {}
    if not pd.get("name"):
        frappe.throw("PO Dispatch not found")
    if (pd.get("subcon_status") or "") != "Work Done":
        frappe.throw("Submission status can only be set on completed sub-contract POIDs.")
    if role == "im":
        _, im_identifiers, _ = resolve_im_for_session()
        if not _can_assign_backend_dispatch(role, im_identifiers, pd):
            frappe.throw("Not permitted", frappe.PermissionError)
    frappe.db.set_value(
        "PO Dispatch", name,
        "subcon_submission_status", status,
        update_modified=True,
    )

    if note is not None and status == "Confirmation Done" and frappe.db.has_column("PO Dispatch", "im_confirmation_note"):
        frappe.db.set_value("PO Dispatch", name, "im_confirmation_note", (note or "").strip(), update_modified=False)

    pic_warning = None
    if status != "Confirmation Done":
        pic_warning = _revert_pic_status_if_safe(name)

    frappe.db.commit()
    result = {"po_dispatch": name, "poid": pd.get("poid") or name, "submission_status": status}
    if pic_warning:
        result["pic_warning"] = pic_warning
    return result


@frappe.whitelist()
def list_issue_risk_rows(im=None, limit=1000, search=None, portal_filters=None, _options=None, _summary=None):
    """
    Issue & Risk rows from rollout plans that are in issue state or carry an issue category.
    - Admin roles can view all rows (or filter by im argument).
    - IM role is restricted to its own dispatches.
    ``search`` matches rollout / dispatch / project / team / IM fields across the full dataset
    before the row limit is applied.

    ``portal_filters`` (JSON dict) may set exact ``project_code``, ``site_code``, ``team``
    (rollout plan team id), ``issue_category``, ``execution_status``, ``tl_status``,
    ``qc_status``, ``ciag_status`` — applied in SQL before the row limit.
    """
    user = frappe.session.user
    roles = set(frappe.get_roles(user))

    is_admin = (
        "Administrator" in roles
        or "System Manager" in roles
        or "INET Admin" in roles
    )
    is_im = "INET IM" in roles
    if not (is_admin or is_im):
        frappe.throw("Not permitted", frappe.PermissionError)

    im_filter_value = (im or "").strip()
    if is_im and not is_admin:
        im_filter_value, _, _ = resolve_im_for_session(im_filter_value)
        if not im_filter_value:
            return []

    rp_im_join_ir = ""
    im_full_sql_ir = "im_pd.full_name AS im_full_name"
    if frappe.db.has_column("Rollout Plan", "im"):
        rp_im_join_ir = "\n        LEFT JOIN `tabIM Master` im_rp ON im_rp.name = rp.im"
        im_full_sql_ir = "COALESCE(im_rp.full_name, im_pd.full_name) AS im_full_name"
    ciag_sel_ir = "de.ciag_status" if frappe.db.has_column("Daily Execution", "ciag_status") else "NULL AS ciag_status"
    lim_ir = _portal_row_limit(limit, 1000)

    # I&R = open issues tracked by issue_status. A plan appears when
    # issue_status is set and not yet 'Resolved'. The row disappears only
    # when Work Done is created (which sets issue_status = 'Resolved') or
    # the NOT EXISTS Work Done guard catches it.
    #
    # Backward-compat fallback: old rows without issue_status set still
    # surface via visit_type / plan_status markers.
    #
    # A later plan (higher visit_number) for the same po_dispatch supersedes
    # an earlier one — logically the earlier issue is resolved the moment a
    # follow-up plan exists for that line, even if its own issue_status was
    # never flipped to 'Resolved'. This guard used to apply only to the
    # backward-compat branch, so a dispatch could show 2 open rows at once:
    # the original issue (still "In Execution"/etc, never explicitly
    # resolved) AND the new issue on its own follow-up re-visit plan. Now
    # applies to both branches so only the latest plan's issue ever shows.
    wheres = [
        "("
        # New data: tracked by issue_status
        "  IFNULL(rp.issue_status,'') NOT IN ('','Resolved')"
        "  OR ("
        # Old data backward compat: no issue_status but plan is in issue state
        # Note: visit_type='Re-Visit' is NOT used here — new Re-Visit plans
        # created from I&R are real execution plans, not issue-tracking rows.
        "    IFNULL(rp.issue_status,'') = ''"
        "    AND ("
        "      rp.plan_status = 'Planning with Issue'"
        "      OR IFNULL(rp.issue_category,'') != ''"
        "    )"
        "  )"
        ")",
        "NOT EXISTS ("
        "  SELECT 1 FROM `tabRollout Plan` rp_later"
        "  WHERE rp_later.po_dispatch = rp.po_dispatch"
        "  AND IFNULL(rp_later.visit_number,0) > IFNULL(rp.visit_number,0)"
        ")",
        "NOT EXISTS ("
        " SELECT 1 FROM `tabWork Done` wd_ir"
        " INNER JOIN `tabDaily Execution` de_ir ON de_ir.name = wd_ir.execution"
        " INNER JOIN `tabRollout Plan` rp_wd ON rp_wd.name = de_ir.rollout_plan"
        " WHERE rp_wd.po_dispatch = rp.po_dispatch"
        ")",
    ]
    params = []
    if im_filter_value:
        if frappe.db.has_column("Rollout Plan", "im"):
            wheres.append("(IFNULL(pd.im,'') = %s OR IFNULL(rp.im,'') = %s)")
            params.extend([im_filter_value, im_filter_value])
        else:
            wheres.append("IFNULL(pd.im,'') = %s")
            params.append(im_filter_value)

    pf_ir = _portal_filters_dict(portal_filters)
    for col, key in (("IFNULL(pd.project_code,'')", "project_code"),
                     ("IFNULL(pd.site_code,'')", "site_code"),
                     ("IFNULL(rp.team,'')", "team")):
        c, p = _sql_in_or_eq(col, pf_ir.get(key))
        if c:
            wheres.append(c)
            params.extend(p)
    # Portal IM filter (multi-select) — overrides the single-string im arg
    pf_im_vals = _ensure_list(pf_ir.get("im"))
    if pf_im_vals and not im_filter_value:
        ph_ir = ", ".join(["%s"] * len(pf_im_vals))
        if frappe.db.has_column("Rollout Plan", "im"):
            wheres.append(f"(IFNULL(pd.im,'') IN ({ph_ir}) OR IFNULL(rp.im,'') IN ({ph_ir}))")
            params.extend(pf_im_vals + pf_im_vals)
        else:
            wheres.append(f"IFNULL(pd.im,'') IN ({ph_ir})")
            params.extend(pf_im_vals)

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale. `id_sql` (below) doesn't join Daily Execution directly, so
    # execution-sourced columns (tl_status/qc/ciag/etc.) are matched via a
    # correlated subquery mirroring the exact "latest execution up to this
    # visit" logic the second query's `de` JOIN uses.
    def _latest_de_ir(col):
        return (
            f"(SELECT de2.{col} FROM `tabDaily Execution` de2 "
            "INNER JOIN `tabRollout Plan` rp2 ON rp2.name = de2.rollout_plan "
            "WHERE rp2.po_dispatch = rp.po_dispatch "
            "AND IFNULL(rp2.visit_number, 0) <= IFNULL(rp.visit_number, 0) "
            "ORDER BY IFNULL(rp2.visit_number,0) DESC, de2.modified DESC LIMIT 1)"
        )

    # Dedicated toolbar filters (Issue Category / Exec Status / date range) —
    # same "loaded rows only" bug as the Manage Table column filters above,
    # just on this page's own dropdown/date-range controls instead.
    ic_vals = _ensure_list(pf_ir.get("issue_category"))
    if ic_vals:
        ph_ic = ", ".join(["%s"] * len(ic_vals))
        wheres.append(f"IFNULL(rp.issue_category,'') IN ({ph_ic})")
        params.extend(ic_vals)
    es_vals = _ensure_list(pf_ir.get("execution_status"))
    if es_vals:
        ph_es = ", ".join(["%s"] * len(es_vals))
        wheres.append(f"IFNULL({_latest_de_ir('execution_status')},'') IN ({ph_es})")
        params.extend(es_vals)
    tl_vals = _ensure_list(pf_ir.get("tl_status"))
    if tl_vals:
        ph_tl = ", ".join(["%s"] * len(tl_vals))
        wheres.append(f"IFNULL({_latest_de_ir('tl_status')},'') IN ({ph_tl})")
        params.extend(tl_vals)
    qc_vals = _ensure_list(pf_ir.get("qc_status"))
    if qc_vals:
        ph_qc = ", ".join(["%s"] * len(qc_vals))
        wheres.append(f"IFNULL({_latest_de_ir('qc_status')},'') IN ({ph_qc})")
        params.extend(qc_vals)
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        ciag_vals = _ensure_list(pf_ir.get("ciag_status"))
        if ciag_vals:
            ph_ciag = ", ".join(["%s"] * len(ciag_vals))
            wheres.append(f"IFNULL({_latest_de_ir('ciag_status')},'') IN ({ph_ciag})")
            params.extend(ciag_vals)
    if pf_ir.get("from_date") and pf_ir.get("to_date"):
        wheres.append("rp.plan_date BETWEEN %s AND %s")
        params.extend([pf_ir["from_date"], pf_ir["to_date"]])
    elif pf_ir.get("from_date"):
        wheres.append("rp.plan_date >= %s")
        params.append(pf_ir["from_date"])
    elif pf_ir.get("to_date"):
        wheres.append("rp.plan_date <= %s")
        params.append(pf_ir["to_date"])

    _desc_expr_ir = (
        "CASE WHEN IFNULL(pd.is_dummy_po,0) = 1 AND IFNULL(pd.item_description,'') = '' "
        "THEN IFNULL(pd.manager_remark,'') ELSE IFNULL(pd.item_description,'') END"
        if frappe.db.has_column("PO Dispatch", "is_dummy_po") and frappe.db.has_column("PO Dispatch", "manager_remark")
        else "IFNULL(pd.item_description,'')"
    )
    col_filter_map_ir = {
        "poid": "COALESCE(NULLIF(pd.poid,''), pd.name)",
        "plan": "rp.name",
        # Column shows the IM's full name, falling back to the raw code.
        "im": "IFNULL(NULLIF(im_pd.full_name, ''), IFNULL(pd.im, ''))",
        "item_code": "IFNULL(pd.item_code,'')",
        "description": _desc_expr_ir,
        "project": "IFNULL(pd.project_code,'')",
        "duid": "IFNULL(pd.site_code,'')",
        "team": "IFNULL(it.team_name,'')",
        "plan_date": "CAST(rp.plan_date AS CHAR)",
        "exec_date": f"CAST({_latest_de_ir('execution_date')} AS CHAR)",
        "attempt": "CAST(rp.visit_number AS CHAR)",
        "line_amount": "CAST(pd.line_amount AS CHAR)",
        "region": "IFNULL(pd.region_type,'')",
        "exec_status": _latest_de_ir("execution_status"),
        "tl_status": _latest_de_ir("tl_status"),
        "qc": _latest_de_ir("qc_status"),
        "issue_status": "IFNULL(rp.issue_status,'')",
        "issue_category": "IFNULL(rp.issue_category,'')",
        "issue_remarks": "IFNULL(rp.issue_remarks,'')",
        "execution_remarks": _latest_de_ir("remarks"),
        "huawei_im": "COALESCE(NULLIF(pd.huawei_im,''), pcc_ir.huawei_im, '')",
        "domain": "COALESCE(NULLIF(pd.project_domain,''), pcc_ir.project_domain, '')",
    }
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        col_filter_map_ir["ciag"] = _latest_de_ir("ciag_status")
    if frappe.db.has_column("PO Dispatch", "general_remark"):
        col_filter_map_ir["general"] = "IFNULL(pd.general_remark,'')"
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        col_filter_map_ir["manager"] = "IFNULL(pd.manager_remark,'')"
    if frappe.db.has_column("PO Dispatch", "team_lead_remark"):
        col_filter_map_ir["team_lead"] = "IFNULL(pd.team_lead_remark,'')"
    # Not backend-filterable: "activity_type" is a Python post-query
    # enrichment (not used by this function's output at all, so N/A here).
    column_filters_ir = pf_ir.get("column_filters")
    if isinstance(column_filters_ir, str):
        try:
            column_filters_ir = frappe.parse_json(column_filters_ir)
        except Exception:
            column_filters_ir = None
    if isinstance(column_filters_ir, dict):
        for col_key, raw_val in column_filters_ir.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map_ir.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            if col_key == "im":
                im_parts_ir = ["(IFNULL(pd.im,'') LIKE %s)"]
                im_params_ir = [pat]
                if frappe.db.has_column("Rollout Plan", "im"):
                    im_parts_ir.append("(IFNULL(rp.im,'') LIKE %s)")
                    im_params_ir.append(pat)
                im_parts_ir.append("(pd.im IN (SELECT name FROM `tabIM Master` WHERE full_name LIKE %s))")
                im_params_ir.append(pat)
                if frappe.db.has_column("Rollout Plan", "im"):
                    im_parts_ir.append("(rp.im IN (SELECT name FROM `tabIM Master` WHERE full_name LIKE %s))")
                    im_params_ir.append(pat)
                wheres.append("(" + " OR ".join(im_parts_ir) + ")")
                params.extend(im_params_ir)
                continue
            expr = col_filter_map_ir.get(col_key)
            if not expr:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat)

    like_pat = _sql_like_pattern(search or "")
    if like_pat:
        concat_parts = [
            "IFNULL(rp.name,'')",
            "IFNULL(rp.po_dispatch,'')",
            "COALESCE(NULLIF(pd.poid,''), pd.name, '')",
            "IFNULL(rp.issue_category,'')",
            "IFNULL(rp.team,'')",
            "IFNULL(it.team_name,'')",
            "IFNULL(pd.po_no,'')",
            "IFNULL(pd.project_code,'')",
            "IFNULL(pd.site_code,'')",
            "IFNULL(pd.site_name,'')",
            "IFNULL(pd.im,'')",
            "IFNULL(im_pd.full_name,'')",
            _desc_expr_ir,
            "COALESCE(NULLIF(pd.project_domain,''), pcc_ir.project_domain, '')",
            "IFNULL(pcc_ir.huawei_im,'')",
        ]
        if frappe.db.has_column("Rollout Plan", "im"):
            concat_parts.append("IFNULL(im_rp.full_name,'')")
        concat_expr = "CONCAT_WS(' ', " + ", ".join(concat_parts) + ")"
        clause, cparams = _sql_search_clause(
            concat_expr, search or "",
            exact_cols=["COALESCE(NULLIF(pd.poid,''), pd.name)", "IFNULL(pd.site_code,'')"],
        )
        if clause:
            wheres.append(clause)
            params.extend(cparams)

    _ir_from = (
        "`tabRollout Plan` rp "
        "LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
        "LEFT JOIN `tabINET Team` it ON it.name = rp.team "
        "LEFT JOIN `tabProject Control Center` pcc_ir ON pcc_ir.name = pd.project_code "
        f"{rp_im_join_ir}"
        " LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im"
    )
    if _options:
        _e = col_filter_map_ir.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            _ir_from, " AND ".join(wheres), params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # This page exists to be emptied, so the useful figures are how many
        # are still open and what kind — not a value roll-up.
        _ps_ir = "IFNULL(rp.plan_status,'')"
        _cat = "IFNULL(rp.issue_category,'')"
        return summary_from_query(_ir_from, " AND ".join(wheres), params, [
            {"key": "issues", "label": "Issues", "agg": "count"},
            {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
             "expr": "NULLIF(IFNULL(pd.site_code,''), '')"},
            {"key": "open", "label": "Open", "agg": "count_if", "group": "State",
             "cond": f"{_ps_ir} NOT IN ('Completed','Cancelled')", "tone": "bad"},
            {"key": "overdue", "label": "Overdue", "agg": "count_if", "group": "State",
             "cond": f"{_ps_ir} = 'Overdue'", "tone": "bad", "hide_if_zero": True},
            {"key": "resolved", "label": "Resolved", "agg": "count_if", "group": "State",
             "cond": f"{_ps_ir} = 'Completed'", "tone": "good", "hide_if_zero": True},
            {"key": "qc_reject", "label": "QC", "agg": "count_if", "group": "Category",
             "cond": f"{_cat} = 'QC Rejection'", "tone": "warn", "hide_if_zero": True},
            {"key": "pat_reject", "label": "PAT", "agg": "count_if", "group": "Category",
             "cond": f"{_cat} = 'PAT Rejection'", "tone": "warn", "hide_if_zero": True},
            {"key": "extra_visit", "label": "Extra visit", "agg": "count_if", "group": "Category",
             "cond": f"{_cat} = 'Extra Visit'", "hide_if_zero": True},
            {"key": "late", "label": "Late arrival", "agg": "count_if", "group": "Category",
             "cond": f"{_cat} = 'Late Arrival'", "hide_if_zero": True},
        ])
    id_sql = (
        "SELECT rp.name AS plan_id "
        "FROM `tabRollout Plan` rp "
        "LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
        "LEFT JOIN `tabINET Team` it ON it.name = rp.team "
        "LEFT JOIN `tabProject Control Center` pcc_ir ON pcc_ir.name = pd.project_code "
        f"{rp_im_join_ir}"
        "\n        LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im"
        f"\n        WHERE {' AND '.join(wheres)} "
        "ORDER BY rp.modified DESC "
        f"{_sql_limit_suffix(lim_ir)}"
    )
    plan_rows = frappe.db.sql(id_sql, tuple(params), as_dict=True)
    plan_ids = [r.plan_id for r in (plan_rows or []) if r.get("plan_id")]
    if not plan_ids:
        return []

    ph = ", ".join(["%s"] * len(plan_ids))
    rows = frappe.db.sql(
        f"""
        SELECT
            rp.name AS rollout_plan,
            rp.po_dispatch,
            COALESCE(NULLIF(pd.poid, ''), pd.name) AS poid,
            rp.plan_status,
            IFNULL(rp.issue_status,'') AS issue_status,
            rp.issue_category,
            rp.issue_remarks,
            rp.visit_number,
            rp.plan_date,
            rp.visit_type,
            rp.team,
            it.team_name AS team_name,
            {im_full_sql_ir},
            rp.modified,
            pd.im,
            pd.huawei_im,
            pd.po_no,
            pd.project_code,
            pd.site_code,
            pd.site_name,
            pd.item_code,
            pd.item_description,
            pd.is_dummy_po,
            pd.qty,
            pd.line_amount,
            pd.center_area,
            pd.region_type,
            pd.dispatch_status,
            {_remark_select()},
            de.name AS execution_name,
            de.execution_date,
            de.execution_status,
            de.tl_status,
            de.remarks AS execution_remarks,
            de.qc_status,
            {ciag_sel_ir}
        FROM `tabRollout Plan` rp
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabINET Team` it ON it.name = rp.team
        {rp_im_join_ir}
        LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im
        LEFT JOIN `tabDaily Execution` de ON de.name = (
            SELECT de2.name
            FROM `tabDaily Execution` de2
            INNER JOIN `tabRollout Plan` rp2 ON rp2.name = de2.rollout_plan
            WHERE rp2.po_dispatch = rp.po_dispatch
            AND IFNULL(rp2.visit_number, 0) <= IFNULL(rp.visit_number, 0)
            ORDER BY IFNULL(rp2.visit_number,0) DESC, de2.modified DESC
            LIMIT 1
        )
        WHERE rp.name IN ({ph})
        ORDER BY rp.modified DESC, de.modified DESC
        """,
        tuple(plan_ids),
        as_dict=True,
    )

    out = []
    seen_plans = set()
    for r in rows or []:
        rp_name = r.get("rollout_plan")
        if not rp_name or rp_name in seen_plans:
            continue
        seen_plans.add(rp_name)
        out.append(
            {
                "rollout_plan": rp_name,
                "po_dispatch": r.get("po_dispatch"),
                "poid": r.get("poid"),
                "plan_status": r.get("plan_status"),
                "issue_status": r.get("issue_status") or "",
                "issue_category": r.get("issue_category"),
                "issue_remarks": r.get("issue_remarks"),
                "visit_number": r.get("visit_number"),
                "plan_date": r.get("plan_date"),
                "visit_type": r.get("visit_type"),
                "team": r.get("team"),
                "team_name": r.get("team_name"),
                "im": r.get("im"),
                "im_full_name": r.get("im_full_name"),
                "po_no": r.get("po_no"),
                "project_code": r.get("project_code"),
                "site_code": r.get("site_code"),
                "site_name": r.get("site_name"),
                "item_code": r.get("item_code"),
                "item_description": r.get("item_description"),
                "is_dummy_po": r.get("is_dummy_po"),
                "qty": r.get("qty"),
                "line_amount": r.get("line_amount"),
                "center_area": r.get("center_area"),
                "region_type": r.get("region_type"),
                "general_remark": r.get("general_remark"),
                "manager_remark": r.get("manager_remark"),
                "team_lead_remark": r.get("team_lead_remark"),
                "execution_name": r.get("execution_name"),
                "execution_date": r.get("execution_date"),
                "execution_status": r.get("execution_status"),
                "tl_status": r.get("tl_status"),
                "execution_remarks": r.get("execution_remarks"),
                "qc_status": r.get("qc_status"),
                "ciag_status": r.get("ciag_status"),
                "dispatch_status": r.get("dispatch_status"),
                "modified": r.get("modified"),
            }
        )
    _enrich_with_project_fields(out)
    _apply_dummy_description(out)
    return out


