def _month_bounds():
    """Return (first_day_str, last_day_str, today_str) for current month."""
    today = getdate(nowdate())
    first = get_first_day(today)
    last = get_last_day(today)
    return str(first), str(last), str(today)


def _days_in_month(today=None):
    today = getdate(today or nowdate())
    return calendar.monthrange(today.year, today.month)[1]


def _team_cost_days(start_date, end_date, period_from, period_to, cap=30):
    """Days of `daily_cost` to charge for a team within [period_from, period_to].

    A team only costs money for the days it actually existed - clip the report
    period to [start_date, end_date] (either bound blank = unbounded on that
    side, so an untouched team behaves exactly as before this field existed)
    before applying the existing flat-monthly-salary cap.
    """
    period_from = getdate(period_from)
    period_to = getdate(period_to)
    overlap_start = max(period_from, getdate(start_date)) if start_date else period_from
    overlap_end = min(period_to, getdate(end_date)) if end_date else period_to
    days = (overlap_end - overlap_start).days + 1
    return max(0, min(cap, days))


# ── Reporting definition of "invoiced" ─────────────────────────────────────
#
# A milestone counts as invoiced once it reaches "Commercial Invoice
# Submitted" (invoice raised) or "Commercial Invoice Closed" (raised AND
# payment received). Both are invoiced; Closed just also means paid.
#
# The value is the milestone's FULL ``ms1_amount`` / ``ms2_amount``. There is
# no partial billing inside a milestone — once MS1 is submitted, all of MS1 is
# invoiced. This is why reporting must NOT use ``ms1_invoiced`` /
# ``ms1_unbilled``: those two fields are PIC's own display fields and carry
# bad values left over from earlier testing. They stay untouched on the PIC
# dashboard; nothing that reports numbers should read them.
_INVOICED_STATUSES_SQL = "('Commercial Invoice Submitted', 'Commercial Invoice Closed')"

_MS1_INVOICED_SQL = f"pd.pic_status IN {_INVOICED_STATUSES_SQL}"
_MS2_INVOICED_SQL = f"pd.pic_status_ms2 IN {_INVOICED_STATUSES_SQL}"

# Invoiced value: full milestone amount for every milestone that got there.
_INVOICED_VALUE_SQL = f"""
(CASE WHEN {_MS1_INVOICED_SQL} THEN IFNULL(pd.ms1_amount, 0) ELSE 0 END
 + CASE WHEN {_MS2_INVOICED_SQL} THEN IFNULL(pd.ms2_amount, 0) ELSE 0 END)
"""


# Backlog: milestone value that has NOT reached an invoiced status yet.
# Invoiced + backlog partitions the total milestone value exactly.
#
# NOTE the IFNULL. `NOT (pic_status IN (...))` is NOT the negation here:
# `NULL IN (...)` evaluates to NULL, and `NOT NULL` is NULL — not TRUE — so a
# CASE on it falls through to ELSE and the ~1.7k rows with a NULL pic_status
# would contribute no backlog at all, breaking the partition by ~SAR 1.77M.
_MS1_NOT_INVOICED_SQL = f"IFNULL(pd.pic_status, '') NOT IN {_INVOICED_STATUSES_SQL}"
_MS2_NOT_INVOICED_SQL = f"IFNULL(pd.pic_status_ms2, '') NOT IN {_INVOICED_STATUSES_SQL}"

_BACKLOG_VALUE_SQL = f"""
(CASE WHEN {_MS1_NOT_INVOICED_SQL} THEN IFNULL(pd.ms1_amount, 0) ELSE 0 END
 + CASE WHEN {_MS2_NOT_INVOICED_SQL} THEN IFNULL(pd.ms2_amount, 0) ELSE 0 END)
"""

# A cancelled line carries no money either way: nothing was invoiced and its
# remainder is not backlog. Kept separate from the scope below because some
# callers (PIC's "All Lines" tile) must still COUNT cancelled rows.
_NOT_CANCELLED_SQL = """
IFNULL(pd.dispatch_status, '') <> 'Cancelled'
AND IFNULL(pd.pic_status, '') <> 'PO Line Canceled'
AND IFNULL(pd.pic_status_ms2, '') <> 'PO Line Canceled'
"""

# Lines that count at all: real work, and not cancelled at either level.
_REPORTING_SCOPE_SQL = f"""
IFNULL(pd.is_internal_work, 0) = 0
AND IFNULL(pd.is_dummy_po, 0) = 0
AND {_NOT_CANCELLED_SQL}
"""


def _undated_invoiced_value():
    """Invoiced milestone value with no invoicing month — can't be charted.

    Returned alongside the monthly series so the gap between "total invoiced"
    on a KPI tile and the sum of the chart's bars is stated, not hidden.
    """
    rows = frappe.db.sql(
        f"""
        SELECT
          COALESCE(SUM(CASE WHEN {_MS1_INVOICED_SQL} AND pd.ms1_invoice_month IS NULL
                            THEN IFNULL(pd.ms1_amount, 0) ELSE 0 END), 0)
        + COALESCE(SUM(CASE WHEN {_MS2_INVOICED_SQL} AND pd.ms2_invoice_month IS NULL
                            THEN IFNULL(pd.ms2_amount, 0) ELSE 0 END), 0) AS undated
        FROM `tabPO Dispatch` pd
        WHERE {_REPORTING_SCOPE_SQL}
        """,
        as_dict=True,
    )
    return flt((rows[0] if rows else {}).get("undated") or 0, 2)


# When a PO line was closed, for the as-of snapshot in _open_po_line_totals.
#
# There is no closed-on field, and `modified` is useless as a proxy: 9,814 of
# the 10,590 closed lines share one bulk-import timestamp. So the date comes
# off the billing chain on the line's dispatch instead — the payment received
# date where it exists, falling back to the i-BUY invoice date.
#
# Payment is the real closure event, but that field is currently empty on all
# 17,454 dispatches, while the i-BUY invoice date covers 9,762 of the 12,044
# closed lines and carries genuine history (22 distinct months, 2024-05 to
# 2026-02). The COALESCE order means each line automatically becomes exact
# the moment someone starts recording its payment date, with no change here.
#
# A line closes when its LAST milestone settles, hence GREATEST. The
# '1900-01-01' floors are load-bearing: MySQL's GREATEST returns NULL if any
# argument is NULL, which would make the comparison unknown and silently drop
# the row. With the floors, a line whose closure cannot be dated at all (the
# ~19% with neither date) evaluates to 1900 and so is never re-opened by the
# snapshot — it stays counted as closed, which is exactly the old behaviour
# and the conservative side to err on. 11,302 of the 12,044 have no MS2 at
# all, so for 94% of them this reduces to the MS1 date.
# A PO line whose work has been carried out. Status is the source of truth for
# this, not Work Done: only 61 Work Done records exist against 12,000+ done
# lines, because the rest were imported already completed — and often already
# invoiced — with no plan or execution ever created. An invoiced or closed
# line is work delivered, so all five count.
#
# Shared so the project reports and the project pages cannot drift to
# different definitions of the same word, which is exactly what happened:
# the pages measured revenue off Work Done and read SAR 47,470 company-wide
# against SAR 9,428,121 of delivered line value.
LINE_DONE_STATUSES = ('Completed', 'Partially Submitted', 'Submitted',
                      'Partially Closed', 'Closed')


def wd_revenue_sql(wd="wd", pd="pd", pd2=None):
    """A Work Done row's revenue, taken from the PO LINE rather than from
    Work Done's own ``revenue_sar`` column. Use this for every reported
    revenue figure.

    Revenue is not an independently editable number: a line is worth what the
    PO says it is worth, so ``revenue_sar`` and ``pd.line_amount`` must agree.
    They can drift because Work Done recomputes the column in before_save as
    ``billing_rate_sar * executed_qty`` (there is even a patch,
    fix_work_done_revenue_sar, whose whole job is realigning them). Reading
    the line removes the drift by construction instead of chasing it.

    The one real exception is a MILESTONE-SCOPED Direct Close, and this is why
    the expression is a CASE rather than a plain column swap. Closing a single
    milestone does not necessarily move the line's dispatch_status, and such a
    row represents only the milestone it closed — so it is worth that
    milestone's amount, not the whole line. The ms1_closed/ms2_closed test is
    the same one list_work_done_rows already uses for its visibility rule:

        ms1 only  -> pd.ms1_amount
        ms2 only  -> pd.ms2_amount
        both flags equal (0/0 normal row, or 1/1 whole-line close) -> line_amount

    Measured on live data when this was introduced: 59 of 61 Work Done rows
    already matched line_amount exactly, and both exceptions were MS2-only
    Direct Closes whose stored revenue was wrong — one holding the full line
    amount (1,383 against a 414.90 milestone) and one holding 0 against 49.80.

    Falls back to the plain line amount where the milestone columns are absent,
    so this is safe on a site that has not had that field yet.

    ``pd2`` is a second dispatch alias to fall back to, for the queries that
    reach the line two ways — list_work_done_rows joins it both through the
    rollout plan and through wd.system_id, and only the latter is guaranteed
    present on a teamless close.
    """
    def amt(field):
        if pd2:
            return f"COALESCE({pd}.{field}, {pd2}.{field}, 0)"
        return f"COALESCE({pd}.{field}, 0)"

    if not frappe.db.has_column("Work Done", "ms1_closed"):
        return amt("line_amount")
    return (
        f"CASE"
        f" WHEN IFNULL({wd}.ms1_closed, 0) = 1 AND IFNULL({wd}.ms2_closed, 0) = 0"
        f" THEN {amt('ms1_amount')}"
        f" WHEN IFNULL({wd}.ms2_closed, 0) = 1 AND IFNULL({wd}.ms1_closed, 0) = 0"
        f" THEN {amt('ms2_amount')}"
        f" ELSE {amt('line_amount')} END"
    )


_PO_LINE_CLOSED_ON = """GREATEST(
    COALESCE(pd.ms1_payment_received_date, pd.ms1_ibuy_inv_date, '1900-01-01'),
    COALESCE(pd.ms2_payment_received_date, pd.ms2_ibuy_inv_date, '1900-01-01')
)"""


def _open_po_line_totals(from_date=None, to_date=None):
    """Open order book: PO Intake Lines whose per-line status is not terminal.

    The line-wise status is the source of truth — the parent PO Intake's
    ``status`` is a roll-up and isn't authoritative for KPIs.

    This is a BACKLOG SNAPSHOT, not a flow, so it has no start bound and
    ``from_date`` is deliberately ignored. "Open lines this month" means
    every line still open, not the few that happened to be published inside
    the month — the previous behaviour filtered on publish date at both ends
    and so reported 8 open lines against a real backlog in the thousands,
    because every line published earlier and still open was excluded.

    ``to_date`` is the as-of date, and bounds existence only: a line counts
    if it had been published by then, on the basis
    ``COALESCE(publish_date, start_date, creation)`` — the same basis
    get_po_vs_invoice_trend() buckets by, since publish_date lands on only a
    minority of lines and start_date carries the rest.

    A line that has closed SINCE ``to_date`` is re-opened by the snapshot, so
    "as of yesterday" still counts what closed today. There is no closed-on
    field to read that from, so the closure is dated off the dispatch's
    billing chain instead — see _PO_LINE_CLOSED_ON above for the expression
    and why the payment date falls back to the i-BUY invoice date. Closures
    that cannot be dated at all stay counted as closed.

    Called with no range it is the live, unfiltered order book, which is how
    ``get_commercial_dashboard`` uses it — that screen deliberately has no
    date filter, and the two now agree whenever the dashboard's range ends
    today, instead of only when both were unscoped.
    """
    wheres = []
    params = []
    if to_date:
        # Existed by then...
        wheres.append("DATE(COALESCE(il.publish_date, il.start_date, il.creation)) <= %s")
        params.append(to_date)
        # ...and was still open then: either it is open now, or it has closed
        # since the as-of date. _PO_LINE_CLOSED_ON dates that closure.
        wheres.append(
            f"(IFNULL(il.po_line_status, 'New') NOT IN ('Closed', 'Cancelled')"
            f" OR {_PO_LINE_CLOSED_ON} > %s)"
        )
        params.append(to_date)
    else:
        wheres.append("IFNULL(il.po_line_status, 'New') NOT IN ('Closed', 'Cancelled')")
    rows = frappe.db.sql(
        f"""
        SELECT COALESCE(SUM(il.line_amount), 0) AS total_value, COUNT(*) AS line_count
        FROM `tabPO Intake Line` il
        LEFT JOIN `tabPO Dispatch` pd ON pd.poid = il.poid
        WHERE {' AND '.join(wheres)}
        """,
        tuple(params), as_dict=True,
    )
    return (rows[0] if rows else {}) or {}


_MONTH_ABBR = ("Jan", "Feb", "Mar", "Apr", "May", "Jun",
               "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


def _ym_label(ym):
    """``"2024-03"`` -> ``"Mar-24"`` (the axis label format the charts use)."""
    try:
        y, m = int(ym[:4]), int(ym[5:7])
        return f"{_MONTH_ABBR[m - 1]}-{y % 100:02d}"
    except Exception:
        return ym


def _month_spine(start_ym, end_ym, max_months=180):
    """Every ``YYYY-MM`` from start to end inclusive.

    Charts must receive a dense series: a line chart draws straight across a
    month that is simply absent from the data, which silently hides a gap.
    Months with no rows have to be explicit zeros instead.
    """
    if not start_ym or not end_ym or start_ym > end_ym:
        return []
    y, m = int(start_ym[:4]), int(start_ym[5:7])
    ey, em = int(end_ym[:4]), int(end_ym[5:7])
    out = []
    while (y, m) <= (ey, em) and len(out) < max_months:
        out.append(f"{y:04d}-{m:02d}")
        m += 1
        if m > 12:
            m, y = 1, y + 1
    return out


@frappe.whitelist()
def get_po_vs_invoice_trend(from_date=None, to_date=None, months=0, etag=None):
    """Monthly PO published value vs invoiced value, for the admin trend charts.

    Two series on a shared dense month spine:

    * ``po_value``  — SUM(`PO Intake Line`.line_amount) bucketed by the PO's
      published month, ``COALESCE(publish_date, start_date, creation)``.
      ``publish_date`` only lands on ~30% of lines (it comes from an optional
      upload column), so ``start_date`` carries most rows; ``po_date_basis``
      in the payload reports the split so the UI can be honest about it.
    * ``invoiced``  — the PIC "Monthly Invoicing Roll-up" verbatim, so this
      chart and the PIC dashboard always show the same number for a month.

    ``months`` (>0) overrides the date range with the trailing N months ending
    at the *current* month — deliberately anchored to today rather than to the
    last month holding data, so a PIC data-entry lag shows as a real decline
    instead of being cropped out of the window.

    Unguarded like ``get_command_dashboard``: PM/admin users are the audience
    and most of them lack the INET PIC role that ``get_pic_dashboard`` demands.
    """
    from inet_app.api.pic import _monthly_invoicing_rows

    months = cint(months)
    if months > 0:
        today = getdate(nowdate())
        end_ym = f"{today.year:04d}-{today.month:02d}"
        y, m = today.year, today.month - (months - 1)
        while m < 1:
            m += 12
            y -= 1
        start_ym = f"{y:04d}-{m:02d}"
        fd = getdate(f"{start_ym}-01")
        td = get_last_day(getdate(f"{end_ym}-01"))
    else:
        fd = getdate(from_date) if from_date else None
        td = getdate(to_date) if to_date else None
        start_ym = f"{fd.year:04d}-{fd.month:02d}" if fd else None
        end_ym = f"{td.year:04d}-{td.month:02d}" if td else None

    current_etag = _dashboard_etag("po_trend", start_ym, end_ym)
    if etag and etag == current_etag:
        return {"unchanged": True, "etag": current_etag, "last_updated": _iso_now()}

    # ── Series A: PO published value, bucketed by resolved publish month.
    # Join is `po_intake` + `po_line_no` (covered by idx_pd_po_intake_line) —
    # NOT `poid`, which is unindexed on both sides and trips MAX_JOIN_SIZE.
    po_having, po_params = "", []
    if start_ym and end_ym:
        po_having, po_params = "HAVING m BETWEEN %s AND %s", [start_ym, end_ym]
    elif start_ym:
        po_having, po_params = "HAVING m >= %s", [start_ym]
    elif end_ym:
        po_having, po_params = "HAVING m <= %s", [end_ym]

    po_rows = frappe.db.sql(
        f"""
        SELECT DATE_FORMAT(COALESCE(il.publish_date, il.start_date, il.creation),
                           '%%Y-%%m') AS m,
               COALESCE(SUM(il.line_amount), 0) AS po_value,
               COUNT(*) AS po_lines
        FROM `tabPO Intake Line` il
        LEFT JOIN `tabPO Dispatch` pd
               ON pd.po_intake = il.parent AND pd.po_line_no = il.po_line_no
        WHERE IFNULL(il.po_line_status, 'New') <> 'Cancelled'
          AND IFNULL(pd.is_dummy_po, 0) = 0
          AND IFNULL(pd.is_internal_work, 0) = 0
        GROUP BY m
        {po_having}
        ORDER BY m
        """,
        tuple(po_params),
        as_dict=True,
    )

    # ── Series B: invoiced — the shared PIC roll-up, which now carries the
    # reporting definition (full milestone amount at Submitted/Closed), so
    # this chart and the PIC dashboard agree by construction.
    inv_rows = _monthly_invoicing_rows(fd, td, order="ASC", limit=None)

    po_by_month = {r["m"]: r for r in po_rows if r.get("m")}
    inv_by_month = {r["invoice_month"]: r for r in inv_rows if r.get("invoice_month")}

    if months > 0:
        spine = _month_spine(start_ym, end_ym)
    else:
        keys = sorted(set(po_by_month) | set(inv_by_month))
        spine = _month_spine(keys[0], keys[-1]) if keys else []

    series = []
    for ym in spine:
        p = po_by_month.get(ym) or {}
        i = inv_by_month.get(ym) or {}
        series.append({
            "m": ym,
            "label": _ym_label(ym),
            "po_value": flt(p.get("po_value") or 0, 2),
            "po_lines": cint(p.get("po_lines") or 0),
            "invoiced": flt(i.get("total") or 0, 2),
        })

    total_po = sum(r["po_value"] for r in series)
    total_inv = sum(r["invoiced"] for r in series)

    basis = frappe.db.sql(
        """
        SELECT
          SUM(publish_date IS NOT NULL)                              AS by_publish,
          SUM(publish_date IS NULL AND start_date IS NOT NULL)       AS by_start,
          SUM(publish_date IS NULL AND start_date IS NULL)           AS by_creation
        FROM `tabPO Intake Line`
        WHERE IFNULL(po_line_status, 'New') <> 'Cancelled'
        """,
        as_dict=True,
    )
    basis_row = basis[0] if basis else {}

    return {
        "series": series,
        "totals": {
            "po_value": flt(total_po, 2),
            "invoiced": flt(total_inv, 2),
            "conversion_pct": flt((total_inv / total_po * 100) if total_po else 0, 1),
        },
        "po_date_basis": {
            "publish_date": cint(basis_row.get("by_publish") or 0),
            "start_date": cint(basis_row.get("by_start") or 0),
            "creation": cint(basis_row.get("by_creation") or 0),
        },
        "undated_invoiced": _undated_invoiced_value(),
        "range": {"from_month": start_ym, "to_month": end_ym, "months": months},
        "etag": current_etag,
        "last_updated": _iso_now(),
    }


@frappe.whitelist()
def get_team_domain_utilization(month=None, domains=None, include_fridays=0, etag=None):
    """Daily team idle / project-domain grid — the report handed to the domains.

    One row per Active INET Team (labelled by its ISDP account), one column per
    day of ``month``, and per cell either the project domain the team worked in
    that day or ``Idle``. Trailing column = idle days per team; footer row =
    idle teams per day.

    ``domains`` (multi-select of Project Domain names) does not remove rows: a
    day whose domain is selected shows that domain's own name, any *other*
    domain collapses to ``Other``, and no work is still ``Idle``. So the grid
    keeps its shape and only the labelling narrows.

    Attendance is the inclusive span ``execution_date`` ->
    ``last_progress_date`` on Daily Execution; with no last-progress date the
    execution counts as that single day. ``Daily Execution.team`` is the
    signal — verified to be set on every row and never shared between teams.
    If production ever shares one execution across teams, extend via
    ``Rollout Plan Team.execution_name``.

    Fridays are omitted to match the delivered report; pass
    ``include_fridays=1`` to keep them.

    No ``Leave`` state: nothing in inet_app records team leave yet, so it is
    deliberately absent rather than guessed at.

    Days outside a team's start/end window render ``-`` and never count as
    idle — a team cannot be idle before it existed.

    FUTURE days are never idle either: a day that has not happened yet cannot
    have been wasted, and counting it made the current month's idle figures
    read as though the rest of it were already lost (a mid-month view showed
    every remaining day as Idle and rolled them into both totals). Those days
    show the ROLLOUT PLAN instead — the planned domain where the team has one,
    else ``No Plan``, which is a planning gap worth seeing rather than an idle
    day. Neither counts toward idle_days, idle_per_day or grand_total_idle,
    and idle_per_day is None for a future column so the footer can say "not
    yet" instead of a misleading 0.

    ``kinds`` runs parallel to ``cells`` and says what each value IS — actual /
    idle / planned / unplanned / na — so the grid can colour a planned domain
    differently from a domain actually worked instead of the two looking
    identical.
    """
    from calendar import monthrange

    NA, IDLE, OTHER, NO_DOMAIN, NO_PLAN = "-", "Idle", "Other", "No Domain", "No Plan"
    K_NA, K_IDLE, K_ACTUAL, K_PLANNED, K_UNPLANNED = (
        "na", "idle", "actual", "planned", "unplanned")

    today = getdate(nowdate())
    if month:
        y, m = int(str(month)[:4]), int(str(month)[5:7])
    else:
        y, m = today.year, today.month
    first = date(y, m, 1)
    last = date(y, m, monthrange(y, m)[1])

    selected = set(_ensure_list(domains))
    keep_fri = cint(include_fridays)

    # today.isoformat() is a required discriminator, not padding: the grid's
    # past/future split is drawn against the current date, so the same data on
    # a new day is a different answer. Without it the etag would still match
    # overnight and a client would be told "unchanged" while yesterday's
    # future column sat there as a plan that has since become an elapsed day.
    current_etag = _dashboard_etag(
        "team_domain", f"{y:04d}-{m:02d}", ",".join(sorted(selected)), keep_fri,
        today.isoformat())
    if etag and etag == current_etag:
        return {"unchanged": True, "etag": current_etag, "last_updated": _iso_now()}

    # Friday == weekday 4. The delivered report drops them.
    days = []
    d = first
    while d <= last:
        if keep_fri or d.weekday() != 4:
            days.append(d)
        d = add_days(d, 1)

    teams = frappe.db.sql(
        """
        SELECT name, team_name, isdp_account, start_date, end_date, team_category
        FROM `tabINET Team`
        WHERE IFNULL(status, '') = 'Active'
        ORDER BY IFNULL(NULLIF(isdp_account, ''), team_name)
        """,
        as_dict=True,
    )

    # Executions overlapping the month, with the domain resolved from the
    # POID's own PO Dispatch.project_domain first (the IM can override this
    # per line — Create Rollout Plan / Direct Close / Backend Assign — see
    # _enrich_with_project_fields for the same override-wins rule elsewhere)
    # and only falling back to the project's default domain when the line
    # was never overridden. Span is clamped to the month, so one row can
    # contribute at most ~31 days no matter how stale its last_progress_date is.
    execs = frappe.db.sql(
        """
        SELECT de.team AS team,
               de.execution_date AS d1,
               COALESCE(de.last_progress_date, de.execution_date) AS d2,
               NULLIF(COALESCE(NULLIF(pd.project_domain, ''), pcc.project_domain), '') AS domain
        FROM `tabDaily Execution` de
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = de.system_id
        LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
        WHERE de.execution_date IS NOT NULL
          AND IFNULL(de.team, '') != ''
          AND de.execution_date <= %s
          AND COALESCE(de.last_progress_date, de.execution_date) >= %s
        """,
        (last, first),
        as_dict=True,
    )

    # Rollout plans from today onward, for the future half of the grid. Only
    # the future needs them: a past day is judged on what was actually
    # executed, and showing a plan there would paper over work that never
    # happened.
    #
    # Both team sources, same as the multi-team fix applied to the performance
    # reports: Rollout Plan.team is only the LEAD team, and the rest of a split
    # plan live in Rollout Plan Team — without the UNION a team would look
    # unplanned on a day it is in fact scheduled. Cancelled plans are excluded;
    # a cancelled plan is not work anyone intends to do.
    plans = frappe.db.sql(
        """
        SELECT t.team AS team,
               rp.plan_date AS d,
               NULLIF(COALESCE(NULLIF(pd.project_domain, ''), pcc.project_domain), '') AS domain
        FROM `tabRollout Plan` rp
        JOIN (
            SELECT name AS plan, team FROM `tabRollout Plan` WHERE IFNULL(team, '') != ''
            UNION
            SELECT parent AS plan, team FROM `tabRollout Plan Team` WHERE IFNULL(team, '') != ''
        ) t ON t.plan = rp.name
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
        WHERE rp.plan_date BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
        """,
        (max(first, today), last), as_dict=True,
    )

    # (team, isodate) -> {domain: plan count}
    planned = {}
    for r in plans:
        dom = r.get("domain") or NO_DOMAIN
        slot = planned.setdefault((r["team"], getdate(r["d"]).isoformat()), {})
        slot[dom] = slot.get(dom, 0) + 1

    # (team, isodate) -> {domain: execution count}
    worked = {}
    undomained = 0
    for r in execs:
        dom = r.get("domain") or NO_DOMAIN
        if dom == NO_DOMAIN:
            undomained += 1
        cur = max(getdate(r["d1"]), first)
        end = min(getdate(r["d2"]), last)
        while cur <= end:
            slot = worked.setdefault((r["team"], cur.isoformat()), {})
            slot[dom] = slot.get(dom, 0) + 1
            cur = add_days(cur, 1)

    def pick(counts, allowed=None):
        """Most-executed domain that day; alphabetical tie-break for stability."""
        items = [(k, v) for k, v in counts.items() if allowed is None or k in allowed]
        if not items:
            return None
        return sorted(items, key=lambda kv: (-kv[1], kv[0]))[0][0]

    # A future column's idle count is None, not 0 — nothing is idle yet, and a
    # 0 would read as "every team busy".
    is_future = [d > today for d in days]
    rows = []
    idle_per_day = [None if fut else 0 for fut in is_future]
    grand_total = 0
    for t in teams:
        t_start = getdate(t["start_date"]) if t.get("start_date") else None
        t_end = getdate(t["end_date"]) if t.get("end_date") else None
        cells, kinds, idle_days, planned_days = [], [], 0, 0
        for i, day in enumerate(days):
            if (t_start and day < t_start) or (t_end and day > t_end):
                cells.append(NA)
                kinds.append(K_NA)
                continue
            if is_future[i]:
                # Not yet happened, so not idle whatever the answer is.
                p_counts = planned.get((t["name"], day.isoformat()))
                if not p_counts:
                    cells.append(NO_PLAN)
                    kinds.append(K_UNPLANNED)
                    continue
                if selected:
                    cells.append(pick(p_counts, allowed=selected) or OTHER)
                else:
                    cells.append(pick(p_counts) or OTHER)
                kinds.append(K_PLANNED)
                planned_days += 1
                continue
            counts = worked.get((t["name"], day.isoformat()))
            if not counts:
                cells.append(IDLE)
                kinds.append(K_IDLE)
                idle_days += 1
                idle_per_day[i] += 1
                continue
            if selected:
                hit = pick(counts, allowed=selected)
                cells.append(hit or OTHER)
            else:
                cells.append(pick(counts) or OTHER)
            kinds.append(K_ACTUAL)
        rows.append({
            "team": t["name"],
            "team_name": t.get("team_name"),
            "isdp_account": t.get("isdp_account") or "",
            "label": t.get("isdp_account") or t.get("team_name") or t["name"],
            "has_isdp": bool(t.get("isdp_account")),
            "cells": cells,
            "kinds": kinds,
            # Idle counts elapsed days only, so on the running month this is
            # "idle so far", not a forecast of the whole month.
            "idle_days": idle_days,
            "planned_days": planned_days,
        })
        grand_total += idle_days

    domain_options = frappe.get_all(
        "Project Domain", filters={"status": "Active"}, pluck="name", order_by="name")

    proj_total = frappe.db.count("Project Control Center")
    proj_no_domain = frappe.db.sql(
        "SELECT COUNT(*) FROM `tabProject Control Center` WHERE IFNULL(project_domain,'') = ''")[0][0]

    return {
        "month": f"{y:04d}-{m:02d}",
        "days": [{"d": d.isoformat(),
                  "label": d.strftime("%d-%b-%Y"),
                  "dow": d.strftime("%a"),
                  "future": d > today} for d in days],
        "rows": rows,
        "totals": {
            "idle_per_day": idle_per_day,
            "grand_total_idle": grand_total,
            # So the grid can say what the idle figure actually covers rather
            # than implying it spans the whole month.
            "elapsed_days": sum(1 for f in is_future if not f),
            "future_days": sum(1 for f in is_future if f),
            "grand_total_planned": sum(r["planned_days"] for r in rows),
        },
        "domain_options": domain_options,
        "domains_selected": sorted(selected),
        "include_fridays": bool(keep_fri),
        # Surfaced so an empty-looking grid explains itself instead of reading
        # as a bug: both of these fields are unpopulated on local data.
        "coverage": {
            "teams": len(teams),
            "teams_without_isdp": sum(1 for r in rows if not r["has_isdp"]),
            "projects": cint(proj_total),
            "projects_without_domain": cint(proj_no_domain),
            "executions_in_window": len(execs),
            "executions_without_domain": undomained,
        },
        "etag": current_etag,
        "last_updated": _iso_now(),
    }


@frappe.whitelist()
def get_commercial_dashboard(etag=None):
    """Commercial (order-book + invoicing) figures for the admin dashboard.

    The Commercial dashboard used to read its money tiles off
    ``get_command_dashboard``, which is an *operational day/month* payload —
    ``company.total_achieved`` is this month's Work Done revenue, so "Total
    Revenue" rendered as a few hundred SAR while PIC reported millions
    invoiced. Everything money-shaped here now comes from the PIC computation
    (``pic_dashboard_payload``) and the order book from the same helper
    ``get_command_dashboard`` uses, so this screen agrees with both by
    construction rather than by coincidence.

    Deliberately takes no date range. The two trend charts each carry their
    own time filter, and the KPI tiles are lifetime figures matching PIC's
    unfiltered default.

    A page-level date filter was investigated and dropped: this payload mixes
    flows (invoiced, paid — dated by invoicing month) with stocks (backlog,
    open order book — no invoicing date exists for them; of 4,584 backlog
    lines only 2 carry an invoice month). Scoping everything by date would
    zero the Backlog tile and push Billed % to ~100%. If it is ever revisited,
    scope the flows only and leave the stocks alone — which is exactly what
    ``get_command_dashboard`` does with ``total_open_po_line_value``.
    """
    from inet_app.api.pic import pic_dashboard_payload

    current_etag = _dashboard_etag("commercial")
    if etag and etag == current_etag:
        return {"unchanged": True, "etag": current_etag, "last_updated": _iso_now()}

    pic = pic_dashboard_payload()
    kpi = pic.get("kpi") or {}

    open_po = _open_po_line_totals()

    # All money below uses the reporting definition of invoiced (full
    # milestone amount once the milestone reaches Submitted/Closed) — never
    # PIC's ms1_invoiced/ms1_unbilled display fields.
    per_im = frappe.db.sql(
        f"""
        SELECT pd.im AS im,
               COUNT(*) AS line_count,
               COALESCE(SUM({_INVOICED_VALUE_SQL}), 0) AS invoiced,
               COALESCE(SUM({_BACKLOG_VALUE_SQL}), 0) AS backlog
        FROM `tabPO Dispatch` pd
        WHERE {_REPORTING_SCOPE_SQL}
          AND IFNULL(pd.im, '') != ''
        GROUP BY pd.im
        ORDER BY invoiced DESC
        LIMIT 10
        """,
        as_dict=True,
    )

    per_project = frappe.db.sql(
        f"""
        SELECT pd.project_code AS project_code,
               COALESCE(MAX(proj.project_name), pd.project_code) AS project_name,
               COUNT(*) AS line_count,
               COALESCE(SUM({_INVOICED_VALUE_SQL}), 0) AS invoiced,
               COALESCE(SUM({_BACKLOG_VALUE_SQL}), 0) AS backlog
        FROM `tabPO Dispatch` pd
        LEFT JOIN `tabProject Control Center` proj ON proj.name = pd.project_code
        WHERE {_REPORTING_SCOPE_SQL}
          AND IFNULL(pd.project_code, '') != ''
        GROUP BY pd.project_code
        ORDER BY invoiced DESC
        LIMIT 8
        """,
        as_dict=True,
    )

    # Subcontract resolution and the payout/margin split mirror the PIC
    # dashboard's INET-vs-Subcon query (pic.py _PIC_FROM_JOIN_LEAN + _split):
    # pd.contract wins, else the rollout-plan team's subcontractor, else the
    # backend team's. Percentages come off Subcontract Master the same way,
    # defaulting margin to 100% and payout to 0% when no master is linked.
    #
    # The alias is `sub_key`, NOT `contract` — `PO Dispatch` has a real
    # `contract` column, so `GROUP BY contract` binds to that column instead
    # of the SELECT alias and silently splits one subcontractor into two rows.
    per_subcontract = frappe.db.sql(
        f"""
        SELECT
          COALESCE(pd.contract, plan_contract.subcontractor, sc_team.subcontractor) AS sub_key,
          MAX(COALESCE(sm.subcontractor_name,
                       pd.contract, plan_contract.subcontractor, sc_team.subcontractor)) AS subcontractor_name,
          MAX(COALESCE(sm.type, 'SUB')) AS type,
          MAX(COALESCE(sm.sub_payout_pct, 0)) AS payout_pct,
          MAX(COALESCE(sm.inet_margin_pct, 100)) AS margin_pct,
          COUNT(*) AS line_count,
          COALESCE(SUM({_INVOICED_VALUE_SQL}), 0) AS invoiced,
          COALESCE(SUM({_BACKLOG_VALUE_SQL}), 0) AS backlog,
          COALESCE(SUM({_INVOICED_VALUE_SQL} * COALESCE(sm.sub_payout_pct, 0) / 100), 0) AS payout,
          COALESCE(SUM({_INVOICED_VALUE_SQL} * COALESCE(sm.inet_margin_pct, 100) / 100), 0) AS inet_margin
        FROM `tabPO Dispatch` pd
        LEFT JOIN (
            SELECT rp.po_dispatch, MAX(it.subcontractor) AS subcontractor
            FROM `tabRollout Plan` rp
            LEFT JOIN `tabINET Team` it ON it.name = rp.team
            GROUP BY rp.po_dispatch
        ) plan_contract ON plan_contract.po_dispatch = pd.name
        LEFT JOIN `tabINET Team` sc_team ON sc_team.name = pd.backend_team
        LEFT JOIN `tabSubcontract Master` sm
               ON sm.name = COALESCE(pd.contract, plan_contract.subcontractor, sc_team.subcontractor)
        WHERE {_REPORTING_SCOPE_SQL}
          AND COALESCE(pd.contract, plan_contract.subcontractor, sc_team.subcontractor) IS NOT NULL
        GROUP BY sub_key
        ORDER BY invoiced DESC
        LIMIT 12
        """,
        as_dict=True,
    )

    # Headline money, on the reporting definition. `invoiced + backlog` is an
    # exact partition of the total milestone value, which the PIC display
    # fields are not (they miss by ~SAR 3.5k of bad test data).
    totals = frappe.db.sql(
        f"""
        SELECT
          COALESCE(SUM({_INVOICED_VALUE_SQL}), 0) AS invoiced,
          COALESCE(SUM({_BACKLOG_VALUE_SQL}), 0) AS backlog,
          COALESCE(SUM(CASE WHEN {_MS1_INVOICED_SQL}
                            THEN IFNULL(pd.ms1_amount, 0) ELSE 0 END), 0) AS invoiced_ms1,
          COALESCE(SUM(CASE WHEN {_MS2_INVOICED_SQL}
                            THEN IFNULL(pd.ms2_amount, 0) ELSE 0 END), 0) AS invoiced_ms2,
          COALESCE(SUM(CASE WHEN pd.pic_status = 'Commercial Invoice Closed'
                            THEN IFNULL(pd.ms1_amount, 0) ELSE 0 END), 0)
        + COALESCE(SUM(CASE WHEN pd.pic_status_ms2 = 'Commercial Invoice Closed'
                            THEN IFNULL(pd.ms2_amount, 0) ELSE 0 END), 0) AS paid
        FROM `tabPO Dispatch` pd
        WHERE {_REPORTING_SCOPE_SQL}
        """,
        as_dict=True,
    )
    t = (totals[0] if totals else {}) or {}
    total_invoiced = flt(t.get("invoiced") or 0, 2)
    backlog = flt(t.get("backlog") or 0, 2)
    booked = total_invoiced + backlog

    return {
        "kpi": {
            "total_invoiced": total_invoiced,
            "invoiced_ms1": flt(t.get("invoiced_ms1") or 0, 2),
            "invoiced_ms2": flt(t.get("invoiced_ms2") or 0, 2),
            # "Closed" milestones only — invoice raised AND payment received.
            "paid": flt(t.get("paid") or 0, 2),
            "backlog": backlog,
            "booked_value": flt(booked, 2),
            "line_count": cint(kpi.get("line_count") or 0),
            "pending_count": cint(kpi.get("pending_count") or 0),
            "active_count": cint(kpi.get("active_count") or 0),
            "closed_count": cint(kpi.get("closed_count") or 0),
            "cancelled_count": cint(kpi.get("cancelled_count") or 0),
            # Share of booked milestone value that has been invoiced.
            # Denominator is invoiced + backlog, not the order book: PO value
            # with no milestone split yet was never billable.
            "billed_pct": flt((total_invoiced / booked * 100) if booked else 0, 1),
            # Share of invoiced value where payment has landed.
            "collected_pct": flt((flt(t.get("paid") or 0) / total_invoiced * 100)
                                 if total_invoiced else 0, 1),
        },
        "order_book": {
            "open_value": flt(open_po.get("total_value") or 0),
            "open_lines": cint(open_po.get("line_count") or 0),
        },
        "inet_subcon": pic.get("inet_subcon") or {},
        "per_im": per_im,
        "per_project": per_project,
        "per_subcontract": per_subcontract,
        "etag": current_etag,
        "last_updated": _iso_now(),
    }


def _inhouse_contract_names():
    """Subcontract Masters that represent INET's own work.

    payout 0 / margin 100 — the "INet Telecom *" contracts. Lets the Direct
    Close section's "Via INET" tile filter Work Done by contract, the same
    way its "Via Sub-Con" twin does, since the page can filter BY contract
    but cannot express "has none".
    """
    rows = frappe.db.sql(
        """
        SELECT name FROM `tabSubcontract Master`
        WHERE IFNULL(sub_payout_pct, 0) = 0
        """,
        as_dict=True,
    ) or []
    return [r.name for r in rows if r.name]


def _subcontracted_contract_names():
    """Subcontract Masters that represent genuinely subcontracted work.

    `sub_payout_pct > 0` is the test: every PO Dispatch links a contract, but
    the in-house ones ("INet Telecom F&C/M&D/M&W") carry payout 0 / margin
    100, so a linked contract alone does not mean the line was subcontracted.
    """
    rows = frappe.db.sql(
        """
        SELECT name FROM `tabSubcontract Master`
        WHERE IFNULL(sub_payout_pct, 0) > 0
        """,
        as_dict=True,
    ) or []
    return [r.name for r in rows if r.name]


def _all_team_names_by_type(team_type):
    """Every INET Team of one team_type, active or not.

    The dashboard's INET/Sub-Con revenue figures are keyed on team_type
    alone, so they include work by teams that have since been deactivated.
    Drill-throughs must filter on the same population or the list comes back
    short of the tile it was opened from.
    """
    rows = frappe.db.sql(
        """
        SELECT name FROM `tabINET Team`
        WHERE team_type = %s AND IFNULL(team_category, '') != 'Backend Team'
        """,
        (team_type,), as_dict=True,
    ) or []
    return [r.name for r in rows if r.name]


@frappe.whitelist()
def get_command_dashboard(from_date=None, to_date=None, etag=None):
    """
    Return ALL data for the admin Command Dashboard in a single API call.

    Optional ``from_date`` / ``to_date`` (ISO YYYY-MM-DD) override the default
    month window for date-scoped metrics (closed activities, revenue, cost,
    team activity, etc.). Strategic targets still use the running-month
    baseline so the pro-rated "target today" calc stays meaningful.

    If the caller passes the ``etag`` it last received, and nothing in the
    underlying tables has changed since, returns a small ``{"unchanged":
    True, "etag": ...}`` payload so polling clients save a full re-render.
    """
    current_etag = _dashboard_etag("cmd", from_date, to_date)
    if etag and etag == current_etag:
        return {"unchanged": True, "etag": current_etag, "last_updated": _iso_now()}
    # Short-lived cache, keyed BY the etag rather than merely expiring on a
    # timer: the etag already hashes MAX(modified) across every table this
    # payload reads, so any data change lands on a different key and a stale
    # payload can never be served. The TTL only bounds how long an idle
    # key sits in Redis.
    #
    # The point is the other dashboards. This endpoint is the whole payload
    # for the CEO, Financial and Operations screens as well, and those three
    # pass no etag (nothing to pass on a fresh mount) and block their entire
    # page on the result — so flipping between them through the dashboard
    # switcher recomputed this identical payload every time. First one warms
    # it, the rest are a Redis read.
    _cmd_cache_key = f"inet_cmd_dashboard::{current_etag}"
    _cached = frappe.cache().get_value(_cmd_cache_key, expires=True)
    if _cached:
        return _cached
    today_str = nowdate()
    today = getdate(today_str)
    first_day, last_day, _ = _month_bounds()
    if from_date:
        try: first_day = getdate(from_date)
        except Exception: pass
    if to_date:
        try: last_day = getdate(to_date)
        except Exception: pass

    # Pro-ration basis for the whole "Company Financial Summary" section:
    # progress through the SELECTED range (first_day..last_day), not through
    # the calendar month. A fully-past range (last_day before today) is
    # already 100% elapsed — no pro-rating; a range still in progress (today
    # falls inside it) pro-rates by how much of it has actually happened;
    # a range entirely in the future is 0% elapsed. This replaces an earlier
    # "day_of_month / 30" pro-ration that assumed the range was always
    # exactly "this month, 1st to today" — silently wrong for any other
    # from_date/to_date the caller picked.
    # _month_bounds() returns plain strings (for SQL params below); getdate()
    # them locally for the arithmetic without disturbing first_day/last_day
    # themselves — from_date/to_date go through getdate() above already, so
    # this only matters for the untouched default (no from_date/to_date).
    _range_start, _range_end = getdate(first_day), getdate(last_day)
    range_days = (_range_end - _range_start).days + 1
    elapsed_days = max(0, min(range_days, (today - _range_start).days + 1))
    range_elapsed_frac = (elapsed_days / range_days) if range_days else 0.0

    # ---- Operational KPIs --------------------------------------------------
    # Open lines = PO Intake Lines whose per-line status is NOT terminal.
    # The line-wise status is the source of truth — the parent PO Intake's
    # status field is just a roll-up and isn't authoritative for KPIs.
    # Scoped to the dashboard's range (by PO publish date) so these two tiles
    # respond to the filter like the rest of the section.
    _open_po_row = _open_po_line_totals(first_day, last_day)
    total_open_po_line_value = flt(_open_po_row.get("total_value") or 0)
    total_open_po_lines = cint(_open_po_row.get("line_count") or 0)
    # Legacy key: same as total open line amount (SAR)
    total_open_po = total_open_po_line_value

    # Teams with at least one execution today. Checks last_progress_date too,
    # not just execution_date — a multi-day plan's single reused Daily
    # Execution row never updates execution_date past its first day, so
    # last_progress_date is what actually reflects "touched today" from
    # day 2 onward (see the same fix in list_admin_teams/list_im_teams).
    active_team_rows = frappe.db.sql(
        """
        SELECT DISTINCT de.team FROM `tabDaily Execution` de
        LEFT JOIN `tabINET Team` it ON it.name = de.team
        WHERE (de.execution_date = %s OR de.last_progress_date = %s)
        AND de.execution_status NOT IN ('Cancelled')
        AND IFNULL(it.team_category, '') != 'Backend Team'
        """,
        (today_str, today_str),
        as_dict=True,
    )
    active_team_ids = {r.team for r in active_team_rows}
    active_teams_count = len(active_team_ids)

    # Teams with a Rollout Plan for TODAY in Planned/In Execution status
    # — they have assigned work today so they should NOT count as idle.
    # We use a bounded range against plan_end_date (falling back to
    # plan_date when never extended), not plan_date alone, so a multi-day
    # plan extended past its original plan_date still counts on day 2+ —
    # plan_date is stamped once at creation and never moves. This stays
    # bounded (not an open-ended <=), so old stale unexecuted plans from
    # past dates still don't prevent a team from being counted as idle
    # today — only plans genuinely extended to cover today do.
    # UNION in secondary teams from Rollout Plan Team (a plan split across
    # 2+ teams only records the first/primary team on rp.team itself — see
    # the same gap fixed in list_admin_teams/list_im_teams) so a secondary
    # team with real work today isn't miscounted as idle below.
    planned_team_rows = frappe.db.sql(
        """
        SELECT DISTINCT rp.team AS team FROM `tabRollout Plan` rp
        LEFT JOIN `tabINET Team` it ON it.name = rp.team
        WHERE rp.plan_status IN ('Planned', 'In Execution', 'Extended')
        AND %s BETWEEN rp.plan_date AND IFNULL(rp.plan_end_date, rp.plan_date)
        AND IFNULL(it.team_category, '') != 'Backend Team'
        AND IFNULL(it.status, 'Active') = 'Active'
        UNION
        SELECT DISTINCT rpt.team AS team FROM `tabRollout Plan Team` rpt
        INNER JOIN `tabRollout Plan` rp2 ON rp2.name = rpt.parent
        LEFT JOIN `tabINET Team` it2 ON it2.name = rpt.team
        WHERE rp2.plan_status IN ('Planned', 'In Execution', 'Extended')
        AND %s BETWEEN rp2.plan_date AND IFNULL(rp2.plan_end_date, rp2.plan_date)
        AND IFNULL(it2.team_category, '') != 'Backend Team'
        AND IFNULL(it2.status, 'Active') = 'Active'
        """,
        (today_str, today_str),
        as_dict=True,
    )
    # Union of executing + planned teams — used only for idle calculation
    non_idle_team_ids = active_team_ids | {r.team for r in planned_team_rows}

    total_teams = frappe.db.sql(
        "SELECT COUNT(*) FROM `tabINET Team` WHERE IFNULL(status, 'Active') = 'Active' AND IFNULL(team_category, '') != 'Backend Team'"
    )[0][0]
    idle_teams_count = max(0, total_teams - len(non_idle_team_ids))

    # These 4 pipeline tiles (Planned -> In Progress -> Work Done -> Closed)
    # each reuse the SAME function their own drill-down page calls, with the
    # SAME filters the click-through passes — count/amount = len()/sum() over
    # that exact result set. This is deliberate, not just convenient: a
    # bespoke COUNT query here previously drifted from what the routed-to
    # page actually showed (missing "Extended"/"Planning with Issue", no
    # latest-visit exclusion, an excludeBackend flag the destination page
    # never read, etc) — every one of those was a real reported bug. Reusing
    # the exact function makes tile and page permanently identical by
    # construction, the same fix already applied to "Total Work Done" earlier.
    #
    # All 4 tiles are scoped to first_day/last_day (rp.plan_date for the
    # first two) so the count always matches what you land on after
    # clicking through with the same range — a tile that doesn't move with
    # the date picker but a destination page that does is exactly the kind
    # of drift this whole rewrite was meant to eliminate.
    _planned_rows = list_execution_monitor_rows(
        filters={
            "status": ["Planned", "Extended", "Planning with Issue"],
            "from_date": str(first_day), "to_date": str(last_day),
        }, limit=0
    ) or []
    planned_activities = len(_planned_rows)
    planned_amount = sum(flt(r.get("target_amount")) for r in _planned_rows)

    # "In Progress" = actively executing, OR execution finished but Work Done
    # hasn't been generated yet. list_execution_monitor_rows already hides a
    # "Completed" row once it's fully closed (QC/CIAG pass + a real Work Done
    # record exists) — see its own unconditional hide-clause — so filtering
    # to just these two statuses naturally yields exactly "In Execution" plus
    # "Completed, still needs Generate Work Done", with no extra logic needed.
    _in_progress_rows = list_execution_monitor_rows(
        filters={
            "status": ["In Execution", "Completed"],
            "from_date": str(first_day), "to_date": str(last_day),
        }, limit=0
    ) or []
    in_progress_activities = len(_in_progress_rows)
    in_progress_amount = sum(flt(r.get("target_amount")) for r in _in_progress_rows)

    _workdone_rows = list_work_done_rows(
        filters={"tab": "all", "from_date": str(first_day), "to_date": str(last_day)}, limit=0
    ) or []
    workdone_activities = len(_workdone_rows)
    workdone_amount = sum(flt(r.get("revenue_sar")) for r in _workdone_rows)

    # Closed = every milestone a Work Done row represents has reached a
    # terminal PIC status — the exact inverse of list_work_done_rows' own
    # default-hide rule (_DATA_INTEGRITY_TERMINAL_MS), so "Closed" and "Work
    # Done" above partition the same universe with no overlap and no gap.
    # No drill-down route yet (list_work_done_rows has no "resolved only"
    # mode to route to) — a standalone query for now; if a route is added
    # later this should switch to reusing that mode instead, for the same
    # by-construction-consistency reason as the other 3 tiles.
    _closed_terminal_ms = list(_DATA_INTEGRITY_TERMINAL_MS)
    _closed_ph = ", ".join(["%s"] * len(_closed_terminal_ms))
    _closed_ms1 = "IFNULL(COALESCE(pd.pic_status, pd_sys.pic_status), '')"
    _closed_ms2 = "IFNULL(COALESCE(pd.pic_status_ms2, pd_sys.pic_status_ms2), '')"
    _closed_ms2_amt = "COALESCE(pd.ms2_amount, pd_sys.ms2_amount, 0)"
    closed_activities = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS cnt
        FROM `tabWork Done` wd
        LEFT JOIN `tabPO Dispatch` pd_sys ON pd_sys.name = wd.system_id
        LEFT JOIN `tabDaily Execution` de ON de.name = wd.execution
        LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE COALESCE(de.execution_date, DATE(wd.creation)) BETWEEN %s AND %s
        AND (
          (IFNULL(wd.ms1_closed,0) = 1 AND IFNULL(wd.ms2_closed,0) = 0 AND {_closed_ms1} IN ({_closed_ph}))
          OR
          (IFNULL(wd.ms2_closed,0) = 1 AND IFNULL(wd.ms1_closed,0) = 0 AND {_closed_ms2} IN ({_closed_ph}))
          OR
          (IFNULL(wd.ms1_closed,0) = IFNULL(wd.ms2_closed,0)
            AND {_closed_ms1} IN ({_closed_ph})
            AND ({_closed_ms2_amt} = 0 OR {_closed_ms2} IN ({_closed_ph})))
        )
        """,
        (first_day, last_day) + tuple(_closed_terminal_ms) * 4,
        as_dict=True,
    )[0].cnt or 0
    closed_amount = frappe.db.sql(
        f"""
        SELECT COALESCE(SUM(wd.revenue_sar), 0) AS total
        FROM `tabWork Done` wd
        LEFT JOIN `tabPO Dispatch` pd_sys ON pd_sys.name = wd.system_id
        LEFT JOIN `tabDaily Execution` de ON de.name = wd.execution
        LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE COALESCE(de.execution_date, DATE(wd.creation)) BETWEEN %s AND %s
        AND (
          (IFNULL(wd.ms1_closed,0) = 1 AND IFNULL(wd.ms2_closed,0) = 0 AND {_closed_ms1} IN ({_closed_ph}))
          OR
          (IFNULL(wd.ms2_closed,0) = 1 AND IFNULL(wd.ms1_closed,0) = 0 AND {_closed_ms2} IN ({_closed_ph}))
          OR
          (IFNULL(wd.ms1_closed,0) = IFNULL(wd.ms2_closed,0)
            AND {_closed_ms1} IN ({_closed_ph})
            AND ({_closed_ms2_amt} = 0 OR {_closed_ms2} IN ({_closed_ph})))
        )
        """,
        (first_day, last_day) + tuple(_closed_terminal_ms) * 4,
        as_dict=True,
    )[0].total or 0

    revisits = frappe.db.sql(
        """
        SELECT COUNT(*) AS cnt FROM `tabRollout Plan`
        WHERE visit_type = 'Re-Visit'
        AND plan_date BETWEEN %s AND %s
        """,
        (first_day, last_day),
        as_dict=True,
    )[0].cnt or 0

    open_dummy_pos = 0
    if frappe.db.has_column("PO Dispatch", "is_dummy_po"):
        open_dummy_pos = frappe.db.count("PO Dispatch", {"is_dummy_po": 1}) or 0

    # ---- INET KPIs ---------------------------------------------------------
    # Not status-filtered here — Active/Inactive/On Vacation all still cost
    # the company, only Disbanded stops (see _team_cost_days below, which
    # clips to end_date). active_inet_teams stays a literal "status=Active"
    # headcount tile, computed separately from the same rows so it doesn't
    # silently start counting Inactive/On Vacation/Disbanded teams too.
    inet_teams = frappe.db.sql(
        """
        SELECT name, team_id, daily_cost, im, start_date, end_date, status
        FROM `tabINET Team`
        WHERE team_type = 'INET'
        AND IFNULL(team_category, '') != 'Backend Team'
        """, as_dict=True
    )
    active_inet_teams = sum(1 for t in inet_teams if (t.status or "Active") == "Active")

    # Teams are monthly-paid (fixed salary): cost = daily_cost × days, where
    # days is however much of [first_day, last_day] this team was actually
    # active for (capped at 30 - the flat-monthly-salary rule), not always 30.
    inet_monthly_cost = sum(
        flt(t.daily_cost) * _team_cost_days(t.start_date, t.end_date, first_day, last_day)
        for t in inet_teams
    )

    # Monthly target = cost × 1.25 (25% margin), consistent with Command Dashboard frontend
    inet_monthly_target = round(inet_monthly_cost * 1.25)

    # Pro-rate linearly by calendar day (day 15 of 30 = 50%), matches Excel logic
    inet_target_today = round(inet_monthly_target * range_elapsed_frac)

    # Achieved: sum PO Dispatch line_amount for INET teams (excl. backend)
    # within the selected range — this used to be hardcoded to "current
    # month 1st -> today" regardless of from_date/to_date, which is why
    # Total Revenue never changed when a different range was picked.
    #
    # Excludes a line whose POID is genuinely subcontracted (payout > 0),
    # even if an INET-type team happened to execute it — the commercial
    # arrangement lives on the line, not the team (see the Subcontractor
    # KPIs comment below), so that line's revenue is INET's margin cut only,
    # already counted once via inet_margin_sub. Checked live: 3 such lines,
    # SAR 1,744 gross, were being counted here at full value AND again as
    # margin — this is what "how is Total Revenue calculated" turned up.
    inet_achieved_rows = frappe.db.sql(
        """
        SELECT COALESCE(SUM(pd.line_amount), 0) AS total
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` exe ON exe.name = wd.execution
        JOIN `tabINET Team` it ON it.name = exe.team
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        LEFT JOIN `tabSubcontract Master` sm ON sm.name = pd.contract
        WHERE it.team_type = 'INET'
        AND IFNULL(it.team_category, '') != 'Backend Team'
        AND IFNULL(sm.sub_payout_pct, 0) = 0
        AND exe.execution_date BETWEEN %s AND %s
        """,
        (first_day, last_day),
        as_dict=True,
    )
    inet_achieved = flt(inet_achieved_rows[0].total if inet_achieved_rows else 0)
    inet_gap_today = inet_target_today - inet_achieved

    # ---- Subcontractor KPIs ------------------------------------------------
    # Subcontracted work is identified by the POID's own `contract` link to
    # Subcontract Master — every PO Dispatch carries it, so this is a normal
    # field check — NOT by the executing team's type. A team can be anything;
    # the commercial arrangement lives on the line.
    #
    # The master holds the split: `inet_margin_pct` is what INET retains and
    # `sub_payout_pct` is what the subcontractor is paid (they sum to 100).
    # In-house contracts ("INet Telecom F&C/M&D/M&W") carry margin 100 /
    # payout 0, so `sub_payout_pct > 0` is what makes a line genuinely
    # subcontracted rather than merely having a contract linked.
    #
    # Nothing here reads Work Done's own cost/margin columns. SUB teams have
    # no daily cost, and the stored per-row cost/margin figures are not
    # reportable (they charge a whole team-day to each POID). Revenue comes
    # from wd.revenue_sar; expense and margin are derived from the master's
    # percentages, the way the reference Target_Control sheet does it.
    _sub_contracts = frappe.db.sql(
        """
        SELECT COUNT(*) AS cnt FROM `tabSubcontract Master`
        WHERE IFNULL(status, '') = 'Active' AND IFNULL(sub_payout_pct, 0) > 0
        """,
        as_dict=True,
    )
    active_sub_teams = cint(_sub_contracts[0].cnt if _sub_contracts else 0)

    # Realized: revenue on subcontracted POIDs, split by the master's pcts.
    # Dated by the execution where there is one and by wd.creation otherwise,
    # so a direct-closed subcontracted line is not silently dropped.
    _sub_rev_rows = frappe.db.sql(
        """
        SELECT COALESCE(SUM(wd.revenue_sar), 0) AS revenue,
               COALESCE(SUM(wd.revenue_sar * IFNULL(sm.sub_payout_pct, 0) / 100.0), 0) AS expense,
               COALESCE(SUM(wd.revenue_sar * IFNULL(sm.inet_margin_pct, 0) / 100.0), 0) AS margin,
               COUNT(DISTINCT pd.contract) AS contracts
        FROM `tabWork Done` wd
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        JOIN `tabSubcontract Master` sm ON sm.name = pd.contract
        LEFT JOIN `tabDaily Execution` de ON de.name = wd.execution
        WHERE IFNULL(sm.sub_payout_pct, 0) > 0
          AND COALESCE(de.execution_date, DATE(wd.creation)) BETWEEN %s AND %s
        """,
        (first_day, last_day), as_dict=True,
    )
    _sr = (_sub_rev_rows[0] if _sub_rev_rows else {}) or {}
    sub_revenue = flt(_sr.get("revenue"))
    sub_expense = flt(_sr.get("expense"))
    inet_margin_sub = flt(_sr.get("margin"))
    sub_contracts_active = cint(_sr.get("contracts"))

    # Target = the monthly commitment agreed per subcontract, the way the
    # reference Target_Control sheet does it. In that workbook the figure is
    # typed in per contract (27,000 / 27,000 / 150,000 / 60,000 / 90,000 =
    # 354,000); here it lives on Subcontract Master.monthly_target so it is
    # editable in one place instead of hand-keyed into a spreadsheet.
    #
    # Nothing in the app's own data can reproduce it: it is a commercial
    # commitment, not a derivable figure. Deriving it from rollout plans (the
    # previous attempt) put Target BELOW Revenue, because a direct-closed
    # line has revenue but no plan at all.
    #
    # The commitment is monthly, so it is scaled by how many 30-day months
    # the selected range spans — a one-month range gives one month's target.
    # `total_target_today` then pro-rates that by elapsed time, matching the
    # sheet's "Sub-Con Target x Day Progress %".
    #
    # Margin target uses each contract's agreed `inet_margin_pct`. The sheet
    # instead multiplies by the contract's *realized* margin %, which makes
    # the target move with actual performance — deliberately not copied.
    _sub_months = (range_days / 30.0) if range_days else 1.0
    _sub_tgt_rows = frappe.db.sql(
        """
        SELECT COALESCE(SUM(monthly_target), 0) AS target,
               COALESCE(SUM(monthly_target * IFNULL(inet_margin_pct, 0) / 100.0), 0) AS margin_target
        FROM `tabSubcontract Master`
        WHERE IFNULL(status, '') = 'Active' AND IFNULL(sub_payout_pct, 0) > 0
        """,
        as_dict=True,
    )
    _st = (_sub_tgt_rows[0] if _sub_tgt_rows else {}) or {}
    sub_monthly_target = flt(_st.get("target"))
    sub_target = round(sub_monthly_target * _sub_months, 2)
    inet_margin_target_sub = round(flt(_st.get("margin_target")) * _sub_months, 2)
    sub_gap = sub_target - sub_revenue

    # ---- Backend Teams KPIs ------------------------------------------------
    backend_active_teams = frappe.db.sql(
        "SELECT COUNT(*) AS cnt FROM `tabINET Team` WHERE IFNULL(status, 'Active') = 'Active' AND IFNULL(team_category, '') = 'Backend Team'"
    )[0][0] or 0

    _backend_pending_rows = frappe.db.sql(
        "SELECT COUNT(*) AS cnt, COALESCE(SUM(line_amount), 0) AS val FROM `tabPO Dispatch` WHERE subcon_status = 'Pending' AND dispatch_status = 'Backend Assigned' AND IFNULL(is_internal_work, 0) = 0",
        as_dict=True,
    )
    backend_assigned_pending = cint(_backend_pending_rows[0].cnt if _backend_pending_rows else 0)
    backend_pending_value = flt(_backend_pending_rows[0].val if _backend_pending_rows else 0)

    _backend_done_rows = frappe.db.sql(
        # dispatch_status IN (...): PIC progressing the line into its own
        # invoicing pipeline in the same month shouldn't retroactively drop
        # it out of "backend completed this month" — see
        # inet_app.api.pic._compute_dispatch_status_from_pic.
        "SELECT COUNT(*) AS cnt, COALESCE(SUM(line_amount), 0) AS val FROM `tabPO Dispatch` WHERE subcon_status = 'Completed' AND dispatch_status IN ('Completed', 'Partially Submitted', 'Submitted', 'Partially Closed', 'Closed') AND subcon_completed_on BETWEEN %s AND %s AND IFNULL(is_internal_work, 0) = 0",
        (first_day, last_day),
        as_dict=True,
    )
    backend_completed_mtd = cint(_backend_done_rows[0].cnt if _backend_done_rows else 0)
    backend_completed_value = flt(_backend_done_rows[0].val if _backend_done_rows else 0)

    # ---- Company-level KPIs ------------------------------------------------
    # True gross Total Revenue: every Work Done row's revenue, counted once,
    # regardless of team/channel — the client's own top-line "how much
    # business did we do" figure, including the portion that's owed out to
    # subcontractors. This is deliberately a single direct SUM rather than
    # re-adding inet_achieved + sub_revenue + direct_close + backend_close:
    # those four overlap (a subcontracted line closed with no team appears
    # in both its channel bucket AND the sub-con bucket — see total_achieved
    # below), so recombining them risks the exact double-count already fixed
    # there. A flat SUM over Work Done can't have that problem.
    #
    # Total Expense is total_cost_today just below (INET team cost + the
    # subcontractor payout) — Total Revenue − Total Expense is the company's
    # real margin, which comes out numerically equal to total_achieved below
    # (checked live) since Expense already nets out exactly the payout
    # portion embedded in this gross figure.
    _gross_rev_rows = frappe.db.sql(
        """
        SELECT COALESCE(SUM(wd.revenue_sar), 0) AS total
        FROM `tabWork Done` wd
        LEFT JOIN `tabDaily Execution` de ON de.name = wd.execution
        WHERE COALESCE(de.execution_date, DATE(wd.creation)) BETWEEN %s AND %s
        """,
        (first_day, last_day), as_dict=True,
    )
    total_revenue_gross = flt(_gross_rev_rows[0].total if _gross_rev_rows else 0)

    day_progress_pct = round(range_elapsed_frac * 100, 1)

    # INET cost pro-rated to however much of the selected range has elapsed
    # so far (1.0 / no reduction for a range that's already fully in the past).
    inet_cost_today = round(inet_monthly_cost * range_elapsed_frac, 2)
    inet_profit_loss_today = round(inet_achieved - inet_cost_today, 2)

    # Sub-Con target pro-rated the same way, on the margin-adjusted figure —
    # the Company-level Target (as of today) needs the same basis as
    # total_achieved (margin-only on the sub side), not the sub-con's own
    # gross target. See company_target's comment below for why.
    inet_margin_target_sub_today = round(inet_margin_target_sub * range_elapsed_frac, 2)
    total_target_today = round(inet_target_today + inet_margin_target_sub_today, 2)

    # Direct Close revenue — has no team at all, so it's invisible to
    # inet_achieved/sub_revenue above (both require a Daily Execution ->
    # INET Team join). Backend already has its own tracked tile
    # (backend_completed_value, via PO Dispatch fields, not Work Done) kept
    # deliberately separate; Direct Close has no equivalent anywhere in this
    # dashboard at all, so Total Revenue silently omitted it entirely.
    # ---- Direct Close / Backend KPIs ---------------------------------------
    # These closes have no Rollout Plan, no Daily Execution and no team, so
    # every team-keyed aggregate above is blind to them by construction.
    # They get their own section rather than being folded into the INET or
    # Sub-Con numbers: those must stay strictly team metrics, and mixing a
    # teamless close into them would make a team figure that no team did.
    #
    # Dated by wd.creation (when the close was recorded) — there is no
    # execution date to use. Split by wd.source so Direct Close and Backend
    # stay distinguishable. The subcontractor side comes from the POID's
    # contract link further down, not from Work Done's own subcontractor /
    # subcontract_cost columns, which are not reportable.
    _dc_rows = frappe.db.sql(
        """
        SELECT IFNULL(wd.source, '') AS source,
               COUNT(*) AS lines_count,
               COALESCE(SUM(wd.revenue_sar), 0) AS revenue,
               COUNT(DISTINCT NULLIF(pd.project_code, '')) AS projects
        FROM `tabWork Done` wd
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        WHERE IFNULL(wd.execution, '') = ''
          AND DATE(wd.creation) BETWEEN %s AND %s
        GROUP BY IFNULL(wd.source, '')
        """,
        (first_day, last_day), as_dict=True,
    ) or []
    _dc_by_source = {(r.source or "").strip(): r for r in _dc_rows}
    _dc = _dc_by_source.get("Direct Close")
    _bk = _dc_by_source.get("Backend")

    def _dc_val(row, key):
        return flt(row.get(key)) if row else 0.0

    def _dc_cnt(row, key):
        return cint(row.get(key)) if row else 0

    direct_close_achieved = _dc_val(_dc, "revenue")
    backend_close_achieved = _dc_val(_bk, "revenue")

    # Who executed the closed work: a subcontractor, or INET itself. This is
    # the split that matters on a teamless close — there is no team to read
    # it from, so it comes off the Work Done row's own subcontractor /
    # subcontract cost. Revenue as well as line counts, since a count alone
    # says nothing about how much money each side represents.
    # Grouped by source AND side: Direct Close is shown split in its own
    # section below; Backend's split isn't shown anywhere yet, but is needed
    # here regardless — a Backend close on a subcontracted POID (2 lines,
    # SAR 4,415 gross, checked live) is just as invisible to
    # backend_close_achieved's blind gross sum as a Direct Close one is, and
    # would double-count against inet_margin_sub the same way.
    # Split on the POID's own contract link, the same test the Sub-Contractor
    # block uses (payout > 0 = genuinely subcontracted; the in-house INet
    # Telecom contracts carry payout 0). Deliberately NOT on Work Done's
    # subcontractor / subcontract_cost columns — those per-row cost figures
    # are not reportable.
    _dc_who_rows = frappe.db.sql(
        """
        SELECT IFNULL(wd.source, '') AS source,
               CASE WHEN IFNULL(sm.sub_payout_pct, 0) > 0
                    THEN 'SUB' ELSE 'INET' END AS side,
               COUNT(*) AS lines_count,
               COALESCE(SUM(wd.revenue_sar), 0) AS revenue
        FROM `tabWork Done` wd
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        LEFT JOIN `tabSubcontract Master` sm ON sm.name = pd.contract
        WHERE IFNULL(wd.execution, '') = ''
          AND IFNULL(wd.source, '') IN ('Direct Close', 'Backend')
          AND DATE(wd.creation) BETWEEN %s AND %s
        GROUP BY source, side
        """,
        (first_day, last_day), as_dict=True,
    ) or []
    _dc_who = {(r.side or ""): r for r in _dc_who_rows if (r.source or "") == "Direct Close"}
    _bk_who = {(r.side or ""): r for r in _dc_who_rows if (r.source or "") == "Backend"}
    _dc_sub, _dc_inet = _dc_who.get("SUB"), _dc_who.get("INET")
    backend_close_inet_only = _dc_val(_bk_who.get("INET"), "revenue")

    direct_close = {
        "revenue": direct_close_achieved,
        "lines": _dc_cnt(_dc, "lines_count"),
        "projects": _dc_cnt(_dc, "projects"),
        # Who did the work — a teamless close has no team to read it from,
        # so it comes off the Work Done row's own subcontractor /
        # subcontract cost. These two partition the section exactly:
        # sub_revenue + inet_revenue == revenue.
        "sub_revenue": _dc_val(_dc_sub, "revenue"),
        "sub_lines": _dc_cnt(_dc_sub, "lines_count"),
        "inet_revenue": _dc_val(_dc_inet, "revenue"),
        "inet_lines": _dc_cnt(_dc_inet, "lines_count"),
        # Contract lists so both Via tiles can drill through by contract.
        "sub_contract_names": _subcontracted_contract_names(),
        "inet_contract_names": _inhouse_contract_names(),
    }

    # Total Revenue = INET achieved (team execution) + INET's margin from
    # sub-con (not full sub-con revenue) + the teamless closes, which are
    # realized Work Done revenue exactly like the first term but reachable
    # only via wd.system_id. Backend close revenue is included here for the
    # first time: it was in no total at all, so Total Revenue understated by
    # it. This does not double count against the Backend Teams tile —
    # backend_completed_value sums PO Dispatch.line_amount dated by
    # subcon_completed_on (contracted value, order-book style), a different
    # measure on a different date basis from Work Done revenue.
    #
    # direct_close_achieved / backend_close_achieved are the RAW, unsplit
    # gross for each bucket (kept as-is for the "Revenue (No Team)" / Backend
    # tiles, which show total money processed through that channel). But a
    # subcontracted line inside either bucket already has its revenue counted
    # in full there — using that raw gross here as well as inet_margin_sub
    # would count the same line twice: once at its full value, once again at
    # just its margin. Only the INET-side slice of each bucket belongs in
    # Total Revenue; the SUB-side slice is represented by inet_margin_sub
    # instead. Checked live against the dashboard: a single subcontracted
    # Direct Close line (SAR 726 gross, 15% margin) was inflating Total
    # Revenue by its own margin a second time (SAR 109) on top of counting
    # its full SAR 726 — this is what turned up under "how is Total Revenue
    # calculated".
    # company_target uses inet_margin_target_sub (INET's margin-share of the
    # sub-con target), not sub_target (the sub-con's own full gross target).
    # total_achieved below only ever counts INET's margin from subcontracted
    # work, never the gross — so the target it's measured against has to be
    # on that same basis, or Coverage % compares a margin-only actual to a
    # gross-inclusive target and reads permanently low the moment
    # Subcontract Master.monthly_target gets filled in (it's 0 on all seven
    # contracts today, so company_target ≈ inet_monthly_target alone and the
    # mismatch is dormant — but real subcontract targets will make it bite).
    # This is the workbook's own stated design rule (Target_Control's note:
    # "so the dashboard does not mix gross subcontract revenue with INET
    # retained revenue") — its own Total INET Target/Total Revenue actually
    # violate it exactly this way, which is why it never turns that pair
    # into a %, only ever a $ gap. We do want a Coverage % tile, so both
    # sides go on INET's own basis instead of dropping the ratio.
    company_target = inet_monthly_target + inet_margin_target_sub
    total_achieved = (
        inet_achieved + inet_margin_sub
        + direct_close["inet_revenue"] + backend_close_inet_only
    )
    # Total Cost Today = pro-rated INET cost + sub-con expense (actual, not pro-rated)
    total_cost_today = round(inet_cost_today + sub_expense, 2)
    company_gap = company_target - total_achieved
    # Profit/Loss = Total Revenue (gross) − Total Expense (INET cost + the
    # subcontractor payout) — both comprehensive figures on the same gross
    # basis, so this is a clean P&L subtraction. NOT total_achieved (margin)
    # − total_cost_today: total_achieved already excludes the subcontractor
    # payout (it's margin-only on the sub side, see its comment above), so
    # subtracting sub_expense from it a second time double-counted the same
    # SAR twice. Confirmed live: the two formulas gave −1,258.2 vs the
    # correct −641.1 (== total_achieved − inet_cost_today, verified equal).
    profit_loss = round(total_revenue_gross - total_cost_today, 2)
    coverage_pct = (total_achieved / company_target * 100.0) if company_target else 0.0

    # ---- Top 5 teams + IM performance -------------------------------------
    # Both come straight from the report functions the Reports page serves,
    # so a widget and its report can never disagree. These were ~150 lines of
    # near-duplicate queries here, and they had drifted badly: the copies
    # reached Work Done only through Daily Execution and read de.team alone,
    # so a team's revenue disappeared unless Work Done had been generated for
    # it, and a split plan's non-executing teams were invisible. That is why
    # IM Performance showed Teams 0 for every IM, and Cost 0 for any IM whose
    # revenue came from a Direct Close. The Operations dashboard's Team
    # Performance / IM Performance tables read this same payload, so they
    # were wrong in exactly the same way and are fixed with it.
    _tt_report = get_top_teams_report(from_date=first_day, to_date=last_day)
    # Teams with no activity at all in the period are dropped rather than
    # padding out a list titled "Top 5". The report itself still lists every
    # team — an idle salaried team is a real cost, worth seeing there — but a
    # widget showing the best five should not spend its slots on zero rows.
    top_teams = [
        {
            "team":      r.get("team_name"),
            "team_name": r.get("team_name"),
            "revenue":   r.get("revenue"),
            "team_cost": r.get("team_cost"),
            "profit":    r.get("profit"),
        }
        for r in (_tt_report.get("data") or [])
        if flt(r.get("revenue"))
        or cint(r.get("assigned_lines"))
        or cint(r.get("completed_lines"))
    ][:5]

    _ip_report = get_im_performance_report(from_date=first_day, to_date=last_day)
    im_perf = [
        {
            "im":        r.get("im"),
            "teams":     r.get("teams"),
            "revenue":   r.get("revenue"),
            "team_cost": r.get("team_cost"),
            "profit":    r.get("profit"),
        }
        for r in (_ip_report.get("data") or [])
    ]

    # ---- Team status summary -----------------------------------------------
    # Teams that have any Daily Execution today (started or completed work)
    in_progress_count = len(active_team_ids)

    # Same secondary-team UNION as planned_team_rows above — and same
    # plan_end_date-bounded range fix, for the same day-2+ reason.
    planned_today = frappe.db.sql(
        """
        SELECT COUNT(DISTINCT team) AS cnt FROM (
            SELECT rp.team AS team FROM `tabRollout Plan` rp
            WHERE %s BETWEEN rp.plan_date AND IFNULL(rp.plan_end_date, rp.plan_date)
            AND rp.plan_status IN ('Planned', 'Extended')
            UNION
            SELECT rpt.team AS team FROM `tabRollout Plan Team` rpt
            INNER JOIN `tabRollout Plan` rp2 ON rp2.name = rpt.parent
            WHERE %s BETWEEN rp2.plan_date AND IFNULL(rp2.plan_end_date, rp2.plan_date)
            AND rp2.plan_status IN ('Planned', 'Extended')
        ) combined
        """,
        (today_str, today_str),
        as_dict=True,
    )[0].cnt or 0

    # Teams that have a plan today but are NOT yet executing (pure "Planned" state)
    teams_planned_only = len({r.team for r in planned_team_rows} - active_team_ids)

    team_status = {
        "active": total_teams,
        "idle": idle_teams_count,
        "planned": planned_today,           # distinct teams with any plan today (for bar chart compat)
        "teams_planned": teams_planned_only, # teams planned but not yet executing
        "in_progress": in_progress_count,
    }

    # ---- Watchlist (action items) — shape matches CommandDashboard.jsx ------
    watchlist = []
    issue_rows = frappe.db.sql(
        """
        SELECT COALESCE(rp.issue_category, 'Uncategorized') AS issue_category, COUNT(*) AS cnt
        FROM `tabDaily Execution` de
        JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        WHERE de.qc_status = 'Fail'
        AND de.execution_date BETWEEN %s AND %s
        GROUP BY COALESCE(rp.issue_category, 'Uncategorized')
        ORDER BY cnt DESC
        LIMIT 5
        """,
        (first_day, last_day),
        as_dict=True,
    )
    for row in issue_rows:
        cnt = cint(row.cnt)
        watchlist.append(
            {
                "indicator": f"QC open issues — {row.issue_category}",
                "current": cnt,
                # `current` is a count on some rows and SAR on others, so each
                # row states its unit; the dashboard cannot format a team
                # count and a revenue gap with the same formatter.
                "unit": "count",
                "target": None,
                "status": "Recover",
            }
        )

    if idle_teams_count > 0:
        watchlist.append(
            {
                "indicator": "Idle teams today",
                "current": idle_teams_count,
                "unit": "count",
                "target": None,
                "status": "Behind",
            }
        )
    if inet_gap_today > 0:
        watchlist.append(
            {
                "indicator": "INET revenue gap (month-to-date vs prorated target)",
                "current": inet_gap_today,
                "unit": "sar",
                "target": None,
                "status": "Recover",
            }
        )
    if sub_gap > 0:
        watchlist.append(
            {
                "indicator": "Subcontractor revenue gap",
                "current": sub_gap,
                "unit": "sar",
                "target": None,
                "status": "Recover",
            }
        )
    if not watchlist:
        watchlist.append(
            {
                "indicator": "Operational health",
                "current": 0,
                "unit": "count",
                "target": None,
                "status": "Optimized",
            }
        )

    payload = {
        "operational": {
            "total_open_po_lines": total_open_po_lines,
            "total_open_po_line_value": total_open_po_line_value,
            "total_open_po": total_open_po,
            "active_teams": active_teams_count,
            "idle_teams": idle_teams_count,
            "planned_activities": planned_activities,
            "planned_amount": planned_amount,
            "in_progress_activities": in_progress_activities,
            "in_progress_amount": in_progress_amount,
            "workdone_activities": workdone_activities,
            "workdone_amount": workdone_amount,
            "closed_activities": closed_activities,
            "closed_amount": closed_amount,
            "revisits": revisits,
            "open_dummy_pos": open_dummy_pos,
        },
        "inet": {
            "active_inet_teams": active_inet_teams,
            "inet_monthly_cost": inet_monthly_cost,
            "inet_monthly_target": inet_monthly_target,
            "inet_target_today": inet_target_today,
            "inet_achieved": inet_achieved,
            "inet_gap_today": inet_gap_today,
            "inet_profit_loss_today": inet_profit_loss_today,
            # Team names behind these figures, so the dashboard's drill-through
            # filters Work Done to these teams instead of landing on every row
            # and contradicting the tile. Every team of the type, not just the
            # currently-active ones: inet_achieved is keyed on team_type alone,
            # so revenue from a since-deactivated team is in the figure and its
            # rows must not be filtered out of the drill-through.
            "team_names": _all_team_names_by_type("INET"),
        },
        "subcon": {
            "active_sub_teams": active_sub_teams,
            "sub_target": sub_target,
            "inet_margin_target_sub": inet_margin_target_sub,
            "sub_revenue": sub_revenue,
            "sub_expense": sub_expense,
            "inet_margin_sub": inet_margin_sub,
            "sub_gap": sub_gap,
            "contracts_with_activity": sub_contracts_active,
            # The un-scaled monthly commitment, so the UI can say whether the
            # target is unset (0) rather than just showing a scaled zero.
            "monthly_target": sub_monthly_target,
            # Subcontract Master names behind these figures, so the drill-through
            # filters Work Done by the POID's `contract` link (the same thing
            # this block is keyed on) rather than by team.
            "contract_names": _subcontracted_contract_names(),
        },
        "backend": {
            "active_teams": backend_active_teams,
            "assigned_pending": backend_assigned_pending,
            "pending_value": backend_pending_value,
            "completed_mtd": backend_completed_mtd,
            "completed_value": backend_completed_value,
            # Backend closes recorded as Work Done (no execution, no team).
            # Reported here rather than in the Direct Close section so one
            # figure lives in one place. Distinct from completed_value above,
            # which is contracted PO line value dated by subcon_completed_on.
            "close_revenue": backend_close_achieved,
            "close_lines": _dc_cnt(_bk, "lines_count"),
        },
        # Teamless closes, kept out of the INET/Sub-Con team blocks on purpose.
        "direct_close": direct_close,
        "company": {
            "day_progress_pct": day_progress_pct,
            "company_target": company_target,
            "total_target_today": total_target_today,
            # Gross top-line — every SAR of work recognized, INET's own and
            # subcontracted alike, at full value. This is the "Total Revenue"
            # tile. total_achieved (below) is a different, narrower figure —
            # INET's own retained share only — used for Target/Gap/Coverage %,
            # which are commitments against INET's own margin, not gross
            # throughput.
            "total_revenue": total_revenue_gross,
            "total_achieved": total_achieved,
            "company_gap": company_gap,
            "total_cost_today": total_cost_today,
            "profit_loss": profit_loss,
            "coverage_pct": coverage_pct,
        },
        "top_teams": top_teams,
        "im_performance": im_perf,
        "team_status": team_status,
        "watchlist": watchlist,
        "last_updated": _iso_now(),
        "etag": current_etag,
    }
    frappe.cache().set_value(_cmd_cache_key, payload, expires_in_sec=120)
    return payload


def resolve_im_for_session(im=None):
    """
    Resolve IM Master document name + all identifier strings usable in PO Dispatch.im
    and similar Link fields. Shared by IM dashboard, pipeline lists, and overview APIs.
    """
    session_user = frappe.session.user
    user_full_name = frappe.db.get_value("User", session_user, "full_name") or ""
    im_rec = None

    def _find_im_rec(filters):
        if not frappe.db.exists("DocType", "IM Master"):
            return None
        try:
            rows = frappe.get_all(
                "IM Master", filters=filters,
                fields=["name", "full_name", "email"], limit=1,
                ignore_permissions=True,
            )
            return rows[0] if rows else None
        except Exception:
            return None

    if im and frappe.db.exists("IM Master", im):
        im_rec = _find_im_rec({"name": im})
    if not im_rec and im:
        im_rec = _find_im_rec({"full_name": im})
    if not im_rec and im:
        im_rec = _find_im_rec({"email": im})
    if not im_rec:
        im_rec = _find_im_rec({"user": session_user})
    if not im_rec and user_full_name:
        im_rec = _find_im_rec({"full_name": user_full_name})

    if im_rec:
        im_identifiers = list({
            v for v in [im_rec.name, im_rec.full_name, im_rec.email, im, user_full_name]
            if v
        })
        im_resolved = im_rec.name
    else:
        im_resolved = im or user_full_name or None
        im_identifiers = list({v for v in [im, user_full_name] if v})

    if not im_identifiers:
        return None, [], {}
    return im_resolved, im_identifiers, {"session_user": session_user, "user_full_name": user_full_name}


def im_action_counts(im_identifiers):
    """Counts for IM dashboard action strip (PM→IM→execution workflow)."""
    if not im_identifiers:
        return {"pending_plan_dispatches": 0, "qc_fail_needs_action": 0, "planned_ready_execution": 0, "pending_approvals": 0, "open_dummy_pos": 0}
    ph = ", ".join(["%s"] * len(im_identifiers))
    params = tuple(im_identifiers)
    pending = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS c FROM `tabPO Dispatch`
        WHERE im IN ({ph}) AND dispatch_status = 'Dispatched'
        """,
        params,
        as_dict=True,
    )[0].c
    qc_open = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS c FROM `tabDaily Execution` de
        INNER JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE pd.im IN ({ph}) AND de.qc_status = 'Fail'
        AND de.execution_status NOT IN ('Cancelled')
        """,
        params,
        as_dict=True,
    )[0].c
    planned_exec = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS c FROM `tabRollout Plan` rp
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE pd.im IN ({ph}) AND rp.plan_status IN ('Planned', 'Extended')
        """,
        params,
        as_dict=True,
    )[0].c
    # All pending approvals relevant to this IM:
    # - Team Allocation Requests awaiting this IM's response (Pending Source IM)
    # - Plan Cancel Requests for this IM's plans awaiting PM approval
    pending_team = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS c FROM `tabTeam Allocation Request`
        WHERE from_im IN ({ph}) AND request_status = 'Pending Source IM'
        """,
        params,
        as_dict=True,
    )[0].c
    pending_cancel = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS c FROM `tabRollout Plan` rp
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE pd.im IN ({ph}) AND rp.cancel_request_status = 'Pending PM Approval'
        """,
        params,
        as_dict=True,
    )[0].c
    pending_approvals = cint(pending_team) + cint(pending_cancel)
    # Open dummy POs for this IM
    open_dummies = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS c FROM `tabPO Dispatch`
        WHERE im IN ({ph}) AND IFNULL(is_dummy_po, 0) = 1
        """,
        params,
        as_dict=True,
    )[0].c
    return {
        "pending_plan_dispatches": cint(pending),
        "qc_fail_needs_action": cint(qc_open),
        "planned_ready_execution": cint(planned_exec),
        "pending_approvals": cint(pending_approvals),
        "open_dummy_pos": cint(open_dummies),
    }


# ─────────────────────────────────────────────────────────────────────────────
# Step 5 — Performance Scorecard Reports
# ─────────────────────────────────────────────────────────────────────────────

def _perf_date_range(from_date, to_date):
    from frappe.utils import today as _today, getdate
    fd = str(getdate(from_date)) if from_date else _today()
    td = str(getdate(to_date)) if to_date else fd
    return fd, td


@frappe.whitelist()
def get_im_performance_report(from_date=None, to_date=None, **kwargs):
    """IM Performance Scorecard — revenue, cost, profit, completion %, rating per IM.
    Target = SUM(pd.line_amount) for distinct POs that had plans in the period.
    Rating thresholds (IM-level, stricter): >=100% Excellent, >=85% Good, >=70% NI, else Idle.
    """
    fd, td = _perf_date_range(from_date, to_date)

    # Plans: assigned/completed lines per IM. Team count is NOT derived here —
    # rp.team is only the plan's lead team; a multi-team split (Rollout Plan
    # Team child rows) puts the other teams nowhere this query can see them,
    # which silently undercounted "Teams" on this report. See teams_by_im below.
    plan_rows = frappe.db.sql(
        """
        SELECT pd.im,
               COALESCE(imm.full_name, pd.im) AS im_name,
               COUNT(DISTINCT rp.name)         AS assigned_lines,
               SUM(CASE WHEN rp.plan_status = 'Completed' THEN 1 ELSE 0 END) AS completed_lines
        FROM `tabRollout Plan` rp
        JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabIM Master` imm ON imm.name = pd.im
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND pd.im IS NOT NULL AND pd.im != ''
          AND IFNULL(pd.is_internal_work, 0) = 0
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
        GROUP BY pd.im
        """,
        (fd, td), as_dict=True,
    )

    # Teams per IM — union of each plan's lead team (rp.team) with every team
    # in its Rollout Plan Team split, so a multi-team plan counts all of its
    # teams, not just the lead. Kept as a separate query (not joined into
    # plan_rows above) so the team fan-out can't double-count assigned/
    # completed lines.
    team_split_rows = frappe.db.sql(
        """
        SELECT pd.im, t.team
        FROM `tabRollout Plan` rp
        JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        JOIN (
            SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
            UNION
            SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
        ) t ON t.plan = rp.name
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND pd.im IS NOT NULL AND pd.im != ''
          AND IFNULL(pd.is_internal_work, 0) = 0
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
          AND t.team IS NOT NULL AND t.team != ''
        GROUP BY pd.im, t.team
        """,
        (fd, td), as_dict=True,
    )
    teams_by_im = {}
    for r in team_split_rows:
        teams_by_im.setdefault(r.im, set()).add(r.team)

    # Target = SUM of line_amount on distinct PO Dispatches that either had
    # plans in the period, OR were closed directly (Direct Close / Backend —
    # no Rollout Plan at all, so the first branch alone never sees them; an
    # IM who only ever direct-closes would show Target=0 forever otherwise).
    target_rows = frappe.db.sql(
        """
        SELECT pd.im, COALESCE(SUM(pd.line_amount), 0) AS target
        FROM (
            SELECT DISTINCT rp.po_dispatch AS po_dispatch
            FROM `tabRollout Plan` rp
            WHERE DATE(rp.plan_date) BETWEEN %s AND %s
              AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
            UNION
            SELECT DISTINCT wd.system_id AS po_dispatch
            FROM `tabWork Done` wd
            WHERE IFNULL(wd.execution, '') = ''
              AND DATE(wd.creation) BETWEEN %s AND %s
        ) plans
        JOIN `tabPO Dispatch` pd ON pd.name = plans.po_dispatch
        WHERE pd.im IS NOT NULL AND pd.im != ''
          AND IFNULL(pd.is_internal_work, 0) = 0
        GROUP BY pd.im
        """,
        (fd, td, fd, td), as_dict=True,
    )
    target_by_im = {r.im: flt(r.target) for r in target_rows}

    # Revenue per IM from Work Done. Two sources: normal rollout execution
    # (via Daily Execution -> Rollout Plan -> PO Dispatch, dated by when the
    # field work happened) and Direct Close / Backend (wd.execution is blank
    # for these — no Daily Execution ever exists — so wd.system_id -> pd
    # directly, dated by when the WD record itself was created, i.e. when
    # the IM did the direct close / marked the backend line done). Without
    # the second query, an IM who only ever direct-closes showed 0 revenue
    # here no matter how much they'd actually closed.
    rev_rows = frappe.db.sql(
        """
        SELECT pd.im, COALESCE(SUM(wd.revenue_sar), 0) AS revenue
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
          AND pd.im IS NOT NULL AND pd.im != ''
        GROUP BY pd.im
        """,
        (fd, td), as_dict=True,
    )
    rev_by_im = {r.im: flt(r.revenue) for r in rev_rows}

    rev_rows_direct = frappe.db.sql(
        """
        SELECT pd.im, COALESCE(SUM(wd.revenue_sar), 0) AS revenue
        FROM `tabWork Done` wd
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        WHERE IFNULL(wd.execution, '') = ''
          AND DATE(wd.creation) BETWEEN %s AND %s
          AND pd.im IS NOT NULL AND pd.im != ''
        GROUP BY pd.im
        """,
        (fd, td), as_dict=True,
    )
    for r in rev_rows_direct:
        rev_by_im[r.im] = rev_by_im.get(r.im, 0.0) + flt(r.revenue)

    # Direct Close / Backend lines, kept SEPARATE from the rollout-execution
    # Assigned/Completed rather than blended in — the client's whole reason
    # for the Contract Model gating earlier was visibility into how much of
    # an IM's throughput is real field execution vs. the Direct Close/Backend
    # shortcut, so folding them together would hide exactly that signal.
    # Same "no Rollout Plan at all" gap as target/revenue above (plan_rows
    # never sees these), counted as DISTINCT po_dispatch (not per WD row) so
    # a milestone-split line with 2 WD rows (MS1 + MS2) is still one line.
    # "Completed" requires dispatch_status = 'Completed', which
    # _direct_close_one only sets once BOTH milestones are closed — an
    # MS1-only close counts as touched but not yet completed.
    direct_source_rows = frappe.db.sql(
        """
        SELECT pd.im, wd.source,
               COUNT(DISTINCT pd.name) AS assigned_lines,
               COUNT(DISTINCT CASE WHEN pd.dispatch_status = 'Completed' THEN pd.name END) AS completed_lines
        FROM `tabWork Done` wd
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        WHERE IFNULL(wd.execution, '') = ''
          AND DATE(wd.creation) BETWEEN %s AND %s
          AND pd.im IS NOT NULL AND pd.im != ''
        GROUP BY pd.im, wd.source
        """,
        (fd, td), as_dict=True,
    )
    direct_by_im = {}
    backend_by_im = {}
    for r in direct_source_rows:
        target_map = direct_by_im if r.source == "Direct Close" else backend_by_im if r.source == "Backend" else None
        if target_map is not None:
            target_map[r.im] = r

    # Team costs per IM. Keyed on the SAME plan-based, multi-team-aware set
    # the Teams column counts (teams_by_im above), not on Work Done: an INET
    # team is monthly-salaried, so it costs its IM's P&L from the moment it
    # is assigned plans, whether or not Work Done has been generated for
    # them yet. Reading it off Work Done via Daily Execution — as this did —
    # left every IM whose teams had plans but no generated Work Done showing
    # revenue against SAR 0 cost, and skipped a split plan's non-executing
    # teams entirely.
    #
    # A team assigned under more than one IM in the period has its period
    # cost SPLIT between them in proportion to each IM's share of its plans,
    # rather than charged in full to each: the same salary cannot be spent
    # twice, and summing the column has to stay within real company cost.
    im_team_plan_rows = frappe.db.sql(
        """
        SELECT pd.im, t.team, COUNT(DISTINCT rp.name) AS plans
        FROM `tabRollout Plan` rp
        JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        JOIN (
            SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
            UNION
            SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
        ) t ON t.plan = rp.name
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
          AND pd.im IS NOT NULL AND pd.im != ''
          AND t.team IS NOT NULL AND t.team != ''
        GROUP BY pd.im, t.team
        """,
        (fd, td), as_dict=True,
    )
    # Payout owed per team on subcontracted work, for the SUB branch below —
    # a SUB team has no daily cost, so what it costs INET is the payout, and
    # that follows the revenue actually attributed to it rather than its
    # assignment count.
    sub_payout_rows = frappe.db.sql(
        """
        SELECT de.team,
               COALESCE(SUM(wd.revenue_sar * IFNULL(sm.sub_payout_pct, 0) / 100.0), 0) AS subcon_payout
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        LEFT JOIN `tabSubcontract Master` sm ON sm.name = pd.contract
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
          AND de.team IS NOT NULL AND de.team != ''
        GROUP BY de.team
        """,
        (fd, td), as_dict=True,
    )
    payout_by_team = {r.team: flt(r.subcon_payout) for r in sub_payout_rows}
    # Not status-filtered — pure cost-rate lookup; _team_cost_days handles a
    # Disbanded team's end_date cutoff.
    team_info_rows = frappe.db.sql(
        """
        SELECT name, COALESCE(daily_cost, 0) AS daily_cost, team_type, start_date, end_date
        FROM `tabINET Team`
        """,
        as_dict=True,
    )
    team_info = {r.name: r for r in team_info_rows}

    plans_by_team = {}
    for _tp in im_team_plan_rows:
        plans_by_team[_tp.team] = plans_by_team.get(_tp.team, 0) + cint(_tp.plans)

    cost_by_im = {}
    for tc in im_team_plan_rows:
        ti         = team_info.get(tc.team)
        team_type  = ((ti.team_type if ti else None) or "INET").upper()
        if team_type == "SUB":
            full_cost = payout_by_team.get(tc.team, 0.0)
        else:
            daily_cost = flt(ti.daily_cost if ti else 0)
            days       = _team_cost_days(ti.start_date if ti else None, ti.end_date if ti else None, fd, td)
            full_cost  = daily_cost * days
        team_plans = plans_by_team.get(tc.team, 0)
        share      = (cint(tc.plans) / team_plans) if team_plans > 0 else 1.0
        cost_by_im[tc.im] = cost_by_im.get(tc.im, 0.0) + full_cost * share

    # All IMs from master — so IMs with 0 activity still appear
    all_ims = frappe.db.sql(
        "SELECT name, COALESCE(full_name, name) AS im_name FROM `tabIM Master`",
        as_dict=True,
    )
    plan_by_im = {r.im: r for r in plan_rows}

    data = []
    total_assigned = 0
    total_completed = 0
    total_overall_assigned = 0
    total_overall_completed = 0
    total_target = 0.0
    total_revenue = 0.0
    for im_rec in all_ims:
        im_id     = im_rec.name
        r         = plan_by_im.get(im_id, frappe._dict(assigned_lines=0, completed_lines=0))
        dc        = direct_by_im.get(im_id, frappe._dict(assigned_lines=0, completed_lines=0))
        bk        = backend_by_im.get(im_id, frappe._dict(assigned_lines=0, completed_lines=0))
        assigned  = cint(r.assigned_lines)
        completed = cint(r.completed_lines)
        dc_assigned, dc_completed = cint(dc.assigned_lines), cint(dc.completed_lines)
        bk_assigned, bk_completed = cint(bk.assigned_lines), cint(bk.completed_lines)
        overall_assigned  = assigned + dc_assigned + bk_assigned
        overall_completed = completed + dc_completed + bk_completed
        target    = target_by_im.get(im_id, 0.0)
        revenue   = rev_by_im.get(im_id, 0.0)
        team_cost = round(cost_by_im.get(im_id, 0.0), 0)
        profit    = round(revenue - team_cost, 0)
        compl_pct = round(completed / assigned * 100, 1) if assigned > 0 else 0.0
        overall_compl_pct = round(overall_completed / overall_assigned * 100, 1) if overall_assigned > 0 else 0.0
        ach_pct   = round(revenue / target * 100, 1) if target > 0 else 0.0
        total_assigned += assigned
        total_completed += completed
        total_overall_assigned += overall_assigned
        total_overall_completed += overall_completed
        total_target += target
        total_revenue += revenue
        rating    = ("Excellent"        if ach_pct >= 100 else
                     "Good"             if ach_pct >= 85  else
                     "Need Improvement" if ach_pct >= 70  else "Idle")
        data.append({
            "im":                  im_rec.im_name,
            "teams":               len(teams_by_im.get(im_id, ())),
            "assigned_lines":      assigned,
            "completed_lines":     completed,
            "completion_pct":      compl_pct,
            "direct_backend_closed": (
                f"{dc_completed + bk_completed}/{dc_assigned + bk_assigned}"
                if (dc_assigned + bk_assigned) else "—"
            ),
            "overall_completion_pct": overall_compl_pct,
            "target":              round(target, 0),
            "revenue":             round(revenue, 0),
            "achievement_pct":     ach_pct,
            "team_cost":           team_cost,
            "profit":              profit,
            "rating":              rating,
        })
    data.sort(key=lambda x: x["revenue"], reverse=True)

    columns = [
        {"fieldname": "im",              "label": "IM",              "fieldtype": "Data"},
        {"fieldname": "teams",           "label": "Teams",           "fieldtype": "Int"},
        {"fieldname": "assigned_lines",  "label": "Assigned",        "fieldtype": "Int"},
        {"fieldname": "completed_lines", "label": "Completed",       "fieldtype": "Int"},
        {"fieldname": "completion_pct",  "label": "Completion %",    "fieldtype": "Percent"},
        {"fieldname": "direct_backend_closed", "label": "Direct/Backend Closed", "fieldtype": "Data"},
        {"fieldname": "overall_completion_pct", "label": "Overall Completion %", "fieldtype": "Percent"},
        {"fieldname": "target",          "label": "Target (SAR)",    "fieldtype": "Currency"},
        {"fieldname": "revenue",         "label": "Revenue (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "achievement_pct", "label": "Achievement %",   "fieldtype": "Percent"},
        {"fieldname": "team_cost",       "label": "Team Cost (SAR)", "fieldtype": "Currency"},
        {"fieldname": "profit",          "label": "Profit / Loss",   "fieldtype": "Currency"},
        {"fieldname": "rating",          "label": "Rating",          "fieldtype": "Data"},
    ]
    # Overall % columns = ratio of totals, never an average of the per-IM
    # percentages — IMs have very different assigned-line/target sizes, so
    # averaging would weight a 1-line IM the same as one with hundreds.
    totals = {
        "completion_pct": round(total_completed / total_assigned * 100, 1) if total_assigned > 0 else None,
        "overall_completion_pct": (
            round(total_overall_completed / total_overall_assigned * 100, 1)
            if total_overall_assigned > 0 else None
        ),
        "achievement_pct": round(total_revenue / total_target * 100, 1) if total_target > 0 else None,
    }
    return {"columns": columns, "data": data, "totals": totals}



def _project_meta_map():
    """project_code -> name / IM / domain, with the PO line's domain override
    winning over the project's default (same rule as everywhere else)."""
    rows = frappe.db.sql(
        """
        SELECT pcc.name AS project_code,
               IFNULL(pcc.project_name, pcc.name) AS project_name,
               IFNULL(pcc.implementation_manager, '') AS im,
               IFNULL((
                   SELECT COALESCE(NULLIF(pd2.project_domain, ''), pcc.project_domain)
                   FROM `tabPO Dispatch` pd2
                   WHERE pd2.project_code = pcc.name
                     AND IFNULL(pd2.project_domain, '') != ''
                   LIMIT 1
               ), IFNULL(pcc.project_domain, '')) AS project_domain
        FROM `tabProject Control Center` pcc
        """,
        as_dict=True,
    ) or []
    return {r.project_code: r for r in rows}


def _report_chart(rows, label_key, value_key, value_name, top=10):
    """The {labels, datasets} shape ReportChart renders — top N rows by value."""
    picked = [r for r in rows if flt(r.get(value_key))][:top]
    if not picked:
        return None
    return {
        "data": {
            "labels": [str(r.get(label_key) or "") for r in picked],
            "datasets": [{"name": value_name,
                          "values": [round(flt(r.get(value_key)), 2) for r in picked]}],
        },
        "type": "bar",
    }


@frappe.whitelist()
def get_project_profitability_report(from_date=None, to_date=None, **kwargs):
    """Project Profitability — the workbook's Project_Profitability sheet.

    Revenue delivery by project code, measured against the PO value:

      PO Value         = SUMIFS('PO Dump'!V, Y=code)  -> SUM(pd.line_amount)
      Revenue Achieved = line value of the lines that are DONE
      Remaining Value  = PO Value - Revenue Achieved
      Assigned Lines   = COUNTIFS('PO Dump'!Y=code, C<>"")
      Completed Lines  = count of those same done lines
      Delivery %       = Revenue Achieved / PO Value

    "Done" is the line's dispatch_status reaching Completed, Partially
    Submitted, Submitted, Partially Closed or Closed — a submitted, invoiced
    or closed line is work that has already been carried out, so its line
    value counts as achieved. Same status set the PM dashboard's Top Projects
    uses, so the two agree.

    Achieved is deliberately NOT taken from Work Done: only 53 of this
    database's 11,439 done lines carry a Work Done record (the rest were
    imported historically with their invoice data), so keying it there
    reported 0 achieved for projects with 1,557 lines closed. Nor is it taken
    from the PIC invoiced amounts, which measure the billed position rather
    than the work — Revenue Achieved and Completed Lines are now the value
    and the count of one single set of lines, which is why they move together.

    The sheet's "Profitability Index" column is literally `=I4` (a copy of
    Delivery %), so it is not repeated here.

    Separate from get_project_performance_report on purpose: this one measures
    against CONTRACTED value, that one against the ROLLOUT PLAN target. The
    two answer different questions and will not agree.

    Deliberately NOT date-filtered. PO value has no usable date basis
    (target_month is set on 95 of 17,449 lines), so filtering one side only
    made Delivery % compare an all-time denominator against a windowed
    numerator. The workbook has no date concept here either: this is a
    current-state report.
    """

    line_rows = frappe.db.sql(
        """
        SELECT pd.project_code AS project_code,
               COALESCE(SUM(pd.line_amount), 0) AS po_value,
               COUNT(*) AS assigned_lines,
               SUM(CASE WHEN pd.dispatch_status IN
                        ('Completed', 'Partially Submitted', 'Submitted',
                         'Partially Closed', 'Closed')
                        THEN 1 ELSE 0 END) AS completed_lines,
               COALESCE(SUM(CASE WHEN pd.dispatch_status IN
                        ('Completed', 'Partially Submitted', 'Submitted',
                         'Partially Closed', 'Closed')
                        THEN pd.line_amount ELSE 0 END), 0) AS achieved
        FROM `tabPO Dispatch` pd
        WHERE IFNULL(pd.project_code, '') != ''
          AND IFNULL(pd.is_internal_work, 0) != 1
          AND IFNULL(pd.dispatch_status, '') NOT LIKE '%%Cancel%%'
        GROUP BY pd.project_code
        """,
        as_dict=True,
    ) or []

    meta = _project_meta_map()

    data = []
    for lr in line_rows:
        code = lr.project_code
        m = meta.get(code) or {}
        po_value = flt(lr.po_value)
        achieved = flt(lr.achieved)
        data.append({
            "project_domain": m.get("project_domain") or "",
            "project_name": m.get("project_name") or code,
            "project_code": code,
            "po_value": round(po_value, 2),
            "achieved": round(achieved, 2),
            "remaining_value": round(po_value - achieved, 2),
            "assigned_lines": cint(lr.assigned_lines),
            "completed_lines": cint(lr.completed_lines),
            "delivery_pct": round(achieved / po_value * 100, 1) if po_value else 0.0,
        })
    data.sort(key=lambda r: r["po_value"], reverse=True)
    for i, r in enumerate(data, 1):
        r["sn"] = i

    columns = [
        {"fieldname": "sn",              "label": "#",                "fieldtype": "Int"},
        {"fieldname": "project_domain",  "label": "Project Domain",   "fieldtype": "Data"},
        {"fieldname": "project_name",    "label": "Project Name",     "fieldtype": "Data"},
        {"fieldname": "project_code",    "label": "Project Code",     "fieldtype": "Data"},
        {"fieldname": "po_value",        "label": "PO Value (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "achieved",        "label": "Revenue Achieved", "fieldtype": "Currency"},
        {"fieldname": "remaining_value", "label": "Remaining Value",  "fieldtype": "Currency"},
        {"fieldname": "assigned_lines",  "label": "Assigned Lines",   "fieldtype": "Int"},
        {"fieldname": "completed_lines", "label": "Completed Lines",  "fieldtype": "Int"},
        {"fieldname": "delivery_pct",    "label": "Delivery %",       "fieldtype": "Percent"},
    ]

    tot_po = sum(r["po_value"] for r in data)
    tot_ach = sum(r["achieved"] for r in data)
    totals = {
        "project_code": f"{len(data)} projects",
        "po_value": round(tot_po, 2),
        "achieved": round(tot_ach, 2),
        "remaining_value": round(tot_po - tot_ach, 2),
        "assigned_lines": sum(r["assigned_lines"] for r in data),
        "completed_lines": sum(r["completed_lines"] for r in data),
        # Ratio of the totals, never an average of the row percentages.
        "delivery_pct": round(tot_ach / tot_po * 100, 1) if tot_po else 0.0,
    }
    return {
        "columns": columns,
        "data": data,
        "totals": totals,
        "chart": _report_chart(data, "project_code", "achieved", "Revenue Achieved (SAR)"),
    }


@frappe.whitelist()
def get_project_performance_report(from_date=None, to_date=None, **kwargs):
    """Project Performance — the workbook's Project_Performance sheet.

    Project-wise performance against target:

      Known Target    = SUM(pd.line_amount) — what the lines are worth
      Achieved        = line value of the lines that are DONE
      Gap             = Known Target - Achieved
      Total Lines     = lines in scope (no plan needed)
      Completed Lines = count of the done lines
      Achievement %   = Achieved / Known Target
      Completion %    = Completed Lines / Total Lines
      Avg Rev / Line  = Achieved / Completed
      KPI Rating      = >=95% Excellent, >=80% Good, >0 Need Improvement,
                        else No Progress
      Rank            = by Achievement %

    Known Target is the line value, with no reference to rollout plans. The
    workbook read it from Rollout_Planning_V2, which held a row for every
    line; here plans exist for 94 of 15,995 lines, because 11,400 of the
    11,439 done lines are legacy — completed and often already invoiced with
    no plan ever created. Reading the target from plans gave 66 of 75
    projects a target of zero.

    A plan is not needed to know what a line was worth, and for a line that
    is already complete the plan is irrelevant. Consulting plans also
    over-counted: a re-visited line carries several plans, so summing their
    target_amount pushed the target above the line's own value (13,722,891
    against a book of 13,710,253).

    Achieved is the line value of done lines (dispatch_status reaching
    Completed / Partially Submitted / Submitted / Partially Closed / Closed)
    — a submitted, invoiced or closed line is work already carried out. Not
    Work Done revenue, which exists for only 53 of the 11,439 done lines.

    Current-state, not date-filtered: neither a line's value nor its status
    has a usable date basis here (target_month is set on 95 of 17,449 lines),
    and filtering one side only made every percentage collapse.
    """
    DONE_STATUSES = LINE_DONE_STATUSES
    _ph_done = ", ".join(["%s"] * len(DONE_STATUSES))

    # One row per project, straight off PO Dispatch. No Rollout Plan join at
    # all: the target is what the lines are worth and the achieved side is
    # their status, so a legacy line that was never planned is measured the
    # same as a planned one. `total_lines` is every line in scope — NOT a
    # count of planned lines, which is why it is not called that.
    rows = frappe.db.sql(
        f"""
        SELECT pd.project_code AS project_code,
               COALESCE(SUM(pd.line_amount), 0) AS known_target,
               COALESCE(SUM(CASE WHEN pd.dispatch_status IN ({_ph_done})
                                 THEN pd.line_amount ELSE 0 END), 0) AS achieved,
               COUNT(*) AS total_lines,
               SUM(CASE WHEN pd.dispatch_status IN ({_ph_done})
                        THEN 1 ELSE 0 END) AS completed_lines
        FROM `tabPO Dispatch` pd
        WHERE IFNULL(pd.project_code, '') != ''
          AND IFNULL(pd.is_internal_work, 0) != 1
          AND IFNULL(pd.dispatch_status, '') NOT LIKE '%%Cancel%%'
        GROUP BY pd.project_code
        """,
        tuple(DONE_STATUSES) * 2, as_dict=True,
    ) or []
    meta = _project_meta_map()

    data = []
    for r in rows:
        code = r.project_code
        m = meta.get(code) or {}
        target = flt(r.known_target)
        achieved = flt(r.achieved)
        total_lines = cint(r.total_lines)
        completed = cint(r.completed_lines)
        ach_pct = round(achieved / target * 100, 1) if target else 0.0
        if ach_pct >= 95:
            rating = "Excellent"
        elif ach_pct >= 80:
            rating = "Good"
        elif ach_pct > 0:
            rating = "Need Improvement"
        else:
            rating = "No Progress"
        data.append({
            "project_code": code,
            "project_name": m.get("project_name") or code,
            "im": m.get("im") or "",
            "known_target": round(target, 2),
            "achieved": round(achieved, 2),
            "gap": round(target - achieved, 2),
            "total_lines": total_lines,
            "completed_lines": completed,
            "achievement_pct": ach_pct,
            "completion_pct": round(completed / total_lines * 100, 1) if total_lines else 0.0,
            "avg_revenue_per_line": round(achieved / completed, 2) if completed else 0.0,
            "kpi_rating": rating,
        })

    # Ranked by Achievement %, as the sheet's RANK() does.
    data.sort(key=lambda r: r["achievement_pct"], reverse=True)
    for i, r in enumerate(data, 1):
        r["rank"] = i
        r["sn"] = i

    columns = [
        {"fieldname": "sn",                   "label": "#",                    "fieldtype": "Int"},
        {"fieldname": "project_code",         "label": "Project Code",         "fieldtype": "Data"},
        {"fieldname": "project_name",         "label": "Project Name",         "fieldtype": "Data"},
        {"fieldname": "im",                   "label": "IM",                   "fieldtype": "Data"},
        {"fieldname": "known_target",         "label": "Known Target (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "achieved",             "label": "Achieved (SAR)",       "fieldtype": "Currency"},
        {"fieldname": "gap",                  "label": "Gap (SAR)",            "fieldtype": "Currency"},
        {"fieldname": "total_lines",        "label": "Total Lines",          "fieldtype": "Int"},
        {"fieldname": "completed_lines",      "label": "Completed Lines",      "fieldtype": "Int"},
        {"fieldname": "achievement_pct",      "label": "Achievement %",        "fieldtype": "Percent"},
        {"fieldname": "completion_pct",       "label": "Completion %",         "fieldtype": "Percent"},
        {"fieldname": "avg_revenue_per_line", "label": "Avg Rev / Line (SAR)", "fieldtype": "Currency"},
        {"fieldname": "kpi_rating",           "label": "KPI Rating",           "fieldtype": "Data"},
    ]

    tot_t = sum(r["known_target"] for r in data)
    tot_a = sum(r["achieved"] for r in data)
    tot_p = sum(r["total_lines"] for r in data)
    tot_c = sum(r["completed_lines"] for r in data)
    totals = {
        "project_code": f"{len(data)} projects",
        "known_target": round(tot_t, 2),
        "achieved": round(tot_a, 2),
        "gap": round(tot_t - tot_a, 2),
        "total_lines": tot_p,
        "completed_lines": tot_c,
        "achievement_pct": round(tot_a / tot_t * 100, 1) if tot_t else 0.0,
        "completion_pct": round(tot_c / tot_p * 100, 1) if tot_p else 0.0,
        "avg_revenue_per_line": round(tot_a / tot_c, 2) if tot_c else 0.0,
    }

    return {
        "columns": columns,
        "data": data,
        "totals": totals,
        "chart": _report_chart(data, "project_code", "achieved", "Achieved (SAR)"),
    }


@frappe.whitelist()
def get_rollout_burn_down_report(from_date=None, to_date=None, **kwargs):
    """Rollout Delivery Burn-Down — the workbook's Rollout_Progress sheet.

    Company-wide PO-line backlog, burning down week by week against a
    straight-line pace target (the same even-pace assumption behind Command
    Dashboard's Target card).

    Total Lines is every in-scope PO Dispatch line — the same "in scope"
    definition get_project_performance_report uses (has a project, not
    internal work, not cancelled). A line's closed date, needed to place it
    in a week, barely exists in this data (only 53 of 11,439 done lines have
    a Work Done record — see that function's docstring for the full legacy
    picture). The best available signal, in order: the latest Daily
    Execution against the line, then the earliest Work Done record, then the
    PO Dispatch row's own last-modified date as a last resort — which for a
    line bulk-imported already closed means "the system learned this was
    closed", not the day the work actually happened. Checked live: 10,625 of
    11,439 done lines fall back to that last resort, almost all landing on
    the same handful of migration dates. A chart of that would show one
    enormous spike on the import date and nothing else, which is true but
    useless.

    So the target and the "actual" progress line are both measured against
    the OPEN BACKLOG AT THE START OF THE SELECTED WINDOW, not the whole
    15,995-line universe — closing the backlog that already existed before
    the window opened isn't this window's job. Target Progress % is how much
    of that backlog *should* be gone by now at an even daily pace to period
    end; Actual Progress % is how much of it actually is. Comparing either
    one against the full universe instead (as the workbook does, because its
    own tracker had no pre-existing backlog to net out) made the line sit
    flat near 71% every week regardless of real closing activity that week —
    checked, and dropped for exactly that reason.

    Closed Cumulative / Remaining / Target Remaining are snapshots as of a
    week's end — summing them across weeks in a table footer would be
    meaningless (double- and triple-counting the same still-open lines), so
    those columns carry no per-column total; the KPI cards show the period's
    start and end snapshots instead. New Closures and Re-Scheduled are
    deltas (an event dated inside that week specifically) and sum correctly,
    so they do carry one.

    Default window: the last 8 weeks to today, not "this calendar month" —
    the workbook's own choice, but with 10,625 of 11,439 closures dated by
    a handful of migration days rather than real activity, a single month
    is as likely to be empty as to be the one migration hit; 8 weeks gives
    enough width to show real recent movement either way. Any request
    narrower than 4 weeks — including the Reports page's own date picker,
    which defaults to month-to-date for every report that uses it — is
    widened backward to that same 8-week floor, ending at whatever to_date
    was asked for; a deliberately wide custom range is honoured as given.
    """
    DONE_STATUSES = LINE_DONE_STATUSES
    _ph_done = ", ".join(["%s"] * len(DONE_STATUSES))
    scope_where = """
        IFNULL(pd.project_code, '') != ''
        AND IFNULL(pd.is_internal_work, 0) != 1
        AND IFNULL(pd.dispatch_status, '') NOT LIKE '%%Cancel%%'
    """

    # The Reports page's own "dateonly" picker defaults to month-to-date for
    # every report that uses it, which for this one would mean a 1-4 day
    # window on the 1st of a month — nothing for a burn-down to show. A
    # request narrower than 4 weeks is widened backward to the standard
    # 8-week floor, ending at whatever to_date was actually asked for; a
    # deliberately wide custom range (e.g. a full quarter) is honoured as-is.
    t = getdate(nowdate())
    if from_date or to_date:
        td = getdate(to_date) if to_date else t
        fd = getdate(from_date) if from_date else add_days(td, -55)
        if td < fd:
            fd, td = td, fd
        if (td - fd).days + 1 < 28:
            fd = add_days(td, -55)
    else:
        fd, td = add_days(t, -55), t
    period_len = (td - fd).days + 1

    per_line = frappe.db.sql(
        f"""
        SELECT pd.name AS pdname,
               (pd.dispatch_status IN ({_ph_done})) AS is_done,
               DATE(COALESCE(ex.last_exec_date, wdd.wd_date, pd.modified)) AS closed_date
        FROM `tabPO Dispatch` pd
        LEFT JOIN (
            SELECT rp.po_dispatch AS pdname, MAX(de.execution_date) AS last_exec_date
            FROM `tabDaily Execution` de
            JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
            GROUP BY rp.po_dispatch
        ) ex ON ex.pdname = pd.name
        LEFT JOIN (
            SELECT wd.system_id AS pdname, MIN(wd.creation) AS wd_date
            FROM `tabWork Done` wd
            GROUP BY wd.system_id
        ) wdd ON wdd.pdname = pd.name
        WHERE {scope_where}
        """,
        tuple(DONE_STATUSES), as_dict=True,
    ) or []

    total_lines = len(per_line)
    closed_dates = [getdate(r.closed_date) for r in per_line if r.is_done and r.closed_date]

    revisit_rows = frappe.db.sql(
        f"""
        SELECT DATE(de.execution_date) AS d, COUNT(*) AS c
        FROM `tabDaily Execution` de
        JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE de.revisit_flag = 1
          AND de.execution_date IS NOT NULL
          AND {scope_where}
        GROUP BY DATE(de.execution_date)
        """,
        as_dict=True,
    ) or []
    revisit_by_date = {getdate(r.d): cint(r.c) for r in revisit_rows}

    baseline_closed = sum(1 for d in closed_dates if d < fd)
    open_backlog_at_start = max(total_lines - baseline_closed, 0)

    buckets = []
    cursor = fd
    idx = 1
    while cursor <= td:
        wk_end = min(add_days(cursor, 6), td)
        buckets.append((idx, cursor, wk_end))
        cursor = add_days(wk_end, 1)
        idx += 1

    data = []
    for idx, wstart, wend in buckets:
        cum = sum(1 for d in closed_dates if d <= wend)
        newc = sum(1 for d in closed_dates if wstart <= d <= wend)
        reschedules = sum(c for d, c in revisit_by_date.items() if wstart <= d <= wend)
        days_elapsed = (wend - fd).days + 1
        target_pct = round(min(days_elapsed / period_len, 1.0) * 100, 1) if period_len else 0.0
        actual_pct = (round((cum - baseline_closed) / open_backlog_at_start * 100, 1)
                      if open_backlog_at_start else 0.0)
        data.append({
            "sn":               idx,
            "week":             f"W-{idx}",
            "week_start":       str(wstart),
            "week_end":         str(wend),
            "total_lines":      total_lines,
            "closed_cumulative": cum,
            "new_closures":     newc,
            "remaining_lines":  total_lines - cum,
            "target_remaining": round(max(open_backlog_at_start * (1 - target_pct / 100), 0)),
            "actual_pct":       actual_pct,
            "target_pct":       target_pct,
            "reschedules":      reschedules,
        })

    columns = [
        {"fieldname": "sn",                "label": "#",                     "fieldtype": "Int"},
        {"fieldname": "week",              "label": "Week",                  "fieldtype": "Data"},
        {"fieldname": "week_start",        "label": "Week Start",            "fieldtype": "Date"},
        {"fieldname": "week_end",          "label": "Week End",              "fieldtype": "Date"},
        {"fieldname": "total_lines",       "label": "Total PO Lines",        "fieldtype": "Int",     "no_total": True},
        {"fieldname": "closed_cumulative", "label": "Closed (Cumulative)",   "fieldtype": "Int",     "no_total": True},
        {"fieldname": "new_closures",      "label": "New Closures",          "fieldtype": "Int"},
        {"fieldname": "remaining_lines",   "label": "Remaining Lines",       "fieldtype": "Int",     "no_total": True},
        {"fieldname": "target_remaining",  "label": "Target Remaining",      "fieldtype": "Int",     "no_total": True},
        {"fieldname": "actual_pct",        "label": "Actual Progress %",     "fieldtype": "Percent"},
        {"fieldname": "target_pct",        "label": "Target Progress %",     "fieldtype": "Percent"},
        {"fieldname": "reschedules",       "label": "Re-Scheduled",          "fieldtype": "Int"},
    ]

    last = data[-1] if data else {}
    totals = {
        "total_lines":       total_lines,
        "closed_cumulative": last.get("closed_cumulative", baseline_closed),
        "new_closures":      sum(r["new_closures"] for r in data),
        "remaining_lines":   last.get("remaining_lines", total_lines - baseline_closed),
        "target_remaining":  last.get("target_remaining", open_backlog_at_start),
        "actual_pct":        last.get("actual_pct", 0.0),
        "target_pct":        last.get("target_pct", 0.0),
        "reschedules":       sum(r["reschedules"] for r in data),
    }

    return {
        "columns": columns,
        "data": data,
        "totals": totals,
        "chart": _report_chart(data, "week", "actual_pct", "Actual Progress %", top=len(data)),
        "open_backlog_at_start": open_backlog_at_start,
        "from_date": str(fd),
        "to_date": str(td),
    }


@frappe.whitelist()
def get_top_teams_report(from_date=None, to_date=None, **kwargs):
    """Top Teams — ranked by revenue.
    Team Cost:
      INET  → daily_cost × days (days = the period clipped to the team's own
              start_date/end_date, capped at 30 - Excel standard: month = 30 days)
      SUB   → revenue × (1 - inet_margin_pct/100)  i.e. revenue × subcon_rate
    Utilization % = distinct days worked / period days × 100
    """
    fd, td = _perf_date_range(from_date, to_date)
    fd_date = getdate(fd)
    td_date = getdate(td)
    period_days = (td_date - fd_date).days + 1

    # Realized value per plan, attributed to the team(s) on that plan.
    #
    # Revenue used to come from Work Done alone, joined via Daily Execution on
    # de.team. That contradicted the Assigned/Completed columns sitting beside
    # it in two ways, and is why the report showed teams with completed lines
    # against SAR 0 revenue:
    #   - it required a Work Done record to exist, and on this data most
    #     completed work has none — legacy lines were imported already done,
    #     carrying their PIC invoice data with no plan or execution behind
    #     them (53 of 11,439 done lines have a Work Done row);
    #   - it credited only the executing team, while plan_rows below credits
    #     every team on a split plan, so a split plan's other teams took the
    #     completion but never any of the money.
    # A plan's realized value is now its Work Done revenue where that exists,
    # and the line's own value once the plan is Completed otherwise — the same
    # "a submitted, invoiced or closed line is work already carried out" rule
    # the project reports settled on. It is then split across the plan's teams
    # by Rollout Plan Team.assigned_amount, which exists for that purpose.
    plan_value_rows = frappe.db.sql(
        """
        SELECT rp.name AS plan, rp.plan_status,
               COALESCE(pd.line_amount, 0) AS line_amount,
               IFNULL(sm.sub_payout_pct, 0) AS payout_pct,
               (SELECT COALESCE(SUM(wd.revenue_sar), 0)
                  FROM `tabWork Done` wd
                  JOIN `tabDaily Execution` de ON de.name = wd.execution
                 WHERE de.rollout_plan = rp.name) AS wd_revenue
        FROM `tabRollout Plan` rp
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabSubcontract Master` sm ON sm.name = pd.contract
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
        """,
        (fd, td), as_dict=True,
    )
    # The split child table where a plan has one (it carries the prorated
    # assigned_amount), else the plan's own lead team.
    split_rows = frappe.db.sql(
        """
        SELECT rpt.parent AS plan, rpt.team,
               COALESCE(rpt.assigned_amount, 0) AS assigned_amount
        FROM `tabRollout Plan Team` rpt
        JOIN `tabRollout Plan` rp ON rp.name = rpt.parent
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
          AND rpt.team IS NOT NULL AND rpt.team != ''
        """,
        (fd, td), as_dict=True,
    )
    lead_rows = frappe.db.sql(
        """
        SELECT rp.name AS plan, rp.team
        FROM `tabRollout Plan` rp
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
          AND rp.team IS NOT NULL AND rp.team != ''
        """,
        (fd, td), as_dict=True,
    )
    splits_by_plan = {}
    for _s in split_rows:
        splits_by_plan.setdefault(_s.plan, []).append(_s)
    lead_by_plan = {r.plan: r.team for r in lead_rows}

    rev_by_team = {}

    def _tt_bucket(team):
        return rev_by_team.setdefault(
            team, frappe._dict(revenue=0.0, subcon_payout=0.0, days_worked=0)
        )

    for _pv in plan_value_rows:
        _realized = flt(_pv.wd_revenue)
        if not _realized and (_pv.plan_status or "") == "Completed":
            _realized = flt(_pv.line_amount)
        if not _realized:
            continue
        _rate = flt(_pv.payout_pct) / 100.0
        _members = splits_by_plan.get(_pv.plan) or []
        if _members:
            _total_share = sum(flt(m.assigned_amount) for m in _members)
            for _m in _members:
                # Prorate by assigned_amount, falling back to an even split
                # when the child rows carry no amounts at all.
                _frac = (
                    flt(_m.assigned_amount) / _total_share if _total_share > 0
                    else 1.0 / len(_members)
                )
                _b = _tt_bucket(_m.team)
                _b.revenue       += _realized * _frac
                _b.subcon_payout += _realized * _frac * _rate
        else:
            _lead = lead_by_plan.get(_pv.plan)
            if not _lead:
                continue
            _b = _tt_bucket(_lead)
            _b.revenue       += _realized
            _b.subcon_payout += _realized * _rate

    # Days worked: execution dates where they exist, plus the plan dates of
    # completed plans that never got an execution record — otherwise
    # Utilization % reads 0% for a team whose completions are all legacy,
    # the same gap the revenue attribution above closes.
    day_rows = frappe.db.sql(
        """
        SELECT team, COUNT(DISTINCT d) AS days_worked FROM (
            SELECT de.team AS team, DATE(de.execution_date) AS d
            FROM `tabDaily Execution` de
            WHERE DATE(de.execution_date) BETWEEN %s AND %s
              AND de.team IS NOT NULL AND de.team != ''
            UNION
            SELECT t.team AS team, DATE(rp.plan_date) AS d
            FROM `tabRollout Plan` rp
            JOIN (
                SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
                UNION
                SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
            ) t ON t.plan = rp.name
            WHERE DATE(rp.plan_date) BETWEEN %s AND %s
              AND rp.plan_status = 'Completed'
              AND t.team IS NOT NULL AND t.team != ''
        ) x GROUP BY team
        """,
        (fd, td, fd, td), as_dict=True,
    )
    for _d in day_rows:
        _tt_bucket(_d.team).days_worked = cint(_d.days_worked)

    # Plans: assigned lines + completed lines per team. Joined through the
    # union of rp.team (lead) and every Rollout Plan Team split row, so a
    # multi-team plan credits ALL of its teams, not just the lead — a plan
    # split Team A + Team B previously gave Team B's row a silent 0 here.
    plan_rows = frappe.db.sql(
        """
        SELECT t.team,
               COUNT(DISTINCT rp.name) AS assigned_lines,
               SUM(CASE WHEN rp.plan_status = 'Completed' THEN 1 ELSE 0 END) AS completed_lines
        FROM `tabRollout Plan` rp
        JOIN (
            SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
            UNION
            SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
        ) t ON t.plan = rp.name
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND t.team IS NOT NULL AND t.team != ''
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
        GROUP BY t.team
        """,
        (fd, td), as_dict=True,
    )
    plan_by_team = {r.team: r for r in plan_rows}

    # Most frequent IM per team. Plan-based (Rollout Plan -> PO Dispatch.im)
    # is the primary source — it has a row as soon as a plan is assigned,
    # not only once Work Done/revenue exists, so a team whose plans in this
    # window haven't been executed yet still shows its IM instead of "—".
    # Revenue-based Work Done is kept as a fallback for the rare team that
    # has neither (legacy data). Both go through the same multi-team union
    # as plan_rows above, so a split plan's IM is counted for every team
    # it's assigned to, not just the lead.
    im_plan_rows = frappe.db.sql(
        """
        SELECT t.team, pd.im, COUNT(*) AS cnt
        FROM `tabRollout Plan` rp
        JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        JOIN (
            SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
            UNION
            SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
        ) t ON t.plan = rp.name
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND t.team IS NOT NULL AND t.team != ''
          AND pd.im IS NOT NULL AND pd.im != ''
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
        GROUP BY t.team, pd.im
        ORDER BY t.team, cnt DESC
        """,
        (fd, td), as_dict=True,
    )
    im_by_team = {}
    for row in im_plan_rows:
        if row.team not in im_by_team:
            im_by_team[row.team] = row.im

    im_rows = frappe.db.sql(
        """
        SELECT de.team, pd.im, COUNT(*) AS cnt
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
          AND de.team IS NOT NULL AND de.team != ''
          AND pd.im IS NOT NULL AND pd.im != ''
        GROUP BY de.team, pd.im
        ORDER BY de.team, cnt DESC
        """,
        (fd, td), as_dict=True,
    )
    for row in im_rows:
        if row.team not in im_by_team:
            im_by_team[row.team] = row.im

    # Team master: daily_cost + team_type (INET vs SUB) + team_name
    team_info_rows = frappe.db.sql(
        """
        SELECT name, team_name, COALESCE(daily_cost, 0) AS daily_cost, team_type,
               start_date, end_date, status
        FROM `tabINET Team`
        WHERE IFNULL(team_category, '') != 'Backend Team'
        """,
        as_dict=True,
    )
    team_info = {r.name: r for r in team_info_rows}

    data = []
    # Every non-Disbanded team appears even at 0 revenue (Active/Inactive/On
    # Vacation all still cost the company, so an idle one is worth showing) —
    # PLUS any Disbanded team that has real revenue in this period (its cost
    # up to its end_date still needs to surface; once no period has revenue
    # for it, it naturally stops appearing rather than cluttering the report
    # forever as a dead 0-revenue row). Tested on revenue, not on mere
    # presence in rev_by_team: that map now also carries teams whose only
    # entry is a days_worked count, which would otherwise resurrect a
    # Disbanded team as a permanent zero row.
    report_teams = [
        name for name, ti in team_info.items()
        if (ti.status or "Active") != "Disbanded"
        or flt((rev_by_team.get(name) or {}).get("revenue")) > 0
    ]
    total_assigned = 0
    total_completed = 0
    total_days_worked = 0
    for team in report_teams:
        ti = team_info[team]
        r           = rev_by_team.get(team, frappe._dict(revenue=0, subcon_payout=0, days_worked=0))
        p           = plan_by_team.get(team, frappe._dict(assigned_lines=0, completed_lines=0))
        assigned    = cint(p.assigned_lines)
        completed   = cint(p.completed_lines)
        revenue     = flt(r.revenue)
        days_worked = cint(r.days_worked)
        total_assigned += assigned
        total_completed += completed
        total_days_worked += days_worked

        team_type = ((ti.team_type if ti else None) or "INET").upper()

        if team_type == "SUB":
            # No daily cost on a SUB team; its cost is the payout owed.
            team_cost   = round(flt(r.subcon_payout), 0)
        else:
            daily_cost = flt(ti.daily_cost if ti else 0)
            cost_days  = _team_cost_days(ti.start_date if ti else None, ti.end_date if ti else None, fd, td)
            team_cost  = round(daily_cost * cost_days, 0)

        profit          = round(revenue - team_cost, 0)
        utilization_pct = round(days_worked / period_days * 100, 1) if period_days > 0 else 0.0
        compl_pct       = round(completed / assigned * 100, 1) if assigned > 0 else 0.0

        data.append({
            "team_name":       ti.team_name or team,
            "im":              im_by_team.get(team, ""),
            "assigned_lines":  assigned,
            "completed_lines": completed,
            "completion_pct":  compl_pct,
            "revenue":         round(revenue, 0),
            "team_cost":       team_cost,
            "profit":          profit,
            "utilization_pct": utilization_pct,
        })

    data.sort(key=lambda x: x["revenue"], reverse=True)
    for i, row in enumerate(data, 1):
        row["sn"] = i

    columns = [
        {"fieldname": "sn",              "label": "#",               "fieldtype": "Int"},
        {"fieldname": "team_name",       "label": "Team",            "fieldtype": "Data"},
        {"fieldname": "im",              "label": "IM",              "fieldtype": "Data"},
        {"fieldname": "assigned_lines",  "label": "Assigned",        "fieldtype": "Int"},
        {"fieldname": "completed_lines", "label": "Completed",       "fieldtype": "Int"},
        {"fieldname": "completion_pct",  "label": "Completion %",    "fieldtype": "Percent"},
        {"fieldname": "revenue",         "label": "Revenue (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "team_cost",       "label": "Team Cost (SAR)", "fieldtype": "Currency"},
        {"fieldname": "profit",          "label": "Profit / Loss",   "fieldtype": "Currency"},
        {"fieldname": "utilization_pct", "label": "Utilization %",   "fieldtype": "Percent"},
    ]
    # Overall Completion % = SUM(completed)/SUM(assigned), never an average of
    # the per-row percentages — teams have very different assigned counts, so
    # averaging would weight a 1-line team the same as a 50-line one.
    # Overall Utilization % IS just the plain average here, but only because
    # every row shares the same denominator (period_days) — equivalent to
    # SUM(days_worked)/(period_days * team_count).
    totals = {
        "completion_pct": round(total_completed / total_assigned * 100, 1) if total_assigned > 0 else None,
        "utilization_pct": (
            round(total_days_worked / (period_days * len(report_teams)) * 100, 1)
            if report_teams and period_days > 0 else None
        ),
    }
    return {"columns": columns, "data": data, "totals": totals}


@frappe.whitelist()
def get_team_utilization_pva(from_date=None, to_date=None, **kwargs):
    """Team Utilization PVA — Planned vs Actual per team per day."""
    import json as _json
    fd, td = _perf_date_range(from_date, to_date)

    raw_team = kwargs.get("team") or []
    if isinstance(raw_team, str):
        try:
            raw_team = _json.loads(raw_team)
        except Exception:
            raw_team = [raw_team] if raw_team else []

    team_cond   = ""
    team_params = []
    if raw_team:
        ph = ", ".join(["%s"] * len(raw_team))
        team_cond   = f" AND t.team IN ({ph})"
        team_params = list(raw_team)

    # Joined through Rollout Plan Team so a multi-team split plan credits
    # EVERY team it's split across, not just the lead (rp.team). Target uses
    # each team's own assigned_amount (already prorated by assigned_qty in
    # _sync_plan_teams) rather than the plan's full target_amount, or a
    # split plan would inflate the sum of all teams' targets past the plan's
    # real value. Plans that predate the multi-team feature (no Rollout Plan
    # Team rows at all) fall back to the plan's own team + full target.
    plan_rows = frappe.db.sql(
        f"""
        SELECT DATE(rp.plan_date) AS plan_date,
               t.team,
               COUNT(DISTINCT rp.name) AS planned_lines,
               SUM(CASE WHEN rp.plan_status = 'Completed' THEN 1 ELSE 0 END) AS completed_lines,
               COALESCE(SUM(t.amount), 0) AS target
        FROM `tabRollout Plan` rp
        JOIN (
            SELECT rpt.parent AS plan, rpt.team AS team, rpt.assigned_amount AS amount
            FROM `tabRollout Plan Team` rpt
            UNION ALL
            SELECT rp2.name AS plan, rp2.team AS team, rp2.target_amount AS amount
            FROM `tabRollout Plan` rp2
            WHERE NOT EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt2 WHERE rpt2.parent = rp2.name)
        ) t ON t.plan = rp.name
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND t.team IS NOT NULL AND t.team != ''
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
          {team_cond}
        GROUP BY DATE(rp.plan_date), t.team
        ORDER BY plan_date, t.team
        """,
        (fd, td, *team_params), as_dict=True,
    )

    team_cond_de = team_cond.replace("rp.team", "de.team") if team_cond else ""
    rev_rows = frappe.db.sql(
        f"""
        SELECT DATE(de.execution_date) AS exec_date, de.team,
               COALESCE(SUM(wd.revenue_sar), 0) AS revenue
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
          AND de.team IS NOT NULL
          {team_cond_de}
        GROUP BY DATE(de.execution_date), de.team
        """,
        (fd, td, *team_params), as_dict=True,
    )
    rev_map    = {(str(r.exec_date), r.team): flt(r.revenue) for r in rev_rows}
    team_names = {}

    data = []
    total_planned = 0
    total_completed = 0
    total_target = 0.0
    total_revenue = 0.0
    for r in plan_rows:
        team = r.team
        if team not in team_names:
            team_names[team] = frappe.db.get_value("INET Team", team, "team_name") or team
        planned   = cint(r.planned_lines)
        completed = cint(r.completed_lines)
        target    = flt(r.target)
        revenue   = rev_map.get((str(r.plan_date), team), 0.0)
        compl_pct = round(completed / planned * 100, 1) if planned > 0 else 0.0
        ach_pct   = round(revenue / target * 100, 1) if target > 0 else 0.0
        total_planned += planned
        total_completed += completed
        total_target += target
        total_revenue += revenue
        data.append({
            "plan_date":       str(r.plan_date),
            "team_name":       team_names[team],
            "planned_lines":   planned,
            "completed_lines": completed,
            "completion_pct":  compl_pct,
            "target":          round(target, 0),
            "revenue":         round(revenue, 0),
            "achievement_pct": ach_pct,
        })

    columns = [
        {"fieldname": "plan_date",       "label": "Date",           "fieldtype": "Date"},
        {"fieldname": "team_name",       "label": "Team",           "fieldtype": "Data"},
        {"fieldname": "planned_lines",   "label": "Planned",        "fieldtype": "Int"},
        {"fieldname": "completed_lines", "label": "Completed",      "fieldtype": "Int"},
        {"fieldname": "completion_pct",  "label": "Completion %",   "fieldtype": "Percent"},
        {"fieldname": "target",          "label": "Target (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "revenue",         "label": "Revenue (SAR)",  "fieldtype": "Currency"},
        {"fieldname": "achievement_pct", "label": "Achievement %",  "fieldtype": "Percent"},
    ]
    totals = {
        "completion_pct": round(total_completed / total_planned * 100, 1) if total_planned > 0 else None,
        "achievement_pct": round(total_revenue / total_target * 100, 1) if total_target > 0 else None,
    }
    return {"columns": columns, "data": data, "totals": totals}



# The dispatch pipeline in the order work actually moves through it, with the
# stage each status belongs to. Sorting these by size instead would scramble
# the flow the report exists to show — the same reason the PIC status tables
# are ordered by their workflow rather than by row count.
#
# The stage split follows the app's own vocabulary: everything from Completed
# onward is DONE_STATUSES elsewhere in this module (work carried out), and
# the three part-way statuses between it and Closed are the PIC's invoicing
# ladder, not rollout states.
_DISPATCH_STAGE_FLOW = (
    ("Pending",             "Not Started"),
    ("Dispatched",          "In Rollout"),
    ("Planned",             "In Rollout"),
    ("Backend Assigned",    "In Rollout"),
    ("Completed",           "Work Done"),
    ("Partially Submitted", "Invoicing"),
    ("Submitted",           "Invoicing"),
    ("Partially Closed",    "Invoicing"),
    ("Closed",              "Closed"),
    ("Cancelled",           "Cancelled"),
)


@frappe.whitelist()
def get_po_dispatch_status_report(from_date=None, to_date=None, **kwargs):
    """PO Dispatch Status — how the order book sits across the dispatch pipeline.

    A SNAPSHOT of where every line stands right now, so it is deliberately
    not date-filtered, the same call the two project reports make. There is
    no usable date basis for a line's current status: target_month is set on
    95 of 17,449 lines, and scoping by PO publish date would answer a
    different question ("lines published this month") while the Reports page's
    month-to-date default would leave the report all but empty.

    Internal work is excluded, matching every other line-value report here.

    Every status in the pipeline gets a row even at zero, so a stage that has
    emptied out reads as an explicit 0 rather than vanishing from the table.
    """
    rows = frappe.db.sql(
        """
        SELECT IFNULL(NULLIF(dispatch_status, ''), 'Pending') AS status,
               COUNT(*) AS lines_count,
               COALESCE(SUM(line_amount), 0) AS value
        FROM `tabPO Dispatch`
        WHERE IFNULL(is_internal_work, 0) = 0
        GROUP BY IFNULL(NULLIF(dispatch_status, ''), 'Pending')
        """,
        as_dict=True,
    )
    by_status = {r.status: r for r in rows}

    total_lines = sum(cint(r.lines_count) for r in rows)
    total_value = sum(flt(r.value) for r in rows)

    data = []
    for status, stage in _DISPATCH_STAGE_FLOW:
        r = by_status.get(status)
        cnt = cint(r.lines_count) if r else 0
        val = flt(r.value) if r else 0.0
        data.append({
            "stage":       stage,
            "status":      status,
            "lines_count": cnt,
            "lines_pct":   round(cnt / total_lines * 100, 1) if total_lines else 0.0,
            "value":       round(val, 2),
            "value_pct":   round(val / total_value * 100, 1) if total_value else 0.0,
            "avg_value":   round(val / cnt, 2) if cnt else 0.0,
        })
    # Any status not in the flow above (a value added to the Select later, or
    # dirty legacy data) still has to appear, or the table would silently
    # under-report the book and its own percentages would not reach 100.
    for extra in sorted(set(by_status) - {s for s, _ in _DISPATCH_STAGE_FLOW}):
        r = by_status[extra]
        cnt, val = cint(r.lines_count), flt(r.value)
        data.append({
            "stage":       "Other",
            "status":      extra,
            "lines_count": cnt,
            "lines_pct":   round(cnt / total_lines * 100, 1) if total_lines else 0.0,
            "value":       round(val, 2),
            "value_pct":   round(val / total_value * 100, 1) if total_value else 0.0,
            "avg_value":   round(val / cnt, 2) if cnt else 0.0,
        })
    for i, row in enumerate(data, 1):
        row["sn"] = i

    columns = [
        {"fieldname": "sn",          "label": "#",            "fieldtype": "Int"},
        {"fieldname": "stage",       "label": "Stage",        "fieldtype": "Data"},
        {"fieldname": "status",      "label": "Status",       "fieldtype": "Data"},
        {"fieldname": "lines_count", "label": "Lines",        "fieldtype": "Int"},
        {"fieldname": "lines_pct",   "label": "Lines %",      "fieldtype": "Percent"},
        {"fieldname": "value",       "label": "Value (SAR)",  "fieldtype": "Currency"},
        {"fieldname": "value_pct",   "label": "Value %",      "fieldtype": "Percent"},
        {"fieldname": "avg_value",   "label": "Avg / Line",   "fieldtype": "Currency"},
    ]
    # The two percent columns total to 100 by construction, not by summing the
    # rows' own percentages. Avg / Line is the book average — total value over
    # total lines — never the mean of the per-row averages, which would weight
    # a 2-line status the same as a 10,590-line one.
    totals = {
        "lines_count": total_lines,
        "value":       round(total_value, 2),
        "lines_pct":   100.0 if total_lines else 0.0,
        "value_pct":   100.0 if total_value else 0.0,
        "avg_value":   round(total_value / total_lines, 2) if total_lines else 0.0,
    }
    # Explicit chart so Desk and the portal draw the same thing, and the
    # Operations dashboard panel can read it straight off this endpoint
    # instead of running its own query that could drift from the table.
    chart = {
        "data": {
            "labels": [r["status"] for r in data],
            "datasets": [
                {"name": "Lines", "values": [r["lines_count"] for r in data]},
            ],
        },
        "type": "bar",
    }
    return {"columns": columns, "data": data, "totals": totals, "chart": chart}


@frappe.whitelist()
def get_po_milestone_status_report(from_date=None, to_date=None, **kwargs):
    """PO Milestone Status — the order book counted by MILESTONE, not by line.

    dispatch_status is one value per line, but billing is per milestone, and a
    line's two milestones are routinely at different stages. That is what the
    "Partially Submitted" / "Partially Closed" statuses are papering over, and
    the line-level report cannot express it: it books a partially-closed
    line's WHOLE value into one stage. Measured on this data, the 801
    partially-closed/submitted lines carry SAR 423,415 of MS1 that is already
    Commercial Invoice Closed and only SAR 190,064 of MS2 still working
    through invoicing — so a line-level view overstates in-flight money by
    roughly the MS1 half.

    Here each milestone is its own row in the population: an MS1-only line
    contributes one, a two-milestone line contributes two, each carrying its
    own PIC status and its own ms1_amount / ms2_amount. 2,073 of 17,449 lines
    have an MS2; the other 15,376 are single-milestone, so the two views
    differ only on that minority — but that minority is where the money in
    flight actually sits.

    Ordered by the PIC's own status order, shared with the PIC pages via
    pic_status_order() so the same ladder reads the same way everywhere.

    A snapshot, so not date-filtered — same reasoning as the line-level report.
    """
    from inet_app.api.pic import pic_status_order

    rows = frappe.db.sql(
        """
        SELECT 'MS1' AS ms,
               IFNULL(NULLIF(pic_status, ''), 'Work Not Done') AS status,
               COUNT(*) AS milestones,
               COALESCE(SUM(ms1_amount), 0) AS value
        FROM `tabPO Dispatch`
        WHERE IFNULL(is_internal_work, 0) = 0 AND IFNULL(ms1_pct, 0) > 0
        GROUP BY IFNULL(NULLIF(pic_status, ''), 'Work Not Done')
        UNION ALL
        SELECT 'MS2' AS ms,
               IFNULL(NULLIF(pic_status_ms2, ''), 'Work Not Done') AS status,
               COUNT(*) AS milestones,
               COALESCE(SUM(ms2_amount), 0) AS value
        FROM `tabPO Dispatch`
        WHERE IFNULL(is_internal_work, 0) = 0 AND IFNULL(ms2_pct, 0) > 0
        GROUP BY IFNULL(NULLIF(pic_status_ms2, ''), 'Work Not Done')
        """,
        as_dict=True,
    )

    agg = {}
    for r in rows:
        a = agg.setdefault(r.status, {"ms1": 0, "ms2": 0, "ms1_val": 0.0, "ms2_val": 0.0})
        if r.ms == "MS1":
            a["ms1"] += cint(r.milestones)
            a["ms1_val"] += flt(r.value)
        else:
            a["ms2"] += cint(r.milestones)
            a["ms2_val"] += flt(r.value)

    total_ms = sum(a["ms1"] + a["ms2"] for a in agg.values())
    total_val = sum(a["ms1_val"] + a["ms2_val"] for a in agg.values())

    # Every PIC status first, in the PIC's order, then anything the data holds
    # that the list does not — a status left out would silently drop its
    # milestones from the book and stop the percentages reaching 100.
    ordered = list(pic_status_order())
    ordered += [s for s in sorted(agg) if s not in ordered]

    data = []
    for status in ordered:
        a = agg.get(status) or {"ms1": 0, "ms2": 0, "ms1_val": 0.0, "ms2_val": 0.0}
        cnt = a["ms1"] + a["ms2"]
        val = a["ms1_val"] + a["ms2_val"]
        data.append({
            "status":     status,
            "ms1_count":  a["ms1"],
            "ms2_count":  a["ms2"],
            "milestones": cnt,
            "ms_pct":     round(cnt / total_ms * 100, 1) if total_ms else 0.0,
            "ms1_value":  round(a["ms1_val"], 2),
            "ms2_value":  round(a["ms2_val"], 2),
            "value":      round(val, 2),
            "value_pct":  round(val / total_val * 100, 1) if total_val else 0.0,
        })
    for i, row in enumerate(data, 1):
        row["sn"] = i

    columns = [
        {"fieldname": "sn",         "label": "#",              "fieldtype": "Int"},
        {"fieldname": "status",     "label": "PIC Status",     "fieldtype": "Data"},
        {"fieldname": "ms1_count",  "label": "MS1",            "fieldtype": "Int"},
        {"fieldname": "ms2_count",  "label": "MS2",            "fieldtype": "Int"},
        {"fieldname": "milestones", "label": "Milestones",     "fieldtype": "Int"},
        {"fieldname": "ms_pct",     "label": "Milestones %",   "fieldtype": "Percent"},
        {"fieldname": "ms1_value",  "label": "MS1 Value (SAR)", "fieldtype": "Currency"},
        {"fieldname": "ms2_value",  "label": "MS2 Value (SAR)", "fieldtype": "Currency"},
        {"fieldname": "value",      "label": "Value (SAR)",    "fieldtype": "Currency"},
        {"fieldname": "value_pct",  "label": "Value %",        "fieldtype": "Percent"},
    ]
    # Percent totals are 100 by construction, not the sum of the rows' own
    # rounded percentages.
    totals = {
        "ms1_count":  sum(r["ms1_count"] for r in data),
        "ms2_count":  sum(r["ms2_count"] for r in data),
        "milestones": total_ms,
        "ms1_value":  round(sum(r["ms1_value"] for r in data), 2),
        "ms2_value":  round(sum(r["ms2_value"] for r in data), 2),
        "value":      round(total_val, 2),
        "ms_pct":     100.0 if total_ms else 0.0,
        "value_pct":  100.0 if total_val else 0.0,
    }
    chart = {
        "data": {
            "labels": [r["status"] for r in data],
            "datasets": [
                {"name": "MS1", "values": [r["ms1_count"] for r in data]},
                {"name": "MS2", "values": [r["ms2_count"] for r in data]},
            ],
        },
        "type": "bar",
    }
    return {"columns": columns, "data": data, "totals": totals, "chart": chart}

@frappe.whitelist()
def get_weekly_performance_report(from_date=None, to_date=None, **kwargs):
    """Weekly Performance — aggregated by ISO week: lines, revenue, re-visits."""
    fd, td = _perf_date_range(from_date, to_date)

    plan_rows = frappe.db.sql(
        """
        SELECT YEARWEEK(rp.plan_date, 1)        AS yw,
               MIN(DATE(rp.plan_date))           AS week_start,
               COUNT(DISTINCT rp.name)           AS assigned_lines,
               SUM(CASE WHEN rp.plan_status = 'Completed' THEN 1 ELSE 0 END) AS completed_lines,
               COUNT(CASE WHEN LOWER(IFNULL(rp.visit_type,'')) LIKE '%%re%%visit%%' THEN 1 END) AS revisits,
               COALESCE(SUM(rp.target_amount), 0) AS target
        FROM `tabRollout Plan` rp
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
        GROUP BY YEARWEEK(rp.plan_date, 1)
        ORDER BY yw
        """,
        (fd, td), as_dict=True,
    )

    # Active teams per week — separate query (not joined into plan_rows above,
    # which would fan out and double-count assigned/completed/target for any
    # multi-team plan). Unions rp.team (lead) with every Rollout Plan Team
    # split row so a multi-team plan counts all of its teams.
    team_split_rows = frappe.db.sql(
        """
        SELECT YEARWEEK(rp.plan_date, 1) AS yw, t.team
        FROM `tabRollout Plan` rp
        JOIN (
            SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
            UNION
            SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
        ) t ON t.plan = rp.name
        WHERE DATE(rp.plan_date) BETWEEN %s AND %s
          AND IFNULL(rp.plan_status, '') NOT IN ('Cancelled')
          AND t.team IS NOT NULL AND t.team != ''
        GROUP BY YEARWEEK(rp.plan_date, 1), t.team
        """,
        (fd, td), as_dict=True,
    )
    active_teams_by_yw = {}
    for r in team_split_rows:
        active_teams_by_yw.setdefault(r.yw, set()).add(r.team)

    rev_rows = frappe.db.sql(
        """
        SELECT YEARWEEK(de.execution_date, 1) AS yw,
               COALESCE(SUM(wd.revenue_sar), 0) AS revenue
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
        GROUP BY YEARWEEK(de.execution_date, 1)
        """,
        (fd, td), as_dict=True,
    )
    rev_by_yw = {r.yw: flt(r.revenue) for r in rev_rows}

    data = []
    total_assigned = 0
    total_completed = 0
    total_target = 0.0
    total_revenue = 0.0
    for i, r in enumerate(plan_rows, 1):
        target    = flt(r.target)
        revenue   = rev_by_yw.get(r.yw, 0.0)
        assigned  = cint(r.assigned_lines)
        completed = cint(r.completed_lines)
        compl_pct = round(completed / assigned * 100, 1) if assigned > 0 else 0.0
        ach_pct   = round(revenue / target * 100, 1) if target > 0 else 0.0
        total_assigned += assigned
        total_completed += completed
        total_target += target
        total_revenue += revenue
        data.append({
            "sn":              i,
            "week_start":      str(r.week_start),
            "active_teams":    len(active_teams_by_yw.get(r.yw, ())),
            "assigned_lines":  assigned,
            "completed_lines": completed,
            "completion_pct":  compl_pct,
            "revisits":        cint(r.revisits),
            "target":          round(target, 0),
            "revenue":         round(revenue, 0),
            "achievement_pct": ach_pct,
        })

    columns = [
        {"fieldname": "sn",              "label": "Week #",         "fieldtype": "Int"},
        {"fieldname": "week_start",      "label": "Week Start",     "fieldtype": "Date"},
        {"fieldname": "active_teams",    "label": "Active Teams",   "fieldtype": "Int"},
        {"fieldname": "assigned_lines",  "label": "Assigned",       "fieldtype": "Int"},
        {"fieldname": "completed_lines", "label": "Completed",      "fieldtype": "Int"},
        {"fieldname": "completion_pct",  "label": "Completion %",   "fieldtype": "Percent"},
        {"fieldname": "revisits",        "label": "Re-Visits",      "fieldtype": "Int"},
        {"fieldname": "target",          "label": "Target (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "revenue",         "label": "Revenue (SAR)",  "fieldtype": "Currency"},
        {"fieldname": "achievement_pct", "label": "Achievement %",  "fieldtype": "Percent"},
    ]
    totals = {
        "completion_pct": round(total_completed / total_assigned * 100, 1) if total_assigned > 0 else None,
        "achievement_pct": round(total_revenue / total_target * 100, 1) if total_target > 0 else None,
    }
    return {"columns": columns, "data": data, "totals": totals}


# ─────────────────────────────────────────────────────────────────────────────
# Step 4 — Revenue Tracking & Forecast
# ─────────────────────────────────────────────────────────────────────────────

@frappe.whitelist()
def get_revenue_tracking_report(from_date=None, to_date=None, **kwargs):
    """Monthly revenue breakdown: Gross, Sub-Con split, INET net revenue.

    Sub-Con Expense  = revenue × (1 - inet_margin_pct / 100)
    INET from Sub-Con = Sub-Con Gross − Sub-Con Expense
    INET Own Revenue  = Gross − Sub-Con Gross
    Total INET Revenue = INET from Sub-Con + INET Own Revenue
    """
    fd, td = _perf_date_range(from_date, to_date)

    rows = frappe.db.sql(
        """
        SELECT
            DATE_FORMAT(de.execution_date, '%%Y-%%m')            AS month,
            COALESCE(it.team_type, 'INET')                        AS team_type,
            COALESCE(SUM(wd.revenue_sar), 0)                      AS revenue,
            COALESCE(SUM(
                wd.revenue_sar * (100 - COALESCE(NULLIF(wd.inet_margin_pct, 0), 100)) / 100
            ), 0)                                                  AS subcon_expense
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        LEFT JOIN `tabINET Team` it ON it.name = de.team
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
        GROUP BY DATE_FORMAT(de.execution_date, '%%Y-%%m'), COALESCE(it.team_type, 'INET')
        ORDER BY month
        """,
        (fd, td), as_dict=True,
    )

    # Direct Close / Backend — no team/Daily Execution at all, so the query
    # above never sees them; bucketed by wd.creation's month instead of an
    # execution date it doesn't have. There's no INET Team.team_type to read
    # for these, so subcontract_cost_sar > 0 (set when the direct close was
    # done as type "SUB") stands in for the same INET/SUB split, reusing the
    # identical subcon_expense formula.
    direct_rows = frappe.db.sql(
        """
        SELECT
            DATE_FORMAT(wd.creation, '%%Y-%%m') AS month,
            (CASE WHEN IFNULL(wd.subcontract_cost_sar, 0) > 0 THEN 'SUB' ELSE 'INET' END) AS team_type,
            COALESCE(SUM(wd.revenue_sar), 0) AS revenue,
            COALESCE(SUM(
                wd.revenue_sar * (100 - COALESCE(NULLIF(wd.inet_margin_pct, 0), 100)) / 100
            ), 0) AS subcon_expense
        FROM `tabWork Done` wd
        WHERE IFNULL(wd.execution, '') = ''
          AND DATE(wd.creation) BETWEEN %s AND %s
        GROUP BY DATE_FORMAT(wd.creation, '%%Y-%%m'),
                 (CASE WHEN IFNULL(wd.subcontract_cost_sar, 0) > 0 THEN 'SUB' ELSE 'INET' END)
        """,
        (fd, td), as_dict=True,
    )
    rows = list(rows) + list(direct_rows)

    # Aggregate per month
    month_data = {}
    for r in rows:
        m = r.month
        if m not in month_data:
            month_data[m] = {"gross": 0.0, "subcon_gross": 0.0, "subcon_expense": 0.0}
        month_data[m]["gross"] += flt(r.revenue)
        if (r.team_type or "").upper() == "SUB":
            month_data[m]["subcon_gross"]   += flt(r.revenue)
            month_data[m]["subcon_expense"] += flt(r.subcon_expense)

    data = []
    for i, (month, m) in enumerate(sorted(month_data.items()), 1):
        gross           = round(m["gross"], 0)
        subcon_gross    = round(m["subcon_gross"], 0)
        subcon_expense  = round(m["subcon_expense"], 0)
        inet_subcon_rev = round(subcon_gross - subcon_expense, 0)
        inet_own_rev    = round(gross - subcon_gross, 0)
        total_inet_rev  = round(inet_subcon_rev + inet_own_rev, 0)
        inet_pct        = round(total_inet_rev / gross * 100, 1) if gross > 0 else 0.0
        data.append({
            "sn":              i,
            "month":           month,
            "gross_revenue":   gross,
            "subcon_gross":    subcon_gross,
            "subcon_expense":  subcon_expense,
            "inet_subcon_rev": inet_subcon_rev,
            "inet_own_rev":    inet_own_rev,
            "total_inet_rev":  total_inet_rev,
            "inet_margin_pct": inet_pct,
        })

    columns = [
        {"fieldname": "sn",              "label": "#",                       "fieldtype": "Int"},
        {"fieldname": "month",           "label": "Month",                   "fieldtype": "Data"},
        {"fieldname": "gross_revenue",   "label": "Gross Revenue (SAR)",     "fieldtype": "Currency"},
        {"fieldname": "subcon_gross",    "label": "Sub-Con Gross (SAR)",     "fieldtype": "Currency"},
        {"fieldname": "subcon_expense",  "label": "Sub-Con Expense (SAR)",   "fieldtype": "Currency"},
        {"fieldname": "inet_subcon_rev", "label": "INET from Sub-Con (SAR)", "fieldtype": "Currency"},
        {"fieldname": "inet_own_rev",    "label": "INET Own Revenue (SAR)",  "fieldtype": "Currency"},
        {"fieldname": "total_inet_rev",  "label": "Total INET Revenue (SAR)","fieldtype": "Currency"},
        {"fieldname": "inet_margin_pct", "label": "INET Margin %",           "fieldtype": "Percent"},
    ]
    return {"columns": columns, "data": data}


@frappe.whitelist()
def get_revenue_forecast_report(**kwargs):
    """6-month rolling revenue forecast (current month + 5 future).

    Planned  = SUM(pd.line_amount) WHERE pd.target_month = that month
    Achieved = SUM(wd.revenue_sar) WHERE execution_date in month
    Run Rate = Achieved / days_elapsed
    Forecast = Run Rate × total_days_in_month
    Gap      = Planned − Forecast
    """
    import calendar as _cal
    from frappe.utils import getdate as _gd, today as _today

    today_d = _gd(_today())

    # Planned revenue by month from PO Dispatch.target_month
    planned_rows = frappe.db.sql(
        """
        SELECT DATE_FORMAT(target_month, '%%Y-%%m') AS month,
               COALESCE(SUM(line_amount), 0)        AS planned
        FROM `tabPO Dispatch`
        WHERE target_month IS NOT NULL AND target_month != '0000-00-00'
          AND IFNULL(is_internal_work, 0) = 0
        GROUP BY DATE_FORMAT(target_month, '%%Y-%%m')
        """,
        as_dict=True,
    )
    planned_by_month = {r.month: flt(r.planned) for r in planned_rows}

    # Achieved revenue by month from Work Done
    achieved_rows = frappe.db.sql(
        """
        SELECT DATE_FORMAT(de.execution_date, '%%Y-%%m') AS month,
               COALESCE(SUM(wd.revenue_sar), 0)          AS achieved
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` de ON de.name = wd.execution
        GROUP BY DATE_FORMAT(de.execution_date, '%%Y-%%m')
        """,
        as_dict=True,
    )
    achieved_by_month = {r.month: flt(r.achieved) for r in achieved_rows}

    # Direct Close / Backend — no team/Daily Execution, so invisible above;
    # bucketed by wd.creation's month instead of an execution date it
    # doesn't have.
    direct_achieved_rows = frappe.db.sql(
        """
        SELECT DATE_FORMAT(wd.creation, '%%Y-%%m') AS month,
               COALESCE(SUM(wd.revenue_sar), 0)     AS achieved
        FROM `tabWork Done` wd
        WHERE IFNULL(wd.execution, '') = ''
        GROUP BY DATE_FORMAT(wd.creation, '%%Y-%%m')
        """,
        as_dict=True,
    )
    for r in direct_achieved_rows:
        achieved_by_month[r.month] = achieved_by_month.get(r.month, 0.0) + flt(r.achieved)

    # Build 6 rows: current month + 5 ahead
    data = []
    for offset in range(6):
        year  = today_d.year + (today_d.month - 1 + offset) // 12
        month = (today_d.month - 1 + offset) % 12 + 1
        month_key   = f"{year}-{month:02d}"
        total_days  = _cal.monthrange(year, month)[1]
        is_current  = (year == today_d.year and month == today_d.month)
        days_passed = today_d.day if is_current else (total_days if offset < 0 else 0)
        # For past months use full days; future months use 0 (no achieved, no run-rate)
        if offset == 0:
            days_passed = today_d.day
        elif offset < 0:
            days_passed = total_days
        else:
            days_passed = 0

        planned  = planned_by_month.get(month_key, 0.0)
        achieved = achieved_by_month.get(month_key, 0.0)
        run_rate = round(achieved / days_passed, 0) if days_passed > 0 else 0.0
        forecast = round(run_rate * total_days, 0)
        gap      = round(planned - forecast, 0)

        data.append({
            "month":       month_key,
            "planned":     round(planned, 0),
            "achieved":    round(achieved, 0),
            "days_passed": days_passed,
            "total_days":  total_days,
            "run_rate":    run_rate,
            "forecast":    forecast,
            "gap":         gap,
        })

    columns = [
        {"fieldname": "month",       "label": "Month",             "fieldtype": "Data"},
        {"fieldname": "planned",     "label": "Planned (SAR)",     "fieldtype": "Currency"},
        {"fieldname": "achieved",    "label": "Achieved (SAR)",    "fieldtype": "Currency"},
        {"fieldname": "days_passed", "label": "Days Elapsed",      "fieldtype": "Int"},
        {"fieldname": "total_days",  "label": "Total Days",        "fieldtype": "Int"},
        {"fieldname": "run_rate",    "label": "Daily Run Rate",    "fieldtype": "Currency"},
        {"fieldname": "forecast",    "label": "Forecast (SAR)",    "fieldtype": "Currency"},
        {"fieldname": "gap",         "label": "Gap (SAR)",         "fieldtype": "Currency"},
    ]
    return {"columns": columns, "data": data}


# ── Rollout Planning — weekly dashboard ─────────────────────────────────────
# Buckets the Rollout Plan statuses into the four the weekly view speaks in.
# Written out rather than inferred so it is obvious what lands where, and so
# the four together are a real partition of everything except Cancelled.
ROLLOUT_WEEK_BUCKETS = {
    "planned": ("Planned", "Planning with Issue"),
    "in_progress": ("In Execution", "Extended"),
    "completed": ("Completed",),
    "delayed": ("Overdue", "Not Attended"),
}
ROLLOUT_WEEK_EXCLUDED = ("Cancelled",)


def _rollout_scope_clause(im, alias="pd"):
    """(clause, params, resolved_im) for the rollout dashboards.

    An IM only ever sees their own lines. A PM asking for no particular IM sees
    every one — that is the whole difference between the two pages, so it lives
    here rather than in two near-identical endpoints.
    """
    roles = set(frappe.get_roles(frappe.session.user))
    is_admin = bool(roles & {"Administrator", "System Manager", "INET Admin"})
    if is_admin and not im:
        return "1=1", [], None
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    if not im_identifiers:
        return None, [], im_resolved
    ph = ", ".join(["%s"] * len(im_identifiers))
    return f"{alias}.im IN ({ph})", list(im_identifiers), im_resolved


def _rollout_week_bounds(week_start=None):
    """Monday..Sunday containing `week_start` (today when unset)."""
    anchor_day = getdate(week_start) if week_start else getdate(nowdate())
    monday = add_days(anchor_day, -anchor_day.weekday())
    return monday, add_days(monday, 6)


@frappe.whitelist()
def get_rollout_week_dashboard(im=None, week_start=None, portal_filters=None):
    """Everything the Rollout Planning weekly view shows, in one round trip.

    One query over the week's Rollout Plans feeds the plan grid, the status
    tiles, the activity split, the team workload and the per-day calendar —
    they are five readings of the same set, so computing them separately would
    be five chances for them to disagree.
    """
    scope_clause, scope_params, im_resolved = _rollout_scope_clause(im)
    monday, sunday = _rollout_week_bounds(week_start)
    empty = {
        "week": {"start": str(monday), "end": str(sunday), "days": []},
        "summary": {k: 0 for k in ("total", "planned", "in_progress", "completed", "delayed", "cancelled")},
        "activity": [], "teams": [], "rows": [], "im": im_resolved,
    }
    if scope_clause is None:
        return empty

    pf = _portal_filters_dict(portal_filters)
    wheres = [
        scope_clause,
        "rp.plan_date IS NOT NULL",
        # A plan counts as "in the week" when its span overlaps the week, not
        # only when it starts inside it — a Thu-to-Tue plan belongs to both.
        "rp.plan_date <= %s",
        "COALESCE(rp.plan_end_date, rp.plan_date) >= %s",
    ]
    params = list(scope_params) + [str(sunday), str(monday)]

    for col, key in (("pd.project_code", "project_code"),
                     ("rp.team", "team"),
                     ("pd.site_code", "site_code"),
                     ("pd.dispatch_mode", "dispatch_mode"),
                     # Narrows WITHIN the scope clause above, never past it —
                     # an IM cannot widen their own view by naming another IM.
                     ("pd.im", "im")):
        c, p = _sql_in_or_eq(col, pf.get(key))
        if c:
            wheres.append(c)
            params.extend(p)

    # Dummy / internal presets: the pages keep these selectors visible on the
    # weekly view, so they have to mean something here too rather than sit
    # there doing nothing.
    dummy_preset = (pf.get("dummy_preset") or "").strip()
    if dummy_preset == "dummy":
        wheres.append("IFNULL(pd.is_dummy_po, 0) = 1")
    elif dummy_preset == "standard":
        wheres.append("IFNULL(pd.is_dummy_po, 0) = 0")
    elif dummy_preset == "mapped_dummy":
        wheres.append("(IFNULL(pd.was_dummy_po, 0) = 1 AND IFNULL(pd.is_dummy_po, 0) = 0)")
    elif dummy_preset == "dummy_any":
        wheres.append("(IFNULL(pd.is_dummy_po, 0) = 1 OR IFNULL(pd.was_dummy_po, 0) = 1)")

    internal_preset = (pf.get("internal_preset") or "").strip()
    if internal_preset == "only":
        wheres.append("IFNULL(pd.is_internal_work, 0) = 1")
    elif internal_preset != "include":
        wheres.append("IFNULL(pd.is_internal_work, 0) = 0")

    like_pat = _sql_like_pattern(pf.get("search") or "")
    if like_pat:
        wheres.append(
            "CONCAT_WS(' ', IFNULL(pd.poid,''), IFNULL(pd.po_no,''), "
            "IFNULL(pd.project_code,''), IFNULL(pd.site_code,''), "
            "IFNULL(pd.site_name,''), IFNULL(it.team_name,'')) LIKE %s"
        )
        params.append(like_pat)

    rows = frappe.db.sql(
        f"""
        SELECT rp.name AS plan, rp.plan_date, rp.plan_end_date, rp.plan_status,
               IFNULL(rp.completion_pct, 0) AS completion_pct,
               rp.team, IFNULL(it.team_name, rp.team) AS team_name,
               rp.visit_type, rp.visit_number,
               pd.name AS po_dispatch, IFNULL(pd.poid, pd.name) AS poid,
               IFNULL(pd.dispatch_mode, '') AS mode,
               IFNULL(pd.project_code, '') AS project_code,
               COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') AS domain,
               IFNULL(pd.site_code, '') AS duid,
               IFNULL(pd.item_description, '') AS item_description,
               IFNULL(itm.activity_type, '') AS activity_type,
               IFNULL(pd.line_amount, 0) AS line_amount
        FROM `tabRollout Plan` rp
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabINET Team` it ON it.name = rp.team
        LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
        LEFT JOIN `tabItem` itm ON itm.name = pd.item_code
        WHERE {" AND ".join(wheres)}
        ORDER BY rp.plan_date ASC, pd.poid ASC
        """,
        tuple(params),
        as_dict=True,
    ) or []

    # Team workload ("teams" below) must count EVERY team a plan is split
    # across (Rollout Plan Team), not just rp.team (the lead) — fetched as a
    # separate query keyed by plan name rather than joined into `rows` above,
    # since `rows` feeds the plan grid / daily buckets / activity split too
    # and must stay one row per plan there.
    plan_names = [r["plan"] for r in rows]
    plan_teams_map = {}
    if plan_names:
        ph = ", ".join(["%s"] * len(plan_names))
        for t in frappe.db.sql(
            f"""
            SELECT rpt.parent AS plan, rpt.team AS team, IFNULL(it.team_name, rpt.team) AS team_name
            FROM `tabRollout Plan Team` rpt
            LEFT JOIN `tabINET Team` it ON it.name = rpt.team
            WHERE rpt.parent IN ({ph})
            """,
            tuple(plan_names), as_dict=True,
        ):
            plan_teams_map.setdefault(t.plan, set()).add((t.team, t.team_name))

    bucket_of = {}
    for bucket, statuses in ROLLOUT_WEEK_BUCKETS.items():
        for st in statuses:
            bucket_of[st] = bucket

    summary = {k: 0 for k in ("total", "planned", "in_progress", "completed", "delayed", "cancelled")}
    activity_counts, team_counts = {}, {}
    days = [{"date": str(add_days(monday, i)), "planned": 0, "in_progress": 0,
             "completed": 0, "delayed": 0} for i in range(7)]

    out_rows = []
    for r in rows:
        status = (r.get("plan_status") or "").strip()
        if status in ROLLOUT_WEEK_EXCLUDED:
            summary["cancelled"] += 1
            continue
        bucket = bucket_of.get(status, "planned")
        summary["total"] += 1
        summary[bucket] += 1

        act = (r.get("activity_type") or "").strip() or "Unspecified"
        activity_counts[act] = activity_counts.get(act, 0) + 1
        # plan_teams_map has one entry per team in the plan's real split
        # (including the lead, per _sync_plan_teams) whenever the plan has
        # been through the multi-team flow; legacy/unsplit plans fall back
        # to rp.team alone, same as before.
        split_teams = plan_teams_map.get(r["plan"])
        if split_teams:
            for key in split_teams:
                team_counts[key] = team_counts.get(key, 0) + 1
        elif r.get("team"):
            key = (r["team"], r.get("team_name") or r["team"])
            team_counts[key] = team_counts.get(key, 0) + 1

        # Clip the plan's span to the week so the grid can lay it out directly.
        start = getdate(r["plan_date"])
        end = getdate(r.get("plan_end_date") or r["plan_date"])
        if end < start:
            end = start
        clipped_start = max(start, monday)
        clipped_end = min(end, sunday)
        offset = (clipped_start - monday).days
        span = (clipped_end - clipped_start).days + 1
        for i in range(offset, offset + span):
            days[i][bucket] += 1

        out_rows.append({
            "plan": r["plan"], "po_dispatch": r["po_dispatch"], "poid": r["poid"],
            "mode": r["mode"], "project_code": r["project_code"], "domain": r["domain"],
            "duid": r["duid"], "activity_type": r["activity_type"],
            "item_description": r["item_description"],
            "team": r.get("team"), "team_name": r.get("team_name"),
            "visit_type": r.get("visit_type"), "visit_number": r.get("visit_number"),
            "plan_status": status, "bucket": bucket,
            "completion_pct": flt(r.get("completion_pct")),
            "line_amount": flt(r.get("line_amount")),
            "plan_date": str(start), "plan_end_date": str(end),
            "day_offset": offset, "day_span": span,
        })

    total = summary["total"] or 1
    activity = sorted(
        ({"label": k, "count": v, "pct": round(v * 100.0 / total, 1)}
         for k, v in activity_counts.items()),
        key=lambda a: -a["count"],
    )
    teams = sorted(
        ({"team": k[0], "team_name": k[1], "planned": v} for k, v in team_counts.items()),
        key=lambda t: -t["planned"],
    )
    for i, d in enumerate(days):
        d["label"] = frappe.utils.formatdate(d["date"], "EEE d")
        d["index"] = i

    return {
        "week": {"start": str(monday), "end": str(sunday), "days": days},
        "summary": summary,
        "activity": activity,
        "teams": teams,
        "rows": out_rows,
        "im": im_resolved,
    }


# ---------------------------------------------------------------------------
# Rollout Planning — weekly FORECAST (what the IM committed to at dispatch)
# ---------------------------------------------------------------------------

# Unlike ROLLOUT_WEEK_BUCKETS (a real partition of plan_status), the forecast
# reads a LINE's state plus an independent "did it slip" flag. A line completed
# in the wrong week is BOTH executed and slipped, and forcing that into one
# bucket loses whichever half the reader cared about.
FORECAST_STATES = ("not_planned", "planned", "executed")


def _forecast_month_weeks(month_start):
    """Every week that OVERLAPS the month, as (index, monday, sunday).

    Starts at the Monday of the 1st — so W1 usually begins in the previous
    month — and includes the week containing the last day. This is exactly the
    set the dispatch picker offers and the set _validate_forecast_input
    accepts, so a forecast can never land in a week this view has no column
    for.
    """
    out = []
    cur = add_days(month_start, -month_start.weekday())
    month_end = get_last_day(month_start)
    i = 1
    while cur <= month_end:
        out.append((i, cur, add_days(cur, 6)))
        cur = add_days(cur, 7)
        i += 1
    return out


def _forecast_month_start(month=None):
    """First day of the forecast month (this month when unset)."""
    if not month:
        return getdate(nowdate()).replace(day=1)
    m = str(month).strip()
    if len(m) == 7:
        m = f"{m}-01"
    return getdate(m).replace(day=1)


@frappe.whitelist()
def get_rollout_forecast_dashboard(
    im=None, month=None, months_ahead=6, portal_filters=None, limit=1500
):
    """The Weekly Forecast tab: one month, split into its weeks.

    The forecast is a MONTHLY commitment that the IM breaks down by week, so
    the month is the unit of the page and the weeks are how it is read inside.
    A rolling N-week horizon was the wrong frame — it cuts across month
    boundaries, which is not how this business plans.

    Three readings, one round trip:
      - the selected month's lines, bucketed into that month's weeks
      - a month strip either side of it, so the pipeline ahead is visible
      - the forecast-vs-planned-vs-executed variance for the selected month

    Where get_rollout_week_dashboard is Rollout Plan-driven (INNER JOIN to PO
    Dispatch), this is PO DISPATCH-driven with a LEFT JOIN to the current plan,
    because "forecast with nothing planned yet" is the most important row here
    and a plan-driven query cannot see it.

    Scope is the DISPATCHED population only (``target_month`` set). A line with
    no month has not been forecast at all — it is still in PO Control — so
    counting it as a "missing week" would report thousands of false gaps.

    A line's amount and qty are read live: a PO line's value is fixed once it
    exists, and a later change is a data-entry correction the forecast should
    follow rather than outrun.

    Nothing here constrains planning; a slip is reported, never blocked.
    """
    scope_clause, scope_params, im_resolved = _rollout_scope_clause(im)
    month_start = _forecast_month_start(month)
    month_end = get_last_day(month_start)
    weeks = _forecast_month_weeks(month_start)
    this_month = getdate(nowdate()).replace(day=1)
    today_monday, _ = _rollout_week_bounds(None)

    def _week_buckets():
        return [{
            "index": i, "start": str(mon), "end": str(sun),
            "label": f"W{i}",
            "range": f"{mon.strftime('%b %-d')} – {sun.strftime('%b %-d')}",
            "is_current": mon == today_monday,
            "total": 0, "not_planned": 0, "planned": 0, "executed": 0, "slipped": 0,
            "forecast_amount": 0.0, "planned_amount": 0.0, "executed_amount": 0.0,
        } for i, mon, sun in weeks]

    empty = {
        "month": {"start": str(month_start), "end": str(month_end),
                  "label": month_start.strftime("%B %Y"),
                  "is_current": month_start == this_month,
                  "weeks": _week_buckets()},
        "months": [],
        "summary": {k: 0 for k in ("total", "not_planned", "planned", "executed",
                                   "slipped", "team_changed", "no_week")}
                   | {k: 0.0 for k in ("forecast_amount", "planned_amount", "executed_amount")}
                   | {"plan_coverage_pct": 0.0, "week_accuracy_pct": 0.0},
        "unset": {"count": 0, "amount": 0.0, "rows": [], "truncated": False},
        "overdue": {"count": 0, "amount": 0.0},
        "activity": [], "teams": [], "ims": [], "projects": [],
        "rows": [], "rows_truncated": False, "im": im_resolved,
    }
    if scope_clause is None or not frappe.db.has_column("PO Dispatch", "target_week"):
        return empty

    pf = _portal_filters_dict(portal_filters)

    # Shared by the month query and the month-strip aggregate so the strip can
    # never disagree with the month it links to.
    base = [
        scope_clause,
        # Mirrors the has_target_month="yes" rule: once PIC owns the commercial
        # side there is no rollout left to forecast.
        "IFNULL(pd.dispatch_status, 'Pending') NOT IN "
        "('Cancelled', 'Submitted', 'Partially Submitted', 'Partially Closed', 'Closed')",
        "pd.target_month IS NOT NULL",
    ]
    base_params = list(scope_params)

    for col, key in (("pd.project_code", "project_code"),
                     ("pd.site_code", "site_code"),
                     ("pd.dispatch_mode", "dispatch_mode"),
                     # Narrows WITHIN the scope clause, never past it.
                     ("pd.im", "im")):
        c, p = _sql_in_or_eq(col, pf.get(key))
        if c:
            base.append(c)
            base_params.extend(p)

    dummy_preset = (pf.get("dummy_preset") or "").strip()
    if dummy_preset == "dummy":
        base.append("IFNULL(pd.is_dummy_po, 0) = 1")
    elif dummy_preset == "standard":
        base.append("IFNULL(pd.is_dummy_po, 0) = 0")
    elif dummy_preset == "mapped_dummy":
        base.append("(IFNULL(pd.was_dummy_po, 0) = 1 AND IFNULL(pd.is_dummy_po, 0) = 0)")
    elif dummy_preset == "dummy_any":
        base.append("(IFNULL(pd.is_dummy_po, 0) = 1 OR IFNULL(pd.was_dummy_po, 0) = 1)")

    internal_preset = (pf.get("internal_preset") or "").strip()
    if internal_preset == "only":
        base.append("IFNULL(pd.is_internal_work, 0) = 1")
    elif internal_preset != "include":
        base.append("IFNULL(pd.is_internal_work, 0) = 0")

    # ── Month strip: one row per forecast month, around the selected one ────
    months_ahead = max(1, min(cint(months_ahead) or 6, 12))
    strip_from = add_months(month_start, -1)
    strip_to = get_last_day(add_months(month_start, months_ahead - 1))
    strip = frappe.db.sql(
        f"""
        SELECT pd.target_month AS month, COUNT(*) AS total,
               SUM(IFNULL(pd.line_amount, 0)) AS forecast_amount,
               SUM(CASE WHEN IFNULL(pd.target_week, '') = '' THEN 1 ELSE 0 END) AS no_week
        FROM `tabPO Dispatch` pd
        WHERE {' AND '.join(base)} AND pd.target_month BETWEEN %s AND %s
        GROUP BY pd.target_month ORDER BY pd.target_month
        """,
        tuple(base_params) + (str(strip_from), str(strip_to)),
        as_dict=True,
    ) or []
    by_month = {str(r["month"]): r for r in strip}
    months = []
    for k in range(-1, months_ahead):
        ms = add_months(month_start, k)
        hit = by_month.get(str(ms)) or {}
        months.append({
            "month": str(ms),
            "label": ms.strftime("%b %Y"),
            "total": cint(hit.get("total") or 0),
            "forecast_amount": flt(hit.get("forecast_amount") or 0),
            "no_week": cint(hit.get("no_week") or 0),
            "is_selected": ms == month_start,
            "is_current": ms == this_month,
        })

    # ── The selected month's lines ─────────────────────────────────────────
    lim = _portal_row_limit(limit, 1500)
    wheres = list(base) + ["pd.target_month = %s"]
    params = list(base_params) + [str(month_start)]

    like_pat = _sql_like_pattern(pf.get("search") or "")
    if like_pat:
        wheres.append(
            "CONCAT_WS(' ', IFNULL(pd.poid,''), IFNULL(pd.po_no,''), "
            "IFNULL(pd.project_code,''), IFNULL(pd.site_code,''), "
            "IFNULL(pd.site_name,''), IFNULL(ft.team_name,''), "
            "IFNULL(pt.team_name,'')) LIKE %s"
        )
        params.append(like_pat)

    tc, tp = _sql_in_or_eq("pd.target_team", pf.get("team"))
    pc, pp = _sql_in_or_eq("rp.team", pf.get("team"))
    if tc and pc:
        wheres.append(f"({tc} OR {pc})")
        params.extend(list(tp) + list(pp))

    # The current-plan join reproduces _current_plan_subquery's ORDER BY
    # verbatim (visit_number DESC, modified DESC) so this tab can never
    # disagree with the table's Plan Status column. It cannot reuse that helper
    # literally — the helper hardcodes its outer reference and returns a scalar.
    rows = frappe.db.sql(
        f"""
        SELECT pd.name AS po_dispatch, IFNULL(pd.poid, pd.name) AS poid,
               IFNULL(pd.dispatch_mode, '') AS mode,
               IFNULL(pd.project_code, '') AS project_code,
               COALESCE(NULLIF(pd.project_domain, ''), pcc.project_domain, '') AS domain,
               IFNULL(pd.site_code, '') AS duid,
               IFNULL(pd.item_description, '') AS item_description,
               IFNULL(itm.activity_type, '') AS activity_type,
               pd.dispatch_status, pd.target_month, pd.target_week, pd.target_date,
               pd.target_team, IFNULL(ft.team_name, pd.target_team) AS target_team_name,
               IFNULL(pd.im, '') AS im_code,
               COALESCE(NULLIF(rim.full_name, ''), NULLIF(pd.im, ''), '') AS im_name,
               IFNULL(pd.line_amount, 0) AS forecast_amount,
               IFNULL(pd.qty, 0) AS forecast_qty,
               rp.name AS plan, rp.plan_date, rp.plan_end_date, rp.plan_status,
               IFNULL(rp.completion_pct, 0) AS completion_pct,
               IFNULL(rp.target_amount, 0) AS planned_amount,
               IFNULL(rp.achieved_amount, 0) AS executed_amount,
               rp.team AS plan_team, IFNULL(pt.team_name, rp.team) AS plan_team_name
        FROM `tabPO Dispatch` pd
        LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
        LEFT JOIN `tabItem` itm ON itm.name = pd.item_code
        LEFT JOIN `tabINET Team` ft ON ft.name = pd.target_team
        LEFT JOIN `tabIM Master` rim ON rim.name = pd.im
        LEFT JOIN `tabRollout Plan` rp ON rp.name = (
            SELECT rp2.name FROM `tabRollout Plan` rp2
            WHERE rp2.po_dispatch = pd.name AND rp2.plan_status != 'Cancelled'
            ORDER BY IFNULL(rp2.visit_number, 0) DESC, rp2.modified DESC LIMIT 1)
        LEFT JOIN `tabINET Team` pt ON pt.name = rp.team
        WHERE {' AND '.join(wheres)}
        ORDER BY IFNULL(pd.target_week, '9999-12-31') ASC, pd.poid ASC
        """,
        tuple(params),
        as_dict=True,
    ) or []

    # Executed dates, keyed by the plans actually returned — mirroring how the
    # weekly view fetches Rollout Plan Team. A LEFT JOIN (SELECT ... GROUP BY)
    # here would scan all of Daily Execution on every call.
    exec_map = {}
    plan_names = [r["plan"] for r in rows if r.get("plan")]
    if plan_names:
        for chunk in _chunked(plan_names, 1000):
            ph = ", ".join(["%s"] * len(chunk))
            for e in frappe.db.sql(
                f"""SELECT rollout_plan, MIN(execution_date) AS first_exec,
                           MAX(execution_date) AS last_exec,
                           SUM(IFNULL(achieved_qty, 0)) AS exec_qty
                    FROM `tabDaily Execution` WHERE rollout_plan IN ({ph})
                    GROUP BY rollout_plan""",
                tuple(chunk), as_dict=True,
            ) or []:
                exec_map[e["rollout_plan"]] = e

    week_buckets = _week_buckets()
    by_week = {b["start"]: b for b in week_buckets}
    summary = dict(empty["summary"])
    dated_rows, unset_rows = [], []
    overdue_n, overdue_amt = 0, 0.0
    activity_counts, team_stats, project_stats, im_stats = {}, {}, {}, {}

    for r in rows:
        tw = r.get("target_week")
        fa = flt(r.get("forecast_amount"))
        ex = exec_map.get(r.get("plan")) or {}
        r["first_exec_date"] = str(ex["first_exec"]) if ex.get("first_exec") else None
        r["last_exec_date"] = str(ex["last_exec"]) if ex.get("last_exec") else None
        r["executed_qty"] = flt(ex.get("exec_qty") or 0)

        if not r.get("plan"):
            state = "not_planned"
        elif (r.get("plan_status") or "") == "Completed" or flt(r.get("completion_pct")) >= 100:
            state = "executed"
        else:
            state = "planned"
        r["state"] = state

        plan_week = None
        if r.get("plan_date"):
            plan_week, _ = _rollout_week_bounds(r["plan_date"])
            r["plan_week"] = str(plan_week)

        # Slip = the plan's SPAN does not overlap the forecast week. Overlap,
        # not equality: a multi-day plan straddling the boundary is not a miss.
        slipped = False
        week_delta = None
        if tw and r.get("plan_date"):
            tw_d = getdate(tw)
            sun = add_days(tw_d, 6)
            p_start = getdate(r["plan_date"])
            p_end = getdate(r.get("plan_end_date") or r["plan_date"])
            slipped = (p_start > sun or p_end < tw_d)
            week_delta = (plan_week - tw_d).days // 7
        if (r.get("plan_status") or "") in ("Overdue", "Not Attended"):
            slipped = True
        r["slipped"] = slipped
        r["week_delta"] = week_delta
        r["team_changed"] = bool(
            r.get("target_team") and r.get("plan_team")
            and r["target_team"] != r["plan_team"]
        )

        # Every line counts toward the MONTH, whether or not it has a week —
        # the month is the commitment, the week is only how it is broken down.
        summary["total"] += 1
        summary[state] += 1
        if slipped:
            summary["slipped"] += 1
        if r["team_changed"]:
            summary["team_changed"] += 1
        summary["forecast_amount"] += fa
        summary["planned_amount"] += flt(r.get("planned_amount"))
        summary["executed_amount"] += flt(r.get("executed_amount"))

        act = r.get("activity_type") or "Unspecified"
        activity_counts[act] = activity_counts.get(act, 0) + 1
        tid = r.get("target_team") or ""
        ts = team_stats.setdefault(
            tid, {"team": tid, "team_name": r.get("target_team_name") or (tid or "No team"),
                  "forecast": 0, "planned": 0, "executed": 0})
        ts["forecast"] += 1
        if state == "planned":
            ts["planned"] += 1
        elif state == "executed":
            ts["executed"] += 1
        proj = r.get("project_code") or ""
        ps = project_stats.setdefault(
            proj, {"project_code": proj or "No project", "total": 0, "forecast_amount": 0.0})
        ps["total"] += 1
        ps["forecast_amount"] += fa

        # Per-IM roll-up. An IM's own view collapses to a single row, so the
        # frontend only shows this rail when no IM scope is in play.
        imc = r.get("im_code") or ""
        ims = im_stats.setdefault(imc, {
            "im": imc, "im_name": r.get("im_name") or (imc or "No IM"),
            "total": 0, "not_planned": 0, "planned": 0, "executed": 0,
            "slipped": 0, "no_week": 0, "forecast_amount": 0.0,
        })
        ims["total"] += 1
        ims[state] += 1
        if slipped:
            ims["slipped"] += 1
        if not tw:
            ims["no_week"] += 1
        ims["forecast_amount"] += fa

        if not tw:
            summary["no_week"] += 1
            unset_rows.append(r)
            continue
        dated_rows.append(r)
        if getdate(tw) < today_monday and state != "executed":
            overdue_n += 1
            overdue_amt += fa

        b = by_week.get(str(tw))
        if b:
            b["total"] += 1
            b[state] += 1
            if slipped:
                b["slipped"] += 1
            b["forecast_amount"] += fa
            b["planned_amount"] += flt(r.get("planned_amount"))
            b["executed_amount"] += flt(r.get("executed_amount"))

    planned_or_better = summary["planned"] + summary["executed"]
    summary["plan_coverage_pct"] = round(
        planned_or_better * 100.0 / summary["total"], 1) if summary["total"] else 0.0
    summary["week_accuracy_pct"] = round(
        (planned_or_better - summary["slipped"]) * 100.0 / planned_or_better, 1
    ) if planned_or_better else 0.0

    total_act = sum(activity_counts.values()) or 1
    activity = sorted(
        ({"label": k, "count": v, "pct": round(v * 100.0 / total_act, 1)}
         for k, v in activity_counts.items()),
        key=lambda x: -x["count"])

    out_rows = dated_rows + unset_rows
    return {
        "month": {"start": str(month_start), "end": str(month_end),
                  "label": month_start.strftime("%B %Y"),
                  "is_current": month_start == this_month,
                  "weeks": week_buckets},
        "months": months,
        "summary": summary,
        "unset": {
            "count": len(unset_rows),
            "amount": sum(flt(r.get("forecast_amount")) for r in unset_rows),
            "rows": unset_rows[:200],
            "truncated": len(unset_rows) > 200,
        },
        "overdue": {"count": overdue_n, "amount": overdue_amt},
        "activity": activity,
        "teams": sorted(team_stats.values(), key=lambda t: -t["forecast"]),
        "ims": sorted(im_stats.values(), key=lambda x: -x["total"]),
        "projects": sorted(project_stats.values(), key=lambda p: -p["forecast_amount"])[:10],
        "rows": out_rows[:lim] if lim else out_rows,
        "rows_truncated": bool(lim and len(out_rows) > lim),
        "im": im_resolved,
    }


# ---------------------------------------------------------------------------
# Execution Analytics — the Execution Monitor dataset, read analytically
# ---------------------------------------------------------------------------

# One pass over Daily Execution gives BOTH the per-plan aggregates and the
# latest-DE values. The monitor derives each DE column with its own correlated
# subquery (_latest_de), which EXPLAIN shows as a DEPENDENT SUBQUERY with no
# usable index on rollout_plan — O(plans x DEs). This materialises once and
# joins on an auto-key instead.
#
# ORDER BY modified DESC + rn = 1 reproduces the monitor's "first seen per
# plan is the latest" rule exactly, so both pages agree on what "the latest
# execution" means.
_DEX_SQL = """
  SELECT * FROM (
    SELECT rollout_plan,
           execution_status AS latest_exec_status,
           tl_status        AS latest_tl_status,
           qc_status        AS latest_qc_status,
           ciag_status      AS latest_ciag_status,
           issue_category   AS latest_issue_category,
           execution_date   AS latest_exec_date,
           team             AS latest_exec_team,
           COUNT(*)                                         OVER w AS de_count,
           MAX(execution_status = 'Completed')              OVER w AS any_im_done,
           MAX(tl_status = 'Completed')                     OVER w AS any_tl_done,
           MAX(qc_status   IN ('Pass', 'Not Applicable'))   OVER w AS qc_ok,
           MAX(qc_status   = 'Fail')                        OVER w AS qc_fail,
           MAX(ciag_status IN ('Approved', 'Not Applicable')) OVER w AS ciag_ok,
           MAX(IFNULL(issue_category, '') <> '')            OVER w AS any_issue,
           MIN(execution_date)                              OVER w AS first_exec_date,
           MAX(execution_date)                              OVER w AS last_exec_date,
           ROW_NUMBER() OVER (PARTITION BY rollout_plan ORDER BY modified DESC) AS rn
    FROM `tabDaily Execution`
    WINDOW w AS (PARTITION BY rollout_plan)
  ) z WHERE z.rn = 1
"""

# Work Done reaches a plan through its execution, never directly.
_WDX_SQL = """
  SELECT de.rollout_plan,
         MIN(DATE(wd.creation)) AS wd_created,
         MAX(IFNULL(wd.ms1_closed, 0)) AS ms1_closed,
         MAX(IFNULL(wd.ms2_closed, 0)) AS ms2_closed
  FROM `tabWork Done` wd
  INNER JOIN `tabDaily Execution` de ON de.name = wd.execution
  GROUP BY de.rollout_plan
"""

# Work nobody is going to do is not "attention". A cancelled plan, or one
# waiting on a PM to approve its cancellation, is deliberately excluded from
# every bucket — chasing QC on a line the IM has asked to cancel is noise.
# Both remain visible in the plan_status dimension and in the totals.
_ACTIONABLE = (
    "IFNULL(rp.plan_status, '') <> 'Cancelled'"
    " AND IFNULL(rp.cancel_request_status, '') <> 'Pending PM Approval'"
)

_QC_REQ = "IFNULL(rp.qc_required, 1)"
_CIAG_REQ = "IFNULL(rp.ciag_required, 1)"

# Predicates are shared with list_execution_monitor_rows (via the `bucket`
# filter) so a tile's count and the list you land on cannot disagree.
# NOTE: buckets deliberately overlap — a line can be QC-pending AND overdue
# AND issue-flagged. They do not sum to the total, and the UI says so.
EXECUTION_ATTENTION_BUCKETS = {
    "no_execution": {
        "target": "plans",
        "label": "No execution yet", "tone": "warn",
        "hint": "Planned, but no Daily Execution has been filed",
        "cond": "dex.rollout_plan IS NULL",
    },
    "qc_pending": {
        "target": "work_done",
        "label": "QC pending", "tone": "warn",
        "hint": "Executed, still waiting on a QC pass",
        "cond": f"dex.rollout_plan IS NOT NULL AND {_QC_REQ} = 1 AND IFNULL(dex.qc_ok, 0) = 0",
    },
    "qc_failed": {
        "target": "work_done",
        "label": "QC failed", "tone": "bad",
        "hint": "At least one execution failed QC",
        "cond": "IFNULL(dex.qc_fail, 0) = 1",
    },
    "ciag_pending": {
        "target": "work_done",
        "label": "CIAG pending", "tone": "warn",
        "hint": "Executed, still waiting on CIAG approval",
        "cond": f"dex.rollout_plan IS NOT NULL AND {_CIAG_REQ} = 1 AND IFNULL(dex.ciag_ok, 0) = 0",
    },
    "im_confirmation_pending": {
        "target": "work_done",
        "label": "IM confirmation pending", "tone": "warn",
        "hint": "Team lead finished; the IM has not confirmed",
        "cond": "IFNULL(dex.any_tl_done, 0) = 1 AND IFNULL(dex.any_im_done, 0) = 0",
    },
    "im_confirmation_only": {
        "target": "work_done",
        "label": "IM confirmation ONLY pending", "tone": "bad",
        "hint": "Nothing else is outstanding — one click from done",
        # QC/CIAG short-circuit on the per-plan _required flags, exactly as the
        # closure test does, so a plan that never needed QC is not held back by
        # a qc_status still reading 'Pending'.
        "cond": (
            "IFNULL(dex.any_tl_done, 0) = 1 AND IFNULL(dex.any_im_done, 0) = 0"
            f" AND ({_QC_REQ} = 0 OR IFNULL(dex.qc_ok, 0) = 1)"
            f" AND ({_CIAG_REQ} = 0 OR IFNULL(dex.ciag_ok, 0) = 1)"
            " AND IFNULL(rp.plan_status, '') <> 'Cancelled'"
        ),
    },
    "work_done_missing": {
        "target": "work_done",
        "label": "Work Done not created", "tone": "warn",
        "hint": "IM-confirmed but no Work Done record exists",
        "cond": "IFNULL(dex.any_im_done, 0) = 1 AND wdx.rollout_plan IS NULL",
    },
    "dummy_unmapped": {
        "target": "plans",
        "label": "Dummy PO not mapped", "tone": "warn",
        "hint": "Still a placeholder — never mapped to a real PO line",
        # is_dummy_po, NOT was_dummy_po: mapping clears the former and leaves
        # the latter set forever.
        "cond": "IFNULL(pd.is_dummy_po, 0) = 1",
    },
    "internal_unclassified": {
        "target": "plans",
        "label": "Internal work unclassified", "tone": "warn",
        "hint": "Internal work with no work type, or Domain with no domain set",
        "cond": (
            "IFNULL(pd.is_internal_work, 0) = 1 AND ("
            " IFNULL(pd.internal_work_type, '') = ''"
            " OR (pd.internal_work_type = 'Domain' AND IFNULL(pd.internal_domain, '') = '')"
            ")"
        ),
    },
    "internal_pending": {
        "target": "plans",
        "label": "Internal work pending", "tone": "warn",
        "hint": "Internal work still outstanding",
        "cond": "IFNULL(pd.is_internal_work, 0) = 1 AND IFNULL(dex.any_im_done, 0) = 0",
    },
    "overdue_flagged": {
        "target": "plans",
        "label": "Overdue (flagged)", "tone": "bad",
        "hint": "plan_status is Overdue — written by the nightly job",
        "cond": "IFNULL(rp.plan_status, '') = 'Overdue'",
    },
    "overdue_by_date": {
        "target": "plans",
        "label": "Overdue (by date)", "tone": "bad",
        "hint": "Plan end date has passed and it is neither complete nor cancelled",
        # Shown next to the flagged count on purpose: a gap between the two
        # means the scheduler is behind, which is itself worth knowing.
        "cond": (
            "COALESCE(rp.plan_end_date, rp.plan_date) < CURDATE()"
            " AND IFNULL(rp.plan_status, '') NOT IN ('Completed', 'Cancelled')"
        ),
    },
    "not_attended": {
        "target": "plans",
        "label": "Not attended", "tone": "bad",
        "hint": "Planned but the team never attended",
        "cond": "IFNULL(rp.plan_status, '') = 'Not Attended'",
    },
    "issue_flagged": {
        "target": "work_done",
        "label": "Issue flagged", "tone": "bad",
        "hint": "An issue category is set on the plan or an execution",
        "cond": "IFNULL(rp.issue_category, '') <> '' OR IFNULL(dex.any_issue, 0) = 1",
    },
    "cancel_pending": {
        "target": "plans",
        "label": "Cancel awaiting PM", "tone": "info",
        "hint": "IM asked to cancel; a PM has not responded yet",
        "cond": "IFNULL(rp.cancel_request_status, '') = 'Pending PM Approval'",
        "always": True,
    },
    "no_team": {
        "target": "plans",
        "label": "No team assigned", "tone": "warn",
        "hint": "Neither a lead team nor any split team",
        "cond": (
            "IFNULL(rp.team, '') = '' AND NOT EXISTS ("
            " SELECT 1 FROM `tabRollout Plan Team` rpt WHERE rpt.parent = rp.name)"
        ),
    },
}

# Every dimension the client may group by. The client sends a KEY; the SQL
# never comes from the request.
#
# Two traps encoded here:
#  - project_domain must NOT reuse col_filter_map["domain"], which is a
#    CONCAT_WS built for LIKE matching. As a group key it yields labels like
#    "Zain Fixes Zain Fixes" whenever both domain columns are populated.
#  - `im` groups on the code and labels with the full name, so a breakdown row
#    can drill through to a filter that matches what the cell renders.
EXECUTION_ANALYTICS_DIMENSIONS = {
    "project_domain": {"label": "Project domain", "blank": "(No domain)", "expr":
        "CASE WHEN IFNULL(pd.is_internal_work, 0) = 1 THEN IFNULL(pd.internal_domain, '')"
        " ELSE COALESCE(NULLIF(pd.project_domain, ''), pcc.project_domain, '') END"},
    "project": {"label": "Project", "blank": "(No project)", "expr": "IFNULL(pd.project_code, '')"},
    "duid": {"label": "DUID / site", "blank": "(No DUID)", "expr": "IFNULL(pd.site_code, '')"},
    "im": {"label": "IM", "blank": "(No IM)",
           "expr": "COALESCE(NULLIF(pd.im, ''), rp.im, '')",
           "label_expr": "COALESCE(NULLIF(rim.full_name, ''), NULLIF(pd.im, ''), rp.im, '')"},
    "huawei_im": {"label": "Huawei IM", "blank": "(No Huawei IM)", "expr":
        "COALESCE(NULLIF(pd.huawei_im, ''), pcc.huawei_im, '')"},
    "team": {"label": "Team (plan lead)", "blank": "(No team)", "expr":
        "IFNULL(NULLIF(it.team_name, ''), IFNULL(rp.team, ''))"},
    "visit_type": {"label": "Visit type", "blank": "(Unset)", "expr": "IFNULL(rp.visit_type, '')"},
    "visit_number": {"label": "Visit number", "blank": "0", "expr":
        "CASE WHEN IFNULL(rp.visit_number, 0) >= 5 THEN '5+'"
        " ELSE CAST(IFNULL(rp.visit_number, 0) AS CHAR) END"},
    "plan_status": {"label": "Plan status", "blank": "(Unset)", "expr": "IFNULL(rp.plan_status, '')"},
    "execution_status": {"label": "Execution status (IM)", "blank": "(No execution)", "expr":
        "IFNULL(dex.latest_exec_status, '')"},
    "tl_status": {"label": "TL status", "blank": "(No execution)", "expr":
        "IFNULL(dex.latest_tl_status, '')"},
    "issue_category": {"label": "Issue category", "blank": "(No issue)", "expr":
        "COALESCE(NULLIF(dex.latest_issue_category, ''), NULLIF(rp.issue_category, ''), '')"},
    "issue_status": {"label": "Issue status", "blank": "(No issue)", "expr":
        "IFNULL(rp.issue_status, '')"},
    "qc_status": {"label": "QC status", "blank": "(No execution)", "expr":
        f"CASE WHEN {_QC_REQ} = 0 THEN 'Not required' ELSE IFNULL(dex.latest_qc_status, '') END"},
    "ciag_status": {"label": "CIAG status", "blank": "(No execution)", "expr":
        f"CASE WHEN {_CIAG_REQ} = 0 THEN 'Not required' ELSE IFNULL(dex.latest_ciag_status, '') END"},
    "access_period": {"label": "Access period", "blank": "(Unset)", "expr":
        "IFNULL(rp.access_period, '')"},
    "access_time": {"label": "Access time", "blank": "(Unset)", "expr":
        "CASE WHEN rp.access_time IS NULL THEN ''"
        " ELSE CONCAT(LPAD(HOUR(rp.access_time), 2, '0'), ':00') END"},
    "region_type": {"label": "Region", "blank": "(Unset)", "expr":
        "COALESCE(NULLIF(rp.region_type, ''), pd.region_type, '')"},
    "center_area": {"label": "Center area", "blank": "(Unset)", "expr": "IFNULL(pd.center_area, '')"},
    "activity_type": {"label": "Activity type", "blank": "(Unspecified)", "expr":
        "IFNULL(itm.activity_type, '')"},
    "item_code": {"label": "Item", "blank": "(No item)", "expr": "IFNULL(pd.item_code, '')"},
    "dispatch_status": {"label": "Dispatch status", "blank": "(Unset)", "expr":
        "IFNULL(pd.dispatch_status, '')"},
    "internal_work_type": {"label": "Internal work type", "blank": "(Not internal)", "expr":
        "IFNULL(pd.internal_work_type, '')"},
    "work_mode": {"label": "Work mode", "blank": "(Unset)", "expr":
        "CASE WHEN IFNULL(pd.is_internal_work, 0) = 1 THEN 'Internal'"
        " WHEN IFNULL(pd.is_dummy_po, 0) = 1 THEN 'Dummy (open)'"
        " WHEN IFNULL(pd.was_dummy_po, 0) = 1 THEN 'Mapped dummy'"
        " ELSE 'Standard' END"},
}

EXECUTION_ANALYTICS_DEFAULT_DIMS = [
    "project_domain", "project", "im", "execution_status", "plan_status", "team",
]

_EXEC_DATE_BASES = {
    # Span overlap, not "starts inside": a Thu-to-Tue plan belongs to both
    # windows. Mirrors get_rollout_week_dashboard; the monitor's plain BETWEEN
    # on plan_date silently drops straddling plans.
    "plan": {"label": "Plan date", "expr": "rp.plan_date", "overlap": True},
    "execution": {"label": "Execution date",
                  "expr": "COALESCE(dex.last_exec_date, rp.plan_date)"},
    # Work Done carries no work date of its own; COALESCE(execution_date,
    # DATE(wd.creation)) is the convention already used in six other reports.
    "work_done": {"label": "Work done date",
                  "expr": "COALESCE(dex.latest_exec_date, wdx.wd_created)"},
}

_EXEC_ANALYTICS_FROM = f"""
FROM `tabRollout Plan` rp
LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
LEFT JOIN `tabINET Team` it ON it.name = rp.team
LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
LEFT JOIN `tabIM Master` rim ON rim.name = COALESCE(NULLIF(pd.im, ''), rp.im)
LEFT JOIN `tabItem` itm ON itm.name = pd.item_code
LEFT JOIN ({_DEX_SQL}) dex ON dex.rollout_plan = rp.name
LEFT JOIN ({_WDX_SQL}) wdx ON wdx.rollout_plan = rp.name
"""


def execution_bucket_condition(key):
    """A bucket's SQL, with the shared actionable guard applied.

    Every consumer goes through here — the analytics tiles and both drill-in
    list endpoints — so a tile and the list it opens can never diverge on what
    counts as still-actionable. Buckets marked `always` opt out of the guard
    because they ARE the cancellation state.
    """
    spec = EXECUTION_ATTENTION_BUCKETS.get(key)
    if not spec:
        frappe.throw(f"Unknown bucket: {key}")
    if spec.get("always"):
        return f"({spec['cond']})"
    return f"(({spec['cond']}) AND {_ACTIONABLE})"


def _execution_analytics_where(pf, im):
    """(wheres, params, im_resolved) shared by every rail on the page.

    Returning one WHERE for all of them is the point: the tiles, the
    breakdowns and the concentration rail are readings of a single set, so
    they cannot describe different populations.
    """
    scope_clause, scope_params, im_resolved = _rollout_scope_clause(im)
    if scope_clause is None:
        return None, [], im_resolved

    wheres = [scope_clause]
    params = list(scope_params)

    closure = (pf.get("closure") or "all").strip().lower()
    if closure not in ("open", "all", "closed"):
        closure = "all"
    if closure != "all":
        wheres.append(("NOT " if closure == "open" else "") + _execution_closed_exists_sql())

    wheres.append("NOT " + _execution_superseded_exists_sql())

    # Internal work that is already done needs nothing from anyone — it would
    # only pad the totals and the breakdowns. Mirrors the "Internal Work Done"
    # split both list pages already make.
    wheres.append(
        "NOT (IFNULL(pd.is_internal_work, 0) = 1"
        " AND IFNULL(dex.any_im_done, 0) = 1)"
    )

    basis_key = (pf.get("date_basis") or "plan").strip().lower()
    basis = _EXEC_DATE_BASES.get(basis_key) or _EXEC_DATE_BASES["plan"]
    from_date, to_date = pf.get("from_date"), pf.get("to_date")
    if from_date or to_date:
        if basis.get("overlap"):
            if to_date:
                wheres.append("rp.plan_date <= %s")
                params.append(to_date)
            if from_date:
                wheres.append("COALESCE(rp.plan_end_date, rp.plan_date) >= %s")
                params.append(from_date)
        else:
            if from_date:
                wheres.append(f"{basis['expr']} >= %s")
                params.append(from_date)
            if to_date:
                wheres.append(f"{basis['expr']} <= %s")
                params.append(to_date)

    for col, key in (("pd.project_code", "project_code"),
                     ("pd.site_code", "site_code"),
                     ("rp.team", "team"),
                     ("rp.visit_type", "visit_type"),
                     ("rp.plan_status", "status"),
                     ("dex.latest_exec_status", "execution_status"),
                     # Narrows WITHIN the scope clause, never past it.
                     ("pd.im", "im")):
        c, p = _sql_in_or_eq(col, pf.get(key))
        if c:
            wheres.append(c)
            params.extend(p)

    dom = pf.get("project_domain")
    c, p = _sql_in_or_eq(EXECUTION_ANALYTICS_DIMENSIONS["project_domain"]["expr"], dom)
    if c:
        wheres.append(c)
        params.extend(p)

    bucket = (pf.get("bucket") or "").strip()
    if bucket:
        wheres.append(execution_bucket_condition(bucket))

    internal_preset = (pf.get("internal_preset") or "include").strip().lower()
    if internal_preset == "only":
        wheres.append("IFNULL(pd.is_internal_work, 0) = 1")
    elif internal_preset == "exclude":
        wheres.append("IFNULL(pd.is_internal_work, 0) = 0")

    dummy_preset = (pf.get("dummy_preset") or "").strip().lower()
    if dummy_preset == "dummy":
        wheres.append("IFNULL(pd.is_dummy_po, 0) = 1")
    elif dummy_preset == "standard":
        wheres.append("IFNULL(pd.is_dummy_po, 0) = 0")

    like_pat = _sql_like_pattern(pf.get("search") or "")
    if like_pat:
        wheres.append(
            "CONCAT_WS(' ', IFNULL(pd.poid,''), IFNULL(pd.po_no,''), "
            "IFNULL(pd.project_code,''), IFNULL(pd.site_code,''), "
            "IFNULL(pd.site_name,''), IFNULL(it.team_name,'')) LIKE %s"
        )
        params.append(like_pat)

    return wheres, params, im_resolved


@frappe.whitelist()
def get_execution_analytics(im=None, portal_filters=None, dimensions=None):
    """A full analytical read of the Execution Monitor dataset.

    Answers, in one round trip: what needs attention, how it splits across any
    of ~25 dimensions, where work is concentrated (repeat visits, busy DUIDs),
    and how it has moved month to month.

    Four tiers of aggregate SQL — no rows are ever fetched and counted in
    Python. Every count comes from GROUP BY or SUM(condition).

    Unlike the monitor this defaults to closure='all': the whole point is to
    include finished and historical work. That costs nothing in bucket
    accuracy, because a fully closed line fails every attention bucket on its
    own predicate anyway.

    Buckets deliberately OVERLAP. They do not sum to the total.
    """
    pf = _portal_filters_dict(portal_filters)
    wheres, params, im_resolved = _execution_analytics_where(pf, im)

    # One GROUP BY per selected dimension — capped at 6 so the page stays a
    # single round trip of bounded cost.
    dims = _ensure_list(dimensions) or EXECUTION_ANALYTICS_DEFAULT_DIMS
    dims = [d for d in dims if d in EXECUTION_ANALYTICS_DIMENSIONS][:6]
    if not dims:
        dims = EXECUTION_ANALYTICS_DEFAULT_DIMS

    empty = {
        "totals": {"lines": 0, "poids": 0, "duids": 0, "projects": 0, "value": 0.0,
                   "closed": 0, "open": 0},
        "buckets": [], "dimensions": [], "trend": [],
        "concentration": {"visits": [], "top_poids": [], "duids": [], "top_duids": []},
        "meta": {"date_basis": (pf.get("date_basis") or "plan"),
                 "closure": (pf.get("closure") or "all"),
                 "visits": "current",
                 "from_date": pf.get("from_date") or "", "to_date": pf.get("to_date") or "",
                 "available_dimensions": [
                     {"key": k, "label": v["label"]}
                     for k, v in EXECUTION_ANALYTICS_DIMENSIONS.items()],
                 "selected_dimensions": dims},
        "im": im_resolved,
    }
    if wheres is None:
        return empty

    where_sql = " AND ".join(wheres)

    # ── Tier A: totals + every attention bucket, in ONE statement ──────────
    bucket_keys = list(EXECUTION_ATTENTION_BUCKETS.keys())
    bucket_cols = ", ".join(
        f"SUM(CASE WHEN {execution_bucket_condition(k)} THEN 1 ELSE 0 END) AS `b_{k}`,"
        f" SUM(CASE WHEN {execution_bucket_condition(k)}"
        f" THEN IFNULL(pd.line_amount, 0) ELSE 0 END) AS `v_{k}`"
        for k in bucket_keys
    )
    closed_sql = _execution_closed_exists_sql()
    head = frappe.db.sql(
        f"""SELECT COUNT(*) AS lines_n,
                   COUNT(DISTINCT pd.name) AS poids,
                   COUNT(DISTINCT NULLIF(pd.site_code, '')) AS duids,
                   COUNT(DISTINCT NULLIF(pd.project_code, '')) AS projects,
                   SUM(IFNULL(pd.line_amount, 0)) AS value,
                   SUM(CASE WHEN {closed_sql} THEN 1 ELSE 0 END) AS closed_n,
                   {bucket_cols}
            {_EXEC_ANALYTICS_FROM}
            WHERE {where_sql}""",
        tuple(params), as_dict=True,
    ) or [{}]
    head = head[0] or {}
    total = cint(head.get("lines_n") or 0)
    closed_n = cint(head.get("closed_n") or 0)

    buckets = []
    for k in bucket_keys:
        spec = EXECUTION_ATTENTION_BUCKETS[k]
        buckets.append({
            "key": k, "label": spec["label"], "tone": spec.get("tone") or "info",
            "hint": spec.get("hint") or "", "value": cint(head.get(f"b_{k}") or 0),
            "amount": flt(head.get(f"v_{k}") or 0),
            "target": spec.get("target") or "plans",
        })

    # ── Tier B: one GROUP BY per selected dimension ────────────────────────
    out_dims = []
    for key in dims:
        spec = EXECUTION_ANALYTICS_DIMENSIONS[key]
        expr = spec["expr"]
        label_expr = spec.get("label_expr") or expr
        rows = frappe.db.sql(
            f"""SELECT {expr} AS k, MAX({label_expr}) AS label, COUNT(*) AS n,
                       COUNT(DISTINCT NULLIF(pd.site_code, '')) AS duids,
                       SUM(IFNULL(pd.line_amount, 0)) AS value
                {_EXEC_ANALYTICS_FROM}
                WHERE {where_sql}
                GROUP BY {expr} ORDER BY n DESC LIMIT 26""",
            tuple(params), as_dict=True,
        ) or []
        top = rows[:25]
        shown = sum(cint(r["n"]) for r in top)
        items = [{
            "key": (r["k"] or ""),
            "label": (r.get("label") or r["k"] or "") or spec["blank"],
            "n": cint(r["n"]), "duids": cint(r["duids"] or 0),
            "value": flt(r["value"] or 0),
            "pct": round(cint(r["n"]) * 100.0 / total, 1) if total else 0.0,
            "is_blank": not (r["k"] or ""),
        } for r in top]
        # Without the fold, the rows on screen would not add up to the total —
        # the same trap as a truncated table whose footer reads as the whole answer.
        if total > shown:
            items.append({"key": "__others__", "label": f"Others ({len(rows) - len(top)}+)",
                          "n": total - shown, "duids": 0, "value": 0.0,
                          "pct": round((total - shown) * 100.0 / total, 1) if total else 0.0,
                          "is_blank": False, "is_others": True})
        out_dims.append({"key": key, "label": spec["label"], "items": items,
                         "sums_to_total": True})

    # ── Tier C: monthly trend on the chosen date basis ─────────────────────
    basis_key = (pf.get("date_basis") or "plan").strip().lower()
    basis_expr = (_EXEC_DATE_BASES.get(basis_key) or _EXEC_DATE_BASES["plan"])["expr"]
    trend = frappe.db.sql(
        f"""SELECT DATE_FORMAT({basis_expr}, '%%Y-%%m') AS month, COUNT(*) AS lines_n,
                   COUNT(DISTINCT NULLIF(pd.site_code, '')) AS duids,
                   SUM(IFNULL(pd.line_amount, 0)) AS value,
                   SUM(CASE WHEN IFNULL(dex.any_im_done, 0) = 1 THEN 1 ELSE 0 END) AS im_confirmed,
                   SUM(CASE WHEN wdx.rollout_plan IS NOT NULL THEN 1 ELSE 0 END) AS work_done
            {_EXEC_ANALYTICS_FROM}
            WHERE {where_sql} AND {basis_expr} IS NOT NULL
            GROUP BY 1 ORDER BY 1""",
        tuple(params), as_dict=True,
    ) or []

    # ── Tier D: concentration — computed over ALL visits on purpose, because
    # "how many times has this POID been re-planned" is the question. ──────
    conc_wheres = [w for w in wheres if "rp_later" not in w]
    visit_rows = frappe.db.sql(
        f"""SELECT visits, COUNT(*) AS poids, SUM(visits) AS lines_n FROM (
              SELECT rp.po_dispatch, COUNT(*) AS visits
              {_EXEC_ANALYTICS_FROM}
              WHERE {' AND '.join(conc_wheres)} AND IFNULL(rp.po_dispatch, '') <> ''
              GROUP BY rp.po_dispatch
            ) x GROUP BY visits ORDER BY visits""",
        tuple(params), as_dict=True,
    ) or []
    top_poids = frappe.db.sql(
        f"""SELECT rp.po_dispatch, MAX(IFNULL(pd.poid, rp.po_dispatch)) AS poid,
                   MAX(IFNULL(pd.site_code, '')) AS duid,
                   MAX(IFNULL(pd.project_code, '')) AS project_code,
                   COUNT(*) AS visits
            {_EXEC_ANALYTICS_FROM}
            WHERE {' AND '.join(conc_wheres)} AND IFNULL(rp.po_dispatch, '') <> ''
            GROUP BY rp.po_dispatch HAVING visits > 1 ORDER BY visits DESC LIMIT 10""",
        tuple(params), as_dict=True,
    ) or []
    duid_rows = frappe.db.sql(
        f"""SELECT n, COUNT(*) AS duids FROM (
              SELECT pd.site_code, COUNT(*) AS n
              {_EXEC_ANALYTICS_FROM}
              WHERE {where_sql} AND IFNULL(pd.site_code, '') <> ''
              GROUP BY pd.site_code
            ) y GROUP BY n ORDER BY n DESC""",
        tuple(params), as_dict=True,
    ) or []
    top_duids = frappe.db.sql(
        f"""SELECT pd.site_code AS duid, MAX(IFNULL(pd.site_name, '')) AS site_name,
                   MAX(IFNULL(pd.project_code, '')) AS project_code,
                   COUNT(*) AS lines_n, COUNT(DISTINCT pd.name) AS poids
            {_EXEC_ANALYTICS_FROM}
            WHERE {where_sql} AND IFNULL(pd.site_code, '') <> ''
            GROUP BY pd.site_code HAVING lines_n > 1 ORDER BY lines_n DESC LIMIT 10""",
        tuple(params), as_dict=True,
    ) or []

    return {
        "totals": {
            "lines": total,
            "poids": cint(head.get("poids") or 0),
            "duids": cint(head.get("duids") or 0),
            "projects": cint(head.get("projects") or 0),
            "value": flt(head.get("value") or 0),
            "closed": closed_n,
            "open": total - closed_n,
        },
        "buckets": buckets,
        "dimensions": out_dims,
        "trend": [{"month": t["month"], "lines": cint(t["lines_n"]),
                   "duids": cint(t["duids"] or 0), "value": flt(t["value"] or 0),
                   "im_confirmed": cint(t["im_confirmed"] or 0),
                   "work_done": cint(t["work_done"] or 0)} for t in trend],
        "concentration": {
            "visits": [{"visits": cint(v["visits"]), "poids": cint(v["poids"]),
                        "lines": cint(v["lines_n"])} for v in visit_rows],
            "top_poids": top_poids,
            "duids": [{"lines": cint(d["n"]), "duids": cint(d["duids"])} for d in duid_rows],
            "top_duids": top_duids,
        },
        "meta": empty["meta"],
        "im": im_resolved,
    }


def fiscal_quarter_of(day):
    """Quarter containing `day`, aligned to the site's Fiscal Year.

    This bench's fiscal year runs 1 Apr - 31 Mar, so Apr-Jun is Q1 and Jul-Sep
    is Q2 — NOT the calendar Q3 a naive month/3 would give. Reading the start
    month off the Fiscal Year record means a site configured differently gets
    its own quarters without a code change.

    -> {"from", "to", "label"}
    """
    day = getdate(day)
    start_month = 1
    fy_name = ""
    try:
        rows = frappe.get_all(
            "Fiscal Year", filters={"disabled": 0}, fields=["name", "year_start_date"],
            order_by="year_start_date desc", limit=1, ignore_permissions=True,
        )
        if rows and rows[0].get("year_start_date"):
            start_month = getdate(rows[0]["year_start_date"]).month
            fy_name = rows[0].get("name") or ""
    except Exception:
        pass

    # Months since the fiscal year began, so quarter 1 starts at start_month.
    offset = (day.month - start_month) % 12
    q = offset // 3
    q_start_month = ((start_month - 1 + q * 3) % 12) + 1
    # The fiscal year begins in the calendar year before `day` when the quarter
    # has wrapped past December.
    year = day.year if day.month >= q_start_month else day.year - 1
    q_from = getdate(f"{year}-{q_start_month:02d}-01")
    end_month = ((q_start_month - 1 + 2) % 12) + 1
    end_year = year if end_month >= q_start_month else year + 1
    q_to = get_last_day(getdate(f"{end_year}-{end_month:02d}-01"))

    span = f"{q_from.strftime('%b')}–{q_to.strftime('%b %Y')}"
    label = f"Q{q + 1} {fy_name}" if fy_name else f"Q{q + 1} {q_from.year}"
    return {"from": str(q_from), "to": str(q_to), "label": label, "span": span}


@frappe.whitelist()
def get_rollout_fiscal_quarter(day=None):
    """Fiscal quarter bounds for a date — the weekly dashboard asks for the
    quarter its displayed week falls in."""
    return fiscal_quarter_of(day or nowdate())


@frappe.whitelist()
def get_rollout_commercial_summary(im=None, from_date=None, to_date=None, project_code=None, filter_im=None):
    """Money behind this IM's rollout plans over a date range.

    Every figure here is read off PO Dispatch for the lines that have a plan in
    the range — "planned value" is the value of what is scheduled, not a
    separate budget field, because there isn't one.

    Collected is the invoiced amount on milestones whose payment_received_date
    is set; a milestone invoiced but not yet paid falls into the pending slice.
    """
    scope_clause, scope_params, im_resolved = _rollout_scope_clause(im)
    empty = {
        "top": {k: 0.0 for k in ("planned", "invoiced", "collected", "pending", "not_invoiced")},
        "projects": [], "from_date": from_date, "to_date": to_date, "im": im_resolved,
    }
    if scope_clause is None:
        return empty

    wheres = [scope_clause, "IFNULL(pd.is_internal_work, 0) = 0"]
    params = list(scope_params)
    if from_date:
        wheres.append("rp.plan_date >= %s")
        params.append(from_date)
    if to_date:
        wheres.append("rp.plan_date <= %s")
        params.append(to_date)
    for col, val in (("pd.project_code", project_code), ("pd.im", filter_im)):
        c, p = _sql_in_or_eq(col, val)
        if c:
            wheres.append(c)
            params.extend(p)

    # DISTINCT on the dispatch: a line replanned across several visits must not
    # have its value counted once per visit.
    rows = frappe.db.sql(
        f"""
        SELECT pd.project_code,
               COUNT(*) AS line_count,
               COALESCE(SUM(pd.line_amount), 0) AS planned,
               COALESCE(SUM(IFNULL(pd.ms1_invoiced,0) + IFNULL(pd.ms2_invoiced,0)), 0) AS invoiced,
               COALESCE(SUM(
                 IF(pd.ms1_payment_received_date IS NOT NULL, IFNULL(pd.ms1_invoiced,0), 0)
                 + IF(pd.ms2_payment_received_date IS NOT NULL, IFNULL(pd.ms2_invoiced,0), 0)
               ), 0) AS collected
        FROM (
          SELECT DISTINCT rp.po_dispatch
          FROM `tabRollout Plan` rp
          INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
          WHERE {" AND ".join(wheres)}
        ) planned_lines
        INNER JOIN `tabPO Dispatch` pd ON pd.name = planned_lines.po_dispatch
        GROUP BY pd.project_code
        ORDER BY planned DESC
        """,
        tuple(params),
        as_dict=True,
    ) or []

    top = {
        "planned": sum(flt(r["planned"]) for r in rows),
        "invoiced": sum(flt(r["invoiced"]) for r in rows),
        "collected": sum(flt(r["collected"]) for r in rows),
        "lines": sum(cint(r["line_count"]) for r in rows),
    }
    # The three slices of the breakdown donut, and they add to planned by
    # construction rather than by three separate queries agreeing.
    top["pending"] = max(top["invoiced"] - top["collected"], 0.0)
    top["not_invoiced"] = max(top["planned"] - top["invoiced"], 0.0)

    return {
        "top": top,
        "projects": [
            {"project_code": r["project_code"] or "—", "lines": cint(r["line_count"]),
             "planned": flt(r["planned"]), "invoiced": flt(r["invoiced"]),
             "collected": flt(r["collected"])}
            for r in rows
        ],
        "from_date": from_date, "to_date": to_date, "im": im_resolved,
    }


@frappe.whitelist()
def list_im_rollout_plans(im=None, plan_status=None, limit=500, portal_filters=None, _options=None, _summary=None):
    """Rollout plans for this IM (join PO Dispatch — works before im backfill on Rollout Plan)."""
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    if not im_identifiers:
        return []
    pf = _portal_filters_dict(portal_filters)
    ph = ", ".join(["%s"] * len(im_identifiers))
    params = list(im_identifiers)
    status_clause = ""
    status_vals = _ensure_list(plan_status)
    if status_vals:
        if len(status_vals) == 1:
            status_clause = " AND rp.plan_status = %s"
            params.append(status_vals[0])
        else:
            status_clause = " AND rp.plan_status IN ({})".format(", ".join(["%s"] * len(status_vals)))
            params.extend(status_vals)
    portal_clause = ""
    for col, key in (("rp.visit_type", "visit_type"),
                     ("IFNULL(pd.project_code,'')", "project_code"),
                     ("IFNULL(pd.site_code,'')", "site_code"),
                     ("IFNULL(rp.team,'')", "team")):
        c, p = _sql_in_or_eq(col, pf.get(key))
        if c:
            portal_clause += f" AND {c}"
            params.extend(p)
    if pf.get("from_date") and pf.get("to_date"):
        portal_clause += " AND rp.plan_date BETWEEN %s AND %s"
        params.extend([pf["from_date"], pf["to_date"]])
    elif pf.get("from_date"):
        portal_clause += " AND rp.plan_date >= %s"
        params.append(pf["from_date"])
    elif pf.get("to_date"):
        portal_clause += " AND rp.plan_date <= %s"
        params.append(pf["to_date"])
    # "Dummy PO" toggle — a dedicated toolbar filter (previously applied only
    # to already-loaded rows client-side). Matches list_po_dispatches' own
    # dummy_preset convention: "dummy" = open dummy POs only.
    if (pf.get("dummy_preset") or "").strip().lower() == "dummy":
        portal_clause += " AND IFNULL(pd.is_dummy_po, 0) = 1"

    # Drill-through from Execution Analytics. Same predicate registry the tile
    # counted with, so the number and the list it opens agree. All three
    # default to NO filtering — this page has never hidden closed or
    # superseded plans, and that stays true for every ordinary call.
    bucket_join = ""
    _bucket = (pf.get("bucket") or "").strip()
    if _bucket:
        bucket_join = (
            f" LEFT JOIN ({_DEX_SQL}) dex ON dex.rollout_plan = rp.name"
            f" LEFT JOIN ({_WDX_SQL}) wdx ON wdx.rollout_plan = rp.name "
        )
        portal_clause += " AND " + execution_bucket_condition(_bucket)
        # Match the analytics base exactly: current visit only, and no
        # internal work that is already finished.
        portal_clause += " AND NOT " + _execution_superseded_exists_sql()
        portal_clause += (
            " AND NOT (IFNULL(pd.is_internal_work, 0) = 1"
            " AND IFNULL(dex.any_im_done, 0) = 1)"
        )
    _closure = (pf.get("closure") or "all").strip().lower()
    if _closure in ("open", "closed"):
        portal_clause += " AND " + ("NOT " if _closure == "open" else "") + _execution_closed_exists_sql()
    if (pf.get("visits") or "all").strip().lower() == "current":
        portal_clause += " AND NOT " + _execution_superseded_exists_sql()

    rp_im_join = ""
    im_full_sql = "im_pd.full_name AS im_full_name"
    if frappe.db.has_column("Rollout Plan", "im"):
        rp_im_join = "LEFT JOIN `tabIM Master` im_rp ON im_rp.name = rp.im"
        im_full_sql = "COALESCE(im_rp.full_name, im_pd.full_name) AS im_full_name"

    # Per-column "Manage Table" filters: each column is matched independently
    # against its own SQL expression (plain substring LIKE, same semantics the
    # old client-side filter used) and ANDed together — not blended into the
    # wide multi-column `search` clause below, which searched every column at
    # once and produced false/missing matches when more than one column filter
    # (or a filter plus the top search box) was active together. These same
    # expressions are also reused below to widen the general/top search box so
    # it covers the same columns a per-column filter can reach (e.g. item
    # description), instead of the two search paths covering different fields.
    _desc_expr_rp = (
        "CASE WHEN IFNULL(pd.is_dummy_po,0) = 1 AND IFNULL(pd.item_description,'') = '' "
        "THEN IFNULL(pd.manager_remark,'') ELSE IFNULL(pd.item_description,'') END"
        if frappe.db.has_column("PO Dispatch", "is_dummy_po") and frappe.db.has_column("PO Dispatch", "manager_remark")
        else "IFNULL(pd.item_description,'')"
    )
    col_filter_map = {
        "plan_id": "rp.name",
        "poid": "COALESCE(NULLIF(pd.poid,''), pd.name)",
        "description": _desc_expr_rp,
        "duid": "IFNULL(pd.site_code,'')",
        "po": "IFNULL(pd.po_no,'')",
        "team": "IFNULL(it.team_name,'')",
        "im": im_full_sql.split(" AS ")[0],
        "plan_date": "CAST(rp.plan_date AS CHAR)",
        "end_date": "CAST(rp.plan_end_date AS CHAR)",
        "visit": "IFNULL(rp.visit_type,'')",
        "visit_no": "CAST(rp.visit_number AS CHAR)",
        "status": "IFNULL(rp.plan_status,'')",
        "target_sar": "CAST(rp.target_amount AS CHAR)",
        "cancel": "IFNULL(rp.cancel_request_status,'')",
        "domain": "COALESCE(NULLIF(pd.project_domain,''), pcc_rp.project_domain, '')",
        "huawei_im": "COALESCE(NULLIF(pd.huawei_im,''), pcc_rp.huawei_im, '')",
    }
    if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
        col_filter_map["dummy_poid"] = "IFNULL(pd.original_dummy_poid,'')"
    if frappe.db.has_column("PO Dispatch", "center_area"):
        col_filter_map["center_area"] = "IFNULL(pd.center_area,'')"
    if frappe.db.has_column("Rollout Plan", "region_type"):
        col_filter_map["region"] = "IFNULL(rp.region_type,'')"
    if frappe.db.has_column("PO Dispatch", "general_remark"):
        col_filter_map["general"] = "IFNULL(pd.general_remark,'')"
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        col_filter_map["manager"] = "IFNULL(pd.manager_remark,'')"
    if frappe.db.has_column("PO Dispatch", "team_lead_remark"):
        col_filter_map["team_lead"] = "IFNULL(pd.team_lead_remark,'')"
    col_filter_map["activity_type"] = (
        "IFNULL((SELECT activity_type FROM `tabItem` WHERE name = pd.item_code), '')"
    )
    if frappe.db.has_column("Rollout Plan", "access_time"):
        col_filter_map["access_time"] = "IFNULL(CAST(rp.access_time AS CHAR), '')"
    # Not backend-filterable here: "access" is a computed badge —
    # it doesn't map to a single SQL expression. Left client-side only, same
    # as before this change (no regression, just not yet full-dataset).
    column_filters = pf.get("column_filters")
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map.get(col_key), raw_val)
                if _c:
                    portal_clause += f" AND {_c}"
                    params.extend(_p)
                continue
            expr = col_filter_map.get(col_key)
            if not expr:
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            portal_clause += f" AND {expr} LIKE %s"
            params.append(pat)

    like_pat = _sql_like_pattern(pf.get("search") or pf.get("q") or "")
    if like_pat:
        concat_parts = [
            "IFNULL(rp.name,'')",
            "IFNULL(rp.po_dispatch,'')",
            "COALESCE(NULLIF(pd.poid,''), pd.name, '')",
            "CAST(rp.plan_date AS CHAR)",
            "IFNULL(rp.visit_type,'')",
            "IFNULL(rp.team,'')",
            "IFNULL(it.team_name,'')",
            "IFNULL(pd.po_no,'')",
            "IFNULL(pd.project_code,'')",
            "IFNULL(pd.site_code,'')",
            "IFNULL(pd.item_code,'')",
            "IFNULL(pd.im,'')",
            "IFNULL(im_pd.full_name,'')",
        ]
        if frappe.db.has_column("Rollout Plan", "im"):
            concat_parts.append("IFNULL(im_rp.full_name,'')")
        # Widen with every backend-filterable column's expression too, so the
        # top search box can find the same things a per-column filter can
        # (e.g. item description, remarks) instead of covering fewer fields.
        seen_parts = set(concat_parts)
        for expr in col_filter_map.values():
            if expr not in seen_parts:
                concat_parts.append(expr)
                seen_parts.add(expr)
        concat_expr = "CONCAT_WS(' ', " + ", ".join(concat_parts) + ")"
        clause, cparams = _sql_search_clause(
            concat_expr, pf.get("search") or pf.get("q") or "",
            exact_cols=["COALESCE(NULLIF(pd.poid,''), pd.name)", "IFNULL(pd.site_code,'')"],
        )
        if clause:
            portal_clause += f" AND {clause}"
            params.extend(cparams)
    im_plan_extras = []
    if frappe.db.has_column("Rollout Plan", "region_type"):
        im_plan_extras.append("rp.region_type AS region_type")
    else:
        im_plan_extras.append("NULL AS region_type")
    if frappe.db.has_column("PO Dispatch", "center_area"):
        im_plan_extras.append("pd.center_area AS center_area")
    else:
        im_plan_extras.append("NULL AS center_area")
    if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
        im_plan_extras.append("pd.original_dummy_poid AS original_dummy_poid")
    else:
        im_plan_extras.append("NULL AS original_dummy_poid")
    if frappe.db.has_column("PO Dispatch", "is_internal_work"):
        im_plan_extras.append("pd.is_internal_work AS is_internal_work")
        im_plan_extras.append("pd.internal_work_type AS internal_work_type")
        im_plan_extras.append("pd.internal_domain AS internal_domain")
    else:
        im_plan_extras.append("0 AS is_internal_work")
        im_plan_extras.append("NULL AS internal_work_type")
        im_plan_extras.append("NULL AS internal_domain")
    im_plan_extra_sql = ", " + ", ".join(im_plan_extras)
    lim_rp = _portal_row_limit(limit, 500)
    if _options:
        _e = col_filter_map.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabRollout Plan` rp "
            "INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
            "LEFT JOIN `tabINET Team` it ON it.name = rp.team "
            "LEFT JOIN `tabProject Control Center` pcc_rp ON pcc_rp.name = pd.project_code "
            f"{rp_im_join} "
            "LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im"
            f"{bucket_join}",
            f"pd.im IN ({ph}){status_clause}{portal_clause}", params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # The IM's question is scheduling: what have I got out there, what is
        # late, and how much of it is still unassigned to a team.
        _ps = "IFNULL(rp.plan_status,'')"
        return summary_from_query(
            "`tabRollout Plan` rp "
            "INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
            "LEFT JOIN `tabINET Team` it ON it.name = rp.team "
            "LEFT JOIN `tabProject Control Center` pcc_rp ON pcc_rp.name = pd.project_code "
            f"{rp_im_join} "
            "LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im"
            f"{bucket_join}",
            f"pd.im IN ({ph}){status_clause}{portal_clause}", params, [
                {"key": "plans", "label": "Plans", "agg": "count"},
                {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pd.site_code,''), '')"},
                {"key": "value", "label": "Value", "agg": "sum",
                 "expr": "IFNULL(pd.line_amount, 0)", "format": "money", "tone": "good"},
                {"key": "running", "label": "Running", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} IN ('In Execution','Extended')", "tone": "info", "hide_if_zero": True},
                {"key": "completed", "label": "Completed", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Completed'", "tone": "good", "hide_if_zero": True},
                {"key": "overdue", "label": "Overdue", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Overdue'", "tone": "bad", "hide_if_zero": True},
                {"key": "issue", "label": "With issue", "agg": "count_if", "group": "Progress",
                 "cond": f"{_ps} = 'Planning with Issue'", "tone": "warn", "hide_if_zero": True},
                {"key": "no_team", "label": "No team", "agg": "count_if",
                 "cond": "IFNULL(rp.team,'') = ''", "tone": "warn", "hide_if_zero": True,
                 "hint": "Planned but no field team assigned yet"},
            ])

    rows = frappe.db.sql(
        f"""
        SELECT rp.name, rp.modified, rp.po_dispatch AS system_id, rp.po_dispatch,
               COALESCE(NULLIF(pd.poid, ''), pd.name) AS poid,
               rp.team, rp.plan_date, rp.plan_end_date, rp.visit_type,
               rp.visit_number, rp.visit_multiplier, rp.target_amount, rp.achieved_amount,
               rp.completion_pct, rp.plan_status,
               rp.cancel_request_status, rp.cancel_reason,
               rp.cancel_requested_at, rp.cancel_responded_at, rp.cancel_pm_remark,
               IFNULL(rp.reschedule_count, 0) AS reschedule_count,
               rp.access_time, rp.access_period,
               rp.plan_documents,
               (SELECT MIN(etl.start_time) FROM `tabExecution Time Log` etl
                INNER JOIN `tabRollout Plan` rp2 ON rp2.name = etl.rollout_plan
                INNER JOIN `tabPO Dispatch` pd2 ON pd2.name = rp2.po_dispatch
                WHERE pd2.site_code = pd.site_code AND DATE(etl.start_time) = CURDATE()
               ) AS timer_start,
               pd.qty AS qty,
               pd.im AS dispatch_im, pd.site_code, pd.po_no, pd.project_code, pd.item_code,
               pd.customer AS customer, pd.item_description, pd.is_dummy_po,
               pd.huawei_im,
               {_remark_select()},
               it.team_name AS team_name,
               {im_full_sql}
               {im_plan_extra_sql}
        FROM `tabRollout Plan` rp
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabINET Team` it ON it.name = rp.team
        LEFT JOIN `tabProject Control Center` pcc_rp ON pcc_rp.name = pd.project_code
        {rp_im_join}
        LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im
        {bucket_join}
        WHERE pd.im IN ({ph}){status_clause}{portal_clause}
        ORDER BY rp.plan_date DESC, rp.creation DESC
        {_sql_limit_suffix(lim_rp)}
        """,
        tuple(params),
        as_dict=True,
    )
    if rows:
        act_map = _batch_item_activity_types(rows)
        for r in rows:
            r["activity_type"] = act_map.get(r.get("item_code") or "")
            r["timer_start_ms"] = _frappe_dt_to_epoch_ms(r.get("timer_start"))
        _enrich_with_project_fields(rows)
        _apply_dummy_description(rows)
    return rows or []


@frappe.whitelist()
def list_im_daily_executions(im=None, execution_status=None, limit=500, portal_filters=None, _options=None, _summary=None):
    """Daily executions for this IM's dispatches."""
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    if not im_identifiers:
        return []
    pf = _portal_filters_dict(portal_filters)
    ph = ", ".join(["%s"] * len(im_identifiers))
    params = list(im_identifiers)
    status_clause = ""
    status_vals = _ensure_list(execution_status)
    if status_vals:
        norm_vals = [_normalize_execution_status(s) for s in status_vals]
        if len(norm_vals) == 1:
            status_clause = " AND de.execution_status = %s"
            params.append(norm_vals[0])
        else:
            status_clause = " AND de.execution_status IN ({})".format(", ".join(["%s"] * len(norm_vals)))
            params.extend(norm_vals)
    portal_clause = ""
    for col, key in (("IFNULL(de.qc_status,'')", "qc_status"),
                     ("IFNULL(pd.project_code,'')", "project_code"),
                     ("IFNULL(pd.site_code,'')", "site_code"),
                     ("IFNULL(de.team,'')", "team")):
        c, p = _sql_in_or_eq(col, pf.get(key))
        if c:
            portal_clause += f" AND {c}"
            params.extend(p)
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        c, p = _sql_in_or_eq("IFNULL(de.ciag_status,'')", pf.get("ciag_status"))
        if c:
            portal_clause += f" AND {c}"
            params.extend(p)
    if pf.get("from_date") and pf.get("to_date"):
        portal_clause += " AND de.execution_date BETWEEN %s AND %s"
        params.extend([pf["from_date"], pf["to_date"]])
    elif pf.get("from_date"):
        portal_clause += " AND de.execution_date >= %s"
        params.append(pf["from_date"])
    elif pf.get("to_date"):
        portal_clause += " AND de.execution_date <= %s"
        params.append(pf["to_date"])
    # "Dummy PO" toggle — a dedicated toolbar filter (previously applied only
    # to already-loaded rows client-side). Matches list_po_dispatches' own
    # dummy_preset convention: "dummy" = open dummy POs only.
    if (pf.get("dummy_preset") or "").strip().lower() == "dummy":
        portal_clause += " AND IFNULL(pd.is_dummy_po, 0) = 1"

    # Drill-through from Execution Analytics, on the same registry the tile
    # counted with. NOTE the grain: the tile counts Rollout PLANS, this list
    # is one row per Daily Execution, so a multi-team plan contributes several
    # rows. The rows are the right rows; the count is legitimately larger, and
    # the page says so rather than pretending otherwise.
    future_planned_clause = "AND NOT (rp.plan_status = 'Planned' AND rp.plan_date > CURDATE())"
    extended_clause = "AND rp.plan_status != 'Extended'"
    issue_block_clause = (
        "AND NOT ("
        " IFNULL(rp.issue_status,'') = 'Reported'"
        " OR (IFNULL(rp.issue_status,'') = '' AND rp.plan_status = 'Planning with Issue'))"
    )
    bucket_join_ex = ""
    _bucket_ex = (pf.get("bucket") or "").strip()
    if _bucket_ex:
        bucket_join_ex = (
            f" LEFT JOIN ({_DEX_SQL}) dex ON dex.rollout_plan = rp.name"
            f" LEFT JOIN ({_WDX_SQL}) wdx ON wdx.rollout_plan = rp.name "
        )
        portal_clause += " AND " + execution_bucket_condition(_bucket_ex)
        # Match the analytics base exactly: current visit only, and no
        # internal work that is already finished.
        portal_clause += " AND NOT " + _execution_superseded_exists_sql()
        portal_clause += (
            " AND NOT (IFNULL(pd.is_internal_work, 0) = 1"
            " AND IFNULL(dex.any_im_done, 0) = 1)"
        )
        future_planned_clause = ""
        extended_clause = ""
        issue_block_clause = ""
    _closure_ex = (pf.get("closure") or "all").strip().lower()
    if _closure_ex in ("open", "closed"):
        portal_clause += " AND " + ("NOT " if _closure_ex == "open" else "") + _execution_closed_exists_sql()
    if (pf.get("visits") or "all").strip().lower() == "current":
        portal_clause += " AND NOT " + _execution_superseded_exists_sql()

    # The "Internal Work Done" sub-table (client-side split of this same
    # fetch by is_internal_work=1) has its own dedicated team/domain/type/date
    # filters — previously applied only to the already-loaded rows. Each
    # condition is OR'd with "not an internal-work row" so it only narrows
    # the internal subset, leaving the main table's rows untouched.
    if frappe.db.has_column("PO Dispatch", "is_internal_work"):
        internal_team_vals = _ensure_list(pf.get("internal_team"))
        if internal_team_vals:
            ph_it = ", ".join(["%s"] * len(internal_team_vals))
            portal_clause += f" AND (IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(de.team,'') IN ({ph_it}))"
            params.extend(internal_team_vals)
        if frappe.db.has_column("PO Dispatch", "internal_domain"):
            internal_domain_vals = _ensure_list(pf.get("internal_domain"))
            if internal_domain_vals:
                ph_id = ", ".join(["%s"] * len(internal_domain_vals))
                portal_clause += f" AND (IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(pd.internal_domain,'') IN ({ph_id}))"
                params.extend(internal_domain_vals)
        if frappe.db.has_column("PO Dispatch", "internal_work_type"):
            internal_type_vals = _ensure_list(pf.get("internal_work_type"))
            if internal_type_vals:
                ph_ty = ", ".join(["%s"] * len(internal_type_vals))
                portal_clause += f" AND (IFNULL(pd.is_internal_work,0) = 0 OR IFNULL(pd.internal_work_type,'') IN ({ph_ty}))"
                params.extend(internal_type_vals)
        if pf.get("internal_from_date"):
            portal_clause += " AND (IFNULL(pd.is_internal_work,0) = 0 OR de.execution_date >= %s)"
            params.append(pf["internal_from_date"])
        if pf.get("internal_to_date"):
            portal_clause += " AND (IFNULL(pd.is_internal_work,0) = 0 OR de.execution_date <= %s)"
            params.append(pf["internal_to_date"])

        # "tab" - which subset of this shared main+internal-done fetch to
        # return. Mirrors the frontend's own client-side split in
        # IMExecution.jsx (filteredExecutions / internalDoneExecutions):
        # "internal_done" = is_internal_work AND execution_status Completed;
        # "main" (default) = everything else. Without this, one row-limited
        # fetch served both tabs, so whichever tab wasn't the majority of
        # that batch lost rows beyond the limit.
        tab_scope_ex = (pf.get("tab") or "main").strip().lower()
        if tab_scope_ex == "internal_done":
            portal_clause += " AND IFNULL(pd.is_internal_work,0) = 1 AND de.execution_status = 'Completed'"
        elif tab_scope_ex == "main":
            portal_clause += " AND NOT (IFNULL(pd.is_internal_work,0) = 1 AND de.execution_status = 'Completed')"

    # Hide a DE once the IM has nothing left to do with it. Two rules (OR):
    # 1. Lead-DE rule: this DE's own QC/CIAG is done AND a WD exists for the plan.
    # 2. Companion-DE rule (multi-team): WD was created through a *different* DE in the
    #    same plan — this DE is a secondary team row and the plan is already closed.
    ciag_col_hide = "de.ciag_status" if frappe.db.has_column("Daily Execution", "ciag_status") else "''"
    qc_req_col2 = "rp.qc_required" if frappe.db.has_column("Rollout Plan", "qc_required") else "1"
    ciag_req_col2 = "rp.ciag_required" if frappe.db.has_column("Rollout Plan", "ciag_required") else "1"
    portal_clause += "" if _bucket_ex else (
        " AND NOT ("
        " de.execution_status = 'Completed'"
        " AND ("
        # Rule 1: lead DE — own QC/CIAG complete + any WD exists for this plan
        "   ("
        f"    ({qc_req_col2} = 0 OR IFNULL(de.qc_status,'') IN ('Pass', 'Not Applicable'))"
        f"    AND ({ciag_req_col2} = 0 OR IFNULL({ciag_col_hide},'') IN ('Approved', 'Not Applicable'))"
        "    AND EXISTS ("
        "      SELECT 1 FROM `tabWork Done` wd0"
        "      INNER JOIN `tabDaily Execution` de_wd0 ON de_wd0.name = wd0.execution"
        "      WHERE de_wd0.rollout_plan = de.rollout_plan"
        "    )"
        "   )"
        "   OR"
        # Rule 2: companion DE — WD was created through a DIFFERENT DE in the same plan
        "   EXISTS ("
        "     SELECT 1 FROM `tabWork Done` wd1"
        "     INNER JOIN `tabDaily Execution` de_wd1 ON de_wd1.name = wd1.execution"
        "     WHERE de_wd1.rollout_plan = de.rollout_plan"
        "     AND de_wd1.name != de.name"
        "   )"
        " )"
        ")"
    )

    rp_im_join_ex = ""
    im_full_sql_ex = "im_pd.full_name AS im_full_name"
    if frappe.db.has_column("Rollout Plan", "im"):
        rp_im_join_ex = "LEFT JOIN `tabIM Master` im_rp ON im_rp.name = rp.im"
        im_full_sql_ex = "COALESCE(im_rp.full_name, im_pd.full_name) AS im_full_name"

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale (each column matched independently and ANDed, not blended
    # into the wide `search` clause; same expressions widen that search too).
    _desc_expr_ex = (
        "CASE WHEN IFNULL(pd.is_dummy_po,0) = 1 AND IFNULL(pd.item_description,'') = '' "
        "THEN IFNULL(pd.manager_remark,'') ELSE IFNULL(pd.item_description,'') END"
        if frappe.db.has_column("PO Dispatch", "is_dummy_po") and frappe.db.has_column("PO Dispatch", "manager_remark")
        else "IFNULL(pd.item_description,'')"
    )
    col_filter_map = {
        "execution": "IFNULL(de.name,'')",
        "rollout_plan": "IFNULL(de.rollout_plan,'')",
        "poid": "COALESCE(NULLIF(pd.poid,''), pd.name)",
        "item": "IFNULL(pd.item_code,'')",
        "item_code": "IFNULL(pd.item_code,'')",
        "description": _desc_expr_ex,
        "project": "IFNULL(pd.project_code,'')",
        "duid": "IFNULL(pd.site_code,'')",
        "po": "IFNULL(pd.po_no,'')",
        "team": "IFNULL(it.team_name,'')",
        "im": im_full_sql_ex.split(" AS ")[0],
        "plan_period": "CONCAT_WS(' ', CAST(rp.plan_date AS CHAR), CAST(rp.plan_end_date AS CHAR))",
        "exec_date": "CAST(de.execution_date AS CHAR)",
        "tl_status": "IFNULL(de.tl_status,'')",
        "execution_status": "IFNULL(de.execution_status,'')",
        "issue_category": "IFNULL(de.issue_category,'')",
        "qc": "IFNULL(de.qc_status,'')",
        "qty": "CAST(de.achieved_qty AS CHAR)",
        "visit": "CAST(rp.visit_number AS CHAR)",
        "domain": "COALESCE(NULLIF(pd.project_domain,''), pcc_ex.project_domain, '')",
        "huawei_im": "COALESCE(NULLIF(pd.huawei_im,''), pcc_ex.huawei_im, '')",
    }
    if frappe.db.has_column("Daily Execution", "ciag_status"):
        col_filter_map["ciag"] = "IFNULL(de.ciag_status,'')"
    if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
        col_filter_map["dummy_poid"] = "IFNULL(pd.original_dummy_poid,'')"
    if frappe.db.has_column("PO Dispatch", "center_area"):
        col_filter_map["center_area"] = "IFNULL(pd.center_area,'')"
    if frappe.db.has_column("Daily Execution", "region_type"):
        col_filter_map["region"] = "IFNULL(de.region_type,'')"
    if frappe.db.has_column("PO Dispatch", "general_remark"):
        col_filter_map["general"] = "IFNULL(pd.general_remark,'')"
    if frappe.db.has_column("PO Dispatch", "manager_remark"):
        col_filter_map["manager"] = "IFNULL(pd.manager_remark,'')"
        col_filter_map["im_note"] = "IFNULL(pd.manager_remark,'')"
    if frappe.db.has_column("PO Dispatch", "team_lead_remark"):
        col_filter_map["team_lead"] = "IFNULL(pd.team_lead_remark,'')"
        col_filter_map["tl_remark"] = "IFNULL(pd.team_lead_remark,'')"
    if frappe.db.has_column("PO Dispatch", "internal_work_type"):
        col_filter_map["type"] = "IFNULL(pd.internal_work_type,'')"
    col_filter_map["activity_type"] = (
        "IFNULL((SELECT activity_type FROM `tabItem` WHERE name = pd.item_code), '')"
    )
    if frappe.db.has_column("Rollout Plan", "access_time"):
        col_filter_map["access_time"] = "IFNULL(CAST(rp.access_time AS CHAR), '')"
    # Not backend-filterable: "access" is a computed badge. Client-side only.
    column_filters = pf.get("column_filters")
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map.get(col_key), raw_val)
                if _c:
                    portal_clause += f" AND {_c}"
                    params.extend(_p)
                continue
            expr = col_filter_map.get(col_key)
            if not expr:
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            portal_clause += f" AND {expr} LIKE %s"
            params.append(pat)

    like_pat = _sql_like_pattern(pf.get("search") or pf.get("q") or "")
    if like_pat:
        concat_parts = [
            "IFNULL(de.name,'')",
            "IFNULL(de.rollout_plan,'')",
            "CAST(de.execution_date AS CHAR)",
            "IFNULL(de.team,'')",
            "IFNULL(it.team_name,'')",
            "IFNULL(de.execution_status,'')",
            "IFNULL(de.qc_status,'')",
            "COALESCE(NULLIF(pd.poid,''), pd.name, '')",
            "IFNULL(pd.po_no,'')",
            "IFNULL(pd.project_code,'')",
            "IFNULL(pd.site_code,'')",
            "IFNULL(pd.site_name,'')",
            "IFNULL(pd.item_code,'')",
            "IFNULL(pd.item_description,'')",
            "IFNULL(pd.im,'')",
            "IFNULL(im_pd.full_name,'')",
        ]
        if frappe.db.has_column("Daily Execution", "ciag_status"):
            concat_parts.append("IFNULL(de.ciag_status,'')")
        if frappe.db.has_column("Rollout Plan", "im"):
            concat_parts.append("IFNULL(im_rp.full_name,'')")
        seen_parts = set(concat_parts)
        for expr in col_filter_map.values():
            if expr not in seen_parts:
                concat_parts.append(expr)
                seen_parts.add(expr)
        concat_expr = "CONCAT_WS(' ', " + ", ".join(concat_parts) + ")"
        clause, cparams = _sql_search_clause(
            concat_expr, pf.get("search") or pf.get("q") or "",
            exact_cols=["COALESCE(NULLIF(pd.poid,''), pd.name)", "IFNULL(pd.site_code,'')"],
        )
        if clause:
            portal_clause += f" AND {clause}"
            params.extend(cparams)
    ciag_sel = "de.ciag_status" if frappe.db.has_column("Daily Execution", "ciag_status") else "NULL"
    im_ex_extras = []
    if frappe.db.has_column("Daily Execution", "region_type"):
        im_ex_extras.append("de.region_type AS region_type")
    else:
        im_ex_extras.append("NULL AS region_type")
    if frappe.db.has_column("PO Dispatch", "center_area"):
        im_ex_extras.append("pd.center_area AS center_area")
    else:
        im_ex_extras.append("NULL AS center_area")
    if frappe.db.has_column("PO Dispatch", "original_dummy_poid"):
        im_ex_extras.append("pd.original_dummy_poid AS original_dummy_poid")
    else:
        im_ex_extras.append("NULL AS original_dummy_poid")
    if frappe.db.has_column("PO Dispatch", "is_internal_work"):
        im_ex_extras.append("pd.is_internal_work AS is_internal_work")
        im_ex_extras.append("pd.internal_work_type AS internal_work_type")
        im_ex_extras.append("pd.internal_domain AS internal_domain")
    else:
        im_ex_extras.append("0 AS is_internal_work")
        im_ex_extras.append("NULL AS internal_work_type")
        im_ex_extras.append("NULL AS internal_domain")
    im_ex_extra_sql = ", " + ", ".join(im_ex_extras)
    qc_req_sel = "rp.qc_required" if frappe.db.has_column("Rollout Plan", "qc_required") else "1"
    ciag_req_sel = "rp.ciag_required" if frappe.db.has_column("Rollout Plan", "ciag_required") else "1"
    access_time_sel = "rp.access_time" if frappe.db.has_column("Rollout Plan", "access_time") else "NULL"
    access_period_sel = "rp.access_period" if frappe.db.has_column("Rollout Plan", "access_period") else "NULL"
    lim_de = _portal_row_limit(limit, 500)
    if _options:
        _e = col_filter_map.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabDaily Execution` de "
            "INNER JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan "
            "INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
            "LEFT JOIN `tabINET Team` it ON it.name = de.team "
            "LEFT JOIN `tabProject Control Center` pcc_ex ON pcc_ex.name = pd.project_code "
            f"{rp_im_join_ex} "
            "LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im"
            f"{bucket_join_ex}",
            f"pd.im IN ({ph}){status_clause}{portal_clause}", params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # Day-to-day execution: what is in progress right now, what completed,
        # and what is parked (hold / cancelled).
        _es = "IFNULL(de.execution_status,'')"
        return summary_from_query(
            "`tabDaily Execution` de "
            "INNER JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan "
            "INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
            "LEFT JOIN `tabINET Team` it ON it.name = de.team "
            "LEFT JOIN `tabProject Control Center` pcc_ex ON pcc_ex.name = pd.project_code "
            f"{rp_im_join_ex} "
            "LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im"
            f"{bucket_join_ex}",
            f"pd.im IN ({ph}){status_clause}{portal_clause}", params, [
                {"key": "executions", "label": "Executions", "agg": "count"},
                {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pd.site_code,''), '')"},
                {"key": "teams", "label": "Teams", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(de.team,''), '')"},
                {"key": "in_progress", "label": "In progress", "agg": "count_if", "group": "Status",
                 "cond": f"{_es} = 'In Progress'", "tone": "info", "hide_if_zero": True},
                {"key": "completed", "label": "Completed", "agg": "count_if", "group": "Status",
                 "cond": f"{_es} = 'Completed'", "tone": "good", "hide_if_zero": True},
                {"key": "hold", "label": "On hold", "agg": "count_if", "group": "Status",
                 "cond": f"{_es} = 'Hold'", "tone": "warn", "hide_if_zero": True},
                {"key": "cancelled", "label": "Cancelled", "agg": "count_if", "group": "Status",
                 "cond": f"{_es} = 'Cancelled'", "tone": "bad", "hide_if_zero": True},
            ])

    rows = frappe.db.sql(
        f"""
        SELECT de.name, de.modified, rp.po_dispatch AS system_id, de.rollout_plan,
               COALESCE(NULLIF(pd.poid, ''), pd.name) AS poid,
               rp.visit_number, rp.visit_type, rp.plan_date, rp.plan_end_date, rp.plan_status AS plan_status,
               IFNULL(rp.reschedule_count, 0) AS reschedule_count,
               (SELECT MIN(etl.start_time) FROM `tabExecution Time Log` etl
                INNER JOIN `tabRollout Plan` rp2 ON rp2.name = etl.rollout_plan
                INNER JOIN `tabPO Dispatch` pd2 ON pd2.name = rp2.po_dispatch
                WHERE pd2.site_code = pd.site_code AND DATE(etl.start_time) = CURDATE()
               ) AS timer_start,
               de.team, de.execution_date,
               de.execution_status, de.tl_status, de.issue_category,
               de.achieved_qty, de.achieved_amount, de.gps_location,
               de.qc_status, {ciag_sel} AS ciag_status, de.revisit_flag, de.photos,
               {qc_req_sel} AS qc_required,
               {ciag_req_sel} AS ciag_required,
               {access_time_sel} AS access_time,
               {access_period_sel} AS access_period,
               pd.im AS dispatch_im, pd.huawei_im, pd.site_code, pd.site_name, pd.po_no, pd.project_code, pd.item_code, pd.item_description,
               pd.is_dummy_po,
               pd.customer AS customer,
               {_remark_select()},
               (
                 SELECT wd.name FROM `tabWork Done` wd
                 INNER JOIN `tabDaily Execution` de_wd ON de_wd.name = wd.execution
                 WHERE de_wd.rollout_plan = de.rollout_plan
                 LIMIT 1
               ) AS work_done,
               it.team_name AS team_name,
               {im_full_sql_ex}
               {im_ex_extra_sql}
        FROM `tabDaily Execution` de
        INNER JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabINET Team` it ON it.name = de.team
        LEFT JOIN `tabProject Control Center` pcc_ex ON pcc_ex.name = pd.project_code
        {rp_im_join_ex}
        LEFT JOIN `tabIM Master` im_pd ON im_pd.name = pd.im
        {bucket_join_ex}
        WHERE pd.im IN ({ph}){status_clause}{portal_clause}
        {future_planned_clause}
        -- Extended: IM pushed the deadline on a stalled plan but the TL
        -- hasn't re-engaged yet — belongs on Rollout Execution (needs the
        -- TL to start/restart it), not here, even though an old Daily
        -- Execution from before it stalled may still exist. The moment the
        -- TL logs activity, the sync logic flips this to In Execution and
        -- it reappears here normally.
        {extended_clause}
        AND NOT EXISTS (
            SELECT 1 FROM `tabRollout Plan` rp_later
            WHERE rp_later.po_dispatch = rp.po_dispatch
            AND IFNULL(rp_later.visit_number, 0) > IFNULL(rp.visit_number, 0)
        )
        {issue_block_clause}
        ORDER BY de.execution_date DESC, de.creation DESC
        {_sql_limit_suffix(lim_de)}
        """,
        tuple(params),
        as_dict=True,
    )
    if rows:
        act_map = _batch_item_activity_types(rows)
        for r in rows:
            r["activity_type"] = act_map.get(r.get("item_code") or "")
            r["timer_start_ms"] = _frappe_dt_to_epoch_ms(r.get("timer_start"))
        _enrich_with_project_fields(rows)
        _apply_dummy_description(rows)
    return rows or []


def _split_search_tokens(text):
    """Split a pasted/typed search box's content into distinct values.

    One value per LINE is the primary case ("support multiple lines"), but
    comma/semicolon/tab-separated values on one line also work — the same
    multi-value paste convention SearchableSelect already uses elsewhere in
    this app, so a user pasting an Excel column behaves the same way here.
    Blank lines and stray whitespace are dropped; duplicates are removed
    while keeping the first-seen order (stable, for a predictable result
    order downstream).
    """
    if not text:
        return []
    raw = re.split(r"[\n\r,;\t]+", str(text))
    seen = set()
    out = []
    for t in raw:
        t = t.strip()
        if t and t not in seen:
            seen.add(t)
            out.append(t)
    return out


# A single free-text box can't know whether a pasted value is a DUID, a POID,
# or a PO number, and the point of unifying the three old tabs is that it
# shouldn't have to — every token is matched against all three fields at
# once via OR'd IN-clauses (cheap: 3 IN-lists, not 3xN OR'd equalities).
MAX_DUID_OVERVIEW_TOKENS = 200


@frappe.whitelist()
def get_duid_overview(query=None, duid=None, po_no=None, poid=None):
    """
    DUID / POID / PO-No search — one free-text box, one or more values (one
    per line, or comma/semicolon/tab-separated), of any mix of the three
    identifier kinds. Each token is matched against site_code, poid AND
    po_no, since the box has no way to know — and doesn't need to — which
    kind was typed.

    `duid`/`po_no`/`poid` remain as a legacy single-value fallback for any
    caller still using the old three-tab shape; folded into the same token
    set as `query` rather than handled separately.

    Expenses / acceptance-detail linking: placeholders for Phase 2 (the
    acceptance MILESTONE data itself is already returned — see
    _duid_overview_acceptance below).

    PM / desk admin only — not for INET IM / field roles.
    """
    user = frappe.session.user
    if not user or user == "Guest":
        frappe.throw("Not permitted", frappe.PermissionError)
    roles = set(frappe.get_roles(user))
    if not (
        "Administrator" in roles
        or "System Manager" in roles
        or "INET Admin" in roles
    ):
        frappe.throw("Not permitted", frappe.PermissionError)

    tokens = _split_search_tokens(query)
    for legacy in (duid, po_no, poid):
        v = (legacy or "").strip()
        if v and v not in tokens:
            tokens.append(v)
    if not tokens:
        frappe.throw("Enter one or more DUID / POID / PO number values (one per line).")
    if len(tokens) > MAX_DUID_OVERVIEW_TOKENS:
        frappe.throw(f"Too many values — search up to {MAX_DUID_OVERVIEW_TOKENS} at a time.")

    dispatches = frappe.get_all(
        "PO Dispatch",
        or_filters=[
            ["site_code", "in", tokens],
            ["poid", "in", tokens],
            ["po_no", "in", tokens],
        ],
        fields=["*"],
        order_by="modified desc",
        # A multi-line search can legitimately match far more than the old
        # single-value box's 50 — a handful of DUIDs can each carry dozens
        # of PO lines. Not unlimited: still a real cap, just sized for the
        # actual use case instead of the old one-value assumption.
        limit_page_length=500,
    )
    dispatch_names = [d.name for d in dispatches]
    plans = []
    executions = []
    if dispatch_names:
        plans = frappe.get_all(
            "Rollout Plan",
            filters={"po_dispatch": ["in", dispatch_names]},
            fields=["*"],
            order_by="plan_date desc",
            limit_page_length=200,
        )
        plan_names = [p.name for p in plans]
        if plan_names:
            executions = frappe.get_all(
                "Daily Execution",
                filters={"rollout_plan": ["in", plan_names]},
                fields=["*"],
                order_by="execution_date desc",
                limit_page_length=200,
            )

    return {
        "query_tokens": tokens,
        "matched_count": len(dispatches),
        "dispatches": dispatches,
        "rollout_plans": plans,
        "executions": executions,
        "additional_activities": [],
        "expenses": [],
        "acceptance": _duid_overview_acceptance(dispatch_names),
        "subcon": _duid_overview_subcon(dispatch_names),
        "notes": "Additional activities and expenses can be linked in a later phase.",
    }


def _duid_overview_acceptance(dispatch_names):
    """PIC side of a searched DUID: where each milestone sits and what it is worth.

    Lazy import — pic.py imports from this module, so a module-level import
    would be circular.
    """
    if not dispatch_names:
        return []
    pic = __import__("inet_app.api.pic", fromlist=["x"])
    fields = set(frappe.db.get_table_columns("PO Dispatch"))

    def col(name, default="NULL"):
        return f"pd.{name}" if name in fields else default

    rows = frappe.db.sql(
        f"""
        SELECT pd.name AS po_dispatch, IFNULL(pd.poid, pd.name) AS poid,
               {col("pic_status")} AS pic_status,
               {col("pic_status_ms2")} AS pic_status_ms2,
               {col("ms1_pct", "0")} AS ms1_pct, {col("ms2_pct", "0")} AS ms2_pct,
               {col("ms1_amount", "0")} AS ms1_amount, {col("ms2_amount", "0")} AS ms2_amount,
               {col("ms1_invoiced", "0")} AS ms1_invoiced, {col("ms2_invoiced", "0")} AS ms2_invoiced,
               {col("ms1_unbilled", "0")} AS ms1_unbilled, {col("ms2_unbilled", "0")} AS ms2_unbilled,
               {col("ms1_applied_date")} AS ms1_applied_date,
               {col("ms2_applied_date")} AS ms2_applied_date,
               {col("ms1_invoice_month")} AS ms1_invoice_month,
               {col("ms2_invoice_month")} AS ms2_invoice_month,
               {col("ms1_payment_received_date")} AS ms1_payment_received_date,
               {col("ms2_payment_received_date")} AS ms2_payment_received_date,
               {col("isdp_owner")} AS isdp_owner, {col("ibuy_owner")} AS ibuy_owner,
               {col("pic_rejection_remark")} AS pic_rejection_remark
        FROM `tabPO Dispatch` pd
        WHERE pd.name IN ({", ".join(["%s"] * len(dispatch_names))})
        ORDER BY pd.poid
        """,
        tuple(dispatch_names),
        as_dict=True,
    ) or []

    invoices = {}
    try:
        invoices = pic._batch_linked_invoices(dispatch_names) or {}
    except Exception:
        # A missing Sales Invoice link must not cost the caller the whole
        # acceptance section — the milestone figures above still stand.
        invoices = {}
    for r in rows:
        r["invoices"] = invoices.get(r["po_dispatch"]) or ""
    return rows


def _duid_overview_subcon(dispatch_names):
    """Supplier side of the same lines: who owes what, and against which PO.

    The subcontract is RESOLVED, not stored — pd.contract wins, else the plan
    team's subcontractor, else the backend team's. Same COALESCE precedence
    as subcon_po._SUBCON_FROM_JOIN, so this page and the Subcon PO page can
    never name different suppliers for one line.
    """
    if not dispatch_names:
        return []
    if not frappe.db.exists("DocType", "Subcontract Master"):
        return []
    fields = set(frappe.db.get_table_columns("PO Dispatch"))
    if "contract" not in fields:
        return []

    def col(name, default="NULL"):
        return f"pd.{name}" if name in fields else default

    ph = ", ".join(["%s"] * len(dispatch_names))
    rows = frappe.db.sql(
        f"""
        SELECT pd.name AS po_dispatch, IFNULL(pd.poid, pd.name) AS poid,
               sm.name AS subcontract, sm.subcontractor_name, sm.supplier,
               sm.contract_model, IFNULL(sm.sub_payout_pct, 0) AS payout_pct,
               {col("ms1_amount", "0")} AS ms1_amount, {col("ms2_amount", "0")} AS ms2_amount,
               ROUND(IFNULL({col("ms1_amount", "0")}, 0) * IFNULL(sm.sub_payout_pct, 0) / 100, 2) AS ms1_payout,
               ROUND(IFNULL({col("ms2_amount", "0")}, 0) * IFNULL(sm.sub_payout_pct, 0) / 100, 2) AS ms2_payout,
               {col("sub_po_status_ms1")} AS sub_po_status_ms1,
               {col("sub_po_status_ms2")} AS sub_po_status_ms2
        FROM `tabPO Dispatch` pd
        LEFT JOIN (
            SELECT rp.po_dispatch AS po_dispatch, MAX(it.subcontractor) AS subcontractor
            FROM `tabRollout Plan` rp
            LEFT JOIN `tabINET Team` it ON it.name = rp.team
            GROUP BY rp.po_dispatch
        ) plan_sub ON plan_sub.po_dispatch = pd.name
        LEFT JOIN `tabINET Team` bt ON bt.name = {col("backend_team", "NULL")}
        LEFT JOIN `tabSubcontract Master` sm
               ON sm.name = COALESCE(NULLIF(pd.contract, ''), plan_sub.subcontractor, bt.subcontractor)
        WHERE pd.name IN ({ph})
        ORDER BY pd.poid
        """,
        tuple(dispatch_names),
        as_dict=True,
    ) or []

    linked = {}
    try:
        subcon = __import__("inet_app.api.subcon_po", fromlist=["x"])
        linked = subcon._batch_linked_purchase_docs(dispatch_names) or {}
    except Exception:
        linked = {}
    for r in rows:
        docs = linked.get(r["po_dispatch"]) or {}
        r["purchase_orders"] = docs.get("po") or ""
        r["purchase_invoices"] = docs.get("pi") or ""
    return rows


@frappe.whitelist()
def reopen_rollout_for_revisit(rollout_plan, issue_category=None, planning_route=None, issue_remarks=None):
    """
    Report Issue: mark the source plan and its DEs as needing a Re-Visit.
    No new plan is created here — IM creates the Re-Visit plan from Issues & Risks.
    """
    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Invalid Rollout Plan")

    source_updates = {
        "plan_status": "Planning with Issue",
        "issue_status": "Reported",
        "issue_category": (issue_category or "")[:140],
    }
    if frappe.db.has_column("Rollout Plan", "issue_remarks") and issue_remarks:
        source_updates["issue_remarks"] = str(issue_remarks)[:2000]
    frappe.db.set_value("Rollout Plan", rollout_plan, source_updates, update_modified=True)

    if frappe.db.has_column("Daily Execution", "revisit_flag"):
        for de_name in frappe.get_all(
            "Daily Execution",
            filters={"rollout_plan": rollout_plan},
            pluck="name",
        ):
            frappe.db.set_value("Daily Execution", de_name, "revisit_flag", 1, update_modified=False)

    frappe.db.commit()
    return {
        "ok": True,
        "source_rollout_plan": rollout_plan,
        "plan_status": "Planning with Issue",
        "issue_status": "Reported",
    }


@frappe.whitelist()
def reschedule_rollout_plan(rollout_plan, new_date, reason, im_note=None, new_end_date=None):
    """
    Reschedule a plan that did not execute (Not Attended / Cancelled / Overdue / Hold).
    Does NOT create a new plan and does NOT increment visit_number.
    Resets plan_date and plan_status to 'Planned', logs the event in reschedule_log.

    new_end_date: optional — lets the IM pick a genuinely new multi-day span on the
    same reschedule (e.g. a 2-day job that never started, moved to next week and
    still needs 2 days). Defaults to new_date (single day) when omitted, same as the
    frontend's default. Without this, a plan that used to be multi-day would either
    keep a stale old end date (if still >= new_date) or silently collapse to a single
    day (if not) — neither reflects a deliberate choice by the IM.
    """
    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Invalid Rollout Plan")
    if not new_date:
        frappe.throw("New date is required")
    if new_end_date and getdate(new_end_date) < getdate(new_date):
        frappe.throw("New end date cannot be before the new date.")

    doc = frappe.get_doc("Rollout Plan", rollout_plan)
    if doc.plan_status == "Completed":
        frappe.throw("Cannot reschedule a completed plan.")
    wd_exists = frappe.db.sql(
        """SELECT 1 FROM `tabWork Done` wd
           JOIN `tabDaily Execution` de ON de.name = wd.execution
           WHERE de.rollout_plan = %s LIMIT 1""",
        (rollout_plan,),
    )
    if wd_exists:
        frappe.throw("Cannot reschedule: Work Done already exists for this plan.")

    tl_snap = frappe.db.get_value(
        "Daily Execution",
        {"rollout_plan": rollout_plan},
        "tl_status",
        order_by="modified desc",
    ) or ""

    doc.append("reschedule_log", {
        "original_date": doc.plan_date,
        "new_date": new_date,
        "reason": reason or "Other",
        "tl_status_at_time": tl_snap,
        "im_note": (im_note or "")[:2000],
        "rescheduled_by": frappe.session.user,
        "rescheduled_at": frappe.utils.now(),
    })
    doc.reschedule_count = cint(doc.reschedule_count or 0) + 1
    doc.plan_date = new_date
    if new_end_date:
        doc.plan_end_date = new_end_date
    elif doc.plan_end_date and getdate(doc.plan_end_date) < getdate(new_date):
        # No explicit new_end_date given — fall back to the old clamp-forward
        # behavior so a stale end date can never end up before the new start.
        doc.plan_end_date = new_date
    doc.plan_status = "Planned"
    doc.save(ignore_permissions=True)
    frappe.db.commit()
    return {"ok": True, "reschedule_count": doc.reschedule_count}


@frappe.whitelist()
def get_reschedule_logs(rollout_plan):
    """Return reschedule_log child rows + reschedule_count for a Rollout Plan."""
    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Invalid Rollout Plan")
    reschedule_count = frappe.db.get_value("Rollout Plan", rollout_plan, "reschedule_count") or 0
    logs = frappe.db.get_all(
        "Rollout Plan Reschedule Log",
        filters={"parent": rollout_plan},
        fields=["original_date", "new_date", "reason", "tl_status_at_time", "im_note",
                "rescheduled_by", "rescheduled_at"],
        order_by="rescheduled_at asc",
    )
    return {"reschedule_count": reschedule_count, "logs": logs}


def auto_mark_overdue_plans():
    """Scheduled daily: mark Planned rollout plans past their plan_date as Overdue."""
    frappe.db.sql("""
        UPDATE `tabRollout Plan`
        SET plan_status = 'Overdue', modified = NOW(), modified_by = 'Administrator'
        WHERE plan_status = 'Planned'
        AND plan_date < CURDATE()
        AND NOT EXISTS (
            SELECT 1 FROM `tabWork Done` wd
            JOIN `tabDaily Execution` de ON de.name = wd.execution
            WHERE de.rollout_plan = `tabRollout Plan`.name
        )
    """)
    frappe.db.commit()


def _cascade_im_on_dispatch(dispatch_name, new_im):
    """Cascade a new IM value to all non-Cancelled Rollout Plans and Daily
    Executions linked to *dispatch_name*.

    Called both from the PO Dispatch controller (Frappe form save) and from
    any API that updates pd.im via frappe.db.set_value (which bypasses hooks).
    """
    if not dispatch_name or not new_im:
        return
    plan_names = frappe.db.sql(
        "SELECT name FROM `tabRollout Plan` WHERE po_dispatch = %s AND IFNULL(plan_status,'') != 'Cancelled'",
        (dispatch_name,), as_dict=False,
    )
    plan_names = [r[0] for r in plan_names]
    if not plan_names:
        return
    ph = ", ".join(["%s"] * len(plan_names))
    if frappe.db.has_column("Rollout Plan", "im"):
        frappe.db.sql(
            f"UPDATE `tabRollout Plan` SET im = %s WHERE name IN ({ph})",
            [new_im] + plan_names,
        )
    if frappe.db.has_column("Daily Execution", "im"):
        frappe.db.sql(
            f"UPDATE `tabDaily Execution` SET im = %s "
            f"WHERE rollout_plan IN ({ph}) AND IFNULL(execution_status,'') != 'Cancelled'",
            [new_im] + plan_names,
        )


@frappe.whitelist()
def backfill_rollout_and_execution_im():
    """One-shot: set Rollout Plan.im and Daily Execution.im from PO Dispatch (Administrator)."""
    frappe.only_for("System Manager")
    updated_rp = 0
    updated_de = 0
    for rp in frappe.get_all("Rollout Plan", filters={"po_dispatch": ["!=", ""]}, fields=["name", "po_dispatch"]):
        im_v = frappe.db.get_value("PO Dispatch", rp.po_dispatch, "im")
        if im_v:
            frappe.db.set_value("Rollout Plan", rp.name, "im", im_v, update_modified=False)
            updated_rp += 1
    for de in frappe.get_all("Daily Execution", filters={"rollout_plan": ["!=", ""]}, fields=["name", "rollout_plan"]):
        pd = frappe.db.get_value("Rollout Plan", de.rollout_plan, "po_dispatch")
        if not pd:
            continue
        im_v = frappe.db.get_value("PO Dispatch", pd, "im")
        if im_v:
            frappe.db.set_value("Daily Execution", de.name, "im", im_v, update_modified=False)
            updated_de += 1
    frappe.db.commit()
    return {"rollout_plans_updated": updated_rp, "executions_updated": updated_de}


@frappe.whitelist()
def get_im_dashboard(im=None, from_date=None, to_date=None, etag=None):
    """
    Filtered dashboard for a single IM.
    Resolves the IM Master record name in multiple ways so mismatched
    im/full_name values don't silently return empty data.

    Optional ``from_date`` / ``to_date`` (ISO YYYY-MM-DD) override the
    default month window for date-scoped metrics.

    If the caller passes an ``etag`` matching the current data version,
    short-circuits with ``{"unchanged": True, "etag": ...}``.
    """
    current_etag = _dashboard_etag("im", im or "", from_date, to_date)
    if etag and etag == current_etag:
        return {"unchanged": True, "etag": current_etag, "last_updated": _iso_now()}
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    if not im_identifiers:
        return {
            "im": None,
            "teams": [],
            "projects": [],
            "kpi": {},
            "action_items": {"pending_plan_dispatches": 0, "qc_fail_needs_action": 0, "planned_ready_execution": 0, "pending_approvals": 0, "open_dummy_pos": 0},
            "debug": {"error": "Could not resolve IM from session or parameter"},
            "etag": current_etag,
            "last_updated": _iso_now(),
        }

    im = im_resolved
    action_items = im_action_counts(im_identifiers)

    today_str = nowdate()
    today = getdate(today_str)
    first_day, last_day, _ = _month_bounds()
    if from_date:
        try: first_day = getdate(from_date)
        except Exception: pass
    if to_date:
        try: last_day = getdate(to_date)
        except Exception: pass
    days_in_month = _days_in_month(today)
    day_of_month = min(today.day, 30)   # month basis = 30; cost capped at 30 days

    # Teams belonging to this IM — match any known identifier value
    teams = frappe.get_all(
        "INET Team",
        filters={"im": ["in", im_identifiers], "status": "Active"},
        fields=["name", "team_id", "team_name", "team_type", "daily_cost", "status"],
    )
    team_ids = [t.name for t in teams]

    # Projects assigned to this IM — match any known identifier value
    projects = frappe.get_all(
        "Project Control Center",
        filters={"implementation_manager": ["in", im_identifiers]},
        fields=["name", "project_code", "project_name", "project_status", "customer"],
        order_by="modified desc",
        limit=50,
    )
    # Normalize field names for frontend. completion_pct/budget used to come
    # from the dead completion_percentage/budget_amount fields (nothing
    # writes them) — dropped rather than replaced since this "projects" list
    # itself isn't rendered anywhere (IM Dashboard reads project_progress,
    # computed separately below from real Rollout Plan completion counts).
    for p in projects:
        p["status"] = p.pop("project_status", "Active") or "Active"

    debug_info = {
        "im_resolved": im_resolved,
        "im_identifiers": im_identifiers,
        "teams_found": len(team_ids),
        "projects_found": len(projects),
        "action_items": action_items,
    }

    if not team_ids:
        return {
            "im": im_resolved,
            "teams": [],
            "projects": projects,
            "kpi": {"team_count": 0, "revenue": 0, "cost": 0, "profit": 0},
            "action_items": action_items,
            "message": (
                f"No active INET Teams found for this IM "
                f"(searched: {', '.join(im_identifiers)}). "
                f"In INET Team master set 'Implementation Manager' to one of those values."
            ),
            "debug": debug_info,
            "last_updated": _iso_now(),
            "etag": current_etag,
        }

    placeholders = ", ".join(["%s"] * len(team_ids))

    # Revenue this month
    revenue_rows = frappe.db.sql(
        f"""
        SELECT COALESCE(SUM(wd.revenue_sar), 0) AS revenue,
               COALESCE(SUM(wd.total_cost_sar), 0) AS cost
        FROM `tabWork Done` wd
        JOIN `tabDaily Execution` exe ON exe.name = wd.execution
        JOIN `tabRollout Plan` rp ON rp.name = exe.rollout_plan
        WHERE rp.team IN ({placeholders})
        AND exe.execution_date BETWEEN %s AND %s
        """,
        tuple(team_ids) + (first_day, last_day),
        as_dict=True,
    )
    revenue = flt(revenue_rows[0].revenue if revenue_rows else 0)
    cost = flt(revenue_rows[0].cost if revenue_rows else 0)

    # Direct Close / Backend revenue for this IM — wd.execution is blank for
    # these (no Daily Execution/Rollout Plan, no team), so the team-scoped
    # query above never sees them; scoped by pd.im instead, dated by
    # wd.creation since there's no execution date. Without this, an IM who
    # only direct-closes/backend-closes showed 0 here even after the same
    # gap was fixed on the IM Performance Scorecard.
    _direct_ph = ", ".join(["%s"] * len(im_identifiers))
    direct_revenue_rows = frappe.db.sql(
        f"""
        SELECT COALESCE(SUM(wd.revenue_sar), 0) AS revenue,
               COALESCE(SUM(wd.total_cost_sar), 0) AS cost
        FROM `tabWork Done` wd
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        WHERE IFNULL(wd.execution, '') = ''
          AND DATE(wd.creation) BETWEEN %s AND %s
          AND pd.im IN ({_direct_ph})
        """,
        (first_day, last_day) + tuple(im_identifiers),
        as_dict=True,
    )
    revenue += flt(direct_revenue_rows[0].revenue if direct_revenue_rows else 0)
    cost += flt(direct_revenue_rows[0].cost if direct_revenue_rows else 0)

    # Add approved project expense claims filed against this IM's teams
    im_users = [u for u in [frappe.db.get_value("IM Master", im_resolved, "user")] if u]
    if im_users:
        expense_rows = frappe.db.sql(
            """
            SELECT COALESCE(SUM(total_sanctioned_amount), 0) AS expense_cost
            FROM `tabExpense Claim`
            WHERE is_project_claim = 1
              AND expense_approver IN %s
              AND approval_status = 'Approved'
              AND docstatus < 2
              AND posting_date BETWEEN %s AND %s
            """,
            (tuple(im_users), first_day, last_day),
            as_dict=True,
        )
        cost += flt(expense_rows[0].expense_cost if expense_rows else 0)

    # Monthly target — projects where this IM is implementation_manager
    im_ph = ", ".join(["%s"] * len(im_identifiers))
    monthly_target_rows = frappe.db.sql(
        f"""
        SELECT COALESCE(SUM(pcc.monthly_target), 0) AS total
        FROM `tabProject Control Center` pcc
        WHERE pcc.implementation_manager IN ({im_ph})
        AND pcc.active_flag = 'Yes'
        """,
        tuple(im_identifiers),
        as_dict=True,
    )
    monthly_target = flt(monthly_target_rows[0].total if monthly_target_rows else 0)
    target_today = (
        (monthly_target * day_of_month) / days_in_month if days_in_month else 0.0
    )
    gap_today = target_today - revenue

    # Active teams today
    active_today_rows = frappe.db.sql(
        f"""
        SELECT COUNT(DISTINCT team) AS cnt FROM `tabDaily Execution`
        WHERE team IN ({placeholders})
        AND execution_date = %s
        """,
        tuple(team_ids) + (today_str,),
        as_dict=True,
    )
    active_today = cint(active_today_rows[0].cnt if active_today_rows else 0)

    # Planned activities — match the Planning page: every Rollout Plan whose
    # PO Dispatch belongs to this IM (or whose rp.im column points at this IM)
    # and is in `Planned` status. Counting by team missed plans that weren't
    # team-assigned yet or that were on teams outside the active list, which
    # made the dashboard KPI disagree with the Planning table.
    im_ph = ", ".join(["%s"] * len(im_identifiers))
    rp_im_clause = ""
    rp_im_params = []
    if frappe.db.has_column("Rollout Plan", "im"):
        rp_im_clause = f" OR IFNULL(rp.im,'') IN ({im_ph})"
        rp_im_params = list(im_identifiers)
    planned_rows = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS cnt
        FROM `tabRollout Plan` rp
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE rp.plan_status IN ('Planned', 'Extended')
        AND (IFNULL(pd.im,'') IN ({im_ph}){rp_im_clause})
        """,
        tuple(im_identifiers) + tuple(rp_im_params),
        as_dict=True,
    )
    planned_activities = cint(planned_rows[0].cnt if planned_rows else 0)

    # ── Rollout-plan KPIs ────────────────────────────────────────────────
    # These count ROLLOUT PLANS (one per planned visit), not distinct sites —
    # a site replanned three times is three plans. They used to be labelled
    # "…Sites" in the UI, which read ~3x the real site count because a third
    # of plans are re-visits. The tiles are named after plans now; use
    # `distinct_sites` if a true site count is ever wanted.
    #
    # The four period tiles honour the dashboard's date range, matched on the
    # plan's own plan_date. The range condition sits inside each CASE rather
    # than in the WHERE so that the two "Today" tiles stay anchored to the
    # actual today — they are labelled "Today", so they must not read zero
    # just because the selected range happens to exclude it. Plans with no
    # plan_date fall outside every range and so are not counted.
    site_kpi_rows = frappe.db.sql(
        f"""
        SELECT
            -- A cancelled plan is not assigned work; it used to be counted.
            SUM(CASE WHEN rp.plan_date BETWEEN %s AND %s
                      AND IFNULL(rp.plan_status, '') <> 'Cancelled'
                     THEN 1 ELSE 0 END) AS total_assigned,
            COUNT(DISTINCT CASE WHEN rp.plan_date BETWEEN %s AND %s
                                THEN NULLIF(pd.site_code, '') END) AS distinct_sites,
            SUM(CASE WHEN rp.plan_date BETWEEN %s AND %s
                      AND rp.plan_status = 'Completed'
                     THEN 1 ELSE 0 END) AS completed_total,
            SUM(CASE WHEN rp.plan_date BETWEEN %s AND %s
                      AND rp.plan_status = 'In Execution'
                     THEN 1 ELSE 0 END) AS in_progress_cnt,
            -- 'Overdue' is the bigger delayed group and was ignored entirely,
            -- so this tile only ever showed 'Planning with Issue'.
            SUM(CASE WHEN rp.plan_date BETWEEN %s AND %s
                      AND rp.plan_status IN ('Overdue', 'Planning with Issue')
                     THEN 1 ELSE 0 END) AS delayed_cnt,
            SUM(CASE WHEN rp.plan_date BETWEEN %s AND %s
                      AND rp.plan_status = 'Cancelled'
                     THEN 1 ELSE 0 END) AS cancelled_cnt,
            SUM(CASE WHEN rp.plan_date = %s THEN 1 ELSE 0 END) AS today_target_cnt,
            -- Completed today, dated by the execution's own execution_date.
            -- This was `rp.modified >= today`, the last-edited timestamp, so
            -- re-saving any old completed plan inflated "Today Completed".
            COUNT(DISTINCT CASE
                WHEN rp.plan_status = 'Completed' AND de_today.rollout_plan IS NOT NULL
                THEN rp.name END) AS today_completed_cnt
        FROM `tabRollout Plan` rp
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN (
            SELECT DISTINCT rollout_plan
            FROM `tabDaily Execution`
            WHERE execution_date = %s AND IFNULL(rollout_plan, '') <> ''
        ) de_today ON de_today.rollout_plan = rp.name
        WHERE (IFNULL(pd.im,'') IN ({im_ph}){rp_im_clause})
        """,
        (first_day, last_day) * 6 + (today_str, today_str)
        + tuple(im_identifiers) + tuple(rp_im_params),
        as_dict=True,
    )
    skr = (site_kpi_rows[0] if site_kpi_rows else {}) or {}
    site_kpi = {
        "total_assigned": cint(skr.get("total_assigned") or 0),
        "distinct_sites": cint(skr.get("distinct_sites") or 0),
        "completed_total": cint(skr.get("completed_total") or 0),
        "in_progress": cint(skr.get("in_progress_cnt") or 0),
        "delayed": cint(skr.get("delayed_cnt") or 0),
        "cancelled": cint(skr.get("cancelled_cnt") or 0),
        "today_target": cint(skr.get("today_target_cnt") or 0),
        "today_completed": cint(skr.get("today_completed_cnt") or 0),
        # The window the four period tiles describe, so the UI can label it
        # rather than leaving the reader to guess.
        "range_from": str(first_day),
        "range_to": str(last_day),
    }

    # ── Team performance: completed sites per team in the date window ────
    team_perf = []
    if team_ids:
        team_perf_rows = frappe.db.sql(
            f"""
            SELECT t.team_id AS team_id,
                   COALESCE(t.team_name, t.team_id) AS team_name,
                   COUNT(rp.name) AS sites_done
            FROM `tabINET Team` t
            LEFT JOIN `tabRollout Plan` rp
                ON (
                    EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt
                        WHERE rpt.parent = rp.name AND rpt.team = t.name
                    )
                    -- Legacy plans with no multi-team split rows at all fall
                    -- back to the plan's own lead team, same as before this
                    -- multi-team-aware attribution was added.
                    OR (
                        rp.team = t.name
                        AND NOT EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt2 WHERE rpt2.parent = rp.name)
                    )
                )
                AND rp.plan_status = 'Completed'
                AND rp.plan_date BETWEEN %s AND %s
            WHERE t.name IN ({placeholders})
            GROUP BY t.name, t.team_id, t.team_name
            ORDER BY sites_done DESC, team_name ASC
            """,
            (first_day, last_day) + tuple(team_ids),
            as_dict=True,
        )
        team_perf = [
            {"team_id": r.team_id, "team_name": r.team_name, "sites_done": cint(r.sites_done or 0)}
            for r in (team_perf_rows or [])
        ]

    # ── Project progress: planned rollout visits completed, per project ──
    # This is deliberately a PLANNING metric — "how much of the rollout work
    # I planned is done" — measured in Rollout Plans, not PO lines. It is
    # therefore NOT the same number as the PM dashboard's Top Projects
    # completion %, which is line-based; see get_project_line_completion in
    # project_management.dashboard_charts.
    #
    # Cancelled plans are excluded from the denominator (a cancelled visit is
    # not outstanding work), and the exclusion sits in the CASE rather than
    # the WHERE so projects with no plans at all still come back with a row.
    project_progress = []
    if projects:
        project_codes = [p["project_code"] for p in projects if p.get("project_code")]
        if project_codes:
            ph_pr = ", ".join(["%s"] * len(project_codes))
            prog_rows = frappe.db.sql(
                f"""
                SELECT pd.project_code AS project_code,
                       SUM(CASE WHEN rp.name IS NOT NULL
                                 AND IFNULL(rp.plan_status, '') <> 'Cancelled'
                                THEN 1 ELSE 0 END) AS total,
                       SUM(CASE WHEN rp.plan_status = 'Completed' THEN 1 ELSE 0 END) AS done,
                       SUM(CASE WHEN rp.plan_status = 'Cancelled' THEN 1 ELSE 0 END) AS cancelled
                FROM `tabPO Dispatch` pd
                LEFT JOIN `tabRollout Plan` rp ON rp.po_dispatch = pd.name
                WHERE pd.project_code IN ({ph_pr})
                AND IFNULL(pd.im,'') IN ({im_ph})
                GROUP BY pd.project_code
                """,
                tuple(project_codes) + tuple(im_identifiers),
                as_dict=True,
            )
            prog_map = {r.project_code: r for r in (prog_rows or [])}
            # Show the projects that actually have rollout activity, not
            # whichever six were touched most recently — a project modified
            # today with no plans used to occupy a slot at a flat 0%.
            ranked = sorted(
                projects,
                key=lambda p: cint((prog_map.get(p.get("project_code")) or {}).get("total")),
                reverse=True,
            )
            for p in ranked[:6]:
                pc = p.get("project_code")
                row = prog_map.get(pc)
                total = cint(row.total) if row else 0
                done = cint(row.done) if row else 0
                pct = int(round((done / total) * 100)) if total > 0 else 0
                project_progress.append({
                    "project_code": pc,
                    "project_name": p.get("project_name") or pc,
                    "total": total,
                    "done": done,
                    "cancelled": cint(row.cancelled) if row else 0,
                    "pct": pct,
                    # Lets the UI say "no plans yet" instead of showing a
                    # project with zero plans as though it were 0% complete.
                    "has_plans": total > 0,
                    "basis": "rollout_plans",
                })

    # ── Site status table: latest rollout plans for this IM ──────────────
    # Site ID = DUID code from PO Dispatch (joins to DUID Master).
    # Location = Area Master.area_name via DUID Master.area. No fallback to
    # center_area / site_name — if the DUID has no Area set, the cell stays
    # empty so it's obvious where the master data is missing.
    site_status = frappe.db.sql(
        f"""
        SELECT pd.site_code AS site_id,
               am.area_name AS location,
               pd.project_code AS project,
               rp.plan_status AS status,
               rp.modified AS last_update,
               rp.issue_category AS issue
        FROM `tabRollout Plan` rp
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabDUID Master` dm ON dm.name = pd.site_code
        LEFT JOIN `tabArea Master` am ON am.name = dm.area
        WHERE (IFNULL(pd.im,'') IN ({im_ph}){rp_im_clause})
        ORDER BY rp.modified DESC
        LIMIT 8
        """,
        tuple(im_identifiers) + tuple(rp_im_params),
        as_dict=True,
    )
    site_status = [
        {
            "site_id": r.site_id or "—",
            "location": r.location or "—",
            "project": r.project or "—",
            "status": r.status or "—",
            "last_update": str(r.last_update) if r.last_update else "",
            "issue": r.issue or "",
        }
        for r in (site_status or [])
    ]

    # ── Material shortage: rollout plans / executions tagged with that issue
    material_categories = ("Material Shortage", "Spare Parts Pending")
    mat_ph = ", ".join(["%s"] * len(material_categories))
    mat_rows = frappe.db.sql(
        f"""
        SELECT COUNT(*) AS cnt FROM (
            SELECT rp.name FROM `tabRollout Plan` rp
            LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
            WHERE rp.issue_category IN ({mat_ph})
            AND (IFNULL(pd.im,'') IN ({im_ph}){rp_im_clause})
            UNION
            SELECT de.name FROM `tabDaily Execution` de
            LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
            LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
            WHERE de.issue_category IN ({mat_ph})
            AND (IFNULL(pd.im,'') IN ({im_ph}){rp_im_clause})
        ) AS u
        """,
        tuple(material_categories) + tuple(im_identifiers) + tuple(rp_im_params)
        + tuple(material_categories) + tuple(im_identifiers) + tuple(rp_im_params),
        as_dict=True,
    )
    material_shortage = cint(mat_rows[0].cnt if mat_rows else 0)

    # ── Site locations: lat/lon from DUID Master joined via PO Dispatch ──
    site_locations = []
    has_lat = frappe.db.has_column("DUID Master", "latitude")
    has_lon = frappe.db.has_column("DUID Master", "longitude")
    if has_lat and has_lon:
        site_loc_rows = frappe.db.sql(
            f"""
            SELECT
                pd.site_code AS site_code,
                COALESCE(pd.site_name, pd.site_code) AS site_name,
                pd.project_code AS project_code,
                d.latitude AS lat,
                d.longitude AS lon,
                MAX(rp.modified) AS last_update,
                /* Status: latest rollout plan's status if any, else 'Planned' */
                SUBSTRING_INDEX(GROUP_CONCAT(rp.plan_status ORDER BY rp.modified DESC), ',', 1) AS status
            FROM `tabPO Dispatch` pd
            INNER JOIN `tabDUID Master` d ON d.name = pd.site_code
            LEFT JOIN `tabRollout Plan` rp ON rp.po_dispatch = pd.name
            WHERE IFNULL(pd.im,'') IN ({im_ph})
              AND IFNULL(d.latitude, 0) <> 0
              AND IFNULL(d.longitude, 0) <> 0
            GROUP BY pd.site_code, pd.site_name, pd.project_code, d.latitude, d.longitude
            ORDER BY last_update DESC
            LIMIT 200
            """,
            tuple(im_identifiers),
            as_dict=True,
        )
        for r in (site_loc_rows or []):
            try:
                lat = float(r.lat)
                lon = float(r.lon)
            except (TypeError, ValueError):
                continue
            site_locations.append({
                "site_code": r.site_code,
                "site_name": r.site_name or r.site_code,
                "project_code": r.project_code,
                "lat": lat,
                "lon": lon,
                "status": r.status or "Planned",
                "last_update": str(r.last_update) if r.last_update else "",
            })

    # ── Activity timeline: recent Daily Execution events ─────────────────
    timeline_rows = frappe.db.sql(
        f"""
        SELECT de.name AS exec_id,
               de.execution_date,
               de.modified AS ts,
               de.execution_status,
               de.rollout_plan,
               COALESCE(pd.site_code, pd.site_name) AS site
        FROM `tabDaily Execution` de
        LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE (IFNULL(pd.im,'') IN ({im_ph}){rp_im_clause})
        ORDER BY de.modified DESC
        LIMIT 8
        """,
        tuple(im_identifiers) + tuple(rp_im_params),
        as_dict=True,
    )
    timeline = []
    for r in (timeline_rows or []):
        verb = (
            "completed" if (r.execution_status or "").lower() == "completed"
            else "delay reported" if (r.execution_status or "").lower() in ("hold", "cancelled", "postponed")
            else "work started" if (r.execution_status or "").lower() == "in progress"
            else "updated"
        )
        site = r.site or r.rollout_plan or "—"
        timeline.append({
            "ts": str(r.ts) if r.ts else "",
            "label": f"Site {site} {verb}",
            "exec_id": r.exec_id,
        })

    return {
        "im": im_resolved,
        "teams": teams,
        "projects": projects,
        "action_items": action_items,
        "site_kpi": site_kpi,
        "team_perf": team_perf,
        "project_progress": project_progress,
        "site_status": site_status,
        "timeline": timeline,
        "material_shortage": material_shortage,
        "site_locations": site_locations,
        "kpi": {
            "monthly_target": monthly_target,
            "target_today": target_today,
            "revenue": revenue,
            "cost": cost,
            "profit": revenue - cost,
            "gap_today": gap_today,
            "active_teams_today": active_today,
            "total_teams": len(teams),
            "team_count": len(teams),
            "planned_activities": planned_activities,
        },
        "debug": debug_info,
        "last_updated": _iso_now(),
        "etag": current_etag,
    }


@frappe.whitelist()
def get_im_reports():
    """
    IM-scoped report bundle for the portal (single round-trip).
    Same IM resolution as get_im_dashboard; no hardcoded placeholders.
    """
    im_resolved, im_identifiers = _require_inet_im_session()
    first_day, last_day, _today_str = _month_bounds()
    im_ph = ", ".join(["%s"] * len(im_identifiers))

    disp_rows = frappe.db.sql(
        f"""
        SELECT dispatch_status, COALESCE(project_code, '') AS project_code,
               COALESCE(line_amount, 0) AS line_amount, dispatch_mode
        FROM `tabPO Dispatch`
        WHERE im IN ({im_ph})
        LIMIT 2000
        """,
        tuple(im_identifiers),
        as_dict=True,
    ) or []
    total_lines = len(disp_rows)
    total_amount = sum(flt(r.get("line_amount")) for r in disp_rows)
    by_status = {}
    by_project = {}
    by_mode = {}
    for r in disp_rows:
        st = (r.get("dispatch_status") or "").strip() or "(No status)"
        by_status[st] = by_status.get(st, 0) + 1
        pk = (r.get("project_code") or "").strip() or "(No project)"
        by_project[pk] = by_project.get(pk, 0) + flt(r.get("line_amount"))
        md = (r.get("dispatch_mode") or "").strip() or "(No mode)"
        by_mode[md] = by_mode.get(md, 0) + 1

    teams = frappe.get_all(
        "INET Team",
        filters={"im": ["in", im_identifiers], "status": "Active"},
        fields=["name", "team_id", "team_name"],
    )
    team_ids = [t.name for t in teams]

    rollout_status_counts = []
    rollouts_recent = []
    exec_status_counts = []
    executions_recent = []
    wd_mtd = {"count": 0, "revenue_sar": 0.0, "by_billing": {}}

    if team_ids:
        tph = ", ".join(["%s"] * len(team_ids))
        rollout_status_counts = (
            frappe.db.sql(
                f"""
                SELECT rp.plan_status AS status_key, COUNT(*) AS cnt
                FROM `tabRollout Plan` rp
                WHERE rp.team IN ({tph})
                GROUP BY rp.plan_status
                ORDER BY cnt DESC
                """,
                tuple(team_ids),
                as_dict=True,
            )
            or []
        )

        rollouts_recent = (
            frappe.db.sql(
                f"""
                SELECT rp.name, rp.plan_date, rp.plan_status, rp.team, rp.po_dispatch,
                       rp.visit_type, rp.target_amount
                FROM `tabRollout Plan` rp
                WHERE rp.team IN ({tph})
                ORDER BY rp.modified DESC
                LIMIT 80
                """,
                tuple(team_ids),
                as_dict=True,
            )
            or []
        )
        for r in rollouts_recent:
            tid = r.get("team")
            r["team_name"] = frappe.db.get_value("INET Team", tid, "team_name") or tid

        exec_status_counts = (
            frappe.db.sql(
                f"""
                SELECT de.execution_status AS status_key, COUNT(*) AS cnt
                FROM `tabDaily Execution` de
                WHERE de.team IN ({tph})
                AND de.execution_date BETWEEN %s AND %s
                GROUP BY de.execution_status
                ORDER BY cnt DESC
                """,
                tuple(team_ids) + (first_day, last_day),
                as_dict=True,
            )
            or []
        )

        executions_recent = (
            frappe.db.sql(
                f"""
                SELECT de.name, de.rollout_plan, de.execution_date, de.execution_status,
                       de.qc_status, de.team, rp.po_dispatch
                FROM `tabDaily Execution` de
                LEFT JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
                WHERE de.team IN ({tph})
                AND de.execution_date BETWEEN %s AND %s
                ORDER BY de.modified DESC
                LIMIT 60
                """,
                tuple(team_ids) + (first_day, last_day),
                as_dict=True,
            )
            or []
        )

        wd_rows = (
            frappe.db.sql(
                f"""
                SELECT wd.billing_status AS billing_status,
                       COUNT(*) AS c,
                       COALESCE(SUM(wd.revenue_sar), 0) AS rev
                FROM `tabWork Done` wd
                INNER JOIN `tabDaily Execution` exe ON exe.name = wd.execution
                WHERE exe.team IN ({tph})
                AND exe.execution_date BETWEEN %s AND %s
                GROUP BY wd.billing_status
                """,
                tuple(team_ids) + (first_day, last_day),
                as_dict=True,
            )
            or []
        )
        by_billing = {}
        total_rev = 0.0
        total_cnt = 0
        for w in wd_rows:
            bs = (w.get("billing_status") or "").strip() or "Pending"
            c = cint(w.get("c"))
            rev = flt(w.get("rev"))
            by_billing[bs] = {"count": c, "revenue_sar": rev}
            total_cnt += c
            total_rev += rev
        wd_mtd = {"count": total_cnt, "revenue_sar": total_rev, "by_billing": by_billing}

    # Direct Close / Backend Work Done for this IM — no team at all, so the
    # team-scoped query above (and its `if team_ids:` gate) never sees these;
    # scoped by pd.im instead, dated by wd.creation since there's no
    # execution date to filter by. Runs unconditionally so an IM whose only
    # activity is direct/backend closes (or who has no teams at all) still
    # gets a non-zero Work Done MTD tile.
    direct_wd_rows = frappe.db.sql(
        """
        SELECT wd.billing_status AS billing_status,
               COUNT(*) AS c,
               COALESCE(SUM(wd.revenue_sar), 0) AS rev
        FROM `tabWork Done` wd
        JOIN `tabPO Dispatch` pd ON pd.name = wd.system_id
        WHERE IFNULL(wd.execution, '') = ''
          AND DATE(wd.creation) BETWEEN %s AND %s
          AND pd.im IN %s
        GROUP BY wd.billing_status
        """,
        (first_day, last_day, tuple(im_identifiers)),
        as_dict=True,
    ) or []
    for w in direct_wd_rows:
        bs = (w.get("billing_status") or "").strip() or "Pending"
        c = cint(w.get("c"))
        rev = flt(w.get("rev"))
        existing = wd_mtd["by_billing"].get(bs, {"count": 0, "revenue_sar": 0.0})
        wd_mtd["by_billing"][bs] = {"count": existing["count"] + c, "revenue_sar": existing["revenue_sar"] + rev}
        wd_mtd["count"] += c
        wd_mtd["revenue_sar"] += rev

    # completion_pct/budget used to come from the dead completion_percentage/
    # budget_amount/actual_cost fields (nothing writes them) — dropped rather
    # than replaced since this "projects" list isn't rendered by IMReports.jsx.
    projects = frappe.get_all(
        "Project Control Center",
        filters={"implementation_manager": ["in", im_identifiers]},
        fields=["name", "project_code", "project_name", "project_status"],
        order_by="modified desc",
        limit_page_length=50,
    )
    for p in projects:
        p["status"] = p.get("project_status") or "Active"

    return {
        "im": im_resolved,
        "last_updated": _iso_now(),
        "period": {"from": first_day, "to": last_day},
        "dispatch_summary": {
            "total_lines": total_lines,
            "total_amount": total_amount,
            "by_status": by_status,
            "by_project": by_project,
            "by_dispatch_mode": by_mode,
        },
        "rollout_status_counts": rollout_status_counts,
        "rollouts_recent": rollouts_recent,
        "execution_status_counts": exec_status_counts,
        "executions_recent": executions_recent,
        "work_done_mtd": wd_mtd,
        "projects": projects,
        "teams": teams,
    }


@frappe.whitelist()
def get_field_team_dashboard(team_id=None):
    """
    Return today's planned work for a specific team.
    Enriches rollout plan data with dispatch info (item_code, item_description,
    project_code, site_name).

    Returns
    -------
    {
        "team": team_id,
        "today": "YYYY-MM-DD",
        "planned": [...],
        "last_updated": ...,
    }
    """
    today_str = nowdate()

    if not team_id:
        return {"team": None, "today": today_str, "planned": [], "last_updated": _iso_now()}

    # Rollout Plans for this team today.
    # Drop plans the field team has *already* completed (tl_status or
    # execution_status = Completed) so cards don't reappear after the
    # team has wrapped up the day's job.
    has_access_time = frappe.db.has_column("Rollout Plan", "access_time")
    has_access_period = frappe.db.has_column("Rollout Plan", "access_period")
    has_qc_req = frappe.db.has_column("Rollout Plan", "qc_required")
    has_ciag_req = frappe.db.has_column("Rollout Plan", "ciag_required")
    extra_cols = ""
    if has_access_time:
        extra_cols += ", rp.access_time"
    if has_access_period:
        extra_cols += ", rp.access_period"
    if has_qc_req:
        extra_cols += ", rp.qc_required"
    if has_ciag_req:
        extra_cols += ", rp.ciag_required"
    # Multi-team: also match plans where this team is in the
    # Rollout Plan Team child table (not just the lead team field).
    has_rpt = frappe.db.exists("DocType", "Rollout Plan Team")
    team_match_clause = (
        "(rp.team = %s OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt "
        "WHERE rpt.parent = rp.name AND rpt.team = %s))"
        if has_rpt else "rp.team = %s"
    )
    team_params = (team_id, team_id) if has_rpt else (team_id,)
    plans = frappe.db.sql(
        f"""
        SELECT rp.name, rp.po_dispatch, rp.plan_date, rp.plan_end_date, rp.visit_type,
               rp.visit_number, rp.visit_multiplier, rp.target_amount,
               rp.achieved_amount, rp.completion_pct, rp.plan_status{extra_cols}
        FROM `tabRollout Plan` rp
        WHERE {team_match_clause}
        -- Multi-day plans: show on every day from plan_date through plan_end_date.
        AND rp.plan_date <= %s
        AND IFNULL(rp.plan_end_date, rp.plan_date) >= %s
        -- Hard excludes (plan-wide terminal states the team can't act on).
        AND rp.plan_status NOT IN ('Cancelled', 'Planning with Issue', 'Not Attended')
        -- Per-team actionability: hide when THIS team's own DE is done.
        AND NOT EXISTS (
          SELECT 1 FROM `tabDaily Execution` de
          WHERE de.rollout_plan = rp.name
            AND de.team = %s
            AND (de.tl_status IN ('Completed', 'Cancelled')
                 OR de.execution_status IN ('Completed', 'Cancelled'))
        )
        ORDER BY rp.name
        """,
        (*team_params, today_str, today_str, team_id),
        as_dict=True,
    )

    if not plans:
        return {
            "team": team_id,
            "today": today_str,
            "planned": [],
            "last_updated": _iso_now(),
        }

    dispatch_names = [p.po_dispatch for p in plans if p.po_dispatch]
    plan_names = [p.name for p in plans]
    dispatch_map = {}

    if dispatch_names:
        placeholders = ", ".join(["%s"] * len(dispatch_names))
        # Include manager_remark so the field card can show the IM Note.
        extra_remark_cols = ""
        for rk in ("general_remark", "manager_remark", "team_lead_remark"):
            if frappe.db.has_column("PO Dispatch", rk):
                extra_remark_cols += f", {rk}"
        dispatch_rows = frappe.db.sql(
            f"""
            SELECT name, poid, item_code, item_description, qty, project_code,
                   customer, site_name, site_code, center_area, region_type{extra_remark_cols}
            FROM `tabPO Dispatch`
            WHERE name IN ({placeholders})
            """,
            tuple(dispatch_names),
            as_dict=True,
        )
        dispatch_map = {d.name: d for d in dispatch_rows}

    # Multi-team: prefer THIS team's own DE row over the latest plan-
    # wide one — the card should reflect this team's status, not a
    # teammate's.
    exec_map = {}
    if plan_names:
        ex_placeholders = ", ".join(["%s"] * len(plan_names))
        own_rows = frappe.db.sql(
            f"""
            SELECT rollout_plan, execution_status, tl_status,
                   qc_status, ciag_status, achieved_qty, achieved_amount
            FROM `tabDaily Execution`
            WHERE rollout_plan IN ({ex_placeholders})
              AND team = %s
            """,
            tuple(plan_names) + (team_id,),
            as_dict=True,
        )
        for r in own_rows:
            exec_map[r["rollout_plan"]] = r
        latest_rows = frappe.db.sql(
            f"""
            SELECT de.rollout_plan, de.execution_status, de.tl_status,
                   de.qc_status, de.ciag_status, de.achieved_qty, de.achieved_amount
            FROM `tabDaily Execution` de
            INNER JOIN (
              SELECT rollout_plan, MAX(modified) AS m
              FROM `tabDaily Execution`
              WHERE rollout_plan IN ({ex_placeholders})
              GROUP BY rollout_plan
            ) t ON t.rollout_plan = de.rollout_plan AND t.m = de.modified
            """,
            tuple(plan_names),
            as_dict=True,
        )
        for r in latest_rows:
            exec_map.setdefault(r["rollout_plan"], r)

    # Per-team assigned qty for the current team_id (multi-team plans).
    my_assigned_map = {}
    teams_total_map = {}
    if plan_names and frappe.db.exists("DocType", "Rollout Plan Team"):
        ph2 = ", ".join(["%s"] * len(plan_names))
        try:
            for r in frappe.db.sql(
                f"SELECT parent, team, assigned_qty FROM `tabRollout Plan Team` "
                f"WHERE parent IN ({ph2})",
                tuple(plan_names), as_dict=True,
            ) or []:
                teams_total_map[r["parent"]] = teams_total_map.get(r["parent"], 0) + 1
                if r["team"] == team_id:
                    my_assigned_map[r["parent"]] = flt(r["assigned_qty"] or 0)
        except Exception:
            pass

    act_map = _batch_item_activity_types(
        [{"item_code": (d or {}).get("item_code")} for d in dispatch_map.values()]
    )

    # Merge dispatch data into plan records
    enriched = []
    for plan in plans:
        dispatch_info = dispatch_map.get(plan.po_dispatch) or {}
        ex = exec_map.get(plan.name) or {}
        enriched.append(
            {
                "name": plan.name,
                "po_dispatch": plan.po_dispatch,
                "plan_date": plan.plan_date,
                "visit_type": plan.visit_type,
                "visit_number": plan.visit_number,
                "visit_multiplier": plan.visit_multiplier,
                "target_amount": plan.target_amount,
                "achieved_amount": plan.achieved_amount,
                "completion_pct": plan.completion_pct,
                "plan_status": plan.plan_status,
                "poid": dispatch_info.get("poid"),
                "item_code": dispatch_info.get("item_code"),
                "item_description": dispatch_info.get("item_description"),
                "qty": dispatch_info.get("qty"),
                "project_code": dispatch_info.get("project_code"),
                "site_name": dispatch_info.get("site_name"),
                "site_code": dispatch_info.get("site_code"),
                "center_area": dispatch_info.get("center_area"),
                "region_type": dispatch_info.get("region_type")
                or region_type_from_center_area(dispatch_info.get("center_area")),
                "activity_type": act_map.get(dispatch_info.get("item_code") or ""),
                # IM-confirmed and field-side execution flags so the card
                # can show "IM ✓" or "Awaiting IM" without a second fetch.
                "execution_status": ex.get("execution_status"),
                "tl_status": ex.get("tl_status"),
                "qc_status": ex.get("qc_status"),
                "ciag_status": ex.get("ciag_status"),
                "access_time": plan.get("access_time") if has_access_time else None,
                "access_period": plan.get("access_period") if has_access_period else None,
                "qc_required": plan.get("qc_required", 1) if has_qc_req else 1,
                "ciag_required": plan.get("ciag_required", 1) if has_ciag_req else 1,
                "my_team": team_id,
                "my_assigned_qty": my_assigned_map.get(plan.name),
                "teams_total": teams_total_map.get(plan.name) or (1 if plan.get("name") else 0),
                "manager_remark": dispatch_info.get("manager_remark"),
                "general_remark": dispatch_info.get("general_remark"),
                "team_lead_remark": dispatch_info.get("team_lead_remark"),
            }
        )

    return {
        "team": team_id,
        "today": today_str,
        "planned": enriched,
        "last_updated": _iso_now(),
    }


@frappe.whitelist()
def list_field_team_actionable_plans(team_id=None):
    """All Rollout Plans for a team that the field user can still act on.

    Used by the Field Execute page (when entered without a specific plan
    id) so the dropdown shows planned + in-execution work — not just
    rows already flipped to "In Execution". Each row is enriched with
    PO Dispatch context (POID, item, project, DUID, qty, customer
    activity type) so the dropdown is actually useful — picking by
    plan id alone gave no context about which job it is.

    No date filter: a plan from yesterday that's still open is just as
    valid to act on as today's. ``plan_status`` is constrained to
    actionable values; *Completed* / *Cancelled* are excluded.
    """
    if not team_id:
        return []

    # Exclude plans where the field team has *already* marked
    # tl_status=Completed (they're done — picking them again would be
    # confusing). Defensive: catches sites where plan_status sync hasn't
    # caught up yet.
    has_access_time = frappe.db.has_column("Rollout Plan", "access_time")
    has_access_period = frappe.db.has_column("Rollout Plan", "access_period")
    has_qc_req = frappe.db.has_column("Rollout Plan", "qc_required")
    has_ciag_req = frappe.db.has_column("Rollout Plan", "ciag_required")
    extra_cols = ""
    if has_access_time:
        extra_cols += ", rp.access_time"
    if has_access_period:
        extra_cols += ", rp.access_period"
    if has_qc_req:
        extra_cols += ", rp.qc_required"
    if has_ciag_req:
        extra_cols += ", rp.ciag_required"
    has_rpt = frappe.db.exists("DocType", "Rollout Plan Team")
    team_match_clause = (
        "(rp.team = %s OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt "
        "WHERE rpt.parent = rp.name AND rpt.team = %s))"
        if has_rpt else "rp.team = %s"
    )
    team_params = (team_id, team_id) if has_rpt else (team_id,)
    plans = frappe.db.sql(
        f"""
        SELECT rp.name, rp.po_dispatch, rp.plan_date, rp.visit_type,
               rp.visit_number, rp.visit_multiplier, rp.target_amount,
               rp.achieved_amount, rp.completion_pct, rp.plan_status{extra_cols}
        FROM `tabRollout Plan` rp
        WHERE {team_match_clause}
          AND rp.plan_status NOT IN ('Cancelled', 'Planning with Issue')
          AND NOT EXISTS (
            SELECT 1 FROM `tabDaily Execution` de
            WHERE de.rollout_plan = rp.name
              AND de.team = %s
              AND (de.tl_status IN ('Completed', 'Cancelled')
                   OR de.execution_status IN ('Completed', 'Cancelled'))
          )
        ORDER BY rp.plan_date DESC, rp.modified DESC
        """,
        (*team_params, team_id),
        as_dict=True,
    )

    if not plans:
        return []

    dispatch_names = list({p.po_dispatch for p in plans if p.po_dispatch})
    dispatch_map = {}
    if dispatch_names:
        placeholders = ", ".join(["%s"] * len(dispatch_names))
        # Include manager_remark (and siblings) so the field user's plan
        # card / picker can surface the IM's "Note for field team".
        extra_remark_cols = ""
        for rk in ("general_remark", "manager_remark", "team_lead_remark"):
            if frappe.db.has_column("PO Dispatch", rk):
                extra_remark_cols += f", {rk}"
        dispatch_rows = frappe.db.sql(
            f"""
            SELECT name, poid, item_code, item_description, qty, project_code,
                   customer, site_name, site_code, center_area, region_type{extra_remark_cols}
            FROM `tabPO Dispatch`
            WHERE name IN ({placeholders})
            """,
            tuple(dispatch_names),
            as_dict=True,
        )
        dispatch_map = {d.name: d for d in dispatch_rows}

    act_map = _batch_item_activity_types(
        [{"item_code": (d or {}).get("item_code")} for d in dispatch_map.values()]
    )

    out = []
    for p in plans:
        d = dispatch_map.get(p.po_dispatch) or {}
        out.append({
            "name": p.name,
            "po_dispatch": p.po_dispatch,
            "plan_date": p.plan_date,
            "plan_status": p.plan_status,
            "visit_type": p.visit_type,
            "visit_number": p.visit_number,
            "target_amount": p.target_amount,
            "poid": d.get("poid"),
            "item_code": d.get("item_code"),
            "item_description": d.get("item_description"),
            "qty": d.get("qty"),
            "project_code": d.get("project_code"),
            "site_code": d.get("site_code"),
            "site_name": d.get("site_name"),
            "activity_type": act_map.get(d.get("item_code") or ""),
            "access_time": p.get("access_time") if has_access_time else None,
            "access_period": p.get("access_period") if has_access_period else None,
            "qc_required": p.get("qc_required", 1) if has_qc_req else 1,
            "ciag_required": p.get("ciag_required", 1) if has_ciag_req else 1,
            "manager_remark": d.get("manager_remark"),
            "general_remark": d.get("general_remark"),
            "team_lead_remark": d.get("team_lead_remark"),
        })
    return out


