# ---------------------------------------------------------------------------
# Execution Time Log — field time on rollout (Next PMS–style; not ERPNext Timesheet)
# ---------------------------------------------------------------------------


def _frappe_dt_to_epoch_ms(value):
    """
    Convert Frappe DB datetime (wall time in site timezone) to UTC epoch milliseconds.
    Used so portal timers stay correct for users in any region (vs parsing strings in local JS).
    """
    if value is None:
        return None
    dt = get_datetime(value)
    if not dt:
        return None
    try:
        from zoneinfo import ZoneInfo

        tzname = frappe.db.get_single_value("System Settings", "time_zone")
        if tzname and getattr(dt, "tzinfo", None) is None:
            dt = dt.replace(tzinfo=ZoneInfo(tzname))
            return int(dt.timestamp() * 1000)
    except Exception:
        pass
    return int(get_datetime(value).timestamp() * 1000)


@frappe.whitelist()
def save_rollout_plan_documents(rollout_plan, documents):
    """Save newline-separated file URLs to Rollout Plan.plan_documents."""
    rollout_plan = (rollout_plan or "").strip()
    if not rollout_plan:
        frappe.throw("rollout_plan is required")
    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    if not (
        "INET IM" in roles or "INET Admin" in roles
        or "System Manager" in roles or "Administrator" in roles
    ):
        frappe.throw("Not permitted", frappe.PermissionError)
    if isinstance(documents, list):
        documents = "\n".join(str(u) for u in documents if u)
    frappe.db.set_value("Rollout Plan", rollout_plan, "plan_documents", documents or "", update_modified=False)
    frappe.db.commit()
    return {"ok": True}


def _auto_create_daily_execution(rollout_plan, team_id):
    """
    Create a minimal Daily Execution when the TL starts a timer.
    Mirrors the new-DE path in update_execution so field validation flags
    (qc_required / ciag_required / region_type) are stamped correctly.
    """
    rp = frappe.db.get_value(
        "Rollout Plan", rollout_plan, ["po_dispatch", "team", "region_type"], as_dict=True
    )
    de = frappe.new_doc("Daily Execution")
    de.rollout_plan = rollout_plan
    de.system_id = rp.get("po_dispatch") if rp else None
    de.team = team_id
    de.tl_status = "In Progress"
    de.execution_status = "In Progress"

    pd_name = rp.get("po_dispatch") if rp else None
    if pd_name:
        im_v = frappe.db.get_value("PO Dispatch", pd_name, "im")
        if im_v and hasattr(de, "im"):
            de.im = im_v

    rp_flag_cols = []
    if frappe.db.has_column("Rollout Plan", "qc_required"):
        rp_flag_cols.append("qc_required")
    if frappe.db.has_column("Rollout Plan", "ciag_required"):
        rp_flag_cols.append("ciag_required")
    if rp_flag_cols:
        rp_flags = frappe.db.get_value("Rollout Plan", rollout_plan, rp_flag_cols, as_dict=True) or {}
        if rp_flags.get("qc_required") == 0 and hasattr(de, "qc_status"):
            de.qc_status = "Not Applicable"
        if rp_flags.get("ciag_required") == 0 and hasattr(de, "ciag_status"):
            de.ciag_status = "Not Applicable"

    if hasattr(de, "region_type"):
        de.region_type = (rp.get("region_type") if rp else None) or None
        if not de.region_type and pd_name:
            pd_row = frappe.db.get_value(
                "PO Dispatch", pd_name, ["region_type", "center_area"], as_dict=True
            )
            if pd_row:
                de.region_type = pd_row.get("region_type") or region_type_from_center_area(
                    pd_row.get("center_area")
                )
        if not de.region_type:
            de.region_type = "Standard"

    de.insert(ignore_permissions=True)


@frappe.whitelist()
def get_server_now():
    """Return server epoch ms and UTC offset so browsers can compute server-timezone-aware times."""
    from datetime import datetime
    server_now = now_datetime()
    now_ms = _frappe_dt_to_epoch_ms(server_now)
    utc_offset_ms = 0
    try:
        from zoneinfo import ZoneInfo
        tzname = frappe.db.get_single_value("System Settings", "time_zone") or "UTC"
        tz = ZoneInfo(tzname)
        offset_sec = tz.utcoffset(datetime.now()).total_seconds()
        utc_offset_ms = int(offset_sec * 1000)
    except Exception:
        pass
    return {"server_now_ms": now_ms, "utc_offset_ms": utc_offset_ms}


def _session_inet_field_team_id():
    """INET Team.team_id for the logged-in field user, if any.

    Strict match on `field_user` (set automatically from the team-lead
    Employee's user_id). If no team explicitly names this user, return
    None — do NOT fuzzy-match by first name in team_name. The earlier
    fallback was a security/correctness bug: an IM user whose first
    name happened to appear in some team's name would inherit all that
    team's plans even though they were never a member.

    Defensive secondary lookup: also accept users linked through the
    `team_members` child table (via Employee.user_id), so a team lead
    set there but not yet propagated to `field_user` still resolves.
    """
    user = frappe.session.user
    if not user or user == "Guest":
        return None
    ft = frappe.get_all(
        "INET Team",
        filters={"field_user": user, "status": "Active"},
        fields=["team_id"],
        limit=1,
    )
    if ft and ft[0].team_id:
        return ft[0].team_id

    # Secondary: match through team_members → Employee.user_id (team
    # lead). Skip silently if Employee table or the join chain isn't
    # available on this site.
    try:
        rows = frappe.db.sql(
            """
            SELECT it.team_id
            FROM `tabINET Team Member` itm
            JOIN `tabINET Team` it ON it.name = itm.parent
            JOIN `tabEmployee` emp ON emp.name = itm.employee
            WHERE emp.user_id = %s
              AND IFNULL(it.status, 'Active') = 'Active'
              AND IFNULL(itm.is_team_lead, 0) = 1
            ORDER BY it.modified DESC
            LIMIT 1
            """,
            (user,), as_dict=True,
        )
        if rows and rows[0].get("team_id"):
            return rows[0]["team_id"]
    except Exception:
        pass

    return None


def _assert_rollout_plan_access_field_team(team_id, rollout_plan):
    if not team_id or not rollout_plan:
        frappe.throw("Team or plan missing", frappe.PermissionError)
    if not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Rollout Plan not found")
    plan_team = frappe.db.get_value("Rollout Plan", rollout_plan, "team")
    if plan_team == team_id:
        return
    # Multi-team plans (see _sync_plan_teams / "Rollout Plan Team" child
    # table) split one plan's qty across 2+ teams — Rollout Plan.team only
    # ever holds the single PRIMARY team, so checking it alone locked every
    # other assigned team out of their own execution with "Not permitted",
    # even though they're legitimately on the plan.
    if frappe.db.exists("DocType", "Rollout Plan Team") and frappe.db.exists(
        "Rollout Plan Team", {"parent": rollout_plan, "parenttype": "Rollout Plan", "team": team_id}
    ):
        return
    frappe.throw("Not permitted", frappe.PermissionError)


def _im_team_ids_for_filter(im_filter=None):
    """team_id values for teams managed by the resolved IM."""
    _im_r, im_ids, _meta = resolve_im_for_session(im_filter)
    if not im_ids:
        return []
    teams = frappe.get_all(
        "INET Team",
        filters={"im": ["in", im_ids], "status": "Active"},
        fields=["team_id"],
        limit_page_length=500,
    )
    return [t.team_id for t in teams if t.team_id]


@frappe.whitelist()
def start_execution_timer(rollout_plan):
    """
    Start a timer for the given Rollout Plan (field user). One running log per user.
    """
    rollout_plan = (rollout_plan or "").strip()
    if not rollout_plan:
        frappe.throw("rollout_plan is required")

    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    if "INET Field Team" not in roles and "Administrator" not in roles:
        frappe.throw("Only field team users can start execution timers", frappe.PermissionError)

    team_id = _session_inet_field_team_id()
    if not team_id:
        frappe.throw("No active field team linked to your user")

    _assert_rollout_plan_access_field_team(team_id, rollout_plan)

    plan_status = frappe.db.get_value("Rollout Plan", rollout_plan, "plan_status")
    if plan_status in ("Completed", "Cancelled"):
        frappe.throw("Cannot start a timer on a completed or cancelled plan.")

    existing = frappe.get_all(
        "Execution Time Log",
        filters={"user": user, "rollout_plan": rollout_plan, "is_running": 1},
        fields=["name"],
        limit=1,
        ignore_permissions=True,
    )
    if existing:
        rp_label = rollout_plan
        frappe.throw(
            f"A timer is already running for {rp_label} ({existing[0].name}). Stop it first."
        )

    log = frappe.new_doc("Execution Time Log")
    log.rollout_plan = rollout_plan
    log.team_id = team_id
    log.user = user
    log.start_time = now_datetime()
    log.is_running = 1
    log.insert(ignore_permissions=True)

    if plan_status in ("Planned", "Planning with Issue", "Extended"):
        frappe.db.set_value("Rollout Plan", rollout_plan, "plan_status", "In Execution", update_modified=False)

    # Auto-create a Daily Execution so IM/PM monitors can track progress immediately.
    # If the IM already created one for this team, leave it alone.
    existing_de = frappe.db.get_value(
        "Daily Execution",
        {"rollout_plan": rollout_plan, "team": team_id},
        "name",
    )
    if not existing_de:
        _auto_create_daily_execution(rollout_plan, team_id)

    frappe.db.commit()

    server_now = now_datetime()
    return {
        "log_name": log.name,
        "rollout_plan": rollout_plan,
        "start_time": str(log.start_time),
        "server_time": str(server_now),
        "start_time_ms": _frappe_dt_to_epoch_ms(log.start_time),
        "server_time_ms": _frappe_dt_to_epoch_ms(server_now),
        "user": user,
    }


@frappe.whitelist()
def stop_execution_timer(log_name):
    """Stop a running execution timer and persist duration."""
    log_name = (log_name or "").strip()
    if not log_name:
        frappe.throw("log_name is required")

    log = frappe.get_doc("Execution Time Log", log_name)
    if not log.is_running:
        frappe.throw("This timer is not running.")

    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    can_stop = log.user == user or "Administrator" in roles or "System Manager" in roles or "INET Admin" in roles
    if not can_stop:
        frappe.throw("You can only stop your own timers.", frappe.PermissionError)

    log.end_time = now_datetime()
    log.is_running = 0
    start = get_datetime(log.start_time)
    end = get_datetime(log.end_time)
    diff_seconds = time_diff_in_seconds(end, start)
    log.duration_minutes = int(diff_seconds / 60)
    log.duration_hours = round(diff_seconds / 3600, 2)
    log.save(ignore_permissions=True)
    frappe.db.commit()

    return {
        "log_name": log.name,
        "rollout_plan": log.rollout_plan,
        "duration_minutes": log.duration_minutes,
        "duration_hours": log.duration_hours,
    }


@frappe.whitelist()
def get_running_execution_timer():
    """All running Execution Time Logs for the current user (array)."""
    user = frappe.session.user
    if not user or user == "Guest":
        return []

    running = frappe.get_all(
        "Execution Time Log",
        filters={"user": user, "is_running": 1},
        fields=["name", "rollout_plan", "start_time", "team_id"],
        order_by="start_time asc",
        ignore_permissions=True,
    )
    if not running:
        return []

    server_now = now_datetime()
    server_now_ms = _frappe_dt_to_epoch_ms(server_now)
    server_time_str = str(server_now)

    # Batch-fetch item descriptions to avoid N+1
    plan_names = list({r.rollout_plan for r in running if r.rollout_plan})
    dispatch_map = {}
    if plan_names:
        ph = ", ".join(["%s"] * len(plan_names))
        rows = frappe.db.sql(
            f"SELECT rp.name, pd.item_description FROM `tabRollout Plan` rp "
            f"LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
            f"WHERE rp.name IN ({ph})",
            tuple(plan_names),
            as_dict=True,
        )
        dispatch_map = {r.name: (r.item_description or "") for r in rows}

    result = []
    for r in running:
        st_ms = _frappe_dt_to_epoch_ms(r.start_time)
        elapsed_seconds = None
        try:
            if server_now_ms is not None and st_ms is not None:
                elapsed_seconds = int(max(0, (server_now_ms - st_ms) // 1000))
        except Exception:
            pass
        result.append({
            "log_name": r.name,
            "rollout_plan": r.rollout_plan,
            "start_time": str(r.start_time) if r.start_time else None,
            "server_time": server_time_str,
            "start_time_ms": st_ms,
            "server_time_ms": server_now_ms,
            "elapsed_seconds": elapsed_seconds,
            "team_id": r.team_id,
            "item_description": dispatch_map.get(r.rollout_plan, ""),
        })
    return result


@frappe.whitelist()
def save_execution_time_log_manual(rollout_plan, start_time, end_time, notes=None):
    """
    Create a completed time log without using the live timer (field user).
    start_time / end_time: ISO or Frappe datetime strings.
    """
    rollout_plan = (rollout_plan or "").strip()
    if not rollout_plan or not start_time or not end_time:
        frappe.throw("rollout_plan, start_time, and end_time are required")

    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    if "INET Field Team" not in roles and "Administrator" not in roles:
        frappe.throw("Not permitted", frappe.PermissionError)

    team_id = _session_inet_field_team_id()
    if not team_id:
        frappe.throw("No active field team linked to your user")

    _assert_rollout_plan_access_field_team(team_id, rollout_plan)

    st = get_datetime(start_time)
    et = get_datetime(end_time)
    if et < st:
        frappe.throw("End time cannot be before start time")

    diff_seconds = time_diff_in_seconds(et, st)
    log = frappe.new_doc("Execution Time Log")
    log.rollout_plan = rollout_plan
    log.team_id = team_id
    log.user = user
    log.start_time = st
    log.end_time = et
    log.is_running = 0
    log.duration_minutes = int(diff_seconds / 60)
    log.duration_hours = round(diff_seconds / 3600, 2)
    log.notes = notes or ""
    log.insert(ignore_permissions=True)
    frappe.db.commit()
    return {"name": log.name, "duration_hours": log.duration_hours}


@frappe.whitelist()
def list_execution_time_logs(filters=None, limit=100, offset=0, _options=None, _summary=None):
    """
    List execution time logs with role-based scoping.
    filters (JSON): team_id, im, user, rollout_plan, from_date, to_date, is_running,
    search (or q) — free-text match across log, user, rollout, PO dispatch fields;
    applied server-side on the full dataset before limit/offset.
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters or "{}")
    if not isinstance(filters, dict):
        filters = {}

    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    is_desk_admin = (
        "Administrator" in roles or "System Manager" in roles or "INET Admin" in roles
    )
    is_im = "INET IM" in roles
    is_field = "INET Field Team" in roles

    db_filters = {}

    if filters.get("rollout_plan"):
        db_filters["rollout_plan"] = filters["rollout_plan"]
    if filters.get("is_running") is not None and filters.get("is_running") != "":
        db_filters["is_running"] = cint(filters["is_running"])

    # Role scoping
    if is_desk_admin:
        tid = filters.get("team_id")
        if tid:
            db_filters["team_id"] = ["in", tid] if isinstance(tid, list) else tid
        if filters.get("user"):
            db_filters["user"] = filters["user"]
    elif is_im:
        team_ids = _im_team_ids_for_filter(filters.get("im"))
        tid = filters.get("team_id")
        if tid:
            allowed = [t for t in (tid if isinstance(tid, list) else [tid]) if t in set(team_ids)]
            if not allowed:
                return {"logs": [], "total": 0}
            db_filters["team_id"] = ["in", allowed] if len(allowed) > 1 else allowed[0]
        else:
            if not team_ids:
                return {"logs": [], "total": 0}
            db_filters["team_id"] = ["in", team_ids]
        if filters.get("user"):
            db_filters["user"] = filters["user"]
    elif is_field:
        db_filters["user"] = user
        ft_team = _session_inet_field_team_id()
        if ft_team:
            db_filters["team_id"] = ft_team
    else:
        frappe.throw("Not permitted", frappe.PermissionError)

    from_date = filters.get("from_date")
    to_date = filters.get("to_date")
    if from_date and to_date:
        db_filters["start_time"] = ["between", [f"{from_date} 00:00:00", f"{to_date} 23:59:59"]]
    elif from_date:
        db_filters["start_time"] = [">=", f"{from_date} 00:00:00"]
    elif to_date:
        db_filters["start_time"] = ["<=", f"{to_date} 23:59:59"]

    search_term_etl = filters.get("search") or filters.get("q") or ""
    like_tokens_etl = _sql_like_tokens(search_term_etl)
    lim_etl = _portal_row_limit(limit, 100)
    off_etl = cint(offset)

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale. Forces the raw-SQL path below (like the free-text search
    # already does) since the plain ORM path can't apply a LIKE filter.
    column_filters_etl = filters.get("column_filters")
    if isinstance(column_filters_etl, str):
        try:
            column_filters_etl = frappe.parse_json(column_filters_etl)
        except Exception:
            column_filters_etl = None
    active_col_filters_etl = {
        k: v for k, v in (column_filters_etl or {}).items() if str(v or "").strip()
    } if isinstance(column_filters_etl, dict) else {}

    # `or _options` / `or _summary`: both are built from the wheres/params
    # assembled in this branch, so it must be taken even when nothing is
    # filtered (otherwise the plain path returns rows instead of options).
    duid_filter_etl = _ensure_list(filters.get("duid"))
    poid_filter_etl = _ensure_list(filters.get("poid"))
    if like_tokens_etl or active_col_filters_etl or duid_filter_etl or poid_filter_etl or _options or _summary:
        wheres = ["1=1"]
        params = []
        joins = (
            "LEFT JOIN `tabRollout Plan` rp ON rp.name = etl.rollout_plan "
            "LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch "
            "LEFT JOIN `tabUser` u ON u.name = etl.user"
        )
        if filters.get("rollout_plan"):
            wheres.append("etl.rollout_plan = %s")
            params.append(filters["rollout_plan"])
        if filters.get("is_running") is not None and filters.get("is_running") != "":
            wheres.append("etl.is_running = %s")
            params.append(cint(filters["is_running"]))

        if is_desk_admin:
            if filters.get("team_id"):
                wheres.append("etl.team_id = %s")
                params.append(filters["team_id"])
            if filters.get("user"):
                wheres.append("etl.user = %s")
                params.append(filters["user"])
        elif is_im:
            team_ids_sq = _im_team_ids_for_filter(filters.get("im"))
            if filters.get("team_id"):
                if filters["team_id"] not in team_ids_sq:
                    return {"logs": [], "total": 0}
                wheres.append("etl.team_id = %s")
                params.append(filters["team_id"])
            else:
                if not team_ids_sq:
                    return {"logs": [], "total": 0}
                ph_sq = ", ".join(["%s"] * len(team_ids_sq))
                wheres.append(f"etl.team_id IN ({ph_sq})")
                params.extend(team_ids_sq)
            if filters.get("user"):
                wheres.append("etl.user = %s")
                params.append(filters["user"])
        elif is_field:
            wheres.append("etl.user = %s")
            params.append(user)
            ft_team_sq = _session_inet_field_team_id()
            if ft_team_sq:
                wheres.append("etl.team_id = %s")
                params.append(ft_team_sq)

        if from_date and to_date:
            wheres.append("etl.start_time BETWEEN %s AND %s")
            params.extend([f"{from_date} 00:00:00", f"{to_date} 23:59:59"])
        elif from_date:
            wheres.append("etl.start_time >= %s")
            params.append(f"{from_date} 00:00:00")
        elif to_date:
            wheres.append("etl.start_time <= %s")
            params.append(f"{to_date} 23:59:59")

        # DUID / POID toolbar filters — need the pd join above, so (like
        # team_id) they only work on this raw-SQL path.
        if duid_filter_etl:
            ph_duid = ", ".join(["%s"] * len(duid_filter_etl))
            wheres.append(f"pd.site_code IN ({ph_duid})")
            params.extend(duid_filter_etl)
        if poid_filter_etl:
            ph_poid = ", ".join(["%s"] * len(poid_filter_etl))
            wheres.append(f"IFNULL(pd.poid, pd.name) IN ({ph_poid})")
            params.extend(poid_filter_etl)

        col_filter_map_etl = {
            "id": "IFNULL(etl.name,'')",
            # Column renders team_name with a team_id fallback (see
            # Timesheets.jsx), so the option list must resolve the same way —
            # otherwise the dropdown offers "Team-01" for a cell reading
            # "Irfan/Rafeeq". INET Team.name == its team_id.
            "team": ("IFNULL(NULLIF((SELECT it_t.team_name FROM `tabINET Team` it_t "
                     "WHERE it_t.name = etl.team_id), ''), IFNULL(etl.team_id,''))"),
            "rollout": "IFNULL(etl.rollout_plan,'')",
            "work": "CONCAT_WS(' ', IFNULL(pd.item_description,''), IFNULL(pd.project_code,''))",
            "work_project": "CONCAT_WS(' ', IFNULL(pd.item_description,''), IFNULL(pd.project_code,''))",
            "duid": "IFNULL(pd.site_code,'')",
            "poid": "IFNULL(pd.poid, pd.name)",
            "project": "IFNULL(pd.project_code,'')",
            "start": "CAST(etl.start_time AS CHAR)",
            "end": "CAST(etl.end_time AS CHAR)",
            "hours": "CAST(etl.duration_hours AS CHAR)",
            # Column shows the user's full name, falling back to the login id.
            # The tabUser join already exists for the search clause.
            "user": "IFNULL(NULLIF(u.full_name, ''), IFNULL(etl.user, ''))",
        }
        # Not backend-filterable: "state"/"status" is a client-computed
        # Running/Done label derived from is_running, not a plain column.
        for col_key, raw_val in active_col_filters_etl.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map_etl.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            pat = _sql_like_pattern(raw_val)
            if not pat:
                continue
            if col_key == "user":
                wheres.append("(IFNULL(etl.user,'') LIKE %s OR IFNULL(u.full_name,'') LIKE %s)")
                params.extend([pat, pat])
                continue
            expr = col_filter_map_etl.get(col_key)
            if not expr:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat)

        if like_tokens_etl:
            concat_etl = (
                "CONCAT_WS(' ', IFNULL(etl.name,''), IFNULL(etl.rollout_plan,''), IFNULL(etl.team_id,''), "
                "IFNULL(etl.user,''), IFNULL(u.full_name,''), IFNULL(etl.notes,''), IFNULL(pd.project_code,''), "
                "IFNULL(pd.item_description,''), IFNULL(pd.site_name,''), IFNULL(pd.po_no,''), "
                "IFNULL(pd.site_code,''), IFNULL(pd.poid,''))"
            )
            ors_etl = " OR ".join([f"{concat_etl} LIKE %s"] * len(like_tokens_etl))
            wheres.append(f"({ors_etl})")
            params.extend(like_tokens_etl)

        if _options:
            _e = col_filter_map_etl.get(_options.get("col_key"))
            if not _e:
                return {"values": [], "has_blanks": False, "total": 0, "supported": False}
            return excel_options_from_query(
                f"`tabExecution Time Log` etl {joins}", " AND ".join(wheres), params, _e,
                bucket=_options.get("bucket"), search=_options.get("search"),
                limit=_options.get("limit"), label_kind=_options.get("label_kind"),
            )
        if _summary:
            # Timesheets are about time, so lead with hours; the open-session
            # count is what tells a manager somebody forgot to clock out.
            return summary_from_query(
                f"`tabExecution Time Log` etl {joins}", " AND ".join(wheres), params, [
                    {"key": "logs", "label": "Logs", "agg": "count"},
                    {"key": "teams", "label": "Teams", "agg": "count_distinct",
                     "expr": "NULLIF(IFNULL(etl.team_id,''), '')"},
                    {"key": "hours", "label": "Hours", "agg": "sum",
                     "expr": "IFNULL(etl.duration_minutes, 0) / 60", "format": "qty", "tone": "good"},
                    # is_running, not a null end_time: a log is open only while
                    # the timer says so.
                    {"key": "open", "label": "Running", "agg": "count_if",
                     "cond": "IFNULL(etl.is_running, 0) = 1", "tone": "warn", "hide_if_zero": True,
                     "hint": "Clocked in, not yet clocked out"},
                ])
        wc = " AND ".join(wheres)
        total = int(
            frappe.db.sql(
                f"SELECT COUNT(*) FROM `tabExecution Time Log` etl {joins} WHERE {wc}",
                tuple(params),
            )[0][0]
        )
        if lim_etl:
            etl_page_sql = f" LIMIT {int(lim_etl)} OFFSET {int(off_etl)}"
        elif off_etl:
            etl_page_sql = f" LIMIT 18446744073709551615 OFFSET {int(off_etl)}"
        else:
            etl_page_sql = ""
        logs = frappe.db.sql(
            f"""
            SELECT etl.name, etl.rollout_plan, etl.team_id, etl.user, etl.start_time, etl.end_time,
                   etl.duration_hours, etl.duration_minutes, etl.is_running, etl.notes
            FROM `tabExecution Time Log` etl
            {joins}
            WHERE {wc}
            ORDER BY etl.start_time DESC
            {etl_page_sql}
            """,
            tuple(params),
            as_dict=True,
        ) or []
    else:
        total = frappe.db.count("Execution Time Log", db_filters) or 0

        ga_etl = dict(
            filters=db_filters,
            fields=[
                "name",
                "rollout_plan",
                "team_id",
                "user",
                "start_time",
                "end_time",
                "duration_hours",
                "duration_minutes",
                "is_running",
                "notes",
            ],
            order_by="start_time desc",
            limit_start=off_etl,
            ignore_permissions=True,
        )
        if lim_etl:
            ga_etl["limit_page_length"] = lim_etl
        logs = frappe.get_all("Execution Time Log", **ga_etl)

    # Batch-enrich: two bulk fetches replace 2 queries per row (plan + dispatch).
    plan_ids = list({r.get("rollout_plan") for r in logs if r.get("rollout_plan")})
    plan_map = {}
    if plan_ids:
        for p in frappe.get_all(
            "Rollout Plan",
            filters={"name": ["in", plan_ids]},
            fields=["name", "po_dispatch", "plan_date", "visit_type", "plan_status"],
            limit_page_length=len(plan_ids) + 1,
        ):
            plan_map[p.name] = p
    dispatch_ids = list({p.po_dispatch for p in plan_map.values() if p.po_dispatch})
    dispatch_map = {}
    if dispatch_ids:
        d_fields = ["name", "item_description", "project_code", "site_name"]
        if frappe.db.has_column("PO Dispatch", "poid"):
            d_fields.append("poid")
        if frappe.db.has_column("PO Dispatch", "site_code"):
            d_fields.append("site_code")
        for d in frappe.get_all(
            "PO Dispatch",
            filters={"name": ["in", dispatch_ids]},
            fields=d_fields,
            limit_page_length=len(dispatch_ids) + 1,
        ):
            dispatch_map[d.name] = d

    for row in logs:
        raw_start = row.get("start_time")
        raw_end = row.get("end_time")
        if row.get("is_running") and raw_start:
            now_ms = _frappe_dt_to_epoch_ms(now_datetime())
            st_ms = _frappe_dt_to_epoch_ms(raw_start)
            if now_ms is not None and st_ms is not None:
                row["elapsed_seconds"] = int(max(0, (now_ms - st_ms) // 1000))
        row["start_time"] = str(raw_start) if raw_start else None
        row["end_time"] = str(raw_end) if raw_end else None
        # get_cached_value uses the in-process Frappe cache, so this is cheap
        row["user_full_name"] = (
            frappe.get_cached_value("User", row.get("user"), "full_name") or row.get("user")
        )
        row["team_name"] = (
            frappe.get_cached_value("INET Team", row.get("team_id"), "team_name") or row.get("team_id")
        ) if row.get("team_id") else None
        pd = plan_map.get(row.get("rollout_plan"))
        if pd:
            row["plan_date"] = str(pd.plan_date) if pd.plan_date else None
            row["visit_type"] = pd.visit_type
            row["plan_status"] = pd.plan_status
            if pd.po_dispatch:
                disp = dispatch_map.get(pd.po_dispatch)
                if disp:
                    row["item_description"] = disp.item_description
                    row["project_code"] = disp.project_code
                    row["site_name"] = disp.site_name
                    row["poid"] = (disp.get("poid") or disp.name) if disp else None
                    row["duid"] = disp.get("site_code") if disp else None
                    row["system_id"] = pd.po_dispatch

    return {"logs": logs, "total": total}


@frappe.whitelist()
def get_team_time_totals(filters=None):
    """
    Hours per TEAM over a date range — "how much did each team work this week
    / this month".

    Built on exactly the same first-in / last-out rule as
    get_daily_time_totals: a person's day is their first clock-in to their
    last clock-out, not a sum of sessions. Those per-person days are then
    summed per team, which makes span_hours man-hours door to door.

    Summing a span ACROSS days would be meaningless (day one's start to day
    seven's end), so the span is always computed within a day first and only
    then added up.

    filters (JSON): team_id, im, user, from_date, to_date, search — identical
    scoping to the other two tabs.

    Returns rows with:
      team_id, team_name, days (distinct dates worked), members (distinct
      users), sessions, span_hours (sum of each member's daily span),
      logged_hours (sum of session durations — "actually working" vs
      span_hours' "present"), idle_hours (the gap between them),
      avg_span_per_day, first_start, last_end, has_running.
    """
    daily = get_daily_time_totals(filters)
    by_team = {}
    for r in daily.get("rows") or []:
        key = r.get("team_id") or ""
        t = by_team.setdefault(key, {
            "team_id": r.get("team_id"),
            "team_name": r.get("team_name") or (r.get("team_id") or "— no team —"),
            "days": set(), "members": set(), "sessions": 0,
            "span_hours": 0.0, "logged_hours": 0.0,
            "first_start": None, "last_end": None, "has_running": False,
        })
        if r.get("log_date"):
            t["days"].add(r["log_date"])
        if r.get("user"):
            t["members"].add(r["user"])
        t["sessions"] += cint(r.get("sessions"))
        # A day still running has no span yet — count its logged time, but do
        # not invent a closing time for it.
        if r.get("span_hours") is not None:
            t["span_hours"] += flt(r["span_hours"])
        t["logged_hours"] += flt(r.get("logged_hours"))
        if r.get("first_start") and (t["first_start"] is None or r["first_start"] < t["first_start"]):
            t["first_start"] = r["first_start"]
        if r.get("last_end") and (t["last_end"] is None or r["last_end"] > t["last_end"]):
            t["last_end"] = r["last_end"]
        t["has_running"] = t["has_running"] or bool(r.get("has_running"))

    out = []
    for t in by_team.values():
        days = len(t["days"])
        span = round(t["span_hours"], 2)
        logged = round(t["logged_hours"], 2)
        out.append({
            "team_id": t["team_id"],
            "team_name": t["team_name"],
            "days": days,
            "members": len(t["members"]),
            "sessions": t["sessions"],
            "span_hours": span,
            "logged_hours": logged,
            # Present but not on a task. Never negative: a session can outlast
            # its own day's span only through bad data, and a negative "idle"
            # would read as nonsense.
            "idle_hours": round(max(span - logged, 0), 2),
            "avg_span_per_day": round(span / days, 2) if days else 0,
            "first_start": t["first_start"],
            "last_end": t["last_end"],
            "has_running": t["has_running"],
        })
    out.sort(key=lambda r: -r["span_hours"])

    return {
        "rows": out,
        "totals": {
            "teams": len(out),
            "days": len({d for t in by_team.values() for d in t["days"]}),
            "members": len({m for t in by_team.values() for m in t["members"]}),
            "sessions": sum(r["sessions"] for r in out),
            "span_hours": round(sum(r["span_hours"] for r in out), 2),
            "logged_hours": round(sum(r["logged_hours"] for r in out), 2),
        },
    }


@frappe.whitelist()
def get_duid_time_totals(filters=None):
    """
    Hours logged per DUID (site) — how much field time actually went into
    each site, under the same role scoping / date range as the other two
    Execution Time Log tabs.

    Deliberately NOT built on get_daily_time_totals' per-(date,user) rows
    the way get_team_time_totals is: those rows carry no DUID at all (a
    person's day-span can cover more than one site — see duid_count on that
    endpoint), so there is nothing to key a DUID roll-up off there. This is
    its own aggregate straight off Execution Time Log, joined through
    Rollout Plan -> PO Dispatch to resolve site_code.

    Also deliberately NOT a "first-in / last-out" presence span the way Team
    Totals is: a span only means something for ONE PERSON on ONE DAY. A DUID
    is visited by different teams on different days, so there is no single
    door-to-door window to compute for it — only a straight SUM of logged
    session time, which every log row can contribute to unambiguously
    (each one belongs to exactly one DUID via its rollout plan).

    filters: team_id, im, user, duid, poid, from_date, to_date, search — same
    shape as list_execution_time_logs / get_daily_time_totals.

    Returns rows with: duid, project_code, site_name, teams (distinct teams
    that logged time here), poids (distinct PO lines), days (distinct dates
    worked), sessions, logged_hours, first_date, last_date, has_running.
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters or "{}")
    if not isinstance(filters, dict):
        filters = {}

    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    is_desk_admin = "Administrator" in roles or "System Manager" in roles or "INET Admin" in roles
    is_im = "INET IM" in roles
    is_field = "INET Field Team" in roles

    empty = {"rows": [], "totals": {"duids": 0, "sessions": 0, "logged_hours": 0.0}}

    # A log whose chain doesn't resolve to a DUID has nothing to bucket by —
    # excluded here rather than surfaced as a confusing blank-label row.
    wheres = ["1=1", "IFNULL(pd.site_code,'') != ''"]
    params = []

    if is_desk_admin:
        im_pick = filters.get("im")
        if im_pick:
            im_team_ids = _im_team_ids_for_filter(im_pick)
            if not im_team_ids:
                return empty
            ph = ", ".join(["%s"] * len(im_team_ids))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(im_team_ids)
        tid = filters.get("team_id")
        if tid:
            vals = tid if isinstance(tid, list) else [tid]
            ph = ", ".join(["%s"] * len(vals))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(vals)
        if filters.get("user"):
            wheres.append("etl.user = %s")
            params.append(filters["user"])
    elif is_im:
        team_ids = _im_team_ids_for_filter(filters.get("im"))
        tid = filters.get("team_id")
        if tid:
            allowed = [t for t in (tid if isinstance(tid, list) else [tid]) if t in set(team_ids)]
            if not allowed:
                return empty
            ph = ", ".join(["%s"] * len(allowed))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(allowed)
        else:
            if not team_ids:
                return empty
            ph = ", ".join(["%s"] * len(team_ids))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(team_ids)
        if filters.get("user"):
            wheres.append("etl.user = %s")
            params.append(filters["user"])
    elif is_field:
        wheres.append("etl.user = %s")
        params.append(user)
        ft_team = _session_inet_field_team_id()
        if ft_team:
            wheres.append("etl.team_id = %s")
            params.append(ft_team)
    else:
        frappe.throw("Not permitted", frappe.PermissionError)

    duid_vals = _ensure_list(filters.get("duid"))
    if duid_vals:
        ph = ", ".join(["%s"] * len(duid_vals))
        wheres.append(f"pd.site_code IN ({ph})")
        params.extend(duid_vals)
    poid_vals = _ensure_list(filters.get("poid"))
    if poid_vals:
        ph = ", ".join(["%s"] * len(poid_vals))
        wheres.append(f"IFNULL(pd.poid, pd.name) IN ({ph})")
        params.extend(poid_vals)

    from_date = filters.get("from_date")
    to_date = filters.get("to_date")
    if from_date:
        wheres.append("DATE(etl.start_time) >= %s")
        params.append(from_date)
    if to_date:
        wheres.append("DATE(etl.start_time) <= %s")
        params.append(to_date)

    search = (filters.get("search") or filters.get("q") or "").strip()
    if search:
        like_tokens = _sql_like_tokens(search)
        if like_tokens:
            concat_expr = (
                "CONCAT_WS(' ', IFNULL(pd.site_code,''), IFNULL(pd.poid,''), IFNULL(pd.project_code,''), "
                "IFNULL(etl.user,''), IFNULL(u.full_name,''), IFNULL(etl.team_id,''))"
            )
            ors = " OR ".join([f"{concat_expr} LIKE %s"] * len(like_tokens))
            wheres.append(f"({ors})")
            params.extend(like_tokens)

    rows = frappe.db.sql(
        f"""
        SELECT pd.site_code AS duid,
               MAX(pd.project_code) AS project_code,
               MAX(pd.site_name) AS site_name,
               COUNT(DISTINCT etl.team_id) AS teams,
               COUNT(DISTINCT IFNULL(pd.poid, pd.name)) AS poids,
               COUNT(DISTINCT DATE(etl.start_time)) AS days,
               COUNT(*) AS sessions,
               SUM(IFNULL(etl.duration_minutes, 0)) / 60 AS logged_hours,
               MIN(DATE(etl.start_time)) AS first_date,
               MAX(DATE(etl.start_time)) AS last_date,
               MAX(IFNULL(etl.is_running, 0)) AS has_running
        FROM `tabExecution Time Log` etl
        LEFT JOIN `tabRollout Plan` rp ON rp.name = etl.rollout_plan
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabUser` u ON u.name = etl.user
        WHERE {' AND '.join(wheres)}
        GROUP BY pd.site_code
        ORDER BY logged_hours DESC
        """,
        tuple(params),
        as_dict=True,
    ) or []

    out = []
    for r in rows:
        out.append({
            "duid": r.get("duid"),
            "project_code": r.get("project_code"),
            "site_name": r.get("site_name"),
            "teams": cint(r.get("teams")),
            "poids": cint(r.get("poids")),
            "days": cint(r.get("days")),
            "sessions": cint(r.get("sessions")),
            "logged_hours": round(flt(r.get("logged_hours")), 2),
            "first_date": str(r.get("first_date")) if r.get("first_date") else None,
            "last_date": str(r.get("last_date")) if r.get("last_date") else None,
            "has_running": bool(r.get("has_running")),
        })

    return {
        "rows": out,
        # Only the two aggregates that are unambiguous to sum ACROSS DUIDs —
        # "teams" and "days" are per-row DISTINCT counts, and summing those
        # across rows would double-count a team/day that touched more than
        # one site, so they are deliberately left off this totals block.
        "totals": {
            "duids": len(out),
            # Safe to sum: every PO Dispatch (and so every poid) has exactly
            # one site_code, so a poid can never appear under more than one
            # DUID group here — unlike "teams" or "days", which a single
            # team/date CAN legitimately span more than one site.
            "poids": sum(r["poids"] for r in out),
            "sessions": sum(r["sessions"] for r in out),
            "logged_hours": round(sum(r["logged_hours"] for r in out), 2),
        },
    }


@frappe.whitelist()
def get_daily_time_totals(filters=None):
    """
    Daily hours per (date, user): first clock-in to last clock-out that day,
    not a sum of individual session durations — "door to door" time, so a
    day with two visits and a gap between them still reads as one span
    covering the whole day, the way a manager actually thinks about
    "how many hours did this person work today".

    filters (JSON): team_id, im, user, from_date, to_date, search — same
    role scoping as list_execution_time_logs (Admin sees everyone, IM sees
    their own teams, Field Team sees only their own logs).

    Returns rows with:
      log_date, user, user_full_name, team_id, team_name,
      first_start, last_end (None if every session that day is still
      running — nothing to close the span with yet),
      span_hours (last_end - first_start; None if last_end is None),
      logged_hours (sum of each session's own duration_hours — the
      "actually working" time, vs span_hours' "present at all" time; the
      gap between them is idle/break time within the day),
      sessions (count), has_running (bool — today's number can still grow).
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters or "{}")
    if not isinstance(filters, dict):
        filters = {}

    user = frappe.session.user
    roles = set(frappe.get_roles(user))
    is_desk_admin = "Administrator" in roles or "System Manager" in roles or "INET Admin" in roles
    is_im = "INET IM" in roles
    is_field = "INET Field Team" in roles

    wheres = ["1=1"]
    params = []

    if is_desk_admin:
        # A PM sees every team by default, and can narrow to one IM's teams —
        # the IM branch below already scopes that way, so an admin picking an
        # IM should land on exactly the same set that IM sees.
        im_pick = filters.get("im")
        if im_pick:
            im_team_ids = _im_team_ids_for_filter(im_pick)
            if not im_team_ids:
                return {"rows": []}
            ph = ", ".join(["%s"] * len(im_team_ids))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(im_team_ids)
        tid = filters.get("team_id")
        if tid:
            vals = tid if isinstance(tid, list) else [tid]
            ph = ", ".join(["%s"] * len(vals))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(vals)
        if filters.get("user"):
            wheres.append("etl.user = %s")
            params.append(filters["user"])
    elif is_im:
        team_ids = _im_team_ids_for_filter(filters.get("im"))
        tid = filters.get("team_id")
        if tid:
            allowed = [t for t in (tid if isinstance(tid, list) else [tid]) if t in set(team_ids)]
            if not allowed:
                return {"rows": []}
            ph = ", ".join(["%s"] * len(allowed))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(allowed)
        else:
            if not team_ids:
                return {"rows": []}
            ph = ", ".join(["%s"] * len(team_ids))
            wheres.append(f"etl.team_id IN ({ph})")
            params.extend(team_ids)
        if filters.get("user"):
            wheres.append("etl.user = %s")
            params.append(filters["user"])
    elif is_field:
        wheres.append("etl.user = %s")
        params.append(user)
        ft_team = _session_inet_field_team_id()
        if ft_team:
            wheres.append("etl.team_id = %s")
            params.append(ft_team)
    else:
        frappe.throw("Not permitted", frappe.PermissionError)

    from_date = filters.get("from_date")
    to_date = filters.get("to_date")
    if from_date:
        wheres.append("DATE(etl.start_time) >= %s")
        params.append(from_date)
    if to_date:
        wheres.append("DATE(etl.start_time) <= %s")
        params.append(to_date)

    # DUID / POID filters — need the Rollout Plan -> PO Dispatch chain, which
    # this query didn't previously join at all. A LEFT JOIN on a Link field
    # (rollout_plan, then po_dispatch) is always 1:1, so adding it can never
    # fan out a row — safe to include unconditionally rather than branching
    # like list_execution_time_logs does.
    duid_vals = _ensure_list(filters.get("duid"))
    if duid_vals:
        ph = ", ".join(["%s"] * len(duid_vals))
        wheres.append(f"pd.site_code IN ({ph})")
        params.extend(duid_vals)
    poid_vals = _ensure_list(filters.get("poid"))
    if poid_vals:
        ph = ", ".join(["%s"] * len(poid_vals))
        wheres.append(f"IFNULL(pd.poid, pd.name) IN ({ph})")
        params.extend(poid_vals)

    search = (filters.get("search") or filters.get("q") or "").strip()
    if search:
        like_tokens = _sql_like_tokens(search)
        if like_tokens:
            concat_expr = (
                "CONCAT_WS(' ', IFNULL(etl.user,''), IFNULL(u.full_name,''), IFNULL(etl.team_id,''), "
                "IFNULL(pd.site_code,''), IFNULL(pd.poid,''))"
            )
            ors = " OR ".join([f"{concat_expr} LIKE %s"] * len(like_tokens))
            wheres.append(f"({ors})")
            params.extend(like_tokens)

    rows = frappe.db.sql(
        f"""
        SELECT DATE(etl.start_time) AS log_date,
               etl.user,
               etl.team_id,
               MIN(etl.start_time) AS first_start,
               MAX(CASE WHEN etl.is_running = 0 THEN etl.end_time END) AS last_end,
               SUM(IFNULL(etl.duration_minutes, 0)) / 60 AS logged_hours,
               COUNT(*) AS sessions,
               MAX(IFNULL(etl.is_running, 0)) AS has_running,
               COUNT(DISTINCT pd.site_code) AS duid_count
        FROM `tabExecution Time Log` etl
        LEFT JOIN `tabUser` u ON u.name = etl.user
        LEFT JOIN `tabRollout Plan` rp ON rp.name = etl.rollout_plan
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        WHERE {' AND '.join(wheres)}
        GROUP BY DATE(etl.start_time), etl.user, etl.team_id
        ORDER BY log_date DESC, first_start DESC
        """,
        tuple(params),
        as_dict=True,
    ) or []

    out = []
    for r in rows:
        first_start = r.get("first_start")
        last_end = r.get("last_end")
        span_hours = None
        if first_start and last_end:
            span_hours = round(time_diff_in_seconds(get_datetime(last_end), get_datetime(first_start)) / 3600, 2)
        out.append({
            "log_date": str(r.get("log_date")) if r.get("log_date") else None,
            "user": r.get("user"),
            "user_full_name": frappe.get_cached_value("User", r.get("user"), "full_name") or r.get("user"),
            "team_id": r.get("team_id"),
            "team_name": (frappe.get_cached_value("INET Team", r.get("team_id"), "team_name") or r.get("team_id")) if r.get("team_id") else None,
            "first_start": str(first_start) if first_start else None,
            "last_end": str(last_end) if last_end else None,
            "span_hours": span_hours,
            "logged_hours": round(flt(r.get("logged_hours")), 2),
            "sessions": cint(r.get("sessions")),
            "has_running": bool(r.get("has_running")),
            # >1 means this presence window covered more than one DUID that
            # day (e.g. two visits) — the span above is still a valid
            # door-to-door number, it just isn't attributable to one site.
            "duid_count": cint(r.get("duid_count")),
        })

    return {"rows": out}


# ---------------------------------------------------------------------------
# Timesheet APIs — ERPNext Timesheet (legacy; portal uses Execution Time Log)
# ---------------------------------------------------------------------------

@frappe.whitelist()
def create_timesheet(payload):
    """
    Create an ERPNext Timesheet with time_logs.

    payload = {
        "employee": "HR-EMP-00001" or team name,
        "team": "Team-01",
        "time_logs": [
            {
                "activity_type": "...",
                "from_time": "2026-04-05 08:00:00",
                "to_time": "2026-04-05 17:00:00",
                "hours": 9,
                "project": "PRJ-001",
                "description": "..."
            }
        ]
    }
    """
    if isinstance(payload, str):
        payload = frappe.parse_json(payload)
    payload = payload or {}

    team = payload.get("team")
    time_logs = payload.get("time_logs") or []

    if not time_logs:
        frappe.throw("At least one time log is required.")

    doc = frappe.new_doc("Timesheet")
    doc.company = frappe.defaults.get_global_default("company") or "INET"

    # Try to resolve employee from team
    employee = payload.get("employee")
    if not employee and frappe.db.exists("DocType", "Employee"):
        employee = frappe.db.get_value("Employee", {"user_id": frappe.session.user}, "name")
    if not employee and team:
        # Look up employee linked to this team (if any)
        emp = frappe.db.get_value("Employee", {"employee_name": ["like", f"%{team}%"]}, "name")
        if emp:
            employee = emp

    if employee:
        doc.employee = employee

    # Custom field to track which INET team submitted
    if hasattr(doc, "custom_inet_team"):
        doc.custom_inet_team = team

    for log in time_logs:
        doc.append("time_logs", {
            "activity_type": log.get("activity_type", "Execution"),
            "from_time": log.get("from_time"),
            "to_time": log.get("to_time"),
            "hours": flt(log.get("hours", 0)),
            "project": log.get("project"),
            "description": log.get("description", ""),
        })

    doc.insert(ignore_permissions=True)
    frappe.db.commit()

    return {"name": doc.name, "status": doc.status}


@frappe.whitelist()
def list_timesheets(filters=None):
    """
    List timesheets with optional filters.

    filters = {
        "team": "Team-01",
        "im": "Ajmal",
        "from_date": "2026-04-01",
        "to_date": "2026-04-30",
        "status": "Draft",
    }
    """
    if isinstance(filters, str):
        filters = frappe.parse_json(filters)
    if not isinstance(filters, dict):
        filters = {}

    db_filters = {}
    if filters.get("status"):
        db_filters["docstatus"] = 1 if filters["status"] == "Submitted" else 0

    include_bounds = filters.pop("include_log_bounds", None) or filters.pop("include_log_times", None)

    timesheets = frappe.get_all(
        "Timesheet",
        filters=db_filters,
        fields=[
            "name", "employee", "employee_name", "company",
            "total_hours", "total_billable_hours", "total_billed_hours",
            "status", "start_date", "end_date", "creation", "modified",
        ],
        order_by="modified desc",
        limit_page_length=200,
    )

    if include_bounds and timesheets and frappe.db.exists("DocType", "Timesheet Detail"):
        names = [t.name for t in timesheets]
        try:
            ph = ", ".join(["%s"] * len(names))
            bounds = frappe.db.sql(
                f"""
                SELECT parent, MIN(from_time) AS log_start, MAX(to_time) AS log_end
                FROM `tabTimesheet Detail`
                WHERE parent IN ({ph}) AND parenttype = 'Timesheet'
                GROUP BY parent
                """,
                tuple(names),
                as_dict=True,
            )
            bmap = {b.parent: b for b in (bounds or [])}
            for ts in timesheets:
                b = bmap.get(ts.name)
                if b:
                    ts["log_start"] = b.log_start
                    ts["log_end"] = b.log_end
        except Exception:
            pass

    # Filter by date range if provided
    from_date = filters.get("from_date")
    to_date = filters.get("to_date")

    if from_date or to_date:
        filtered = []
        for ts in timesheets:
            sd = str(ts.start_date) if ts.start_date else ""
            if from_date and sd < from_date:
                continue
            if to_date and sd > to_date:
                continue
            filtered.append(ts)
        timesheets = filtered

    # If team filter, fetch time_logs for each and check project/team link
    team_filter = filters.get("team")
    im_filter = filters.get("im")

    if team_filter or im_filter:
        team_ids = set()
        if im_filter:
            _im_r, im_ids, _ = resolve_im_for_session(im_filter)
            lookup = im_ids or [im_filter]
            im_teams = frappe.get_all(
                "INET Team",
                filters={"im": ["in", lookup], "status": "Active"},
                fields=["team_id", "team_name"],
            )
            for t in im_teams:
                if t.get("team_id"):
                    team_ids.add(t["team_id"])
                if t.get("team_name"):
                    team_ids.add(t["team_name"])
        if team_filter:
            team_ids.add(team_filter)

        if im_filter and not team_ids:
            return []

        if team_ids:
            filtered = []
            for ts in timesheets:
                emp_name = (ts.employee_name or "").lower()
                if any(str(tid).lower() in emp_name for tid in team_ids if tid):
                    filtered.append(ts)
            timesheets = filtered

    return timesheets


@frappe.whitelist()
def approve_timesheet(name):
    """Submit/approve a timesheet."""
    doc = frappe.get_doc("Timesheet", name)
    if doc.docstatus == 0:
        doc.submit()
        frappe.db.commit()
    return {"name": doc.name, "status": "Submitted"}


@frappe.whitelist()
def get_timesheet_detail(name):
    """Get full timesheet with time_logs."""
    doc = frappe.get_doc("Timesheet", name)
    return doc.as_dict()


# Fields the IM is allowed to edit on their own INET Team. team_id / im /
# team_type / subcontractor / field_user / isdp_account / daily_cost are
# admin-only — IMs only manage display name, status, members and notes.
_IM_TEAM_EDITABLE_FIELDS = (
    "team_name",
    "status",
    "note",
)


@frappe.whitelist()
def update_im_team(name, payload=None):
    """Update an INET Team owned by the logged-in IM.

    Only the IM whose identifiers match the team's `im` field may edit, and
    only the safelist of fields above. ``team_members`` (when provided)
    replaces the child table; expects ``[{employee, designation, is_team_lead}, ...]``.
    """
    if not name:
        frappe.throw("name is required")
    if isinstance(payload, str):
        payload = frappe.parse_json(payload) if payload else {}
    payload = payload or {}

    _im_resolved, im_identifiers = _require_inet_im_session()

    team = frappe.db.get_value("INET Team", name, ["name", "im"], as_dict=True)
    if not team:
        frappe.throw(f"INET Team not found: {name}")
    if (team.im or "") not in im_identifiers:
        frappe.throw("Not permitted: this team is not assigned to you", frappe.PermissionError)

    members_raw = payload.get("team_members")
    members_changed = members_raw is not None
    clean = []

    updates = {}
    for fname in _IM_TEAM_EDITABLE_FIELDS:
        if fname not in payload:
            continue
        val = payload.get(fname)
        if fname == "daily_cost":
            try:
                val = flt(val)
            except Exception:
                continue
        elif fname == "daily_cost_applies":
            val = 1 if val in (1, "1", True, "true", "yes", "on") else 0
        elif isinstance(val, str):
            val = val.strip()
        updates[fname] = val

    if updates:
        frappe.db.set_value("INET Team", name, updates, update_modified=True)

    if members_changed:
        seen_emp = set()
        team_leads = 0
        for m in (members_raw or []):
            emp = (m or {}).get("employee")
            if not emp:
                continue
            emp = str(emp).strip()
            if not emp or emp in seen_emp:
                continue
            seen_emp.add(emp)
            is_lead = 1 if (m.get("is_team_lead") in (1, "1", True, "true", "yes", "on")) else 0
            if is_lead:
                team_leads += 1
            desig = (m.get("designation") or "").strip() or None
            clean.append({
                "employee": emp,
                "designation": desig,
                "is_team_lead": is_lead,
            })
        if team_leads > 1:
            frappe.throw("Only one team member can be marked as Team Lead.")

        # Replace the child table via the document API so Frappe handles
        # name allocation, validate hooks (e.g. lead-syncs-field_user) and
        # parent linkage automatically.
        doc = frappe.get_doc("INET Team", name)
        doc.set("team_members", [])
        for row in clean:
            doc.append("team_members", row)
        doc.save(ignore_permissions=True)

    frappe.db.commit()
    return {
        "name": name,
        "updated": len(updates),
        "fields": list(updates.keys()),
        "members_replaced": members_changed,
        "member_count": len(clean) if members_changed else None,
    }


@frappe.whitelist()
def get_im_team_detail(name):
    """Return one INET Team's data including members for the edit modal.
    Restricted to teams owned by the logged-in IM."""
    if not name:
        frappe.throw("name is required")
    _im_resolved, im_identifiers = _require_inet_im_session()
    team = frappe.db.get_value("INET Team", name, ["name", "im"], as_dict=True)
    if not team or (team.im or "") not in im_identifiers:
        frappe.throw("Not permitted: this team is not assigned to you", frappe.PermissionError)
    doc = frappe.get_doc("INET Team", name).as_dict()
    members = []
    for m in (doc.get("team_members") or []):
        emp_full = ""
        if m.get("employee"):
            emp_full = frappe.db.get_value("Employee", m.get("employee"), "employee_name") or ""
        members.append({
            "employee": m.get("employee"),
            "employee_name": emp_full,
            "designation": m.get("designation") or "",
            "is_team_lead": 1 if m.get("is_team_lead") else 0,
        })

    # Same query as admin_get_team_detail — this popup was missing it
    # entirely (IM's view never showed active plans, unlike the admin one).
    active_plans = frappe.db.sql(
        """
        SELECT
            rp.name AS plan_name,
            rp.plan_date,
            rp.plan_status,
            pd.project_code,
            COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') AS project_domain,
            IFNULL(pcc.project_name,'') AS project_name,
            COALESCE(NULLIF(pd.poid,''), pd.name) AS poid,
            pd.site_code
        FROM `tabRollout Plan` rp
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
        WHERE (rp.team = %s OR EXISTS (
                SELECT 1 FROM `tabRollout Plan Team` rpt
                WHERE rpt.parent = rp.name AND rpt.team = %s
              ))
          AND rp.plan_status IN ('Planned','In Execution','Extended')
        ORDER BY rp.plan_date DESC
        LIMIT 20
        """,
        (name, name),
        as_dict=True,
    )

    return {
        "name": doc.get("name"),
        "team_id": doc.get("team_id"),
        "team_name": doc.get("team_name"),
        "team_type": doc.get("team_type"),
        "im": doc.get("im"),
        "subcontractor": doc.get("subcontractor"),
        "isdp_account": doc.get("isdp_account"),
        "field_user": doc.get("field_user"),
        "status": doc.get("status"),
        "daily_cost": doc.get("daily_cost"),
        "daily_cost_applies": doc.get("daily_cost_applies"),
        "note": doc.get("note"),
        "team_members": members,
        "active_plans": [dict(r) for r in (active_plans or [])],
    }


@frappe.whitelist()
def admin_list_employees_for_picker(search=None, limit=100):
    """Employee picker accessible to PM/admin roles (no IM ownership check)."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    if search and search.strip():
        s = f"%{search.strip()}%"
        emps = frappe.db.sql(
            """
            SELECT name, employee_name, designation
            FROM `tabEmployee`
            WHERE status = 'Active'
              AND (name LIKE %s OR IFNULL(employee_name,'') LIKE %s)
            ORDER BY employee_name ASC
            LIMIT %s
            """,
            (s, s, int(limit)),
            as_dict=True,
        )
    else:
        emps = frappe.get_all(
            "Employee",
            filters={"status": "Active"},
            fields=["name", "employee_name", "designation"],
            order_by="employee_name asc",
            limit_page_length=int(limit),
        )
    return emps or []


@frappe.whitelist()
def list_im_masters_for_picker(search=None, limit=200):
    """IM Master picker for admin forms — returns name + full_name."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    if search and search.strip():
        s = f"%{search.strip()}%"
        ims = frappe.db.sql(
            """
            SELECT name, IFNULL(full_name, name) AS full_name
            FROM `tabIM Master`
            WHERE name LIKE %s OR IFNULL(full_name,'') LIKE %s
            ORDER BY full_name ASC
            LIMIT %s
            """,
            (s, s, int(limit)),
            as_dict=True,
        )
    else:
        ims = frappe.db.sql(
            """
            SELECT name, IFNULL(full_name, name) AS full_name
            FROM `tabIM Master`
            ORDER BY full_name ASC
            LIMIT %s
            """,
            (int(limit),),
            as_dict=True,
        )
    return ims or []


