# ──────────────────────────────────────────────────────────────────────
# POID-level remarks (general / manager / team_lead) — role-scoped
# ──────────────────────────────────────────────────────────────────────
_REMARK_TYPES = {"general", "manager", "team_lead"}


def _resolve_dispatch_for_remarks(po_dispatch):
    """Find the PO Dispatch row for a POID or system_id and return its name."""
    name = (po_dispatch or "").strip()
    if not name:
        frappe.throw("po_dispatch is required")
    if frappe.db.exists("PO Dispatch", name):
        return name
    hit = frappe.db.get_value("PO Dispatch", {"poid": name}, "name")
    if hit:
        return hit
    frappe.throw(f"PO Dispatch not found: {name}")


def _user_role_class():
    """Coarse role bucket for remark visibility/edit rules."""
    roles = set(frappe.get_roles(frappe.session.user))
    if "Administrator" in roles or "System Manager" in roles or "INET Admin" in roles:
        return "pm"
    if "INET IM" in roles:
        return "im"
    if "INET Field Team" in roles:
        return "field"
    return None


@frappe.whitelist()
def get_po_remarks(po_dispatch):
    """Return the remark trio for a POID, masking fields the caller can't read.

    Visibility:
      - PM / admin: sees all three; edits any of the three
      - IM:        sees all three; edits manager + team_lead
      - Field:     sees only team_lead; edits team_lead
    """
    role = _user_role_class()
    if role is None:
        frappe.throw("Not permitted", frappe.PermissionError)
    name = _resolve_dispatch_for_remarks(po_dispatch)
    remark_cols = [c for c in ("general_remark", "manager_remark", "team_lead_remark")
                   if frappe.db.has_column("PO Dispatch", c)]
    row = frappe.db.get_value(
        "PO Dispatch", name,
        ["name", "poid", *remark_cols],
        as_dict=True,
    ) or {}

    visible = {
        "po_dispatch": row.get("name"),
        "poid": row.get("poid") or row.get("name"),
        "role": role,
    }
    if role in ("pm", "im"):
        visible["general_remark"] = row.get("general_remark") or ""
        visible["manager_remark"] = row.get("manager_remark") or ""
        visible["team_lead_remark"] = row.get("team_lead_remark") or ""
    elif role == "field":
        visible["team_lead_remark"] = row.get("team_lead_remark") or ""
    visible["editable"] = {
        # general:   PM only
        # manager:   PM + IM
        # team_lead: PM + IM + Field
        "general_remark": role == "pm",
        "manager_remark": role in ("pm", "im"),
        "team_lead_remark": role in ("pm", "im", "field"),
    }
    return visible


@frappe.whitelist()
def update_po_remark(po_dispatch, remark_type, value):
    """Set one remark on a POID. Permissions:
        - general    → PM
        - manager    → PM + IM
        - team_lead  → PM + IM + Field
    """
    role = _user_role_class()
    if role is None:
        frappe.throw("Not permitted", frappe.PermissionError)
    name = _resolve_dispatch_for_remarks(po_dispatch)
    rtype = (remark_type or "").strip().lower()
    if rtype not in _REMARK_TYPES:
        frappe.throw("Invalid remark_type")
    field = f"{rtype}_remark"

    allowed = (
        (rtype == "general" and role == "pm")
        or (rtype == "manager" and role in ("pm", "im"))
        or (rtype == "team_lead" and role in ("pm", "im", "field"))
    )
    if not allowed:
        frappe.throw("Not permitted to edit this remark", frappe.PermissionError)

    text = str(value or "")
    if len(text) > 8000:
        text = text[:8000]
    if not frappe.db.has_column("PO Dispatch", field):
        frappe.throw(
            f"Field {field} is not yet available on this site — run "
            "`bench --site <site> migrate` to add the role-scoped remark columns.",
            frappe.ValidationError,
        )
    frappe.db.set_value("PO Dispatch", name, field, text, update_modified=True)
    frappe.db.commit()
    return {"po_dispatch": name, "remark_type": rtype, "value": text}


# ──────────────────────────────────────────────────────────────────────
# Sub-Contract flow — IM-driven, lives outside the rollout chain
# ──────────────────────────────────────────────────────────────────────
def _can_assign_backend_dispatch(role, im_identifiers, pd):
    if role == "pm":
        return True
    if role != "im":
        return False
    pd_im = (pd.get("im") or "")
    if pd_im and pd_im not in (im_identifiers or []):
        return False
    return True


@frappe.whitelist()
def get_my_backend_capability(im=None):
    """Return whether the current session can sub-contract POIDs.

    PM/admin: always True. IM: True only if `IM Master.can_assign_backend = 1`.
    Field: never.
    """
    role = _user_role_class()
    if role == "pm":
        return {"role": role, "can_assign_backend": True, "im": None}
    if role != "im":
        return {"role": role, "can_assign_backend": False, "im": None}
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    if not im_identifiers:
        return {"role": role, "can_assign_backend": False, "im": None}
    # `im_resolved` is the IM Master name; `im_identifiers` is an unordered
    # set-derived list (may contain email / full_name / etc.). Probe both.
    target = im_resolved if im_resolved and frappe.db.exists("IM Master", im_resolved) else None
    if not target:
        for ident in im_identifiers:
            if frappe.db.exists("IM Master", ident):
                target = ident
                break
    flag = 0
    if target:
        flag = cint(frappe.db.get_value("IM Master", target, "can_assign_backend") or 0)
    return {"role": role, "can_assign_backend": bool(flag), "im": target}


@frappe.whitelist()
def get_my_direct_close_capability(im=None):
    """Return whether the current session can directly close PO Dispatches.

    PM/admin: always True. IM: True only if `IM Master.can_direct_close = 1`.
    Field: never.
    """
    role = _user_role_class()
    if role == "pm":
        return {"role": role, "can_direct_close": True, "can_milestone_close": True, "im": None}
    if role != "im":
        return {"role": role, "can_direct_close": False, "can_milestone_close": False, "im": None}
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    if not im_identifiers:
        return {"role": role, "can_direct_close": False, "can_milestone_close": False, "im": None}
    target = im_resolved if im_resolved and frappe.db.exists("IM Master", im_resolved) else None
    if not target:
        for ident in im_identifiers:
            if frappe.db.exists("IM Master", ident):
                target = ident
                break
    flag = 0
    milestone_flag = 0
    if target:
        vals = frappe.db.get_value(
            "IM Master", target,
            ["can_direct_close", "can_milestone_close"],
            as_dict=True,
        ) or {}
        flag = cint(vals.get("can_direct_close") or 0)
        milestone_flag = cint(vals.get("can_milestone_close") or 0)
    return {"role": role, "can_direct_close": bool(flag), "can_milestone_close": bool(milestone_flag), "im": target}


def _im_master_flag(im_resolved, im_identifiers, fieldname):
    """Resolve the session's IM Master record and read one Check field off it.

    Returns (bool flag, IM Master name or None). Shared by the capability
    getters and the matching server-side enforcement so both agree on which
    record they resolved to.
    """
    target = im_resolved if im_resolved and frappe.db.exists("IM Master", im_resolved) else None
    if not target:
        for ident in (im_identifiers or []):
            if frappe.db.exists("IM Master", ident):
                target = ident
                break
    if not target:
        return False, None
    return bool(cint(frappe.db.get_value("IM Master", target, fieldname) or 0)), target


@frappe.whitelist()
def get_my_record_execution_capability(im=None):
    """Return whether the current session can bulk-record execution from the
    Rollout Execution page (IMPlanning.jsx "Record execution" action).

    PM/admin: always True. IM: True only if `IM Master.can_record_execution = 1`.
    Field: never.
    """
    role = _user_role_class()
    if role == "pm":
        return {"role": role, "can_record_execution": True, "im": None}
    if role != "im":
        return {"role": role, "can_record_execution": False, "im": None}
    im_resolved, im_identifiers, _ = resolve_im_for_session(im)
    flag, target = _im_master_flag(im_resolved, im_identifiers, "can_record_execution")
    return {"role": role, "can_record_execution": flag, "im": target}


@frappe.whitelist()
def get_subcontractors_by_type(close_type):
    """Return subcontractors from Subcontract Master filtered by their own type field.

    For close_type "SUB", excludes subcontractors whose Contract Model has
    `block_direct_close` checked — admin-configured per contract model, not a
    hardcoded list. Does NOT apply to close_type "INET": a Fix & Core line
    closed against INET's own team is still allowed — only handing it to an
    external Fix & Core subcontractor is blocked. See
    `Contract Model.block_direct_close` and the matching server-side check in
    `_direct_close_one`.
    """
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)
    block_clause = "AND IFNULL(cm.block_direct_close, 0) = 0" if close_type == "SUB" else ""
    sql = f"""
        SELECT sm.name, sm.subcontractor_name AS label
        FROM `tabSubcontract Master` sm
        LEFT JOIN `tabContract Model` cm ON cm.name = sm.contract_model
        WHERE sm.type = %s
          AND IFNULL(sm.status, 'Active') = 'Active'
          AND IFNULL(sm.approved_flag, 0) = 1
          {block_clause}
        ORDER BY sm.subcontractor_name
    """
    return frappe.db.sql(sql, (close_type,), as_dict=True) or []


@frappe.whitelist()
def direct_close_dispatches(po_dispatches, close_type, subcontractor, note=None, milestone=None,
                             huawei_im=None, project_domain=None):
    """Bulk direct-close PO Dispatch lines: create Work Done + move to Completed.

    Only available to IMs with `can_direct_close = 1` (or PM/admin).
    milestone: None/"MS1"/"MS2" — if set, partial milestone close (IM must have can_milestone_close).
    huawei_im/project_domain: optional overrides, same idea as the ones on
    create_rollout_plans — normally these come from the project, but the IM
    may set them per line here too.
    """
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)

    if role == "im":
        cap = get_my_direct_close_capability()
        if not cap.get("can_direct_close"):
            frappe.throw("You do not have permission to Direct Close dispatches.", frappe.PermissionError)
        if milestone and not cap.get("can_milestone_close"):
            frappe.throw("You do not have permission for Milestone Close.", frappe.PermissionError)

    if isinstance(po_dispatches, str):
        po_dispatches = frappe.parse_json(po_dispatches)

    milestone = (milestone or "").strip().upper() or None
    if milestone and milestone not in ("MS1", "MS2"):
        frappe.throw("milestone must be MS1 or MS2")

    huawei_im = (huawei_im or "").strip()
    if huawei_im and not frappe.db.exists("Huawei IM", huawei_im):
        frappe.throw(frappe._("Invalid Huawei IM selected"))
    project_domain = (project_domain or "").strip()
    if project_domain and not frappe.db.exists("Project Domain", project_domain):
        frappe.throw(frappe._("Invalid Project Domain selected"))

    im_resolved, im_identifiers, _ = resolve_im_for_session(None)
    im_doc = im_resolved

    updated = []
    errors = []
    for name in (po_dispatches or []):
        ok, info = _direct_close_one(role, im_identifiers or [], im_doc, name,
                                     close_type, subcontractor, (note or "").strip(),
                                     milestone=milestone, huawei_im=huawei_im, project_domain=project_domain)
        if ok:
            updated.append(info)
        else:
            errors.append(info)

    return {"updated": updated, "errors": errors}


def _direct_close_one(role, im_identifiers, im_doc, name, close_type, subcontractor, note, milestone=None,
                       huawei_im=None, project_domain=None):
    """Create Work Done + complete one PO Dispatch directly. Returns (ok, info).

    milestone: None = full close; "MS1"/"MS2" = partial milestone close on single WD.
    """
    extra_pd_fields = []
    if frappe.db.has_column("PO Dispatch", "ms1_amount"):
        extra_pd_fields += ["ms1_amount", "ms2_amount"]
    if frappe.db.has_column("PO Dispatch", "pic_status"):
        extra_pd_fields += ["pic_status"]
    if frappe.db.has_column("PO Dispatch", "pic_status_ms2"):
        extra_pd_fields += ["pic_status_ms2"]

    pd = frappe.db.get_value(
        "PO Dispatch", name,
        ["name", "im", "dispatch_status", "is_dummy_po", "poid", "item_code",
         "center_area", "region_type", "qty", "rate", "line_amount", "contract",
         "po_intake", "po_line_no"] + extra_pd_fields,
        as_dict=True,
    ) or {}
    if not pd.get("name"):
        return False, {"po_dispatch": name, "error": "PO Dispatch not found"}

    poid = pd.get("poid") or name
    if pd.get("is_dummy_po"):
        return False, {"po_dispatch": name, "poid": poid, "error": "Cannot direct-close a dummy PO"}
    if _is_internal_dispatch(name):
        return False, {"po_dispatch": name, "poid": poid, "error": "Cannot direct-close internal work"}

    cur_status = pd.get("dispatch_status") or ""
    if cur_status in ("Cancelled", "Closed"):
        return False, {"po_dispatch": name, "poid": poid, "error": f"Already {cur_status}"}

    # For milestone close, allow re-entry even if Completed (the other milestone may still be open)
    if not milestone and cur_status == "Completed":
        return False, {"po_dispatch": name, "poid": poid, "error": "Already Completed"}

    if role == "im":
        pd_im = pd.get("im") or ""
        if pd_im and pd_im not in (im_identifiers or []):
            return False, {"po_dispatch": name, "poid": poid, "error": "This POID belongs to a different IM"}

    if not subcontractor:
        return False, {"po_dispatch": name, "poid": poid, "error": "Subcontractor is required"}

    # Fix & Core (or any contract model flagged block_direct_close) is only
    # blocked when handed to an external SUB subcontractor — closing it
    # against INET's own team (close_type "INET") is still allowed.
    if close_type == "SUB":
        sub_contract_model = frappe.db.get_value("Subcontract Master", subcontractor, "contract_model")
        if sub_contract_model and cint(frappe.db.get_value("Contract Model", sub_contract_model, "block_direct_close")):
            return False, {"po_dispatch": name, "poid": poid,
                           "error": f"{subcontractor} is a {sub_contract_model} subcontractor — not eligible for "
                                    f"Direct Close. Route this POID through Rollout Plan -> Execution -> Work Done."}

    # ── Milestone close path ─────────────────────────────────────────────
    if milestone:
        ms_amount_field = "ms1_amount" if milestone == "MS1" else "ms2_amount"
        ms_closed_field = "ms1_closed" if milestone == "MS1" else "ms2_closed"
        ms_closed_at_field = "ms1_closed_at" if milestone == "MS1" else "ms2_closed_at"
        other_closed_field = "ms2_closed" if milestone == "MS1" else "ms1_closed"
        other_amount_field = "ms2_amount" if milestone == "MS1" else "ms1_amount"
        pic_field = "pic_status" if milestone == "MS1" else "pic_status_ms2"

        ms_revenue = flt(pd.get(ms_amount_field) or 0)
        if not ms_revenue:
            return False, {"po_dispatch": name, "poid": poid,
                           "error": f"{milestone} amount is not set on this PO Dispatch"}

        subcontract_cost = 0.0
        inet_margin_pct = 0.0
        if close_type == "SUB":
            scc = frappe.db.get_value(
                "Subcontract Cost Master",
                {"subcontractor": subcontractor, "active_flag": 1},
                "expected_cost_sar",
            )
            subcontract_cost = flt(scc or 0)
            margin_pct = frappe.db.get_value("Subcontract Master", subcontractor, "inet_margin_pct")
            inet_margin_pct = flt(margin_pct or 0)

        now_dt = now_datetime()
        existing_wd_name = frappe.db.get_value("Work Done", {"system_id": name}, "name")

        if existing_wd_name:
            # Check this milestone isn't already closed
            wd_vals = frappe.db.get_value(
                "Work Done", existing_wd_name,
                [ms_closed_field, other_closed_field, "revenue_sar", "subcontractor"],
                as_dict=True,
            ) or {}
            if cint(wd_vals.get(ms_closed_field)):
                return False, {"po_dispatch": name, "poid": poid,
                               "error": f"{milestone} is already closed"}

            # Lock subcontractor: if existing WD already has one, use it (cannot change)
            existing_sub = (wd_vals.get("subcontractor") or "").strip()
            if existing_sub:
                subcontractor = existing_sub

            # Recalculate subcontract_cost for the locked subcontractor
            if close_type == "SUB" and subcontractor:
                scc = frappe.db.get_value(
                    "Subcontract Cost Master",
                    {"subcontractor": subcontractor, "active_flag": 1},
                    "expected_cost_sar",
                )
                subcontract_cost = flt(scc or 0)

            # Accumulate revenue: add this milestone's amount to existing
            other_closed = cint(wd_vals.get(other_closed_field) or 0)
            other_revenue = flt(pd.get(other_amount_field) or 0) if other_closed else 0
            new_revenue = ms_revenue + other_revenue
            margin = new_revenue - subcontract_cost

            wd_updates = {
                ms_closed_field: 1,
                ms_closed_at_field: now_dt,
                "revenue_sar": new_revenue,
                "margin_sar": margin,
            }
            frappe.db.set_value("Work Done", existing_wd_name, wd_updates, update_modified=True)
            wd_name = existing_wd_name
        else:
            billing_rate = flt(pd.get("rate") or 0)
            executed_qty = flt(pd.get("qty") or 0) or 1.0
            margin = ms_revenue - subcontract_cost

            wd = frappe.new_doc("Work Done")
            wd.system_id = name
            wd.region_type = pd.get("region_type") or region_type_from_center_area(pd.get("center_area") or "")
            wd.item_code = pd.get("item_code")
            wd.executed_qty = executed_qty
            wd.billing_rate_sar = billing_rate
            wd.revenue_sar = ms_revenue
            wd.team_cost_sar = 0
            wd.subcontract_cost_sar = subcontract_cost
            wd.activity_cost_sar = 0
            wd.total_cost_sar = subcontract_cost
            wd.margin_sar = margin
            wd.inet_margin_pct = inet_margin_pct
            wd.billing_status = "Pending"
            if frappe.db.has_column("Work Done", "subcontractor"):
                wd.subcontractor = subcontractor
            if frappe.db.has_column("Work Done", "source"):
                wd.source = "Direct Close"
            if frappe.db.has_column("Work Done", "direct_close_by"):
                wd.direct_close_by = im_doc or frappe.session.user
            if frappe.db.has_column("Work Done", ms_closed_field):
                setattr(wd, ms_closed_field, 1)
            if frappe.db.has_column("Work Done", ms_closed_at_field):
                setattr(wd, ms_closed_at_field, now_dt)
            wd.insert(ignore_permissions=True)
            wd_name = wd.name

        frappe.db.commit()

        # Do NOT auto-set pic_status here — IM submits each milestone to PIC
        # explicitly from the Work Done page via submit_milestone_to_pic().
        pd_updates = {}
        if frappe.db.has_column("PO Dispatch", "direct_close_by"):
            pd_updates["direct_close_by"] = im_doc or frappe.session.user
        existing_contract = pd.get("contract") or ""
        if subcontractor and not existing_contract:
            pd_updates["contract"] = subcontractor
        if huawei_im:
            pd_updates["huawei_im"] = huawei_im
        if project_domain:
            pd_updates["project_domain"] = project_domain

        # Only set Completed when both milestones are now closed
        wd_check = frappe.db.get_value("Work Done", wd_name, ["ms1_closed", "ms2_closed"], as_dict=True) or {}
        both_closed = cint(wd_check.get("ms1_closed")) and cint(wd_check.get("ms2_closed"))
        if both_closed:
            pd_updates["dispatch_status"] = "Completed"

        if pd_updates:
            frappe.db.set_value("PO Dispatch", name, pd_updates, update_modified=False)

        # Mark PO Intake Line Completed only when both milestones closed
        if both_closed:
            intake_parent = pd.get("po_intake")
            line_no = pd.get("po_line_no")
            if intake_parent and line_no:
                intake_line = frappe.db.exists("PO Intake Line",
                    {"parent": intake_parent, "po_line_no": line_no})
                if intake_line and isinstance(intake_line, str):
                    frappe.db.set_value("PO Intake Line", intake_line, "po_line_status", "Completed")

        frappe.db.commit()
        return True, {"po_dispatch": name, "poid": poid, "work_done": wd_name,
                      "milestone": milestone, "both_closed": both_closed}

    # ── Full close path (original logic) ────────────────────────────────
    if cur_status == "Completed":
        return False, {"po_dispatch": name, "poid": poid, "error": "Already Completed"}

    if frappe.db.exists("Work Done", {"system_id": name}):
        return False, {"po_dispatch": name, "poid": poid, "error": "Work Done already exists for this POID"}

    # Resolve subcontract cost and margin (only for SUB type teams)
    revenue = flt(pd.get("line_amount") or 0)
    billing_rate = flt(pd.get("rate") or 0)
    executed_qty = flt(pd.get("qty") or 0) or 1.0
    if not revenue:
        revenue = billing_rate * executed_qty

    subcontract_cost = 0.0
    inet_margin_pct = 0.0
    if close_type == "SUB":
        scc = frappe.db.get_value(
            "Subcontract Cost Master",
            {"subcontractor": subcontractor, "active_flag": 1},
            "expected_cost_sar",
        )
        subcontract_cost = flt(scc or 0)
        margin_pct = frappe.db.get_value("Subcontract Master", subcontractor, "inet_margin_pct")
        inet_margin_pct = flt(margin_pct or 0)

    margin = revenue - subcontract_cost

    wd = frappe.new_doc("Work Done")
    wd.system_id = name
    wd.region_type = pd.get("region_type") or region_type_from_center_area(pd.get("center_area") or "")
    wd.item_code = pd.get("item_code")
    wd.executed_qty = executed_qty
    wd.billing_rate_sar = billing_rate
    wd.revenue_sar = revenue
    wd.team_cost_sar = 0
    wd.subcontract_cost_sar = subcontract_cost
    wd.activity_cost_sar = 0
    wd.total_cost_sar = subcontract_cost
    wd.margin_sar = margin
    wd.inet_margin_pct = inet_margin_pct
    wd.billing_status = "Pending"
    if frappe.db.has_column("Work Done", "subcontractor"):
        wd.subcontractor = subcontractor
    if frappe.db.has_column("Work Done", "source"):
        wd.source = "Direct Close"
    if frappe.db.has_column("Work Done", "direct_close_by"):
        wd.direct_close_by = im_doc or frappe.session.user

    wd.insert(ignore_permissions=True)
    frappe.db.commit()

    # Update PO Dispatch
    pd_updates = {"dispatch_status": "Completed"}
    if frappe.db.has_column("PO Dispatch", "direct_close_by"):
        pd_updates["direct_close_by"] = im_doc or frappe.session.user
    existing_contract = pd.get("contract") or ""
    if subcontractor and not existing_contract:
        pd_updates["contract"] = subcontractor
    if huawei_im:
        pd_updates["huawei_im"] = huawei_im
    if project_domain:
        pd_updates["project_domain"] = project_domain
    frappe.db.set_value("PO Dispatch", name, pd_updates, update_modified=False)

    # Mark PO Intake Line as Completed
    intake_parent = pd.get("po_intake")
    line_no = pd.get("po_line_no")
    if intake_parent and line_no:
        intake_line = frappe.db.exists("PO Intake Line",
            {"parent": intake_parent, "po_line_no": line_no})
        if intake_line and isinstance(intake_line, str):
            frappe.db.set_value("PO Intake Line", intake_line, "po_line_status", "Completed")
    frappe.db.commit()

    return True, {"po_dispatch": name, "poid": poid, "work_done": wd.name}


@frappe.whitelist()
def list_backend_teams_for_picker(search=None, limit=200):
    """Backend Team picker — only teams with category 'Backend Team'."""
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)
    s = (search or "").strip()
    where = ["IFNULL(team_category,'Field Team') = 'Backend Team'", "IFNULL(status,'Active') = 'Active'"]
    params = []
    if s:
        where.append("(name LIKE %s OR IFNULL(team_id,'') LIKE %s OR IFNULL(team_name,'') LIKE %s)")
        like = f"%{s}%"
        params.extend([like, like, like])
    sql = f"""
        SELECT name, team_id, team_name, subcontractor, department
        FROM `tabINET Team`
        WHERE {' AND '.join(where)}
        ORDER BY IFNULL(team_name, team_id) ASC
        LIMIT {int(limit)}
    """
    return frappe.db.sql(sql, tuple(params), as_dict=True)


def _assign_backend_one(role, im_identifiers, name, team, remark, huawei_im=None, project_domain=None):
    """Stamp subcon fields on a single PO Dispatch. Returns (ok, info_or_error)."""
    pd = frappe.db.get_value(
        "PO Dispatch", name,
        ["name", "im", "dispatch_status", "subcon_status", "backend_team", "is_dummy_po", "poid"],
        as_dict=True,
    ) or {}
    if not pd.get("name"):
        return False, {"po_dispatch": name, "error": "PO Dispatch not found"}

    cur_status = (pd.get("dispatch_status") or "")
    if cur_status == "Planned":
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Already in Rollout Planning — cancel the plan first."}
    if cur_status == "Completed":
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Already completed."}
    if cur_status == "Cancelled":
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Cancelled — cannot sub-contract."}
    if (pd.get("subcon_status") or "") == "Pending":
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Already sub-contracted (pending)."}
    if (pd.get("is_dummy_po") or 0) and not (pd.get("poid") or "").strip():
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Map the dummy PO to a real PO line before sub-contracting."}

    if role == "im":
        if not _can_assign_backend_dispatch(role, im_identifiers, pd):
            return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Not assigned to you."}

    updates = {
        "backend_team": team["name"],
        "subcon_status": "Pending",
        "subcon_completed_on": None,
        "dispatch_status": "Backend Assigned",
    }
    if remark is not None and str(remark or "").strip():
        updates["subcon_remark"] = str(remark or "")[:8000]
    if huawei_im:
        updates["huawei_im"] = huawei_im
    if project_domain:
        updates["project_domain"] = project_domain
    frappe.db.set_value("PO Dispatch", name, updates, update_modified=True)
    return True, {
        "po_dispatch": name,
        "poid": pd.get("poid") or name,
        "backend_team": team["name"],
        "backend_team_name": team.get("team_name") or team.get("team_id"),
        "subcon_status": "Pending",
        "dispatch_status": "Backend Assigned",
    }


@frappe.whitelist()
def assign_backend(po_dispatch=None, po_dispatches=None, backend_team=None, remark=None,
                    huawei_im=None, project_domain=None):
    """Sub-contract one or many PO Dispatches to a non-field team.

    Accepts either ``po_dispatch`` (single name) or ``po_dispatches`` (list / JSON
    array). The list form is preferred for bulk actions from the UI.

    Side-effects per dispatch:
        backend_team           = <team>
        subcon_status         = 'Pending'
        subcon_completed_on   = NULL
        dispatch_status       = 'Backend Assigned'
        subcon_remark         = <remark> (optional)
        huawei_im             = <huawei_im> (optional override, same as create_rollout_plans)
        project_domain        = <project_domain> (optional override)

    NOTE: subcon dispatches are intentionally kept OUT of the rollout chain — no
    Rollout Plan, Daily Execution or Work Done rows are created. Reporting that
    needs them must read the PO Dispatch row directly.
    """
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)
    if not backend_team:
        frappe.throw("backend_team is required")

    huawei_im = (huawei_im or "").strip()
    if huawei_im and not frappe.db.exists("Huawei IM", huawei_im):
        frappe.throw(frappe._("Invalid Huawei IM selected"))
    project_domain = (project_domain or "").strip()
    if project_domain and not frappe.db.exists("Project Domain", project_domain):
        frappe.throw(frappe._("Invalid Project Domain selected"))

    raw = po_dispatches if po_dispatches not in (None, "", []) else po_dispatch
    if isinstance(raw, str):
        try:
            parsed = frappe.parse_json(raw)
            if isinstance(parsed, (list, tuple)):
                raw = parsed
        except Exception:
            pass
    if isinstance(raw, (list, tuple)):
        candidates = [str(x).strip() for x in raw if str(x or "").strip()]
    elif raw:
        candidates = [str(raw).strip()]
    else:
        candidates = []
    if not candidates:
        frappe.throw("po_dispatch is required")

    team = frappe.db.get_value(
        "INET Team", backend_team,
        ["name", "team_id", "team_name", "team_category", "status"],
        as_dict=True,
    )
    if not team:
        frappe.throw(f"INET Team not found: {backend_team}")
    if (team.get("team_category") or "Field Team") != "Backend Team":
        frappe.throw("Backend assignment is only allowed to teams with category 'Backend Team'.")
    if (team.get("status") or "Active") != "Active":
        frappe.throw("Selected team is not Active.")

    im_identifiers = []
    if role == "im":
        im_resolved, im_identifiers, _ = resolve_im_for_session()
        # Gate by IM Master.can_assign_backend. resolve_im_for_session returns
        # `im_resolved` = IM Master name; `im_identifiers` is an unordered
        # set-derived list that can include email / full_name / etc., so
        # always look up the IM Master row by the resolved name (or by any
        # identifier that maps to one).
        my_im = im_resolved if im_resolved and frappe.db.exists("IM Master", im_resolved) else None
        if not my_im:
            for ident in im_identifiers or []:
                if frappe.db.exists("IM Master", ident):
                    my_im = ident
                    break
        if not my_im:
            frappe.throw("Could not resolve your IM Master record.", frappe.PermissionError)
        if not cint(frappe.db.get_value("IM Master", my_im, "can_assign_backend") or 0):
            frappe.throw("Sub-contracting is not enabled for your IM profile. Ask the admin to enable 'Can Sub-Contract' on your IM Master.", frappe.PermissionError)

    # Resolve POIDs / system_ids to real names
    resolved = []
    for token in candidates:
        try:
            resolved.append(_resolve_dispatch_for_remarks(token))
        except Exception:
            resolved.append(None)

    updated = []
    errors = []
    for i, name in enumerate(resolved):
        if not name:
            errors.append({"po_dispatch": candidates[i], "error": "PO Dispatch not found"})
            continue
        ok, info = _assign_backend_one(role, im_identifiers, name, team, remark,
                                       huawei_im=huawei_im, project_domain=project_domain)
        (updated if ok else errors).append(info)

    frappe.db.commit()
    return {
        "updated": updated,
        "errors": errors,
        "summary": {
            "total": len(candidates),
            "updated_count": len(updated),
            "error_count": len(errors),
            "backend_team": team["name"],
            "backend_team_name": team.get("team_name") or team.get("team_id"),
        },
    }


def _mark_backend_done_one(role, im_identifiers, name, completed, remark):
    pd = frappe.db.get_value(
        "PO Dispatch", name,
        ["name", "im", "dispatch_status", "subcon_status", "backend_team", "subcon_remark",
         "poid", "item_code", "center_area", "region_type", "qty", "rate", "line_amount",
         "contract", "po_intake", "po_line_no"],
        as_dict=True,
    ) or {}
    if not pd.get("name"):
        return False, {"po_dispatch": name, "error": "PO Dispatch not found"}
    if _is_internal_dispatch(name):
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Internal work cannot be marked done via the backend flow."}
    if (pd.get("subcon_status") or "") != "Pending":
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Not in 'Sub-Contract Pending' state."}
    if role == "im" and not _can_assign_backend_dispatch(role, im_identifiers, pd):
        return False, {"po_dispatch": name, "poid": pd.get("poid") or name, "error": "Not assigned to you."}

    updates = {
        "subcon_status": "Work Done",
        "subcon_completed_on": completed,
        "dispatch_status": "Completed",
    }
    # Snapshot the backend team's subcontractor onto pd.contract (only if not already set).
    backend_team = pd.get("backend_team")
    if backend_team:
        team_subcon = frappe.db.get_value("INET Team", backend_team, "subcontractor")
        existing_contract = frappe.db.get_value("PO Dispatch", name, "contract")
        if team_subcon and not existing_contract:
            updates["contract"] = team_subcon
    addition = (str(remark or "")).strip() if remark is not None else ""
    if addition:
        existing = (pd.get("subcon_remark") or "").strip()
        if existing:
            combined = existing + "\n— Work Done note —\n" + addition
        else:
            combined = addition
        updates["subcon_remark"] = combined[:8000]
    frappe.db.set_value("PO Dispatch", name, updates, update_modified=True)
    frappe.db.commit()

    # Create a real Work Done record (skip if one already exists for this POID)
    wd_name = None
    if not frappe.db.exists("Work Done", {"system_id": name}):
        try:
            revenue = flt(pd.get("line_amount") or 0)
            billing_rate = flt(pd.get("rate") or 0)
            executed_qty = flt(pd.get("qty") or 0) or 1.0
            if not revenue:
                revenue = billing_rate * executed_qty

            subcontractor = updates.get("contract") or pd.get("contract") or ""
            subcontract_cost = 0.0
            inet_margin_pct = 0.0
            if subcontractor:
                scc = frappe.db.get_value(
                    "Subcontract Cost Master",
                    {"subcontractor": subcontractor, "active_flag": 1},
                    "expected_cost_sar",
                )
                subcontract_cost = flt(scc or 0)
                margin_pct = frappe.db.get_value("Subcontract Master", subcontractor, "inet_margin_pct")
                inet_margin_pct = flt(margin_pct or 0)

            wd = frappe.new_doc("Work Done")
            wd.system_id = name
            wd.region_type = pd.get("region_type") or region_type_from_center_area(pd.get("center_area") or "")
            wd.item_code = pd.get("item_code")
            wd.executed_qty = executed_qty
            wd.billing_rate_sar = billing_rate
            wd.revenue_sar = revenue
            wd.team_cost_sar = 0
            wd.subcontract_cost_sar = subcontract_cost
            wd.activity_cost_sar = 0
            wd.total_cost_sar = subcontract_cost
            wd.margin_sar = revenue - subcontract_cost
            wd.inet_margin_pct = inet_margin_pct
            wd.billing_status = "Pending"
            if frappe.db.has_column("Work Done", "subcontractor"):
                wd.subcontractor = subcontractor
            if frappe.db.has_column("Work Done", "source"):
                wd.source = "Backend"
            wd.insert(ignore_permissions=True)
            frappe.db.commit()
            wd_name = wd.name
        except Exception:
            frappe.log_error(frappe.get_traceback(), "_mark_backend_done_one: WD creation failed")

    return True, {
        "po_dispatch": name,
        "poid": pd.get("poid") or name,
        "subcon_status": "Work Done",
        "subcon_completed_on": str(completed),
        "dispatch_status": "Completed",
        "work_done": wd_name,
    }


@frappe.whitelist()
def mark_backend_work_done(po_dispatch=None, po_dispatches=None, completed_on=None, remark=None):
    """Mark one or many sub-contracted POIDs as Work Done.

    Accepts either ``po_dispatch`` (single name) or ``po_dispatches`` (list / JSON).
    """
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)

    raw = po_dispatches if po_dispatches not in (None, "", []) else po_dispatch
    if isinstance(raw, str):
        try:
            parsed = frappe.parse_json(raw)
            if isinstance(parsed, (list, tuple)):
                raw = parsed
        except Exception:
            pass
    if isinstance(raw, (list, tuple)):
        candidates = [str(x).strip() for x in raw if str(x or "").strip()]
    elif raw:
        candidates = [str(raw).strip()]
    else:
        candidates = []
    if not candidates:
        frappe.throw("po_dispatch is required")

    completed = completed_on or nowdate()
    try:
        completed = getdate(completed)
    except Exception:
        completed = nowdate()

    im_identifiers = []
    if role == "im":
        _, im_identifiers, _ = resolve_im_for_session()

    resolved = []
    for token in candidates:
        try:
            resolved.append(_resolve_dispatch_for_remarks(token))
        except Exception:
            resolved.append(None)

    updated = []
    errors = []
    for i, name in enumerate(resolved):
        if not name:
            errors.append({"po_dispatch": candidates[i], "error": "PO Dispatch not found"})
            continue
        ok, info = _mark_backend_done_one(role, im_identifiers, name, completed, remark)
        (updated if ok else errors).append(info)

    frappe.db.commit()
    return {
        "updated": updated,
        "errors": errors,
        "summary": {
            "total": len(candidates),
            "updated_count": len(updated),
            "error_count": len(errors),
            "completed_on": str(completed),
        },
    }


@frappe.whitelist()
def list_backend_dispatches(
    im=None, search=None, status="all", limit=300,
    project_code=None, site_code=None, backend_team=None,
    column_filters=None, _options=None, _summary=None,
):
    """Sub-Contract list feed.

    status: "all" | "pending" | "done"
    Visible to PM (all IMs) and IM (own POIDs only).
    Optional filters ``project_code``, ``site_code`` and ``backend_team`` accept
    a single value or a JSON-array / comma-separated list.
    """
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)

    where = ["IFNULL(pd.subcon_status,'') != ''"]
    params = []

    if role == "im":
        _, im_identifiers, _ = resolve_im_for_session(im)
        if not im_identifiers:
            return []
        ph = ", ".join(["%s"] * len(im_identifiers))
        where.append(f"IFNULL(pd.im,'') IN ({ph})")
        params.extend(list(im_identifiers))
    elif role == "pm" and im:
        _, im_identifiers, _ = resolve_im_for_session(im)
        if im_identifiers:
            ph = ", ".join(["%s"] * len(im_identifiers))
            where.append(f"IFNULL(pd.im,'') IN ({ph})")
            params.extend(list(im_identifiers))

    s = (status or "all").lower()
    if s == "pending":
        where.append("pd.subcon_status = 'Pending'")
    elif s in ("done", "work_done"):
        where.append("pd.subcon_status = 'Work Done'")

    for col, raw in (("project_code", project_code), ("site_code", site_code), ("backend_team", backend_team)):
        clause, in_params = _sql_in_or_eq(f"pd.{col}", raw)
        if clause:
            where.append(clause)
            params.extend(in_params)

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale. "Domain"/"Huawei IM" are normally Python post-query
    # enrichments (_enrich_with_project_fields, by project_code) — the `pcc`
    # join below makes them backend-filterable too, same pattern used for
    # list_execution_monitor_rows/list_issue_risk_rows/list_po_intake_lines.
    col_filter_map_backend = {
        "poid": "COALESCE(NULLIF(pd.poid,''), pd.name)",
        "po_no": "IFNULL(pd.po_no,'')",
        "project": "IFNULL(pd.project_code,'')",
        "domain": "COALESCE(NULLIF(pd.project_domain,''), pcc_bk.project_domain, '')",
        "huawei_im": "COALESCE(NULLIF(pd.huawei_im,''), pcc_bk.huawei_im, '')",
        "item": "IFNULL(pd.item_code,'')",
        "description": "IFNULL(pd.item_description,'')",
        "qty": "CAST(pd.qty AS CHAR)",
        "amount_sar": "CAST(pd.line_amount AS CHAR)",
        "duid": "IFNULL(pd.site_code,'')",
        "center_area": "IFNULL(pd.center_area,'')",
        "backend_team": "IFNULL(t.team_name,'')",
        "status": "IFNULL(pd.subcon_status,'')",
        "completed": "CAST(pd.subcon_completed_on AS CHAR)",
        "note": "IFNULL(pd.subcon_remark,'')",
    }
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map_backend.get(col_key), raw_val)
                if _c:
                    where.append(_c)
                    params.extend(_p)
                continue
            pat_bk = _sql_like_pattern(raw_val)
            if not pat_bk:
                continue
            expr_bk = col_filter_map_backend.get(col_key)
            if not expr_bk:
                continue
            where.append(f"{expr_bk} LIKE %s")
            params.append(pat_bk)

    if search:
        clause, like_params = _sql_search_clause(
            "CONCAT_WS(' ', pd.poid, pd.po_no, pd.item_code, pd.item_description, pd.site_name, pd.site_code, "
            "pd.project_code, IFNULL(t.team_name,''), IFNULL(t.team_id,''), COALESCE(NULLIF(pd.project_domain,''), pcc_bk.project_domain, ''), "
            "IFNULL(pcc_bk.huawei_im,''), IFNULL(pd.subcon_remark,''))",
            search,
            exact_cols=["IFNULL(pd.poid,'')", "IFNULL(pd.site_code,'')"],
        )
        if clause:
            where.append(clause)
            params.extend(like_params)

    if _options:
        _e = col_filter_map_backend.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabPO Dispatch` pd "
            "LEFT JOIN `tabINET Team` t ON t.name = pd.backend_team "
            "LEFT JOIN `tabProject Control Center` pcc_bk ON pcc_bk.name = pd.project_code",
            " AND ".join(where), params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # Backend work has no field execution behind it, so the IM's question
        # is simply what is still outstanding with the backend teams.
        _ss = "IFNULL(pd.subcon_status,'')"
        return summary_from_query(
            "`tabPO Dispatch` pd "
            "LEFT JOIN `tabINET Team` t ON t.name = pd.backend_team "
            "LEFT JOIN `tabProject Control Center` pcc_bk ON pcc_bk.name = pd.project_code",
            " AND ".join(where), params, [
                {"key": "lines", "label": "Lines", "agg": "count"},
                {"key": "duids", "label": "DUIDs", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pd.site_code,''), '')"},
                {"key": "teams", "label": "Teams", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(pd.backend_team,''), '')"},
                {"key": "value", "label": "Value", "agg": "sum",
                 "expr": "IFNULL(pd.line_amount, 0)", "format": "money", "tone": "good"},
                {"key": "pending", "label": "Pending", "agg": "count_if", "group": "Backend",
                 "cond": f"{_ss} IN ('', 'Pending')", "tone": "warn", "hide_if_zero": True},
                {"key": "work_done", "label": "Work done", "agg": "count_if", "group": "Backend",
                 "cond": f"{_ss} = 'Work Done'", "tone": "good", "hide_if_zero": True},
            ])

    limit_int = int(limit) if limit else 300
    sql = f"""
        SELECT pd.name AS po_dispatch,
               pd.poid AS poid,
               pd.po_no, pd.po_line_no,
               pd.item_code, pd.item_description,
               pd.qty, pd.line_amount,
               pd.project_code, pd.customer, pd.im, pd.huawei_im,
               pd.site_code, pd.site_name, pd.center_area, pd.region_type,
               pd.dispatch_status, pd.target_month,
               pd.backend_team, pd.subcon_status, pd.subcon_completed_on, pd.subcon_remark,
               t.team_id   AS backend_team_id,
               t.team_name AS backend_team_name,
               pd.modified
        FROM `tabPO Dispatch` pd
        LEFT JOIN `tabINET Team` t ON t.name = pd.backend_team
        LEFT JOIN `tabProject Control Center` pcc_bk ON pcc_bk.name = pd.project_code
        WHERE {' AND '.join(where)}
        ORDER BY pd.modified DESC
        LIMIT {limit_int}
    """
    rows = frappe.db.sql(sql, tuple(params), as_dict=True)
    _enrich_with_project_fields(rows)
    return rows


# ──────────────────────────────────────────────────────────────────────
# PO Archive Import — closed/cancelled lines are imported with terminal
# status and stay out of the active workflow. Used to backfill historical
# POs from spreadsheets so the PM can dump them later.
# ──────────────────────────────────────────────────────────────────────
_PO_ARCHIVE_ALIAS = {
    "ID": "source_id",
    "Contract": "contract",
    "Project Domain": "project_domain",
    "POID": "poid",
    "PO Status": "po_status",
    "PO STATUS": "po_status",
    "Status": "po_status",
    "PO status": "po_status",
    "PO NO.": "po_no",
    "PO No.": "po_no",
    "PO No": "po_no",
    "PO Line NO.": "po_line_no",
    "PO Line No.": "po_line_no",
    "PO Line No": "po_line_no",
    "Shipment NO.": "shipment_no",
    "Shipment No.": "shipment_no",
    "Site Name": "site_name",
    "Site Code": "site_code",
    "Item Code": "item_code",
    "Item Description": "item_description",
    "Unit": "unit",
    "Requested Qty": "qty",
    "Due Qty": "due_qty",
    "Billed Quantity": "billed_quantity",
    "Quantity Cancel": "quantity_cancel",
    "Start Date": "start_date",
    "End Date": "end_date",
    "Sub Contract NO.": "sub_contract_no",
    "Contract": "contract",
    "Sub Contract": "contract",
    "Sub-Contract": "contract",
    "Currency": "currency",
    "Unit Price": "rate",
    "Line Amount": "line_amount",
    "Tax Rate": "tax_rate",
    "Payment Terms": "payment_terms",
    "Project Code": "project_code",
    "Project Name": "project_name",
    "Center Area": "center_area",
    "Publish Date": "publish_date",
    "Huawei Owner": "huawei_owner",
    "Inet Owner": "inet_owner",
    "Inet IM Remarks": "manager_remark",
    # PIC / invoice tracking columns
    "SQC Status": "sqc_status",
    "PAT Status": "pat_status",
    "IM's Remarks on Rejection": "im_rejection_remark",
    "PIC Remarks": "pic_status",
    "ISDP Owner": "isdp_owner",
    "ISDP / I-Buy Owner": "isdp_owner",
    "MS1": "ms1_amount",
    "MS2": "ms2_amount",
    "PIC Remarks (2nd Milestone)": "pic_status_ms2",
    "iBuy Owner": "ibuy_owner",
    "ISD / I-Buy Owner (2nd Milestone)": "ibuy_owner",
    "Remaining Milestone": "remaining_milestone_pct",
    "1st Payment PO Amount": "ms1_amount",
    "1st Payment Invoiced": "ms1_invoiced",
    "Subcon Per% MS1": "subcon_pct_ms1",
    "Inet Per% MS1": "inet_pct_ms1",
    "2nd Payment PO Amount": "ms2_amount",
    "2nd Payment Invoiced": "ms2_invoiced",
    "Subcon Per% MS2": "subcon_pct_ms2",
    "Inet Per% MS2": "inet_pct_ms2",
    "Invoicing Month (First Payment Milestone)": "ms1_invoice_month",
    "Invoicing Month (Second Payment Milestone)": "ms2_invoice_month",
    # Duplicate-named cols ("Applied Date", "IBUY / INV date", "Payment Received
    # Date", "Detail Remarks/Dependency") are disambiguated positionally by
    # ``_resolve_archive_header_keys`` using the most recent "PIC Remarks"
    # anchor as the milestone marker.
}


def _resolve_archive_header_keys(headers):
    """Return ``{col_index: standard_key}`` for a Master-Tracker header row.

    The Master Tracker has several columns whose **header text repeats** —
    ``Detail Remarks/Dependency`` appears 3× (IM, MS1 PIC, MS2 PIC),
    ``Applied Date`` 2× (MS1, MS2), ``IBUY / INV date`` 2× and
    ``Payment Received Date`` 2×. A plain dict keyed by header name would
    collapse them onto the same field.

    We walk the header row left-to-right and track the occurrence count of
    each duplicate header name. Occurrence 1 → MS1 field, occurrence 2 → MS2
    field. This is simpler and more robust than milestone-context tracking
    because the IBUY / INV date columns appear AFTER both PIC-section anchors,
    making a milestone counter unreliable.
    """
    out = {}
    # Map (header_text, occurrence_number) → standard field key.
    # Occurrence is 1-indexed and incremented each time the header appears.
    DUP_BY_OCC = {
        ("Detail Remarks/Dependency", 1): "pic_detail_remark",
        ("Detail Remarks/Dependency", 2): "pic_detail_remark_ms2",
        ("Applied Date", 1): "ms1_applied_date",
        ("Applied Date", 2): "ms2_applied_date",
        ("IBUY / INV date", 1): "ms1_ibuy_inv_date",
        ("IBUY / INV date", 2): "ms2_ibuy_inv_date",
    }
    DUP_NAMES = {h for (h, _) in DUP_BY_OCC.keys()}
    occ_count = {}  # tracks how many times each duplicate header has appeared

    for i, h in enumerate(headers or []):
        h = str(h or "").strip() if h is not None else ""
        if not h:
            continue
        if h in DUP_NAMES:
            occ_count[h] = occ_count.get(h, 0) + 1
            key = DUP_BY_OCC.get((h, occ_count[h]))
            if key:
                out[i] = key
            # occurrence > 2 (e.g. a third Detail Remarks): ignore
            continue
        alias = _PO_ARCHIVE_ALIAS.get(h)
        if alias:
            out[i] = alias
    return out


def _sanitize_archive_date(v):
    """Return a YYYY-MM-DD string MySQL will accept, or None to skip the field.

    Handles:
    - Excel float/int serials (e.g. 45776.0)
    - Clean ISO strings ("2025-05-01")
    - Month-year strings like "May-25", "May 2025", "(13) May-25"
    - DD-Mon-YY like "01-May-25"
    """
    if v is None or v == "":
        return None
    if isinstance(v, (int, float)):
        return _excel_serial_to_date_str(v)  # handles float serial
    s = str(v).strip()
    if not s:
        return None
    # Strip leading "(N) " prefix common in archive invoice month cells
    import re as _re
    s = _re.sub(r"^\(\d+\)\s*", "", s).strip()
    # Try ISO / common formats first
    from datetime import datetime as _dt
    for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%m/%d/%Y",
                "%d-%b-%y", "%d-%b-%Y", "%d %b %Y", "%d %b %y"):
        try:
            return _dt.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    # Month-Year only: "May-25", "May 2025", "May-2025"
    for fmt in ("%b-%y", "%b %Y", "%b-%Y", "%B-%y", "%B %Y", "%B-%Y"):
        try:
            return _dt.strptime(s, fmt).strftime("%Y-%m-01")
        except ValueError:
            pass
    # Fallback: try Excel serial stored as string
    try:
        return _excel_serial_to_date_str(float(s))
    except Exception:
        pass
    return None  # unparseable — skip field


# Known decorations seen in archive data ("Rejected By Asad Mehmood" where
# "Asad Mehmood" is the real owner) — stripped (case-insensitive, leading
# position only) before re-checking against the real owner list. Shared by
# both the archive-import path (_stamp_archive_pic_fields, below) and the
# one-off cleanup patch (inet_app.patches.v1_0.fix_po_dispatch_legacy_data)
# so future archive imports don't reintroduce the same bad data.
_OWNER_LINK_KNOWN_PREFIXES = [
    "rejected by",
]


def normalize_select_value(doctype, fieldname, value):
    """Return the correctly-cased option for a Select field's value.

    Frappe's Select validation is exact-match, so a value that only
    case-differs from a real option (e.g. "PO line Canceled" vs the defined
    "PO Line Canceled") throws on save with no help correcting it. Returns
    the original value unchanged if it's already exact, already invalid in
    some other way, or the field isn't a Select.
    """
    val = (value or "").strip()
    if not val:
        return value
    meta = frappe.get_meta(doctype)
    field = meta.get_field(fieldname)
    if not field or field.fieldtype != "Select":
        return value
    valid_options = [o for o in (field.options or "").split("\n") if o.strip()]
    if val in valid_options:
        return value
    for o in valid_options:
        if o.lower() == val.lower():
            return o
    return value


def resolve_or_create_owner_link(owner_doctype, value, owner_name_field="owner_name"):
    """Resolve a PIC "owner" Link field value (ISDP Owner / IBuy Owner), even
    when it's decorated with a known prefix (e.g. "Rejected By Asad Mehmood").

    Returns (resolved_value_or_None, created_bool). resolved_value is None
    when no real owner can be identified even after stripping known
    prefixes — the caller should leave the field unset rather than write an
    invalid link, and should NOT stash the original text in a
    business-facing remark field (PIC Rejection Remark etc. are for genuine
    PIC notes, not import-cleanup artifacts).
    """
    val = (value or "").strip()
    if not val:
        return None, False
    if frappe.db.exists(owner_doctype, val):
        return val, False
    low = val.lower()
    for prefix in _OWNER_LINK_KNOWN_PREFIXES:
        if low.startswith(prefix):
            stripped = val[len(prefix):].strip(" :-")
            if not stripped:
                continue
            if frappe.db.exists(owner_doctype, stripped):
                return stripped, False
            frappe.get_doc({"doctype": owner_doctype, owner_name_field: stripped}).insert(
                ignore_permissions=True
            )
            return stripped, True
    return None, False


def _stamp_archive_pic_fields(dispatch_name, src_line):
    """Copy PIC / invoice tracking fields from an archive row onto a PO Dispatch.

    Bypasses ``doc.save()`` (which would be expensive for 12k+ rows) and writes
    via ``frappe.db.set_value`` directly. Computes ``ms1_unbilled`` /
    ``ms2_unbilled`` here so they don't drift when validate hasn't run.
    """
    PIC_KEYS = (
        "contract",
        "sqc_status", "pat_status", "im_rejection_remark",
        "pic_status", "pic_status_ms2",
        "isdp_owner", "ibuy_owner",
        "pic_detail_remark", "pic_detail_remark_ms2",
        "ms1_applied_date", "ms2_applied_date",
        "ms1_amount", "ms2_amount",
        "ms1_invoiced", "ms2_invoiced",
        "remaining_milestone_pct",
        "subcon_pct_ms1", "inet_pct_ms1",
        "subcon_pct_ms2", "inet_pct_ms2",
        "ms1_invoice_month", "ms2_invoice_month",
        "ms1_ibuy_inv_date", "ms2_ibuy_inv_date",
        "manager_remark",
    )
    NUMERIC = {
        "ms1_amount", "ms2_amount", "ms1_invoiced", "ms2_invoiced",
        "remaining_milestone_pct",
        "subcon_pct_ms1", "inet_pct_ms1", "subcon_pct_ms2", "inet_pct_ms2",
    }
    DATE_KEYS = {
        "ms1_applied_date", "ms2_applied_date",
        "ms1_invoice_month", "ms2_invoice_month",
        "ms1_ibuy_inv_date", "ms2_ibuy_inv_date",
    }
    # Rows downgraded to "Pending" (see _archive_row_has_no_pic_progress) have
    # no evidence any work was actually done — don't carry over the archive's
    # subcontractor either, since that mapping is only meaningful for a line
    # that genuinely progressed. Let the normal dispatch workflow assign it.
    skip_contract = src_line.get("_target_status") == "Pending"
    updates = {}
    for k in PIC_KEYS:
        if k == "contract" and skip_contract:
            continue
        v = src_line.get(k)
        if v is None or v == "":
            continue
        if k == "contract":
            # Link field → Subcontract Master; skip if not found to avoid broken links
            if not frappe.db.exists("Subcontract Master", str(v).strip()):
                continue
            updates[k] = str(v).strip()
        elif k in ("pic_status", "pic_status_ms2"):
            # Select field — archive rows have been seen with a value that
            # only case-differs from the real option (e.g. "PO line
            # Canceled"); Frappe's Select validation is exact-match, so an
            # unnormalized value would silently sit fine here (this path
            # bypasses validate()) but throw the next time anyone runs this
            # record through a real doc.save() (e.g. PIC Tracker updates).
            updates[k] = normalize_select_value("PO Dispatch", k, str(v).strip())
        elif k == "isdp_owner":
            resolved, _ = resolve_or_create_owner_link("ISDP Owner", str(v).strip())
            if resolved:
                updates[k] = resolved
            # else: not a recognizable owner (no known decoration prefix
            # matched) — skip rather than write an invalid link.
        elif k == "ibuy_owner":
            resolved, _ = resolve_or_create_owner_link("IBuy Owner", str(v).strip())
            if resolved:
                updates[k] = resolved
        elif k in NUMERIC:
            try:
                updates[k] = flt(v)
            except Exception:
                continue
        elif k in DATE_KEYS:
            parsed = _sanitize_archive_date(v)
            if parsed:
                updates[k] = parsed
            # else skip — don't write invalid date to MySQL
            continue
        else:
            updates[k] = str(v).strip()[:8000] if isinstance(v, str) else v
    # Always normalize ms1/ms2_unbilled when we touched the matching amount or
    # invoiced value — keeps the archive data consistent without running validate.
    if "ms1_amount" in updates or "ms1_invoiced" in updates:
        amt = updates.get("ms1_amount")
        if amt is None:
            amt = flt(frappe.db.get_value("PO Dispatch", dispatch_name, "ms1_amount") or 0)
        inv = flt(updates.get("ms1_invoiced", 0))
        updates["ms1_unbilled"] = round(flt(amt) - inv, 4)
    if "ms2_amount" in updates or "ms2_invoiced" in updates:
        amt = updates.get("ms2_amount")
        if amt is None:
            amt = flt(frappe.db.get_value("PO Dispatch", dispatch_name, "ms2_amount") or 0)
        inv = flt(updates.get("ms2_invoiced", 0))
        updates["ms2_unbilled"] = round(flt(amt) - inv, 4)
    if updates:
        frappe.db.set_value("PO Dispatch", dispatch_name, updates)


def _sync_archive_dispatch_status(dispatch_name, target_status):
    """After stamping PIC fields from an archive row, re-derive the correct
    dispatch_status from that row's own MS1/MS2 status — the archive's raw
    "CLOSED" classification only reflects the source file's own status
    column, not whether both milestones are ACTUALLY closed under the
    stricter Closed/Partially Closed/Submitted/Partially Submitted rules
    (see inet_app.api.pic._compute_dispatch_status_from_pic). Without this,
    an archive line whose MS2 only shows "submitted" (not "closed") would
    import as fully Closed instead of Partially Closed — the exact stale
    classification the one-time backfill patch (sync_dispatch_status_from_pic)
    corrected for existing data; new imports need the same correction going
    forward, not just the one-time fix.

    Only applies when the archive classified this row as "Closed" — that's
    the one case that can actually be wrong under the new rules. "Pending"/
    "Cancelled" reflect the archive file's own explicit classification and
    are left untouched (a local, deferred import to avoid a circular import
    with inet_app.api.pic, which itself imports from this module).

    Also corrects the linked PO Intake Line's po_line_status the same way —
    it was stamped "Closed" earlier from this same raw target_status (see
    _archive_line_status_for), independent of PIC data, so it has the exact
    same gap. po_line_status has no Partially Closed/Submitted/Partially
    Submitted values of its own; anything short of a real "Closed" becomes
    "Completed" there instead (matching how an "OPEN" archive row already
    imports — operationally done, not yet fully commercially wrapped up).
    """
    if target_status != "Closed":
        return
    from inet_app.api.pic import _compute_dispatch_status_from_pic
    row = frappe.db.get_value(
        "PO Dispatch", dispatch_name,
        ["pic_status", "pic_status_ms2", "ms2_amount", "po_intake", "po_line_no"], as_dict=True,
    )
    if not row:
        return
    new_status = _compute_dispatch_status_from_pic(
        row.pic_status, row.pic_status_ms2, row.ms2_amount, "Closed"
    )
    if not new_status or new_status == "Closed":
        return
    frappe.db.set_value("PO Dispatch", dispatch_name, "dispatch_status", new_status)
    if row.po_intake and row.po_line_no:
        il = frappe.db.exists("PO Intake Line", {"parent": row.po_intake, "po_line_no": row.po_line_no})
        if il and isinstance(il, str):
            frappe.db.set_value("PO Intake Line", il, "po_line_status", "Completed")


def _archive_date_keys():
    """All archive-row keys whose source values are Excel date serials in xlsb."""
    return (
        "start_date",
        "end_date",
        "publish_date",
        "ms1_applied_date",
        "ms2_applied_date",
        "ms1_invoice_month",
        "ms2_invoice_month",
        "ms1_ibuy_inv_date",
        "ms2_ibuy_inv_date",
    )


def _excel_serial_to_date_str(value):
    """Normalise any date value from an Excel cell to a YYYY-MM-DD string.

    Handles:
    - Python datetime / date objects (openpyxl xlsx mode)
    - Float / int serial numbers (pyxlsb xlsb mode)
    - Existing string pass-through (already ISO-formatted or month-label)
    """
    if value is None or value == "":
        return None
    import datetime as _datetime_mod
    if isinstance(value, (_datetime_mod.datetime, _datetime_mod.date)):
        return value.strftime("%Y-%m-%d")
    if isinstance(value, (int, float)):
        try:
            from datetime import datetime as _dt, timedelta as _td
            base = _dt(1899, 12, 30)
            return (base + _td(days=float(value))).strftime("%Y-%m-%d")
        except Exception:
            return None
    return str(value)


def _po_archive_resolve_local_path(file_url):
    if file_url and file_url.startswith("/private/files/"):
        return frappe.get_site_path("private", "files", file_url[len("/private/files/"):])
    if file_url and file_url.startswith("/files/"):
        return frappe.get_site_path("public", "files", file_url[len("/files/"):])
    try:
        file_doc = frappe.get_doc("File", {"file_url": file_url})
        return file_doc.get_full_path()
    except Exception:
        frappe.throw(f"Cannot resolve file path for: {file_url}")


def _detect_archive_header_row(rows_iter):
    """Find the header row (the first row containing 'PO NO.' or 'PO Status').

    Master Tracker exports often prepend a totals row before the real headers.
    """
    headers = None
    skipped = 0
    while True:
        try:
            row = next(rows_iter)
        except StopIteration:
            break
        vals = [(str(v).strip() if v is not None else "") for v in row]
        if any(h in ("PO NO.", "PO No.", "PO No", "PO Status", "POID") for h in vals):
            headers = vals
            break
        skipped += 1
        if skipped > 8:
            break
    return headers, rows_iter


def _yield_po_archive_rows(file_path, sheet_hint="PO Tracker"):
    """Yield raw row dicts (aliased keys) from xlsb / xlsx / xlsm / csv."""
    ext = os.path.splitext(file_path)[1].lower()

    if ext == ".xlsb":
        try:
            from pyxlsb import open_workbook
        except ImportError:
            frappe.throw("pyxlsb is not installed. Run `bench pip install pyxlsb`.")
        with open_workbook(file_path) as wb:
            target = sheet_hint if sheet_hint in wb.sheets else wb.sheets[0]
            with wb.get_sheet(target) as sheet:
                py_iter = ([c.v for c in r] for r in sheet.rows())
                headers, py_iter = _detect_archive_header_row(py_iter)
                if not headers:
                    return
                col_map = _resolve_archive_header_keys(headers)
                date_keys = _archive_date_keys()
                for vals in py_iter:
                    if not any(v not in (None, "") for v in vals):
                        continue
                    row_dict = {}
                    for col_idx, cell_val in enumerate(vals):
                        std_key = col_map.get(col_idx)
                        if std_key:
                            row_dict[std_key] = cell_val
                    if row_dict:
                        for k in date_keys:
                            if k in row_dict:
                                row_dict[k] = _excel_serial_to_date_str(row_dict[k])
                        # Whole-number ints come back as floats from xlsb; clean
                        # them so POIDs don't end up with `-1-1.0`.
                        for k in ("po_line_no", "shipment_no"):
                            if k in row_dict:
                                row_dict[k] = _normalize_int_token(row_dict[k])
                        yield row_dict
        return

    if ext in (".xlsx", ".xlsm"):
        try:
            import openpyxl
        except ImportError:
            frappe.throw("openpyxl is not installed. Run `bench pip install openpyxl`.")
        wb = openpyxl.load_workbook(file_path, data_only=True, read_only=True)
        ws = wb[sheet_hint] if sheet_hint in wb.sheetnames else wb.active
        py_iter = (list(r) for r in ws.iter_rows(values_only=True))
        headers, py_iter = _detect_archive_header_row(py_iter)
        if not headers:
            return
        col_map = _resolve_archive_header_keys(headers)
        date_keys = _archive_date_keys()
        for vals in py_iter:
            if not any(v not in (None, "") for v in vals):
                continue
            row_dict = {}
            for col_idx, cell_val in enumerate(vals):
                std_key = col_map.get(col_idx)
                if std_key:
                    row_dict[std_key] = cell_val
            if row_dict:
                # openpyxl returns date/datetime cells as Python datetime objects;
                # normalise them to YYYY-MM-DD strings so downstream code and MySQL
                # both see a consistent format (same as the xlsb path).
                for k in date_keys:
                    if k in row_dict:
                        row_dict[k] = _excel_serial_to_date_str(row_dict[k])
                # Numeric-looking ints (line no, shipment no) may be returned as
                # Python int by openpyxl — normalise same as xlsb path.
                for k in ("po_line_no", "shipment_no"):
                    if k in row_dict:
                        row_dict[k] = _normalize_int_token(row_dict[k])
                yield row_dict
        return

    if ext == ".csv":
        with open(file_path, "r", encoding="utf-8-sig", newline="") as f:
            rows = list(csv.reader(f))
        py_iter = iter(rows)
        headers, py_iter = _detect_archive_header_row(py_iter)
        if not headers:
            return
        col_map = _resolve_archive_header_keys(headers)
        for vals in py_iter:
            if not any(v not in (None, "") for v in vals):
                continue
            row_dict = {}
            for col_idx, cell_val in enumerate(vals):
                std_key = col_map.get(col_idx)
                if std_key:
                    row_dict[std_key] = cell_val
            if row_dict:
                yield row_dict
        return

    frappe.throw(f"Unsupported file type: {ext}")


def _archive_status_for(po_status):
    """Map normalized po_status → PO Dispatch dispatch_status; None only for truly unknown rows."""
    s = str(po_status or "").strip().upper()
    if s in ("CLOSED", "CLOSE", "COMPLETED", "DONE"):
        return "Closed"
    if s in ("CANCELLED", "CANCELED", "CANCEL"):
        return "Cancelled"
    if s == "OPEN":
        # Commercially open but operationally done — import as Completed.
        # Caller downgrades this to "Pending" when the row's own PIC data
        # shows no real progress on either milestone — see
        # _archive_row_has_no_pic_progress().
        return "Completed"
    return None


def _archive_row_has_no_pic_progress(row):
    """True when an archive row's PIC Remarks columns show neither milestone
    has actually progressed — blank, or the "Work Not Done" default itself.

    An "OPEN" row defaults to dispatch_status=Completed on the assumption
    the field work was already done historically; but if there's no PIC
    data backing that up on either milestone, there's no evidence the work
    was actually done, so it shouldn't be imported as Completed with
    nothing behind it.
    """
    ms1_raw = str(row.get("pic_status") or "").strip()
    ms2_raw = str(row.get("pic_status_ms2") or "").strip()
    ms1 = normalize_select_value("PO Dispatch", "pic_status", ms1_raw) if ms1_raw else ""
    ms2 = normalize_select_value("PO Dispatch", "pic_status_ms2", ms2_raw) if ms2_raw else ""
    return ms1 in ("", "Work Not Done") and ms2 in ("", "Work Not Done")


def _archive_line_status_for(dispatch_target):
    """Map an archive dispatch_status classification to PO Intake Line's
    (different) status enum — the two doctypes don't share "Pending"."""
    if dispatch_target == "Pending":
        return "Dispatched"  # a PO Dispatch already exists for this line
    return dispatch_target


@frappe.whitelist()
def preview_po_archive_file(file_url):
    """Pre-flight scan: counts, missing UOMs / Items / Projects, and a small sample.

    The customer is *not* required at this stage — it's resolved per-line from
    the row's ``project_code`` (Project Control Center.customer) at import time.
    """
    file_path = _po_archive_resolve_local_path(file_url)
    counts = {"CLOSED": 0, "CANCELLED": 0, "OPEN": 0, "OTHER": 0}
    sample = []
    total = 0
    uoms = set()
    items = set()
    projects = set()
    contracts = set()
    projects_no_customer = set()
    rows_missing_project = 0
    for row_dict in _yield_po_archive_rows(file_path):
        total += 1
        target = _archive_status_for(row_dict.get("po_status"))
        if target == "Closed":
            counts["CLOSED"] += 1
        elif target == "Cancelled":
            counts["CANCELLED"] += 1
        else:
            ps = str(row_dict.get("po_status") or "").strip().upper()
            counts["OPEN" if ps == "OPEN" else "OTHER"] += 1
        if not target:
            continue
        if str(row_dict.get("unit") or "").strip():
            uoms.add(str(row_dict["unit"]).strip())
        if str(row_dict.get("item_code") or "").strip():
            items.add(str(row_dict["item_code"]).strip())
        if str(row_dict.get("project_code") or "").strip():
            projects.add(str(row_dict["project_code"]).strip())
        else:
            rows_missing_project += 1
        if str(row_dict.get("contract") or "").strip():
            contracts.add(str(row_dict["contract"]).strip())
        if len(sample) < 10:
            sample.append({
                "poid": row_dict.get("poid"),
                "po_status": row_dict.get("po_status"),
                "po_no": row_dict.get("po_no"),
                "po_line_no": row_dict.get("po_line_no"),
                "item_code": row_dict.get("item_code"),
                "site_code": row_dict.get("site_code"),
                "site_name": row_dict.get("site_name"),
                "project_code": row_dict.get("project_code"),
                "project_name": row_dict.get("project_name"),
                "qty": row_dict.get("qty"),
                "rate": row_dict.get("rate"),
                "line_amount": row_dict.get("line_amount"),
                "unit": row_dict.get("unit"),
            })

    # UOM check: anything not present in `tabUOM` is missing. Compare
    # case-insensitively because the DB collation accepts `Set`/`SET` as the
    # same row, but `_bulk_existing_set` returns the canonical casing.
    missing_uoms = []
    if uoms:
        existing_uom = _bulk_existing_set("UOM", list(uoms))
        existing_uom_ci = {str(x).strip().lower() for x in existing_uom}
        missing_uoms = sorted([u for u in uoms if u.strip().lower() not in existing_uom_ci])
    # Item check (case-insensitive: same reason).
    missing_items = []
    if items:
        existing_items = _bulk_existing_set("Item", list(items))
        existing_items_ci = {str(x).strip().lower() for x in existing_items}
        missing_items = sorted([i for i in items if i.strip().lower() not in existing_items_ci])
    # Project check: which projects are missing & which exist but have no customer.
    missing_projects = []
    if projects:
        existing_projects = _bulk_existing_set("Project Control Center", list(projects))
        missing_projects = sorted([p for p in projects if p not in existing_projects])
        if existing_projects:
            ph = ", ".join(["%s"] * len(existing_projects))
            no_cust_rows = frappe.db.sql(
                f"SELECT name FROM `tabProject Control Center` "
                f"WHERE name IN ({ph}) AND IFNULL(customer,'') = ''",
                tuple(existing_projects),
            )
            projects_no_customer = sorted([r[0] for r in no_cust_rows])
    # Subcontractor check: contract values not in Subcontract Master will be skipped on import.
    missing_subcontractors = []
    if contracts:
        existing_contracts = _bulk_existing_set("Subcontract Master", list(contracts))
        missing_subcontractors = sorted([c for c in contracts if c not in existing_contracts])

    return {
        "total_rows": total,
        "counts": counts,
        "to_import": counts["CLOSED"] + counts["CANCELLED"] + counts["OPEN"],
        "sample": sample,
        "missing_uoms": missing_uoms,
        "missing_items": missing_items,
        "missing_projects": missing_projects,
        "projects_without_customer": list(projects_no_customer),
        "rows_missing_project_code": rows_missing_project,
        "missing_subcontractors": missing_subcontractors,
        "unique_projects": len(projects),
        "unique_uoms": len(uoms),
        "unique_items": len(items),
    }


def _archive_log_update(log_name, **fields):
    if not log_name or not frappe.db.exists("PO Upload Log", log_name):
        return
    fields = {k: v for k, v in fields.items() if v is not None}
    if not fields:
        return
    frappe.db.set_value("PO Upload Log", log_name, fields, update_modified=True)
    frappe.db.commit()


def _bulk_existing_set(doctype, names):
    if not names:
        return set()
    names = list({str(n).strip() for n in names if str(n or "").strip()})
    if not names:
        return set()
    ph = ", ".join(["%s"] * len(names))
    rows = frappe.db.sql(
        f"SELECT name FROM `tab{doctype}` WHERE name IN ({ph})",
        tuple(names),
    )
    return {r[0] for r in rows}


def _run_po_archive_import(file_url, customer, log_name, chunk_size=200):
    """Background worker: import CLOSED/CANCELLED rows from an archive file.
    Updates the PO Upload Log row with progress; final status Completed/Partial/Failed.
    No auto-dispatch — these rows stay out of the workflow.

    ``customer`` is optional. When empty, each row's customer is resolved from
    its ``project_code`` → ``Project Control Center.customer``. Rows whose
    project has no customer are recorded as failed in the per-PO breakdown.
    """
    try:
        _archive_log_update(log_name, status="Running")
        # Customer is now optional at the upload level — resolved per project.
        fallback_cust = _resolve_customer_link_name(customer) if customer else None

        file_path = _po_archive_resolve_local_path(file_url)
        groups = {}  # keyed by (po_no, customer)
        total_seen = 0
        total_archive = 0
        rows_missing_customer = 0
        unresolved_projects = set()

        # Build a project → customer map up-front
        first_pass_projects = set()
        all_rows = []
        for row in _yield_po_archive_rows(file_path):
            total_seen += 1
            target = _archive_status_for(row.get("po_status"))
            if not target:
                continue
            if target == "Completed" and _archive_row_has_no_pic_progress(row):
                target = "Pending"
            row["_target_status"] = target
            all_rows.append(row)
            if str(row.get("project_code") or "").strip():
                first_pass_projects.add(str(row["project_code"]).strip())
        proj_cust_map = {}
        if first_pass_projects:
            ph = ", ".join(["%s"] * len(first_pass_projects))
            for r in frappe.db.sql(
                f"SELECT name, customer FROM `tabProject Control Center` WHERE name IN ({ph})",
                tuple(first_pass_projects), as_dict=True,
            ) or []:
                if r.customer:
                    proj_cust_map[r.name] = r.customer

        for row in all_rows:
            po_no = str(row.get("po_no") or "").strip()
            if not po_no:
                continue
            proj = str(row.get("project_code") or "").strip()
            cust = proj_cust_map.get(proj) or fallback_cust
            if not cust:
                rows_missing_customer += 1
                if proj:
                    unresolved_projects.add(proj)
                # Skip — will surface in summary
                continue
            groups.setdefault((po_no, cust), []).append(row)
            total_archive += 1

        if total_archive == 0 and rows_missing_customer == 0:
            _archive_log_update(
                log_name, status="Completed",
                total_rows=total_seen, lines_imported=0, lines_skipped=0,
                po_created=0, po_updated=0,
                notes="No CLOSED or CANCELLED rows found in file.",
            )
            return
        if total_archive == 0 and rows_missing_customer > 0:
            _archive_log_update(
                log_name, status="Failed",
                total_rows=total_seen, lines_imported=0,
                lines_skipped=rows_missing_customer,
                po_created=0, po_updated=0,
                notes=(
                    f"All {rows_missing_customer} archive rows lack a resolvable customer "
                    f"(missing on Project Control Center). Set customer on these projects first: "
                    f"{', '.join(sorted(unresolved_projects)[:30])}"
                ),
            )
            return

        # Pre-resolve master existence so we don't run per-row checks.
        all_projects = {str(l.get("project_code") or "").strip() for ls in groups.values() for l in ls if l.get("project_code")}
        all_items = {str(l.get("item_code") or "").strip() for ls in groups.values() for l in ls if l.get("item_code")}
        all_duids = {str(l.get("site_code") or "").strip() for ls in groups.values() for l in ls if l.get("site_code")}
        all_uoms = {str(l.get("unit") or "").strip() for ls in groups.values() for l in ls if l.get("unit")}
        existing_projects = _bulk_existing_set("Project Control Center", list(all_projects))
        existing_items = _bulk_existing_set("Item", list(all_items))
        existing_duids = _bulk_existing_set("DUID Master", list(all_duids))
        existing_uoms = _bulk_existing_set("UOM", list(all_uoms))
        # Case-insensitive lookup: file may say `Set`, DB says `SET`.
        existing_uoms_ci = {str(x).strip().lower(): str(x) for x in existing_uoms}
        cim_done = set()

        def _ensure_project(line, resolved_cust):
            code = str(line.get("project_code") or "").strip()
            if not code:
                return None
            if code in existing_projects:
                return code
            try:
                ok, _ = ensure_project_control_center(
                    code, resolved_cust, line.get("project_name"), line.get("center_area"),
                )
                if ok:
                    existing_projects.add(code)
                    return code
            except Exception:
                pass
            return None

        def _ensure_item(line):
            code = str(line.get("item_code") or "").strip()
            if not code or code in existing_items:
                return
            try:
                ok, _ = ensure_item_master(code, line.get("item_description"))
                if ok:
                    existing_items.add(code)
            except Exception:
                pass

        def _ensure_duid(line):
            code = str(line.get("site_code") or "").strip()
            if not code or code in existing_duids:
                return
            try:
                ok, _ = ensure_duid_master(code, line.get("site_name"), line.get("center_area"))
                if ok:
                    existing_duids.add(code)
            except Exception:
                pass

        po_created = 0
        po_updated = 0
        lines_imported = 0
        lines_overridden = 0
        lines_skipped = 0
        lines_failed = 0
        per_po = []

        group_keys = list(groups.keys())
        for chunk_idx in range(0, len(group_keys), chunk_size):
            chunk = group_keys[chunk_idx: chunk_idx + chunk_size]
            for key in chunk:
                po_no, group_customer = key
                lines = groups[key]
                statuses = {l.get("_target_status") for l in lines}
                hdr_status = "CANCELLED" if statuses == {"Cancelled"} else "CLOSED"

                existing_name = frappe.db.get_value("PO Intake", {"po_no": po_no}, "name")
                # poid → {line_name, dispatch_name, dispatch_status}
                existing_poids = {}
                if existing_name:
                    rows_existing = frappe.db.sql(
                        "SELECT name, po_line_no, shipment_number, poid FROM `tabPO Intake Line` WHERE parent=%s",
                        existing_name, as_dict=True,
                    ) or []
                    # Look up dispatches by po_intake + po_line_no — the same
                    # key _upsert_po_dispatch_for_line uses, avoids POID format mismatches.
                    # PO Dispatch has no shipment_number column; po_line_no is the join key.
                    dispatch_by_line = {}
                    for dr in (frappe.db.sql(
                        "SELECT po_line_no, name, dispatch_status "
                        "FROM `tabPO Dispatch` WHERE po_intake=%s",
                        existing_name, as_dict=True,
                    ) or []):
                        dispatch_by_line[cint(dr.po_line_no)] = {
                            "dispatch_name": dr.name,
                            "dispatch_status": dr.dispatch_status or "",
                        }
                    for r in rows_existing:
                        pid = (r.poid or "").strip() or _make_poid(po_no, r.po_line_no, r.shipment_number)
                        existing_poids[pid] = {
                            "line_name": r.name,
                            **dispatch_by_line.get(cint(r.po_line_no), {}),
                        }

                new_entries = []
                override_entries = []  # (line, append_row, info) — Excel always wins
                po_skipped = 0
                for line in lines:
                    poid = _poid_for_upload_line(po_no, line)
                    info = existing_poids.get(poid)  # None = brand new POID

                    # Resolve all data regardless of new vs override
                    # Item code is mandatory on PO Intake Line for the standard
                    # workflow, but archive imports may include legacy rows where
                    # it's blank or set to "NA". Fall back to the description so
                    # ``ensure_item_master`` can create something usable; if even
                    # the description is empty we rely on ``flags.ignore_mandatory``
                    # below to let the row through.
                    item_code, used_desc = _resolve_item_code_with_fallback(line)
                    if used_desc and item_code:
                        line["item_code"] = item_code
                        if not str(line.get("item_description") or "").strip():
                            line["item_description"] = item_code

                    proj = _ensure_project(line, group_customer)
                    _ensure_item(line)
                    _ensure_duid(line)

                    if item_code:
                        ck = (group_customer, item_code)
                        if ck not in cim_done:
                            try:
                                ensure_customer_item_master(group_customer, item_code)
                            except Exception:
                                pass
                            cim_done.add(ck)

                    # UOM may not exist; setting an unknown link will fail
                    # validation. Probe case-insensitively and use the canonical
                    # DB name when found.
                    raw_uom = (str(line.get("unit") or "").strip() or None)
                    uom_value = existing_uoms_ci.get(raw_uom.lower()) if raw_uom else None

                    line_center_area = line.get("center_area")
                    line_region = region_type_from_center_area(line_center_area)
                    desc = line.get("item_description")
                    if isinstance(desc, str):
                        desc = desc[:8000]  # Small Text upper bound, generous

                    append_row = {
                        "source_id": line.get("source_id"),
                        "po_line_no": cint(line.get("po_line_no") or 0),
                        "shipment_number": _normalize_int_token(line.get("shipment_no")) or None,
                        "poid": poid,
                        "site_code": str(line.get("site_code") or "").strip() or None,
                        "site_name": line.get("site_name"),
                        "item_code": item_code,
                        "item_description": desc,
                        "uom": uom_value,
                        "qty": flt(line.get("qty", 0)),
                        "due_qty": flt(line.get("due_qty", 0)),
                        "billed_quantity": flt(line.get("billed_quantity", 0)),
                        "quantity_cancel": flt(line.get("quantity_cancel", 0)),
                        "start_date": line.get("start_date") or None,
                        "end_date": line.get("end_date") or None,
                        "sub_contract_no": line.get("sub_contract_no"),
                        "currency": line.get("currency"),
                        "rate": flt(line.get("rate", 0)),
                        "line_amount": flt(line.get("line_amount", 0)),
                        "tax_rate": line.get("tax_rate"),
                        "payment_terms": line.get("payment_terms"),
                        "project_code": proj,
                        "project_name": line.get("project_name"),
                        "center_area": line_center_area,
                        "region_type": line_region,
                        "publish_date": line.get("publish_date") or None,
                        "po_line_status": _archive_line_status_for(line.get("_target_status")),
                        "dispatch_mode": "Manual",
                    }

                    if info is not None:
                        # Existing POID — Excel is source of truth, always override
                        override_entries.append((line, append_row, info))
                    else:
                        new_entries.append((line, append_row))
                        existing_poids[poid] = {}  # prevent duplicate within same file

                if not new_entries and not override_entries:
                    lines_skipped += po_skipped
                    if po_skipped > 0:
                        per_po.append({
                            "po_no": po_no, "intake_name": existing_name,
                            "lines_added": 0, "lines_skipped": po_skipped, "is_new": False,
                        })
                    continue

                # Only touch the PO Intake parent doc when there are new lines to append.
                # Override-only runs skip the save entirely — set_value on child rows is
                # sufficient and avoids Frappe validation that would skip overrides via `continue`.
                doc = None
                is_new_po = False
                new_entries_failed = False

                if new_entries:
                    frappe.db.sql("SAVEPOINT _archive_po")
                    try:
                        if existing_name:
                            doc = frappe.get_doc("PO Intake", existing_name)
                            doc.status = _normalize_po_intake_status(hdr_status)
                            for _src, append_row in new_entries:
                                doc.append("po_lines", append_row)
                            # Archive: legacy lines may have blank item_code / qty.
                            doc.flags.ignore_mandatory = True
                            doc.save(ignore_permissions=True)
                            po_updated += 1
                        else:
                            doc = frappe.new_doc("PO Intake")
                            doc.po_no = po_no
                            doc.customer = group_customer
                            doc.status = _normalize_po_intake_status(hdr_status)
                            doc.publish_date = lines[0].get("publish_date") or None
                            doc.center_area = lines[0].get("center_area")
                            for _src, append_row in new_entries:
                                doc.append("po_lines", append_row)
                            doc.flags.ignore_mandatory = True
                            doc.insert(ignore_permissions=True)
                            is_new_po = True
                            po_created += 1
                    except Exception as e:
                        frappe.db.sql("ROLLBACK TO SAVEPOINT _archive_po")
                        err_msg = frappe.utils.cstr(e)[:1000]
                        lines_failed += len(new_entries)
                        per_po.append({
                            "po_no": po_no, "intake_name": existing_name,
                            "lines_added": 0, "lines_skipped": len(new_entries),
                            "is_new": not bool(existing_name), "error": err_msg,
                        })
                        new_entries_failed = True
                        new_entries = []  # clear so dispatch creation is skipped below
                elif existing_name:
                    # Override-only: get a lightweight doc reference (for orphaned dispatch creation)
                    doc = frappe.get_cached_doc("PO Intake", existing_name)

                child_sql_rows = frappe.db.sql(
                    "SELECT name, po_line_no, shipment_number, poid FROM `tabPO Intake Line` WHERE parent=%s",
                    doc.name, as_dict=True,
                ) if doc and new_entries else []
                new_poid_map = {ar["poid"]: ar for _src, ar in new_entries}
                for r in child_sql_rows:
                    got_poid = (r.poid or "").strip() or _make_poid(po_no, r.po_line_no, r.shipment_number)
                    if got_poid not in new_poid_map:
                        continue
                    line_dict = dict(new_poid_map[got_poid])
                    line_dict["name"] = r.name
                    line_dict["parent"] = doc.name
                    target_status = next(
                        (l["_target_status"] for l in lines if _poid_for_upload_line(po_no, l) == got_poid),
                        "Closed",
                    )
                    try:
                        dispatch_name = _upsert_po_dispatch_for_line(
                            doc.name, po_no, line_dict,
                            customer=group_customer,
                            dispatch_status=target_status,
                            dispatch_mode="Manual",
                        )
                        # Stamp the rich PIC / invoice-tracking fields from
                        # the source archive row onto the just-upserted dispatch.
                        src_line = next(
                            (l for l in lines if _poid_for_upload_line(po_no, l) == got_poid),
                            None,
                        )
                        if dispatch_name and src_line:
                            _stamp_archive_pic_fields(dispatch_name, src_line)
                            _sync_archive_dispatch_status(dispatch_name, target_status)
                    except Exception as e:
                        per_po.append({
                            "po_no": po_no, "intake_name": doc.name,
                            "lines_added": 0, "lines_skipped": 1,
                            "is_new": False, "error": f"dispatch error: {frappe.utils.cstr(e)[:800]}",
                        })

                lines_imported += len(new_entries)
                lines_skipped += po_skipped

                # Override existing POIDs — Excel is always source of truth, full data update
                po_overridden = 0
                for src_line, append_row, info in override_entries:
                    target_status = src_line.get("_target_status", "Completed")
                    dispatch_name = info.get("dispatch_name")
                    line_name = info.get("line_name")
                    try:
                        if line_name:
                            # Update all fields on the PO Intake Line from Excel
                            intake_updates = {
                                k: v for k, v in append_row.items()
                                if k not in ("poid", "po_line_no", "shipment_number", "source_id")
                                and v is not None and v != ""
                            }
                            if intake_updates:
                                frappe.db.set_value(
                                    "PO Intake Line", line_name, intake_updates,
                                    update_modified=False,
                                )
                        if not dispatch_name and doc:
                            # Orphaned intake line — create the missing PO Dispatch
                            line_dict = dict(append_row)
                            line_dict["name"] = line_name
                            line_dict["parent"] = doc.name
                            try:
                                dispatch_name = _upsert_po_dispatch_for_line(
                                    doc.name, po_no, line_dict,
                                    customer=group_customer,
                                    dispatch_status=target_status,
                                    dispatch_mode="Manual",
                                )
                            except Exception:
                                dispatch_name = None
                        if dispatch_name:
                            # Update all relevant fields on PO Dispatch from Excel
                            dispatch_updates = {k: v for k, v in {
                                "dispatch_status": target_status,
                                "item_code": append_row.get("item_code"),
                                "item_description": append_row.get("item_description"),
                                "qty": append_row.get("qty"),
                                "rate": append_row.get("rate"),
                                "line_amount": append_row.get("line_amount"),
                                "payment_terms": append_row.get("payment_terms") or "",
                                "tax_rate": append_row.get("tax_rate") or "",
                                "center_area": append_row.get("center_area"),
                                "region_type": append_row.get("region_type"),
                                "site_code": append_row.get("site_code"),
                                "site_name": append_row.get("site_name"),
                                "project_code": append_row.get("project_code"),
                            }.items() if v is not None and v != ""}
                            # An archive row can classify an existing dispatch as
                            # "Pending" (see _archive_row_has_no_pic_progress) based
                            # only on that row's own, possibly-blank PIC columns —
                            # but a dispatch that already has an `im` assigned was,
                            # by definition, already dispatched: dispatch_po_lines
                            # sets dispatch_status="Dispatched" the moment im is
                            # assigned and never leaves it at "Pending". Regressing
                            # it back here silently hides the line from every
                            # IM-facing queue (they all filter out Pending rows),
                            # so the IM can no longer act on it at all.
                            if dispatch_updates.get("dispatch_status") == "Pending":
                                existing_im = frappe.db.get_value("PO Dispatch", dispatch_name, "im")
                                if existing_im:
                                    dispatch_updates.pop("dispatch_status", None)
                            if dispatch_updates:
                                frappe.db.set_value(
                                    "PO Dispatch", dispatch_name, dispatch_updates,
                                )
                            _stamp_archive_pic_fields(dispatch_name, src_line)
                            _sync_archive_dispatch_status(dispatch_name, target_status)
                    except Exception as _ov_exc:
                        frappe.log_error(
                            title="Archive override error",
                            message=f"POID {append_row.get('poid')} line={line_name} dispatch={dispatch_name}: {_ov_exc}\n{frappe.get_traceback()}",
                        )
                    po_overridden += 1  # count regardless of PIC stamp errors
                lines_overridden += po_overridden

                per_po.append({
                    "po_no": po_no, "intake_name": (doc.name if doc else existing_name),
                    "lines_added": len(new_entries),
                    "lines_overridden": po_overridden,
                    "lines_skipped": po_skipped,
                    "is_new": is_new_po,
                })

            # One commit per chunk (200 POs) instead of per PO.
            # Savepoints above ensure individual PO errors only undo that PO.
            frappe.db.commit()
            _archive_log_update(
                log_name,
                total_rows=total_archive,
                lines_imported=lines_imported,
                lines_skipped=lines_skipped,
                po_created=po_created,
                po_updated=po_updated,
                notes=f"Processed {min(chunk_idx + chunk_size, len(group_keys))}/{len(group_keys)} POs",
            )

        try:
            log_doc = frappe.get_doc("PO Upload Log", log_name)
            log_doc.set("po_details", [])
            for d in per_po:
                if d.get("error"):
                    detail_status = "Failed"
                elif d.get("lines_added") or d.get("lines_overridden"):
                    detail_status = "New" if d.get("is_new") else "Appended"
                else:
                    detail_status = "Duplicate"
                log_doc.append("po_details", {
                    "po_no": d.get("po_no"),
                    "intake_name": d.get("intake_name"),
                    "status": detail_status,
                    "lines_added": d.get("lines_added") or 0,
                    "lines_skipped": d.get("lines_skipped") or 0,
                    "error": d.get("error") or "",
                })
            log_doc.status = "Completed" if lines_failed == 0 else "Partial"
            log_doc.total_rows = total_archive
            log_doc.lines_imported = lines_imported
            log_doc.lines_overridden = lines_overridden
            log_doc.lines_skipped = lines_skipped + lines_failed
            log_doc.po_created = po_created
            log_doc.po_updated = po_updated
            log_doc.auto_dispatched = 0
            log_doc.notes = (
                f"Archive import: {total_archive} archive rows; "
                f"{lines_imported} imported (new), {lines_overridden} overridden (open→closed/cancelled), "
                f"{lines_skipped} skipped (already terminal), {lines_failed} failed."
            )
            log_doc.save(ignore_permissions=True)
            frappe.db.commit()
        except Exception:
            _archive_log_update(
                log_name, status="Partial",
                total_rows=total_archive,
                lines_imported=lines_imported,
                lines_skipped=lines_skipped + lines_failed,
                po_created=po_created, po_updated=po_updated,
                notes="Imported but failed to write per-PO breakdown.",
            )
    except Exception as e:
        frappe.log_error(title="PO archive import failed", message=frappe.get_traceback())
        _archive_log_update(log_name, status="Failed", notes=f"Error: {str(e)[:240]}")


@frappe.whitelist()
def start_po_archive_import(file_url, customer=None):
    """Kick off an archive import in the background. Returns a log_name to poll.

    ``customer`` is optional — if not given, each row's customer is resolved
    from its ``project_code``. The file is attached to the PO Upload Log doc
    so admins can re-download what was imported.
    """
    if not file_url:
        frappe.throw("file_url is required")
    file_path = _po_archive_resolve_local_path(file_url)
    if not os.path.exists(file_path):
        frappe.throw(f"File not found on server: {file_url}")
    resolved_cust = None
    if customer:
        resolved_cust = _resolve_customer_link_name(customer)
        if not resolved_cust:
            frappe.throw(f"Customer not found: {customer}")

    log = frappe.new_doc("PO Upload Log")
    log.uploaded_by = frappe.session.user
    log.uploaded_at = frappe.utils.now_datetime()
    log.customer = resolved_cust
    log.file_name = os.path.basename(file_path)
    log.file_url = file_url
    log.upload_mode = "Archive"
    log.status = "Queued"
    log.total_rows = 0
    log.lines_imported = 0
    log.lines_skipped = 0
    log.po_created = 0
    log.po_updated = 0
    log.auto_dispatched = 0
    log.insert(ignore_permissions=True)

    # Attach the source file to the log so it stays linked.
    try:
        attach = frappe.get_doc({
            "doctype": "File",
            "file_url": file_url,
            "file_name": os.path.basename(file_path),
            "attached_to_doctype": "PO Upload Log",
            "attached_to_name": log.name,
            "is_private": 1 if "/private/" in (file_url or "") else 0,
        })
        attach.insert(ignore_permissions=True, ignore_links=True)
    except Exception:
        # Non-fatal: the import still runs; the file_url is on the log doc.
        pass

    frappe.db.commit()

    frappe.enqueue(
        "inet_app.api.command_center._run_po_archive_import",
        queue="long", timeout=3600,
        file_url=file_url, customer=resolved_cust, log_name=log.name,
    )
    return {"log_name": log.name, "status": log.status}


@frappe.whitelist()
def get_po_archive_import_status(log_name):
    """Lightweight status snapshot for the FE poller."""
    if not frappe.db.exists("PO Upload Log", log_name):
        frappe.throw(f"PO Upload Log not found: {log_name}")
    row = frappe.db.get_value(
        "PO Upload Log", log_name,
        ["status", "total_rows", "lines_imported", "lines_overridden", "lines_skipped",
         "po_created", "po_updated", "notes", "uploaded_at", "file_name"],
        as_dict=True,
    ) or {}
    row["log_name"] = log_name
    return row


# ---------------------------------------------------------------------------
# Team Allocation Request — IM-to-IM transfer with PM approval
#
# Lifecycle:
#   Pending Source IM → (source IM accept) → Pending PM Approval
#                     → (source IM reject) → Rejected by Source IM (terminal)
#   Pending Source IM → (requester cancel)  → Cancelled (terminal)
#   Pending PM Approval → (PM approve) → Approved (terminal, atomic flip)
#   Pending PM Approval → (PM reject)  → Rejected by PM (terminal)
#
# The atomic flip is a single SQL UPDATE on `INET Team.im` plus the status
# bump in the same transaction so a race (two concurrent approvals on
# different requests for the same team) can't leak a half-applied state.
# ---------------------------------------------------------------------------


def _is_pm_role():
    """PM-level approver: Administrator / System Manager / INET Admin.
    INET IM alone is not enough — IMs cannot approve their own transfers."""
    roles = set(frappe.get_roles(frappe.session.user))
    return bool(roles & {"Administrator", "System Manager", "INET Admin"})


# ---------------------------------------------------------------------------
# Data Integrity — PM-facing review of PO Dispatch status mismatches that
# slip in from manual desk edits, historical bugs, or archive import. Each
# category here is a *symptom* (dispatch_status disagreeing with the real
# evidence behind it), not a single root cause — new categories should be
# added here as they're found rather than silently patched away, so PM has
# one place to see and fix all of them instead of a one-off script per bug.
# ---------------------------------------------------------------------------

_DATA_INTEGRITY_TERMINAL_MS = {"Commercial Invoice Closed", "Commercial Invoice Submitted", "PO Line Canceled"}


@frappe.whitelist()
def list_data_integrity_issues(category):
    """Rows for one Data Integrity category — see the tab definitions in
    the frontend for the full category list."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    category = (category or "").strip()

    base_select = """
        SELECT pd.name, pd.poid, pd.po_no, pd.project_code, proj.project_name,
               pd.site_code, pd.dispatch_status, pd.pic_status, pd.pic_status_ms2,
               pd.line_amount, pd.ms1_amount, pd.ms1_invoiced, pd.ms2_amount, pd.ms2_invoiced,
               pd.modified
        FROM `tabPO Dispatch` pd
        LEFT JOIN `tabProject Control Center` proj ON proj.name = pd.project_code
    """

    if category == "completed_no_evidence":
        rows = frappe.db.sql(
            f"""
            {base_select}
            WHERE pd.dispatch_status = 'Completed'
              AND IFNULL(pd.is_internal_work, 0) = 0
              AND IFNULL(pd.is_dummy_po, 0) = 0
              AND IFNULL(pd.pic_status, '') IN ('', 'Work Not Done')
              AND IFNULL(pd.pic_status_ms2, '') IN ('', 'Work Not Done')
              AND NOT EXISTS (SELECT 1 FROM `tabWork Done` wd WHERE wd.system_id = pd.name)
              -- Not "no evidence" if a real execution actually completed —
              -- that's a different bug (Work Done generation didn't fire),
              -- not an absence of work. Excluded here so it doesn't get
              -- wrongly reopened as Pending.
              AND NOT EXISTS (
                SELECT 1 FROM `tabDaily Execution` de
                JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
                WHERE rp.po_dispatch = pd.name
                  AND (de.execution_status = 'Completed' OR de.tl_status = 'Completed')
              )
            ORDER BY pd.modified DESC
            """,
            as_dict=True,
        )
    elif category == "closed_unresolved_milestone":
        ph = ", ".join(["%s"] * len(_DATA_INTEGRITY_TERMINAL_MS))
        rows = frappe.db.sql(
            f"""
            {base_select}
            WHERE pd.dispatch_status = 'Closed'
              AND IFNULL(pd.is_internal_work, 0) = 0
              AND IFNULL(pd.is_dummy_po, 0) = 0
              AND (
                (IFNULL(pd.ms1_amount, 0) > 0 AND IFNULL(pd.pic_status, '') NOT IN ({ph}))
                OR
                (IFNULL(pd.ms2_amount, 0) > 0 AND IFNULL(pd.pic_status_ms2, '') NOT IN ({ph}))
              )
            ORDER BY pd.modified DESC
            """,
            tuple(_DATA_INTEGRITY_TERMINAL_MS) * 2,
            as_dict=True,
        )
        for r in rows:
            r["ms1_stuck"] = bool(flt(r.get("ms1_amount")) > 0 and (r.get("pic_status") or "") not in _DATA_INTEGRITY_TERMINAL_MS)
            r["ms2_stuck"] = bool(flt(r.get("ms2_amount")) > 0 and (r.get("pic_status_ms2") or "") not in _DATA_INTEGRITY_TERMINAL_MS)
            r["ms1_unbilled"] = flt(r.get("ms1_amount")) - flt(r.get("ms1_invoiced")) if r["ms1_stuck"] else 0
            r["ms2_unbilled"] = flt(r.get("ms2_amount")) - flt(r.get("ms2_invoiced")) if r["ms2_stuck"] else 0
    else:
        frappe.throw(f"Unknown category: {category}")

    return rows


def _reset_linked_intake_line_status(dispatch_name, status):
    """Mirror a dispatch_status fix onto the linked PO Intake Line, mapping
    to that doctype's own (different) status enum — see
    _archive_line_status_for in pic.py for the same mapping rationale."""
    po_intake, po_line_no = frappe.db.get_value(
        "PO Dispatch", dispatch_name, ["po_intake", "po_line_no"]
    ) or (None, None)
    if not (po_intake and po_line_no):
        return
    intake_line = frappe.db.exists("PO Intake Line", {"parent": po_intake, "po_line_no": po_line_no})
    if intake_line and isinstance(intake_line, str):
        frappe.db.set_value("PO Intake Line", intake_line, "po_line_status", status, update_modified=False)


@frappe.whitelist()
def fix_data_integrity_completed_no_evidence(po_dispatches):
    """Bulk fix for the "completed_no_evidence" category: no real Work Done
    behind a Completed dispatch means there's no evidence work actually
    happened, so reopen it as a normal open line instead of leaving it
    falsely marked Completed. Reopens to "Dispatched" (not "Pending") when
    an IM is already assigned — Pending would wrongly imply it was never
    dispatched to anyone."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    if isinstance(po_dispatches, str):
        po_dispatches = frappe.parse_json(po_dispatches) or []
    if not isinstance(po_dispatches, (list, tuple)) or not po_dispatches:
        frappe.throw("po_dispatches list is required")

    fixed = []
    for name in po_dispatches:
        name = str(name or "").strip()
        if not name or not frappe.db.exists("PO Dispatch", name):
            continue
        has_im = bool(frappe.db.get_value("PO Dispatch", name, "im"))
        frappe.db.set_value("PO Dispatch", name, "dispatch_status", "Dispatched" if has_im else "Pending", update_modified=True)
        _reset_linked_intake_line_status(name, "Dispatched")
        fixed.append(name)
    if fixed:
        frappe.db.commit()
    return {"fixed": fixed, "count": len(fixed)}


@frappe.whitelist()
def fix_data_integrity_reopen_closed(po_dispatches):
    """Bulk fix for the "closed_unresolved_milestone" category: reverts
    dispatch_status from Closed back to Completed so the line falls back
    into PIC Tracker's normal workflow — PIC decides the real invoicing
    outcome there using the existing milestone logic, this doesn't guess
    at a pic_status on their behalf."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    if isinstance(po_dispatches, str):
        po_dispatches = frappe.parse_json(po_dispatches) or []
    if not isinstance(po_dispatches, (list, tuple)) or not po_dispatches:
        frappe.throw("po_dispatches list is required")

    fixed = []
    for name in po_dispatches:
        name = str(name or "").strip()
        if not name or not frappe.db.exists("PO Dispatch", name):
            continue
        if frappe.db.get_value("PO Dispatch", name, "dispatch_status") != "Closed":
            continue
        frappe.db.set_value("PO Dispatch", name, "dispatch_status", "Completed", update_modified=True)
        _reset_linked_intake_line_status(name, "Completed")
        fixed.append(name)
    if fixed:
        frappe.db.commit()
    return {"fixed": fixed, "count": len(fixed)}


def _resolve_caller_im_or_throw():
    """Return the IM Master *document name* for the calling user. Throws
    if the user has no INET IM role or no IM Master row links to them.

    NB: must use ``im_resolved`` (the doctype name), not ``im_identifiers[0]``
    — identifiers is a Python set of usable Link values (name / full_name /
    email) and its order is non-deterministic, so picking [0] occasionally
    yields the IM's full name and breaks downstream Link validation on
    Team Allocation Request.{from_im,to_im}.
    """
    im_resolved, im_ids, _meta = resolve_im_for_session()
    if not im_resolved or not frappe.db.exists("IM Master", im_resolved):
        # Fallback: scan identifiers for one that does match a real IM Master
        # document name. Defensive — covers edge sites where im_resolved
        # came back empty but identifiers still has the doc name in it.
        for cand in im_ids or []:
            if cand and frappe.db.exists("IM Master", cand):
                return cand
        frappe.throw(
            "No IM Master is linked to your user — cannot act on team requests.",
            frappe.ValidationError,
        )
    return im_resolved


def _team_allocation_serialize(name, *, as_doc=None):
    """Return a JSON-friendly snapshot of a Team Allocation Request — used
    by the FE list / detail views and by the action endpoints' return."""
    d = as_doc or frappe.db.get_value(
        "Team Allocation Request", name,
        [
            "name", "team", "from_im", "to_im", "requested_by",
            "request_status", "reason", "source_im_remark", "pm_remark",
            "responded_by", "responded_at", "approved_by", "approved_at",
            "creation", "modified",
        ],
        as_dict=True,
    )
    if not d:
        return None
    # Enrich with team_name / IM names so the FE doesn't need extra lookups.
    if d.get("team"):
        d["team_name"] = frappe.db.get_value("INET Team", d["team"], "team_name") or d["team"]
    for key in ("from_im", "to_im"):
        v = d.get(key)
        if v:
            d[f"{key}_name"] = frappe.db.get_value("IM Master", v, "full_name") or v
    return d


@frappe.whitelist()
def request_team_allocation(team, reason=None):
    """An IM (caller) requests transfer of `team` from its current IM to
    themselves. Captures `team.im` as `from_im` snapshot. Rejects when:
    - caller is already the team's IM (nothing to request)
    - team has no current IM (no source to ask)
    - a Pending request already exists for this team
    """
    team = (team or "").strip()
    if not team:
        frappe.throw("team is required")
    if not frappe.db.exists("INET Team", team):
        frappe.throw(f"INET Team {team} not found")
    caller_im = _resolve_caller_im_or_throw()
    current_im = frappe.db.get_value("INET Team", team, "im")
    if not current_im:
        frappe.throw("Team has no current IM — assign one in INET Team before requesting transfer.")
    if current_im == caller_im:
        frappe.throw("You already own this team. Nothing to request.")
    # Block when a non-terminal request already exists for this team.
    existing = frappe.db.sql(
        "SELECT name FROM `tabTeam Allocation Request` "
        "WHERE team = %s AND request_status IN ('Pending Source IM', 'Pending PM Approval') "
        "LIMIT 1",
        (team,),
    )
    if existing:
        frappe.throw(
            f"A pending allocation request already exists for {team} "
            f"({existing[0][0]}). Wait for that one to resolve before opening another."
        )
    doc = frappe.new_doc("Team Allocation Request")
    doc.team = team
    doc.from_im = current_im
    doc.to_im = caller_im
    doc.requested_by = frappe.session.user
    doc.request_status = "Pending Source IM"
    if reason:
        doc.reason = str(reason)[:2000]
    doc.insert(ignore_permissions=True)
    frappe.db.commit()
    try:
        from inet_app.api.notifications import notify_source_im_allocation_requested
        notify_source_im_allocation_requested(doc.name)
    except Exception:
        pass
    return _team_allocation_serialize(doc.name)


def _assert_request_caller_role(req, role):
    """Verify the calling user has the right to take `role`'s action on
    this request. `role` is one of: 'requester', 'source_im', 'pm'."""
    user = frappe.session.user
    if role == "requester":
        if req.requested_by != user:
            frappe.throw("Only the original requester can cancel.", frappe.PermissionError)
        return
    if role == "source_im":
        # User must be the IM Master.user for from_im.
        from_user = frappe.db.get_value("IM Master", req.from_im, "user")
        if from_user != user and not _is_pm_role():
            frappe.throw(
                "Only the source IM (or a PM) can respond to this request.",
                frappe.PermissionError,
            )
        return
    if role == "pm":
        if not _is_pm_role():
            frappe.throw("Only a PM / Admin can approve transfers.", frappe.PermissionError)
        return
    frappe.throw(f"Unknown role check: {role}", frappe.ValidationError)


@frappe.whitelist()
def respond_team_allocation(request, action, remark=None):
    """Source IM accepts/rejects a pending request.
    `action` ∈ {"accept", "reject"}. On accept: status → Pending PM Approval.
    On reject: terminal Rejected by Source IM. Atomic — done in one update."""
    request = (request or "").strip()
    action = (action or "").strip().lower()
    if action not in ("accept", "reject"):
        frappe.throw("action must be 'accept' or 'reject'")
    req = frappe.get_doc("Team Allocation Request", request)
    if req.request_status != "Pending Source IM":
        frappe.throw(
            f"Request is not awaiting the source IM (current status: {req.request_status})."
        )
    _assert_request_caller_role(req, "source_im")
    new_status = "Pending PM Approval" if action == "accept" else "Rejected by Source IM"
    updates = {
        "request_status": new_status,
        "responded_by": frappe.session.user,
        "responded_at": now_datetime(),
    }
    if remark:
        updates["source_im_remark"] = str(remark)[:2000]
    frappe.db.set_value("Team Allocation Request", request, updates, update_modified=True)
    frappe.db.commit()
    try:
        if new_status == "Pending PM Approval":
            from inet_app.api.notifications import notify_pm_allocation_pending
            notify_pm_allocation_pending(request)
        else:
            from inet_app.api.notifications import notify_to_im_allocation_source_rejected
            notify_to_im_allocation_source_rejected(request)
    except Exception:
        pass
    return _team_allocation_serialize(request)


@frappe.whitelist()
def pm_decide_team_allocation(request, action, remark=None):
    """PM approves or rejects a request that has cleared source IM.
    `action` ∈ {"approve", "reject"}. On approve: atomically flip
    INET Team.im → to_im in the same transaction as the status bump."""
    request = (request or "").strip()
    action = (action or "").strip().lower()
    if action not in ("approve", "reject"):
        frappe.throw("action must be 'approve' or 'reject'")
    req = frappe.get_doc("Team Allocation Request", request)
    if req.request_status != "Pending PM Approval":
        frappe.throw(
            f"Request is not awaiting PM approval (current status: {req.request_status})."
        )
    _assert_request_caller_role(req, "pm")

    if action == "reject":
        frappe.db.set_value(
            "Team Allocation Request", request,
            {
                "request_status": "Rejected by PM",
                "approved_by": frappe.session.user,
                "approved_at": now_datetime(),
                "pm_remark": str(remark or "")[:2000] or None,
            },
            update_modified=True,
        )
        frappe.db.commit()
        try:
            from inet_app.api.notifications import notify_ims_allocation_pm_decided
            notify_ims_allocation_pm_decided(request, "reject")
        except Exception:
            pass
        return _team_allocation_serialize(request)

    # Approve — atomic transfer. Re-read the team's current IM and only
    # apply the flip if it still matches `from_im`. If someone else has
    # already moved the team out from under us (e.g. an Admin edit),
    # surface a clean error instead of silently losing the to_im change.
    current_im = frappe.db.get_value("INET Team", req.team, "im")
    if current_im != req.from_im:
        frappe.throw(
            f"Team {req.team} is no longer owned by {req.from_im} (current: {current_im}). "
            "Reject this request and create a fresh one."
        )
    # Both writes share the running transaction; commit() flushes both.
    frappe.db.set_value(
        "INET Team", req.team, "im", req.to_im, update_modified=True,
    )
    frappe.db.set_value(
        "Team Allocation Request", request,
        {
            "request_status": "Approved",
            "approved_by": frappe.session.user,
            "approved_at": now_datetime(),
            "pm_remark": str(remark or "")[:2000] or None,
        },
        update_modified=True,
    )
    frappe.db.commit()
    try:
        from inet_app.api.notifications import notify_ims_allocation_pm_decided
        notify_ims_allocation_pm_decided(request, "approve")
    except Exception:
        pass
    return _team_allocation_serialize(request)


@frappe.whitelist()
def cancel_team_allocation(request):
    """Requester withdraws a request that's still awaiting the source IM.
    Once the source IM has accepted, ownership of the decision moves to
    the PM and the requester can no longer cancel."""
    request = (request or "").strip()
    req = frappe.get_doc("Team Allocation Request", request)
    if req.request_status != "Pending Source IM":
        frappe.throw(
            "Cannot cancel — request has already moved past the source IM step."
        )
    _assert_request_caller_role(req, "requester")
    frappe.db.set_value(
        "Team Allocation Request", request,
        {"request_status": "Cancelled"},
        update_modified=True,
    )
    frappe.db.commit()
    return _team_allocation_serialize(request)


@frappe.whitelist()
def list_team_allocation_requests(scope="all", status=None, limit=200):
    """Return team allocation requests visible to the caller.

    `scope` ∈ {"all", "outgoing", "incoming", "pending_pm"}.
      - "outgoing"   — requests where caller IM is `to_im` (their requests)
      - "incoming"   — requests where caller IM is `from_im` (decisions
                       awaiting them)
      - "pending_pm" — PM/Admin approval queue (status = Pending PM Approval)
      - "all"        — all rows the caller has read access to
    Optional `status` further filters.
    """
    scope = (scope or "all").strip().lower()
    wheres = []
    params = []
    if scope in ("outgoing", "incoming"):
        try:
            caller_im = _resolve_caller_im_or_throw()
        except Exception:
            return []
        col = "to_im" if scope == "outgoing" else "from_im"
        wheres.append(f"{col} = %s")
        params.append(caller_im)
    elif scope == "pending_pm":
        wheres.append("request_status = %s")
        params.append("Pending PM Approval")
    if status:
        wheres.append("request_status = %s")
        params.append(status)
    where_sql = ("WHERE " + " AND ".join(wheres)) if wheres else ""
    try:
        limit = max(1, min(int(limit or 200), 500))
    except Exception:
        limit = 200
    rows = frappe.db.sql(
        f"""
        SELECT name, team, from_im, to_im, requested_by, request_status,
               reason, source_im_remark, pm_remark,
               responded_by, responded_at, approved_by, approved_at,
               creation, modified
        FROM `tabTeam Allocation Request`
        {where_sql}
        ORDER BY modified DESC
        LIMIT {limit}
        """,
        tuple(params), as_dict=True,
    )
    if not rows:
        return []
    # Batch-resolve names so the FE can render labels without per-row calls.
    team_ids = list({r["team"] for r in rows if r.get("team")})
    im_ids = list({i for r in rows for i in (r.get("from_im"), r.get("to_im")) if i})
    team_labels = {}
    if team_ids:
        for t in frappe.db.sql(
            "SELECT name, team_name FROM `tabINET Team` WHERE name IN %(ids)s",
            {"ids": tuple(team_ids)}, as_dict=True,
        ):
            team_labels[t["name"]] = t["team_name"] or t["name"]
    im_labels = {}
    if im_ids:
        for m in frappe.db.sql(
            "SELECT name, full_name FROM `tabIM Master` WHERE name IN %(ids)s",
            {"ids": tuple(im_ids)}, as_dict=True,
        ):
            im_labels[m["name"]] = m["full_name"] or m["name"]
    for r in rows:
        r["team_name"] = team_labels.get(r.get("team"), r.get("team"))
        r["from_im_name"] = im_labels.get(r.get("from_im"), r.get("from_im"))
        r["to_im_name"] = im_labels.get(r.get("to_im"), r.get("to_im"))
    return rows


# PO Transfer Request — IM requests batch transfer of Intake-tab POIDs to
# another IM, one single PM approval covers every POID in the batch.
# ---------------------------------------------------------------------------
# Lifecycle:
#   None → (IM requests, N POIDs) → Pending PM Approval
#   Pending PM Approval → (PM approve) → Approved (atomic flip: every line's
#                                          PO Dispatch.im → to_im)
#   Pending PM Approval → (PM reject)  → Rejected by PM (no changes)
#   Pending PM Approval → (requester cancel) → Cancelled (no changes)
#
# Scoped to Intake-tab rows only (no target_month yet — no Rollout Plan /
# Daily Execution exists for these, so there is nothing to cascade).
# ---------------------------------------------------------------------------

_PO_TRANSFER_BLOCKED_STATUSES = frozenset({
    "Backend Assigned", "Closed", "Cancelled", "Cancelled (in System)",
    "Completed", "Planned",
})


def _po_transfer_candidate_snapshot(name):
    return frappe.db.get_value(
        "PO Dispatch", name,
        ["name", "poid", "po_no", "site_code", "project_code", "im",
         "item_code", "item_description",
         "line_amount", "dispatch_status", "target_month",
         "is_dummy_po", "is_internal_work"],
        as_dict=True,
    ) or {}


def _assert_po_transfer_eligible(pd, im_identifiers=None, expected_from_im=None):
    """Shared eligibility check, used both at request-creation time (against
    the caller's own IM identifiers) and at PM-approve time (re-validated
    against the IM snapshotted when the request was made)."""
    label = pd.get("poid") or pd.get("name") or "?"
    if not pd or not pd.get("name"):
        frappe.throw(f"{label}: PO Dispatch not found")
    if im_identifiers is not None and (pd.get("im") or "") not in im_identifiers:
        frappe.throw(f"{label}: not assigned to you")
    if expected_from_im is not None and pd.get("im") != expected_from_im:
        frappe.throw(
            f"{label}: ownership changed since the request was made "
            f"(now: {pd.get('im') or '—'}). Reject and ask the IM to re-request."
        )
    if (pd.get("dispatch_status") or "") in _PO_TRANSFER_BLOCKED_STATUSES:
        frappe.throw(f"{label}: status '{pd.get('dispatch_status')}' cannot be transferred")
    if (pd.get("target_month") or "").strip():
        frappe.throw(f"{label}: already has a target month — outside Intake scope")
    if cint(pd.get("is_dummy_po")) and not (pd.get("poid") or "").strip():
        frappe.throw(f"{label}: unmapped dummy PO — map it to a real PO line before transferring")
    if cint(pd.get("is_internal_work")):
        frappe.throw(f"{label}: internal work cannot be transferred")
    # Duplicate-pending check only applies at request-creation time
    # (im_identifiers set). At PM-approve time this would otherwise find the
    # very request being decided (still "Pending PM Approval" until the
    # write phase below) and falsely reject every approval.
    if im_identifiers is not None:
        existing = frappe.db.sql(
            "SELECT h.name FROM `tabPO Transfer Request Line` l "
            "INNER JOIN `tabPO Transfer Request` h ON h.name = l.parent "
            "WHERE l.po_dispatch = %s AND h.request_status = 'Pending PM Approval' "
            "LIMIT 1",
            (pd.get("name"),),
        )
        if existing:
            frappe.throw(f"{label}: already has a pending transfer request ({existing[0][0]})")


def _po_transfer_serialize(name):
    d = frappe.db.get_value(
        "PO Transfer Request", name,
        ["name", "from_im", "to_im", "requested_by", "request_status",
         "poid_count", "total_amount", "reason", "pm_remark",
         "approved_by", "approved_at", "creation", "modified"],
        as_dict=True,
    )
    if not d:
        return None
    for key in ("from_im", "to_im"):
        v = d.get(key)
        if v:
            d[f"{key}_name"] = frappe.db.get_value("IM Master", v, "full_name") or v
    d["lines"] = frappe.db.get_all(
        "PO Transfer Request Line",
        filters={"parent": name},
        fields=["po_dispatch", "poid", "po_no", "site_code", "project_code",
                "item_code", "item_description", "line_amount", "line_status"],
        order_by="idx asc",
    )
    return d


@frappe.whitelist()
def request_po_transfer(po_dispatches, to_im, reason=None):
    """IM requests transferring one or more of their own Intake-tab POIDs to
    a different IM. Creates one PO Transfer Request covering every POID —
    all-or-nothing validation, nothing is created if any line is ineligible."""
    _im_resolved, im_identifiers = _require_inet_im_session()
    from_im = _resolve_caller_im_or_throw()

    if isinstance(po_dispatches, str):
        try:
            po_dispatches = frappe.parse_json(po_dispatches)
        except Exception:
            po_dispatches = [po_dispatches]
    names = []
    seen = set()
    for n in (po_dispatches or []):
        n = (n or "").strip()
        if n and n not in seen:
            seen.add(n)
            names.append(n)
    if not names:
        frappe.throw("Select at least one POID to transfer")

    to_im = (to_im or "").strip()
    if not to_im:
        frappe.throw("Target IM is required")
    if not frappe.db.exists("IM Master", to_im):
        frappe.throw("Target IM not found")
    if to_im == from_im:
        frappe.throw("You already own these POIDs — pick a different target IM.")

    snapshots = []
    for n in names:
        pd = _po_transfer_candidate_snapshot(n)
        _assert_po_transfer_eligible(pd, im_identifiers=im_identifiers)
        snapshots.append(pd)

    doc = frappe.new_doc("PO Transfer Request")
    doc.from_im = from_im
    doc.to_im = to_im
    doc.requested_by = frappe.session.user
    doc.request_status = "Pending PM Approval"
    if reason:
        doc.reason = str(reason)[:2000]
    doc.poid_count = len(snapshots)
    doc.total_amount = sum(flt(s.get("line_amount")) for s in snapshots)
    for s in snapshots:
        doc.append("poids", {
            "po_dispatch": s.get("name"),
            "poid": s.get("poid") or s.get("name"),
            "po_no": s.get("po_no"),
            "site_code": s.get("site_code"),
            "project_code": s.get("project_code"),
            "item_code": s.get("item_code"),
            "item_description": s.get("item_description"),
            "line_amount": s.get("line_amount"),
            "line_status": "Pending",
        })
    doc.insert(ignore_permissions=True)
    frappe.db.commit()
    try:
        from inet_app.api.notifications import notify_pm_po_transfer_requested
        notify_pm_po_transfer_requested(doc.name)
    except Exception:
        pass
    return _po_transfer_serialize(doc.name)


@frappe.whitelist()
def pm_decide_po_transfer(request, action, remark=None):
    """PM approves or rejects a batch POID transfer. On approve: every
    line's PO Dispatch.im is flipped to to_im atomically — validated in a
    read-only pass first so a single ineligible line aborts the whole
    approval before any write happens."""
    request = (request or "").strip()
    action = (action or "").strip().lower()
    if action not in ("approve", "reject"):
        frappe.throw("action must be 'approve' or 'reject'")
    req = frappe.get_doc("PO Transfer Request", request)
    if req.request_status != "Pending PM Approval":
        frappe.throw(f"Request is not awaiting PM approval (current status: {req.request_status}).")
    _assert_request_caller_role(req, "pm")

    if action == "reject":
        frappe.db.set_value(
            "PO Transfer Request", request,
            {
                "request_status": "Rejected by PM",
                "approved_by": frappe.session.user,
                "approved_at": now_datetime(),
                "pm_remark": str(remark or "")[:2000] or None,
            },
            update_modified=True,
        )
        frappe.db.commit()
        try:
            from inet_app.api.notifications import notify_ims_po_transfer_pm_decided
            notify_ims_po_transfer_pm_decided(request, "reject")
        except Exception:
            pass
        return _po_transfer_serialize(request)

    # Approve — read-only validation pass first (no writes), so a single
    # ineligible line throws before anything is written; only if every line
    # passes do we proceed to the writes below.
    lines = frappe.db.get_all("PO Transfer Request Line", filters={"parent": request}, fields=["po_dispatch"])
    if not lines:
        frappe.throw("This request has no POID lines.")
    for l in lines:
        pd = _po_transfer_candidate_snapshot(l.po_dispatch)
        _assert_po_transfer_eligible(pd, expected_from_im=req.from_im)

    for l in lines:
        frappe.db.set_value("PO Dispatch", l.po_dispatch, "im", req.to_im, update_modified=True)
    frappe.db.sql(
        "UPDATE `tabPO Transfer Request Line` SET line_status = 'Transferred' WHERE parent = %s",
        (request,),
    )
    frappe.db.set_value(
        "PO Transfer Request", request,
        {
            "request_status": "Approved",
            "approved_by": frappe.session.user,
            "approved_at": now_datetime(),
            "pm_remark": str(remark or "")[:2000] or None,
        },
        update_modified=True,
    )
    frappe.db.commit()
    try:
        from inet_app.api.notifications import notify_ims_po_transfer_pm_decided
        notify_ims_po_transfer_pm_decided(request, "approve")
    except Exception:
        pass
    return _po_transfer_serialize(request)


@frappe.whitelist()
def cancel_po_transfer(request):
    """Requester withdraws a request that's still awaiting PM approval."""
    request = (request or "").strip()
    req = frappe.get_doc("PO Transfer Request", request)
    if req.request_status != "Pending PM Approval":
        frappe.throw("Cannot cancel — request has already been decided.")
    _assert_request_caller_role(req, "requester")
    frappe.db.set_value("PO Transfer Request", request, {"request_status": "Cancelled"}, update_modified=True)
    frappe.db.commit()
    return _po_transfer_serialize(request)


@frappe.whitelist()
def list_po_transfer_requests(scope="all", status=None, limit=200):
    """Return PO Transfer Requests visible to the caller.

    `scope` ∈ {"all", "outgoing", "incoming", "pending_pm"}.
      - "outgoing"   — requests where caller IM is `from_im` (their own requests)
      - "incoming"   — requests where caller IM is `to_im` (read-only visibility;
                       the receiving IM has no action to take before the PM decides)
      - "pending_pm" — PM/Admin approval queue (status = Pending PM Approval)
      - "all"        — all rows the caller has read access to
    """
    scope = (scope or "all").strip().lower()
    wheres = []
    params = []
    if scope in ("outgoing", "incoming"):
        try:
            caller_im = _resolve_caller_im_or_throw()
        except Exception:
            return []
        col = "from_im" if scope == "outgoing" else "to_im"
        wheres.append(f"{col} = %s")
        params.append(caller_im)
    elif scope == "pending_pm":
        wheres.append("request_status = %s")
        params.append("Pending PM Approval")
    if status:
        wheres.append("request_status = %s")
        params.append(status)
    where_sql = ("WHERE " + " AND ".join(wheres)) if wheres else ""
    try:
        limit = max(1, min(int(limit or 200), 500))
    except Exception:
        limit = 200
    rows = frappe.db.sql(
        f"""
        SELECT name, from_im, to_im, requested_by, request_status,
               poid_count, total_amount, reason, pm_remark,
               approved_by, approved_at, creation, modified
        FROM `tabPO Transfer Request`
        {where_sql}
        ORDER BY modified DESC
        LIMIT {limit}
        """,
        tuple(params), as_dict=True,
    )
    if not rows:
        return []
    im_ids = list({i for r in rows for i in (r.get("from_im"), r.get("to_im")) if i})
    im_labels = {}
    if im_ids:
        for m in frappe.db.sql(
            "SELECT name, full_name FROM `tabIM Master` WHERE name IN %(ids)s",
            {"ids": tuple(im_ids)}, as_dict=True,
        ):
            im_labels[m["name"]] = m["full_name"] or m["name"]
    names = [r["name"] for r in rows]
    all_lines = frappe.db.sql(
        "SELECT parent, poid, site_code, project_code, item_code, item_description, line_amount "
        "FROM `tabPO Transfer Request Line` WHERE parent IN %(names)s ORDER BY parent, idx ASC",
        {"names": tuple(names)}, as_dict=True,
    )
    lines_by_parent = {}
    for l in all_lines:
        lines_by_parent.setdefault(l["parent"], []).append(l)
    for r in rows:
        r["from_im_name"] = im_labels.get(r.get("from_im"), r.get("from_im"))
        r["to_im_name"] = im_labels.get(r.get("to_im"), r.get("to_im"))
        line_rows = lines_by_parent.get(r["name"], [])
        r["lines"] = line_rows
        poids = [l["poid"] for l in line_rows]
        shown = poids[:5]
        more = len(poids) - len(shown)
        r["poid_list"] = ", ".join(shown) + (f" +{more} more" if more > 0 else "")
    return rows


@frappe.whitelist()
def list_my_pending_po_transfer_poids():
    """Flat list of PO Dispatch names the caller IM currently has tied up
    in a pending transfer request — used to block re-selecting them into a
    second request on the Intake tab."""
    try:
        caller_im = _resolve_caller_im_or_throw()
    except Exception:
        return []
    rows = frappe.db.sql(
        "SELECT l.po_dispatch FROM `tabPO Transfer Request Line` l "
        "INNER JOIN `tabPO Transfer Request` h ON h.name = l.parent "
        "WHERE h.from_im = %s AND h.request_status = 'Pending PM Approval'",
        (caller_im,),
    )
    return [r[0] for r in rows]


@frappe.whitelist()
def list_im_masters_for_transfer_picker(search=None, limit=200):
    """IM Master picker for the Intake-tab Transfer modal — IM-facing
    (unlike list_im_masters_for_picker, which is PM-only), excludes the
    caller's own IM since transferring to yourself is a no-op."""
    role = _user_role_class()
    if role not in ("pm", "im"):
        frappe.throw("Not permitted", frappe.PermissionError)
    exclude_im = None
    try:
        exclude_im = _resolve_caller_im_or_throw()
    except Exception:
        exclude_im = None
    where = ["IFNULL(status,'Active') = 'Active'"]
    params = []
    if exclude_im:
        where.append("name != %s")
        params.append(exclude_im)
    s = (search or "").strip()
    if s:
        where.append("(name LIKE %s OR IFNULL(full_name,'') LIKE %s)")
        like = f"%{s}%"
        params.extend([like, like])
    rows = frappe.db.sql(
        f"""
        SELECT name, IFNULL(full_name, name) AS full_name
        FROM `tabIM Master`
        WHERE {' AND '.join(where)}
        ORDER BY full_name ASC
        LIMIT %s
        """,
        tuple(params) + (int(limit),),
        as_dict=True,
    )
    return rows


# Rollout Plan Cancel Request — IM requests PM approval to cancel a plan
# ---------------------------------------------------------------------------
# Lifecycle:
#   None → (IM requests) → Pending PM Approval
#   Pending PM Approval → (PM approve) → Approved (plan_status=Cancelled, dispatch_status=Pending)
#   Pending PM Approval → (PM reject)  → Rejected (no changes to plan/dispatch)
# ---------------------------------------------------------------------------

_CANCELLABLE_PLAN_STATUSES = frozenset({"Planned", "In Execution", "Planning with Issue"})


def _serialize_plan_for_cancel(plan_name):
    """Return a JSON-friendly snapshot of a Rollout Plan for the cancel flow."""
    d = frappe.db.get_value(
        "Rollout Plan", plan_name,
        [
            "name", "po_dispatch", "plan_status", "plan_date", "team",
            "visit_type", "visit_number", "im", "target_amount",
            "cancel_request_status", "cancel_reason",
            "cancel_requested_by", "cancel_requested_at",
            "cancel_responded_by", "cancel_responded_at", "cancel_pm_remark",
            "modified",
        ],
        as_dict=True,
    )
    if not d:
        return None
    # Enrich with display names
    if d.get("team"):
        d["team_name"] = frappe.db.get_value("INET Team", d["team"], "team_name") or d["team"]
    if d.get("im"):
        d["im_name"] = frappe.db.get_value("IM Master", d["im"], "full_name") or d["im"]
    return d


@frappe.whitelist()
def request_cancel_plan(rollout_plan, reason=None):
    """IM requests cancellation of a Rollout Plan. Requires PM approval.

    Allowed only when plan_status is one of: Planned, In Execution, Planning with Issue.
    Blocks if a cancel request is already pending.
    """
    caller = _resolve_caller_im_or_throw()
    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Rollout Plan not found.")
    plan = frappe.db.get_value(
        "Rollout Plan", rollout_plan,
        ["name", "plan_status", "cancel_request_status", "im", "po_dispatch"],
        as_dict=True,
    )
    if not plan:
        frappe.throw("Rollout Plan not found.")

    if plan.plan_status not in _CANCELLABLE_PLAN_STATUSES:
        frappe.throw(
            f"Cannot cancel a plan in '{plan.plan_status}' status. "
            f"Only {', '.join(sorted(_CANCELLABLE_PLAN_STATUSES))} plans can be cancelled."
        )

    if plan.cancel_request_status and plan.cancel_request_status != "None" and plan.cancel_request_status != "Rejected":
        frappe.throw(f"A cancel request is already {plan.cancel_request_status} for this plan.")

    # Block if any Daily Execution is actively in progress
    active_de = frappe.db.sql(
        "SELECT COUNT(*) AS cnt FROM `tabDaily Execution` WHERE rollout_plan = %s AND execution_status = 'In Progress'",
        rollout_plan,
    )[0][0] or 0

    if active_de > 0:
        frappe.throw(
            f"Cannot cancel: {active_de} Daily Execution row(s) are still 'In Progress'. "
            "Complete or individually cancel them first."
        )

    now = now_datetime()
    frappe.db.set_value("Rollout Plan", rollout_plan, {
        "cancel_request_status": "Pending PM Approval",
        "cancel_reason": (reason or "").strip()[:8000] if reason else None,
        "cancel_requested_by": frappe.session.user,
        "cancel_requested_at": now,
        "cancel_responded_by": None,
        "cancel_responded_at": None,
        "cancel_pm_remark": None,
    }, update_modified=True)
    try:
        from inet_app.api.notifications import notify_pm_cancel_plan_requested
        notify_pm_cancel_plan_requested(rollout_plan)
    except Exception:
        pass
    return _serialize_plan_for_cancel(rollout_plan)


def _material_cleanup_on_plan_cancel(po_dispatch_name, team):
    """Cancelling a plan says nothing about the material already requested
    for its DUID at the team's warehouse — left alone, that material either
    sits there unreturned forever, or a Pending request for a plan that no
    longer exists gets approved and transferred later anyway.

    Rule (per product decision): a Material Request that has NO Stock Entry
    linked yet (nothing staged, nothing moved) is safe to auto-reject — no
    stock has moved, so there's nothing to reverse. One that already has a
    transfer — staged (draft, awaiting confirmation) or fully submitted —
    is never auto-touched; it's surfaced as a warning for a human to handle
    via the normal Return flow, since a team may still legitimately want
    that stock for another job on the same DUID.

    Returns {auto_cancelled: [...], needs_attention: [...], unconsumed_material: [...]}.
    """
    result = {"auto_cancelled": [], "needs_attention": [], "unconsumed_material": []}
    if not po_dispatch_name or not team:
        return result

    duid = frappe.db.get_value("PO Dispatch", po_dispatch_name, "site_code")
    team_wh = frappe.db.get_value("INET Team", team, "warehouse")
    if not duid or not team_wh:
        return result

    mrs = frappe.db.get_all(
        "Material Request",
        filters={
            "duid": duid, "set_warehouse": team_wh, "material_request_type": "Material Transfer",
            "docstatus": 1, "is_return_request": ["!=", 1], "status": ["!=", "Cancelled"],
        },
        fields=["name", "pending_transfer_se"],
    )
    for mr in mrs:
        has_transfer_se = bool(mr.pending_transfer_se) or frappe.db.exists(
            "Stock Entry", {"material_request": mr.name, "stock_entry_type": "Material Transfer"}
        )
        if has_transfer_se:
            result["needs_attention"].append(mr.name)
            continue
        # ERPNext's own permission check on reject_material_request requires
        # System Manager / Stock Manager — a PM approving this may only hold
        # "INET Admin", which _is_pm_role() already accepted as sufficient
        # authorization for *this* action. Elevate briefly rather than widen
        # that role's actual DocType permissions.
        _caller = frappe.session.user
        frappe.set_user("Administrator")
        try:
            from inet_app.api.material_management import reject_material_request
            reject_material_request(mr.name, reason="Rollout Plan cancelled")
            result["auto_cancelled"].append(mr.name)
        except Exception:
            frappe.log_error(frappe.get_traceback(), "Auto-cancel material request on plan cancel failed")
            result["needs_attention"].append(mr.name)
        finally:
            frappe.set_user(_caller)

    unconsumed = frappe.db.sql(
        """
        SELECT sed.item_code, IFNULL(MAX(i.item_name), sed.item_code) AS item_name,
               IFNULL(MAX(sed.uom), '') AS uom,
               SUM(CASE WHEN se.stock_entry_type = 'Material Transfer' AND sed.t_warehouse = %(wh)s
                          AND sed.to_duid = %(duid)s THEN sed.qty ELSE 0 END)
             - SUM(CASE WHEN se.stock_entry_type = 'Material Issue' AND sed.s_warehouse = %(wh)s
                          AND sed.duid = %(duid)s THEN sed.qty ELSE 0 END) AS net_qty
        FROM `tabStock Entry Detail` sed
        JOIN `tabStock Entry` se ON se.name = sed.parent
        LEFT JOIN `tabItem` i ON i.name = sed.item_code
        WHERE se.docstatus = 1
          AND (
            (se.stock_entry_type = 'Material Transfer' AND sed.t_warehouse = %(wh)s AND sed.to_duid = %(duid)s)
            OR (se.stock_entry_type = 'Material Issue' AND sed.s_warehouse = %(wh)s AND sed.duid = %(duid)s)
          )
        GROUP BY sed.item_code
        HAVING net_qty > 0.0001
        """,
        {"wh": team_wh, "duid": duid}, as_dict=True,
    )
    result["unconsumed_material"] = [
        {"item_code": r.item_code, "item_name": r.item_name, "uom": r.uom, "qty": flt(r.net_qty), "warehouse": team_wh}
        for r in unconsumed
    ]
    return result


@frappe.whitelist()
def pm_decide_cancel_plan(rollout_plan, action, remark=None):
    """PM approves or rejects a cancel plan request.

    On approve: Rollout Plan → Cancelled, linked PO Dispatch → Pending, and
    any Material Request for that DUID at the team's warehouse is either
    auto-rejected (nothing moved yet) or flagged for manual attention (stock
    already staged/transferred) — see _material_cleanup_on_plan_cancel.
    On reject: cancel_request_status → Rejected, plan stays as-is.
    """
    if not _is_pm_role():
        frappe.throw("Only a PM / Admin can decide cancel plan requests.", frappe.PermissionError)

    if action not in ("approve", "reject"):
        frappe.throw("action must be 'approve' or 'reject'")

    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Rollout Plan not found.")

    plan = frappe.db.get_value(
        "Rollout Plan", rollout_plan,
        ["name", "plan_status", "cancel_request_status", "po_dispatch", "team"],
        as_dict=True,
    )
    if not plan:
        frappe.throw("Rollout Plan not found.")

    if plan.cancel_request_status != "Pending PM Approval":
        frappe.throw(
            f"Cancel request is '{plan.cancel_request_status}', not 'Pending PM Approval'."
        )

    now = now_datetime()

    if action == "reject":
        frappe.db.set_value("Rollout Plan", rollout_plan, {
            "cancel_request_status": "Rejected",
            "cancel_responded_by": frappe.session.user,
            "cancel_responded_at": now,
            "cancel_pm_remark": (remark or "").strip()[:8000] if remark else None,
        }, update_modified=True)
        frappe.db.commit()
        try:
            from inet_app.api.notifications import notify_im_cancel_plan_decided
            notify_im_cancel_plan_decided(rollout_plan, "reject")
        except Exception:
            pass
        return _serialize_plan_for_cancel(rollout_plan)

    # Approve — atomic: cancel plan + revert PO Dispatch
    po_dispatch_name = plan.po_dispatch
    frappe.db.set_value("Rollout Plan", rollout_plan, {
        "plan_status": "Cancelled",
        "cancel_request_status": "Approved",
        "cancel_responded_by": frappe.session.user,
        "cancel_responded_at": now,
        "cancel_pm_remark": (remark or "").strip()[:8000] if remark else None,
    }, update_modified=True)

    if po_dispatch_name and frappe.db.exists("PO Dispatch", po_dispatch_name):
        cur_status = frappe.db.get_value("PO Dispatch", po_dispatch_name, "dispatch_status")
        if cur_status == "Planned":
            frappe.db.set_value("PO Dispatch", po_dispatch_name, "dispatch_status", "Dispatched")

    frappe.db.commit()

    material_cleanup = _material_cleanup_on_plan_cancel(po_dispatch_name, plan.get("team"))

    try:
        from inet_app.api.notifications import notify_im_cancel_plan_decided
        notify_im_cancel_plan_decided(rollout_plan, "approve", material_cleanup=material_cleanup)
    except Exception:
        pass
    out = _serialize_plan_for_cancel(rollout_plan)
    out.update(material_cleanup)
    return out


@frappe.whitelist()
def list_pending_cancel_requests(status=None):
    """Return Rollout Plans with cancel requests.

    status=None → all non-None cancel requests (for PM history)
    status="Pending PM Approval" → only pending (for PM badge / pending tab)
    """
    if not _is_pm_role():
        frappe.throw("Only a PM / Admin can view cancel plan requests.", frappe.PermissionError)

    if status:
        filters = {"cancel_request_status": status}
    else:
        filters = {"cancel_request_status": ("!=", "None")}

    rows = frappe.db.get_all(
        "Rollout Plan",
        filters=filters,
        fields=[
            "name", "po_dispatch", "plan_status", "plan_date", "team",
            "visit_type", "visit_number", "im", "target_amount",
            "cancel_request_status", "cancel_reason",
            "cancel_requested_by", "cancel_requested_at",
            "cancel_responded_by", "cancel_responded_at", "cancel_pm_remark",
            "modified",
        ],
        order_by="modified desc",
        limit=200,
    )

    # Enrich with display names and PO Dispatch poid
    po_dispatch_ids = list({r.get("po_dispatch") for r in rows if r.get("po_dispatch")})
    team_ids = list({r.get("team") for r in rows if r.get("team")})
    im_ids = list({r.get("im") for r in rows if r.get("im")})
    poid_map = {}
    team_labels = {}
    im_labels = {}
    if po_dispatch_ids:
        for pd in frappe.db.sql(
            "SELECT name, COALESCE(NULLIF(poid, ''), name) AS poid FROM `tabPO Dispatch` WHERE name IN %(ids)s",
            {"ids": tuple(po_dispatch_ids)}, as_dict=True,
        ):
            poid_map[pd["name"]] = pd["poid"]
    if team_ids:
        for t in frappe.db.sql(
            "SELECT name, team_name FROM `tabINET Team` WHERE name IN %(ids)s",
            {"ids": tuple(team_ids)}, as_dict=True,
        ):
            team_labels[t["name"]] = t["team_name"] or t["name"]
    if im_ids:
        for m in frappe.db.sql(
            "SELECT name, full_name FROM `tabIM Master` WHERE name IN %(ids)s",
            {"ids": tuple(im_ids)}, as_dict=True,
        ):
            im_labels[m["name"]] = m["full_name"] or m["name"]
    for r in rows:
        r["team_name"] = team_labels.get(r.get("team"), r.get("team"))
        r["im_name"] = im_labels.get(r.get("im"), r.get("im"))
        r["poid"] = poid_map.get(r.get("po_dispatch"), r.get("po_dispatch"))

    return rows


