# Admin Teams view
# ---------------------------------------------------------------------------

_ADMIN_TEAM_EDITABLE_FIELDS = [
    "team_name", "team_type", "team_category", "im", "status",
    "subcontractor", "field_user", "warehouse", "department",
    "isdp_account", "daily_cost", "daily_cost_applies", "note",
    "start_date", "end_date",
]


@frappe.whitelist()
def list_admin_teams(status=None, team_type=None, team_category=None, im=None, search=None, limit=500, for_date=None, column_filters=None, _options=None, _summary=None):
    """List all INET Teams with active project/domain for the PM admin Teams page.

    for_date: ISO date string (YYYY-MM-DD).  Defaults to today when omitted.
    """
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)

    import re as _re
    if for_date and not _re.match(r"^\d{4}-\d{2}-\d{2}$", str(for_date)):
        frappe.throw("Invalid for_date format")
    date_val = str(for_date) if for_date else None  # None → CURDATE() in SQL

    lim = min(int(limit or 500), 1000)
    wheres = []
    params = []

    if status:
        wheres.append("it.status = %s")
        params.append(status)
    if team_type:
        wheres.append("it.team_type = %s")
        params.append(team_type)
    if team_category:
        wheres.append("it.team_category = %s")
        params.append(team_category)
    if im:
        wheres.append("it.im = %s")
        params.append(im)
    if search:
        pat = f"%{(search or '').strip()}%"
        wheres.append("(it.team_id LIKE %s OR it.team_name LIKE %s OR IFNULL(im_m.full_name,'') LIKE %s)")
        params.extend([pat, pat, pat])

    # Per-column "Manage Table" filters — see list_im_rollout_plans for the
    # rationale. "Current Project"/"Current Domain"/"Active Plans"/"Today"
    # are computed via date-scoped correlated subqueries in the SELECT below;
    # duplicating those into the WHERE clause too would couple this filter's
    # param ordering to `for_date` in a fragile way, so those stay
    # client-side only for now (same graceful-degradation approach used for
    # genuinely Python-only columns elsewhere).
    # Escaped literal, not a bind param — see the note in col_filter_map_teams.
    _date_lit = frappe.db.escape(date_val) if date_val else "CURDATE()"
    col_filter_map_teams = {
        "team_id": "it.team_id",
        "name": "it.team_name",
        "category": "it.team_category",
        "type": "it.team_type",
        "status": "it.status",
        "members": "CAST((SELECT COUNT(*) FROM `tabINET Team Member` itm WHERE itm.parent = it.name) AS CHAR)",
        # The computed columns the page shows. They mirror the SELECT's own
        # subqueries so a filter matches exactly what's rendered. The date is
        # inlined as an escaped literal rather than a bind param: this
        # expression lands in both the SELECT and the WHERE of the options
        # query, so a placeholder here would break param ordering.
        "im": "IFNULL(NULLIF((SELECT full_name FROM `tabIM Master` WHERE name = it.im), ''), IFNULL(it.im,''))",
        "current_domain": (
            "IFNULL((SELECT GROUP_CONCAT(DISTINCT COALESCE(NULLIF(pd_t.project_domain,''), pcc_t.project_domain, '') "
            "ORDER BY COALESCE(NULLIF(pd_t.project_domain,''), pcc_t.project_domain, '') SEPARATOR ', ') "
            "FROM `tabRollout Plan` rp_t "
            "INNER JOIN `tabPO Dispatch` pd_t ON pd_t.name = rp_t.po_dispatch "
            "LEFT JOIN `tabProject Control Center` pcc_t ON pcc_t.name = pd_t.project_code "
            "WHERE (rp_t.team = it.name OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_t "
            "WHERE rpt_t.parent = rp_t.name AND rpt_t.team = it.name)) "
            "AND rp_t.plan_status IN ('Planned','In Execution','Extended','Completed') "
            f"AND {_date_lit} BETWEEN rp_t.plan_date AND IFNULL(rp_t.plan_end_date, rp_t.plan_date) "
            "AND COALESCE(NULLIF(pd_t.project_domain,''), pcc_t.project_domain, '') != ''), '')"
        ),
        "current_project": (
            "IFNULL((SELECT GROUP_CONCAT(DISTINCT IFNULL(pd_p.project_code,'') "
            "ORDER BY pd_p.project_code SEPARATOR ', ') "
            "FROM `tabRollout Plan` rp_p "
            "INNER JOIN `tabPO Dispatch` pd_p ON pd_p.name = rp_p.po_dispatch "
            "WHERE (rp_p.team = it.name OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_p "
            "WHERE rpt_p.parent = rp_p.name AND rpt_p.team = it.name)) "
            "AND rp_p.plan_status IN ('Planned','In Execution','Extended','Completed') "
            f"AND {_date_lit} BETWEEN rp_p.plan_date AND IFNULL(rp_p.plan_end_date, rp_p.plan_date) "
            "AND IFNULL(pd_p.project_code,'') != ''), '')"
        ),
        "active_plans": (
            "CAST((SELECT COUNT(*) FROM `tabRollout Plan` rp_a "
            "WHERE (rp_a.team = it.name OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_a "
            "WHERE rpt_a.parent = rp_a.name AND rpt_a.team = it.name)) "
            "AND rp_a.plan_status IN ('Planned','In Execution','Extended') "
            f"AND {_date_lit} BETWEEN rp_a.plan_date AND IFNULL(rp_a.plan_end_date, rp_a.plan_date)"
            ") AS CHAR)"
        ),
        "today": (
            "IFNULL(CASE WHEN IFNULL(it.team_category,'') = 'Backend Team' THEN '' "
            "WHEN EXISTS (SELECT 1 FROM `tabDaily Execution` de_t WHERE de_t.team = it.name "
            f"AND (de_t.execution_date = {_date_lit} OR de_t.last_progress_date = {_date_lit}) "
            "AND de_t.execution_status NOT IN ('Cancelled')) THEN 'In Execution' "
            "WHEN EXISTS (SELECT 1 FROM `tabRollout Plan` rp_s WHERE (rp_s.team = it.name "
            "OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_s WHERE rpt_s.parent = rp_s.name "
            "AND rpt_s.team = it.name)) "
            "AND rp_s.plan_status IN ('Planned','In Execution','Extended','Completed') "
            f"AND {_date_lit} BETWEEN rp_s.plan_date AND IFNULL(rp_s.plan_end_date, rp_s.plan_date)) "
            "THEN 'Planned' ELSE 'Idle' END, '')"
        ),
    }
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map_teams.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            pat2 = _sql_like_pattern(raw_val)
            if not pat2:
                continue
            if col_key == "im":
                wheres.append(
                    "(IFNULL(it.im,'') LIKE %s OR IFNULL(im_m.full_name,'') LIKE %s)"
                )
                params.extend([pat2, pat2])
                continue
            expr = col_filter_map_teams.get(col_key)
            if not expr:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat2)

    where_sql = ("WHERE " + " AND ".join(wheres)) if wheres else ""
    if _options:
        # Only the WHERE is needed here — the date params belong to the main
        # SELECT's computed subqueries, not to these clauses.
        _e = col_filter_map_teams.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabINET Team` it", " AND ".join(wheres) if wheres else "1=1", params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # A roster page: how many teams, split by who they belong to.
        return summary_from_query(
            "`tabINET Team` it", " AND ".join(wheres) if wheres else "1=1", params, [
                {"key": "teams", "label": "Teams", "agg": "count"},
                {"key": "active", "label": "Active", "agg": "count_if",
                 "cond": "IFNULL(it.status,'') = 'Active'", "tone": "good"},
                {"key": "inet", "label": "INET", "agg": "count_if", "group": "Type",
                 "cond": "IFNULL(it.team_type,'') = 'INET'", "hide_if_zero": True},
                {"key": "sub", "label": "Subcon", "agg": "count_if", "group": "Type",
                 "cond": "IFNULL(it.team_type,'') = 'SUB'", "hide_if_zero": True},
                {"key": "subcons", "label": "Subcons", "agg": "count_distinct",
                 "expr": "NULLIF(IFNULL(it.subcontractor,''), '')", "hide_if_zero": True},
            ])

    # Date placeholder: use the supplied date literal or fall back to CURDATE()
    date_expr = "%s" if date_val else "CURDATE()"
    if date_val:
        # Inject 6 copies of date_val (domains, projects, active_plan_count,
        # today_status ×3 — the Daily Execution check now tests both
        # execution_date and last_progress_date, since a multi-day plan's
        # single reused Daily Execution row never updates execution_date
        # past its first day; last_progress_date is what actually reflects
        # "touched today" from day 2 onward).
        params_date = [date_val] * 6
    else:
        params_date = []

    # Build full param list: date params interleaved with where params
    # Query uses date params first (in subqueries), then where params last
    full_params = params_date + params

    rows = frappe.db.sql(
        f"""
        SELECT
            it.name,
            it.team_id,
            it.team_name,
            it.team_type,
            it.team_category,
            it.im,
            IFNULL(im_m.full_name, it.im) AS im_name,
            it.status,
            it.daily_cost,
            it.daily_cost_applies,
            it.subcontractor,
            it.field_user,
            it.isdp_account,
            it.warehouse,
            it.department,
            it.note,
            (SELECT COUNT(*) FROM `tabINET Team Member` itm WHERE itm.parent = it.name) AS member_count,
            (
                SELECT GROUP_CONCAT(DISTINCT COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') ORDER BY COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') SEPARATOR ', ')
                FROM `tabRollout Plan` rp
                INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
                LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
                WHERE (rp.team = it.name OR EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt_dom
                        WHERE rpt_dom.parent = rp.name AND rpt_dom.team = it.name
                      ))
                  AND rp.plan_status IN ('Planned','In Execution','Extended','Completed')
                  AND {date_expr} BETWEEN rp.plan_date AND IFNULL(rp.plan_end_date, rp.plan_date)
                  AND COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') != ''
            ) AS current_domains,
            (
                SELECT GROUP_CONCAT(DISTINCT IFNULL(pd2.project_code,'') ORDER BY pd2.project_code SEPARATOR ', ')
                FROM `tabRollout Plan` rp2
                INNER JOIN `tabPO Dispatch` pd2 ON pd2.name = rp2.po_dispatch
                WHERE (rp2.team = it.name OR EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt_proj
                        WHERE rpt_proj.parent = rp2.name AND rpt_proj.team = it.name
                      ))
                  AND rp2.plan_status IN ('Planned','In Execution','Extended','Completed')
                  AND {date_expr} BETWEEN rp2.plan_date AND IFNULL(rp2.plan_end_date, rp2.plan_date)
                  AND IFNULL(pd2.project_code,'') != ''
            ) AS current_projects,
            (
                SELECT COUNT(*)
                FROM `tabRollout Plan` rpa
                WHERE (rpa.team = it.name OR EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt_act
                        WHERE rpt_act.parent = rpa.name AND rpt_act.team = it.name
                      ))
                  AND rpa.plan_status IN ('Planned','In Execution','Extended')
                  AND {date_expr} BETWEEN rpa.plan_date AND IFNULL(rpa.plan_end_date, rpa.plan_date)
            ) AS active_plan_count,
            (
                CASE
                    WHEN IFNULL(it.team_category, '') = 'Backend Team' THEN NULL
                    WHEN EXISTS (
                        SELECT 1 FROM `tabDaily Execution` de_s
                        WHERE de_s.team = it.name
                          AND (de_s.execution_date = {date_expr} OR de_s.last_progress_date = {date_expr})
                          AND de_s.execution_status NOT IN ('Cancelled')
                    ) THEN 'In Execution'
                    WHEN EXISTS (
                        SELECT 1 FROM `tabRollout Plan` rp_s
                        WHERE (rp_s.team = it.name OR EXISTS (
                                SELECT 1 FROM `tabRollout Plan Team` rpt_stat
                                WHERE rpt_stat.parent = rp_s.name AND rpt_stat.team = it.name
                              ))
                          AND rp_s.plan_status IN ('Planned', 'In Execution', 'Extended', 'Completed')
                          AND {date_expr} BETWEEN rp_s.plan_date AND IFNULL(rp_s.plan_end_date, rp_s.plan_date)
                    ) THEN 'Planned'
                    ELSE 'Idle'
                END
            ) AS today_status
        FROM `tabINET Team` it
        LEFT JOIN `tabIM Master` im_m ON im_m.name = it.im
        {where_sql}
        ORDER BY it.team_category, it.team_name
        LIMIT {lim}
        """,
        tuple(full_params) if full_params else (),
        as_dict=True,
    )
    return rows or []


@frappe.whitelist()
def list_im_teams(im=None, status=None, team_type=None, team_category=None, search=None, limit=500, for_date=None, column_filters=None, _options=None, _summary=None):
    """Same computed fields as list_admin_teams but accessible to IM role."""
    import re as _re
    if for_date and not _re.match(r"^\d{4}-\d{2}-\d{2}$", str(for_date)):
        frappe.throw("Invalid for_date format")
    date_val = str(for_date) if for_date else None

    lim = min(int(limit or 500), 1000)
    wheres = []
    params = []

    if im:
        wheres.append("it.im = %s")
        params.append(im)
    if status:
        wheres.append("it.status = %s")
        params.append(status)
    if team_type:
        wheres.append("it.team_type = %s")
        params.append(team_type)
    if team_category:
        wheres.append("it.team_category = %s")
        params.append(team_category)
    if search:
        pat = f"%{(search or '').strip()}%"
        wheres.append("(it.team_id LIKE %s OR it.team_name LIKE %s)")
        params.extend([pat, pat])

    # Per-column "Manage Table" filters — see list_admin_teams / list_im_rollout_plans
    # for the rationale. Date-scoped subquery columns (current project/domain,
    # active plans, today) stay client-side only — see the comment there.
    # Escaped literal, not a bind param — see the note in col_filter_map_teams.
    _date_lit = frappe.db.escape(date_val) if date_val else "CURDATE()"
    col_filter_map_teams = {
        "team_id": "it.team_id",
        "name": "it.team_name",
        "category": "it.team_category",
        "type": "it.team_type",
        "status": "it.status",
        "members": "CAST((SELECT COUNT(*) FROM `tabINET Team Member` itm WHERE itm.parent = it.name) AS CHAR)",
        # The computed columns the page shows. They mirror the SELECT's own
        # subqueries so a filter matches exactly what's rendered. The date is
        # inlined as an escaped literal rather than a bind param: this
        # expression lands in both the SELECT and the WHERE of the options
        # query, so a placeholder here would break param ordering.
        "im": "IFNULL(NULLIF((SELECT full_name FROM `tabIM Master` WHERE name = it.im), ''), IFNULL(it.im,''))",
        "current_domain": (
            "IFNULL((SELECT GROUP_CONCAT(DISTINCT COALESCE(NULLIF(pd_t.project_domain,''), pcc_t.project_domain, '') "
            "ORDER BY COALESCE(NULLIF(pd_t.project_domain,''), pcc_t.project_domain, '') SEPARATOR ', ') "
            "FROM `tabRollout Plan` rp_t "
            "INNER JOIN `tabPO Dispatch` pd_t ON pd_t.name = rp_t.po_dispatch "
            "LEFT JOIN `tabProject Control Center` pcc_t ON pcc_t.name = pd_t.project_code "
            "WHERE (rp_t.team = it.name OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_t "
            "WHERE rpt_t.parent = rp_t.name AND rpt_t.team = it.name)) "
            "AND rp_t.plan_status IN ('Planned','In Execution','Extended','Completed') "
            f"AND {_date_lit} BETWEEN rp_t.plan_date AND IFNULL(rp_t.plan_end_date, rp_t.plan_date) "
            "AND COALESCE(NULLIF(pd_t.project_domain,''), pcc_t.project_domain, '') != ''), '')"
        ),
        "current_project": (
            "IFNULL((SELECT GROUP_CONCAT(DISTINCT IFNULL(pd_p.project_code,'') "
            "ORDER BY pd_p.project_code SEPARATOR ', ') "
            "FROM `tabRollout Plan` rp_p "
            "INNER JOIN `tabPO Dispatch` pd_p ON pd_p.name = rp_p.po_dispatch "
            "WHERE (rp_p.team = it.name OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_p "
            "WHERE rpt_p.parent = rp_p.name AND rpt_p.team = it.name)) "
            "AND rp_p.plan_status IN ('Planned','In Execution','Extended','Completed') "
            f"AND {_date_lit} BETWEEN rp_p.plan_date AND IFNULL(rp_p.plan_end_date, rp_p.plan_date) "
            "AND IFNULL(pd_p.project_code,'') != ''), '')"
        ),
        "active_plans": (
            "CAST((SELECT COUNT(*) FROM `tabRollout Plan` rp_a "
            "WHERE (rp_a.team = it.name OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_a "
            "WHERE rpt_a.parent = rp_a.name AND rpt_a.team = it.name)) "
            "AND rp_a.plan_status IN ('Planned','In Execution','Extended') "
            f"AND {_date_lit} BETWEEN rp_a.plan_date AND IFNULL(rp_a.plan_end_date, rp_a.plan_date)"
            ") AS CHAR)"
        ),
        "today": (
            "IFNULL(CASE WHEN IFNULL(it.team_category,'') = 'Backend Team' THEN '' "
            "WHEN EXISTS (SELECT 1 FROM `tabDaily Execution` de_t WHERE de_t.team = it.name "
            f"AND (de_t.execution_date = {_date_lit} OR de_t.last_progress_date = {_date_lit}) "
            "AND de_t.execution_status NOT IN ('Cancelled')) THEN 'In Execution' "
            "WHEN EXISTS (SELECT 1 FROM `tabRollout Plan` rp_s WHERE (rp_s.team = it.name "
            "OR EXISTS (SELECT 1 FROM `tabRollout Plan Team` rpt_s WHERE rpt_s.parent = rp_s.name "
            "AND rpt_s.team = it.name)) "
            "AND rp_s.plan_status IN ('Planned','In Execution','Extended','Completed') "
            f"AND {_date_lit} BETWEEN rp_s.plan_date AND IFNULL(rp_s.plan_end_date, rp_s.plan_date)) "
            "THEN 'Planned' ELSE 'Idle' END, '')"
        ),
    }
    if isinstance(column_filters, str):
        try:
            column_filters = frappe.parse_json(column_filters)
        except Exception:
            column_filters = None
    if isinstance(column_filters, dict):
        for col_key, raw_val in column_filters.items():
            # Excel-style value filter — handled before _sql_like_pattern(),
            # which cannot take a dict. See excel_filter_clause().
            if isinstance(raw_val, dict):
                _c, _p = excel_filter_clause(col_filter_map_teams.get(col_key), raw_val)
                if _c:
                    wheres.append(_c)
                    params.extend(_p)
                continue
            pat2 = _sql_like_pattern(raw_val)
            if not pat2:
                continue
            if col_key == "im":
                wheres.append("(IFNULL(it.im,'') LIKE %s OR IFNULL(im_m.full_name,'') LIKE %s)")
                params.extend([pat2, pat2])
                continue
            expr = col_filter_map_teams.get(col_key)
            if not expr:
                continue
            wheres.append(f"{expr} LIKE %s")
            params.append(pat2)

    where_sql = ("WHERE " + " AND ".join(wheres)) if wheres else ""
    if _options:
        # Only the WHERE is needed here — the date params belong to the main
        # SELECT's computed subqueries, not to these clauses.
        _e = col_filter_map_teams.get(_options.get("col_key"))
        if not _e:
            return {"values": [], "has_blanks": False, "total": 0, "supported": False}
        return excel_options_from_query(
            "`tabINET Team` it", " AND ".join(wheres) if wheres else "1=1", params, _e,
            bucket=_options.get("bucket"), search=_options.get("search"),
            limit=_options.get("limit"), label_kind=_options.get("label_kind"),
        )
    if _summary:
        # The IM's roster: how many teams answer to them, and how many are live.
        return summary_from_query(
            "`tabINET Team` it", " AND ".join(wheres) if wheres else "1=1", params, [
                {"key": "teams", "label": "Teams", "agg": "count"},
                {"key": "active", "label": "Active", "agg": "count_if",
                 "cond": "IFNULL(it.status,'') = 'Active'", "tone": "good"},
                {"key": "inet", "label": "INET", "agg": "count_if", "group": "Type",
                 "cond": "IFNULL(it.team_type,'') = 'INET'", "hide_if_zero": True},
                {"key": "sub", "label": "Subcon", "agg": "count_if", "group": "Type",
                 "cond": "IFNULL(it.team_type,'') = 'SUB'", "hide_if_zero": True},
            ])
    date_expr = "%s" if date_val else "CURDATE()"
    # 6 copies — see list_admin_teams' comment on this same count.
    params_date = [date_val] * 6 if date_val else []
    full_params = params_date + params

    rows = frappe.db.sql(
        f"""
        SELECT
            it.name,
            it.team_id,
            it.team_name,
            it.team_type,
            it.team_category,
            it.im,
            IFNULL(im_m.full_name, it.im) AS im_name,
            it.status,
            it.subcontractor,
            it.field_user,
            it.isdp_account,
            it.warehouse,
            it.department,
            it.note,
            (SELECT COUNT(*) FROM `tabINET Team Member` itm WHERE itm.parent = it.name) AS member_count,
            (
                SELECT GROUP_CONCAT(DISTINCT COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') ORDER BY COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') SEPARATOR ', ')
                FROM `tabRollout Plan` rp
                INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
                LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
                WHERE (rp.team = it.name OR EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt_dom
                        WHERE rpt_dom.parent = rp.name AND rpt_dom.team = it.name
                      ))
                  AND rp.plan_status IN ('Planned','In Execution','Extended','Completed')
                  AND {date_expr} BETWEEN rp.plan_date AND IFNULL(rp.plan_end_date, rp.plan_date)
                  AND COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') != ''
            ) AS current_domains,
            (
                SELECT GROUP_CONCAT(DISTINCT IFNULL(pd2.project_code,'') ORDER BY pd2.project_code SEPARATOR ', ')
                FROM `tabRollout Plan` rp2
                INNER JOIN `tabPO Dispatch` pd2 ON pd2.name = rp2.po_dispatch
                WHERE (rp2.team = it.name OR EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt_proj
                        WHERE rpt_proj.parent = rp2.name AND rpt_proj.team = it.name
                      ))
                  AND rp2.plan_status IN ('Planned','In Execution','Extended','Completed')
                  AND {date_expr} BETWEEN rp2.plan_date AND IFNULL(rp2.plan_end_date, rp2.plan_date)
                  AND IFNULL(pd2.project_code,'') != ''
            ) AS current_projects,
            (
                SELECT COUNT(*)
                FROM `tabRollout Plan` rpa
                WHERE (rpa.team = it.name OR EXISTS (
                        SELECT 1 FROM `tabRollout Plan Team` rpt_act
                        WHERE rpt_act.parent = rpa.name AND rpt_act.team = it.name
                      ))
                  AND rpa.plan_status IN ('Planned','In Execution','Extended')
                  AND {date_expr} BETWEEN rpa.plan_date AND IFNULL(rpa.plan_end_date, rpa.plan_date)
            ) AS active_plan_count,
            (
                CASE
                    WHEN IFNULL(it.team_category, '') = 'Backend Team' THEN NULL
                    WHEN EXISTS (
                        SELECT 1 FROM `tabDaily Execution` de_s
                        WHERE de_s.team = it.name
                          AND (de_s.execution_date = {date_expr} OR de_s.last_progress_date = {date_expr})
                          AND de_s.execution_status NOT IN ('Cancelled')
                    ) THEN 'In Execution'
                    WHEN EXISTS (
                        SELECT 1 FROM `tabRollout Plan` rp_s
                        WHERE (rp_s.team = it.name OR EXISTS (
                                SELECT 1 FROM `tabRollout Plan Team` rpt_stat
                                WHERE rpt_stat.parent = rp_s.name AND rpt_stat.team = it.name
                              ))
                          AND rp_s.plan_status IN ('Planned', 'In Execution', 'Extended', 'Completed')
                          AND {date_expr} BETWEEN rp_s.plan_date AND IFNULL(rp_s.plan_end_date, rp_s.plan_date)
                    ) THEN 'Planned'
                    ELSE 'Idle'
                END
            ) AS today_status
        FROM `tabINET Team` it
        LEFT JOIN `tabIM Master` im_m ON im_m.name = it.im
        {where_sql}
        ORDER BY it.team_category, it.team_name
        LIMIT {lim}
        """,
        tuple(full_params) if full_params else (),
        as_dict=True,
    )
    return rows or []


@frappe.whitelist()
def admin_get_team_detail(name):
    """Full INET Team detail including members and active plans. Admin-only."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    if not name:
        frappe.throw("name is required")

    doc = frappe.get_doc("INET Team", name).as_dict()

    members = []
    for m in (doc.get("team_members") or []):
        emp_full = ""
        if m.get("employee"):
            emp_full = frappe.db.get_value("Employee", m.get("employee"), "employee_name") or ""
        members.append({
            "employee": m.get("employee"),
            "employee_name": emp_full,
            "designation": m.get("designation") or "",
            "is_team_lead": 1 if m.get("is_team_lead") else 0,
        })

    im_full_name = ""
    if doc.get("im"):
        im_full_name = frappe.db.get_value("IM Master", doc.get("im"), "full_name") or ""

    active_plans = frappe.db.sql(
        """
        SELECT
            rp.name AS plan_name,
            rp.plan_date,
            rp.plan_status,
            pd.project_code,
            COALESCE(NULLIF(pd.project_domain,''), pcc.project_domain, '') AS project_domain,
            IFNULL(pcc.project_name,'') AS project_name,
            COALESCE(NULLIF(pd.poid,''), pd.name) AS poid,
            pd.site_code
        FROM `tabRollout Plan` rp
        INNER JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabProject Control Center` pcc ON pcc.name = pd.project_code
        WHERE (rp.team = %s OR EXISTS (
                SELECT 1 FROM `tabRollout Plan Team` rpt
                WHERE rpt.parent = rp.name AND rpt.team = %s
              ))
          AND rp.plan_status IN ('Planned','In Execution','Extended')
        ORDER BY rp.plan_date DESC
        LIMIT 20
        """,
        (name, name),
        as_dict=True,
    )

    return {
        "name": doc.get("name"),
        "team_id": doc.get("team_id"),
        "team_name": doc.get("team_name"),
        "team_type": doc.get("team_type"),
        "team_category": doc.get("team_category"),
        "im": doc.get("im"),
        "im_name": im_full_name,
        "subcontractor": doc.get("subcontractor"),
        "isdp_account": doc.get("isdp_account"),
        "field_user": doc.get("field_user"),
        "warehouse": doc.get("warehouse"),
        "department": doc.get("department"),
        "status": doc.get("status"),
        "start_date": doc.get("start_date"),
        "end_date": doc.get("end_date"),
        "daily_cost": doc.get("daily_cost"),
        "daily_cost_applies": 1 if doc.get("daily_cost_applies") else 0,
        "note": doc.get("note"),
        "team_members": members,
        "active_plans": [dict(r) for r in (active_plans or [])],
    }


@frappe.whitelist()
def admin_update_team(name, payload=None):
    """Update any INET Team field (admin-only, no ownership restriction)."""
    if not _is_pm_role():
        frappe.throw("Not permitted", frappe.PermissionError)
    if not name:
        frappe.throw("name is required")
    if isinstance(payload, str):
        payload = frappe.parse_json(payload) if payload else {}
    payload = payload or {}

    if not frappe.db.exists("INET Team", name):
        frappe.throw(f"INET Team not found: {name}")

    members_raw = payload.get("team_members")
    members_changed = members_raw is not None
    clean = []

    updates = {}
    for fname in _ADMIN_TEAM_EDITABLE_FIELDS:
        if fname not in payload:
            continue
        val = payload.get(fname)
        if fname == "daily_cost":
            try:
                val = flt(val)
            except Exception:
                continue
        elif fname == "daily_cost_applies":
            val = 1 if val in (1, "1", True, "true", "yes", "on") else 0
        elif isinstance(val, str):
            val = val.strip()
        updates[fname] = val

    if updates:
        frappe.db.set_value("INET Team", name, updates, update_modified=True)

    if members_changed:
        seen_emp = set()
        team_leads = 0
        for m in (members_raw or []):
            emp = (m or {}).get("employee")
            if not emp:
                continue
            emp = str(emp).strip()
            if not emp or emp in seen_emp:
                continue
            seen_emp.add(emp)
            is_lead = 1 if (m.get("is_team_lead") in (1, "1", True, "true", "yes", "on")) else 0
            if is_lead:
                team_leads += 1
            desig = (m.get("designation") or "").strip() or None
            clean.append({"employee": emp, "designation": desig, "is_team_lead": is_lead})
        if team_leads > 1:
            frappe.throw("Only one team member can be marked as Team Lead.")
        doc = frappe.get_doc("INET Team", name)
        doc.set("team_members", [])
        for row in clean:
            doc.append("team_members", row)
        doc.save(ignore_permissions=True)

    frappe.db.commit()
    return {
        "name": name,
        "updated": len(updates),
        "fields": list(updates.keys()),
        "members_replaced": members_changed,
        "member_count": len(clean) if members_changed else None,
    }


@frappe.whitelist()
def mark_plan_not_attended(rollout_plan, reason=None):
    """
    TL marks a plan as Not Attended (team did not show up).
    Sets plan_status = 'Not Attended' and stores the reason directly on the
    Rollout Plan. No Daily Execution record is created or updated.
    """
    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Invalid Rollout Plan")

    cur_status = frappe.db.get_value("Rollout Plan", rollout_plan, "plan_status")
    if cur_status in ("Completed", "Cancelled"):
        frappe.throw(f"Cannot mark as Not Attended: plan is already {cur_status}.")

    updates = {"plan_status": "Not Attended"}
    if frappe.db.has_column("Rollout Plan", "not_attended_remark"):
        updates["not_attended_remark"] = str(reason or "")[:500]

    frappe.db.set_value("Rollout Plan", rollout_plan, updates, update_modified=True)
    frappe.db.commit()
    return {"ok": True, "plan_status": "Not Attended"}


@frappe.whitelist()
def extend_plan_end_date(rollout_plan, new_end_date, im_note=None):
    """
    IM extends the end date of a multi-day plan that couldn't be completed in time.
    Updates plan_end_date and logs the extension in the reschedule_log child table
    for full audit history. Only ever changes plan_status for one specific case —
    see the "Extended" handling below.
    """
    if not rollout_plan or not frappe.db.exists("Rollout Plan", rollout_plan):
        frappe.throw("Invalid Rollout Plan")
    if not new_end_date:
        frappe.throw("New end date is required")

    doc = frappe.get_doc("Rollout Plan", rollout_plan)
    if doc.plan_status in ("Completed", "Cancelled"):
        frappe.throw(f"Cannot extend: plan is already {doc.plan_status}.")

    old_end_date = doc.plan_end_date or doc.plan_date
    if getdate(new_end_date) <= getdate(old_end_date):
        frappe.throw(
            f"New end date ({new_end_date}) must be after the current end date "
            f"({old_end_date}) — pick a later date, or use Reschedule instead."
        )

    # Log extension in reschedule_log (same child table used for reschedules).
    tl_snap = frappe.db.get_value(
        "Daily Execution",
        {"rollout_plan": rollout_plan},
        "tl_status",
        order_by="modified desc",
    ) or ""

    doc.append("reschedule_log", {
        "original_date": old_end_date,
        "new_date": new_end_date,
        "reason": "End Date Extension",
        "tl_status_at_time": tl_snap,
        "im_note": (im_note or "")[:2000],
        "rescheduled_by": frappe.session.user,
        "rescheduled_at": frappe.utils.now(),
    })
    doc.reschedule_count = cint(doc.reschedule_count or 0) + 1
    doc.plan_end_date = new_end_date

    # Overdue / Not Attended: leave status untouched. Both already show on
    # Rollout Execution by default, and both are normally handled via
    # Reschedule rather than Extend anyway — no status change needed here,
    # extending one just pushes the deadline.
    #
    # In Execution: this is the one case that actually needs a status
    # change, and only conditionally. A multi-day plan being extended
    # because the TL genuinely needs one more day (already logged progress
    # TODAY) should stay "In Execution" untouched — Work Done still shows
    # it, nothing disrupted. But if the TL hasn't touched it TODAY at all
    # (last_progress_date is stale or missing — the plan's gone quiet
    # mid-stream and the IM is extending because of that), it moves to
    # "Extended": shows on Rollout Execution (needs the TL to re-engage)
    # and drops off Rollout Work Done immediately. The moment the TL logs
    # new activity, the execution-sync logic flips it back to "In
    # Execution" and it returns to Rollout Work Done.
    if doc.plan_status == "In Execution":
        today_str = frappe.utils.nowdate()
        progress_today = frappe.db.exists("Daily Execution", {
            "rollout_plan": rollout_plan,
            "last_progress_date": today_str,
        })
        if not progress_today:
            doc.plan_status = "Extended"

    doc.save(ignore_permissions=True)
    frappe.db.commit()
    return {"ok": True, "plan_end_date": new_end_date, "reschedule_count": doc.reschedule_count}


# ── Team Reports ──────────────────────────────────────────────────────────────

_SUPPLIER_NAME = "Innovation Network General Contracting Establishment"

_TEAM_REPORT_COLS = [
    {"fieldname": "sn",           "label": "S/N"},
    {"fieldname": "supplier_name","label": "Supplier Name"},
    {"fieldname": "date",         "label": "Date"},
    {"fieldname": "team_no",      "label": "Team No"},
    {"fieldname": "tl_name",      "label": "TL Name"},
    {"fieldname": "tl_id",        "label": "TL ID"},
    {"fieldname": "tl_iqama",     "label": "TL Iqama"},
    {"fieldname": "tl_mobile",    "label": "TL Mobile"},
    {"fieldname": "team_skills",  "label": "Team Skills"},
    {"fieldname": "team_status",  "label": "Team Status"},
    {"fieldname": "site_duid",    "label": "Site Name/DUID"},
    {"fieldname": "huawei_im",    "label": "Huawei IM Name"},
    {"fieldname": "project_name", "label": "Project Name"},
    {"fieldname": "domain",       "label": "Domain"},
]

_IDLE_SQL = """
    SELECT
        %s AS supplier_name,
        %s AS `date`,
        it.team_id AS team_no,
        e.employee_name AS tl_name,
        it.tl_id AS tl_id,
        e.employee_number AS tl_iqama,
        e.cell_number AS tl_mobile,
        it.team_skills AS team_skills,
        CASE it.status WHEN 'Inactive' THEN 'On Vacation' ELSE 'Available' END AS team_status,
        NULL AS site_duid,
        NULL AS huawei_im,
        NULL AS project_name,
        NULL AS domain
    FROM `tabINET Team` it
    LEFT JOIN `tabEmployee` e ON e.user_id = it.field_user
    WHERE it.team_category = 'Field Team'
    ORDER BY it.team_id
"""


def _idle_rows(fd, supplier, busy_teams, extra_col=None):
    rows = frappe.db.sql(_IDLE_SQL, (supplier, fd), as_dict=True)
    out = []
    for r in rows:
        if r["team_no"] in busy_teams:
            continue
        d = dict(r)
        if extra_col:
            d[extra_col] = None
        out.append(d)
    return out


@frappe.whitelist()
def get_team_report(report_type="planning", from_date=None, to_date=None):
    """Return {columns, data} for Planning / Utilization / Implementation team reports."""
    from frappe.utils import today as _today
    fd = from_date or _today()
    td = to_date or fd
    single_day = (fd == td)

    if report_type == "planning":
        cols = list(_TEAM_REPORT_COLS)
        rows = _team_planning_rows(fd, td, single_day)
    elif report_type == "utilization":
        cols = list(_TEAM_REPORT_COLS)
        rows = _team_utilization_rows(fd, td, single_day)
    else:
        cols = list(_TEAM_REPORT_COLS) + [{"fieldname": "activity_status", "label": "Activity Status"}]
        rows = _team_implementation_rows(fd, td, single_day)

    for i, r in enumerate(rows, 1):
        r["sn"] = i

    return {"columns": cols, "data": rows}



# Statuses where plan_end_date reflects real, IM-committed continuing work —
# a plan genuinely scheduled/executing/completed across multiple days should
# show the team busy on every one of those days in the report. Overdue / Not
# Attended / Planning with Issue / anything else are deliberately excluded:
# those mean the plan never got worked past its original plan_date (or has
# an unresolved problem), so they must only ever show on that one day —
# extending them would fabricate days of work that never happened. A plan
# only re-enters the active set once it's actually Rescheduled (which stamps
# a fresh plan_date and resets status to Planned).
_PLAN_REPORT_RANGE_STATUSES = ("Planned", "In Execution", "Extended", "Completed")


def _team_planning_rows(fd, td, single_day):
    from frappe.utils import getdate, add_days

    fd_d, td_d = getdate(fd), getdate(td)
    raw = frappe.db.sql(
        """
        SELECT
            rp.plan_date, rp.plan_end_date, rp.plan_status,
            it.name AS team_key, it.team_id, it.tl_id, it.team_skills, it.status AS team_active_status,
            e.employee_name AS tl_name,
            e.employee_number AS tl_iqama,
            e.cell_number AS tl_mobile,
            IFNULL(pd.site_code,'') AS site_code,
            IFNULL(imm.full_name,'') AS huawei_im,
            IFNULL(pd.project_code,'') AS project_code,
            IFNULL(pd.project_domain,'') AS project_domain
        FROM `tabRollout Plan` rp
        JOIN (
            SELECT rp2.name AS plan, rp2.team AS team FROM `tabRollout Plan` rp2
            UNION
            SELECT rpt.parent AS plan, rpt.team AS team FROM `tabRollout Plan Team` rpt
        ) rpteam ON rpteam.plan = rp.name
        INNER JOIN `tabINET Team` it ON it.name = rpteam.team AND it.team_category = 'Field Team'
        LEFT JOIN `tabEmployee` e ON e.user_id = it.field_user
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabIM Master` imm ON imm.name = pd.im
        WHERE IFNULL(rp.plan_status,'') NOT IN ('Cancelled')
          AND rp.plan_date <= %s
          AND IFNULL(rp.plan_end_date, rp.plan_date) >= %s
        """,
        (td, fd),
        as_dict=True,
    )

    # Expand each plan into one bucket per calendar day it actually covers
    # (clipped to the requested [fd, td] window), then aggregate same-team/
    # same-day plans together exactly like the old GROUP_CONCAT did.
    buckets = {}
    order = []
    for r in raw:
        plan_date = getdate(r["plan_date"])
        end_date = plan_date
        if r["plan_status"] in _PLAN_REPORT_RANGE_STATUSES and r.get("plan_end_date"):
            end_date = getdate(r["plan_end_date"])
            if end_date < plan_date:
                end_date = plan_date
        span_start = max(plan_date, fd_d)
        span_end = min(end_date, td_d)
        if span_start > span_end:
            continue
        d = span_start
        while d <= span_end:
            key = (d, r["team_key"])
            b = buckets.get(key)
            if not b:
                b = {
                    "date": d,
                    "team_no": r["team_id"],
                    "tl_name": r["tl_name"],
                    "tl_id": r["tl_id"],
                    "tl_iqama": r["tl_iqama"],
                    "tl_mobile": r["tl_mobile"],
                    "team_skills": r["team_skills"],
                    "team_status": "On Vacation" if r["team_active_status"] == "Inactive" else "Available",
                    "site_duid": set(), "huawei_im": set(), "project_name": set(), "domain": set(),
                }
                buckets[key] = b
                order.append(key)
            if r["site_code"]: b["site_duid"].add(r["site_code"])
            if r["huawei_im"]: b["huawei_im"].add(r["huawei_im"])
            if r["project_code"]: b["project_name"].add(r["project_code"])
            if r["project_domain"]: b["domain"].add(r["project_domain"])
            d = add_days(d, 1)

    rows = []
    for key in order:
        b = buckets[key]
        rows.append({
            "supplier_name": _SUPPLIER_NAME,
            "date": b["date"],
            "team_no": b["team_no"],
            "tl_name": b["tl_name"],
            "tl_id": b["tl_id"],
            "tl_iqama": b["tl_iqama"],
            "tl_mobile": b["tl_mobile"],
            "team_skills": b["team_skills"],
            "team_status": b["team_status"],
            "site_duid": ", ".join(sorted(b["site_duid"])),
            "huawei_im": ", ".join(sorted(b["huawei_im"])),
            "project_name": ", ".join(sorted(b["project_name"])),
            "domain": ", ".join(sorted(b["domain"])),
        })

    if single_day:
        busy = {r["team_no"] for r in rows}
        rows = rows + _idle_rows(fd, _SUPPLIER_NAME, busy)
        rows.sort(key=lambda r: r["team_no"] or "")
    else:
        rows.sort(key=lambda r: (r["team_no"] or "", str(r["date"])))
    return rows


# Daily Execution's execution_date is stamped once at creation and never
# moves; last_progress_date is the server-stamped day of its most recent
# real update_execution call. For a job the TL is still actively on days
# after it started, those are the only two days we have real evidence for —
# unlike a Rollout Plan's plan_end_date (an explicit IM commitment covering
# every day in between), we don't know the TL touched it on the days
# between execution_date and last_progress_date, only that they touched it
# on those two. So this attributes the record to both those days rather
# than fabricating a full range like _team_planning_rows does.
def _daily_execution_report_rows(fd, td, single_day, with_activity_status):
    from frappe.utils import getdate

    fd_d, td_d = getdate(fd), getdate(td)
    activity_sql = ""
    if with_activity_status:
        activity_sql = """,
            TRIM(BOTH ' | ' FROM CONCAT_WS(' | ',
                IF(IFNULL(de.qc_status,'')   != '', CONCAT('QC: ',   de.qc_status),   NULL),
                IF(IFNULL(de.ciag_status,'') != '', CONCAT('CIAG: ', de.ciag_status), NULL),
                IF(IFNULL(de.remarks,'')     != '', de.remarks,                        NULL)
            )) AS activity_status"""
    raw = frappe.db.sql(
        f"""
        SELECT
            de.execution_date, de.last_progress_date,
            it.name AS team_key, it.team_id, it.tl_id, it.team_skills, it.status AS team_active_status,
            e.employee_name AS tl_name,
            e.employee_number AS tl_iqama,
            e.cell_number AS tl_mobile,
            IFNULL(pd.site_code,'') AS site_code,
            IFNULL(imm.full_name,'') AS huawei_im,
            IFNULL(pd.project_code,'') AS project_code,
            IFNULL(pd.project_domain,'') AS project_domain
            {activity_sql}
        FROM `tabDaily Execution` de
        INNER JOIN `tabRollout Plan` rp ON rp.name = de.rollout_plan
        -- de.team, not rp.team: Daily Execution is multi-team aware (a plan
        -- split across teams gets one DE row per team, see
        -- _populate_execution_team_members), so rp.team (the plan's lead
        -- team only) attributed every execution to the wrong team whenever
        -- the actual executing team was a secondary split member.
        INNER JOIN `tabINET Team` it ON it.name = de.team AND it.team_category = 'Field Team'
        LEFT JOIN `tabEmployee` e ON e.user_id = it.field_user
        LEFT JOIN `tabPO Dispatch` pd ON pd.name = rp.po_dispatch
        LEFT JOIN `tabIM Master` imm ON imm.name = pd.im
        WHERE DATE(de.execution_date) BETWEEN %s AND %s
           OR DATE(de.last_progress_date) BETWEEN %s AND %s
        ORDER BY it.team_id, de.execution_date
        """,
        (fd, td, fd, td),
        as_dict=True,
    )

    buckets = {}
    order = []
    for r in raw:
        days = {getdate(r["execution_date"])}
        if r.get("last_progress_date"):
            days.add(getdate(r["last_progress_date"]))
        for d in days:
            if d < fd_d or d > td_d:
                continue
            key = (d, r["team_key"])
            b = buckets.get(key)
            if not b:
                b = {
                    "date": d,
                    "team_no": r["team_id"],
                    "tl_name": r["tl_name"],
                    "tl_id": r["tl_id"],
                    "tl_iqama": r["tl_iqama"],
                    "tl_mobile": r["tl_mobile"],
                    "team_skills": r["team_skills"],
                    "team_status": "On Vacation" if r["team_active_status"] == "Inactive" else "Available",
                    "site_duid": set(), "huawei_im": set(), "project_name": set(), "domain": set(),
                    "activity_status": [],
                }
                buckets[key] = b
                order.append(key)
            if r["site_code"]: b["site_duid"].add(r["site_code"])
            if r["huawei_im"]: b["huawei_im"].add(r["huawei_im"])
            if r["project_code"]: b["project_name"].add(r["project_code"])
            if r["project_domain"]: b["domain"].add(r["project_domain"])
            if with_activity_status and r.get("activity_status"):
                b["activity_status"].append(r["activity_status"])

    rows = []
    for key in order:
        b = buckets[key]
        row = {
            "supplier_name": _SUPPLIER_NAME,
            "date": b["date"],
            "team_no": b["team_no"],
            "tl_name": b["tl_name"],
            "tl_id": b["tl_id"],
            "tl_iqama": b["tl_iqama"],
            "tl_mobile": b["tl_mobile"],
            "team_skills": b["team_skills"],
            "team_status": b["team_status"],
            "site_duid": ", ".join(sorted(b["site_duid"])),
            "huawei_im": ", ".join(sorted(b["huawei_im"])),
            "project_name": ", ".join(sorted(b["project_name"])),
            "domain": ", ".join(sorted(b["domain"])),
        }
        if with_activity_status:
            row["activity_status"] = " | ".join(b["activity_status"])
        rows.append(row)

    if single_day:
        busy = {r["team_no"] for r in rows}
        rows = rows + _idle_rows(fd, _SUPPLIER_NAME, busy, extra_col="activity_status" if with_activity_status else None)
        rows.sort(key=lambda r: r["team_no"] or "")
    else:
        rows.sort(key=lambda r: (r["team_no"] or "", str(r["date"])))
    return rows


def _team_utilization_rows(fd, td, single_day):
    return _daily_execution_report_rows(fd, td, single_day, with_activity_status=False)


def _team_implementation_rows(fd, td, single_day):
    return _daily_execution_report_rows(fd, td, single_day, with_activity_status=True)
